INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#4','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C8',3,'mc','auto','팔을 펼 때 아래팔뼈는 어떻게 되나요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C8","difficulty":3,"kind":"mc","stem":"팔을 펼 때 아래팔뼈는 어떻게 되나요?","options":[{"t":"바깥쪽 근육이 줄어들면서 따라 내려간다","correct":true},{"t":"안쪽 근육이 줄어들면서 따라 올라간다","mis":"SC5-1-u4-X08"},{"t":"근육과 관계없이 스스로 내려간다","mis":"SC5-1-u4-X03"},{"t":"스스로 길게 늘어난다","mis":"SC5-1-u4-X03"}],"explanation":["팔을 펴 봐요.","아래팔뼈가 내려가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#5','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C7',3,'ox','auto','팔을 펼 때는 바깥쪽 근육이 아래팔뼈를 밀어내요.',ARRAY['SC5-1-u4-X07']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C7","difficulty":3,"kind":"ox","stem":"팔을 펼 때는 바깥쪽 근육이 아래팔뼈를 밀어내요.","answer":"X","reason_options":[{"t":"근육은 밀지 못하고 바깥쪽 근육이 줄어들며 아래팔뼈가 따라 내려가기 때문에","correct":true},{"t":"근육은 늘어날 때 뼈를 밀어내기 때문에","mis":"SC5-1-u4-X07"}],"mis":"SC5-1-u4-X07","explanation":["근육이 하는 일을 떠올려요.","줄어들거나 늘어나요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#6','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C6',3,'mc','auto','갈비뼈가 가슴을 둘러싸고 있어서 보호하는 기관으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X05','SC5-1-u4-X06']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C6","difficulty":3,"kind":"mc","stem":"갈비뼈가 가슴을 둘러싸고 있어서 보호하는 기관으로 알맞은 것은 어느 것인가요?","options":[{"t":"심장과 폐","correct":true},{"t":"뇌","mis":"SC5-1-u4-X05"},{"t":"아래팔뼈","mis":"SC5-1-u4-X05"},{"t":"갈비뼈는 아무것도 보호하지 않는다","mis":"SC5-1-u4-X06"}],"explanation":["가슴 안에 무엇이 있나요?","두근두근, 숨을 쉬어요.","심장과 폐예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#7','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C4',3,'mc','auto','기관끼리 묶은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X04']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C4","difficulty":3,"kind":"mc","stem":"기관끼리 묶은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"심장, 폐, 뇌","correct":true},{"t":"똑딱단추, 뼈 도안","mis":"SC5-1-u4-X04"},{"t":"옷, 신발","mis":"SC5-1-u4-X04"},{"t":"손잡이, 근육 도안","mis":"SC5-1-u4-X04"}],"explanation":["몸속에서 일을 하는 부분이에요.","도안이나 물건은 아니에요.","심장, 폐, 뇌예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#8','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C8',4,'mc','auto','컵을 입 쪽으로 가져오려고 팔을 구부릴 때 일어나는 일을 차례대로 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03','SC5-1-u4-X07']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C8","difficulty":4,"kind":"mc","stem":"컵을 입 쪽으로 가져오려고 팔을 구부릴 때 일어나는 일을 차례대로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"안쪽 근육이 줄어든다 → 아래팔뼈가 따라 올라간다 → 팔이 구부러진다","correct":true},{"t":"바깥쪽 근육이 줄어든다 → 아래팔뼈가 따라 올라간다 → 팔이 구부러진다","mis":"SC5-1-u4-X08"},{"t":"아래팔뼈가 스스로 올라간다 → 근육이 따라 줄어든다 → 팔이 구부러진다","mis":"SC5-1-u4-X03"},{"t":"안쪽 근육이 아래팔뼈를 민다 → 아래팔뼈가 올라간다 → 팔이 구부러진다","mis":"SC5-1-u4-X07"}],"explanation":["근육이 먼저 움직여요.","안쪽이 줄어들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#9','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C8',4,'error','auto','뼈와 근육 모형을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X07']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C8","difficulty":4,"kind":"error","stem":"뼈와 근육 모형을 관찰하고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「손잡이를 잡아당기면 바깥쪽 근육 도안이 줄어들어.」","correct":true,"mis_target":"SC5-1-u4-X08"},{"t":"서진 — 「손잡이를 밀면 아래팔뼈 도안이 내려가.」","mis":"SC5-1-u4-X08"},{"t":"은우 — 「근육 도안이 줄어들거나 늘어나며 아래팔뼈 도안이 움직여.」","mis":"SC5-1-u4-X07"}],"explanation":["잡아당길 때를 떠올려요.","안쪽이 줄어들었어요.","하람이 잘못 말했어요."],"asset":{"type":"passage","lines":["손잡이를 잡아당길 때 — 안쪽 근육 도안이 줄어들고 바깥쪽 근육 도안이 늘어났다.","손잡이를 잡아당길 때 — 아래팔뼈 도안이 따라 올라갔다.","손잡이를 밀 때 — ( ? )"],"title":"우리 모둠 뼈와 근육 모형 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L02_challenge#10','sci',5,1,'u4','L02','g5_1_sci_u4_L02_challenge','lesson_challenge','SC5-1-u4-C7',4,'essay','teacher','팔을 구부릴 때와 펼 때 근육과 아래팔뼈가 어떻게 되는지 쓰고, 「근육이 뼈를 밀어서 팔을 편다」는 친구의 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C7","difficulty":4,"kind":"essay","stem":"팔을 구부릴 때와 펼 때 근육과 아래팔뼈가 어떻게 되는지 쓰고, 「근육이 뼈를 밀어서 팔을 편다」는 친구의 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: 팔을 구부릴 때에는 안쪽 근육이 줄어들고 바깥쪽 근육이 늘어나면서 아래팔뼈가 따라 올라간다. 팔을 펼 때에는 바깥쪽 근육이 줄어들고 안쪽 근육이 늘어나면서 아래팔뼈가 따라 내려간다. 근육은 뼈를 밀어내지 않는다. 팔을 펴는 일도 바깥쪽 근육이 줄어들면서 하는 것이다.","scoring_points":["구부릴 때 안쪽 근육이 줄어든다고 썼는가","펼 때 바깥쪽 근육이 줄어든다고 썼는가","근육은 밀지 않고 줄어들며 움직인다고 바로잡았는가"]},"explanation":["구부릴 때부터 써요.","펼 때는 반대예요.","친구에게 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#1','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C10',1,'blank','auto','「음식물 속의 영양소를 흡수할 수 있도록 음식물을 잘게 쪼개는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X09']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C10","difficulty":1,"kind":"blank","stem":"「음식물 속의 영양소를 흡수할 수 있도록 음식물을 잘게 쪼개는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"소화","correct":true},{"t":"흡수","mis":"SC5-1-u4-X09"},{"t":"배출","mis":"SC5-1-u4-X09"},{"t":"골격","mis":"SC5-1-u4-X09"}],"explanation":["잘게 쪼개는 과정이에요.","두 글자예요.","소화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#2','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C12',1,'mc','auto','입에서 삼킨 음식물이 위로 이동하는 통로는 어느 것인가요?',ARRAY['SC5-1-u4-X12']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C12","difficulty":1,"kind":"mc","stem":"입에서 삼킨 음식물이 위로 이동하는 통로는 어느 것인가요?","options":[{"t":"식도","correct":true},{"t":"큰창자","mis":"SC5-1-u4-X12"},{"t":"작은창자","mis":"SC5-1-u4-X12"},{"t":"항문","mis":"SC5-1-u4-X12"}],"explanation":["입과 위 사이예요.","통로예요.","식도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#3','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C13',1,'ox','auto','간, 쓸개, 이자도 소화기관이에요.',ARRAY['SC5-1-u4-X13']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C13","difficulty":1,"kind":"ox","stem":"간, 쓸개, 이자도 소화기관이에요.","answer":"O","reason_options":[{"t":"음식물이 지나가지는 않지만 소화를 도와주기 때문에","correct":true},{"t":"음식물이 간, 쓸개, 이자를 차례로 지나가기 때문에","mis":"SC5-1-u4-X13"}],"mis":"SC5-1-u4-X13","explanation":["소화를 돕는 기관이에요.","지나가지는 않아요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#4','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C11',1,'sa','auto','「음식물 찌꺼기는 □□을 통해 몸 밖으로 배출됩니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u4-C11","difficulty":1,"kind":"sa","stem":"「음식물 찌꺼기는 □□을 통해 몸 밖으로 배출됩니다.」 □□에 알맞은 말을 쓰세요.","answer":["항문"],"explanation":["소화 경로의 끝이에요.","두 글자예요.","항문이에요."],"mis":"SC5-1-u4-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#5','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C12',2,'match','auto','소화기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"match","stem":"소화기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"입","r":"이로 잘게 부수고 침과 섞어 물러지게 한다"},{"l":"식도","r":"음식물이 위로 이동하는 통로이다"},{"l":"작은창자","r":"영양소와 대부분의 수분을 흡수한다"},{"l":"큰창자","r":"음식물 찌꺼기에서 수분을 흡수한다"}],"mis":"SC5-1-u4-X12","explanation":["하나씩 떠올려요.","부수고, 지나고, 흡수해요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#6','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C11',2,'mc','auto','음식물이 지나가는 소화기관의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X10']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C11","difficulty":2,"kind":"mc","stem":"음식물이 지나가는 소화기관의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"입 → 식도 → 위 → 작은창자 → 큰창자","correct":true},{"t":"입 → 위 → 식도 → 작은창자 → 큰창자","mis":"SC5-1-u4-X10"},{"t":"입 → 식도 → 위 → 큰창자 → 작은창자","mis":"SC5-1-u4-X10"},{"t":"입 → 식도 → 작은창자 → 위 → 큰창자","mis":"SC5-1-u4-X10"}],"explanation":["입에서 출발해요.","위 다음은 작은창자예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#7','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C12',2,'mc','auto','영양소와 대부분의 수분을 흡수하는 소화기관은 어느 것인가요?',ARRAY['SC5-1-u4-X11','SC5-1-u4-X12']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"mc","stem":"영양소와 대부분의 수분을 흡수하는 소화기관은 어느 것인가요?","options":[{"t":"작은창자","correct":true},{"t":"위","mis":"SC5-1-u4-X11"},{"t":"식도","mis":"SC5-1-u4-X12"},{"t":"입","mis":"SC5-1-u4-X12"}],"explanation":["흡수는 위에서 끝나지 않아요.","더 잘게 쪼개고 흡수해요.","작은창자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#8','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C10',2,'error','auto','소화에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X09']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C10","difficulty":2,"kind":"error","stem":"소화에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「음식물은 소화기관을 지나면서 점점 커져.」","correct":true,"mis_target":"SC5-1-u4-X09"},{"t":"주원 — 「음식물은 소화기관을 지나면서 잘게 쪼개져.」","mis":"SC5-1-u4-X09"},{"t":"가온 — 「우리는 음식물에서 몸에 필요한 영양소를 얻어.」","mis":"SC5-1-u4-X09"}],"explanation":["소화의 뜻을 떠올려요.","잘게 쪼개요.","민서가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#9','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C14',2,'mc','auto','음식물을 꼭꼭 씹어 먹어야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X15','SC5-1-u4-X11']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C14","difficulty":2,"kind":"mc","stem":"음식물을 꼭꼭 씹어 먹어야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 잘게 쪼개지고 물러져야 소화가 잘되기 때문에","correct":true},{"t":"음식물을 더 빨리 먹을 수 있기 때문에","mis":"SC5-1-u4-X15"},{"t":"음식물이 커야 영양소가 많아지기 때문에","mis":"SC5-1-u4-X15"},{"t":"씹으면 영양소가 입에서 모두 없어지기 때문에","mis":"SC5-1-u4-X11"}],"explanation":["입이 하는 일을 떠올려요.","잘게 부수고 물러지게 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_basic#10','sci',5,1,'u4','L03','g5_1_sci_u4_L03_basic','lesson_basic','SC5-1-u4-C13',3,'mc','auto','음식물이 지나가지는 않지만 소화를 돕는 기관끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X13']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C13","difficulty":3,"kind":"mc","stem":"음식물이 지나가지는 않지만 소화를 돕는 기관끼리 묶은 것은 어느 것인가요?","options":[{"t":"간, 쓸개, 이자","correct":true},{"t":"위, 작은창자","mis":"SC5-1-u4-X13"},{"t":"식도, 큰창자","mis":"SC5-1-u4-X13"},{"t":"입, 항문","mis":"SC5-1-u4-X13"}],"explanation":["음식물이 지나가는 곳은 빼요.","세 기관이에요.","간, 쓸개, 이자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#1','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C14',2,'mc','auto','소화 과정 모형을 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X16']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C14","difficulty":2,"kind":"mc","stem":"소화 과정 모형을 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉢ → ㉠","mis":"SC5-1-u4-X16"},{"t":"㉡ → ㉠ → ㉣ → ㉢","mis":"SC5-1-u4-X16"},{"t":"㉠ → ㉣ → ㉡ → ㉢","mis":"SC5-1-u4-X16"}],"explanation":["도안부터 살펴요.","구멍을 내고 막대를 넣어요.","관찰은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 소화 과정 막대를 도안 안에 넣고 위아래로 움직이게 붙인다.","㉡ 도안의 그림과 이름을 색연필로 연결하고 기능을 조사한다.","㉢ 막대를 천천히 내리며 음식물의 모습을 관찰한다.","㉣ 음식물이 지나가는 자리에 구멍을 내고 도안을 반으로 접는다."],"title":"소화 과정 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#2','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C12',2,'sa','auto','「음식물 찌꺼기에서 수분을 흡수하는 기관은 □□□□입니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"sa","stem":"「음식물 찌꺼기에서 수분을 흡수하는 기관은 □□□□입니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["큰창자"],"explanation":["작은창자 다음이에요.","네 글자예요.","큰창자예요."],"mis":"SC5-1-u4-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#3','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C14',3,'mc','auto','소화기관 도안에 구멍을 내는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X13','SC5-1-u4-X16']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C14","difficulty":3,"kind":"mc","stem":"소화기관 도안에 구멍을 내는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 지나가는 자리","correct":true},{"t":"간, 쓸개, 이자가 있는 자리","mis":"SC5-1-u4-X13"},{"t":"아무 데나 마음에 드는 자리","mis":"SC5-1-u4-X16"},{"t":"구멍을 내지 않고 도안을 그대로 둔다","mis":"SC5-1-u4-X16"}],"explanation":["구멍으로 무엇을 보나요?","음식물의 모습이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#4','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C12',3,'mc','auto','막대를 내리며 본 것의 ㉰는 어느 소화기관에서 일어난 일인가요?',ARRAY['SC5-1-u4-X10','SC5-1-u4-X11']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C12","difficulty":3,"kind":"mc","stem":"막대를 내리며 본 것의 ㉰는 어느 소화기관에서 일어난 일인가요?","options":[{"t":"위","correct":true},{"t":"식도","mis":"SC5-1-u4-X10"},{"t":"작은창자","mis":"SC5-1-u4-X11"},{"t":"큰창자","mis":"SC5-1-u4-X10"}],"explanation":["식도 다음이에요.","소화를 돕는 액체를 분비해요.","위예요."],"asset":{"type":"passage","lines":["㉮ 큰 덩어리가 이로 부서지고 침과 섞여 물러졌다.","㉯ 물러진 덩어리가 아래로 내려가는 통로를 지났다.","㉰ 소화를 돕는 액체와 섞여 잘게 쪼개졌다.","㉱ 더 잘게 쪼개지고 영양소와 대부분의 수분이 흡수되었다.","㉲ 남은 찌꺼기에서 수분이 흡수되었다."],"title":"소화 과정 막대를 내리며 본 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#5','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C12',3,'ox','auto','음식물의 영양소와 수분은 위에서 모두 흡수돼요.',ARRAY['SC5-1-u4-X11']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C12","difficulty":3,"kind":"ox","stem":"음식물의 영양소와 수분은 위에서 모두 흡수돼요.","answer":"X","reason_options":[{"t":"영양소와 대부분의 수분은 작은창자에서, 찌꺼기의 수분은 큰창자에서 흡수되기 때문에","correct":true},{"t":"위가 모든 영양소와 수분을 흡수하기 때문에","mis":"SC5-1-u4-X11"}],"mis":"SC5-1-u4-X11","explanation":["흡수하는 곳을 떠올려요.","창자에서 흡수해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#6','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C11',3,'mc','auto','음식물 찌꺼기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X14','SC5-1-u4-X10']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C11","difficulty":3,"kind":"mc","stem":"음식물 찌꺼기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"큰창자를 지나 항문을 통해 몸 밖으로 배출된다","correct":true},{"t":"몸 밖으로 나가지 못하고 몸속에 그대로 쌓인다","mis":"SC5-1-u4-X14"},{"t":"모두 흡수되어 남는 것이 하나도 없다","mis":"SC5-1-u4-X14"},{"t":"식도를 거쳐 입으로 다시 나온다","mis":"SC5-1-u4-X10"}],"explanation":["소화 경로의 끝이에요.","항문으로 나가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#7','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C14',3,'mc','auto','소화 과정 모형을 관찰하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X16']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C14","difficulty":3,"kind":"mc","stem":"소화 과정 모형을 관찰하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"막대를 천천히 내리며 구멍으로 보이는 음식물의 모습을 관찰한다","correct":true},{"t":"막대를 풀로 붙여 움직이지 않게 한다","mis":"SC5-1-u4-X16"},{"t":"막대를 한 번에 빠르게 끝까지 내린다","mis":"SC5-1-u4-X16"},{"t":"도안을 펴서 막대 없이 그림만 본다","mis":"SC5-1-u4-X16"}],"explanation":["막대가 움직여야 해요.","천천히 내려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#8','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C10',4,'mc','auto','점심에 먹은 밥이 큰창자에 이르렀을 때의 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X09','SC5-1-u4-X11','SC5-1-u4-X14']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C10","difficulty":4,"kind":"mc","stem":"점심에 먹은 밥이 큰창자에 이르렀을 때의 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잘게 쪼개져 영양소와 대부분의 수분이 흡수되고 남은 찌꺼기","correct":true},{"t":"입에 넣었을 때와 같은 큰 덩어리","mis":"SC5-1-u4-X09"},{"t":"아직 영양소가 하나도 흡수되지 않은 상태","mis":"SC5-1-u4-X11"},{"t":"모두 흡수되어 아무것도 남지 않은 상태","mis":"SC5-1-u4-X14"}],"explanation":["작은창자를 지나왔어요.","흡수하고 남은 것이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#9','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C13',4,'error','auto','소화 과정 모형을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X13','SC5-1-u4-X12','SC5-1-u4-X11']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C13","difficulty":4,"kind":"error","stem":"소화 과정 모형을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「간 자리에도 구멍을 내자. 음식물이 간을 지나가니까.」","correct":true,"mis_target":"SC5-1-u4-X13"},{"t":"나래 — 「식도는 음식물이 위로 가는 통로야.」","mis":"SC5-1-u4-X12"},{"t":"지후 — 「작은창자에서 영양소를 흡수해.」","mis":"SC5-1-u4-X11"}],"explanation":["간은 무슨 일을 하나요?","지나가지 않고 도와요.","태오가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L03_challenge#10','sci',5,1,'u4','L03','g5_1_sci_u4_L03_challenge','lesson_challenge','SC5-1-u4-C11',4,'essay','teacher','음식물이 지나가는 소화기관을 차례대로 쓰고, 영양소와 수분이 흡수되는 곳과 음식물 찌꺼기가 나가는 곳을 쓰세요. 그리고 꼭꼭 씹어 먹어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C11","difficulty":4,"kind":"essay","stem":"음식물이 지나가는 소화기관을 차례대로 쓰고, 영양소와 수분이 흡수되는 곳과 음식물 찌꺼기가 나가는 곳을 쓰세요. 그리고 꼭꼭 씹어 먹어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 음식물은 입 → 식도 → 위 → 작은창자 → 큰창자를 거치며 소화된다. 영양소와 대부분의 수분은 작은창자에서, 찌꺼기에 남은 수분은 큰창자에서 흡수되고, 나머지 찌꺼기는 항문을 통해 몸 밖으로 배출된다. 음식물을 꼭꼭 씹으면 잘게 쪼개지고 물러져 소화가 잘된다.","scoring_points":["소화기관의 차례를 바르게 썼는가","흡수하는 곳과 배출되는 곳을 썼는가","꼭꼭 씹는 까닭을 썼는가"]},"explanation":["입에서 출발해요.","흡수하는 곳을 나눠요.","씹는 까닭도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#1','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C15',1,'blank','auto','「혈액이 끊임없이 온몸을 이동하는 것을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C15","difficulty":1,"kind":"blank","stem":"「혈액이 끊임없이 온몸을 이동하는 것을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"혈액 순환","correct":true},{"t":"소화","mis":"SC5-1-u4-X22"},{"t":"흡수","mis":"SC5-1-u4-X22"},{"t":"골격","mis":"SC5-1-u4-X22"}],"explanation":["혈액이 온몸을 돌아요.","돌고 도는 것이에요.","혈액 순환이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#2','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C16',1,'mc','auto','심장은 우리 몸의 어디에 있나요?',ARRAY['SC5-1-u4-X20']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C16","difficulty":1,"kind":"mc","stem":"심장은 우리 몸의 어디에 있나요?","options":[{"t":"가슴 중앙에서 왼쪽으로 약간 치우친 곳","correct":true},{"t":"배 아래쪽 한가운데","mis":"SC5-1-u4-X20"},{"t":"머리 안쪽","mis":"SC5-1-u4-X20"},{"t":"양쪽 손목 안","mis":"SC5-1-u4-X20"}],"explanation":["가슴에 손을 대 봐요.","두근두근 뛰어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#3','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C17',1,'ox','auto','혈관은 온몸에 퍼져 있어요.',ARRAY['SC5-1-u4-X18']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C17","difficulty":1,"kind":"ox","stem":"혈관은 온몸에 퍼져 있어요.","answer":"O","reason_options":[{"t":"혈액이 머리끝부터 발끝까지 이동하는 통로이기 때문에","correct":true},{"t":"혈관은 심장 가까이에만 있기 때문에","mis":"SC5-1-u4-X18"}],"mis":"SC5-1-u4-X18","explanation":["혈액이 어디까지 가나요?","온몸이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#4','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C16',1,'sa','auto','「심장은 끊임없이 □□ 작용을 하여 혈액을 온몸으로 보냅니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-1-u4-C16","difficulty":1,"kind":"sa","stem":"「심장은 끊임없이 □□ 작용을 하여 혈액을 온몸으로 보냅니다.」 □□에 알맞은 말을 쓰세요.","answer":["펌프"],"explanation":["모형실험 도구를 떠올려요.","쥐었다 폈다 해요.","펌프예요."],"mis":"SC5-1-u4-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#5','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C19',2,'match','auto','순환기관 모형의 재료와 같은 역할을 하는 우리 몸의 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C19","difficulty":2,"kind":"match","stem":"순환기관 모형의 재료와 같은 역할을 하는 우리 몸의 부분을 알맞게 이으세요.","pairs":[{"l":"펌프","r":"심장"},{"l":"호스","r":"혈관"},{"l":"붉은 색소 물","r":"혈액"}],"mis":"SC5-1-u4-X21","explanation":["하는 일을 견줘요.","보내고, 지나가고, 이동해요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#6','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C18',2,'mc','auto','혈액이 온몸에 운반하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C18","difficulty":2,"kind":"mc","stem":"혈액이 온몸에 운반하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"영양소와 산소","correct":true},{"t":"씹지 않은 음식물 덩어리","mis":"SC5-1-u4-X22"},{"t":"뼈와 근육","mis":"SC5-1-u4-X22"},{"t":"아무것도 나르지 않는다","mis":"SC5-1-u4-X22"}],"explanation":["혈액이 하는 일이에요.","두 가지를 날라요.","영양소와 산소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#7','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C15',2,'mc','auto','순환기관끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C15","difficulty":2,"kind":"mc","stem":"순환기관끼리 묶은 것은 어느 것인가요?","options":[{"t":"심장과 혈관","correct":true},{"t":"위와 작은창자","mis":"SC5-1-u4-X22"},{"t":"머리뼈와 갈비뼈","mis":"SC5-1-u4-X22"},{"t":"식도와 큰창자","mis":"SC5-1-u4-X22"}],"explanation":["혈액을 돌게 하는 기관이에요.","보내는 곳과 통로예요.","심장과 혈관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#8','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C16',2,'error','auto','순환기관에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X18']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C16","difficulty":2,"kind":"error","stem":"순환기관에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「심장은 혈액을 새로 만들어 내는 곳이야.」","correct":true,"mis_target":"SC5-1-u4-X17"},{"t":"보람 — 「심장은 펌프 작용을 해.」","mis":"SC5-1-u4-X17"},{"t":"다은 — 「혈관은 혈액이 이동하는 통로야.」","mis":"SC5-1-u4-X18"}],"explanation":["심장이 하는 일을 떠올려요.","혈액을 보내요.","수호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#9','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C18',2,'mc','auto','심장에서 나간 혈액은 어떻게 되나요?',ARRAY['SC5-1-u4-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C18","difficulty":2,"kind":"mc","stem":"심장에서 나간 혈액은 어떻게 되나요?","options":[{"t":"온몸을 돌고 다시 심장으로 돌아온다","correct":true},{"t":"온몸을 한 번 돌고 멈춘다","mis":"SC5-1-u4-X19"},{"t":"나가기만 하고 돌아오지 않는다","mis":"SC5-1-u4-X19"},{"t":"혈관을 지나 몸 밖으로 나간다","mis":"SC5-1-u4-X19"}],"explanation":["순환의 뜻을 떠올려요.","돌아와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_basic#10','sci',5,1,'u4','L04','g5_1_sci_u4_L04_basic','lesson_basic','SC5-1-u4-C19',3,'mc','auto','심장박동이 멈추었을 때 빠른 시간 안에 심폐 소생술을 해야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X23']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"심장박동이 멈추었을 때 빠른 시간 안에 심폐 소생술을 해야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 순환하지 못해 영양소와 산소를 온몸에 운반할 수 없기 때문에","correct":true},{"t":"혈액이 몸 밖으로 모두 흘러나오기 때문에","mis":"SC5-1-u4-X23"},{"t":"혈관의 길이가 짧아지기 때문에","mis":"SC5-1-u4-X23"},{"t":"뼈가 곧바로 굳어 버리기 때문에","mis":"SC5-1-u4-X23"}],"explanation":["심장이 멈추면 혈액은요?","돌지 못해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#1','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',2,'mc','auto','순환기관 모형실험의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X21']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C19","difficulty":2,"kind":"mc","stem":"순환기관 모형실험의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉠ → ㉡ → ㉢","mis":"SC5-1-u4-X21"},{"t":"㉡ → ㉠ → ㉣ → ㉢","mis":"SC5-1-u4-X21"},{"t":"㉢ → ㉡ → ㉣ → ㉠","mis":"SC5-1-u4-X21"}],"explanation":["모형부터 살펴요.","호스를 넣고 펌프를 움직여요.","이야기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 펌프를 손으로 쥐었다 폈다 하며 붉은 색소 물의 이동을 관찰한다.","㉡ 순환기관 모형을 관찰해 그림과 이름을 연결하고 기능을 조사한다.","㉢ 모형의 세 가지가 우리 몸의 어떤 부분과 같은지 이야기한다.","㉣ 식용 색소를 녹인 물에 한쪽 호스를 넣고 펌프를 잡는다."],"title":"순환기관 모형실험(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#2','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C16',2,'sa','auto','「펌프 작용으로 혈액을 온몸으로 보내는 순환기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C16","difficulty":2,"kind":"sa","stem":"「펌프 작용으로 혈액을 온몸으로 보내는 순환기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["심장"],"explanation":["가슴에 있어요.","두근두근 뛰어요.","심장이에요."],"mis":"SC5-1-u4-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#3','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',3,'mc','auto','모형실험에서 펌프를 쥐었다 폈다 하다가 멈추면 붉은 색소 물은 어떻게 될까요?',ARRAY['SC5-1-u4-X21','SC5-1-u4-X17']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"모형실험에서 펌프를 쥐었다 폈다 하다가 멈추면 붉은 색소 물은 어떻게 될까요?","options":[{"t":"이동을 멈춘다","correct":true},{"t":"전보다 더 빠르게 이동한다","mis":"SC5-1-u4-X21"},{"t":"펌프와 관계없이 계속 이동한다","mis":"SC5-1-u4-X21"},{"t":"호스 안에서 새로 만들어진다","mis":"SC5-1-u4-X17"}],"explanation":["펌프가 보내 주어요.","멈추면 보내지 못해요.","이동을 멈춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#4','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C18',3,'ox','auto','혈액은 온몸을 한 번 돌고 나면 멈춰요.',ARRAY['SC5-1-u4-X19']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C18","difficulty":3,"kind":"ox","stem":"혈액은 온몸을 한 번 돌고 나면 멈춰요.","answer":"X","reason_options":[{"t":"다시 심장으로 돌아와 순환 과정을 끊임없이 반복하기 때문에","correct":true},{"t":"한 번 운반하고 나면 할 일이 끝나기 때문에","mis":"SC5-1-u4-X19"}],"mis":"SC5-1-u4-X19","explanation":["순환은 끝이 있나요?","반복해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#5','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C18',3,'mc','auto','작은창자에서 흡수한 영양소가 발끝까지 가는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X17']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C18","difficulty":3,"kind":"mc","stem":"작은창자에서 흡수한 영양소가 발끝까지 가는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 혈관을 따라 발끝까지 운반한다","correct":true},{"t":"음식물이 발끝까지 내려간다","mis":"SC5-1-u4-X22"},{"t":"영양소가 다리뼈를 타고 이동한다","mis":"SC5-1-u4-X22"},{"t":"심장이 발끝에서 영양소를 새로 만든다","mis":"SC5-1-u4-X17"}],"explanation":["운반하는 것을 떠올려요.","혈액이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#6','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',3,'error','auto','모형실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X21']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"error","stem":"모형실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「호스는 우리 몸의 심장과 같은 역할을 해.」","correct":true,"mis_target":"SC5-1-u4-X21"},{"t":"정민 — 「붉은 색소 물은 우리 몸의 혈액과 같아.」","mis":"SC5-1-u4-X21"},{"t":"로운 — 「펌프를 쥐었다 펴면 붉은 색소 물이 이동해.」","mis":"SC5-1-u4-X21"}],"explanation":["호스는 무엇이 지나가나요?","통로예요.","하은이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#7','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C19',3,'mc','auto','순환기관 모형실험에서 지켜야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X21']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"순환기관 모형실험에서 지켜야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"붉은 색소 물이 눈에 튀지 않게 조심하고 맛보지 않는다","correct":true},{"t":"붉은 색소 물을 맛보아 무엇인지 확인한다","mis":"SC5-1-u4-X21"},{"t":"펌프를 친구 얼굴 쪽으로 향해 누른다","mis":"SC5-1-u4-X21"},{"t":"남은 물을 아무 데나 쏟아 버린다","mis":"SC5-1-u4-X21"}],"explanation":["실험 약속이에요.","눈과 입을 조심해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#8','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C17',4,'mc','auto','손끝을 살짝 다쳤더니 피가 났어요. 이것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X18','SC5-1-u4-X17','SC5-1-u4-X19']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C17","difficulty":4,"kind":"mc","stem":"손끝을 살짝 다쳤더니 피가 났어요. 이것으로 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손끝에도 혈관이 퍼져 있어 혈액이 이동한다","correct":true},{"t":"혈관은 심장 가까이에만 있다","mis":"SC5-1-u4-X18"},{"t":"손끝에서 혈액이 새로 만들어진다","mis":"SC5-1-u4-X17"},{"t":"손끝의 혈액은 심장으로 돌아가지 않는다","mis":"SC5-1-u4-X19"}],"explanation":["피는 혈액이에요.","손끝까지 왔어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#9','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C16',4,'mc','auto','심장이 쉬지 않고 펌프 작용을 해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X18','SC5-1-u4-X19']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C16","difficulty":4,"kind":"mc","stem":"심장이 쉬지 않고 펌프 작용을 해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 계속 온몸을 돌며 영양소와 산소를 운반해야 하기 때문에","correct":true},{"t":"혈액을 계속 새로 만들어야 하기 때문에","mis":"SC5-1-u4-X17"},{"t":"혈관을 심장 가까이로 모아야 하기 때문에","mis":"SC5-1-u4-X18"},{"t":"혈액을 몸 밖으로 내보내야 하기 때문에","mis":"SC5-1-u4-X19"}],"explanation":["혈액이 하는 일을 떠올려요.","계속 운반해야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L04_challenge#10','sci',5,1,'u4','L04','g5_1_sci_u4_L04_challenge','lesson_challenge','SC5-1-u4-C18',4,'essay','teacher','순환기관 모형의 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 혈액이 온몸을 돌며 하는 일을 쓰세요. 그리고 「심장이 혈액을 만든다」는 친구의 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C18","difficulty":4,"kind":"essay","stem":"순환기관 모형의 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 혈액이 온몸을 돌며 하는 일을 쓰세요. 그리고 「심장이 혈액을 만든다」는 친구의 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: 펌프는 심장, 호스는 혈관, 붉은 색소 물은 혈액과 같은 역할을 한다. 심장에서 나온 혈액은 혈관을 따라 이동하며 영양소와 산소를 온몸에 운반하고 다시 심장으로 돌아오는 순환을 반복한다. 심장은 혈액을 만드는 곳이 아니라 펌프 작용으로 혈액을 온몸으로 보내는 곳이다.","scoring_points":["세 가지를 몸의 부분과 바르게 짝지었는가","영양소와 산소를 운반하고 돌아온다고 썼는가","심장은 펌프 작용을 한다고 바로잡았는가"]},"explanation":["모형부터 짝지어요.","혈액이 하는 일을 써요.","친구에게 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#1','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',1,'mc','auto','숨을 들이마시고 내쉬는 활동을 무엇이라고 하나요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X22']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"mc","stem":"숨을 들이마시고 내쉬는 활동을 무엇이라고 하나요?","options":[{"t":"호흡","correct":true},{"t":"소화","mis":"SC5-1-u4-X24"},{"t":"순환","mis":"SC5-1-u4-X22"},{"t":"흡수","mis":"SC5-1-u4-X24"}],"explanation":["숨을 쉬는 일이에요.","두 글자예요.","호흡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#2','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C21',1,'sa','auto','「숨을 들이마시면 폐는 우리 몸에 필요한 □□를 받아들입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C21","difficulty":1,"kind":"sa","stem":"「숨을 들이마시면 폐는 우리 몸에 필요한 □□를 받아들입니다.」 □□에 알맞은 말을 쓰세요.","answer":["산소"],"explanation":["혈액이 나르는 것 가운데 하나예요.","두 글자예요.","산소예요."],"mis":"SC5-1-u4-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#3','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',1,'ox','auto','숨관가지는 숨관과 폐를 연결해요.',ARRAY['SC5-1-u4-X24']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"ox","stem":"숨관가지는 숨관과 폐를 연결해요.","answer":"O","reason_options":[{"t":"공기가 숨관에서 폐로 이동하는 통로이기 때문에","correct":true},{"t":"숨관가지는 공기가 처음 드나드는 곳이기 때문에","mis":"SC5-1-u4-X24"}],"mis":"SC5-1-u4-X24","explanation":["이름을 살펴봐요.","숨관에서 갈라진 가지예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#4','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',1,'blank','auto','「(    )은/는 공기가 드나드는 곳입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X26']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"blank","stem":"「(    )은/는 공기가 드나드는 곳입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"코","correct":true},{"t":"폐","mis":"SC5-1-u4-X24"},{"t":"식도","mis":"SC5-1-u4-X26"},{"t":"심장","mis":"SC5-1-u4-X24"}],"explanation":["얼굴에 있어요.","공기가 들어가고 나와요.","코예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#5','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C20',2,'match','auto','호흡기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C20","difficulty":2,"kind":"match","stem":"호흡기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"코","r":"공기가 드나드는 곳이다"},{"l":"숨관","r":"공기가 이동하는 통로이다"},{"l":"숨관가지","r":"숨관과 폐를 연결하는 통로이다"},{"l":"폐","r":"산소를 받아들이고 이산화 탄소를 내보낸다"}],"mis":"SC5-1-u4-X24","explanation":["공기의 길을 따라가요.","드나들고, 지나고, 받아들여요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#6','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C21',2,'mc','auto','숨을 들이마실 때 공기가 이동하는 길로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X25','SC5-1-u4-X26']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C21","difficulty":2,"kind":"mc","stem":"숨을 들이마실 때 공기가 이동하는 길로 알맞은 것은 어느 것인가요?","options":[{"t":"코 → 숨관 → 숨관가지 → 폐","correct":true},{"t":"코 → 숨관가지 → 숨관 → 폐","mis":"SC5-1-u4-X24"},{"t":"폐 → 숨관가지 → 숨관 → 코","mis":"SC5-1-u4-X25"},{"t":"코 → 식도 → 위","mis":"SC5-1-u4-X26"}],"explanation":["코에서 출발해요.","숨관이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#7','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C22',2,'mc','auto','숨을 내쉴 때 몸 밖으로 나가는 공기로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X28','SC5-1-u4-X27']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C22","difficulty":2,"kind":"mc","stem":"숨을 내쉴 때 몸 밖으로 나가는 공기로 알맞은 것은 어느 것인가요?","options":[{"t":"이산화 탄소를 포함한 공기","correct":true},{"t":"산소만 들어 있는 공기","mis":"SC5-1-u4-X28"},{"t":"이산화 탄소가 하나도 없는 공기","mis":"SC5-1-u4-X28"},{"t":"영양소가 가득한 공기","mis":"SC5-1-u4-X27"}],"explanation":["몸속에서 생긴 것이에요.","내보내는 기체예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#8','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C26',2,'error','auto','공기와 음식물이 가는 길에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X26']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"error","stem":"공기와 음식물이 가는 길에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세아 — 「먹은 음식물도 숨관을 지나 폐로 들어가.」","correct":true,"mis_target":"SC5-1-u4-X26"},{"t":"준혁 — 「들이마신 공기는 숨관을 지나 폐로 가.」","mis":"SC5-1-u4-X26"},{"t":"채원 — 「삼킨 음식물은 식도를 지나 위로 가.」","mis":"SC5-1-u4-X26"}],"explanation":["공기의 길과 음식물의 길이에요.","서로 달라요.","세아가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#9','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C23',2,'mc','auto','호흡기관 모형을 만들 때 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C23","difficulty":2,"kind":"mc","stem":"호흡기관 모형을 만들 때 알맞은 것은 어느 것인가요?","options":[{"t":"주름 빨대와 종이봉투 사이를 셀로판테이프로 잘 막는다","correct":true},{"t":"종이봉투가 크게 부풀도록 숨이 찰 때까지 분다","mis":"SC5-1-u4-X29"},{"t":"어지러워도 끝까지 공기를 불어 넣는다","mis":"SC5-1-u4-X29"},{"t":"공기가 새도 그대로 실험한다","mis":"SC5-1-u4-X29"}],"explanation":["공기가 새면 어떨까요?","잘 막아야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_basic#10','sci',5,1,'u4','L05','g5_1_sci_u4_L05_basic','lesson_basic','SC5-1-u4-C21',3,'mc','auto','수영할 때 얼굴을 물 위로 내미는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X27']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"mc","stem":"수영할 때 얼굴을 물 위로 내미는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"코로 공기를 들이마셔 폐가 산소를 받아들여야 하기 때문에","correct":true},{"t":"물속을 더 잘 보기 위해서","mis":"SC5-1-u4-X27"},{"t":"물에서 더 빨리 나아가기 위해서","mis":"SC5-1-u4-X27"},{"t":"몸이 차가워지지 않게 하기 위해서","mis":"SC5-1-u4-X27"}],"explanation":["물속에서는 숨을 못 쉬어요.","공기가 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#1','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C23',2,'mc','auto','호흡기관 모형 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C23","difficulty":2,"kind":"mc","stem":"호흡기관 모형 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉢ → ㉠","mis":"SC5-1-u4-X29"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SC5-1-u4-X29"},{"t":"㉢ → ㉣ → ㉠ → ㉡","mis":"SC5-1-u4-X29"}],"explanation":["내 몸부터 느껴요.","감고, 붙이고, 불어요.","관찰은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 호흡기관 붙임딱지를 각 기관의 위치에 맞게 붙인다.","㉡ 가슴에 양손을 얹고 천천히 호흡하며 몸의 변화를 느낀다.","㉢ 모형에 공기를 불어 넣으며 변화를 관찰한다.","㉣ 주름 빨대와 종이봉투를 셀로판테이프로 공기가 새지 않게 감는다."],"title":"호흡기관 모형 만들기(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#2','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',2,'sa','auto','「숨을 내쉬면 공기가 폐 → 숨관가지 → □□ → 코를 거쳐 몸 밖으로 나갑니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C22","difficulty":2,"kind":"sa","stem":"「숨을 내쉬면 공기가 폐 → 숨관가지 → □□ → 코를 거쳐 몸 밖으로 나갑니다.」 □□에 알맞은 말을 쓰세요.","answer":["숨관"],"explanation":["들이마실 때를 거꾸로 해요.","코 바로 안쪽 통로예요.","숨관이에요."],"mis":"SC5-1-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#3','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',3,'mc','auto','숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X25','SC5-1-u4-X26']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C22","difficulty":3,"kind":"mc","stem":"숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 바르게 말한 것은 어느 것인가요?","options":[{"t":"같은 길을 서로 반대 방향으로 지난다","correct":true},{"t":"들이마실 때와 내쉴 때 서로 다른 길로 지난다","mis":"SC5-1-u4-X25"},{"t":"내쉴 때에도 코에서 폐 쪽으로 들어간다","mis":"SC5-1-u4-X25"},{"t":"내쉴 때에는 식도를 지나 나간다","mis":"SC5-1-u4-X26"}],"explanation":["정리 공책을 떠올려요.","거꾸로 되짚어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#4','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C21',3,'ox','auto','폐가 받아들인 산소는 몸에서 아무 일에도 쓰이지 않아요.',ARRAY['SC5-1-u4-X27']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"ox","stem":"폐가 받아들인 산소는 몸에서 아무 일에도 쓰이지 않아요.","answer":"X","reason_options":[{"t":"산소는 몸을 움직이거나 몸속 기관이 일하는 데 쓰이기 때문에","correct":true},{"t":"산소는 들어왔다가 그대로 다시 나가기만 하기 때문에","mis":"SC5-1-u4-X27"}],"mis":"SC5-1-u4-X27","explanation":["산소가 하는 일을 떠올려요.","몸이 써요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#5','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C21',3,'mc','auto','혈액이 온몸에 나르는 산소는 어디에서 오나요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X27','SC5-1-u4-X26']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"mc","stem":"혈액이 온몸에 나르는 산소는 어디에서 오나요?","options":[{"t":"숨을 들이마실 때 폐가 받아들인 산소","correct":true},{"t":"심장이 새로 만든 산소","mis":"SC5-1-u4-X17"},{"t":"작은창자가 음식물에서 흡수한 산소","mis":"SC5-1-u4-X27"},{"t":"식도로 삼켜서 들어온 산소","mis":"SC5-1-u4-X26"}],"explanation":["지난 시간과 이어요.","폐가 받아들여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#6','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C23',3,'error','auto','호흡기관 모형 실험을 하며 친구들이 한 일을 말했어요. 알맞지 않은 행동을 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C23","difficulty":3,"kind":"error","stem":"호흡기관 모형 실험을 하며 친구들이 한 일을 말했어요. 알맞지 않은 행동을 한 친구는 누구인가요?","options":[{"t":"은재 — 「종이봉투를 크게 부풀리려고 숨이 차도 계속 불었어.」","correct":true,"mis_target":"SC5-1-u4-X29"},{"t":"하율 — 「붙임딱지를 각 기관의 위치에 맞게 붙였어.」","mis":"SC5-1-u4-X29"},{"t":"민규 — 「어지러워서 잠깐 활동을 멈췄어.」","mis":"SC5-1-u4-X29"}],"explanation":["안전 약속을 떠올려요.","무리하지 않아요.","은재가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#7','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C20',3,'mc','auto','폐가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X27','SC5-1-u4-X24']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C20","difficulty":3,"kind":"mc","stem":"폐가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"산소를 받아들이고 이산화 탄소를 몸 밖으로 내보낸다","correct":true},{"t":"음식물 속의 영양소를 흡수한다","mis":"SC5-1-u4-X27"},{"t":"펌프 작용으로 혈액을 온몸으로 보낸다","mis":"SC5-1-u4-X24"},{"t":"공기가 처음 드나드는 곳이다","mis":"SC5-1-u4-X24"}],"explanation":["공기의 길 끝이에요.","기체를 주고받아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#8','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',4,'mc','auto','친구의 정리 공책에서 잘못 쓴 것은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X27','SC5-1-u4-X28']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"mc","stem":"친구의 정리 공책에서 잘못 쓴 것은 어느 것인가요?","options":[{"t":"③","correct":true},{"t":"①","mis":"SC5-1-u4-X24"},{"t":"②","mis":"SC5-1-u4-X27"},{"t":"④","mis":"SC5-1-u4-X28"}],"explanation":["들이마실 때와 내쉴 때를 견줘요.","내쉴 때는 반대예요.","③이 잘못되었어요."],"asset":{"type":"passage","lines":["① 들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","② 폐는 우리 몸에 필요한 산소를 받아들인다.","③ 내쉴 때 — 코 → 숨관 → 숨관가지 → 폐","④ 내쉬는 공기에는 이산화 탄소가 들어 있다."],"title":"친구의 호흡 정리 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#9','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C21',4,'mc','auto','숨을 들이마셔 들어온 산소가 다리 근육까지 가는 과정으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X26','SC5-1-u4-X24','SC5-1-u4-X27']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C21","difficulty":4,"kind":"mc","stem":"숨을 들이마셔 들어온 산소가 다리 근육까지 가는 과정으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"폐가 받아들인 산소를 혈액이 혈관을 따라 다리까지 운반한다","correct":true},{"t":"산소가 숨관을 따라 다리까지 내려간다","mis":"SC5-1-u4-X26"},{"t":"다리 근육이 직접 공기를 들이마신다","mis":"SC5-1-u4-X24"},{"t":"산소는 폐에만 머물고 다리로 가지 않는다","mis":"SC5-1-u4-X27"}],"explanation":["폐와 혈액을 이어요.","혈액이 운반해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L05_challenge#10','sci',5,1,'u4','L05','g5_1_sci_u4_L05_challenge','lesson_challenge','SC5-1-u4-C22',4,'essay','teacher','숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 각각 쓰고, 폐가 하는 일을 쓰세요. 그리고 친구의 정리 공책에서 잘못된 줄을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"essay","stem":"숨을 들이마실 때와 내쉴 때 공기가 지나는 길을 각각 쓰고, 폐가 하는 일을 쓰세요. 그리고 친구의 정리 공책에서 잘못된 줄을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 숨을 들이마시면 공기가 코 → 숨관 → 숨관가지 → 폐로 들어가고, 내쉬면 폐 → 숨관가지 → 숨관 → 코를 거쳐 몸 밖으로 나간다. 폐는 우리 몸에 필요한 산소를 받아들이고, 몸속에서 생긴 이산화 탄소를 몸 밖으로 내보낸다. ③은 「내쉴 때 — 폐 → 숨관가지 → 숨관 → 코」로 고쳐야 한다.","scoring_points":["들이마실 때의 길을 바르게 썼는가","내쉴 때 길이 반대라고 썼는가","폐가 하는 일과 ③ 고치기를 바르게 썼는가"]},"explanation":["들이마실 때부터 써요.","내쉴 때는 거꾸로예요.","③을 고쳐요."],"asset":{"type":"passage","lines":["① 들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","② 폐는 우리 몸에 필요한 산소를 받아들인다.","③ 내쉴 때 — 코 → 숨관 → 숨관가지 → 폐","④ 내쉬는 공기에는 이산화 탄소가 들어 있다."],"title":"친구의 호흡 정리 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#1','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C24',1,'blank','auto','「혈액 속의 노폐물을 걸러 내어 몸 밖으로 내보내는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X31']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"blank","stem":"「혈액 속의 노폐물을 걸러 내어 몸 밖으로 내보내는 과정을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"배설","correct":true},{"t":"배출","mis":"SC5-1-u4-X30"},{"t":"소화","mis":"SC5-1-u4-X31"},{"t":"순환","mis":"SC5-1-u4-X31"}],"explanation":["노폐물을 내보내요.","배출과 헷갈리지 않아요.","배설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#2','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',1,'mc','auto','혈액 속의 노폐물을 걸러 내어 오줌을 만드는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C25","difficulty":1,"kind":"mc","stem":"혈액 속의 노폐물을 걸러 내어 오줌을 만드는 기관은 어느 것인가요?","options":[{"t":"콩팥","correct":true},{"t":"방광","mis":"SC5-1-u4-X32"},{"t":"오줌관","mis":"SC5-1-u4-X32"},{"t":"폐","mis":"SC5-1-u4-X32"}],"explanation":["강낭콩처럼 생겼어요.","걸러 내요.","콩팥이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#3','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',1,'sa','auto','「오줌을 모아 두었다가 몸 밖으로 내보내는 기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C25","difficulty":1,"kind":"sa","stem":"「오줌을 모아 두었다가 몸 밖으로 내보내는 기관은 □□입니다.」 □□에 알맞은 말을 쓰세요.","answer":["방광"],"explanation":["오줌관 다음이에요.","두 글자예요.","방광이에요."],"mis":"SC5-1-u4-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#4','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C24',1,'ox','auto','노폐물은 몸에서 영양소가 쓰이면서 만들어져요.',ARRAY['SC5-1-u4-X31']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"ox","stem":"노폐물은 몸에서 영양소가 쓰이면서 만들어져요.","answer":"O","reason_options":[{"t":"영양소가 쓰이면 몸에 필요 없는 것이 생기기 때문에","correct":true},{"t":"노폐물은 먹은 음식물에서만 곧바로 생기기 때문에","mis":"SC5-1-u4-X31"}],"mis":"SC5-1-u4-X31","explanation":["노폐물이 생기는 때를 떠올려요.","영양소가 쓰일 때예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#5','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',2,'match','auto','배설기관과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"match","stem":"배설기관과 하는 일을 알맞게 이으세요.","pairs":[{"l":"콩팥","r":"혈액 속의 노폐물을 걸러 내어 오줌을 만든다"},{"l":"오줌관","r":"오줌이 이동하는 통로이다"},{"l":"방광","r":"오줌을 모아 두었다가 몸 밖으로 내보낸다"}],"mis":"SC5-1-u4-X32","explanation":["오줌을 따라가요.","만들고, 지나고, 모아요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#6','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C26',2,'mc','auto','다음 가운데 배설에 해당하는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"mc","stem":"다음 가운데 배설에 해당하는 것은 어느 것인가요?","options":[{"t":"콩팥이 걸러 만든 오줌이 몸 밖으로 나가는 것","correct":true},{"t":"큰창자를 지난 음식물 찌꺼기가 항문으로 나가는 것","mis":"SC5-1-u4-X30"},{"t":"똥을 누는 것","mis":"SC5-1-u4-X30"},{"t":"소화되고 남은 것을 내보내는 것","mis":"SC5-1-u4-X30"}],"explanation":["배설은 혈액 속 노폐물이에요.","오줌이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#7','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',2,'mc','auto','오줌이 몸 밖으로 나가는 길로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X34']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"mc","stem":"오줌이 몸 밖으로 나가는 길로 알맞은 것은 어느 것인가요?","options":[{"t":"콩팥 → 오줌관 → 방광 → 몸 밖","correct":true},{"t":"방광 → 오줌관 → 콩팥 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"콩팥 → 방광 → 오줌관 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"오줌관 → 콩팥 → 방광 → 몸 밖","mis":"SC5-1-u4-X34"}],"explanation":["만드는 곳부터예요.","통로를 지나 모여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#8','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C26',2,'error','auto','배설에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X32','SC5-1-u4-X34']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"error","stem":"배설에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「똥을 누는 것이 배설이야.」","correct":true,"mis_target":"SC5-1-u4-X30"},{"t":"도준 — 「콩팥은 혈액 속의 노폐물을 걸러 내.」","mis":"SC5-1-u4-X32"},{"t":"서윤 — 「오줌은 방광에 모였다가 나가.」","mis":"SC5-1-u4-X34"}],"explanation":["배설과 배출을 견줘요.","똥은 배출이에요.","하린이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#9','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C27',2,'mc','auto','잠을 잘 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C27","difficulty":2,"kind":"mc","stem":"잠을 잘 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"활동할 때보다 천천히 호흡한다","correct":true},{"t":"호흡이 완전히 멈춘다","mis":"SC5-1-u4-X35"},{"t":"모든 기관이 하던 일을 멈추고 쉰다","mis":"SC5-1-u4-X35"},{"t":"호흡 말고는 아무 기관도 일하지 않는다","mis":"SC5-1-u4-X35"}],"explanation":["자는 동안에도 숨을 쉬어요.","천천히요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_basic#10','sci',5,1,'u4','L06','g5_1_sci_u4_L06_basic','lesson_basic','SC5-1-u4-C25',3,'mc','auto','콩팥에서 노폐물이 걸러진 혈액은 어떻게 되나요?',ARRAY['SC5-1-u4-X33']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"mc","stem":"콩팥에서 노폐물이 걸러진 혈액은 어떻게 되나요?","options":[{"t":"다시 혈관을 통해 온몸을 순환한다","correct":true},{"t":"오줌과 함께 몸 밖으로 나간다","mis":"SC5-1-u4-X33"},{"t":"콩팥에 쌓여 더 이상 움직이지 않는다","mis":"SC5-1-u4-X33"},{"t":"방광에 모였다가 몸 밖으로 나간다","mis":"SC5-1-u4-X33"}],"explanation":["두 갈래를 떠올려요.","혈액은 돌아가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#1','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C27',2,'mc','auto','생각 그물 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C27","difficulty":2,"kind":"mc","stem":"생각 그물 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉠ → ㉣","correct":true},{"t":"㉢ → ㉡ → ㉣ → ㉠","mis":"SC5-1-u4-X35"},{"t":"㉡ → ㉠ → ㉢ → ㉣","mis":"SC5-1-u4-X35"},{"t":"㉠ → ㉢ → ㉡ → ㉣","mis":"SC5-1-u4-X35"}],"explanation":["먼저 조사해요.","그물로 만들고 발표해요.","경로 이야기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 완성한 생각 그물을 발표한다.","㉡ 배설기관 모형을 관찰해 그림과 이름을 연결하고 기능을 조사한다.","㉢ 배설기관의 이름과 하는 일을 생각 그물로 표현한다.","㉣ 노폐물이 몸 밖으로 나가는 경로를 이야기한다."],"title":"생각 그물 활동(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#2','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',2,'sa','auto','「오줌이 콩팥에서 방광으로 이동하는 통로는 □□□입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"sa","stem":"「오줌이 콩팥에서 방광으로 이동하는 통로는 □□□입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["오줌관"],"explanation":["콩팥과 방광 사이예요.","세 글자예요.","오줌관이에요."],"mis":"SC5-1-u4-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#3','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C26',3,'mc','auto','몸 밖으로 내보내는 일 네 가지 가운데 배설에 해당하는 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C26","difficulty":3,"kind":"mc","stem":"몸 밖으로 내보내는 일 네 가지 가운데 배설에 해당하는 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"㉠, ㉢","correct":true},{"t":"㉡, ㉣","mis":"SC5-1-u4-X30"},{"t":"㉠, ㉡","mis":"SC5-1-u4-X30"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"SC5-1-u4-X30"}],"explanation":["혈액 속 노폐물을 찾아요.","콩팥과 방광이에요.","㉠, ㉢이에요."],"asset":{"type":"passage","lines":["㉠ 콩팥이 혈액 속의 노폐물을 걸러 낸다.","㉡ 큰창자를 지난 음식물 찌꺼기가 항문으로 나간다.","㉢ 오줌이 방광에 모였다가 몸 밖으로 나간다.","㉣ 소화되고 남은 것이 몸 밖으로 나간다."],"title":"몸 밖으로 내보내는 일 네 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#4','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',3,'mc','auto','콩팥이 노폐물을 제대로 걸러 내지 못하면 어떤 일이 일어날까요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"mc","stem":"콩팥이 노폐물을 제대로 걸러 내지 못하면 어떤 일이 일어날까요?","options":[{"t":"노폐물이 몸속에 쌓여 건강에 문제가 생긴다","correct":true},{"t":"먹은 음식물이 소화되지 않는다","mis":"SC5-1-u4-X32"},{"t":"뼈가 더 이상 자라지 않는다","mis":"SC5-1-u4-X32"},{"t":"숨을 쉬지 못하게 된다","mis":"SC5-1-u4-X32"}],"explanation":["콩팥이 하는 일을 떠올려요.","걸러 내지 못하면 남아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#5','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C27',3,'ox','auto','한 가지 일을 할 때에는 그 일과 관련된 기관 하나만 일해요.',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C27","difficulty":3,"kind":"ox","stem":"한 가지 일을 할 때에는 그 일과 관련된 기관 하나만 일해요.","answer":"X","reason_options":[{"t":"식사할 때도 뼈와 근육, 소화기관 등 여러 기관이 함께 일하기 때문에","correct":true},{"t":"기관은 한 번에 하나씩만 일하기 때문에","mis":"SC5-1-u4-X35"}],"mis":"SC5-1-u4-X35","explanation":["식사할 때를 떠올려요.","여러 기관이 일해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#6','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C27',3,'mc','auto','여러 상황 기록의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C27","difficulty":3,"kind":"mc","stem":"여러 상황 기록의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"화장실에 가는 동안에도 소화기관은 먹은 음식물을 소화한다","correct":true},{"t":"화장실에 가는 동안에는 모든 기관이 쉰다","mis":"SC5-1-u4-X35"},{"t":"화장실에 가는 동안에는 호흡이 멈춘다","mis":"SC5-1-u4-X35"},{"t":"배설기관 하나만 일하고 나머지는 멈춘다","mis":"SC5-1-u4-X35"}],"explanation":["여러 기관이 함께 일해요.","소화기관도 일해요.","첫 번째예요."],"asset":{"type":"passage","lines":["식사할 때 — 팔뼈와 팔 근육으로 음식을 입에 넣고, 얼굴 근육으로 씹는다.","잠을 잘 때 — 활동할 때보다 천천히 호흡한다.","화장실에 갈 때 — ( ? )"],"title":"지능형 과학실 ON으로 본 여러 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#7','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',3,'error','auto','배설기관 생각 그물을 보고 친구들이 말했어요. 잘못 붙인 친구는 누구인가요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"error","stem":"배설기관 생각 그물을 보고 친구들이 말했어요. 잘못 붙인 친구는 누구인가요?","options":[{"t":"예준 — 「방광 가지에 ‘노폐물을 걸러 내어 오줌을 만든다’를 붙였어.」","correct":true,"mis_target":"SC5-1-u4-X32"},{"t":"소이 — 「콩팥 가지에 ‘노폐물을 걸러 내어 오줌을 만든다’를 붙였어.」","mis":"SC5-1-u4-X32"},{"t":"윤재 — 「오줌관 가지에 ‘오줌이 이동하는 통로’를 붙였어.」","mis":"SC5-1-u4-X32"}],"explanation":["방광이 하는 일을 떠올려요.","모아 두었다가 내보내요.","예준이 잘못 붙였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#8','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C24',4,'mc','auto','몸 곳곳에서 생긴 노폐물이 콩팥까지 오는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X34','SC5-1-u4-X31']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C24","difficulty":4,"kind":"mc","stem":"몸 곳곳에서 생긴 노폐물이 콩팥까지 오는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 노폐물을 실어 혈관을 따라 콩팥으로 운반한다","correct":true},{"t":"작은창자의 음식물이 콩팥으로 바로 내려간다","mis":"SC5-1-u4-X30"},{"t":"방광에서 오줌관을 거꾸로 거슬러 온다","mis":"SC5-1-u4-X34"},{"t":"노폐물은 콩팥에서만 생기므로 올 필요가 없다","mis":"SC5-1-u4-X31"}],"explanation":["지난 시간 순환과 이어요.","혈액이 운반해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#9','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C26',4,'mc','auto','배설기관과 소화기관이 몸 밖으로 내보내는 것을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C26","difficulty":4,"kind":"mc","stem":"배설기관과 소화기관이 몸 밖으로 내보내는 것을 바르게 견준 것은 어느 것인가요?","options":[{"t":"배설기관은 혈액 속 노폐물로 만든 오줌을, 소화기관은 음식물 찌꺼기를 내보낸다","correct":true},{"t":"둘 다 음식물 찌꺼기를 내보낸다","mis":"SC5-1-u4-X30"},{"t":"배설기관은 음식물 찌꺼기를, 소화기관은 오줌을 내보낸다","mis":"SC5-1-u4-X30"},{"t":"둘이 내보내는 것은 똑같다","mis":"SC5-1-u4-X30"}],"explanation":["배설과 배출을 견줘요.","내보내는 것이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L06_challenge#10','sci',5,1,'u4','L06','g5_1_sci_u4_L06_challenge','lesson_challenge','SC5-1-u4-C25',4,'essay','teacher','콩팥에서 오줌이 만들어져 몸 밖으로 나가는 길을 쓰고, 노폐물이 걸러진 혈액이 어떻게 되는지 쓰세요. 그리고 배설과 배출이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C25","difficulty":4,"kind":"essay","stem":"콩팥에서 오줌이 만들어져 몸 밖으로 나가는 길을 쓰고, 노폐물이 걸러진 혈액이 어떻게 되는지 쓰세요. 그리고 배설과 배출이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 콩팥은 혈액 속의 노폐물을 걸러 내어 오줌을 만들고, 오줌은 오줌관을 지나 방광에 모였다가 몸 밖으로 나간다. 노폐물이 걸러진 혈액은 다시 혈관을 통해 온몸을 순환한다. 배설은 혈액 속 노폐물을 걸러 내보내는 것이고, 배출은 소화되고 남은 음식물 찌꺼기가 항문으로 나가는 것이다.","scoring_points":["콩팥 → 오줌관 → 방광의 길을 썼는가","걸러진 혈액이 다시 순환한다고 썼는가","배설과 배출을 바르게 구별했는가"]},"explanation":["콩팥부터 따라가요.","혈액 갈래도 써요.","배설과 배출을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#1','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C28',1,'mc','auto','맥박이란 무엇인가요?',ARRAY['SC5-1-u4-X36']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C28","difficulty":1,"kind":"mc","stem":"맥박이란 무엇인가요?","options":[{"t":"심장의 박동이 목이나 팔목 등에서 느껴지는 것","correct":true},{"t":"몸의 따뜻한 정도","mis":"SC5-1-u4-X36"},{"t":"숨을 들이마시고 내쉬는 활동","mis":"SC5-1-u4-X36"},{"t":"몸에서 땀이 나는 정도","mis":"SC5-1-u4-X36"}],"explanation":["팔목을 짚어 봐요.","콩닥콩닥 느껴져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#2','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C29',1,'ox','auto','운동 직후의 체온은 운동 전보다 높아져요.',ARRAY['SC5-1-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"ox","stem":"운동 직후의 체온은 운동 전보다 높아져요.","answer":"O","reason_options":[{"t":"운동을 하면 체온이 올라가고 땀이 나기도 하기 때문에","correct":true},{"t":"운동을 하면 몸이 식어 체온이 내려가기 때문에","mis":"SC5-1-u4-X37"}],"mis":"SC5-1-u4-X37","explanation":["운동 뒤 몸을 떠올려요.","따뜻해지고 땀이 나요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#3','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C28',1,'sa','auto','「몸의 따뜻한 정도를 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C28","difficulty":1,"kind":"sa","stem":"「몸의 따뜻한 정도를 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["체온"],"explanation":["체온계로 재요.","두 글자예요.","체온이에요."],"mis":"SC5-1-u4-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#4','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C29',1,'mc','auto','운동을 하면 호흡과 심장은 어떻게 되나요?',ARRAY['SC5-1-u4-X37']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"mc","stem":"운동을 하면 호흡과 심장은 어떻게 되나요?","options":[{"t":"호흡이 빨라지고 심장이 빠르게 뛴다","correct":true},{"t":"호흡이 느려지고 심장이 느리게 뛴다","mis":"SC5-1-u4-X37"},{"t":"호흡이 빨라지고 심장이 느리게 뛴다","mis":"SC5-1-u4-X37"},{"t":"호흡과 심장 모두 그대로이다","mis":"SC5-1-u4-X37"}],"explanation":["달리기한 뒤를 떠올려요.","숨이 차고 두근거려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#5','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C31',2,'match','auto','몸을 움직일 때 기관이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C31","difficulty":2,"kind":"match","stem":"몸을 움직일 때 기관이 하는 일을 알맞게 이으세요.","pairs":[{"l":"소화기관","r":"음식물을 소화해 영양소를 흡수한다"},{"l":"호흡기관","r":"산소를 받아들이고 이산화 탄소를 내보낸다"},{"l":"순환기관","r":"산소와 영양소를 온몸에 운반한다"},{"l":"배설기관","r":"혈액 속의 노폐물을 걸러 내보낸다"}],"mis":"SC5-1-u4-X40","explanation":["네 기관을 떠올려요.","흡수, 받아들임, 운반, 거르기예요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#6','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C30',2,'mc','auto','운동할 때 호흡이 빨라지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X28','SC5-1-u4-X27']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C30","difficulty":2,"kind":"mc","stem":"운동할 때 호흡이 빨라지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산소를 많이 흡수하기 위해서","correct":true},{"t":"단지 몸이 힘들기 때문에","mis":"SC5-1-u4-X39"},{"t":"이산화 탄소를 더 많이 받아들이기 위해서","mis":"SC5-1-u4-X28"},{"t":"폐에서 영양소를 흡수하기 위해서","mis":"SC5-1-u4-X27"}],"explanation":["근육에 필요한 것을 떠올려요.","산소가 많이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#7','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C28',2,'blank','auto','「운동한 후 측정하고, (    ) 정도 휴식한 후 체온과 맥박 수를 한 번 더 측정합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C28","difficulty":2,"kind":"blank","stem":"「운동한 후 측정하고, (    ) 정도 휴식한 후 체온과 맥박 수를 한 번 더 측정합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"5분","correct":true},{"t":"1초","mis":"SC5-1-u4-X41"},{"t":"하루","mis":"SC5-1-u4-X41"},{"t":"일주일","mis":"SC5-1-u4-X41"}],"explanation":["잠깐 쉬어요.","몇 분이에요.","5분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#8','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C31',2,'error','auto','운동할 때 우리 몸에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X40','SC5-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C31","difficulty":2,"kind":"error","stem":"운동할 때 우리 몸에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「우리 몸의 기관은 저마다 따로따로 일해.」","correct":true,"mis_target":"SC5-1-u4-X40"},{"t":"아린 — 「각 기관은 서로 영향을 주고받아.」","mis":"SC5-1-u4-X40"},{"t":"건우 — 「운동하면 체온이 올라가고 땀이 나기도 해.」","mis":"SC5-1-u4-X37"}],"explanation":["기관끼리 관계가 있나요?","서로 영향을 주고받아요.","지호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#9','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C29',2,'mc','auto','측정 기록에서 맥박 수가 가장 많은 때는 언제인가요?',ARRAY['SC5-1-u4-X37','SC5-1-u4-X38']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C29","difficulty":2,"kind":"mc","stem":"측정 기록에서 맥박 수가 가장 많은 때는 언제인가요?","options":[{"t":"운동 직후","correct":true},{"t":"운동 전","mis":"SC5-1-u4-X37"},{"t":"5분 휴식 후","mis":"SC5-1-u4-X38"},{"t":"세 번 모두 같다","mis":"SC5-1-u4-X37"}],"explanation":["가장 큰 수를 찾아요.","108회예요.","운동 직후예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_basic#10','sci',5,1,'u4','L07','g5_1_sci_u4_L07_basic','lesson_basic','SC5-1-u4-C30',3,'mc','auto','운동할 때 순환기관이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X32','SC5-1-u4-X40']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C30","difficulty":3,"kind":"mc","stem":"운동할 때 순환기관이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"산소와 영양소를 온몸에 운반하고, 이산화 탄소는 호흡기관으로, 노폐물은 배설기관으로 운반한다","correct":true},{"t":"음식물을 잘게 쪼개 영양소를 흡수한다","mis":"SC5-1-u4-X22"},{"t":"혈액 속의 노폐물을 걸러 오줌을 만든다","mis":"SC5-1-u4-X32"},{"t":"운동하는 동안에는 하던 일을 멈춘다","mis":"SC5-1-u4-X40"}],"explanation":["순환기관은 운반해요.","세 곳으로 날라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#1','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C28',2,'mc','auto','체온과 맥박 수를 측정하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C28","difficulty":2,"kind":"mc","stem":"체온과 맥박 수를 측정하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉣ → ㉤ → ㉠ → ㉢","correct":true},{"t":"㉣ → ㉡ → ㉤ → ㉢ → ㉠","mis":"SC5-1-u4-X41"},{"t":"㉡ → ㉤ → ㉣ → ㉠ → ㉢","mis":"SC5-1-u4-X41"},{"t":"㉤ → ㉠ → ㉡ → ㉣ → ㉢","mis":"SC5-1-u4-X41"}],"explanation":["준비 운동이 먼저예요.","운동 전에 재고 운동해요.","그래프는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 운동한 후 측정하고, 5분 정도 휴식한 후 한 번 더 측정한다.","㉡ 간단한 준비 운동을 한다.","㉢ 측정한 결과를 그래프로 나타내고 이야기한다.","㉣ 운동하기 전에 체온과 맥박 수를 측정한다.","㉤ 제자리 뛰기 같은 가벼운 운동을 한다."],"title":"체온과 맥박 수 측정(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#2','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C29',2,'sa','auto','측정 기록에서 운동 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C29","difficulty":2,"kind":"sa","stem":"측정 기록에서 운동 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.","answer":["108","108회"],"explanation":["운동 직후 줄을 읽어요.","백 회가 넘어요.","108회예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"},"mis":"SC5-1-u4-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#3','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C30',3,'mc','auto','운동할 때 심장이 빠르게 뛰는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X17','SC5-1-u4-X37']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C30","difficulty":3,"kind":"mc","stem":"운동할 때 심장이 빠르게 뛰는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산소와 영양소를 온몸에 빠르게 운반하기 위해서","correct":true},{"t":"단지 몸이 힘들기 때문에","mis":"SC5-1-u4-X39"},{"t":"혈액을 더 많이 만들어 내기 위해서","mis":"SC5-1-u4-X17"},{"t":"체온을 내리기 위해서","mis":"SC5-1-u4-X37"}],"explanation":["근육에 필요한 것을 떠올려요.","빨리 날라야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#4','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C31',3,'ox','auto','운동하는 동안 소화기관과 배설기관은 하던 일을 멈춰요.',ARRAY['SC5-1-u4-X40']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C31","difficulty":3,"kind":"ox","stem":"운동하는 동안 소화기관과 배설기관은 하던 일을 멈춰요.","answer":"X","reason_options":[{"t":"운동하는 동안에도 영양소를 흡수하고 노폐물을 걸러 내는 일을 계속하기 때문에","correct":true},{"t":"운동할 때는 뼈와 근육만 일하기 때문에","mis":"SC5-1-u4-X40"}],"mis":"SC5-1-u4-X40","explanation":["쉬고 있는 기관이 있었나요?","모두 일해요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#5','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C29',3,'mc','auto','측정 기록의 5분 휴식 후 값으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X38']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C29","difficulty":3,"kind":"mc","stem":"측정 기록의 5분 휴식 후 값으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"휴식을 하면 체온과 맥박 수가 차츰 운동 전으로 돌아간다","correct":true},{"t":"휴식을 해도 운동 직후 값이 그대로 이어진다","mis":"SC5-1-u4-X38"},{"t":"휴식을 하면 맥박 수가 계속 많아진다","mis":"SC5-1-u4-X38"},{"t":"휴식을 하면 운동 전보다 훨씬 적어진다","mis":"SC5-1-u4-X38"}],"explanation":["세 값을 견줘요.","108에서 84로 줄었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#6','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C28',3,'error','auto','체온과 맥박 수를 측정하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C28","difficulty":3,"kind":"error","stem":"체온과 맥박 수를 측정하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"태윤 — 「운동 직후에 재는 걸 깜빡해서 5분 쉬고 나서 처음 쟀어.」","correct":true,"mis_target":"SC5-1-u4-X41"},{"t":"나연 — 「체온은 체온계로, 맥박 수는 애플리케이션으로 쟀어.」","mis":"SC5-1-u4-X41"},{"t":"준서 — 「운동하기 전에 준비 운동을 했어.」","mis":"SC5-1-u4-X41"}],"explanation":["세 번 재야 해요.","운동 직후에 바로 재요.","태윤이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#7','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C28',3,'mc','auto','측정한 결과를 기록하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C28","difficulty":3,"kind":"mc","stem":"측정한 결과를 기록하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"예상과 달라도 잰 값을 정확하게 기록한다","correct":true},{"t":"친구가 잰 값을 그대로 베낀다","mis":"SC5-1-u4-X41"},{"t":"예상에 맞도록 값을 고쳐 적는다","mis":"SC5-1-u4-X41"},{"t":"적지 않고 기억해 둔다","mis":"SC5-1-u4-X41"}],"explanation":["기록은 사실대로예요.","정확하게 적어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#8','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C30',4,'mc','auto','운동할 때 콧구멍을 넓혀 주는 밴드를 붙이면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X40','SC5-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"mc","stem":"운동할 때 콧구멍을 넓혀 주는 밴드를 붙이면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"코로 공기가 더 잘 드나들어 산소를 많이 받아들일 수 있다","correct":true},{"t":"심장이 덜 힘들어져 뛰지 않아도 된다","mis":"SC5-1-u4-X39"},{"t":"먹은 음식물이 더 빨리 소화된다","mis":"SC5-1-u4-X40"},{"t":"체온이 오르지 않게 막아 준다","mis":"SC5-1-u4-X37"}],"explanation":["코는 공기가 드나드는 곳이에요.","산소가 많이 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#9','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C31',4,'mc','auto','운동할 때 우리 몸에서 일어나는 일을 차례대로 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X37','SC5-1-u4-X40']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"mc","stem":"운동할 때 우리 몸에서 일어나는 일을 차례대로 바르게 이은 것은 어느 것인가요?","options":[{"t":"근육이 산소와 영양소를 많이 쓴다 → 호흡이 빨라지고 심장이 빠르게 뛴다 → 산소와 영양소가 빠르게 운반된다","correct":true},{"t":"몸이 힘들다 → 심장이 그냥 빨라진다 → 아무것도 운반되지 않는다","mis":"SC5-1-u4-X39"},{"t":"호흡이 느려진다 → 심장이 느리게 뛴다 → 체온이 내려간다","mis":"SC5-1-u4-X37"},{"t":"근육만 일한다 → 다른 기관은 멈춘다 → 몸이 움직인다","mis":"SC5-1-u4-X40"}],"explanation":["근육에서 시작해요.","필요한 것을 빨리 날라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L07_challenge#10','sci',5,1,'u4','L07','g5_1_sci_u4_L07_challenge','lesson_challenge','SC5-1-u4-C30',4,'essay','teacher','측정 기록을 보고 운동 직후와 5분 휴식 후 체온과 맥박 수가 어떻게 변했는지 쓰고, 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 까닭을 여러 기관과 관련지어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"essay","stem":"측정 기록을 보고 운동 직후와 5분 휴식 후 체온과 맥박 수가 어떻게 변했는지 쓰고, 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 까닭을 여러 기관과 관련지어 쓰세요.","answer_guide":{"answer":"예: 운동 직후에는 체온이 36.9 °C, 맥박 수가 108회로 운동 전보다 높아졌고, 5분 휴식 후에는 36.7 °C, 84회로 차츰 운동 전으로 돌아갔다. 운동할 때 뼈와 근육이 움직이려면 산소와 영양소가 필요하다. 그래서 산소를 많이 흡수하려고 호흡이 빨라지고, 산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빠르게 뛴다. 이처럼 각 기관은 서로 영향을 주고받으며 작용한다.","scoring_points":["운동 직후에 높아지고 휴식 후 돌아간다고 썼는가","산소와 영양소가 필요하다는 까닭을 썼는가","호흡기관·순환기관을 관련지어 썼는가"]},"explanation":["표를 읽어요.","근육에 필요한 것을 떠올려요.","기관끼리 이어요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.5 °C, 1분 동안의 맥박 수 72회","운동 직후 — 체온 36.9 °C, 1분 동안의 맥박 수 108회","5분 휴식 후 — 체온 36.7 °C, 1분 동안의 맥박 수 84회","(예시 값 — 실제 값은 사람마다 다름)"],"title":"우리 모둠 측정 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#1','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C32',1,'mc','auto','감기, 장염 등 다양한 질병은 무엇과 관련이 있나요?',ARRAY['SC5-1-u4-X42']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C32","difficulty":1,"kind":"mc","stem":"감기, 장염 등 다양한 질병은 무엇과 관련이 있나요?","options":[{"t":"우리 몸의 기관","correct":true},{"t":"그날그날의 운","mis":"SC5-1-u4-X42"},{"t":"태어난 달","mis":"SC5-1-u4-X42"},{"t":"입은 옷의 색깔","mis":"SC5-1-u4-X42"}],"explanation":["몸이 아픈 곳을 떠올려요.","기관이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#2','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',1,'sa','auto','「변비를 예방하려면 □□를 많이 먹고, 물을 충분히 마시며, 운동을 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C33","difficulty":1,"kind":"sa","stem":"「변비를 예방하려면 □□를 많이 먹고, 물을 충분히 마시며, 운동을 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["채소"],"explanation":["반찬을 떠올려요.","두 글자예요.","채소예요."],"mis":"SC5-1-u4-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#3','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',1,'ox','auto','손을 잘 씻으면 감기를 예방하는 데 도움이 돼요.',ARRAY['SC5-1-u4-X42']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C33","difficulty":1,"kind":"ox","stem":"손을 잘 씻으면 감기를 예방하는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"감기의 예방법으로 손 씻기가 있기 때문에","correct":true},{"t":"감기는 운이 나빠서 걸리므로 손 씻기와 관계없기 때문에","mis":"SC5-1-u4-X42"}],"mis":"SC5-1-u4-X42","explanation":["2모둠 자료를 떠올려요.","손 씻기예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#4','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C34',1,'blank','auto','「질병을 조사할 때는 질병의 종류와 (    ), 예방법을 함께 살펴봅니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C34","difficulty":1,"kind":"blank","stem":"「질병을 조사할 때는 질병의 종류와 (    ), 예방법을 함께 살펴봅니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"증상","correct":true},{"t":"가격","mis":"SC5-1-u4-X45"},{"t":"이름의 글자 수","mis":"SC5-1-u4-X45"},{"t":"유행한 해","mis":"SC5-1-u4-X45"}],"explanation":["아플 때 나타나는 것이에요.","기침, 콧물 같은 것이에요.","증상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#5','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',2,'match','auto','증상과 예방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"match","stem":"증상과 예방법을 알맞게 이으세요.","pairs":[{"l":"변비의 증상","r":"똥이 잘 나오지 않고 배가 아프다"},{"l":"변비의 예방법","r":"채소 많이 먹기, 물 충분히 마시기, 운동하기"},{"l":"감기의 증상","r":"기침, 콧물, 코 막힘"},{"l":"감기의 예방법","r":"손 씻기"}],"mis":"SC5-1-u4-X44","explanation":["모둠별 자료를 떠올려요.","증상과 예방법을 나눠요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#6','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C32',2,'mc','auto','감기와 관련 있는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C32","difficulty":2,"kind":"mc","stem":"감기와 관련 있는 기관은 어느 것인가요?","options":[{"t":"호흡기관","correct":true},{"t":"소화기관","mis":"SC5-1-u4-X44"},{"t":"배설기관","mis":"SC5-1-u4-X44"},{"t":"어느 기관과도 관련이 없다","mis":"SC5-1-u4-X42"}],"explanation":["기침과 콧물을 떠올려요.","코와 숨관이에요.","호흡기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#7','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C34',2,'mc','auto','질병을 조사할 때 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"mc","stem":"질병을 조사할 때 알맞은 방법은 어느 것인가요?","options":[{"t":"검색 자료가 너무 많으면 검색어가 포함된 자료를 활용한다","correct":true},{"t":"가장 위에 있는 자료 하나만 그대로 옮겨 적는다","mis":"SC5-1-u4-X45"},{"t":"조사한 자료는 우리 모둠만 보고 나누지 않는다","mis":"SC5-1-u4-X45"},{"t":"스마트 기기가 뜨거워져도 다 만들 때까지 쓴다","mis":"SC5-1-u4-X45"}],"explanation":["자료가 많을 때예요.","검색어로 골라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#8','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',2,'error','auto','질병 예방에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X43','SC5-1-u4-X42','SC5-1-u4-X44']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"error","stem":"질병 예방에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유진 — 「질병 예방은 어른이 해 주는 거라 우리는 할 게 없어.」","correct":true,"mis_target":"SC5-1-u4-X43"},{"t":"태하 — 「손 씻기는 감기 예방에 도움이 돼.」","mis":"SC5-1-u4-X42"},{"t":"미소 — 「채소를 많이 먹으면 변비 예방에 도움이 돼.」","mis":"SC5-1-u4-X44"}],"explanation":["어린이도 할 수 있나요?","날마다 할 수 있어요.","유진이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#9','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C32',2,'mc','auto','변비와 관련 있는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C32","difficulty":2,"kind":"mc","stem":"변비와 관련 있는 기관은 어느 것인가요?","options":[{"t":"소화기관","correct":true},{"t":"호흡기관","mis":"SC5-1-u4-X44"},{"t":"순환기관","mis":"SC5-1-u4-X44"},{"t":"어느 기관과도 관련이 없다","mis":"SC5-1-u4-X42"}],"explanation":["똥이 잘 나오지 않아요.","큰창자와 항문이에요.","소화기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_basic#10','sci',5,1,'u4','L08','g5_1_sci_u4_L08_basic','lesson_basic','SC5-1-u4-C33',3,'mc','auto','감기와 변비의 예방법을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X43','SC5-1-u4-X42']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C33","difficulty":3,"kind":"mc","stem":"감기와 변비의 예방법을 보고 알 수 있는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"평소의 생활 습관으로 질병을 예방하는 데 도움을 줄 수 있다","correct":true},{"t":"질병은 약으로만 막을 수 있다","mis":"SC5-1-u4-X43"},{"t":"질병 예방은 어른만 할 수 있다","mis":"SC5-1-u4-X43"},{"t":"질병은 운에 달려 있어 어떻게 할 수 없다","mis":"SC5-1-u4-X42"}],"explanation":["손 씻기, 채소 먹기예요.","날마다 하는 일이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#1','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',2,'mc','auto','질병 조사와 공유 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"mc","stem":"질병 조사와 공유 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉢ → ㉣ → ㉠ → ㉤","correct":true},{"t":"㉢ → ㉡ → ㉣ → ㉤ → ㉠","mis":"SC5-1-u4-X45"},{"t":"㉡ → ㉣ → ㉢ → ㉠ → ㉤","mis":"SC5-1-u4-X45"},{"t":"㉠ → ㉡ → ㉢ → ㉣ → ㉤","mis":"SC5-1-u4-X45"}],"explanation":["기관부터 골라요.","조사하고 만들어요.","올린 뒤 댓글을 달아요."],"asset":{"type":"passage","lines":["㉠ 만든 자료나 책을 공유 플랫폼에 올린다.","㉡ 소화, 순환, 호흡, 배설기관 가운데 한 가지를 고른다.","㉢ 고른 기관과 관련 있는 질병의 종류와 증상, 예방법을 조사한다.","㉣ 발표 자료나 책을 계획하고 만든다.","㉤ 다른 모둠 자료를 보고 알게 된 점을 댓글로 단다."],"title":"질병 조사와 공유(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#2','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',2,'sa','auto','「질병의 종류와 증상, 예방법은 국가건강정보□□에서 찾을 수 있습니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"sa","stem":"「질병의 종류와 증상, 예방법은 국가건강정보□□에서 찾을 수 있습니다.」 □□에 알맞은 말을 쓰세요.","answer":["포털"],"explanation":["누리집 이름이에요.","두 글자예요.","포털이에요."],"mis":"SC5-1-u4-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#3','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C33',3,'mc','auto','2모둠 자료를 보고 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C33","difficulty":3,"kind":"mc","stem":"2모둠 자료를 보고 바르게 말한 것은 어느 것인가요?","options":[{"t":"감기는 호흡기관과 관련이 있고, 손 씻기로 예방하는 데 도움을 줄 수 있다","correct":true},{"t":"감기는 소화기관과 관련이 있다","mis":"SC5-1-u4-X44"},{"t":"감기는 예방할 수 있는 방법이 없다","mis":"SC5-1-u4-X42"},{"t":"감기의 증상은 똥이 잘 나오지 않는 것이다","mis":"SC5-1-u4-X44"}],"explanation":["2모둠 줄을 읽어요.","호흡기관이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비","증상: 똥이 잘 나오지 않음, 배가 아픔","예방법: 채소 많이 먹기, 물 충분히 마시기, 운동하기","2모둠 호흡기관 — 감기","증상: 기침, 콧물, 코 막힘","예방법: 손 씻기"],"title":"모둠별 질병 조사 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#4','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C32',3,'ox','auto','질병은 운이 나빠서 걸리는 것이라 예방할 수 없어요.',ARRAY['SC5-1-u4-X42']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"ox","stem":"질병은 운이 나빠서 걸리는 것이라 예방할 수 없어요.","answer":"X","reason_options":[{"t":"질병은 몸의 기관과 관련이 있고, 생활 습관으로 예방에 도움을 줄 수 있기 때문에","correct":true},{"t":"질병에 걸리는 것은 모두 운에 달려 있기 때문에","mis":"SC5-1-u4-X42"}],"mis":"SC5-1-u4-X42","explanation":["예방법을 떠올려요.","할 수 있는 일이 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#5','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',3,'mc','auto','모둠에서 발표 자료를 만드는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C34","difficulty":3,"kind":"mc","stem":"모둠에서 발표 자료를 만드는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠원마다 한 개씩 만들어 합치거나, 모둠에서 한 개를 함께 만든다","correct":true},{"t":"한 사람이 모든 것을 혼자 만든다","mis":"SC5-1-u4-X45"},{"t":"다른 모둠의 자료를 그대로 가져와 쓴다","mis":"SC5-1-u4-X45"},{"t":"만들지 않고 말로만 발표한다","mis":"SC5-1-u4-X45"}],"explanation":["함께 만드는 방법이에요.","두 가지가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#6','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',3,'error','auto','자료를 공유하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C34","difficulty":3,"kind":"error","stem":"자료를 공유하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"우진 — 「다른 모둠 자료는 보지 않고 우리 자료만 봤어.」","correct":true,"mis_target":"SC5-1-u4-X45"},{"t":"소윤 — 「다른 모둠 자료를 보고 알게 된 점을 댓글로 달았어.」","mis":"SC5-1-u4-X45"},{"t":"지율 — 「기기에서 열이 나서 바로 멈추고 선생님께 알렸어.」","mis":"SC5-1-u4-X45"}],"explanation":["공유하는 까닭을 떠올려요.","서로 나누어요.","우진이 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#7','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C32',3,'mc','auto','질병에 걸리면 어떤 일이 생길 수 있나요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X40']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"mc","stem":"질병에 걸리면 어떤 일이 생길 수 있나요?","options":[{"t":"몸이 아프고 일상생활을 하는 데 어려움이 생긴다","correct":true},{"t":"몸에 아무런 변화가 없다","mis":"SC5-1-u4-X42"},{"t":"아픈 기관 하나만 멈추고 다른 기관은 전과 같이 일한다","mis":"SC5-1-u4-X40"},{"t":"운이 좋아져 더 튼튼해진다","mis":"SC5-1-u4-X42"}],"explanation":["아플 때를 떠올려요.","생활이 힘들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#8','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C33',4,'mc','auto','감기에 자주 걸리는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C33","difficulty":4,"kind":"mc","stem":"감기에 자주 걸리는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「밖에서 돌아오면 손을 씻는 습관을 들이면 예방에 도움이 될 거야.」","correct":true},{"t":"「운이 나빠서 그런 거니 어쩔 수 없어.」","mis":"SC5-1-u4-X42"},{"t":"「어른이 대신 예방해 줄 테니 너는 할 일이 없어.」","mis":"SC5-1-u4-X43"},{"t":"「약만 먹으면 다른 건 안 해도 돼.」","mis":"SC5-1-u4-X43"}],"explanation":["감기의 예방법이에요.","날마다 할 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#9','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C34',4,'mc','auto','배설기관을 고른 모둠이 교과서에서 질병의 예를 찾지 못했어요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C34","difficulty":4,"kind":"mc","stem":"배설기관을 고른 모둠이 교과서에서 질병의 예를 찾지 못했어요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"국가건강정보포털에서 직접 찾아 질병의 종류와 증상, 예방법을 조사한다","correct":true},{"t":"그럴듯한 질병을 지어내어 칸을 채운다","mis":"SC5-1-u4-X45"},{"t":"다른 모둠의 자료를 그대로 베낀다","mis":"SC5-1-u4-X45"},{"t":"예가 없으니 조사를 그만둔다","mis":"SC5-1-u4-X45"}],"explanation":["조사하는 활동이에요.","믿을 만한 곳에서 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L08_challenge#10','sci',5,1,'u4','L08','g5_1_sci_u4_L08_challenge','lesson_challenge','SC5-1-u4-C33',4,'essay','teacher','모둠별 질병 조사 자료를 보고 두 질병이 각각 어느 기관과 관련 있는지, 증상과 예방법은 무엇인지 쓰세요. 그리고 이 자료로 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C33","difficulty":4,"kind":"essay","stem":"모둠별 질병 조사 자료를 보고 두 질병이 각각 어느 기관과 관련 있는지, 증상과 예방법은 무엇인지 쓰세요. 그리고 이 자료로 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 변비는 소화기관과 관련이 있고, 똥이 잘 나오지 않고 배가 아픈 증상이 있으며, 채소를 많이 먹고 물을 충분히 마시고 운동하면 예방에 도움이 된다. 감기는 호흡기관과 관련이 있고, 기침·콧물·코 막힘이 나타나며, 손을 잘 씻으면 예방에 도움이 된다. 다양한 질병은 우리 몸의 기관과 관련이 있고, 평소의 생활 습관으로 질병을 예방하는 데 도움을 줄 수 있다.","scoring_points":["두 질병과 관련 기관을 바르게 썼는가","증상과 예방법을 바르게 썼는가","생활 습관으로 예방할 수 있다고 썼는가"]},"explanation":["1모둠부터 읽어요.","증상과 예방법을 나눠요.","알게 된 점을 써요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비","증상: 똥이 잘 나오지 않음, 배가 아픔","예방법: 채소 많이 먹기, 물 충분히 마시기, 운동하기","2모둠 호흡기관 — 감기","증상: 기침, 콧물, 코 막힘","예방법: 손 씻기"],"title":"모둠별 질병 조사 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#1','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',1,'mc','auto','질병을 예방하기 위해 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X48','SC5-1-u4-X42']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C35","difficulty":1,"kind":"mc","stem":"질병을 예방하기 위해 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"건강한 생활 방식을 실천한다","correct":true},{"t":"값비싼 장치를 사서 몸에 차고 다닌다","mis":"SC5-1-u4-X48"},{"t":"아플 때까지 기다렸다가 병원에 간다","mis":"SC5-1-u4-X42"},{"t":"운이 좋기를 바란다","mis":"SC5-1-u4-X42"}],"explanation":["예방은 미리 하는 일이에요.","생활 방식이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#2','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',1,'ox','auto','점검표에는 실천이 가능한 내용을 넣어요.',ARRAY['SC5-1-u4-X46']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C35","difficulty":1,"kind":"ox","stem":"점검표에는 실천이 가능한 내용을 넣어요.","answer":"O","reason_options":[{"t":"실천할 수 있어야 꾸준히 지킬 수 있기 때문에","correct":true},{"t":"어렵고 대단한 목표일수록 좋은 점검표이기 때문에","mis":"SC5-1-u4-X46"}],"mis":"SC5-1-u4-X46","explanation":["점검표를 만드는 까닭이에요.","실천하려고 만들어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#3','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',1,'sa','auto','「몸에 착용하는 장치는 손목시계, 반지, 목걸이, □□ 등의 모양입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C36","difficulty":1,"kind":"sa","stem":"「몸에 착용하는 장치는 손목시계, 반지, 목걸이, □□ 등의 모양입니다.」 □□에 알맞은 말을 쓰세요.","answer":["패치"],"explanation":["피부에 붙이는 것이에요.","두 글자예요.","패치예요."],"mis":"SC5-1-u4-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#4','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',1,'mc','auto','착용형 장치로 측정할 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X49']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C36","difficulty":1,"kind":"mc","stem":"착용형 장치로 측정할 수 있는 것은 어느 것인가요?","options":[{"t":"체온, 심장박동 수, 혈액에 들어 있는 산소의 양","correct":true},{"t":"뼈의 개수와 이름","mis":"SC5-1-u4-X49"},{"t":"오늘 먹은 음식의 맛","mis":"SC5-1-u4-X49"},{"t":"어젯밤에 꾼 꿈의 내용","mis":"SC5-1-u4-X49"}],"explanation":["몸의 수치예요.","7차시에 잰 것과 비슷해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#5','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',2,'match','auto','점검표 활동 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"match","stem":"점검표 활동 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"계획하기","r":"점검표에 넣을 내용을 정하고 만들 방법을 계획한다"},{"l":"해 보기","r":"점검표를 만들어 소개하고 일정한 기간 동안 실천한다"},{"l":"나누기","r":"실천한 결과를 되돌아보며 느낀 점을 발표한다"},{"l":"활동이 끝난 뒤","r":"건강한 생활 방식을 꾸준히 실천한다"}],"mis":"SC5-1-u4-X47","explanation":["단계를 떠올려요.","계획, 실천, 되돌아보기예요.","끝난 뒤에도 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#6','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',2,'mc','auto','친구가 만든 점검표 초안에서 넣기 알맞은 것끼리 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"mc","stem":"친구가 만든 점검표 초안에서 넣기 알맞은 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"①, ②","correct":true},{"t":"③, ④","mis":"SC5-1-u4-X46"},{"t":"①, ③","mis":"SC5-1-u4-X46"},{"t":"②, ④","mis":"SC5-1-u4-X46"}],"explanation":["날마다 할 수 있나요?","③과 ④는 지키기 어려워요.","①, ②예요."],"asset":{"type":"passage","lines":["① 자기 전에 손을 씻었나요?","② 물을 충분히 마셨나요?","③ 하루에 열 시간씩 운동했나요?","④ 한 달 동안 한 번도 아프지 않았나요?"],"title":"친구가 만든 점검표 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#7','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',2,'mc','auto','착용형 장치의 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"mc","stem":"착용형 장치의 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"병원에 가지 않고도 건강 상태를 실시간으로 확인할 수 있다","correct":true},{"t":"크고 무거워서 집에서만 쓸 수 있다","mis":"SC5-1-u4-X49"},{"t":"병원에서만 쓸 수 있다","mis":"SC5-1-u4-X49"},{"t":"장치가 나 대신 건강한 생활 방식을 실천해 준다","mis":"SC5-1-u4-X48"}],"explanation":["몸에 차고 다녀요.","언제 어디서나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#8','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C36',2,'error','auto','착용형 장치에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X48','SC5-1-u4-X49']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"error","stem":"착용형 장치에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은호 — 「장치가 알려 주니까 이제 손 씻기는 안 해도 돼.」","correct":true,"mis_target":"SC5-1-u4-X48"},{"t":"시아 — 「측정한 수치는 건강을 관리하는 자료로 쓸 수 있어.」","mis":"SC5-1-u4-X49"},{"t":"도하 — 「몸속 기관에 문제가 생기면 경고 신호가 울려.」","mis":"SC5-1-u4-X49"}],"explanation":["실천은 누가 하나요?","나 자신이에요.","은호가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#9','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',2,'blank','auto','「자기 전에 하루를 되돌아보며 건강한 생활 방식을 (    )했는지 점검합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"blank","stem":"「자기 전에 하루를 되돌아보며 건강한 생활 방식을 (    )했는지 점검합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"실천","correct":true},{"t":"포기","mis":"SC5-1-u4-X47"},{"t":"계산","mis":"SC5-1-u4-X47"},{"t":"구입","mis":"SC5-1-u4-X48"}],"explanation":["점검표의 목적이에요.","직접 해 보는 것이에요.","실천이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_basic#10','sci',5,1,'u4','L09','g5_1_sci_u4_L09_basic','lesson_basic','SC5-1-u4-C35',3,'mc','auto','점검표 활동이 끝난 뒤에 해야 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":10,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"점검표 활동이 끝난 뒤에 해야 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"건강한 생활 방식을 꾸준히 실천한다","correct":true},{"t":"한 번 만들어 보았으니 실천하지 않는다","mis":"SC5-1-u4-X47"},{"t":"점검표를 버리고 잊는다","mis":"SC5-1-u4-X47"},{"t":"장치를 사서 실천을 맡긴다","mis":"SC5-1-u4-X48"}],"explanation":["활동이 끝나도 건강은 계속이에요.","꾸준히요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#1','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',2,'mc','auto','점검표 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X47']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"mc","stem":"점검표 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉤ → ㉠ → ㉢ → ㉣","correct":true},{"t":"㉤ → ㉡ → ㉢ → ㉠ → ㉣","mis":"SC5-1-u4-X47"},{"t":"㉡ → ㉠ → ㉤ → ㉣ → ㉢","mis":"SC5-1-u4-X47"},{"t":"㉠ → ㉢ → ㉡ → ㉤ → ㉣","mis":"SC5-1-u4-X47"}],"explanation":["질병부터 골라요.","정하고, 만들고, 실천해요.","느낀 점은 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 모둠별로 건강한 생활 방식 점검표를 만들어 소개한다.","㉡ 질병 하나를 골라 예방할 수 있는 방법을 이야기한다.","㉢ 점검표를 일정한 기간 동안 실천한다.","㉣ 실천한 결과를 되돌아보며 느낀 점을 발표한다.","㉤ 점검표에 넣을 내용을 정하고 만들 방법을 계획한다."],"title":"점검표 활동(차례가 섞여 있음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#2','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',2,'sa','auto','「몸에 착용하는 장치는 □□□□기술의 발달로 쓸 수 있게 되었습니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"sa","stem":"「몸에 착용하는 장치는 □□□□기술의 발달로 쓸 수 있게 되었습니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["생명공학"],"explanation":["생명과 기술을 이어요.","네 글자예요.","생명공학이에요."],"mis":"SC5-1-u4-X49"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#3','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',3,'mc','auto','친구가 만든 점검표 초안의 ③을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":3,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"친구가 만든 점검표 초안의 ③을 바르게 고친 것은 어느 것인가요?","options":[{"t":"「하루에 한 번 이상 몸을 움직이는 운동을 했나요?」","correct":true},{"t":"「하루에 스무 시간씩 운동했나요?」","mis":"SC5-1-u4-X46"},{"t":"「운동은 빼고 장치만 차고 다녔나요?」","mis":"SC5-1-u4-X48"},{"t":"「고칠 필요가 없다」","mis":"SC5-1-u4-X46"}],"explanation":["지킬 수 있게 고쳐요.","날마다 할 수 있는 만큼이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 자기 전에 손을 씻었나요?","② 물을 충분히 마셨나요?","③ 하루에 열 시간씩 운동했나요?","④ 한 달 동안 한 번도 아프지 않았나요?"],"title":"친구가 만든 점검표 초안"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#4','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',3,'ox','auto','착용형 장치가 있으면 건강한 생활 방식을 실천하지 않아도 돼요.',ARRAY['SC5-1-u4-X48']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C36","difficulty":3,"kind":"ox","stem":"착용형 장치가 있으면 건강한 생활 방식을 실천하지 않아도 돼요.","answer":"X","reason_options":[{"t":"장치는 몸의 수치를 재어 알려 줄 뿐이고 실천하는 것은 나 자신이기 때문에","correct":true},{"t":"장치가 질병을 모두 막아 주기 때문에","mis":"SC5-1-u4-X48"}],"mis":"SC5-1-u4-X48","explanation":["장치가 하는 일을 떠올려요.","재고 알려 줘요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#5','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',3,'mc','auto','착용형 장치로 측정한 수치를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X49']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C36","difficulty":3,"kind":"mc","stem":"착용형 장치로 측정한 수치를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"건강을 관리하기 위한 자료로 활용한다","correct":true},{"t":"어디에도 활용할 수 없다","mis":"SC5-1-u4-X49"},{"t":"장치를 꾸미는 데에만 쓴다","mis":"SC5-1-u4-X49"},{"t":"병원에 가야만 볼 수 있다","mis":"SC5-1-u4-X49"}],"explanation":["수치가 무엇을 알려 주나요?","건강 상태예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#6','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',3,'error','auto','점검표를 만들며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X45','SC5-1-u4-X47']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"error","stem":"점검표를 만들며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"로아 — 「스마트 기기로 관심 있는 다른 영상까지 마음껏 찾아봤어.」","correct":true,"mis_target":"SC5-1-u4-X45"},{"t":"하진 — 「다른 모둠 점검표와 우리 점검표를 견주어 봤어.」","mis":"SC5-1-u4-X47"},{"t":"서후 — 「다른 모둠 발표를 듣고 잘한 점을 칭찬했어.」","mis":"SC5-1-u4-X47"}],"explanation":["스마트 기기 약속이에요.","필요한 정보만 검색해요.","로아가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#7','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',3,'mc','auto','점검표를 그림으로 그리면 좋은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"점검표를 그림으로 그리면 좋은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"생활 방식이 잘 보여 한눈에 들어오기 때문에","correct":true},{"t":"어려운 목표를 더 많이 넣을 수 있기 때문에","mis":"SC5-1-u4-X46"},{"t":"그림이 있으면 실천하지 않아도 되기 때문에","mis":"SC5-1-u4-X47"},{"t":"그림이 있어야 장치가 알아보기 때문에","mis":"SC5-1-u4-X48"}],"explanation":["보기 좋게 만들어요.","한눈에 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#8','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C36',4,'mc','auto','건강을 지키는 장치를 새로 만든다면, 배운 좋은 점을 가장 잘 살린 생각은 어느 것인가요?',ARRAY['SC5-1-u4-X49']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C36","difficulty":4,"kind":"mc","stem":"건강을 지키는 장치를 새로 만든다면, 배운 좋은 점을 가장 잘 살린 생각은 어느 것인가요?","options":[{"t":"목에 거는 작은 장치로 숨 쉬는 빠르기를 재어, 갑자기 달라지면 알려 준다","correct":true},{"t":"아주 크고 무거워서 집에 두고만 써야 하는 장치","mis":"SC5-1-u4-X49"},{"t":"몸의 어떤 것도 재지 않고 모양만 예쁜 장치","mis":"SC5-1-u4-X49"},{"t":"문제가 생겨도 아무 신호도 보내지 않는 장치","mis":"SC5-1-u4-X49"}],"explanation":["작고, 재고, 알려 줘요.","세 가지를 모두 갖춰요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#9','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',4,'mc','auto','감기에 자주 걸리는 친구가 점검표에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C35","difficulty":4,"kind":"mc","stem":"감기에 자주 걸리는 친구가 점검표에 넣을 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「밖에서 돌아오면 손을 씻었나요?」","correct":true},{"t":"「한 달 동안 감기에 한 번도 걸리지 않았나요?」","mis":"SC5-1-u4-X46"},{"t":"「하루에 열 시간씩 운동했나요?」","mis":"SC5-1-u4-X46"},{"t":"「장치를 하루 종일 차고 있었나요?」","mis":"SC5-1-u4-X48"}],"explanation":["감기의 예방법을 떠올려요.","날마다 할 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_L09_challenge#10','sci',5,1,'u4','L09','g5_1_sci_u4_L09_challenge','lesson_challenge','SC5-1-u4-C35',4,'essay','teacher','건강한 생활 방식 점검표에 넣을 내용 세 가지를 실천할 수 있게 쓰고, 활동이 끝난 뒤의 다짐을 쓰세요. 그리고 착용형 장치와 내가 할 일을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C35","difficulty":4,"kind":"essay","stem":"건강한 생활 방식 점검표에 넣을 내용 세 가지를 실천할 수 있게 쓰고, 활동이 끝난 뒤의 다짐을 쓰세요. 그리고 착용형 장치와 내가 할 일을 견주어 쓰세요.","answer_guide":{"answer":"예: 점검표에 「밖에서 돌아오면 손을 씻었나요?」, 「물을 충분히 마셨나요?」, 「채소 반찬을 먹었나요?」를 넣겠다. 자기 전에 하루를 되돌아보며 점검하고, 활동이 끝난 뒤에도 꾸준히 실천하겠다. 착용형 장치는 체온이나 심장박동 수를 재어 알려 주지만, 건강한 생활 방식을 실천하는 것은 나 자신이다.","scoring_points":["실천할 수 있는 내용 세 가지를 썼는가","꾸준히 실천하겠다는 다짐을 썼는가","장치는 알려 주고 실천은 내가 한다고 썼는가"]},"explanation":["날마다 할 수 있는 것이에요.","끝난 뒤에도요.","장치와 나를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#1','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C5',1,'mc','auto','등 한가운데에 있는 뼈는 어느 것인가요?',ARRAY['SC5-1-u4-X05']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C5","difficulty":1,"kind":"mc","stem":"등 한가운데에 있는 뼈는 어느 것인가요?","options":[{"t":"척추뼈","correct":true},{"t":"머리뼈","mis":"SC5-1-u4-X05"},{"t":"갈비뼈","mis":"SC5-1-u4-X05"},{"t":"다리뼈","mis":"SC5-1-u4-X05"}],"explanation":["등을 만져 봐요.","한가운데 길게 이어져요.","척추뼈예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#2','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',1,'ox','auto','근육은 줄어들거나 늘어나면서 뼈를 움직여요.',ARRAY['SC5-1-u4-X03']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C7","difficulty":1,"kind":"ox","stem":"근육은 줄어들거나 늘어나면서 뼈를 움직여요.","answer":"O","reason_options":[{"t":"근육은 뼈에 연결되어 있어 줄어들거나 늘어나며 뼈를 움직이기 때문에","correct":true},{"t":"뼈가 스스로 움직이고 근육은 따라만 가기 때문에","mis":"SC5-1-u4-X03"}],"mis":"SC5-1-u4-X03","explanation":["뼈와 근육 모형을 떠올려요.","근육이 움직여요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#3','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C8',1,'sa','auto','튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C8","difficulty":1,"kind":"sa","stem":"튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰세요.","answer":["올라갔다","올라갔다.","올라간다","올라감","올라가","위로 올라갔다"],"explanation":["팔이 구부러지는 쪽이에요.","아래팔뼈가 위로 가요.","올라갔다예요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"},"mis":"SC5-1-u4-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#4','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C24',1,'mc','auto','노폐물에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X31']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"mc","stem":"노폐물에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에서 영양소가 쓰이면서 생긴, 몸에 필요 없는 것","correct":true},{"t":"몸에 꼭 필요한 영양소","mis":"SC5-1-u4-X31"},{"t":"먹은 음식물에서만 곧바로 생기는 것","mis":"SC5-1-u4-X31"},{"t":"숨을 쉴 때 들이마시는 산소","mis":"SC5-1-u4-X31"}],"explanation":["필요 없는 것이에요.","영양소가 쓰일 때 생겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#5','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C4',1,'blank','auto','「심장, 폐, 뇌처럼 우리가 살아가는 데 필요한 일을 하는 몸속 부분을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X04']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C4","difficulty":1,"kind":"blank","stem":"「심장, 폐, 뇌처럼 우리가 살아가는 데 필요한 일을 하는 몸속 부분을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"기관","correct":true},{"t":"골격","mis":"SC5-1-u4-X04"},{"t":"근육","mis":"SC5-1-u4-X04"},{"t":"도안","mis":"SC5-1-u4-X04"}],"explanation":["몸속에서 일을 해요.","두 글자예요.","기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#6','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C1',1,'mc','auto','튼튼반 일지 ①의 인체 골격 모형으로 달리는 몸동작을 만들 수 있었던 까닭은 어느 것인가요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C1","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ①의 인체 골격 모형으로 달리는 몸동작을 만들 수 있었던 까닭은 어느 것인가요?","options":[{"t":"여러 뼈를 이은 곳이 접혔다 펴지기 때문에","correct":true},{"t":"뼈가 커다란 하나로 되어 있기 때문에","mis":"SC5-1-u4-X01"},{"t":"뼈가 스스로 늘어나기 때문에","mis":"SC5-1-u4-X03"},{"t":"뼈가 몸의 겉을 감싸고 있기 때문에","mis":"SC5-1-u4-X01"}],"explanation":["똑딱단추로 이은 곳이에요.","접혔다 펴져요.","첫 번째예요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#7','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C29',1,'mc','auto','튼튼반 일지 ⑥에서 체온이 가장 높았던 때는 언제인가요?',ARRAY['SC5-1-u4-X37','SC5-1-u4-X38']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ⑥에서 체온이 가장 높았던 때는 언제인가요?","options":[{"t":"제자리 뛰기 직후","correct":true},{"t":"운동 전","mis":"SC5-1-u4-X37"},{"t":"5분 휴식 후","mis":"SC5-1-u4-X38"},{"t":"세 번 모두 같다","mis":"SC5-1-u4-X37"}],"explanation":["세 체온을 견줘요.","36.8 °C예요.","운동 직후예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#8','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C2',1,'mc','auto','인체 골격 모형에서 똑딱단추가 하는 일은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C2","difficulty":1,"kind":"mc","stem":"인체 골격 모형에서 똑딱단추가 하는 일은 어느 것인가요?","options":[{"t":"뼈 도안과 뼈 도안을 이어 준다","correct":true},{"t":"몸속 모습을 그려 준다","mis":"SC5-1-u4-X02"},{"t":"모형을 예쁘게 꾸민다","mis":"SC5-1-u4-X02"},{"t":"뼈 모양을 본떠 준다","mis":"SC5-1-u4-X02"}],"explanation":["잇는 도구예요.","도안과 도안 사이예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#9','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C12',2,'mc','auto','튼튼반 일지 ②에서 영양소와 대부분의 수분을 흡수한 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X11','SC5-1-u4-X12']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ②에서 영양소와 대부분의 수분을 흡수한 기관은 어느 것인가요?","options":[{"t":"작은창자","correct":true},{"t":"위","mis":"SC5-1-u4-X11"},{"t":"큰창자","mis":"SC5-1-u4-X11"},{"t":"식도","mis":"SC5-1-u4-X12"}],"explanation":["㉠ 자리예요.","위와 큰창자 사이예요.","작은창자예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#10','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C29',2,'sa','auto','튼튼반 일지 ⑥에서 제자리 뛰기 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C29","difficulty":2,"kind":"sa","stem":"튼튼반 일지 ⑥에서 제자리 뛰기 직후 1분 동안의 맥박 수는 몇 회인지 쓰세요.","answer":["104","104회"],"explanation":["둘째 줄을 읽어요.","백 회가 넘어요.","104회예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"},"mis":"SC5-1-u4-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#11','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C13',2,'ox','auto','간은 음식물이 직접 지나가는 소화기관이에요.',ARRAY['SC5-1-u4-X13']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C13","difficulty":2,"kind":"ox","stem":"간은 음식물이 직접 지나가는 소화기관이에요.","answer":"X","reason_options":[{"t":"간·쓸개·이자는 음식물이 지나가지 않고 소화를 돕기 때문에","correct":true},{"t":"음식물이 위에서 간으로 내려가기 때문에","mis":"SC5-1-u4-X13"}],"mis":"SC5-1-u4-X13","explanation":["튼튼반 일지 ②를 떠올려요.","구멍을 내지 않았어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#12','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C6',2,'mc','auto','머리뼈가 보호하는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X05','SC5-1-u4-X06']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C6","difficulty":2,"kind":"mc","stem":"머리뼈가 보호하는 기관은 어느 것인가요?","options":[{"t":"뇌","correct":true},{"t":"심장","mis":"SC5-1-u4-X05"},{"t":"폐","mis":"SC5-1-u4-X05"},{"t":"머리뼈는 아무것도 보호하지 않는다","mis":"SC5-1-u4-X06"}],"explanation":["머리 안에 있어요.","생각하는 기관이에요.","뇌예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#13','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C31',2,'match','auto','운동할 때 일어나는 일과 그 일을 하는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C31","difficulty":2,"kind":"match","stem":"운동할 때 일어나는 일과 그 일을 하는 것을 알맞게 이으세요.","pairs":[{"l":"뼈와 근육","r":"산소와 영양소를 이용해 몸을 움직인다"},{"l":"호흡기관","r":"산소를 많이 받아들이려고 호흡이 빨라진다"},{"l":"순환기관","r":"산소와 영양소를 빠르게 운반하려고 심장이 빨리 뛴다"}],"mis":"SC5-1-u4-X40","explanation":["누가 쓰고 누가 대나요?","받아들이고 운반해요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#14','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C8',2,'mc','auto','튼튼반 일지 ①에서 손잡이를 밀 때 아래팔뼈 도안은 어떻게 되었을까요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03','SC5-1-u4-X07']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C8","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ①에서 손잡이를 밀 때 아래팔뼈 도안은 어떻게 되었을까요?","options":[{"t":"바깥쪽 근육 도안이 줄어들며 따라 내려갔다","correct":true},{"t":"안쪽 근육 도안이 줄어들며 더 올라갔다","mis":"SC5-1-u4-X08"},{"t":"근육과 관계없이 스스로 늘어났다","mis":"SC5-1-u4-X03"},{"t":"안쪽 근육 도안이 밀어 내렸다","mis":"SC5-1-u4-X07"}],"explanation":["마지막 줄을 읽어요.","팔이 펴져요.","첫 번째예요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#15','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C16',2,'error','auto','심장에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X20','SC5-1-u4-X17']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C16","difficulty":2,"kind":"error","stem":"심장에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수빈 — 「심장은 배 아래쪽 한가운데에 있어.」","correct":true,"mis_target":"SC5-1-u4-X20"},{"t":"지원 — 「심장은 가슴 중앙에서 왼쪽으로 약간 치우쳐 있어.」","mis":"SC5-1-u4-X20"},{"t":"태경 — 「심장은 펌프 작용으로 혈액을 보내.」","mis":"SC5-1-u4-X17"}],"explanation":["가슴에 손을 대 봐요.","가슴이에요.","수빈이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#16','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',2,'mc','auto','인체 골격 모형에는 없고 내 몸에는 있어서, 내 몸이 스스로 움직일 수 있게 하는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02','SC5-1-u4-X04']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C7","difficulty":2,"kind":"mc","stem":"인체 골격 모형에는 없고 내 몸에는 있어서, 내 몸이 스스로 움직일 수 있게 하는 것은 어느 것인가요?","options":[{"t":"근육","correct":true},{"t":"똑딱단추","mis":"SC5-1-u4-X02"},{"t":"뼈 도안","mis":"SC5-1-u4-X02"},{"t":"그림 도구","mis":"SC5-1-u4-X04"}],"explanation":["모형은 손으로 움직였어요.","뼈에 연결된 것이에요.","근육이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#17','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',3,'mc','auto','튼튼반 일지 ⑧에서 하람의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X07','SC5-1-u4-X03','SC5-1-u4-X08']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C7","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 하람의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「근육은 밀지 못해. 바깥쪽 근육이 줄어들면서 팔이 펴지는 거야.」","correct":true},{"t":"「맞아, 근육이 뼈를 밀어.」","mis":"SC5-1-u4-X07"},{"t":"「근육과 관계없이 뼈가 스스로 펴져.」","mis":"SC5-1-u4-X03"},{"t":"「안쪽 근육이 줄어들어서 팔이 펴져.」","mis":"SC5-1-u4-X08"}],"explanation":["근육이 하는 일이에요.","줄어들며 당겨요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#18','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C32',3,'mc','auto','튼튼반 일지 ⑧에서 지우의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 지우의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「질병은 우리 몸의 기관과 관련이 있고, 생활 습관으로 예방에 도움을 줄 수 있어.」","correct":true},{"t":"「맞아, 운이 나빠서야.」","mis":"SC5-1-u4-X42"},{"t":"「예방은 어른만 할 수 있어.」","mis":"SC5-1-u4-X43"},{"t":"「질병은 약으로만 막을 수 있어.」","mis":"SC5-1-u4-X43"}],"explanation":["일지 ⑦을 떠올려요.","예방법이 있었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#19','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C22',3,'ox','auto','숨을 들이마실 때와 내쉴 때 공기는 같은 길을 반대 방향으로 지나요.',ARRAY['SC5-1-u4-X26']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C22","difficulty":3,"kind":"ox","stem":"숨을 들이마실 때와 내쉴 때 공기는 같은 길을 반대 방향으로 지나요.","answer":"O","reason_options":[{"t":"들이마실 때는 코에서 폐로 들어가고 내쉴 때는 폐에서 코로 나가기 때문에","correct":true},{"t":"내쉴 때는 식도를 따라 나가기 때문에","mis":"SC5-1-u4-X26"}],"mis":"SC5-1-u4-X26","explanation":["튼튼반 일지 ④를 떠올려요.","거꾸로예요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#20','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C25',3,'mc','auto','튼튼반 일지 ⑤를 보고 콩팥을 지난 두 갈래를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X33','SC5-1-u4-X34']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C25","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑤를 보고 콩팥을 지난 두 갈래를 바르게 말한 것은 어느 것인가요?","options":[{"t":"노폐물은 오줌이 되어 몸 밖으로 나가고, 걸러진 혈액은 다시 온몸을 순환한다","correct":true},{"t":"걸러진 혈액도 오줌과 함께 몸 밖으로 나간다","mis":"SC5-1-u4-X33"},{"t":"오줌이 혈관을 따라 다시 온몸을 돈다","mis":"SC5-1-u4-X34"},{"t":"걸러진 혈액은 방광에 모였다가 나간다","mis":"SC5-1-u4-X33"}],"explanation":["두 갈래예요.","오줌과 혈액이 갈라져요.","첫 번째예요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#21','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C6',3,'mc','auto','갈비뼈가 없다면 어떤 문제가 생길까요?',ARRAY['SC5-1-u4-X06','SC5-1-u4-X05']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C6","difficulty":3,"kind":"mc","stem":"갈비뼈가 없다면 어떤 문제가 생길까요?","options":[{"t":"가슴 속의 심장과 폐를 보호하기 어려워진다","correct":true},{"t":"아무 문제도 생기지 않는다","mis":"SC5-1-u4-X06"},{"t":"머리 속의 뇌를 보호하기 어려워진다","mis":"SC5-1-u4-X05"},{"t":"음식물이 소화되지 않는다","mis":"SC5-1-u4-X06"}],"explanation":["갈비뼈가 둘러싼 곳이에요.","가슴 속이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#22','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C29',3,'mc','auto','튼튼반 일지 ⑥에서 운동 직후 땀이 난 것과 함께 일어난 변화로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X37','SC5-1-u4-X40']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C29","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑥에서 운동 직후 땀이 난 것과 함께 일어난 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"체온이 올라가고 맥박 수가 많아졌다","correct":true},{"t":"체온이 내려가고 맥박 수가 적어졌다","mis":"SC5-1-u4-X37"},{"t":"소화기관이 하던 일을 멈추었다","mis":"SC5-1-u4-X40"},{"t":"아무 변화가 없었다","mis":"SC5-1-u4-X37"}],"explanation":["운동 전과 견줘요.","모두 높아졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#23','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C30',4,'mc','auto','운동 직후 숨을 크게 몰아쉬는 친구를 보고 가장 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X28','SC5-1-u4-X27']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"mc","stem":"운동 직후 숨을 크게 몰아쉬는 친구를 보고 가장 바르게 설명한 것은 어느 것인가요?","options":[{"t":"근육이 산소를 많이 쓰므로, 산소를 많이 받아들이려고 호흡이 빨라진 것이다","correct":true},{"t":"그냥 몸이 힘들어서 그런 것일 뿐이다","mis":"SC5-1-u4-X39"},{"t":"이산화 탄소를 많이 받아들이려고 그런 것이다","mis":"SC5-1-u4-X28"},{"t":"폐에서 영양소를 흡수하려고 그런 것이다","mis":"SC5-1-u4-X27"}],"explanation":["근육에 필요한 것이에요.","산소를 많이 받아들여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#24','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C7',4,'essay','teacher','튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰고, 손잡이를 밀 때 아래팔뼈 도안이 어떻게 되는지 쓰세요. 그리고 일지 ⑧의 하람이 생각을 바로잡아 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C7","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ①의 ( ㉠ )에 알맞은 말을 쓰고, 손잡이를 밀 때 아래팔뼈 도안이 어떻게 되는지 쓰세요. 그리고 일지 ⑧의 하람이 생각을 바로잡아 쓰세요.","answer_guide":{"answer":"예: ( ㉠ )에는 「올라갔다」가 들어간다. 손잡이를 밀면 바깥쪽 근육 도안이 줄어들고 안쪽 근육 도안이 늘어나면서 아래팔뼈 도안이 따라 내려간다. 하람아, 근육은 뼈를 밀지 못해. 근육은 뼈에 연결되어 있어서 줄어들거나 늘어나면서 뼈를 움직이고, 팔을 펼 때는 바깥쪽 근육이 줄어드는 거야.","scoring_points":["㉠에 올라갔다를 썼는가","밀 때 바깥쪽 근육이 줄어들어 내려간다고 썼는가","근육은 밀지 않는다고 하람의 생각을 바로잡았는가"]},"explanation":["㉠부터 써요.","밀 때는 반대예요.","하람에게 말해 줘요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_a#25','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C26',4,'essay','teacher','튼튼반 일지 ⑤의 ( ? )에 들어갈 내용을 쓰고, 오줌이 몸 밖으로 나가는 길을 쓰세요. 그리고 일지 ⑧의 서아에게 배설과 배출의 차이를 설명해 주세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C26","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ⑤의 ( ? )에 들어갈 내용을 쓰고, 오줌이 몸 밖으로 나가는 길을 쓰세요. 그리고 일지 ⑧의 서아에게 배설과 배출의 차이를 설명해 주세요.","answer_guide":{"answer":"예: ( ? )에는 「오줌을 모아 두었다가 몸 밖으로 내보낸다」가 들어간다. 콩팥에서 만든 오줌은 오줌관을 지나 방광에 모였다가 몸 밖으로 나간다. 서아야, 배설은 혈액 속의 노폐물을 콩팥이 걸러 오줌으로 내보내는 것이고, 똥을 누는 것은 소화되고 남은 음식물 찌꺼기를 내보내는 배출이야.","scoring_points":["방광이 하는 일을 썼는가","콩팥 → 오줌관 → 방광의 길을 썼는가","배설과 배출을 구별해 서아에게 설명했는가"]},"explanation":["방광부터 써요.","오줌을 따라가요.","서아에게 말해 줘요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#1','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C13',1,'mc','auto','튼튼반 일지 ②에서 구멍을 내지 않은 간, 쓸개, 이자가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X13','SC5-1-u4-X26']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C13","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ②에서 구멍을 내지 않은 간, 쓸개, 이자가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 지나가지는 않지만 소화를 돕는다","correct":true},{"t":"음식물이 지나가는 통로이다","mis":"SC5-1-u4-X13"},{"t":"소화와 관계없는 일을 한다","mis":"SC5-1-u4-X13"},{"t":"공기가 지나가는 통로이다","mis":"SC5-1-u4-X26"}],"explanation":["구멍을 내지 않은 까닭이에요.","지나가지 않아요.","첫 번째예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#2','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C11',1,'ox','auto','음식물 찌꺼기는 항문을 통해 몸 밖으로 나가요.',ARRAY['SC5-1-u4-X14']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C11","difficulty":1,"kind":"ox","stem":"음식물 찌꺼기는 항문을 통해 몸 밖으로 나가요.","answer":"O","reason_options":[{"t":"큰창자에서 수분이 흡수되고 남은 찌꺼기가 배출되기 때문에","correct":true},{"t":"찌꺼기는 몸속에 그대로 쌓이기 때문에","mis":"SC5-1-u4-X14"}],"mis":"SC5-1-u4-X14","explanation":["소화 경로의 끝이에요.","항문이에요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#3','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C12',1,'sa','auto','튼튼반 일지 ②의 ( ㉠ )에 알맞은 기관의 이름을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C12","difficulty":1,"kind":"sa","stem":"튼튼반 일지 ②의 ( ㉠ )에 알맞은 기관의 이름을 쓰세요.","answer":["작은창자"],"explanation":["위 다음이에요.","영양소를 흡수해요.","작은창자예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"},"mis":"SC5-1-u4-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#4','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C21',1,'mc','auto','폐가 받아들인 산소가 쓰이는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X27','SC5-1-u4-X09']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C21","difficulty":1,"kind":"mc","stem":"폐가 받아들인 산소가 쓰이는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸을 움직이거나 몸속 기관이 일하는 데","correct":true},{"t":"아무 데도 쓰이지 않는다","mis":"SC5-1-u4-X27"},{"t":"음식물을 크게 뭉치는 데","mis":"SC5-1-u4-X09"},{"t":"오줌을 모아 두는 데","mis":"SC5-1-u4-X27"}],"explanation":["산소는 몸에 필요해요.","움직이고 일하는 데예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#5','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C10',1,'blank','auto','「음식물을 잘게 쪼개 영양소를 흡수할 수 있게 하는 일을 담당하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X24','SC5-1-u4-X30']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C10","difficulty":1,"kind":"blank","stem":"「음식물을 잘게 쪼개 영양소를 흡수할 수 있게 하는 일을 담당하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"소화기관","correct":true},{"t":"순환기관","mis":"SC5-1-u4-X22"},{"t":"호흡기관","mis":"SC5-1-u4-X24"},{"t":"배설기관","mis":"SC5-1-u4-X30"}],"explanation":["잘게 쪼개요.","소화를 담당해요.","소화기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#6','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C14',1,'mc','auto','음식물을 꼭꼭 씹으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X15','SC5-1-u4-X11']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C14","difficulty":1,"kind":"mc","stem":"음식물을 꼭꼭 씹으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"잘게 쪼개지고 물러져 소화가 잘된다","correct":true},{"t":"더 빨리 먹을 수 있다","mis":"SC5-1-u4-X15"},{"t":"음식물이 더 커진다","mis":"SC5-1-u4-X15"},{"t":"흡수가 입에서 모두 끝난다","mis":"SC5-1-u4-X11"}],"explanation":["입이 하는 일이에요.","잘게 부수어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#7','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C32',1,'mc','auto','튼튼반 일지 ⑦에서 1모둠이 조사한 변비와 관련 있는 기관은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C32","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ⑦에서 1모둠이 조사한 변비와 관련 있는 기관은 어느 것인가요?","options":[{"t":"소화기관","correct":true},{"t":"호흡기관","mis":"SC5-1-u4-X44"},{"t":"배설기관","mis":"SC5-1-u4-X44"},{"t":"어느 기관과도 관련이 없다","mis":"SC5-1-u4-X42"}],"explanation":["1모둠 줄을 읽어요.","똥과 관련 있어요.","소화기관이에요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#8','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C9',1,'mc','auto','튼튼반 일지 ①에서 손잡이를 잡아당길 때 줄어든 것은 어느 것인가요?',ARRAY['SC5-1-u4-X08','SC5-1-u4-X03','SC5-1-u4-X02']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C9","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ①에서 손잡이를 잡아당길 때 줄어든 것은 어느 것인가요?","options":[{"t":"안쪽 근육 도안","correct":true},{"t":"바깥쪽 근육 도안","mis":"SC5-1-u4-X08"},{"t":"아래팔뼈 도안","mis":"SC5-1-u4-X03"},{"t":"똑딱단추","mis":"SC5-1-u4-X02"}],"explanation":["둘째 줄을 읽어요.","안쪽이에요.","안쪽 근육 도안이에요."],"asset":{"type":"passage","lines":["인체 골격 모형 — 똑딱단추 13개로 이어 달리는 몸동작을 만들었다.","뼈와 근육 모형 — 손잡이를 잡아당기자 안쪽 근육 도안이 줄어들었다.","손잡이를 잡아당기자 아래팔뼈 도안이 따라 ( ㉠ ).","손잡이를 밀자 바깥쪽 근육 도안이 줄어들었다."],"title":"튼튼반 탐구 일지 ① 뼈와 근육"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#9','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C18',2,'mc','auto','튼튼반 일지 ③에서 붉은 색소 물이 호스를 따라 돈 것은 우리 몸의 무엇을 나타내나요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C18","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ③에서 붉은 색소 물이 호스를 따라 돈 것은 우리 몸의 무엇을 나타내나요?","options":[{"t":"혈액이 혈관을 따라 온몸을 도는 혈액 순환","correct":true},{"t":"공기가 숨관을 지나는 호흡","mis":"SC5-1-u4-X22"},{"t":"음식물이 식도를 지나는 소화","mis":"SC5-1-u4-X22"},{"t":"오줌이 오줌관을 지나는 배설","mis":"SC5-1-u4-X22"}],"explanation":["붉은 색소 물은 혈액이에요.","호스는 혈관이에요.","혈액 순환이에요."],"asset":{"type":"passage","lines":["펌프, 호스, 붉은 색소 물로 순환기관 모형실험을 했다.","펌프를 쥐었다 폈다 하자 붉은 색소 물이 호스를 따라 돌았다.","펌프를 멈추자 붉은 색소 물도 멈추었다.","실험이 끝난 뒤 주변을 정리하고 물을 올바르게 처리했다."],"title":"튼튼반 탐구 일지 ③ 순환기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#10','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C22',2,'sa','auto','「숨을 내쉴 때 공기는 폐에서 나와 가장 먼저 □□□□를 지납니다.」 □□□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C22","difficulty":2,"kind":"sa","stem":"「숨을 내쉴 때 공기는 폐에서 나와 가장 먼저 □□□□를 지납니다.」 □□□□에 알맞은 말을 쓰세요.","answer":["숨관가지"],"explanation":["폐와 숨관 사이예요.","네 글자예요.","숨관가지예요."],"mis":"SC5-1-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#11','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C17',2,'ox','auto','혈관은 심장 가까이에만 있어요.',ARRAY['SC5-1-u4-X18']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C17","difficulty":2,"kind":"ox","stem":"혈관은 심장 가까이에만 있어요.","answer":"X","reason_options":[{"t":"혈관은 머리끝부터 발끝까지 온몸에 퍼져 있기 때문에","correct":true},{"t":"혈액은 심장 주변에서만 돌기 때문에","mis":"SC5-1-u4-X18"}],"mis":"SC5-1-u4-X18","explanation":["손끝에도 피가 나요.","온몸이에요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#12','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C14',2,'mc','auto','소화 과정 모형에서 막대를 천천히 내리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X16','SC5-1-u4-X13']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C14","difficulty":2,"kind":"mc","stem":"소화 과정 모형에서 막대를 천천히 내리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식물이 거치는 소화기관과 음식물의 모습을 차례대로 관찰하려고","correct":true},{"t":"활동을 빨리 끝내려고","mis":"SC5-1-u4-X16"},{"t":"막대를 도안에 고정하려고","mis":"SC5-1-u4-X16"},{"t":"간 자리의 구멍을 보려고","mis":"SC5-1-u4-X13"}],"explanation":["구멍으로 무엇을 보나요?","차례대로 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#13','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C12',2,'match','auto','음식물의 모습과 그 모습이 나타나는 기관을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C12","difficulty":2,"kind":"match","stem":"음식물의 모습과 그 모습이 나타나는 기관을 알맞게 이으세요.","pairs":[{"l":"이로 부서지고 침과 섞인다","r":"입"},{"l":"소화를 돕는 액체와 섞여 잘게 쪼개진다","r":"위"},{"l":"영양소와 대부분의 수분이 흡수된다","r":"작은창자"},{"l":"찌꺼기의 수분이 흡수된다","r":"큰창자"}],"mis":"SC5-1-u4-X12","explanation":["막대를 내리며 본 것이에요.","위에서 아래로요.","네 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#14','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C11',2,'mc','auto','튼튼반 일지 ②를 보고 음식물이 지나간 길을 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u4-X10','SC5-1-u4-X13','SC5-1-u4-X26']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C11","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ②를 보고 음식물이 지나간 길을 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"입 → 식도 → 위 → 작은창자 → 큰창자 → 항문","correct":true},{"t":"입 → 식도 → 위 → 큰창자 → 작은창자 → 항문","mis":"SC5-1-u4-X10"},{"t":"입 → 식도 → 간 → 위 → 작은창자 → 항문","mis":"SC5-1-u4-X13"},{"t":"입 → 숨관 → 위 → 작은창자 → 큰창자 → 항문","mis":"SC5-1-u4-X26"}],"explanation":["일지 첫 줄을 읽어요.","㉠은 작은창자예요.","첫 번째예요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#15','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C24',2,'error','auto','노폐물에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X31','SC5-1-u4-X32']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C24","difficulty":2,"kind":"error","stem":"노폐물에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"한결 — 「노폐물은 먹은 음식물에서만 곧바로 생겨.」","correct":true,"mis_target":"SC5-1-u4-X31"},{"t":"보민 — 「영양소가 쓰이면서 노폐물이 생겨.」","mis":"SC5-1-u4-X31"},{"t":"찬희 — 「혈액 속 노폐물은 콩팥이 걸러 내.」","mis":"SC5-1-u4-X32"}],"explanation":["노폐물이 생기는 때예요.","영양소가 쓰일 때예요.","한결이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#16','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C10',2,'mc','auto','소화에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X09','SC5-1-u4-X22','SC5-1-u4-X30']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C10","difficulty":2,"kind":"mc","stem":"소화에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"영양소를 흡수할 수 있도록 음식물을 잘게 쪼개는 과정","correct":true},{"t":"음식물을 크게 뭉치는 과정","mis":"SC5-1-u4-X09"},{"t":"혈액을 온몸으로 보내는 과정","mis":"SC5-1-u4-X22"},{"t":"혈액 속의 노폐물을 걸러 내는 과정","mis":"SC5-1-u4-X30"}],"explanation":["잘게 쪼개요.","흡수하려고요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#17','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C16',3,'mc','auto','튼튼반 일지 ⑧에서 도윤의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X19']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C16","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 도윤의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「심장은 혈액을 만들지 않고, 펌프 작용으로 온몸에 보내.」","correct":true},{"t":"「맞아, 심장이 혈액을 만들어.」","mis":"SC5-1-u4-X17"},{"t":"「혈관이 혈액을 만들어 내.」","mis":"SC5-1-u4-X17"},{"t":"「혈액은 한 번 돌고 없어져.」","mis":"SC5-1-u4-X19"}],"explanation":["모형의 펌프예요.","보내는 일이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#18','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C36',3,'mc','auto','튼튼반 일지 ⑧에서 다온의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X48','SC5-1-u4-X49']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C36","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 다온의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「장치는 몸의 수치를 재어 알려 줄 뿐이고, 실천하는 것은 나 자신이야.」","correct":true},{"t":"「맞아, 장치가 다 해 줘.」","mis":"SC5-1-u4-X48"},{"t":"「장치가 질병을 모두 막아 줘.」","mis":"SC5-1-u4-X48"},{"t":"「장치는 아무것도 재지 못해.」","mis":"SC5-1-u4-X49"}],"explanation":["장치가 하는 일이에요.","재고 알려 줘요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#19','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C33',3,'ox','auto','질병 예방은 어른만 할 수 있는 일이에요.',ARRAY['SC5-1-u4-X43']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C33","difficulty":3,"kind":"ox","stem":"질병 예방은 어른만 할 수 있는 일이에요.","answer":"X","reason_options":[{"t":"손 씻기, 채소 먹기처럼 어린이도 날마다 할 수 있는 일이 예방에 도움이 되기 때문에","correct":true},{"t":"예방은 병원에서 어른이 해 주는 것이기 때문에","mis":"SC5-1-u4-X43"}],"mis":"SC5-1-u4-X43","explanation":["일지 ⑦의 점검표를 떠올려요.","우리도 할 수 있어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#20','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C21',3,'mc','auto','혈액이 온몸에 운반하는 산소와 영양소는 각각 어느 기관에서 받아들이나요?',ARRAY['SC5-1-u4-X27','SC5-1-u4-X17','SC5-1-u4-X26']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C21","difficulty":3,"kind":"mc","stem":"혈액이 온몸에 운반하는 산소와 영양소는 각각 어느 기관에서 받아들이나요?","options":[{"t":"산소는 폐, 영양소는 작은창자","correct":true},{"t":"산소는 작은창자, 영양소는 폐","mis":"SC5-1-u4-X27"},{"t":"둘 다 심장이 만들어 낸다","mis":"SC5-1-u4-X17"},{"t":"산소는 식도, 영양소는 숨관","mis":"SC5-1-u4-X26"}],"explanation":["호흡과 소화를 떠올려요.","폐와 작은창자예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#21','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C19',3,'mc','auto','순환기관 모형실험에서 펌프를 쥐었다 폈다 하는 것은 우리 몸의 무엇을 나타내나요?',ARRAY['SC5-1-u4-X21','SC5-1-u4-X17','SC5-1-u4-X22']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C19","difficulty":3,"kind":"mc","stem":"순환기관 모형실험에서 펌프를 쥐었다 폈다 하는 것은 우리 몸의 무엇을 나타내나요?","options":[{"t":"심장의 펌프 작용","correct":true},{"t":"혈관이 늘어났다 줄어드는 것","mis":"SC5-1-u4-X21"},{"t":"혈액이 새로 만들어지는 것","mis":"SC5-1-u4-X17"},{"t":"숨을 들이마시고 내쉬는 것","mis":"SC5-1-u4-X22"}],"explanation":["펌프는 심장이에요.","혈액을 보내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#22','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C35',3,'mc','auto','점검표를 일정한 기간 동안 실천한 뒤 「나누기」에서 할 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X47','SC5-1-u4-X48']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C35","difficulty":3,"kind":"mc","stem":"점검표를 일정한 기간 동안 실천한 뒤 「나누기」에서 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"실천한 결과를 되돌아보며 느낀 점을 발표하고 잘한 점을 칭찬한다","correct":true},{"t":"점검표를 버리고 실천을 그만둔다","mis":"SC5-1-u4-X47"},{"t":"실천하지 못한 날은 지우고 다 했다고 적는다","mis":"SC5-1-u4-X47"},{"t":"장치가 잰 수치만 발표한다","mis":"SC5-1-u4-X48"}],"explanation":["되돌아보는 단계예요.","느낀 점과 칭찬이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#23','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C25',4,'mc','auto','노폐물이 많은 혈액이 콩팥으로 들어가 오줌이 몸 밖으로 나가기까지를 차례대로 바르게 나타낸 것은 어느 것인가요?',ARRAY['SC5-1-u4-X34','SC5-1-u4-X30']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C25","difficulty":4,"kind":"mc","stem":"노폐물이 많은 혈액이 콩팥으로 들어가 오줌이 몸 밖으로 나가기까지를 차례대로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"혈관 → 콩팥 → 오줌관 → 방광 → 몸 밖","correct":true},{"t":"혈관 → 방광 → 오줌관 → 콩팥 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"혈관 → 콩팥 → 방광 → 오줌관 → 몸 밖","mis":"SC5-1-u4-X34"},{"t":"혈관 → 큰창자 → 항문 → 몸 밖","mis":"SC5-1-u4-X30"}],"explanation":["콩팥에서 오줌이 만들어져요.","통로를 지나 모여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#24','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C11',4,'essay','teacher','튼튼반 일지 ②를 보고 음식물이 지나가는 길을 끝까지 쓰고, 영양소와 수분이 흡수되는 곳을 쓰세요. 그리고 간, 쓸개, 이자 자리에 구멍을 내지 않은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C11","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ②를 보고 음식물이 지나가는 길을 끝까지 쓰고, 영양소와 수분이 흡수되는 곳을 쓰세요. 그리고 간, 쓸개, 이자 자리에 구멍을 내지 않은 까닭을 쓰세요.","answer_guide":{"answer":"예: 음식물은 입 → 식도 → 위 → 작은창자 → 큰창자를 지나 남은 찌꺼기가 항문으로 나간다. 영양소와 대부분의 수분은 작은창자에서, 찌꺼기에 남은 수분은 큰창자에서 흡수된다. 간, 쓸개, 이자는 음식물이 지나가지 않고 소화를 돕는 기관이라서 음식물이 지나가는 자리에 내는 구멍을 내지 않았다.","scoring_points":["소화 경로를 항문까지 썼는가","작은창자·큰창자의 흡수를 썼는가","간·쓸개·이자는 지나가지 않고 돕는다고 썼는가"]},"explanation":["일지 첫 줄부터예요.","흡수하는 곳을 나눠요.","구멍을 내지 않은 까닭이에요."],"asset":{"type":"passage","lines":["막대를 내리며 본 기관 — 입 → 식도 → 위 → ( ㉠ ) → 큰창자","㉠에서 영양소와 대부분의 수분이 흡수되었다.","큰창자에서 찌꺼기의 수분이 흡수되었다.","남은 찌꺼기는 항문으로 나갔다.","간·쓸개·이자 자리에는 구멍을 내지 않았다."],"title":"튼튼반 탐구 일지 ② 소화 과정 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_b#25','sci',5,1,'u4','','g5_1_sci_u4_review_b','unit_review','SC5-1-u4-C30',4,'essay','teacher','튼튼반 일지 ⑥의 세 값이 어떻게 달라졌는지 쓰고, 일지 ⑧의 민호 생각을 여러 기관과 관련지어 바로잡아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C30","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ⑥의 세 값이 어떻게 달라졌는지 쓰고, 일지 ⑧의 민호 생각을 여러 기관과 관련지어 바로잡아 쓰세요.","answer_guide":{"answer":"예: 운동 전 36.4 °C, 74회였던 체온과 맥박 수가 제자리 뛰기 직후에는 36.8 °C, 104회로 높아졌고, 5분 휴식 후에는 36.6 °C, 86회로 차츰 운동 전으로 돌아갔다. 민호야, 심장이 빨리 뛰는 건 그냥 힘들어서가 아니야. 근육이 움직이려면 산소와 영양소가 필요해서, 호흡기관은 산소를 많이 받아들이려고 호흡이 빨라지고 순환기관은 산소와 영양소를 빠르게 운반하려고 심장이 빨리 뛰는 거야.","scoring_points":["직후에 높아지고 휴식 후 돌아간다고 썼는가","산소와 영양소가 필요하다는 까닭을 썼는가","호흡기관과 순환기관을 이어 민호를 바로잡았는가"]},"explanation":["세 줄을 견줘요.","근육에 필요한 것이에요.","민호에게 말해 줘요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#1','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C16',1,'mc','auto','심장이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X17','SC5-1-u4-X22','SC5-1-u4-X32']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C16","difficulty":1,"kind":"mc","stem":"심장이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"펌프 작용으로 혈액을 온몸으로 보낸다","correct":true},{"t":"혈액을 새로 만들어 낸다","mis":"SC5-1-u4-X17"},{"t":"음식물 속의 영양소를 흡수한다","mis":"SC5-1-u4-X22"},{"t":"혈액 속의 노폐물을 걸러 낸다","mis":"SC5-1-u4-X32"}],"explanation":["모형의 펌프예요.","보내요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#2','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C25',1,'ox','auto','콩팥은 혈액 속의 노폐물을 걸러 내어 오줌을 만들어요.',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C25","difficulty":1,"kind":"ox","stem":"콩팥은 혈액 속의 노폐물을 걸러 내어 오줌을 만들어요.","answer":"O","reason_options":[{"t":"배설기관 가운데 노폐물을 걸러 내는 기관이기 때문에","correct":true},{"t":"오줌은 방광에서 새로 만들어지기 때문에","mis":"SC5-1-u4-X32"}],"mis":"SC5-1-u4-X32","explanation":["생각 그물을 떠올려요.","콩팥이 만들어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#3','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C19',1,'sa','auto','순환기관 모형실험에서 우리 몸의 혈관과 같은 역할을 하는 것은 무엇인지 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C19","difficulty":1,"kind":"sa","stem":"순환기관 모형실험에서 우리 몸의 혈관과 같은 역할을 하는 것은 무엇인지 쓰세요.","answer":["호스"],"explanation":["혈액이 지나가는 통로예요.","길쭉한 관이에요.","호스예요."],"mis":"SC5-1-u4-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#4','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C33',1,'mc','auto','튼튼반 일지 ⑦에서 감기의 예방법으로 적은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X44','SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C33","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ⑦에서 감기의 예방법으로 적은 것은 어느 것인가요?","options":[{"t":"손 씻기","correct":true},{"t":"채소 많이 먹기","mis":"SC5-1-u4-X44"},{"t":"운이 좋기를 바라기","mis":"SC5-1-u4-X42"},{"t":"약만 먹기","mis":"SC5-1-u4-X43"}],"explanation":["2모둠 줄을 읽어요.","손이에요.","손 씻기예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#5','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C15',1,'blank','auto','「심장과 혈관처럼 혈액이 온몸을 돌게 하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X22']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C15","difficulty":1,"kind":"blank","stem":"「심장과 혈관처럼 혈액이 온몸을 돌게 하는 기관을 (    )(이)라고 합니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"순환기관","correct":true},{"t":"소화기관","mis":"SC5-1-u4-X22"},{"t":"호흡기관","mis":"SC5-1-u4-X22"},{"t":"배설기관","mis":"SC5-1-u4-X22"}],"explanation":["혈액이 돌아요.","순환이에요.","순환기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#6','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C17',1,'mc','auto','혈관에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X18','SC5-1-u4-X24','SC5-1-u4-X17']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C17","difficulty":1,"kind":"mc","stem":"혈관에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"혈액이 이동하는 통로로 온몸에 퍼져 있다","correct":true},{"t":"심장 가까이에만 있다","mis":"SC5-1-u4-X18"},{"t":"공기가 이동하는 통로이다","mis":"SC5-1-u4-X24"},{"t":"혈액을 새로 만들어 낸다","mis":"SC5-1-u4-X17"}],"explanation":["모형의 호스예요.","온몸에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#7','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C35',1,'mc','auto','건강한 생활 방식 점검표에 넣기 알맞은 내용은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C35","difficulty":1,"kind":"mc","stem":"건강한 생활 방식 점검표에 넣기 알맞은 내용은 어느 것인가요?","options":[{"t":"「물을 충분히 마셨나요?」","correct":true},{"t":"「한 달 동안 한 번도 아프지 않았나요?」","mis":"SC5-1-u4-X46"},{"t":"「하루에 열 시간씩 공부와 운동을 했나요?」","mis":"SC5-1-u4-X46"},{"t":"「건강 장치를 새로 샀나요?」","mis":"SC5-1-u4-X48"}],"explanation":["날마다 할 수 있나요?","실천할 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#8','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C23',1,'mc','auto','튼튼반 일지 ④에서 어지러움을 느낀 친구가 활동을 멈춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C23","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ④에서 어지러움을 느낀 친구가 활동을 멈춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"무리하지 않고 어지럼증을 느끼면 활동을 멈추어야 하기 때문에","correct":true},{"t":"봉투가 다 부풀었기 때문에","mis":"SC5-1-u4-X29"},{"t":"숨이 찰 때까지 불어야 했기 때문에","mis":"SC5-1-u4-X29"},{"t":"셀로판테이프가 떨어졌기 때문에","mis":"SC5-1-u4-X29"}],"explanation":["안전 약속이에요.","어지러우면 멈춰요.","첫 번째예요."],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#9','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C25',2,'mc','auto','튼튼반 일지 ⑤의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X32']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑤의 ( ? )에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"오줌을 모아 두었다가 몸 밖으로 내보낸다","correct":true},{"t":"혈액 속의 노폐물을 걸러 내어 오줌을 만든다","mis":"SC5-1-u4-X32"},{"t":"오줌이 이동하는 통로이다","mis":"SC5-1-u4-X32"},{"t":"혈액을 온몸으로 보낸다","mis":"SC5-1-u4-X32"}],"explanation":["방광이 하는 일이에요.","모아 두어요.","첫 번째예요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#10','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C5',2,'sa','auto','「가슴을 둘러싸 심장과 폐를 보호하는 뼈는 □□뼈입니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C5","difficulty":2,"kind":"sa","stem":"「가슴을 둘러싸 심장과 폐를 보호하는 뼈는 □□뼈입니다.」 □□에 알맞은 말을 쓰세요.","answer":["갈비","갈비뼈"],"explanation":["가슴의 뼈예요.","두 글자예요.","갈비뼈예요."],"mis":"SC5-1-u4-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#11','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C26',2,'ox','auto','똥을 누는 것도 배설이에요.',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C26","difficulty":2,"kind":"ox","stem":"똥을 누는 것도 배설이에요.","answer":"X","reason_options":[{"t":"배설은 혈액 속 노폐물을 걸러 내보내는 것이고 똥을 누는 것은 배출이기 때문에","correct":true},{"t":"몸 밖으로 내보내는 것은 모두 배설이기 때문에","mis":"SC5-1-u4-X30"}],"mis":"SC5-1-u4-X30","explanation":["배설과 배출을 견줘요.","똥은 배출이에요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#12','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C19',2,'mc','auto','튼튼반 일지 ③에서 펌프를 멈추자 붉은 색소 물도 멈춘 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-1-u4-X21','SC5-1-u4-X23']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C19","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ③에서 펌프를 멈추자 붉은 색소 물도 멈춘 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"심장이 펌프 작용을 해야 혈액이 온몸을 돈다","correct":true},{"t":"혈관이 스스로 혈액을 밀어 보낸다","mis":"SC5-1-u4-X21"},{"t":"혈액은 심장 없이도 계속 돈다","mis":"SC5-1-u4-X21"},{"t":"심장이 멈추면 혈액이 더 빨리 돈다","mis":"SC5-1-u4-X23"}],"explanation":["펌프는 심장이에요.","멈추면 돌지 못해요.","첫 번째예요."],"asset":{"type":"passage","lines":["펌프, 호스, 붉은 색소 물로 순환기관 모형실험을 했다.","펌프를 쥐었다 폈다 하자 붉은 색소 물이 호스를 따라 돌았다.","펌프를 멈추자 붉은 색소 물도 멈추었다.","실험이 끝난 뒤 주변을 정리하고 물을 올바르게 처리했다."],"title":"튼튼반 탐구 일지 ③ 순환기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#13','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C32',2,'match','auto','질병과 관련 있는 기관을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C32","difficulty":2,"kind":"match","stem":"질병과 관련 있는 기관을 알맞게 이으세요.","pairs":[{"l":"감기","r":"호흡기관"},{"l":"변비","r":"소화기관"},{"l":"『실험관찰』이 예로 든 빈혈","r":"순환기관"}],"mis":"SC5-1-u4-X44","explanation":["증상을 떠올려요.","기침, 똥, 혈액이에요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#14','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C21',2,'mc','auto','튼튼반 일지 ④에서 숨을 들이마실 때 공기가 폐에 이르기 바로 전에 지나는 곳은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X26']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C21","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ④에서 숨을 들이마실 때 공기가 폐에 이르기 바로 전에 지나는 곳은 어느 것인가요?","options":[{"t":"숨관가지","correct":true},{"t":"숨관","mis":"SC5-1-u4-X24"},{"t":"코","mis":"SC5-1-u4-X24"},{"t":"식도","mis":"SC5-1-u4-X26"}],"explanation":["폐 바로 앞이에요.","숨관과 폐를 이어요.","숨관가지예요."],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#15','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C34',2,'error','auto','질병을 조사하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C34","difficulty":2,"kind":"error","stem":"질병을 조사하며 친구들이 한 일을 말했어요. 알맞지 않게 한 친구는 누구인가요?","options":[{"t":"규리 — 「검색 결과 맨 위의 자료 하나만 그대로 옮겨 적었어.」","correct":true,"mis_target":"SC5-1-u4-X45"},{"t":"동하 — 「검색어가 포함된 자료를 골라 썼어.」","mis":"SC5-1-u4-X45"},{"t":"세빈 — 「만든 자료를 공유 플랫폼에 올렸어.」","mis":"SC5-1-u4-X45"}],"explanation":["자료가 많을 때예요.","골라서 써요.","규리가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#16','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C35',2,'mc','auto','튼튼반 일지 ⑦의 하은이 점검표 초안을 바르게 고친 것은 어느 것인가요?',ARRAY['SC5-1-u4-X46','SC5-1-u4-X48']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C35","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑦의 하은이 점검표 초안을 바르게 고친 것은 어느 것인가요?","options":[{"t":"「하루에 한 번 이상 몸을 움직였나요?」","correct":true},{"t":"「하루에 열다섯 시간씩 운동했나요?」","mis":"SC5-1-u4-X46"},{"t":"「운동 대신 장치를 차고 있었나요?」","mis":"SC5-1-u4-X48"},{"t":"「고칠 필요가 없다」","mis":"SC5-1-u4-X46"}],"explanation":["지킬 수 있게 고쳐요.","날마다 할 만큼이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#17','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C26',3,'mc','auto','튼튼반 일지 ⑧에서 서아의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C26","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 서아의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「배설은 콩팥이 혈액 속 노폐물을 걸러 오줌으로 내보내는 거야.」","correct":true},{"t":"「맞아, 똥 누기가 배설이야.」","mis":"SC5-1-u4-X30"},{"t":"「배설은 숨을 내쉬는 거야.」","mis":"SC5-1-u4-X30"},{"t":"「배설과 배출은 같은 말이야.」","mis":"SC5-1-u4-X30"}],"explanation":["일지 ⑤를 떠올려요.","콩팥이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#18','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C31',3,'mc','auto','아침밥을 먹고 학교에서 달리기를 할 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X40','SC5-1-u4-X37']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C31","difficulty":3,"kind":"mc","stem":"아침밥을 먹고 학교에서 달리기를 할 때 우리 몸에서 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"소화기관은 음식물을 소화하고, 호흡과 심장박동이 빨라지며, 배설기관도 노폐물을 걸러 낸다","correct":true},{"t":"달리기하는 동안 소화기관은 하던 일을 멈춘다","mis":"SC5-1-u4-X40"},{"t":"뼈와 근육만 일하고 다른 기관은 쉰다","mis":"SC5-1-u4-X40"},{"t":"호흡이 느려지고 심장이 느리게 뛴다","mis":"SC5-1-u4-X37"}],"explanation":["쉬는 기관이 있나요?","모두 일해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#19','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C9',3,'ox','auto','뼈와 근육 모형은 도안을 풀로 단단히 붙여 움직이지 않게 만들어요.',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C9","difficulty":3,"kind":"ox","stem":"뼈와 근육 모형은 도안을 풀로 단단히 붙여 움직이지 않게 만들어요.","answer":"X","reason_options":[{"t":"똑딱단추로 이어야 손잡이를 움직일 때 근육 도안과 아래팔뼈 도안이 움직이기 때문에","correct":true},{"t":"단단히 붙일수록 변화가 잘 보이기 때문에","mis":"SC5-1-u4-X02"}],"mis":"SC5-1-u4-X02","explanation":["손잡이를 움직여야 해요.","똑딱단추로 이어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#20','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C12',3,'mc','auto','「흡수는 위에서 다 끝나.」라고 말하는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X11','SC5-1-u4-X14']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C12","difficulty":3,"kind":"mc","stem":"「흡수는 위에서 다 끝나.」라고 말하는 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「영양소와 대부분의 수분은 작은창자에서, 찌꺼기의 수분은 큰창자에서 흡수돼.」","correct":true},{"t":"「맞아, 위가 다 흡수해.」","mis":"SC5-1-u4-X11"},{"t":"「흡수는 입에서 다 끝나.」","mis":"SC5-1-u4-X11"},{"t":"「음식물은 흡수되지 않고 모두 나가.」","mis":"SC5-1-u4-X14"}],"explanation":["튼튼반 일지 ②를 떠올려요.","창자에서 흡수해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#21','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C34',3,'mc','auto','튼튼반 일지 ⑦의 조사 자료를 다른 모둠과 나누는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C34","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑦의 조사 자료를 다른 모둠과 나누는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"공유 플랫폼에 올리고 알게 된 점을 댓글로 나눈다","correct":true},{"t":"우리 모둠만 보고 나누지 않는다","mis":"SC5-1-u4-X45"},{"t":"다른 모둠 자료를 베껴 우리 것처럼 올린다","mis":"SC5-1-u4-X45"},{"t":"자료 없이 기억나는 대로만 말한다","mis":"SC5-1-u4-X45"}],"explanation":["함께 나누어요.","올리고 댓글을 달아요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#22','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C20',3,'mc','auto','공기의 길과 음식물의 길을 바르게 견준 것은 어느 것인가요?',ARRAY['SC5-1-u4-X26']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C20","difficulty":3,"kind":"mc","stem":"공기의 길과 음식물의 길을 바르게 견준 것은 어느 것인가요?","options":[{"t":"공기는 코 → 숨관 → 숨관가지 → 폐로, 음식물은 입 → 식도 → 위로 간다","correct":true},{"t":"공기와 음식물 모두 숨관을 지난다","mis":"SC5-1-u4-X26"},{"t":"공기와 음식물 모두 식도를 지난다","mis":"SC5-1-u4-X26"},{"t":"공기는 식도를 지나 위로 간다","mis":"SC5-1-u4-X26"}],"explanation":["두 길은 달라요.","숨관과 식도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#23','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C31',4,'mc','auto','먹은 음식물의 영양소가 달리기하는 다리 근육에 쓰이기까지, 기관이 일하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X22','SC5-1-u4-X27','SC5-1-u4-X40']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"mc","stem":"먹은 음식물의 영양소가 달리기하는 다리 근육에 쓰이기까지, 기관이 일하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"소화기관이 흡수한다 → 순환기관이 운반한다 → 근육이 쓴다","correct":true},{"t":"순환기관이 흡수한다 → 소화기관이 운반한다 → 근육이 쓴다","mis":"SC5-1-u4-X22"},{"t":"호흡기관이 흡수한다 → 배설기관이 운반한다 → 근육이 쓴다","mis":"SC5-1-u4-X27"},{"t":"근육이 음식물을 바로 흡수해 쓴다","mis":"SC5-1-u4-X40"}],"explanation":["흡수, 운반, 쓰기예요.","소화기관부터예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#24','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C18',4,'essay','teacher','튼튼반 일지 ③의 모형실험에서 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 펌프를 멈추자 물도 멈춘 것을 우리 몸과 관련지어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C18","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ③의 모형실험에서 펌프, 호스, 붉은 색소 물이 우리 몸의 무엇과 같은지 쓰고, 펌프를 멈추자 물도 멈춘 것을 우리 몸과 관련지어 쓰세요.","answer_guide":{"answer":"예: 펌프는 심장, 호스는 혈관, 붉은 색소 물은 혈액과 같다. 펌프를 멈추자 물이 멈춘 것처럼, 심장이 펌프 작용을 멈추면 혈액이 순환하지 못해 영양소와 산소를 온몸에 운반할 수 없다. 그래서 심장박동이 멈추면 빠른 시간 안에 심폐 소생술을 해야 한다.","scoring_points":["세 가지를 바르게 짝지었는가","심장이 멈추면 혈액이 순환하지 못한다고 썼는가","영양소와 산소를 운반하지 못한다고 이었는가"]},"explanation":["짝부터 지어요.","멈추면 어떻게 될까요?","우리 몸과 이어요."],"asset":{"type":"passage","lines":["펌프, 호스, 붉은 색소 물로 순환기관 모형실험을 했다.","펌프를 쥐었다 폈다 하자 붉은 색소 물이 호스를 따라 돌았다.","펌프를 멈추자 붉은 색소 물도 멈추었다.","실험이 끝난 뒤 주변을 정리하고 물을 올바르게 처리했다."],"title":"튼튼반 탐구 일지 ③ 순환기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_c#25','sci',5,1,'u4','','g5_1_sci_u4_review_c','unit_review','SC5-1-u4-C33',4,'essay','teacher','튼튼반 일지 ⑦을 보고 두 질병과 관련 있는 기관과 예방법을 쓰고, 하은이의 점검표 초안을 실천할 수 있게 고쳐 쓰세요. 그리고 일지 ⑧의 지우에게 해 줄 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C33","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ⑦을 보고 두 질병과 관련 있는 기관과 예방법을 쓰고, 하은이의 점검표 초안을 실천할 수 있게 고쳐 쓰세요. 그리고 일지 ⑧의 지우에게 해 줄 말을 쓰세요.","answer_guide":{"answer":"예: 변비는 소화기관과 관련이 있고 채소를 많이 먹고 물을 충분히 마시며 운동하면 예방에 도움이 된다. 감기는 호흡기관과 관련이 있고 손 씻기로 예방에 도움을 줄 수 있다. 하은이의 초안은 「하루에 한 번 이상 몸을 움직였나요?」처럼 날마다 실천할 수 있게 고친다. 지우야, 질병은 운이 나빠서 걸리는 것이 아니라 몸의 기관과 관련이 있고, 우리가 날마다 실천하는 생활 습관으로 예방에 도움을 줄 수 있어.","scoring_points":["두 질병의 기관과 예방법을 썼는가","점검표를 실천할 수 있게 고쳤는가","생활 습관으로 예방할 수 있다고 지우를 바로잡았는가"]},"explanation":["두 모둠을 읽어요.","점검표를 고쳐요.","지우에게 말해 줘요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#1','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C20',1,'mc','auto','숨관이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X24','SC5-1-u4-X26']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C20","difficulty":1,"kind":"mc","stem":"숨관이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"공기가 이동하는 통로이다","correct":true},{"t":"산소를 받아들인다","mis":"SC5-1-u4-X24"},{"t":"음식물이 위로 이동하는 통로이다","mis":"SC5-1-u4-X26"},{"t":"오줌이 이동하는 통로이다","mis":"SC5-1-u4-X24"}],"explanation":["코와 숨관가지 사이예요.","공기가 지나가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#2','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C29',1,'ox','auto','운동 직후에는 맥박 수가 운동 전보다 적어져요.',ARRAY['SC5-1-u4-X37']::text[],false,'{"seq":2,"concept":"SC5-1-u4-C29","difficulty":1,"kind":"ox","stem":"운동 직후에는 맥박 수가 운동 전보다 적어져요.","answer":"X","reason_options":[{"t":"산소와 영양소를 빠르게 운반하려고 심장이 빠르게 뛰어 맥박 수가 많아지기 때문에","correct":true},{"t":"운동을 하면 심장이 느리게 뛰기 때문에","mis":"SC5-1-u4-X37"}],"mis":"SC5-1-u4-X37","explanation":["달리기한 뒤를 떠올려요.","두근두근 빨라요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#3','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C28',1,'sa','auto','「심장의 박동이 목이나 팔목 등에서 느껴지는 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-1-u4-C28","difficulty":1,"kind":"sa","stem":"「심장의 박동이 목이나 팔목 등에서 느껴지는 것을 □□이라고 합니다.」 □□에 알맞은 말을 쓰세요.","answer":["맥박"],"explanation":["팔목을 짚어 봐요.","두 글자예요.","맥박이에요."],"mis":"SC5-1-u4-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#4','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',1,'mc','auto','착용형 장치가 몸속 기관의 기능에 생긴 문제를 발견하면 어떻게 하나요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C36","difficulty":1,"kind":"mc","stem":"착용형 장치가 몸속 기관의 기능에 생긴 문제를 발견하면 어떻게 하나요?","options":[{"t":"경고 신호를 울려 알려 준다","correct":true},{"t":"아무것도 하지 않는다","mis":"SC5-1-u4-X49"},{"t":"장치가 스스로 병을 고친다","mis":"SC5-1-u4-X48"},{"t":"장치가 꺼져 버린다","mis":"SC5-1-u4-X49"}],"explanation":["과학이 톡톡을 떠올려요.","신호가 울려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#5','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C26',1,'blank','auto','「큰창자를 지난 음식물 찌꺼기가 항문으로 나가는 것은 배설이 아니라 (    )입니다.」 (    )에 알맞은 말은 어느 것인가요?',ARRAY['SC5-1-u4-X30']::text[],false,'{"seq":5,"concept":"SC5-1-u4-C26","difficulty":1,"kind":"blank","stem":"「큰창자를 지난 음식물 찌꺼기가 항문으로 나가는 것은 배설이 아니라 (    )입니다.」 (    )에 알맞은 말은 어느 것인가요?","options":[{"t":"배출","correct":true},{"t":"소화","mis":"SC5-1-u4-X30"},{"t":"순환","mis":"SC5-1-u4-X30"},{"t":"호흡","mis":"SC5-1-u4-X30"}],"explanation":["찌꺼기를 내보내요.","배설과 다른 말이에요.","배출이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#6','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C22',1,'mc','auto','튼튼반 일지 ④의 ( ? )에 들어갈 길로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X25','SC5-1-u4-X26']::text[],false,'{"seq":6,"concept":"SC5-1-u4-C22","difficulty":1,"kind":"mc","stem":"튼튼반 일지 ④의 ( ? )에 들어갈 길로 알맞은 것은 어느 것인가요?","options":[{"t":"폐 → 숨관가지 → 숨관 → 코","correct":true},{"t":"코 → 숨관 → 숨관가지 → 폐","mis":"SC5-1-u4-X25"},{"t":"폐 → 식도 → 입","mis":"SC5-1-u4-X26"},{"t":"코 → 숨관가지 → 숨관 → 폐","mis":"SC5-1-u4-X25"}],"explanation":["내쉴 때예요.","들이마실 때를 거꾸로 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#7','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C27',1,'mc','auto','식사할 때 함께 일하는 것끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":7,"concept":"SC5-1-u4-C27","difficulty":1,"kind":"mc","stem":"식사할 때 함께 일하는 것끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"팔뼈와 팔 근육, 얼굴 근육, 소화기관","correct":true},{"t":"소화기관 하나만","mis":"SC5-1-u4-X35"},{"t":"얼굴 근육 하나만","mis":"SC5-1-u4-X35"},{"t":"모든 기관이 쉬고 입만 움직인다","mis":"SC5-1-u4-X35"}],"explanation":["포크로 넣고 씹어요.","여러 기관이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#8','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C34',1,'mc','auto','자료를 만들다가 스마트 기기에서 냄새가 나요. 어떻게 해야 하나요?',ARRAY['SC5-1-u4-X45']::text[],false,'{"seq":8,"concept":"SC5-1-u4-C34","difficulty":1,"kind":"mc","stem":"자료를 만들다가 스마트 기기에서 냄새가 나요. 어떻게 해야 하나요?","options":[{"t":"즉시 사용을 멈추고 선생님께 알린다","correct":true},{"t":"자료를 다 만들 때까지 계속 쓴다","mis":"SC5-1-u4-X45"},{"t":"세게 흔들어 본다","mis":"SC5-1-u4-X45"},{"t":"물을 부어 식힌다","mis":"SC5-1-u4-X45"}],"explanation":["안전이 먼저예요.","멈추고 알려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#9','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C30',2,'mc','auto','튼튼반 일지 ⑥에서 운동 직후 맥박 수가 많아진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X17','SC5-1-u4-X37']::text[],false,'{"seq":9,"concept":"SC5-1-u4-C30","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑥에서 운동 직후 맥박 수가 많아진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빠르게 뛰었기 때문에","correct":true},{"t":"단지 몸이 힘들었기 때문에","mis":"SC5-1-u4-X39"},{"t":"혈액을 더 많이 만들어 내려고","mis":"SC5-1-u4-X17"},{"t":"체온을 낮추려고","mis":"SC5-1-u4-X37"}],"explanation":["근육에 필요한 것을 떠올려요.","빠르게 날라요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#10','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C33',2,'sa','auto','「변비를 예방하려면 채소를 많이 먹고, □을 충분히 마시며, 운동을 합니다.」 □에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"sa","stem":"「변비를 예방하려면 채소를 많이 먹고, □을 충분히 마시며, 운동을 합니다.」 □에 알맞은 말을 쓰세요.","answer":["물"],"explanation":["마시는 것이에요.","한 글자예요.","물이에요."],"mis":"SC5-1-u4-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#11','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C27',2,'ox','auto','잠을 자는 동안에도 우리 몸은 호흡을 해요.',ARRAY['SC5-1-u4-X35']::text[],false,'{"seq":11,"concept":"SC5-1-u4-C27","difficulty":2,"kind":"ox","stem":"잠을 자는 동안에도 우리 몸은 호흡을 해요.","answer":"O","reason_options":[{"t":"잠을 잘 때도 기관이 끊임없이 일하며 활동할 때보다 천천히 호흡하기 때문에","correct":true},{"t":"잠을 자면 호흡이 멈추었다가 깨면 다시 시작하기 때문에","mis":"SC5-1-u4-X35"}],"mis":"SC5-1-u4-X35","explanation":["자는 동안을 떠올려요.","천천히 숨을 쉬어요.","맞는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#12','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C33',2,'mc','auto','튼튼반 일지 ⑦에서 1모둠이 적은 변비의 예방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X44']::text[],false,'{"seq":12,"concept":"SC5-1-u4-C33","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑦에서 1모둠이 적은 변비의 예방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"채소 먹기, 물 마시기, 운동하기","correct":true},{"t":"손 씻기만 하기","mis":"SC5-1-u4-X44"},{"t":"하루 종일 누워서 쉬기","mis":"SC5-1-u4-X44"},{"t":"단 음식을 자주 먹기","mis":"SC5-1-u4-X44"}],"explanation":["1모둠 줄을 읽어요.","세 가지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["1모둠 소화기관 — 변비: 똥이 잘 나오지 않음 / 채소·물·운동","2모둠 호흡기관 — 감기: 기침, 콧물 / 손 씻기","우리 반 점검표 — 손 씻기, 물 충분히 마시기, 채소 반찬 먹기","하은이의 점검표 초안 — 「하루에 열 시간씩 운동했나요?」"],"title":"튼튼반 탐구 일지 ⑦ 질병 조사와 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#13','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C25',2,'match','auto','콩팥을 지난 뒤의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC5-1-u4-C25","difficulty":2,"kind":"match","stem":"콩팥을 지난 뒤의 모습을 알맞게 이으세요.","pairs":[{"l":"노폐물이 많은 혈액","r":"혈관을 따라 콩팥으로 들어온다"},{"l":"노폐물이 걸러진 혈액","r":"다시 온몸을 순환한다"},{"l":"콩팥에서 만든 오줌","r":"오줌관과 방광을 거쳐 몸 밖으로 나간다"}],"mis":"SC5-1-u4-X33","explanation":["두 갈래를 떠올려요.","혈액과 오줌이에요.","세 가지가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#14','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C28',2,'mc','auto','튼튼반 일지 ⑥처럼 체온과 맥박 수를 재는 세 번의 때로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":14,"concept":"SC5-1-u4-C28","difficulty":2,"kind":"mc","stem":"튼튼반 일지 ⑥처럼 체온과 맥박 수를 재는 세 번의 때로 알맞은 것은 어느 것인가요?","options":[{"t":"운동 전, 운동 직후, 5분 휴식 후","correct":true},{"t":"운동 전에만 세 번","mis":"SC5-1-u4-X41"},{"t":"운동 직후에만 세 번","mis":"SC5-1-u4-X41"},{"t":"운동 전, 하루 쉰 뒤, 다음 주","mis":"SC5-1-u4-X41"}],"explanation":["일지 세 줄이에요.","전, 직후, 휴식 후예요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#15','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',2,'error','auto','착용형 장치를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":15,"concept":"SC5-1-u4-C36","difficulty":2,"kind":"error","stem":"착용형 장치를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「착용형 장치는 병원에서만 쓸 수 있어.」","correct":true,"mis_target":"SC5-1-u4-X49"},{"t":"리아 — 「손목시계나 반지 모양이라 차기 쉬워.」","mis":"SC5-1-u4-X49"},{"t":"강민 — 「장치가 알려 줘도 실천은 내가 해야 해.」","mis":"SC5-1-u4-X48"}],"explanation":["언제 어디서나 쓸 수 있나요?","몸에 차고 다녀요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#16','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C23',2,'mc','auto','호흡기관 모형에서 주름 빨대와 종이봉투 사이를 셀로판테이프로 잘 막는 까닭은 어느 것인가요?',ARRAY['SC5-1-u4-X29']::text[],false,'{"seq":16,"concept":"SC5-1-u4-C23","difficulty":2,"kind":"mc","stem":"호흡기관 모형에서 주름 빨대와 종이봉투 사이를 셀로판테이프로 잘 막는 까닭은 어느 것인가요?","options":[{"t":"공기가 새지 않게 하려고","correct":true},{"t":"봉투를 더 무겁게 하려고","mis":"SC5-1-u4-X29"},{"t":"봉투가 부풀지 않게 하려고","mis":"SC5-1-u4-X29"},{"t":"빨대를 예쁘게 꾸미려고","mis":"SC5-1-u4-X29"}],"explanation":["불어 넣은 공기는요?","새면 안 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#17','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C30',3,'mc','auto','튼튼반 일지 ⑧에서 민호의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X39','SC5-1-u4-X37','SC5-1-u4-X17']::text[],false,'{"seq":17,"concept":"SC5-1-u4-C30","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 민호의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「산소와 영양소를 온몸에 빠르게 운반하려고 심장이 빨리 뛰는 거야.」","correct":true},{"t":"「맞아, 그냥 힘들어서야.」","mis":"SC5-1-u4-X39"},{"t":"「운동하면 심장이 느려져.」","mis":"SC5-1-u4-X37"},{"t":"「혈액을 더 많이 만들려고 그래.」","mis":"SC5-1-u4-X17"}],"explanation":["근육에 필요한 것이에요.","빨리 날라야 해요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#18','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C18',3,'mc','auto','작은창자에서 흡수한 영양소가 다리 근육에 닿기까지를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-1-u4-X10','SC5-1-u4-X26','SC5-1-u4-X22']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C18","difficulty":3,"kind":"mc","stem":"작은창자에서 흡수한 영양소가 다리 근육에 닿기까지를 바르게 말한 것은 어느 것인가요?","options":[{"t":"혈액이 영양소를 싣고 혈관을 따라 다리 근육까지 운반한다","correct":true},{"t":"영양소가 식도를 거쳐 다시 올라갔다가 내려간다","mis":"SC5-1-u4-X10"},{"t":"영양소가 숨관을 따라 다리로 간다","mis":"SC5-1-u4-X26"},{"t":"영양소는 작은창자에만 머문다","mis":"SC5-1-u4-X22"}],"explanation":["운반하는 것이에요.","혈액과 혈관이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#19','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C29',3,'ox','auto','운동을 마치고 5분 휴식하면 체온과 맥박 수가 운동 직후보다 더 높아져요.',ARRAY['SC5-1-u4-X38']::text[],false,'{"seq":19,"concept":"SC5-1-u4-C29","difficulty":3,"kind":"ox","stem":"운동을 마치고 5분 휴식하면 체온과 맥박 수가 운동 직후보다 더 높아져요.","answer":"X","reason_options":[{"t":"휴식하면 체온과 맥박 수가 차츰 운동 전으로 돌아가기 때문에","correct":true},{"t":"한번 오른 체온과 맥박 수는 계속 오르기 때문에","mis":"SC5-1-u4-X38"}],"mis":"SC5-1-u4-X38","explanation":["튼튼반 일지 ⑥을 떠올려요.","86회로 줄었어요.","틀린 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#20','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C26',3,'mc','auto','튼튼반 일지 ⑤에서 친구가 「똥 누기」 카드를 배설 가지에서 뗀 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X30','SC5-1-u4-X34']::text[],false,'{"seq":20,"concept":"SC5-1-u4-C26","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑤에서 친구가 「똥 누기」 카드를 배설 가지에서 뗀 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"똥을 누는 것은 음식물 찌꺼기를 내보내는 배출이기 때문에","correct":true},{"t":"똥 누기도 배설이지만 붙일 자리가 없었기 때문에","mis":"SC5-1-u4-X30"},{"t":"똥은 오줌관을 지나 나가기 때문에","mis":"SC5-1-u4-X34"},{"t":"똥은 콩팥에서 만들어지기 때문에","mis":"SC5-1-u4-X30"}],"explanation":["배설과 배출이에요.","똥은 배출이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["콩팥 — 혈액 속의 노폐물을 걸러 내어 오줌을 만든다.","오줌관 — 오줌이 이동하는 통로","방광 — ( ? )","노폐물이 걸러진 혈액 — 다시 온몸을 순환한다.","한 친구가 「똥 누기」 카드를 배설 가지에 붙였다가 떼었다."],"title":"튼튼반 탐구 일지 ⑤ 배설기관 생각 그물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#21','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C1',3,'mc','auto','몸속의 뼈가 여러 개로 이어져 있지 않고 커다란 하나라면 어떻게 될까요?',ARRAY['SC5-1-u4-X01','SC5-1-u4-X03']::text[],false,'{"seq":21,"concept":"SC5-1-u4-C1","difficulty":3,"kind":"mc","stem":"몸속의 뼈가 여러 개로 이어져 있지 않고 커다란 하나라면 어떻게 될까요?","options":[{"t":"팔과 다리를 구부리는 등 다양한 몸동작을 하기 어렵다","correct":true},{"t":"지금보다 더 다양한 몸동작을 할 수 있다","mis":"SC5-1-u4-X01"},{"t":"근육이 없어도 몸이 움직인다","mis":"SC5-1-u4-X03"},{"t":"아무 차이가 없다","mis":"SC5-1-u4-X01"}],"explanation":["골격 모형을 떠올려요.","이은 곳이 접혔어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#22','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C28',3,'mc','auto','튼튼반 일지 ⑥의 값을 그래프로 나타낼 때 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X41']::text[],false,'{"seq":22,"concept":"SC5-1-u4-C28","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑥의 값을 그래프로 나타낼 때 알맞은 것은 어느 것인가요?","options":[{"t":"운동 전, 운동 직후, 5분 휴식 후의 차례로 잰 값을 그대로 나타낸다","correct":true},{"t":"예상에 맞도록 값을 고쳐 나타낸다","mis":"SC5-1-u4-X41"},{"t":"운동 직후 값은 빼고 나타낸다","mis":"SC5-1-u4-X41"},{"t":"친구가 잰 값을 가져와 나타낸다","mis":"SC5-1-u4-X41"}],"explanation":["잰 차례대로예요.","고치지 않아요.","첫 번째예요."],"asset":{"type":"passage","lines":["운동 전 — 체온 36.4 °C, 1분 동안의 맥박 수 74회","제자리 뛰기 직후 — 체온 36.8 °C, 맥박 수 104회","5분 휴식 후 — 체온 36.6 °C, 맥박 수 86회","운동 직후 얼굴과 등에 땀이 났다.","(실제 값은 사람마다 다름)"],"title":"튼튼반 탐구 일지 ⑥ 운동 전후 측정"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#23','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',4,'mc','auto','밤사이 착용형 장치가 심장박동 수가 갑자기 달라졌다며 경고 신호를 보냈어요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C36","difficulty":4,"kind":"mc","stem":"밤사이 착용형 장치가 심장박동 수가 갑자기 달라졌다며 경고 신호를 보냈어요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"몸에 문제가 생겼을 수 있으니 어른께 알리고 몸 상태를 살핀다","correct":true},{"t":"신호를 무시하고 장치를 끈다","mis":"SC5-1-u4-X49"},{"t":"장치가 알아서 고쳐 줄 테니 그냥 둔다","mis":"SC5-1-u4-X48"},{"t":"장치를 더 예쁜 것으로 바꾼다","mis":"SC5-1-u4-X49"}],"explanation":["경고 신호의 뜻이에요.","문제가 생겼다는 신호예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#24','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C22',4,'essay','teacher','튼튼반 일지 ④의 ( ? )에 들어갈 길을 쓰고, 들이마실 때와 내쉴 때 폐가 하는 일을 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ④의 ( ? )에 들어갈 길을 쓰고, 들이마실 때와 내쉴 때 폐가 하는 일을 각각 쓰세요.","answer_guide":{"answer":"예: ( ? )에는 「폐 → 숨관가지 → 숨관 → 코」가 들어간다. 숨을 들이마시면 폐는 우리 몸에 필요한 산소를 받아들이고, 숨을 내쉬면 몸속에서 생긴 이산화 탄소를 포함한 공기를 몸 밖으로 내보낸다. 두 길은 같은 길이고 방향만 반대이다.","scoring_points":["내쉬는 길을 바르게 썼는가","들이마실 때 산소를 받아들인다고 썼는가","내쉴 때 이산화 탄소를 내보낸다고 썼는가"]},"explanation":["거꾸로 써요.","들이마실 때 폐는요?","내쉴 때 폐는요?"],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_sci_u4_review_d#25','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C31',4,'essay','teacher','「우리 몸의 구조와 기능」 단원에서 배운 것을 「뼈와 근육 → 소화·순환·호흡·배설기관 → 운동할 때 서로 영향을 주고받는 기관 → 질병과 건강한 생활」의 차례로 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"essay","stem":"「우리 몸의 구조와 기능」 단원에서 배운 것을 「뼈와 근육 → 소화·순환·호흡·배설기관 → 운동할 때 서로 영향을 주고받는 기관 → 질병과 건강한 생활」의 차례로 정리해 쓰세요.","answer_guide":{"answer":"예: 뼈는 몸의 형태를 만들고 지탱하며 몸속 기관을 보호하고, 근육이 줄어들거나 늘어나면서 뼈를 움직여 몸이 움직인다. 소화기관은 음식물을 잘게 쪼개 영양소를 흡수하고, 호흡기관은 산소를 받아들이며, 순환기관은 영양소와 산소를 온몸에 운반하고, 배설기관은 혈액 속의 노폐물을 걸러 몸 밖으로 내보낸다. 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 것처럼 각 기관은 서로 영향을 주고받으며 작용한다. 다양한 질병은 우리 몸의 기관과 관련이 있으며, 건강한 생활 방식을 꾸준히 실천하면 예방에 도움이 된다.","scoring_points":["뼈와 근육이 하는 일을 썼는가","네 기관이 하는 일을 바르게 썼는가","서로 영향을 주고받음과 질병 예방을 썼는가"]},"explanation":["뼈와 근육부터예요.","네 기관을 넣어요.","서로 영향과 건강으로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C1','soc',5,1,'u1',1,'지형의 뜻과 종류 — 다양하게 나타나는 땅의 생김새를 지형이라고 하며, 산봉우리가 길게 이어진 산지, 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기인 하천, 하천 주변에 주로 발달한 넓고 평평한 평야, 바다와 맞닿아 모래사장·갯벌이 나타나는 해안, 둘레가 바다로 둘러싸인 섬이 있음 · 우리나라는 국토의 약 70%가 산지이고 한 나라 안에 여러 지형이 어우러져 있음 · 이름을 외우기보다 특징을 견주어 이해함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C2','soc',5,1,'u1',2,'산지의 분포와 땅의 높낮이 — 지형도는 땅의 높낮이를 색으로 나타낸 지도이고 범례를 보면 색이 뜻하는 높이를 알 수 있음(색이 진할수록 높음) · 높고 험한 산지는 북쪽과 동쪽에, 낮고 완만한 산지는 남쪽과 서쪽에 많아 우리나라 땅은 북동쪽이 높고 남서쪽이 낮음 · 서쪽에서 동쪽으로 자른 단면도에서도 동쪽으로 갈수록 높아짐',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C3','soc',5,1,'u1',3,'하천의 흐름과 평야 — 물은 언제나 높은 곳에서 낮은 곳으로 흐르므로 큰 하천은 대부분 북쪽·동쪽의 높은 곳에서 시작해 남쪽·서쪽으로 흘러 바다로 감(북동쪽이 높고 남서쪽이 낮기 때문) · 하천 주변, 특히 큰 하천 하류 주변은 대부분 200 m 미만의 낮은 땅으로 넓고 평평한 평야가 발달해 논밭이 많음 · 하천은 오랜 시간 땅을 깎아 골짜기 같은 새 지형을 만들기도 함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C4','soc',5,1,'u1',4,'세 바다의 해안 — 우리나라는 동·서·남 삼면이 바다와 맞닿아 있고 바다와 육지가 만나는 선을 해안선이라고 함 · 동해안은 해안선이 단순하고 섬이 적으며 모래사장이 넓어 해수욕장이 발달 · 서해안과 남해안은 해안선이 복잡하고 섬이 많으며(남해안 다도해) 갯벌이 발달해 해산물을 얻고 간척하기도 함 · 파도가 암석을 깎아 해안 절벽과 동굴을 만들기도 함 — 해안 모습이 다르면 사람들의 생활도 다름',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C5','soc',5,1,'u1',5,'지형이 만든 경관과 보전 — 독특하고 아름다운 지형은 관광지가 됨(산지 — 바위 봉우리와 폭포의 산·고원 목장, 하천 — 두 물줄기가 합쳐지는 강가·지평선이 보이는 평야·깊은 계곡·하천이 깎은 한반도 모양 지형, 해안 — 갯벌·해수욕장·습지·해안 절벽) · 세계 지질 공원은 지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 쓰려고 국제기구가 인증하는 곳(우리나라 처음은 제주) · 지질 공원 해설사는 지질·지형·자연·역사를 엮어 알기 쉽게 설명하고 훼손되지 않게 관리함 — 보고 배우되 그대로 둠',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C6','soc',5,1,'u1',5,'국토 여행 계획 세우기 — 주제 정하기(무엇을 보고 싶은지와 까닭) → 여행 정보 누리집 등으로 여행지 조사하기(디지털 영상 지도로 모습 확인) → 지도에 여행지를 표시하고 일정 순서대로 화살표로 이어 경로 나타내기(한 지역만 갈 때는 그 지역 백지도, 동선이 너무 길지 않게) → 공유 애플리케이션으로 나누고 예절 있게 댓글 쓰기',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C7','soc',5,1,'u1',7,'독도의 위치와 중요성 — 독도는 우리나라 영토의 동쪽 끝, 동해에 있는 섬으로 행정구역은 경상북도 울릉군이고 울릉도에서 87.4 km 떨어져 맑은 날 울릉도에서 보임(예로부터 우리 영토로 인식) · 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통·군사 면에서 중요하며, 연구 가치가 크고 주변 바다에 자원이 풍부함 · 공항이 없어 동해안 항구에서 배를 타고 울릉도를 거쳐 감',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C8','soc',5,1,'u1',8,'독도의 자연환경 — 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌고 오래전 바닷속 화산 활동으로 만들어져 독특한 지형이 많음(바위 이름은 닮은 모습에서) · 대체로 온화하나 안개가 자주 끼고 흐린 날이 많으며 겨울에 눈이 많음 · 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이루고 해양 심층수(수심 200 m 아래, 영양분 많음)와 가스 하이드레이트(불타는 얼음)가 있어 경제적 가치가 큼 · 자연환경과 생태계를 보호하려고 독도 전체를 천연기념물로 지정',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C9','soc',5,1,'u1',9,'독도에 관한 옛 지도와 기록 — 우리나라 자료: 신라 장군 이사부가 우산국을 정벌한 일, 맑은 날 두 섬이 서로 보인다는 기록, 독도가 그려진 가장 오래된 지도 「팔도총도」, 독도를 울릉군이 다스린다고 정한 대한 제국 칙령(10월 25일 독도의 날) · 다른 나라 자료: 일본 국가 문서 「돗토리번 답변서」·「태정관 지령」(일본 땅이 아님), 일본이 만든 「삼국접양지도」(조선과 같은 색), 프랑스의 「조선왕국전도」, 연합국 최고 사령관 각서 부속 지도 · 옛 지도에는 그때 사람들의 영토 인식이 담겨 영토의 역사를 보여 주는 증거 — 누가 만들었고 무엇을 말하는지 읽기',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C10','soc',5,1,'u1',10,'독도를 지키기 위한 노력 — 안용복은 일본에 건너가 울릉도와 독도가 조선 땅임을 설명했고, 홍순칠과 울릉도 청년들은 독도 의용 수비대를 만들어 지키며 바위에 「한국령」을 새겼고, 최종덕은 주민 등록을 옮겨 최초의 독도 주민이 됨 · 정부는 선착장·주민 숙소·등대를 만들고 경찰인 독도 경비대를 파견(평소처럼 다스리는 우리 땅)하며 법과 정책으로 지키고 세계에 알림, 해양 경찰은 바다를 지킴 · 개인·학교·여러 단체도 방문·잘못된 정보 바로잡기·알리기 활동을 함 — 모두 함께',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u1-C11','soc',5,1,'u1',10,'우리 국토를 알리는 그림 만들기 — 그림으로 알리고 싶은 우리나라의 자연 경관(산지·해안·하천·독도 등)을 골라 생김새·동식물·사람·배경을 떠올려 조건을 구체적이고 자세하게 생각함(뜻이 흐린 조건은 무엇을 그릴지 정해 주지 못함) · 인공지능으로 만들고 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만듦 · 그림에 이름을 붙이고 어떤 조건으로 무엇을 표현했는지 스스로 소개함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X01','soc',5,'u1',ARRAY['SO5-1-u1-C1']::text[],'지형을 기후·인구·교통처럼 땅의 생김새가 아닌 것과 헷갈린다','지형 = 땅의 생김새') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X02','soc',5,'u1',ARRAY['SO5-1-u1-C1']::text[],'산지·하천·평야·해안·섬의 뜻을 서로 바꾸어 짝짓는다','솟은 땅·흐르는 물·평평한 땅·바다와 만나는 곳·바다에 둘러싸인 땅') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X03','soc',5,'u1',ARRAY['SO5-1-u1-C2','SO5-1-u1-C3']::text[],'우리나라 땅의 높낮이를 거꾸로(남서쪽이 높고 북동쪽이 낮다고, 또는 어디나 같다고) 안다','높은 산은 북쪽·동쪽에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X04','soc',5,'u1',ARRAY['SO5-1-u1-C2']::text[],'지형도·범례·단면도를 잘못 읽는다(색이 진하면 낮다고, 범례 대신 방위·축척을 본다 등)','범례의 색 = 높이 · 진할수록 높아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X05','soc',5,'u1',ARRAY['SO5-1-u1-C3']::text[],'하천이 낮은 곳에서 높은 곳으로, 또는 아무 방향으로나 흐른다고 여겨 큰 하천이 남서쪽으로 흐르는 까닭을 놓친다','물은 높은 곳 → 낮은 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X06','soc',5,'u1',ARRAY['SO5-1-u1-C3']::text[],'평야가 높은 산지에 있다고 여기거나 하천과 상관없이 생긴다고 여긴다','하천 주변 · 200 m 미만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X07','soc',5,'u1',ARRAY['SO5-1-u1-C4']::text[],'동해안과 서해안·남해안의 특징(해안선·섬·모래사장·갯벌)을 바꾸어 안다','동해안 — 단순·모래사장 · 서·남해안 — 복잡·섬·갯벌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X08','soc',5,'u1',ARRAY['SO5-1-u1-C4']::text[],'갯벌·모래사장·해안 절벽 같은 해안 지형과 그곳의 생활(조개 캐기·해수욕·간척 등)을 맞지 않게 짝짓는다','진흙 땅·모래·파도가 깎은 바위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X09','soc',5,'u1',ARRAY['SO5-1-u1-C5']::text[],'경관이나 관광지를 그것을 만든 지형과 맞지 않게 짝짓는다','무엇이 이 경관을 만들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X10','soc',5,'u1',ARRAY['SO5-1-u1-C5']::text[],'지질 공원·세계 지질 공원·해설사의 뜻을 오해하거나, 멋진 자연물을 기념으로 가져가도 된다고 여긴다','보전하고 알리는 곳 · 보고 배우되 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X11','soc',5,'u1',ARRAY['SO5-1-u1-C6']::text[],'국토 여행 계획의 차례(주제 → 조사 → 경로 → 공유)나 알맞은 도구(누리집·디지털 영상 지도·백지도)를 헷갈린다','주제가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X12','soc',5,'u1',ARRAY['SO5-1-u1-C6']::text[],'온라인에서 계획서를 나눌 때 놀리거나 장난스러운 댓글도 괜찮다고 여긴다','화면 너머에도 친구가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X13','soc',5,'u1',ARRAY['SO5-1-u1-C1','SO5-1-u1-C2','SO5-1-u1-C3','SO5-1-u1-C9']::text[],'지형이나 옛 자료 공부를 이름·숫자·연도를 외우는 것으로 여겨 특징과 뜻을 읽어 내는 것을 놓친다','외우기보다 견주고 읽어 내기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X14','soc',5,'u1',ARRAY['SO5-1-u1-C7']::text[],'독도의 위치(동쪽 끝·동해)·행정구역·가는 길(공항 없음, 배로 울릉도를 거쳐)을 헷갈린다','동쪽 끝 · 경상북도 울릉군 · 배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X15','soc',5,'u1',ARRAY['SO5-1-u1-C7']::text[],'독도가 중요한 까닭(영토 경계·교통과 군사·연구 가치·자원)을 놓치거나 엉뚱한 까닭(등산·농사·관광객 수)을 댄다','경계 · 교통·군사 · 연구 · 자원') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X16','soc',5,'u1',ARRAY['SO5-1-u1-C8']::text[],'독도의 자연환경(화산섬·동도와 서도·기후·어장·해양 심층수와 가스 하이드레이트·천연기념물 지정 까닭)을 잘못 안다','바닷속 화산 · 두 바닷물이 만나는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X17','soc',5,'u1',ARRAY['SO5-1-u1-C9']::text[],'옛 지도와 기록이 무엇을 말하는지 놓친다(다른 나라가 만든 자료의 뜻, 누가 만든 자료인지, 영토 인식의 증거라는 점)','누가 만들었고 무엇을 말하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X18','soc',5,'u1',ARRAY['SO5-1-u1-C10']::text[],'독도를 지킨 사람과 한 일을 바꾸어 짝짓거나, 독도를 지키는 일을 정부·경비대만의 일로 여긴다','안용복·홍순칠·최종덕 · 그리고 우리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u1-X19','soc',5,'u1',ARRAY['SO5-1-u1-C11']::text[],'그림을 만드는 조건을 흐리게 쓰거나, 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 된다고 여긴다','조건은 자세히 · 소개는 내가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#1','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'mc','auto','다양하게 나타나는 땅의 생김새를 무엇이라고 하나요?',ARRAY['SO5-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"다양하게 나타나는 땅의 생김새를 무엇이라고 하나요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO5-1-u1-X01"},{"t":"인구","mis":"SO5-1-u1-X01"},{"t":"교통","mis":"SO5-1-u1-X01"}],"explanation":["땅의 모습을 가리키는 말이에요.","산지·하천·평야·해안·섬이 모두 지형이에요.","기후는 날씨, 인구는 사람 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#2','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'mc','auto','산봉우리가 길게 이어져 솟아 있는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"산봉우리가 길게 이어져 솟아 있는 지형은 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"평야","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"}],"explanation":["산이 여럿 이어진 땅이에요.","이런 땅을 산지라고 해요.","우리 국토의 약 70%가 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#3','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'sa','auto','둘레가 바다로 둘러싸인 땅을 무엇이라고 하나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"sa","stem":"둘레가 바다로 둘러싸인 땅을 무엇이라고 하나요? 한 글자로 쓰세요.","answer":["섬"],"explanation":["사방이 바다예요.","배를 타야 갈 수 있어요.","이런 땅이 섬이에요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#4','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'ox','auto','하천은 낮은 곳에서 높은 곳으로 흐르는 물줄기예요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"하천은 낮은 곳에서 높은 곳으로 흐르는 물줄기예요.","answer":"X","reason_options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"물줄기는 흐르는 방향이 정해져 있지 않기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["하천은 크고 작은 물줄기예요.","물은 높은 곳에서 낮은 곳으로 흘러요.","그래서 하천도 그렇게 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#5','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'match','auto','다섯 장의 땅 카드를 보고 카드와 지형 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"다섯 장의 땅 카드를 보고 카드와 지형 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"섬"},{"l":"㉯","r":"산지"},{"l":"㉰","r":"하천"},{"l":"㉱","r":"평야"}],"mis":"SO5-1-u1-X02","explanation":["㉮는 바다에 둘러싸여 있어요.","㉯는 솟아 있고, ㉰는 흘러요.","㉱는 넓고 평평해요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#6','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','다섯 장의 땅 카드에서 ㉲에 알맞은 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"다섯 장의 땅 카드에서 ㉲에 알맞은 지형은 어느 것인가요?","options":[{"t":"해안","correct":true},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"평야","mis":"SO5-1-u1-X02"},{"t":"하천","mis":"SO5-1-u1-X02"}],"explanation":["㉲는 바다와 맞닿아 있어요.","모래사장이나 갯벌이 보여요.","이곳이 해안이에요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#7','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','넓고 평평하게 펼쳐져 있으며 하천 주변에 주로 발달하는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"넓고 평평하게 펼쳐져 있으며 하천 주변에 주로 발달하는 지형은 어느 것인가요?","options":[{"t":"평야","correct":true},{"t":"산지","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"}],"explanation":["넓고 평평한 땅이에요.","물줄기 곁에 잘 생겨요.","이런 땅이 평야예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#8','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','지난여름 가족과 해수욕장에서 모래 놀이를 했다면 그곳은 어떤 지형일까요?',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"지난여름 가족과 해수욕장에서 모래 놀이를 했다면 그곳은 어떤 지형일까요?","options":[{"t":"해안","correct":true},{"t":"산지","mis":"SO5-1-u1-X08"},{"t":"평야","mis":"SO5-1-u1-X08"},{"t":"하천","mis":"SO5-1-u1-X08"}],"explanation":["해수욕장 곁에는 바다가 있어요.","모래사장은 바다와 맞닿은 곳에 생겨요.","그래서 해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#9','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'ox','auto','우리나라에는 산지·하천·평야·해안·섬이 모두 나타나요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"ox","stem":"우리나라에는 산지·하천·평야·해안·섬이 모두 나타나요.","answer":"O","reason_options":[{"t":"한 나라 안에 여러 땅의 생김새가 어우러져 있기 때문에","correct":true},{"t":"우리나라에는 산지만 있기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["우리 국토에는 여러 지형이 있어요.","높은 산부터 바닷가까지 있어요.","그래서 지형이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_basic#10','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',3,'mc','auto','지형을 공부하는 바른 태도가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"지형을 공부하는 바른 태도가 아닌 것은 어느 것인가요?","options":[{"t":"산맥과 하천 이름을 빠짐없이 외우는 데에만 힘쓴다","correct":true},{"t":"여러 지형의 특징을 견주어 살펴본다","mis":"SO5-1-u1-X13"},{"t":"지도나 영상 자료로 지형의 모습을 확인한다","mis":"SO5-1-u1-X13"},{"t":"우리 국토의 아름다움을 느끼며 살펴본다","mis":"SO5-1-u1-X13"}],"explanation":["외우는 것이 목표가 아니에요.","특징을 견주고 자료로 확인해요.","국토의 아름다움도 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#1','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',2,'sa','auto','산지·하천·평야·해안·섬처럼 다양하게 나타나는 땅의 생김새를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"sa","stem":"산지·하천·평야·해안·섬처럼 다양하게 나타나는 땅의 생김새를 두 글자로 무엇이라고 하나요?","answer":["지형"],"explanation":["땅 지(地) 자가 들어가요.","땅의 모양을 뜻해요.","지형이에요."],"mis":"SO5-1-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#2','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',2,'match','auto','지형과 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"지형과 그 특징을 알맞게 이으세요.","pairs":[{"l":"산지","r":"산봉우리가 길게 이어진 땅"},{"l":"하천","r":"높은 곳에서 낮은 곳으로 흐르는 물줄기"},{"l":"해안","r":"바다와 맞닿은 곳"},{"l":"섬","r":"둘레가 바다로 둘러싸인 땅"}],"mis":"SO5-1-u1-X02","explanation":["솟은 땅은 산지예요.","흐르는 물줄기는 하천이에요.","바다와 만나면 해안, 둘러싸이면 섬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#3','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'mc','auto','다섯 장의 땅 카드 가운데 ㉰와 ㉱가 서로 가까이 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X02']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"다섯 장의 땅 카드 가운데 ㉰와 ㉱가 서로 가까이 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"물줄기 주변에 넓고 평평한 땅이 잘 발달하기 때문에","correct":true},{"t":"물줄기는 산봉우리 위에서만 흐르기 때문에","mis":"SO5-1-u1-X06"},{"t":"평평한 땅은 바다 한가운데에 생기기 때문에","mis":"SO5-1-u1-X06"},{"t":"두 카드는 같은 지형을 다르게 부른 것이기 때문에","mis":"SO5-1-u1-X02"}],"explanation":["㉰는 하천, ㉱는 평야예요.","평야는 하천 주변에 주로 발달해요.","그래서 둘은 가까이 있어요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#4','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'mc','auto','「배를 타고 가야 하고, 바닷가에서 갯벌도 볼 수 있다」는 여행지에서 만날 수 있는 지형을 모두 고른 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"「배를 타고 가야 하고, 바닷가에서 갯벌도 볼 수 있다」는 여행지에서 만날 수 있는 지형을 모두 고른 것은 어느 것인가요?","options":[{"t":"섬과 해안","correct":true},{"t":"산지와 평야","mis":"SO5-1-u1-X02"},{"t":"하천과 평야","mis":"SO5-1-u1-X02"},{"t":"산지와 하천","mis":"SO5-1-u1-X02"}],"explanation":["배를 타고 가는 땅은 섬이에요.","갯벌은 바다와 맞닿은 해안에 있어요.","그래서 섬과 해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#5','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'ox','auto','「높은 산에서 시작한 시원한 계곡물」을 소개하는 글은 하천과 산지를 함께 보여 주는 글이에요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"ox","stem":"「높은 산에서 시작한 시원한 계곡물」을 소개하는 글은 하천과 산지를 함께 보여 주는 글이에요.","answer":"O","reason_options":[{"t":"계곡물은 흐르는 물줄기이고 그 물이 시작하는 곳이 높은 산이기 때문에","correct":true},{"t":"계곡물은 바다와 맞닿은 해안이기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["계곡물은 하천이에요.","높은 산은 산지예요.","한 장면에 두 지형이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#6','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'error','auto','지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X01','SO5-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"error","stem":"지형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서준 — 「날씨가 더운 곳과 추운 곳도 지형이 달라서 생기는 거야.」","correct":true,"mis_target":"SO5-1-u1-X01"},{"t":"하윤 — 「평야는 넓고 평평해서 논밭이 많아.」","mis":"SO5-1-u1-X02"},{"t":"도현 — 「섬은 둘레가 모두 바다야.」","mis":"SO5-1-u1-X02"}],"explanation":["더위와 추위는 기후예요.","지형은 땅의 생김새예요.","둘은 서로 다른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#7','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',3,'mc','auto','우리나라 국토의 약 70%를 차지하는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"우리나라 국토의 약 70%를 차지하는 지형은 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"평야","mis":"SO5-1-u1-X03"},{"t":"해안","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"}],"explanation":["우리나라는 산이 많아요.","어디를 가도 산이 보여요.","국토의 약 70%가 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#8','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',4,'mc','auto','친구가 「우리 가족은 지형이 하나만 있는 곳으로 여행 갔어」라고 했어요. 친구의 말을 가장 알맞게 고쳐 준 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X01','SO5-1-u1-X13']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"친구가 「우리 가족은 지형이 하나만 있는 곳으로 여행 갔어」라고 했어요. 친구의 말을 가장 알맞게 고쳐 준 것은 어느 것인가요?","options":[{"t":"한 곳에도 산·물줄기·평평한 땅·바닷가가 함께 있기 쉬우니 어떤 지형들이 보였는지 다시 떠올려 볼래?","correct":true},{"t":"지형은 한 나라에 하나씩만 있으니 맞는 말이야.","mis":"SO5-1-u1-X02"},{"t":"지형은 날씨에 따라 달라지니 날씨를 먼저 말해 줘.","mis":"SO5-1-u1-X01"},{"t":"지형은 이름만 외우면 되니 이름만 말해 줘.","mis":"SO5-1-u1-X13"}],"explanation":["여러 지형은 서로 이어져 있어요.","한 장면에 여럿이 함께 보여요.","다시 떠올려 보게 돕는 말이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#9','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',4,'mc','auto','「산지·하천·평야·해안·섬」 다섯 지형을 두 무리로 나눌 때 가장 알맞은 기준과 나눔은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"「산지·하천·평야·해안·섬」 다섯 지형을 두 무리로 나눌 때 가장 알맞은 기준과 나눔은 어느 것인가요?","options":[{"t":"바다와 닿아 있는가 — (해안·섬) / (산지·하천·평야)","correct":true},{"t":"물이 흐르는가 — (하천·해안) / (산지·평야·섬)","mis":"SO5-1-u1-X02"},{"t":"사람이 사는가 — (평야) / (산지·하천·해안·섬)","mis":"SO5-1-u1-X01"},{"t":"날씨가 따뜻한가 — (해안·평야) / (산지·하천·섬)","mis":"SO5-1-u1-X01"}],"explanation":["해안은 바다와 맞닿은 곳이에요.","섬은 바다로 둘러싸여 있어요.","나머지 셋은 바다와 떨어져 있어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L01_challenge#10','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',4,'essay','teacher','지형이 무엇인지 쓰고, 여러분이 가 본 곳(또는 가 보고 싶은 곳) 한 곳을 골라 그곳의 지형과 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"essay","stem":"지형이 무엇인지 쓰고, 여러분이 가 본 곳(또는 가 보고 싶은 곳) 한 곳을 골라 그곳의 지형과 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 지형은 다양하게 나타나는 땅의 생김새이다. 나는 할머니 댁 근처의 넓은 들판에 가 보았다. 넓고 평평한 땅에 논이 많고 그 옆으로 강이 흘렀으므로 하천 주변에 발달한 평야라고 생각한다.","scoring_points":["지형의 뜻을 바르게 썼는가","고른 곳의 지형을 썼는가","모습(특징)을 근거로 까닭을 썼는가"]},"explanation":["지형은 땅의 생김새예요.","모습을 떠올려 지형을 골라요.","특징이 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#1','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'mc','auto','지형도에서 색이 얼마만큼의 높이를 뜻하는지 알려 주는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"지형도에서 색이 얼마만큼의 높이를 뜻하는지 알려 주는 것은 어느 것인가요?","options":[{"t":"범례","correct":true},{"t":"방위표","mis":"SO5-1-u1-X04"},{"t":"제목","mis":"SO5-1-u1-X04"},{"t":"축척","mis":"SO5-1-u1-X04"}],"explanation":["색과 뜻을 나란히 적어 둔 부분이에요.","이것을 범례라고 해요.","범례로 땅의 높이를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#2','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'mc','auto','우리나라에서 높고 험한 산지는 주로 어느 쪽에 많나요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"우리나라에서 높고 험한 산지는 주로 어느 쪽에 많나요?","options":[{"t":"북쪽과 동쪽","correct":true},{"t":"남쪽과 서쪽","mis":"SO5-1-u1-X03"},{"t":"남쪽과 동쪽","mis":"SO5-1-u1-X03"},{"t":"북쪽과 서쪽","mis":"SO5-1-u1-X03"}],"explanation":["지형도에서 색이 진한 곳을 떠올려요.","대부분 북쪽과 동쪽이에요.","그래서 그쪽 땅이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#3','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'sa','auto','땅의 높낮이를 서로 다른 색으로 칠해 땅의 생김새를 나타낸 지도를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"sa","stem":"땅의 높낮이를 서로 다른 색으로 칠해 땅의 생김새를 나타낸 지도를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["지형도"],"explanation":["지형을 나타낸 지도예요.","높은 곳과 낮은 곳의 색이 달라요.","지형도라고 해요."],"mis":"SO5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#4','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',1,'ox','auto','지형도에서는 색이 진할수록 땅이 높아요.',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"ox","stem":"지형도에서는 색이 진할수록 땅이 높아요.","answer":"O","reason_options":[{"t":"범례에서 진한 색이 높은 땅을 나타내도록 정해 두었기 때문에","correct":true},{"t":"진한 색은 바다를 나타내기 때문에","mis":"SO5-1-u1-X04"}],"mis":"SO5-1-u1-X04","explanation":["범례를 보면 알 수 있어요.","진한 갈색이 가장 높아요.","초록색은 낮은 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#5','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','우리나라 땅의 높낮이 특징을 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"우리나라 땅의 높낮이 특징을 바르게 말한 것은 어느 것인가요?","options":[{"t":"북동쪽이 높고 남서쪽이 낮다","correct":true},{"t":"남서쪽이 높고 북동쪽이 낮다","mis":"SO5-1-u1-X03"},{"t":"가운데가 가장 높고 가장자리는 모두 낮다","mis":"SO5-1-u1-X03"},{"t":"어디나 높이가 비슷하다","mis":"SO5-1-u1-X03"}],"explanation":["높은 산이 북쪽과 동쪽에 몰려 있어요.","낮은 산은 남쪽과 서쪽에 있어요.","그래서 북동쪽이 높고 남서쪽이 낮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#6','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','지형도 읽기 메모에서 가장 높은 땅은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지형도 읽기 메모에서 가장 높은 땅은 어느 것인가요?","options":[{"t":"㉠ 북쪽 땅","correct":true},{"t":"㉡ 동쪽 땅","mis":"SO5-1-u1-X04"},{"t":"㉢ 서쪽 땅","mis":"SO5-1-u1-X04"},{"t":"㉣ 남서쪽 땅","mis":"SO5-1-u1-X04"}],"explanation":["범례에서 진한 갈색이 가장 높아요.","㉠이 진한 갈색이에요.","그래서 ㉠이 가장 높아요."],"asset":{"type":"passage","lines":["범례 — 진한 갈색 2,000 m 이상 · 갈색 1,000 m 안팎","범례 — 노란색 500 m 안팎 · 초록색 200 m 미만","㉠ 북쪽 땅 — 진한 갈색","㉡ 동쪽 땅 — 갈색","㉢ 서쪽 땅 — 초록색","㉣ 남서쪽 땅 — 노란색과 초록색"],"title":"지형도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#7','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','지형도 읽기 메모에서 ㉢ 서쪽 땅의 높이로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지형도 읽기 메모에서 ㉢ 서쪽 땅의 높이로 알맞은 것은 어느 것인가요?","options":[{"t":"200 m 미만","correct":true},{"t":"2,000 m 이상","mis":"SO5-1-u1-X04"},{"t":"1,000 m 안팎","mis":"SO5-1-u1-X04"},{"t":"500 m 안팎","mis":"SO5-1-u1-X04"}],"explanation":["㉢은 초록색이에요.","범례에서 초록색을 찾아요.","초록색은 200 m 미만이에요."],"asset":{"type":"passage","lines":["범례 — 진한 갈색 2,000 m 이상 · 갈색 1,000 m 안팎","범례 — 노란색 500 m 안팎 · 초록색 200 m 미만","㉠ 북쪽 땅 — 진한 갈색","㉡ 동쪽 땅 — 갈색","㉢ 서쪽 땅 — 초록색","㉣ 남서쪽 땅 — 노란색과 초록색"],"title":"지형도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#8','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'mc','auto','지형도에서 산지가 어디인지 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"지형도에서 산지가 어디인지 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"범례를 보고 육지 높이가 높게 칠해진 곳을 찾는다","correct":true},{"t":"바다 색이 진한 곳을 찾는다","mis":"SO5-1-u1-X04"},{"t":"글자가 많이 적힌 곳을 찾는다","mis":"SO5-1-u1-X04"},{"t":"도시 이름이 적힌 곳을 찾는다","mis":"SO5-1-u1-X04"}],"explanation":["산지는 땅이 높은 곳이에요.","범례로 높은 색을 확인해요.","그 색이 칠해진 곳이 산지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#9','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',2,'ox','auto','서쪽에서 동쪽으로 자른 땅의 단면을 보면 동쪽으로 갈수록 땅이 높아져요.',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"ox","stem":"서쪽에서 동쪽으로 자른 땅의 단면을 보면 동쪽으로 갈수록 땅이 높아져요.","answer":"O","reason_options":[{"t":"높은 산이 동쪽에 몰려 있기 때문에","correct":true},{"t":"서쪽에 높은 산이 몰려 있기 때문에","mis":"SO5-1-u1-X03"}],"mis":"SO5-1-u1-X03","explanation":["단면도는 땅을 옆에서 본 모습이에요.","서쪽은 낮고 동쪽은 높아요.","높은 산이 동쪽에 많아서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_basic#10','soc',5,1,'u1','L02','g5_1_soc_u1_L02_basic','lesson_basic','SO5-1-u1-C2',3,'error','auto','지형도 읽기 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X04','SO5-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"error","stem":"지형도 읽기 메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「㉢이 가장 높아. 초록색이 제일 눈에 잘 띄거든.」","correct":true,"mis_target":"SO5-1-u1-X04"},{"t":"민호 — 「㉠과 ㉡은 높은 산이 있는 곳이야.」","mis":"SO5-1-u1-X03"},{"t":"수아 — 「㉣은 ㉠보다 낮은 땅이야.」","mis":"SO5-1-u1-X03"}],"explanation":["높이는 눈에 띄는 색이 아니라 범례로 읽어요.","초록색은 200 m 미만이에요.","㉢은 낮은 땅이에요."],"asset":{"type":"passage","lines":["범례 — 진한 갈색 2,000 m 이상 · 갈색 1,000 m 안팎","범례 — 노란색 500 m 안팎 · 초록색 200 m 미만","㉠ 북쪽 땅 — 진한 갈색","㉡ 동쪽 땅 — 갈색","㉢ 서쪽 땅 — 초록색","㉣ 남서쪽 땅 — 노란색과 초록색"],"title":"지형도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#1','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',2,'mc','auto','땅의 단면 자료에서 A(서쪽)와 B(동쪽) 가까이의 땅 높이를 견주면 어떠한가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X04']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"땅의 단면 자료에서 A(서쪽)와 B(동쪽) 가까이의 땅 높이를 견주면 어떠한가요?","options":[{"t":"B 가까이가 더 높다","correct":true},{"t":"A가 더 높다","mis":"SO5-1-u1-X03"},{"t":"높이가 같다","mis":"SO5-1-u1-X03"},{"t":"견주어 볼 수 없다","mis":"SO5-1-u1-X04"}],"explanation":["A는 0 m 가까이예요.","B 가까이는 1,000 m가 넘어요.","동쪽이 더 높아요."],"asset":{"type":"passage","lines":["A(서쪽 바닷가) — 0 m 가까이","가운데 — 낮은 언덕과 들(200 m 안팎)","B 가까이(동쪽) — 높은 산줄기(1,000 m 넘음)","B를 지나면 — 곧바로 바다"],"title":"서쪽 A에서 동쪽 B까지 자른 땅의 단면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#2','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',2,'sa','auto','지형도에서 색이나 기호가 무엇을 뜻하는지 적어 둔 부분을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"sa","stem":"지형도에서 색이나 기호가 무엇을 뜻하는지 적어 둔 부분을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["범례"],"explanation":["지도 한쪽에 있어요.","색과 높이를 짝지어 두었어요.","범례라고 해요."],"mis":"SO5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#3','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'mc','auto','땅의 단면 자료를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X04']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"땅의 단면 자료를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서쪽에는 낮은 땅이 넓고, 동쪽에는 높은 산줄기가 바다 가까이까지 솟아 있다","correct":true},{"t":"서쪽에 높은 산줄기가 있고 동쪽은 넓은 들이다","mis":"SO5-1-u1-X03"},{"t":"서쪽과 동쪽 모두 높은 산줄기만 있다","mis":"SO5-1-u1-X03"},{"t":"단면 자료로는 땅의 높낮이를 알 수 없다","mis":"SO5-1-u1-X04"}],"explanation":["A 쪽은 낮아요.","가운데는 언덕과 들이에요.","B 가까이는 높은 산줄기예요."],"asset":{"type":"passage","lines":["A(서쪽 바닷가) — 0 m 가까이","가운데 — 낮은 언덕과 들(200 m 안팎)","B 가까이(동쪽) — 높은 산줄기(1,000 m 넘음)","B를 지나면 — 곧바로 바다"],"title":"서쪽 A에서 동쪽 B까지 자른 땅의 단면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#4','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'mc','auto','지형도에서 색이 가장 진하게 칠해진 곳에 가면 볼 수 있을 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X04','SO5-1-u1-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"지형도에서 색이 가장 진하게 칠해진 곳에 가면 볼 수 있을 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"험한 산봉우리가 줄지어 이어진 모습","correct":true},{"t":"넓게 펼쳐진 논밭","mis":"SO5-1-u1-X04"},{"t":"잔잔한 갯벌","mis":"SO5-1-u1-X08"},{"t":"길게 뻗은 모래사장","mis":"SO5-1-u1-X08"}],"explanation":["진한 색은 높은 땅이에요.","높은 땅에는 산지가 있어요.","험한 봉우리가 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#5','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'mc','auto','산지 지형과 관련 있는 관광지로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"산지 지형과 관련 있는 관광지로 알맞은 것은 어느 것인가요?","options":[{"t":"높은 산지에 펼쳐진 초원과 풍력 발전기가 있는 목장","correct":true},{"t":"물이 빠지면 조개를 캐는 갯벌 체험장","mis":"SO5-1-u1-X09"},{"t":"지평선이 보이는 넓은 평야","mis":"SO5-1-u1-X09"},{"t":"두 물줄기가 합쳐지는 강가 마을","mis":"SO5-1-u1-X09"}],"explanation":["목장은 높은 산지에 있어요.","바람이 세서 풍력 발전기도 있어요.","산지가 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#6','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'ox','auto','「1,000 m가 넘는 높은 산은 주로 남쪽과 서쪽에 있다」는 말은 바르게 지형도를 읽은 것이에요.',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"ox","stem":"「1,000 m가 넘는 높은 산은 주로 남쪽과 서쪽에 있다」는 말은 바르게 지형도를 읽은 것이에요.","answer":"X","reason_options":[{"t":"1,000 m가 넘는 높은 산은 주로 북쪽과 동쪽에 있기 때문에","correct":true},{"t":"높은 산은 우리나라 어디에나 똑같이 퍼져 있기 때문에","mis":"SO5-1-u1-X03"}],"mis":"SO5-1-u1-X03","explanation":["높은 산은 북쪽과 동쪽에 몰려 있어요.","남쪽과 서쪽에는 낮은 산이 많아요.","그래서 바르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#7','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',3,'error','auto','산지를 공부하는 태도를 두고 친구들이 말했어요. 바르지 않은 친구는 누구인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X03','SO5-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"error","stem":"산지를 공부하는 태도를 두고 친구들이 말했어요. 바르지 않은 친구는 누구인가요?","options":[{"t":"은우 — 「산 이름과 높이 숫자를 모두 외우는 게 제일 중요해.」","correct":true,"mis_target":"SO5-1-u1-X13"},{"t":"예린 — 「높은 산이 어느 쪽에 몰려 있는지 견주어 봐야지.」","mis":"SO5-1-u1-X03"},{"t":"준서 — 「산지 경관을 보며 국토의 아름다움을 느껴.」","mis":"SO5-1-u1-X09"}],"explanation":["외우는 것이 목표가 아니에요.","분포를 견주어 이해해요.","아름다움도 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#8','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','어느 학생이 「동쪽 바닷가에서 출발해 서쪽 바닷가까지 걸어간다」고 해요. 길의 높낮이 변화로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"어느 학생이 「동쪽 바닷가에서 출발해 서쪽 바닷가까지 걸어간다」고 해요. 길의 높낮이 변화로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"처음에 곧 높은 산을 넘고, 서쪽으로 갈수록 점점 낮아진다","correct":true},{"t":"처음부터 끝까지 평평하다","mis":"SO5-1-u1-X03"},{"t":"처음에는 낮다가 서쪽 바닷가에서 가장 높아진다","mis":"SO5-1-u1-X03"},{"t":"처음에 넓은 들을 지나고 서쪽 끝에서 높은 산을 넘는다","mis":"SO5-1-u1-X03"}],"explanation":["동쪽은 높은 산이 바다 가까이 있어요.","서쪽으로 갈수록 낮아져요.","단면도를 거꾸로 걸어간 셈이에요."],"asset":{"type":"passage","lines":["A(서쪽 바닷가) — 0 m 가까이","가운데 — 낮은 언덕과 들(200 m 안팎)","B 가까이(동쪽) — 높은 산줄기(1,000 m 넘음)","B를 지나면 — 곧바로 바다"],"title":"서쪽 A에서 동쪽 B까지 자른 땅의 단면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#9','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','높은 산에서 바람이 세게 부는 곳에 풍력 발전기가 많은 까닭을 지형과 관련지어 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X06']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"높은 산에서 바람이 세게 부는 곳에 풍력 발전기가 많은 까닭을 지형과 관련지어 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"높은 산지는 바람을 막는 것이 적어 바람이 세게 불기 때문에","correct":true},{"t":"높은 산지는 갯벌이 넓기 때문에","mis":"SO5-1-u1-X08"},{"t":"높은 산지는 바다와 맞닿아 있기 때문에","mis":"SO5-1-u1-X07"},{"t":"높은 산지는 평평한 논밭이 넓기 때문에","mis":"SO5-1-u1-X06"}],"explanation":["높은 곳은 바람이 세요.","바람이 세면 전기를 만들기 좋아요.","지형이 경관을 만든 예예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L02_challenge#10','soc',5,1,'u1','L02','g5_1_soc_u1_L02_challenge','lesson_challenge','SO5-1-u1-C2',4,'essay','teacher','지형도와 단면도로 알 수 있는 우리나라 땅의 높낮이 특징을 쓰고, 그렇게 말할 수 있는 근거를 두 자료에서 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"essay","stem":"지형도와 단면도로 알 수 있는 우리나라 땅의 높낮이 특징을 쓰고, 그렇게 말할 수 있는 근거를 두 자료에서 하나씩 쓰세요.","answer_guide":{"answer":"예: 우리나라 땅은 북쪽과 동쪽이 높고 남쪽과 서쪽이 낮다. 지형도에서는 진한 갈색으로 칠해진 높은 산이 북쪽과 동쪽에 몰려 있다. 서쪽에서 동쪽으로 자른 단면도에서는 서쪽은 낮고 동쪽으로 갈수록 땅이 높아진다.","scoring_points":["북동쪽이 높고 남서쪽이 낮다고 썼는가","지형도에서 근거를 찾았는가","단면도에서 근거를 찾았는가"]},"explanation":["높은 산이 몰린 쪽이 높아요.","지형도는 색으로 보여요.","단면도는 옆모습으로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#1','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'mc','auto','물은 어떤 방향으로 흐르나요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"물은 어떤 방향으로 흐르나요?","options":[{"t":"높은 곳에서 낮은 곳으로","correct":true},{"t":"낮은 곳에서 높은 곳으로","mis":"SO5-1-u1-X05"},{"t":"언제나 동쪽으로","mis":"SO5-1-u1-X05"},{"t":"방향이 정해져 있지 않다","mis":"SO5-1-u1-X05"}],"explanation":["물은 아래로 흘러요.","높은 곳에서 낮은 곳으로 가요.","하천의 방향도 땅의 높낮이가 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#2','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'mc','auto','우리나라의 큰 하천은 대부분 어느 쪽으로 흐르나요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"우리나라의 큰 하천은 대부분 어느 쪽으로 흐르나요?","options":[{"t":"남쪽과 서쪽","correct":true},{"t":"북쪽과 동쪽","mis":"SO5-1-u1-X05"},{"t":"북쪽과 서쪽","mis":"SO5-1-u1-X05"},{"t":"남쪽과 동쪽","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","우리나라는 남쪽과 서쪽이 낮아요.","그래서 큰 하천도 그쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#3','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'sa','auto','하천 주변에 낮고 평평하게 넓게 펼쳐진 땅을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"sa","stem":"하천 주변에 낮고 평평하게 넓게 펼쳐진 땅을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["평야"],"explanation":["넓고 평평한 땅이에요.","하천 곁에 잘 생겨요.","논밭이 많아요."],"mis":"SO5-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#4','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',1,'ox','auto','하천 주변의 땅은 대부분 200 m 미만의 낮은 땅이에요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"ox","stem":"하천 주변의 땅은 대부분 200 m 미만의 낮은 땅이에요.","answer":"O","reason_options":[{"t":"물이 낮은 곳으로 모여 흐르고 그 주변에 낮고 평평한 땅이 펼쳐지기 때문에","correct":true},{"t":"하천은 높은 산꼭대기를 따라서만 흐르기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["하천은 낮은 곳으로 흘러요.","그 주변도 낮은 땅이에요.","그래서 평야가 발달해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#5','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','물길 따라가기 놀이판의 갈림길 ①에서 물이 갈 수 있는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"물길 따라가기 놀이판의 갈림길 ①에서 물이 갈 수 있는 곳은 어느 것인가요?","options":[{"t":"㉯ 800 m","correct":true},{"t":"㉮ 1,400 m","mis":"SO5-1-u1-X05"},{"t":"㉰ 1,300 m","mis":"SO5-1-u1-X05"},{"t":"세 곳 모두","mis":"SO5-1-u1-X05"}],"explanation":["출발은 1,200 m예요.","물은 더 낮은 곳으로만 가요.","1,200 m보다 낮은 곳은 ㉯뿐이에요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#6','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','물길 따라가기 놀이판의 갈림길 ③에서 물이 가장 먼저 갈 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"물길 따라가기 놀이판의 갈림길 ③에서 물이 가장 먼저 갈 곳은 어느 것인가요?","options":[{"t":"㉯ 150 m","correct":true},{"t":"㉮ 600 m","mis":"SO5-1-u1-X05"},{"t":"㉰ 350 m","mis":"SO5-1-u1-X05"},{"t":"물이 멈춘다","mis":"SO5-1-u1-X05"}],"explanation":["세 곳의 높이를 견줘요.","가장 낮은 곳이 150 m예요.","물은 가장 낮은 곳으로 흘러가요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#7','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','큰 하천이 남쪽과 서쪽으로 흐르는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"큰 하천이 남쪽과 서쪽으로 흐르는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 땅이 북동쪽은 높고 남서쪽은 낮기 때문에","correct":true},{"t":"남서쪽이 높고 북동쪽이 낮기 때문에","mis":"SO5-1-u1-X03"},{"t":"바닷물이 하천을 끌어당기기 때문에","mis":"SO5-1-u1-X05"},{"t":"비가 남서쪽에만 내리기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","우리나라는 남서쪽이 낮아요.","그래서 큰 하천도 남서쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#8','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'mc','auto','큰 하천의 아래쪽 주변에 가면 흔히 볼 수 있는 모습은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"큰 하천의 아래쪽 주변에 가면 흔히 볼 수 있는 모습은 어느 것인가요?","options":[{"t":"넓게 펼쳐진 논밭","correct":true},{"t":"눈 덮인 험한 봉우리","mis":"SO5-1-u1-X06"},{"t":"깎아지른 바닷가 절벽","mis":"SO5-1-u1-X08"},{"t":"바닷물이 빠진 진흙 땅","mis":"SO5-1-u1-X08"}],"explanation":["하천 아래쪽 주변은 낮고 평평해요.","그곳에 평야가 발달해요.","넓은 논밭이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#9','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',2,'ox','auto','평야는 높은 산꼭대기에 주로 발달해요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"평야는 높은 산꼭대기에 주로 발달해요.","answer":"X","reason_options":[{"t":"평야는 낮고 평평한 하천 주변에 주로 발달하기 때문에","correct":true},{"t":"높은 곳일수록 땅이 평평해지기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["산꼭대기는 높고 험해요.","평야는 낮고 평평한 땅이에요.","하천 주변에 주로 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_basic#10','soc',5,1,'u1','L03','g5_1_soc_u1_L03_basic','lesson_basic','SO5-1-u1-C3',3,'mc','auto','물길 따라가기 놀이판에서 출발부터 갈림길 ③까지 물이 지나간 높이를 차례대로 바르게 쓴 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"물길 따라가기 놀이판에서 출발부터 갈림길 ③까지 물이 지나간 높이를 차례대로 바르게 쓴 것은 어느 것인가요?","options":[{"t":"1,200 m → 800 m → 400 m → 150 m","correct":true},{"t":"1,200 m → 1,400 m → 900 m → 600 m","mis":"SO5-1-u1-X05"},{"t":"1,200 m → 800 m → 900 m → 150 m","mis":"SO5-1-u1-X05"},{"t":"1,200 m → 1,300 m → 700 m → 350 m","mis":"SO5-1-u1-X05"}],"explanation":["갈림길마다 가장 낮은 곳을 골라요.","800 m → 400 m → 150 m예요.","물은 점점 낮아지며 바다로 가요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#1','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',2,'mc','auto','두 물줄기가 합쳐져 큰 하천을 이루는 강가 마을의 경관을 만든 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"두 물줄기가 합쳐져 큰 하천을 이루는 강가 마을의 경관을 만든 지형은 어느 것인가요?","options":[{"t":"하천","correct":true},{"t":"해안","mis":"SO5-1-u1-X09"},{"t":"섬","mis":"SO5-1-u1-X09"},{"t":"갯벌","mis":"SO5-1-u1-X09"}],"explanation":["두 물줄기가 만나는 곳이에요.","물줄기는 하천이에요.","하천이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#2','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',2,'sa','auto','크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"sa","stem":"크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["하천"],"explanation":["물이 흐르는 지형이에요.","강과 시내를 함께 이르는 말이에요.","하천이에요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#3','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'mc','auto','물길 따라가기 놀이판에서 갈림길 ②에 물이 도착했을 때, 물이 이미 지나온 곳보다 높은 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"물길 따라가기 놀이판에서 갈림길 ②에 물이 도착했을 때, 물이 이미 지나온 곳보다 높은 곳은 어느 것인가요?","options":[{"t":"㉮ 900 m","correct":true},{"t":"㉯ 700 m","mis":"SO5-1-u1-X05"},{"t":"㉰ 400 m","mis":"SO5-1-u1-X05"},{"t":"세 곳 모두 지나온 곳보다 낮다","mis":"SO5-1-u1-X05"}],"explanation":["물은 갈림길 ①에서 800 m로 왔어요.","900 m는 800 m보다 높아요.","그래서 ㉮로는 갈 수 없어요."],"asset":{"type":"passage","lines":["출발 — 북동쪽 산지(1,200 m)","갈림길 ① — ㉮ 1,400 m · ㉯ 800 m · ㉰ 1,300 m","갈림길 ② — ㉮ 900 m · ㉯ 700 m · ㉰ 400 m","갈림길 ③ — ㉮ 600 m · ㉯ 150 m · ㉰ 350 m","물은 세 곳 가운데 한 곳으로만 갈 수 있다."],"title":"물길 따라가기 놀이판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#4','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'mc','auto','한반도를 줄여 놓은 듯한 모양의 마을 지형은 어떻게 만들어졌을까요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"한반도를 줄여 놓은 듯한 모양의 마을 지형은 어떻게 만들어졌을까요?","options":[{"t":"깊은 골짜기를 흐르는 하천이 오랜 시간 땅을 깎아 만들었다","correct":true},{"t":"바닷물이 오랫동안 드나들며 만들었다","mis":"SO5-1-u1-X09"},{"t":"사람들이 흙을 쌓아 만들었다","mis":"SO5-1-u1-X09"},{"t":"화산이 터지면서 만들어졌다","mis":"SO5-1-u1-X09"}],"explanation":["하천은 흐르면서 땅을 깎아요.","오랜 시간이 지나면 모양이 생겨요.","하천이 만든 지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#5','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'ox','auto','지평선이 보일 만큼 넓은 들판에서 농사 문화를 체험할 수 있는 곳은 하천과 관계가 있어요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"ox","stem":"지평선이 보일 만큼 넓은 들판에서 농사 문화를 체험할 수 있는 곳은 하천과 관계가 있어요.","answer":"O","reason_options":[{"t":"넓은 들판은 하천 주변에 발달한 평야이기 때문에","correct":true},{"t":"넓은 들판은 높은 산지에만 있기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["지평선이 보이는 들판은 평야예요.","평야는 하천 주변에 발달해요.","그래서 하천과 관계가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#6','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'error','auto','하천과 평야를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"error","stem":"하천과 평야를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「물은 바다를 향해 가니까 언제나 동쪽으로 흘러.」","correct":true,"mis_target":"SO5-1-u1-X05"},{"t":"나린 — 「하천 아래쪽 주변에는 논밭이 넓게 펼쳐져.」","mis":"SO5-1-u1-X06"},{"t":"시우 — 「하천이 흐르는 방향을 보면 땅의 높낮이를 알 수 있어.」","mis":"SO5-1-u1-X05"}],"explanation":["물은 동쪽이 아니라 낮은 곳으로 흘러요.","우리나라는 서쪽과 남쪽이 낮아요.","그래서 큰 하천은 서·남쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#7','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',3,'mc','auto','깊은 골짜기를 흐르는 물과 폭포가 어우러진 계곡의 경관을 만든 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"깊은 골짜기를 흐르는 물과 폭포가 어우러진 계곡의 경관을 만든 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"골짜기를 따라 흐르는 하천","correct":true},{"t":"바다와 맞닿은 해안","mis":"SO5-1-u1-X09"},{"t":"넓고 평평한 평야","mis":"SO5-1-u1-X09"},{"t":"파도가 깎은 해안 절벽","mis":"SO5-1-u1-X09"}],"explanation":["계곡에는 물이 흘러요.","흐르는 물이 골짜기를 만들어요.","하천이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#8','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',4,'mc','auto','「하천이 흐르는 방향을 보면 땅의 높낮이를 알 수 있다」는 말의 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X13']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"mc","stem":"「하천이 흐르는 방향을 보면 땅의 높낮이를 알 수 있다」는 말의 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물은 언제나 높은 곳에서 낮은 곳으로 흐르므로, 하천이 흘러가는 쪽이 더 낮은 땅이기 때문에","correct":true},{"t":"하천은 언제나 북쪽에서 시작하기 때문에","mis":"SO5-1-u1-X05"},{"t":"하천 이름에 땅의 높이가 적혀 있기 때문에","mis":"SO5-1-u1-X13"},{"t":"하천이 흐르는 쪽이 언제나 더 높은 땅이기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","흘러가는 쪽이 더 낮아요.","그래서 방향으로 높낮이를 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#9','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',4,'mc','auto','어느 지역에서 하천이 동쪽으로 흐르고 있었어요. 이 지역의 높낮이로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"mc","stem":"어느 지역에서 하천이 동쪽으로 흐르고 있었어요. 이 지역의 높낮이로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서쪽이 동쪽보다 높다","correct":true},{"t":"동쪽이 서쪽보다 높다","mis":"SO5-1-u1-X05"},{"t":"어디나 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"높낮이와 하천은 상관없다","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 쪽으로 흘러요.","동쪽으로 흐르면 동쪽이 낮아요.","그 지역은 서쪽이 더 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L03_challenge#10','soc',5,1,'u1','L03','g5_1_soc_u1_L03_challenge','lesson_challenge','SO5-1-u1-C3',4,'essay','teacher','우리나라의 큰 하천이 대부분 남쪽과 서쪽으로 흐르는 까닭을 쓰고, 하천 주변에 평야가 발달하는 까닭과 그곳에서 볼 수 있는 모습을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"essay","stem":"우리나라의 큰 하천이 대부분 남쪽과 서쪽으로 흐르는 까닭을 쓰고, 하천 주변에 평야가 발달하는 까닭과 그곳에서 볼 수 있는 모습을 쓰세요.","answer_guide":{"answer":"예: 우리나라는 북쪽과 동쪽이 높고 남쪽과 서쪽이 낮은데, 물은 높은 곳에서 낮은 곳으로 흐르므로 큰 하천도 남쪽과 서쪽으로 흐른다. 하천 주변은 대부분 200 m 미만의 낮고 평평한 땅이어서 평야가 발달하고, 그곳에서는 넓은 논밭을 볼 수 있다.","scoring_points":["땅의 높낮이로 흐르는 방향의 까닭을 썼는가","하천 주변이 낮고 평평하다고 썼는가","평야에서 볼 수 있는 모습을 썼는가"]},"explanation":["높낮이가 방향을 정해요.","하천 주변은 낮고 평평해요.","넓은 논밭이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#1','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'mc','auto','우리나라는 몇 면이 바다와 맞닿아 있나요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"우리나라는 몇 면이 바다와 맞닿아 있나요?","options":[{"t":"세 면","correct":true},{"t":"한 면","mis":"SO5-1-u1-X07"},{"t":"두 면","mis":"SO5-1-u1-X07"},{"t":"네 면","mis":"SO5-1-u1-X07"}],"explanation":["동쪽·서쪽·남쪽이 바다예요.","그래서 삼면이 바다라고 해요.","해안 지형이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#2','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'mc','auto','해안선이 단순하고 모래사장이 넓게 펼쳐진 해안은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"해안선이 단순하고 모래사장이 넓게 펼쳐진 해안은 어느 것인가요?","options":[{"t":"동해안","correct":true},{"t":"서해안","mis":"SO5-1-u1-X07"},{"t":"남해안","mis":"SO5-1-u1-X07"},{"t":"서해안과 남해안","mis":"SO5-1-u1-X07"}],"explanation":["동해안은 굴곡이 적어요.","넓은 모래사장이 있어요.","해수욕장이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#3','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'sa','auto','바다와 육지가 만나는 선을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"sa","stem":"바다와 육지가 만나는 선을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["해안선"],"explanation":["바다와 땅의 경계예요.","지도에서 따라 그릴 수 있어요.","해안선이라고 해요."],"mis":"SO5-1-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#4','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',1,'ox','auto','서해안과 남해안은 해안선이 복잡하고 섬이 많아요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"ox","stem":"서해안과 남해안은 해안선이 복잡하고 섬이 많아요.","answer":"O","reason_options":[{"t":"해안선이 들쭉날쭉하고 크고 작은 섬이 많이 흩어져 있기 때문에","correct":true},{"t":"서해안과 남해안은 해안선이 곧게 뻗어 있기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["서해안과 남해안은 굴곡이 많아요.","섬도 아주 많아요.","남해안은 다도해라고도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#5','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'match','auto','해안 특징 카드를 보고 카드와 알맞은 바다를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"match","stem":"해안 특징 카드를 보고 카드와 알맞은 바다를 이으세요.","pairs":[{"l":"㉠","r":"동해안"},{"l":"㉡","r":"서해안"},{"l":"㉢","r":"남해안"}],"mis":"SO5-1-u1-X07","explanation":["곧게 뻗은 해안선은 동해안이에요.","넓은 진흙 땅은 서해안의 갯벌이에요.","섬이 아주 많은 바다는 남해안이에요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#6','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'mc','auto','바닷물이 빠진 뒤 조개를 잡는 체험을 할 수 있는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X09']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"바닷물이 빠진 뒤 조개를 잡는 체험을 할 수 있는 곳은 어느 것인가요?","options":[{"t":"넓은 갯벌","correct":true},{"t":"넓은 모래사장","mis":"SO5-1-u1-X08"},{"t":"깎아지른 해안 절벽","mis":"SO5-1-u1-X08"},{"t":"높은 산지","mis":"SO5-1-u1-X09"}],"explanation":["갯벌은 바닷물이 드나드는 진흙 땅이에요.","물이 빠지면 드러나요.","그때 조개를 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#7','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'mc','auto','여름에 동해안의 해수욕장을 찾는 사람이 많은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"여름에 동해안의 해수욕장을 찾는 사람이 많은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"넓은 모래사장이 펼쳐져 있어서","correct":true},{"t":"갯벌이 넓게 발달해서","mis":"SO5-1-u1-X07"},{"t":"섬이 아주 많아서","mis":"SO5-1-u1-X07"},{"t":"해안선이 복잡해서","mis":"SO5-1-u1-X07"}],"explanation":["해수욕장은 모래사장이 있어야 해요.","동해안은 모래사장이 넓어요.","그래서 해수욕장이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#8','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'mc','auto','파도가 오랜 시간 바위를 깎아 만든 절벽과 동굴을 볼 수 있는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"파도가 오랜 시간 바위를 깎아 만든 절벽과 동굴을 볼 수 있는 곳은 어느 것인가요?","options":[{"t":"해안 절벽이 있는 바닷가","correct":true},{"t":"넓은 평야","mis":"SO5-1-u1-X09"},{"t":"높은 산지","mis":"SO5-1-u1-X09"},{"t":"넓은 모래사장","mis":"SO5-1-u1-X08"}],"explanation":["파도는 바위를 깎아요.","오랜 시간이 지나면 절벽과 동굴이 생겨요.","해안이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#9','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',2,'ox','auto','해안의 모습이 다르면 그곳 사람들의 생활도 달라져요.',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"ox","stem":"해안의 모습이 다르면 그곳 사람들의 생활도 달라져요.","answer":"O","reason_options":[{"t":"갯벌에서는 해산물을 얻고 모래사장에서는 해수욕을 하는 것처럼 지형에 맞게 생활하기 때문에","correct":true},{"t":"해안 사람들은 모두 똑같이 생활하기 때문에","mis":"SO5-1-u1-X08"}],"mis":"SO5-1-u1-X08","explanation":["갯벌이 있으면 조개를 캐요.","모래사장이 있으면 해수욕장이 생겨요.","지형에 따라 생활이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_basic#10','soc',5,1,'u1','L04','g5_1_soc_u1_L04_basic','lesson_basic','SO5-1-u1-C4',3,'mc','auto','해안 특징 카드 가운데 서해안이나 남해안의 모습에 해당하지 않는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"해안 특징 카드 가운데 서해안이나 남해안의 모습에 해당하지 않는 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉡","mis":"SO5-1-u1-X07"},{"t":"㉤","mis":"SO5-1-u1-X08"},{"t":"㉥","mis":"SO5-1-u1-X07"}],"explanation":["㉣은 넓은 모래사장과 해수욕장이에요.","이는 동해안의 모습이에요.","나머지는 서해안·남해안의 모습이에요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#1','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',2,'sa','auto','바닷물이 드나드는 곳에 쌓인 진흙 땅으로, 물이 빠지면 조개 등을 잡을 수 있는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"sa","stem":"바닷물이 드나드는 곳에 쌓인 진흙 땅으로, 물이 빠지면 조개 등을 잡을 수 있는 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["갯벌"],"explanation":["서해안에 넓게 발달했어요.","진흙 땅이에요.","갯벌이에요."],"mis":"SO5-1-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#2','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',2,'mc','auto','지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 활용하려고 국제기구가 인증하는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X09']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 활용하려고 국제기구가 인증하는 곳은 어느 것인가요?","options":[{"t":"세계 지질 공원","correct":true},{"t":"놀이공원","mis":"SO5-1-u1-X10"},{"t":"광물을 캐는 광산","mis":"SO5-1-u1-X10"},{"t":"해수욕장","mis":"SO5-1-u1-X09"}],"explanation":["지질적 가치가 뛰어난 곳이에요.","국제기구가 인증해요.","우리나라는 제주가 처음 받았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#3','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'mc','auto','해안 특징 카드 ㉤처럼 진흙 땅을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"해안 특징 카드 ㉤처럼 진흙 땅을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?","options":[{"t":"갯벌이 넓은 서해안","correct":true},{"t":"모래사장이 넓은 동해안","mis":"SO5-1-u1-X07"},{"t":"해안선이 단순한 동해안","mis":"SO5-1-u1-X07"},{"t":"높은 산지","mis":"SO5-1-u1-X09"}],"explanation":["㉤은 갯벌을 막는 일이에요.","갯벌은 서해안에 넓어요.","이 일을 간척이라고 해요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#4','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'mc','auto','지도에서 해안선을 따라 그릴 때 동해안이 서해안보다 그리기 쉬운 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"지도에서 해안선을 따라 그릴 때 동해안이 서해안보다 그리기 쉬운 까닭은 무엇인가요?","options":[{"t":"동해안은 해안선의 굴곡이 적고 섬도 적기 때문에","correct":true},{"t":"동해안은 섬이 아주 많기 때문에","mis":"SO5-1-u1-X07"},{"t":"동해안은 해안선이 들쭉날쭉하기 때문에","mis":"SO5-1-u1-X07"},{"t":"동해안은 바다와 맞닿아 있지 않기 때문에","mis":"SO5-1-u1-X07"}],"explanation":["동해안은 곧게 뻗었어요.","섬도 적어요.","그래서 따라 그리기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#5','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'ox','auto','같은 바닷가라도 동해안과 서해안은 바닥이 모래인지 진흙인지가 다를 수 있어요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"ox","stem":"같은 바닷가라도 동해안과 서해안은 바닥이 모래인지 진흙인지가 다를 수 있어요.","answer":"O","reason_options":[{"t":"동해안은 모래사장이, 서해안은 갯벌이 넓게 발달했기 때문에","correct":true},{"t":"우리나라 바닷가는 모두 같은 모래로 되어 있기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["동해안 — 모래사장이에요.","서해안 — 갯벌이에요.","바닥이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#6','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'error','auto','해안을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"error","stem":"해안을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「동해안은 섬이 아주 많아서 다도해라고 불러.」","correct":true,"mis_target":"SO5-1-u1-X07"},{"t":"소율 — 「남해안은 섬이 많고 해안선이 복잡해.」","mis":"SO5-1-u1-X07"},{"t":"지후 — 「서해안 갯벌에서는 해산물을 얻어.」","mis":"SO5-1-u1-X08"}],"explanation":["다도해는 남해안을 부르는 말이에요.","동해안은 섬이 적어요.","그래서 하람이의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#7','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',3,'mc','auto','넓은 갯벌과 갈대밭이 펼쳐진 습지에 사람들이 찾아가는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"넓은 갯벌과 갈대밭이 펼쳐진 습지에 사람들이 찾아가는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해안이 만든 독특하고 아름다운 경관을 보려고","correct":true},{"t":"높은 산봉우리를 오르려고","mis":"SO5-1-u1-X09"},{"t":"지평선이 보이는 논에서 농사를 지으려고","mis":"SO5-1-u1-X09"},{"t":"파도가 깎은 동굴에 들어가려고","mis":"SO5-1-u1-X08"}],"explanation":["갯벌과 갈대밭은 해안에 있어요.","독특하고 아름다워요.","그래서 관광지가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#8','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',4,'mc','auto','서핑을 하러 오는 사람이 많은 바닷가가 어느 바다에 있을지 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"mc","stem":"서핑을 하러 오는 사람이 많은 바닷가가 어느 바다에 있을지 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"모래사장이 넓고 파도를 타기 좋은 바다가 탁 트인 동해안","correct":true},{"t":"물이 빠지면 진흙 땅이 넓게 드러나는 서해안","mis":"SO5-1-u1-X08"},{"t":"섬이 아주 많아 바다가 섬에 가려진 남해안","mis":"SO5-1-u1-X07"},{"t":"바다와 맞닿지 않은 산지","mis":"SO5-1-u1-X09"}],"explanation":["서핑은 모래사장과 파도가 필요해요.","동해안은 모래사장이 넓어요.","서해안은 물이 빠지면 갯벌이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#9','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',4,'mc','auto','해안 특징 카드 여섯 장을 동해안과 「서해안·남해안」 두 바구니에 나눌 때 바르게 나눈 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"mc","stem":"해안 특징 카드 여섯 장을 동해안과 「서해안·남해안」 두 바구니에 나눌 때 바르게 나눈 것은 어느 것인가요?","options":[{"t":"동해안 — ㉠·㉣ / 서해안·남해안 — ㉡·㉢·㉤·㉥","correct":true},{"t":"동해안 — ㉠·㉡ / 서해안·남해안 — ㉢·㉣·㉤·㉥","mis":"SO5-1-u1-X07"},{"t":"동해안 — ㉢·㉥ / 서해안·남해안 — ㉠·㉡·㉣·㉤","mis":"SO5-1-u1-X07"},{"t":"동해안 — ㉣·㉤ / 서해안·남해안 — ㉠·㉡·㉢·㉥","mis":"SO5-1-u1-X08"}],"explanation":["단순한 해안선과 모래사장은 동해안이에요.","갯벌·섬·간척·들쭉날쭉한 해안선은 서·남해안이에요.","두 바구니로 나눠요."],"asset":{"type":"passage","lines":["㉠ 해안선이 곧게 뻗어 지도에 따라 그리기 쉽다.","㉡ 바닷물이 빠지면 넓은 진흙 땅이 드러난다.","㉢ 섬이 아주 많아 다도해라고도 부른다.","㉣ 넓은 모래사장에 해수욕장이 많다.","㉤ 진흙 땅을 막아 논이나 공장 땅으로 쓰기도 한다.","㉥ 해안선이 들쭉날쭉해 따라 그리기 어렵다."],"title":"해안 특징 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L04_challenge#10','soc',5,1,'u1','L04','g5_1_soc_u1_L04_challenge','lesson_challenge','SO5-1-u1-C4',4,'essay','teacher','동해안과 서해안의 모습을 해안선과 바닷가 땅(모래사장·갯벌)으로 견주어 쓰고, 그 차이가 사람들의 생활에 어떻게 나타나는지 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"essay","stem":"동해안과 서해안의 모습을 해안선과 바닷가 땅(모래사장·갯벌)으로 견주어 쓰고, 그 차이가 사람들의 생활에 어떻게 나타나는지 하나씩 쓰세요.","answer_guide":{"answer":"예: 동해안은 해안선이 단순하고 넓은 모래사장이 펼쳐져 있다. 서해안은 해안선이 복잡하고 섬이 많으며 넓은 갯벌이 발달했다. 그래서 동해안에는 해수욕장이 많아 여름에 사람들이 해수욕을 즐기고, 서해안에서는 갯벌에서 조개 같은 해산물을 얻거나 갯벌을 막아 땅으로 쓰기도 한다.","scoring_points":["해안선을 견주었는가","모래사장과 갯벌을 바르게 짝지었는가","두 해안의 생활 모습을 썼는가"]},"explanation":["동해안 — 단순·모래사장이에요.","서해안 — 복잡·갯벌이에요.","생활도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#1','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',1,'mc','auto','국토 여행 계획을 세울 때 가장 먼저 할 일은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"국토 여행 계획을 세울 때 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"어떤 주제로 여행할지 정한다","correct":true},{"t":"친구 계획서에 댓글을 단다","mis":"SO5-1-u1-X11"},{"t":"여행지를 화살표로 잇는다","mis":"SO5-1-u1-X11"},{"t":"계획서를 사진으로 찍어 올린다","mis":"SO5-1-u1-X11"}],"explanation":["무엇을 보러 갈지 먼저 정해요.","그래야 어디를 조사할지 알아요.","주제 → 조사 → 경로 → 공유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#2','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',1,'mc','auto','가고 싶은 여행지를 조사할 때 이용하기에 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"가고 싶은 여행지를 조사할 때 이용하기에 알맞은 것은 어느 것인가요?","options":[{"t":"여행 정보 누리집","correct":true},{"t":"학교 시간표","mis":"SO5-1-u1-X11"},{"t":"가족 앨범","mis":"SO5-1-u1-X11"},{"t":"오늘의 일기 예보","mis":"SO5-1-u1-X11"}],"explanation":["누리집에서 여행지를 찾아요.","자연과 관련 있는 곳을 살펴봐요.","지역 누리집도 찾아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#3','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C5',1,'sa','auto','지질 공원을 안내하고 그곳의 지질·지형·자연·역사를 알기 쉽게 설명해 주는 사람을 무엇이라고 하나요? (□□ □□ □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"sa","stem":"지질 공원을 안내하고 그곳의 지질·지형·자연·역사를 알기 쉽게 설명해 주는 사람을 무엇이라고 하나요? (□□ □□ □□□)","answer":["지질 공원 해설사","지질공원 해설사","지질공원해설사"],"explanation":["지질 공원에서 일해요.","지형과 역사를 엮어 설명해요.","지질 공원 해설사예요."],"mis":"SO5-1-u1-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#4','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C1',1,'ox','auto','산지·하천·평야·해안처럼 다양한 땅의 생김새를 지형이라고 해요.',ARRAY['SO5-1-u1-X01']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"산지·하천·평야·해안처럼 다양한 땅의 생김새를 지형이라고 해요.","answer":"O","reason_options":[{"t":"지형은 땅의 생김새를 가리키는 말이기 때문에","correct":true},{"t":"지형은 그 지역의 날씨를 가리키는 말이기 때문에","mis":"SO5-1-u1-X01"}],"mis":"SO5-1-u1-X01","explanation":["땅의 생김새가 지형이에요.","우리 국토에는 여러 지형이 있어요.","네 갈래가 서로 이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#5','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',2,'mc','auto','조사한 여행지의 실제 모습을 확대해서 자세히 살펴볼 때 쓰기 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"조사한 여행지의 실제 모습을 확대해서 자세히 살펴볼 때 쓰기 알맞은 것은 어느 것인가요?","options":[{"t":"디지털 영상 지도","correct":true},{"t":"온도계","mis":"SO5-1-u1-X11"},{"t":"줄자","mis":"SO5-1-u1-X11"},{"t":"달력","mis":"SO5-1-u1-X11"}],"explanation":["영상 지도는 실제 모습을 보여 줘요.","확대해서 볼 수 있어요.","지형의 특징을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#6','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',2,'mc','auto','하율이의 여행 계획 메모를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"하율이의 여행 계획 메모를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉯ → ㉱ → ㉰ → ㉮","correct":true},{"t":"㉱ → ㉯ → ㉰ → ㉮","mis":"SO5-1-u1-X11"},{"t":"㉮ → ㉯ → ㉱ → ㉰","mis":"SO5-1-u1-X11"},{"t":"㉯ → ㉰ → ㉮ → ㉱","mis":"SO5-1-u1-X11"}],"explanation":["주제를 먼저 정해요(㉯).","조사하고(㉱), 경로를 이어요(㉰).","마지막에 나누고 댓글을 달아요(㉮)."],"asset":{"type":"passage","lines":["㉮ 친구 계획서에 느낀 점을 댓글로 남겼다.","㉯ 「세 바다의 해안을 견주어 보고 싶다」고 주제를 정했다.","㉰ 지도에 여행지를 표시하고 일정 순서대로 화살표로 이었다.","㉱ 여행 정보 누리집과 디지털 영상 지도로 여행지를 조사했다."],"title":"하율이의 여행 계획 메모(차례가 섞임)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#7','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',2,'mc','auto','제주도 안에서만 여행할 계획이라 우리나라 전체 지도에는 경로를 그리기 어려워요. 어떻게 하면 좋을까요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"제주도 안에서만 여행할 계획이라 우리나라 전체 지도에는 경로를 그리기 어려워요. 어떻게 하면 좋을까요?","options":[{"t":"그 지역만 크게 나타낸 백지도를 이용한다","correct":true},{"t":"여행 계획을 그만둔다","mis":"SO5-1-u1-X11"},{"t":"일부러 먼 곳을 끼워 넣는다","mis":"SO5-1-u1-X11"},{"t":"지도 없이 글로만 쓴다","mis":"SO5-1-u1-X11"}],"explanation":["한 지역 안의 경로는 작아요.","그 지역만 크게 나타낸 지도가 좋아요.","백지도를 내려받아 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#8','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C3',2,'ox','auto','우리나라는 동쪽이 높고 서쪽이 낮아서 큰 하천이 대부분 남쪽과 서쪽으로 흘러가요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"우리나라는 동쪽이 높고 서쪽이 낮아서 큰 하천이 대부분 남쪽과 서쪽으로 흘러가요.","answer":"O","reason_options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"하천은 땅의 높낮이와 상관없이 흐르기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["땅의 높낮이가 하천을 정해요.","물은 낮은 곳으로 흘러요.","그래서 남쪽과 서쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#9','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C5',2,'mc','auto','지질 공원 해설사가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"지질 공원 해설사가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지질 공원을 안내하고 훼손되지 않도록 관리한다","correct":true},{"t":"공원에 들어오는 사람을 모두 막는다","mis":"SO5-1-u1-X10"},{"t":"공원의 멋진 바위를 캐서 판다","mis":"SO5-1-u1-X10"},{"t":"날마다 날씨를 예보한다","mis":"SO5-1-u1-X01"}],"explanation":["해설사는 공원을 알려요.","알기 쉽게 설명해요.","공원이 망가지지 않게 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_basic#10','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',3,'mc','auto','친구의 여행 계획서에 댓글을 쓸 때의 태도로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"친구의 여행 계획서에 댓글을 쓸 때의 태도로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"재미있으라고 친구를 놀리는 말을 남긴다","correct":true},{"t":"보고 느낀 점을 예의 있게 쓴다","mis":"SO5-1-u1-X12"},{"t":"좋아 보이는 점을 찾아 칭찬한다","mis":"SO5-1-u1-X12"},{"t":"궁금한 점을 정중하게 묻는다","mis":"SO5-1-u1-X12"}],"explanation":["온라인에서도 예절을 지켜요.","놀리는 댓글은 상처를 줘요.","느낀 점과 칭찬을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#1','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',2,'mc','auto','「동해안·서해안·남해안의 모습을 견주어 보고 싶어」라는 생각에서 나올 여행 주제로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"「동해안·서해안·남해안의 모습을 견주어 보고 싶어」라는 생각에서 나올 여행 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"세 바다의 해안 지형을 찾아가는 여행","correct":true},{"t":"높은 산지만 골라 오르는 여행","mis":"SO5-1-u1-X11"},{"t":"하천을 따라 상류에서 하류까지 내려가는 여행","mis":"SO5-1-u1-X11"},{"t":"넓은 평야에서 농사 체험을 하는 여행","mis":"SO5-1-u1-X11"}],"explanation":["주제는 보고 싶은 것에서 나와요.","세 바다를 견주고 싶어 해요.","해안 지형 여행이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#2','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',2,'sa','auto','여행 계획서에서 여행지를 지도에 표시한 뒤 일정 순서대로 무엇으로 이어 여행 경로를 나타내나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"sa","stem":"여행 계획서에서 여행지를 지도에 표시한 뒤 일정 순서대로 무엇으로 이어 여행 경로를 나타내나요? 세 글자로 쓰세요.","answer":["화살표"],"explanation":["순서를 보여 줘요.","한쪽 끝이 뾰족해요.","화살표로 이어요."],"mis":"SO5-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#3','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',3,'mc','auto','여행 경로의 순서를 정할 때 가장 알맞게 생각한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X11']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"여행 경로의 순서를 정할 때 가장 알맞게 생각한 것은 어느 것인가요?","options":[{"t":"이동 거리가 너무 길어지지 않게, 여행의 목적에 맞추어 순서를 정한다","correct":true},{"t":"이름이 가장 긴 곳부터 간다","mis":"SO5-1-u1-X13"},{"t":"가장 먼 곳끼리 번갈아 간다","mis":"SO5-1-u1-X11"},{"t":"조사하지 않은 곳을 먼저 넣는다","mis":"SO5-1-u1-X11"}],"explanation":["동선이 길면 힘들어요.","목적에 맞게 순서를 정해요.","화살표로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#4','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',3,'mc','auto','완성한 여행 계획서를 공유 애플리케이션으로 나누면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11','SO5-1-u1-X12']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"완성한 여행 계획서를 공유 애플리케이션으로 나누면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"자리에 앉아서도 친구들의 계획서를 언제든 볼 수 있다","correct":true},{"t":"여행에 드는 돈이 줄어든다","mis":"SO5-1-u1-X11"},{"t":"계획서를 고칠 수 없게 잠긴다","mis":"SO5-1-u1-X11"},{"t":"댓글은 아무렇게나 써도 된다","mis":"SO5-1-u1-X12"}],"explanation":["사진으로 찍어 올려요.","앞에 나오지 않아도 돼요.","언제든 서로의 계획을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#5','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'ox','auto','지질 공원의 멋진 바위 조각은 기념으로 조금 떼어 와 간직해도 괜찮아요.',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"ox","stem":"지질 공원의 멋진 바위 조각은 기념으로 조금 떼어 와 간직해도 괜찮아요.","answer":"X","reason_options":[{"t":"오랜 시간이 만든 단 하나뿐인 자연이라 떼어 오면 되돌릴 수 없기 때문에","correct":true},{"t":"바위는 다시 금방 자라나기 때문에","mis":"SO5-1-u1-X10"}],"mis":"SO5-1-u1-X10","explanation":["바위와 지형은 오랜 시간이 만들었어요.","떼어 오면 되돌릴 수 없어요.","눈으로 보고 마음에 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#6','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'error','auto','지질 공원 해설사의 말을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"error","stem":"지질 공원 해설사의 말을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「해설사는 지형만 설명하고 마을의 옛이야기는 다루지 않아.」","correct":true,"mis_target":"SO5-1-u1-X10"},{"t":"예준 — 「바위 줄무늬가 생긴 까닭을 알기 쉽게 설명했어.」","mis":"SO5-1-u1-X10"},{"t":"다인 — 「공원이 훼손되지 않게 지키는 일도 해.」","mis":"SO5-1-u1-X10"}],"explanation":["해설사는 지질·지형·자연·역사를 엮어요.","소금 이야기는 역사예요.","그래서 라온이의 말이 틀렸어요."],"asset":{"type":"speech","turns":[{"who":"해설사","text":"이 바위 줄무늬는 아주 오랜 시간 동안 흙과 모래가 쌓여서 생겼어요."},{"who":"해설사","text":"옛날 이 마을 사람들은 이 바위 아래에서 소금을 말렸다고 해요."},{"who":"해설사","text":"바위를 만지거나 떼어 가면 다시 되돌릴 수 없으니 눈으로만 보아 주세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#7','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'mc','auto','지질 공원 해설사가 되려는 사람에게 필요한 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X13']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"mc","stem":"지질 공원 해설사가 되려는 사람에게 필요한 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공원 바위를 마음대로 가져갈 수 있는 힘","correct":true},{"t":"자연환경에 대한 꾸준한 관심","mis":"SO5-1-u1-X10"},{"t":"지질과 지형에 관한 정확한 지식","mis":"SO5-1-u1-X13"},{"t":"자연을 아끼고 사랑하는 마음","mis":"SO5-1-u1-X10"}],"explanation":["관심과 사랑하는 마음이 필요해요.","정확한 지식도 필요해요.","자연물을 가져가면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#8','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','주제 ①에서 배운 내용을 하나로 잇는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"주제 ①에서 배운 내용을 하나로 잇는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"땅의 높낮이 하나가 산지의 분포, 하천의 방향, 평야의 자리까지 정해 준다","correct":true},{"t":"산지·하천·평야는 서로 아무 관계가 없다","mis":"SO5-1-u1-X02"},{"t":"하천은 높낮이와 상관없이 동쪽으로 흐른다","mis":"SO5-1-u1-X05"},{"t":"평야는 높은 산지 위에 주로 펼쳐진다","mis":"SO5-1-u1-X06"}],"explanation":["높은 산은 북·동쪽이에요.","하천은 남·서쪽으로 흘러요.","하천 주변에 평야가 펼쳐져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#9','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',4,'mc','auto','「갯벌과 습지의 생물을 만나는 여행」을 주제로 정했어요. 이 주제에 가장 잘 어울리는 여행지 묶음은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"mc","stem":"「갯벌과 습지의 생물을 만나는 여행」을 주제로 정했어요. 이 주제에 가장 잘 어울리는 여행지 묶음은 어느 것인가요?","options":[{"t":"서해안의 갯벌 체험장과 남해안의 갯벌·갈대밭 습지","correct":true},{"t":"높은 산지의 목장과 바위 봉우리 산","mis":"SO5-1-u1-X09"},{"t":"동해안의 모래 해수욕장과 서핑 바닷가","mis":"SO5-1-u1-X08"},{"t":"지평선이 보이는 평야와 두 물줄기가 합쳐지는 강가","mis":"SO5-1-u1-X09"}],"explanation":["주제에 맞는 곳을 골라요.","갯벌은 서·남해안에 발달했어요.","습지에 갈대밭도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L05_challenge#10','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',4,'essay','teacher','자신만의 국토 여행 주제를 하나 정해 그 까닭을 쓰고, 여행지 두 곳을 어떤 지형인지와 함께 쓴 뒤, 계획을 친구들과 나눌 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"essay","stem":"자신만의 국토 여행 주제를 하나 정해 그 까닭을 쓰고, 여행지 두 곳을 어떤 지형인지와 함께 쓴 뒤, 계획을 친구들과 나눌 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 나의 여행 주제는 「하천을 따라 내려가는 여행」이다. 물이 어디서 시작해 어디로 흘러가는지 직접 보고 싶기 때문이다. 먼저 깊은 골짜기에 물과 폭포가 어우러진 계곡(하천)에 가고, 그다음 하천 주변에 펼쳐진 넓은 평야에 가겠다. 친구들과 나눌 때는 장난스러운 댓글 대신 느낀 점과 좋은 점을 예의 있게 쓰겠다.","scoring_points":["주제와 까닭을 썼는가","여행지 두 곳과 그 지형을 맞게 썼는가","온라인 예절을 썼는가"]},"explanation":["주제가 먼저예요.","여행지의 지형을 함께 써요.","나눌 때는 예절을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#1','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'mc','auto','독도는 우리나라 영토의 어느 쪽 끝에 있는 섬인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도는 우리나라 영토의 어느 쪽 끝에 있는 섬인가요?","options":[{"t":"동쪽 끝","correct":true},{"t":"서쪽 끝","mis":"SO5-1-u1-X14"},{"t":"남쪽 끝","mis":"SO5-1-u1-X14"},{"t":"북쪽 끝","mis":"SO5-1-u1-X14"}],"explanation":["독도는 동해에 있어요.","우리 영토의 동쪽 끝이에요.","동쪽 경계를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#2','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'mc','auto','독도가 있는 바다는 어느 것인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도가 있는 바다는 어느 것인가요?","options":[{"t":"동해","correct":true},{"t":"서해","mis":"SO5-1-u1-X14"},{"t":"남해","mis":"SO5-1-u1-X14"},{"t":"호수","mis":"SO5-1-u1-X14"}],"explanation":["독도는 동쪽 끝에 있어요.","그 바다는 동해예요.","동해는 세 나라에 둘러싸여 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#3','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'sa','auto','독도의 행정구역은 경상북도 어느 군인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"sa","stem":"독도의 행정구역은 경상북도 어느 군인가요? 세 글자로 쓰세요.","answer":["울릉군"],"explanation":["가까운 큰 섬의 이름을 따요.","경상북도에 속해요.","울릉군이에요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#4','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'ox','auto','독도에는 공항이 있어서 비행기로 바로 갈 수 있어요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"ox","stem":"독도에는 공항이 있어서 비행기로 바로 갈 수 있어요.","answer":"X","reason_options":[{"t":"독도에는 공항이 없어 배를 타고 울릉도를 거쳐 가야 하기 때문에","correct":true},{"t":"독도는 너무 가까워 걸어서 갈 수 있기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도에는 공항이 없어요.","동해안 항구에서 배를 타요.","울릉도를 거쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#5','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','독도 가는 길 찾기에서 ①과 ③ 사이에 들르는 섬은 어디인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도 가는 길 찾기에서 ①과 ③ 사이에 들르는 섬은 어디인가요?","options":[{"t":"울릉도","correct":true},{"t":"제주도","mis":"SO5-1-u1-X14"},{"t":"강화도","mis":"SO5-1-u1-X14"},{"t":"거제도","mis":"SO5-1-u1-X14"}],"explanation":["항구에서 배를 타요.","먼저 울릉도로 가요.","울릉도에서 다시 독도로 가요."],"asset":{"type":"passage","lines":["① 우리 학교에서 버스를 타고 동해안의 항구로 간다.","② 항구에서 배를 타고 울릉도로 간다.","③ 울릉도에서 다시 배를 타고 독도에 내린다."],"title":"독도 가는 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#6','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','인터넷 지도로 독도 가는 길을 찾을 때 도착지에 넣을 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11','SO5-1-u1-X14']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"인터넷 지도로 독도 가는 길을 찾을 때 도착지에 넣을 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"독도항","correct":true},{"t":"우리 학교","mis":"SO5-1-u1-X11"},{"t":"가까운 지하철역","mis":"SO5-1-u1-X11"},{"t":"동해안의 항구","mis":"SO5-1-u1-X14"}],"explanation":["출발지는 학교나 집이에요.","도착지는 마지막 목적지예요.","독도항을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#7','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','맑은 날 울릉도에서 독도를 눈으로 볼 수 있다는 사실이 알려 주는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15','SO5-1-u1-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"맑은 날 울릉도에서 독도를 눈으로 볼 수 있다는 사실이 알려 주는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"울릉도 사람들이 오래전부터 독도를 알고 우리 영토로 여겨 왔다","correct":true},{"t":"독도와 울릉도가 땅으로 이어져 있다","mis":"SO5-1-u1-X14"},{"t":"독도에는 사람이 살 수 없다","mis":"SO5-1-u1-X15"},{"t":"독도가 울릉도보다 크다","mis":"SO5-1-u1-X16"}],"explanation":["눈에 보일 만큼 가까웠어요.","그래서 옛날부터 알고 있었어요.","예로부터 우리 영토로 여겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#8','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'ox','auto','독도는 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요해요.',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"ox","stem":"독도는 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요해요.","answer":"O","reason_options":[{"t":"동해를 지나는 배와 비행기를 살필 수 있는 자리에 있기 때문에","correct":true},{"t":"독도에서는 농사를 많이 지을 수 있기 때문에","mis":"SO5-1-u1-X15"}],"mis":"SO5-1-u1-X15","explanation":["독도는 동해 한가운데에 있어요.","배와 비행기를 살필 수 있어요.","교통·군사 면에서 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#9','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',2,'mc','auto','독도가 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도가 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"높은 산이 많아 등산하기 좋다","correct":true},{"t":"주변 바다에 수산 자원과 천연자원이 풍부하다","mis":"SO5-1-u1-X15"},{"t":"동식물이 다양하고 지형이 독특해 연구 가치가 크다","mis":"SO5-1-u1-X15"},{"t":"우리나라 영토의 동쪽 경계를 알려 준다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 영토의 경계를 알려요.","교통·군사·연구·자원 면에서 중요해요.","등산 때문에 중요한 곳이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_basic#10','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',3,'mc','auto','다른 나라 사람이 독도에 가려면 어떻게 해야 하나요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"다른 나라 사람이 독도에 가려면 어떻게 해야 하나요?","options":[{"t":"우리나라에 들어와 우리와 같은 방법으로 배를 타고 울릉도를 거쳐 간다","correct":true},{"t":"자기 나라에서 비행기로 독도에 바로 내린다","mis":"SO5-1-u1-X14"},{"t":"어느 나라에서든 마음대로 배를 타고 바로 간다","mis":"SO5-1-u1-X14"},{"t":"다른 나라 사람은 독도에 갈 수 없다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 우리 영토예요.","그래서 우리나라를 거쳐 가요.","가는 길에도 영토의 뜻이 담겨 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#1','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',2,'mc','auto','독도 안내 카드에서 독도가 교통과 군사 면에서 중요하다는 것을 알려 주는 줄은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도 안내 카드에서 독도가 교통과 군사 면에서 중요하다는 것을 알려 주는 줄은 어느 것인가요?","options":[{"t":"동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아","correct":true},{"t":"행정구역 — 경상북도 울릉군","mis":"SO5-1-u1-X15"},{"t":"공항 — 없다","mis":"SO5-1-u1-X14"},{"t":"울릉도와의 거리 — 87.4 km","mis":"SO5-1-u1-X14"}],"explanation":["세 나라가 동해를 둘러싸요.","많은 배와 비행기가 지나가요.","그래서 교통·군사 면에서 중요해요."],"asset":{"type":"passage","lines":["위치 — 우리나라 영토의 동쪽 끝, 동해","행정구역 — 경상북도 울릉군","울릉도와의 거리 — 87.4 km","맑은 날 — 울릉도 전망대에서 눈으로 보인다","공항 — 없다","동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아"],"title":"독도 안내 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#2','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',2,'sa','auto','배가 바다에서 다니는 길로, 지도에 점선으로 나타내는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"sa","stem":"배가 바다에서 다니는 길로, 지도에 점선으로 나타내는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["항로"],"explanation":["배가 다니는 길이에요.","지도에 점선으로 그려요.","항로라고 해요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#3','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'mc','auto','독도 안내 카드에서 「예로부터 독도를 우리 영토로 여겨 왔다」는 근거가 되는 줄은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"독도 안내 카드에서 「예로부터 독도를 우리 영토로 여겨 왔다」는 근거가 되는 줄은 어느 것인가요?","options":[{"t":"맑은 날 — 울릉도 전망대에서 눈으로 보인다","correct":true},{"t":"공항 — 없다","mis":"SO5-1-u1-X14"},{"t":"동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아","mis":"SO5-1-u1-X15"},{"t":"위치 — 우리나라 영토의 동쪽 끝, 동해","mis":"SO5-1-u1-X14"}],"explanation":["눈으로 보이면 존재를 알 수 있어요.","울릉도 사람들이 오래전부터 알았어요.","그래서 우리 영토로 여겼어요."],"asset":{"type":"passage","lines":["위치 — 우리나라 영토의 동쪽 끝, 동해","행정구역 — 경상북도 울릉군","울릉도와의 거리 — 87.4 km","맑은 날 — 울릉도 전망대에서 눈으로 보인다","공항 — 없다","동해를 둘러싼 나라 — 우리나라 · 일본 · 러시아"],"title":"독도 안내 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#4','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'mc','auto','독도 주변 바다가 어업을 하는 우리 국민에게 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"독도 주변 바다가 어업을 하는 우리 국민에게 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고기를 잡는 국민을 보호하고 배가 급할 때 대피할 수도 있기 때문에","correct":true},{"t":"독도에서는 바다에 나갈 수 없기 때문에","mis":"SO5-1-u1-X15"},{"t":"독도 주변에는 물고기가 살지 않기 때문에","mis":"SO5-1-u1-X16"},{"t":"독도에 큰 공항이 있기 때문에","mis":"SO5-1-u1-X14"}],"explanation":["독도는 바다 한가운데의 섬이에요.","어업하는 국민을 지켜 줘요.","급할 때 배가 피할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#5','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'ox','auto','독도에 가는 길을 찾을 때 항구 이름을 모두 외워야 독도까지 갈 수 있어요.',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"ox","stem":"독도에 가는 길을 찾을 때 항구 이름을 모두 외워야 독도까지 갈 수 있어요.","answer":"X","reason_options":[{"t":"항구 이름보다 동해안 항구에서 배를 타고 울릉도를 거쳐 가는 방법을 이해하는 것이 중요하기 때문에","correct":true},{"t":"독도에 가는 길은 하나도 정해져 있지 않기 때문에","mis":"SO5-1-u1-X13"}],"mis":"SO5-1-u1-X13","explanation":["외우기보다 방법을 이해해요.","항구 → 울릉도 → 독도예요.","배를 타고 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#6','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'error','auto','독도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"error","stem":"독도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「독도는 우리나라 영토의 서쪽 끝에 있는 섬이야.」","correct":true,"mis_target":"SO5-1-u1-X14"},{"t":"채원 — 「독도는 경상북도 울릉군에 속해.」","mis":"SO5-1-u1-X14"},{"t":"로하 — 「독도는 우리 영토의 경계를 알려 줘.」","mis":"SO5-1-u1-X15"}],"explanation":["독도는 동쪽 끝에 있어요.","동해에 있는 섬이에요.","서쪽이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#7','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',3,'match','auto','독도가 중요한 까닭과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"match","stem":"독도가 중요한 까닭과 그 내용을 알맞게 이으세요.","pairs":[{"l":"영토","r":"우리 영토의 동쪽 경계를 알려 준다"},{"l":"교통·군사","r":"동해를 지나는 배와 비행기를 살필 수 있다"},{"l":"연구","r":"다양한 동식물과 독특한 지형이 있다"},{"l":"자원","r":"주변 바다에 수산 자원과 천연자원이 풍부하다"}],"mis":"SO5-1-u1-X15","explanation":["동쪽 끝이라 경계예요.","바다 한가운데라 교통·군사예요.","동식물·지형은 연구, 바다는 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#8','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',4,'mc','auto','독도 안내 카드의 「공항 — 없다」와 「독도 가는 길 찾기」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"mc","stem":"독도 안내 카드의 「공항 — 없다」와 「독도 가는 길 찾기」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누구든 동해안 항구에서 배를 타고 울릉도를 거쳐야 하므로 독도로 가는 길이 우리나라를 지난다","correct":true},{"t":"독도에는 아무도 갈 수 없다","mis":"SO5-1-u1-X14"},{"t":"독도는 일본 쪽에서만 갈 수 있다","mis":"SO5-1-u1-X14"},{"t":"독도는 비행기로 가는 것이 가장 빠르다","mis":"SO5-1-u1-X14"}],"explanation":["공항이 없어 배를 타요.","항구 → 울릉도 → 독도예요.","가는 길이 우리나라를 지나요."],"asset":{"type":"passage","lines":["① 우리 학교에서 버스를 타고 동해안의 항구로 간다.","② 항구에서 배를 타고 울릉도로 간다.","③ 울릉도에서 다시 배를 타고 독도에 내린다."],"title":"독도 가는 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#9','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',4,'mc','auto','독도가 「동해를 지나는 배와 비행기를 살필 수 있는 최전방」이라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"mc","stem":"독도가 「동해를 지나는 배와 비행기를 살필 수 있는 최전방」이라는 말의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 가장 동쪽 바다 위에서 먼저 살피고 지키는 자리라는 뜻","correct":true},{"t":"사람이 가장 많이 사는 곳이라는 뜻","mis":"SO5-1-u1-X15"},{"t":"비행기가 내리는 큰 공항이라는 뜻","mis":"SO5-1-u1-X14"},{"t":"관광객이 가장 많이 찾는 곳이라는 뜻","mis":"SO5-1-u1-X15"}],"explanation":["최전방은 맨 앞이에요.","독도는 동쪽 맨 끝이에요.","먼저 살피고 지키는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L07_challenge#10','soc',5,1,'u1','L07','g5_1_soc_u1_L07_challenge','lesson_challenge','SO5-1-u1-C7',4,'essay','teacher','독도의 위치를 쓰고, 독도가 중요한 까닭을 두 가지 쓴 뒤, 우리 학교에서 독도까지 가는 길을 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"essay","stem":"독도의 위치를 쓰고, 독도가 중요한 까닭을 두 가지 쓴 뒤, 우리 학교에서 독도까지 가는 길을 차례대로 쓰세요.","answer_guide":{"answer":"예: 독도는 우리나라 영토의 동쪽 끝, 동해에 있는 섬이고 행정구역은 경상북도 울릉군이다. 독도는 우리 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요하다. 학교에서 동해안의 항구로 간 다음, 배를 타고 울릉도로 가서 다시 배를 타고 독도에 간다.","scoring_points":["위치를 바르게 썼는가","중요한 까닭을 두 가지 썼는가","항구 → 울릉도 → 독도의 차례를 썼는가"]},"explanation":["동쪽 끝·동해예요.","경계·교통·군사·연구·자원이에요.","배로 울릉도를 거쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#1','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'mc','auto','독도를 이루는 두 개의 큰 섬은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"독도를 이루는 두 개의 큰 섬은 어느 것인가요?","options":[{"t":"동도와 서도","correct":true},{"t":"남도와 북도","mis":"SO5-1-u1-X16"},{"t":"큰섬과 작은섬","mis":"SO5-1-u1-X16"},{"t":"본섬과 끝섬","mis":"SO5-1-u1-X16"}],"explanation":["동쪽 섬과 서쪽 섬이에요.","동도와 서도라고 해요.","주변에 바위섬도 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#2','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'mc','auto','독도는 오래전 바닷속에서 일어난 무슨 활동으로 만들어졌나요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"독도는 오래전 바닷속에서 일어난 무슨 활동으로 만들어졌나요?","options":[{"t":"화산 활동","correct":true},{"t":"빙하 활동","mis":"SO5-1-u1-X16"},{"t":"바람의 활동","mis":"SO5-1-u1-X16"},{"t":"사람의 공사","mis":"SO5-1-u1-X16"}],"explanation":["바닷속에서 화산이 터졌어요.","그래서 독도가 생겼어요.","독특한 지형이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#3','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'sa','auto','자연환경과 생태계를 보호하려고 우리나라가 독도 전체를 무엇으로 지정했나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"sa","stem":"자연환경과 생태계를 보호하려고 우리나라가 독도 전체를 무엇으로 지정했나요? 다섯 글자로 쓰세요.","answer":["천연기념물"],"explanation":["자연을 보호하는 이름이에요.","바위 하나가 아니라 섬 전체예요.","천연기념물이에요."],"mis":"SO5-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#4','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',1,'ox','auto','독도 주변 바다는 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이뤄요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"ox","stem":"독도 주변 바다는 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이뤄요.","answer":"O","reason_options":[{"t":"두 바닷물이 만나는 곳에 여러 해양 생물이 살기 좋기 때문에","correct":true},{"t":"독도 주변 바다에는 바닷물이 흐르지 않기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["차가운 물과 따뜻한 물이 만나요.","해양 생물이 살기 좋아요.","그래서 좋은 어장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#5','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','독도의 날씨를 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"독도의 날씨를 바르게 말한 것은 어느 것인가요?","options":[{"t":"대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다","correct":true},{"t":"일 년 내내 눈이 쌓여 있다","mis":"SO5-1-u1-X16"},{"t":"비가 한 방울도 오지 않는다","mis":"SO5-1-u1-X16"},{"t":"여름에만 바람이 분다","mis":"SO5-1-u1-X16"}],"explanation":["독도는 대체로 온화해요.","바다 한가운데라 안개가 잦아요.","겨울에는 눈이 많이 내려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#6','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','「불타는 얼음」이라고도 불리며 미래 에너지 자원으로 주목받는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"「불타는 얼음」이라고도 불리며 미래 에너지 자원으로 주목받는 것은 어느 것인가요?","options":[{"t":"가스 하이드레이트","correct":true},{"t":"해양 심층수","mis":"SO5-1-u1-X16"},{"t":"해조류","mis":"SO5-1-u1-X16"},{"t":"바닷모래","mis":"SO5-1-u1-X16"}],"explanation":["고체로 된 천연가스예요.","바다 밑바닥에 묻혀 있어요.","가스 하이드레이트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#7','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','해양 심층수를 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"해양 심층수를 바르게 말한 것은 어느 것인가요?","options":[{"t":"수심 200 m 아래의 바닷물로 영양분이 많아 음료·식품 등에 쓰인다","correct":true},{"t":"바다 위에 떠 있는 얼음이다","mis":"SO5-1-u1-X16"},{"t":"바닷가의 모래를 뜻한다","mis":"SO5-1-u1-X16"},{"t":"바닷물이 얼어붙은 것이다","mis":"SO5-1-u1-X16"}],"explanation":["깊은 바다의 물이에요.","수심 200 m 아래예요.","영양분이 많아 여러 곳에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#8','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'ox','auto','독도 바위의 이름은 그 바위가 닮은 모습에서 온 것이 많아요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"ox","stem":"독도 바위의 이름은 그 바위가 닮은 모습에서 온 것이 많아요.","answer":"O","reason_options":[{"t":"물속에 코를 넣은 코끼리를 닮은 바위를 코끼리바위라고 부르는 것처럼 모양을 보고 이름을 지었기 때문에","correct":true},{"t":"바위 이름은 바위를 찾은 사람의 이름을 그대로 붙였기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["바위마다 닮은 모습이 있어요.","코끼리·촛대·한반도 모양이에요.","모양에서 이름이 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#9','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',2,'mc','auto','독도 자연 카드에서 독도의 경제적 가치를 보여 주는 줄을 모두 고른 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"독도 자연 카드에서 독도의 경제적 가치를 보여 주는 줄을 모두 고른 것은 어느 것인가요?","options":[{"t":"바다(좋은 어장)와 깊은 바다(해양 심층수·가스 하이드레이트)","correct":true},{"t":"생김새와 날씨","mis":"SO5-1-u1-X16"},{"t":"만들어진 까닭과 보호","mis":"SO5-1-u1-X16"},{"t":"날씨와 보호","mis":"SO5-1-u1-X16"}],"explanation":["어장에서 물고기를 잡아요.","해양 심층수와 가스 하이드레이트는 자원이에요.","이것이 경제적 가치예요."],"asset":{"type":"passage","lines":["생김새 — 큰 섬 둘(동도·서도)과 크고 작은 바위섬","만들어진 까닭 — 오래전 바닷속 화산 활동","날씨 — 대체로 온화하나 안개가 잦고 흐린 날이 많다","바다 — 차가운 물과 따뜻한 물이 만나는 좋은 어장","깊은 바다 — 해양 심층수 · 바다 밑 — 가스 하이드레이트","보호 — 독도 전체를 천연기념물로 지정"],"title":"독도 자연 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_basic#10','soc',5,1,'u1','L08','g5_1_soc_u1_L08_basic','lesson_basic','SO5-1-u1-C8',3,'mc','auto','우리나라가 독도 전체를 천연기념물로 지정한 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"우리나라가 독도 전체를 천연기념물로 지정한 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"관광객을 더 많이 오게 하려고","correct":true},{"t":"다양한 동식물이 살고 있어서","mis":"SO5-1-u1-X16"},{"t":"화산섬이라 연구 가치가 커서","mis":"SO5-1-u1-X16"},{"t":"독특한 지형과 아름다운 경관을 지녀서","mis":"SO5-1-u1-X16"}],"explanation":["천연기념물은 보호하려고 정해요.","동식물·연구 가치·경관 때문이에요.","사람을 부르려는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#1','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',2,'sa','auto','독도 주변 깊은 바다에 있는 수심 200 m 아래의 바닷물로, 영양분이 많은 것을 무엇이라고 하나요? (□□ □□□)','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"sa","stem":"독도 주변 깊은 바다에 있는 수심 200 m 아래의 바닷물로, 영양분이 많은 것을 무엇이라고 하나요? (□□ □□□)","answer":["해양 심층수","해양심층수"],"explanation":["깊은 곳의 물이에요.","영양분이 많아요.","해양 심층수예요."],"mis":"SO5-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#2','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',2,'match','auto','독도의 바위와 이름이 온 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"match","stem":"독도의 바위와 이름이 온 모습을 알맞게 이으세요.","pairs":[{"l":"코끼리바위","r":"물속에 코를 넣은 코끼리"},{"l":"촛대바위","r":"바다에 솟은 촛대"},{"l":"탕건봉","r":"옛 선비가 갓 아래 받쳐 쓰던 탕건"},{"l":"한반도바위","r":"우리나라 땅 모양"}],"mis":"SO5-1-u1-X16","explanation":["바위는 닮은 모습으로 불려요.","코끼리·촛대·탕건 모양이 있어요.","한반도 모양 바위도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#3','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'mc','auto','독도에 독특한 지형과 아름다운 경관이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X06','SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도에 독특한 지형과 아름다운 경관이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바닷속 화산 활동으로 만들어진 섬이기 때문에","correct":true},{"t":"사람들이 바위를 깎아 꾸몄기 때문에","mis":"SO5-1-u1-X16"},{"t":"넓은 평야가 펼쳐져 있기 때문에","mis":"SO5-1-u1-X06"},{"t":"큰 하천이 섬 가운데를 흐르기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["독도는 화산섬이에요.","화산이 독특한 지형을 만들었어요.","그래서 경관이 아름다워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#4','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'mc','auto','독도 자연 카드의 「보호」 줄에서 바위 하나나 새 한 종이 아니라 「독도 전체」를 지정한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도 자연 카드의 「보호」 줄에서 바위 하나나 새 한 종이 아니라 「독도 전체」를 지정한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바위·새·식물·바다 생물이 함께 어우러진 생태계 전체를 지키려고","correct":true},{"t":"독도에는 바위 하나밖에 없어서","mis":"SO5-1-u1-X16"},{"t":"사람이 더 많이 찾아오게 하려고","mis":"SO5-1-u1-X16"},{"t":"새는 보호할 필요가 없어서","mis":"SO5-1-u1-X16"}],"explanation":["독도의 생물은 서로 이어져 있어요.","한 가지만 지키면 생태계가 무너져요.","그래서 전체를 지정했어요."],"asset":{"type":"passage","lines":["생김새 — 큰 섬 둘(동도·서도)과 크고 작은 바위섬","만들어진 까닭 — 오래전 바닷속 화산 활동","날씨 — 대체로 온화하나 안개가 잦고 흐린 날이 많다","바다 — 차가운 물과 따뜻한 물이 만나는 좋은 어장","깊은 바다 — 해양 심층수 · 바다 밑 — 가스 하이드레이트","보호 — 독도 전체를 천연기념물로 지정"],"title":"독도 자연 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#5','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'ox','auto','독도는 바다 한가운데에 있어서 안개가 자주 끼고 흐린 날이 많아요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"ox","stem":"독도는 바다 한가운데에 있어서 안개가 자주 끼고 흐린 날이 많아요.","answer":"O","reason_options":[{"t":"사방이 바다라 바다에서 올라온 물기로 안개가 자주 생기기 때문에","correct":true},{"t":"독도는 높은 산 위에 있어서 늘 맑기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["독도는 바다로 둘러싸여 있어요.","안개가 자주 끼어요.","흐린 날이 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#6','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'error','auto','독도의 자연환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"error","stem":"독도의 자연환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「독도는 땅이 넓고 평평해서 큰 목장이 있어.」","correct":true,"mis_target":"SO5-1-u1-X16"},{"t":"도윤 — 「괭이갈매기 같은 새가 살아.」","mis":"SO5-1-u1-X16"},{"t":"세아 — 「바위에 사철나무와 해국 같은 식물이 자라.」","mis":"SO5-1-u1-X16"}],"explanation":["독도는 바위섬이에요.","넓은 목장은 없어요.","새와 바위 식물이 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#7','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',3,'mc','auto','독도 주변 바다에 물고기가 많이 모이는 까닭과 가장 관계 깊은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도 주변 바다에 물고기가 많이 모이는 까닭과 가장 관계 깊은 것은 어느 것인가요?","options":[{"t":"차가운 바닷물과 따뜻한 바닷물이 만난다","correct":true},{"t":"바닷물이 아주 얕다","mis":"SO5-1-u1-X16"},{"t":"바다에 공항이 있다","mis":"SO5-1-u1-X14"},{"t":"파도가 전혀 치지 않는다","mis":"SO5-1-u1-X16"}],"explanation":["두 바닷물이 만나요.","먹이가 많아 물고기가 모여요.","좋은 어장이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#8','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',4,'mc','auto','독도 자연 카드의 여섯 줄을 「자연의 모습」과 「쓸모(가치)」로 나눌 때 「쓸모」에 들어갈 줄로만 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"mc","stem":"독도 자연 카드의 여섯 줄을 「자연의 모습」과 「쓸모(가치)」로 나눌 때 「쓸모」에 들어갈 줄로만 묶은 것은 어느 것인가요?","options":[{"t":"바다(어장) · 깊은 바다(해양 심층수·가스 하이드레이트)","correct":true},{"t":"생김새 · 만들어진 까닭","mis":"SO5-1-u1-X16"},{"t":"날씨 · 생김새","mis":"SO5-1-u1-X16"},{"t":"만들어진 까닭 · 날씨","mis":"SO5-1-u1-X16"}],"explanation":["생김새·까닭·날씨는 모습이에요.","어장과 자원은 쓸모예요.","보호는 지키는 일이에요."],"asset":{"type":"passage","lines":["생김새 — 큰 섬 둘(동도·서도)과 크고 작은 바위섬","만들어진 까닭 — 오래전 바닷속 화산 활동","날씨 — 대체로 온화하나 안개가 잦고 흐린 날이 많다","바다 — 차가운 물과 따뜻한 물이 만나는 좋은 어장","깊은 바다 — 해양 심층수 · 바다 밑 — 가스 하이드레이트","보호 — 독도 전체를 천연기념물로 지정"],"title":"독도 자연 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#9','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',4,'mc','auto','「독도는 화산섬이라 연구 가치가 크다」는 말을 가장 알맞게 풀어 쓴 것은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14','SO5-1-u1-X10']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"mc","stem":"「독도는 화산섬이라 연구 가치가 크다」는 말을 가장 알맞게 풀어 쓴 것은 어느 것인가요?","options":[{"t":"바닷속 화산이 만든 지형과 그 위에 자리 잡은 생물을 살피면 땅과 생물의 오랜 변화를 알아낼 수 있다","correct":true},{"t":"화산섬이라 사람이 살기에 가장 편하다","mis":"SO5-1-u1-X16"},{"t":"화산섬이라 큰 공항을 짓기 좋다","mis":"SO5-1-u1-X14"},{"t":"화산섬이라 바위를 마음껏 떼어 가도 된다","mis":"SO5-1-u1-X10"}],"explanation":["화산섬은 특별한 지형이에요.","땅과 생물의 변화를 알 수 있어요.","그래서 연구 가치가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L08_challenge#10','soc',5,1,'u1','L08','g5_1_soc_u1_L08_challenge','lesson_challenge','SO5-1-u1-C8',4,'essay','teacher','독도의 자연환경 가운데 생김새와 만들어진 까닭을 쓰고, 독도 주변 바다의 경제적 가치를 두 가지 쓴 뒤, 독도 전체를 천연기념물로 지정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"essay","stem":"독도의 자연환경 가운데 생김새와 만들어진 까닭을 쓰고, 독도 주변 바다의 경제적 가치를 두 가지 쓴 뒤, 독도 전체를 천연기념물로 지정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 독도는 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌고, 오래전 바닷속 화산 활동으로 만들어졌다. 주변 바다는 차가운 물과 따뜻한 물이 만나 좋은 어장을 이루고, 깊은 바다에는 해양 심층수가, 바다 밑에는 가스 하이드레이트가 있다. 독도는 연구 가치가 크고 다양한 동식물이 사는 생태계를 지녔으므로, 이를 보호하려고 독도 전체를 천연기념물로 지정했다.","scoring_points":["생김새와 화산 활동을 썼는가","경제적 가치를 두 가지 썼는가","천연기념물 지정 까닭(보호)을 썼는가"]},"explanation":["동도·서도·바위섬이에요.","어장과 자원이에요.","생태계를 보호하려고 지정했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#1','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'mc','auto','우산국을 정벌해 우산국이 신라의 영토가 되게 한 신라의 장군은 누구인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"mc","stem":"우산국을 정벌해 우산국이 신라의 영토가 되게 한 신라의 장군은 누구인가요?","options":[{"t":"이사부","correct":true},{"t":"김유신","mis":"SO5-1-u1-X17"},{"t":"장보고","mis":"SO5-1-u1-X17"},{"t":"안용복","mis":"SO5-1-u1-X18"}],"explanation":["『삼국사기』에 남은 일이에요.","신라의 장군이 우산국을 정벌했어요.","이사부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#2','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'mc','auto','지금 남아 있는 우리나라 옛 지도 가운데 독도가 그려진 가장 오래된 지도는 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"mc","stem":"지금 남아 있는 우리나라 옛 지도 가운데 독도가 그려진 가장 오래된 지도는 어느 것인가요?","options":[{"t":"「팔도총도」","correct":true},{"t":"「삼국접양지도」","mis":"SO5-1-u1-X17"},{"t":"「조선왕국전도」","mis":"SO5-1-u1-X17"},{"t":"「태정관 지령」","mis":"SO5-1-u1-X17"}],"explanation":["우리나라가 만든 지도예요.","우산도(독도)가 그려져 있어요.","「팔도총도」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#3','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'sa','auto','대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 일을 기려 정한 「독도의 날」은 몇 월 며칠인가요? (□□월 □□일)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"sa","stem":"대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 일을 기려 정한 「독도의 날」은 몇 월 며칠인가요? (□□월 □□일)","answer":["10월 25일","10월25일"],"explanation":["가을에 있어요.","대한 제국의 칙령을 기려요.","10월 25일이에요."],"mis":"SO5-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#4','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',1,'ox','auto','독도는 옛날에 우산도·삼봉도·석도 같은 여러 이름으로 불렸어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"ox","stem":"독도는 옛날에 우산도·삼봉도·석도 같은 여러 이름으로 불렸어요.","answer":"O","reason_options":[{"t":"오래전부터 우리와 가까운 섬이어서 모습이나 특징을 보고 여러 이름을 붙였기 때문에","correct":true},{"t":"독도는 최근에 처음 발견되어 이름이 하나뿐이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["세 봉우리를 보고 삼봉도라고 불렀어요.","돌섬이라 석도라고도 했어요.","이름이 많을 만큼 가까운 섬이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#5','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','『세종실록지리지』에 적힌 내용으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X14','SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"『세종실록지리지』에 적힌 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 섬이 멀지 않아 맑은 날 서로 바라볼 수 있다","correct":true},{"t":"두 섬이 일본의 영토라고 적혀 있다","mis":"SO5-1-u1-X17"},{"t":"독도에는 아무도 갈 수 없다고 적혀 있다","mis":"SO5-1-u1-X14"},{"t":"독도의 넓이를 정확히 재어 적어 두었다","mis":"SO5-1-u1-X13"}],"explanation":["우산(독도)과 무릉(울릉도)이 나와요.","거리가 멀지 않다고 했어요.","맑으면 서로 보인다고 적었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#6','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','일본에서 만든 「삼국접양지도」에서 독도는 어느 나라와 같은 색으로 칠해져 있나요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"일본에서 만든 「삼국접양지도」에서 독도는 어느 나라와 같은 색으로 칠해져 있나요?","options":[{"t":"조선","correct":true},{"t":"일본","mis":"SO5-1-u1-X17"},{"t":"청나라","mis":"SO5-1-u1-X17"},{"t":"색이 칠해져 있지 않다","mis":"SO5-1-u1-X17"}],"explanation":["나라마다 색이 달라요.","독도는 울릉도와 함께 칠해졌어요.","조선과 같은 색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#7','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','독도에 관한 옛 자료 여섯 가운데 다른 나라가 만든 자료로만 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"독도에 관한 옛 자료 여섯 가운데 다른 나라가 만든 자료로만 묶은 것은 어느 것인가요?","options":[{"t":"㉣·㉤·㉥","correct":true},{"t":"㉠·㉡·㉢","mis":"SO5-1-u1-X17"},{"t":"㉠·㉣·㉥","mis":"SO5-1-u1-X17"},{"t":"㉡·㉢·㉤","mis":"SO5-1-u1-X17"}],"explanation":["괄호 안에 만든 나라가 있어요.","㉣·㉤은 일본, ㉥은 프랑스예요.","나머지는 우리나라 자료예요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#8','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'ox','auto','옛 지도에는 그때 사람들이 어디까지를 자기 나라 땅으로 여겼는지가 담겨 있어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"ox","stem":"옛 지도에는 그때 사람들이 어디까지를 자기 나라 땅으로 여겼는지가 담겨 있어요.","answer":"O","reason_options":[{"t":"지도를 그린 사람들의 영토 인식이 그대로 나타나기 때문에","correct":true},{"t":"옛 지도는 아무렇게나 그려서 아무 뜻이 없기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["옛 지도는 영토 인식을 보여 줘요.","그래서 영토의 역사를 알 수 있어요.","중요한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#9','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',2,'mc','auto','프랑스의 지리학자가 만든 「조선왕국전도」에 울릉도와 독도가 그려진 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"프랑스의 지리학자가 만든 「조선왕국전도」에 울릉도와 독도가 그려진 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"멀리 떨어진 유럽 사람들도 두 섬을 조선의 땅으로 알고 있었다","correct":true},{"t":"우리나라 사람만 독도를 알고 있었다","mis":"SO5-1-u1-X17"},{"t":"독도는 프랑스의 영토였다","mis":"SO5-1-u1-X17"},{"t":"옛날에는 동해에 섬이 없었다","mis":"SO5-1-u1-X17"}],"explanation":["유럽인이 만든 조선 지도예요.","울릉도와 독도가 그려져 있어요.","멀리서도 조선 땅으로 알았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_basic#10','soc',5,1,'u1','L09','g5_1_soc_u1_L09_basic','lesson_basic','SO5-1-u1-C9',3,'mc','auto','「돗토리번 답변서」와 「태정관 지령」이 특별한 증거가 되는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「돗토리번 답변서」와 「태정관 지령」이 특별한 증거가 되는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"일본이 스스로 만든 국가 문서에서 두 섬이 일본 땅이 아니라고 밝혔기 때문에","correct":true},{"t":"우리나라 사람이 일본에 가서 만든 문서이기 때문에","mis":"SO5-1-u1-X17"},{"t":"가장 오래된 옛 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"세계 여러 나라가 함께 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"explanation":["두 자료는 일본의 문서예요.","스스로 일본 땅이 아니라고 했어요.","그래서 더 분명한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#1','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',2,'sa','auto','신라 장군 이사부가 정벌해 신라의 영토가 된 울릉도와 독도 지역의 옛 나라 이름은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"sa","stem":"신라 장군 이사부가 정벌해 신라의 영토가 된 울릉도와 독도 지역의 옛 나라 이름은 무엇인가요? 세 글자로 쓰세요.","answer":["우산국"],"explanation":["『삼국사기』에 나와요.","신라 지증왕 때 항복했어요.","우산국이에요."],"mis":"SO5-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#2','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',2,'match','auto','옛 자료와 그 자료가 말해 주는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"match","stem":"옛 자료와 그 자료가 말해 주는 내용을 알맞게 이으세요.","pairs":[{"l":"『세종실록지리지』","r":"맑은 날 두 섬이 서로 보인다"},{"l":"「팔도총도」","r":"독도가 그려진 가장 오래된 우리 옛 지도"},{"l":"「삼국접양지도」","r":"독도를 조선과 같은 색으로 칠함"},{"l":"「태정관 지령」","r":"두 섬은 일본 땅이 아니라고 밝힘"}],"mis":"SO5-1-u1-X17","explanation":["『세종실록지리지』는 기록이에요.","「팔도총도」는 가장 오래된 우리 지도예요.","두 일본 자료도 조선 땅이라 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#3','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'mc','auto','독도에 관한 옛 자료 여섯에서 ㉡의 기록이 독도가 우리 땅이라는 증거가 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X17']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"독도에 관한 옛 자료 여섯에서 ㉡의 기록이 독도가 우리 땅이라는 증거가 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 사람들이 두 섬의 위치를 알고 우리 땅으로 기록했기 때문에","correct":true},{"t":"독도의 넓이가 정확히 적혀 있기 때문에","mis":"SO5-1-u1-X13"},{"t":"일본이 만든 기록이기 때문에","mis":"SO5-1-u1-X17"},{"t":"가장 최근에 만든 기록이기 때문에","mis":"SO5-1-u1-X17"}],"explanation":["㉡은 우리나라 기록이에요.","두 섬이 서로 보인다고 적었어요.","알고 있었고 우리 땅으로 여겼어요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#4','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'mc','auto','연합국 최고 사령관 각서의 부속 지도가 독도를 어떻게 나타냈나요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"연합국 최고 사령관 각서의 부속 지도가 독도를 어떻게 나타냈나요?","options":[{"t":"울릉도와 함께 일본에서 제외되는 섬으로 표시했다","correct":true},{"t":"일본의 섬으로 표시했다","mis":"SO5-1-u1-X17"},{"t":"러시아의 섬으로 표시했다","mis":"SO5-1-u1-X17"},{"t":"독도를 그리지 않았다","mis":"SO5-1-u1-X17"}],"explanation":["다른 나라가 만든 지도예요.","두 섬을 일본에서 뺐어요.","독도가 일본 땅이 아니라는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#5','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'ox','auto','옛 지도와 기록을 살펴볼 때는 자료에 적힌 연도를 빠짐없이 외우는 것이 가장 중요해요.',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"ox","stem":"옛 지도와 기록을 살펴볼 때는 자료에 적힌 연도를 빠짐없이 외우는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"누가 만들었고 무엇을 말하는지 읽어 내는 것이 더 중요하기 때문에","correct":true},{"t":"옛 자료에는 연도가 하나도 적혀 있지 않기 때문에","mis":"SO5-1-u1-X13"}],"mis":"SO5-1-u1-X13","explanation":["연도를 외우는 것이 목표가 아니에요.","만든 나라와 내용을 읽어요.","자료를 견주면 더 분명해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#6','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'error','auto','옛 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"error","stem":"옛 자료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「일본이 만든 자료는 독도와 아무 관계가 없으니 보지 않아도 돼.」","correct":true,"mis_target":"SO5-1-u1-X17"},{"t":"서아 — 「우리나라 자료와 다른 나라 자료를 함께 봐야 해.」","mis":"SO5-1-u1-X17"},{"t":"유찬 — 「자료가 어느 나라에서 만들어졌는지 살펴봐야 해.」","mis":"SO5-1-u1-X17"}],"explanation":["일본 자료도 독도를 조선 땅으로 나타냈어요.","그래서 더 분명한 증거예요.","여러 나라 자료를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#7','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',3,'mc','auto','「삼국접양지도」를 보고 「당시 일본에서도 독도를 조선의 영토로 여겼다」고 말할 수 있는 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「삼국접양지도」를 보고 「당시 일본에서도 독도를 조선의 영토로 여겼다」고 말할 수 있는 까닭은 무엇인가요?","options":[{"t":"일본이 만든 지도인데도 독도를 조선과 같은 색으로 칠했기 때문에","correct":true},{"t":"독도를 일본과 같은 색으로 칠했기 때문에","mis":"SO5-1-u1-X17"},{"t":"조선 사람이 만든 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"지도에 독도가 그려지지 않았기 때문에","mis":"SO5-1-u1-X17"}],"explanation":["나라마다 색으로 영토를 나눴어요.","독도는 조선 색이에요.","만든 나라가 일본이라 더 뜻깊어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#8','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',4,'mc','auto','독도에 관한 옛 자료 여섯을 모두 볼 때 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"독도에 관한 옛 자료 여섯을 모두 볼 때 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라 자료와 다른 나라 자료 모두 옛날부터 독도를 우리 땅으로 나타냈다","correct":true},{"t":"우리나라 자료만 독도를 우리 땅으로 나타냈다","mis":"SO5-1-u1-X17"},{"t":"독도는 옛 자료에 한 번도 나오지 않는다","mis":"SO5-1-u1-X17"},{"t":"옛 자료마다 독도를 다른 나라 땅으로 나타냈다","mis":"SO5-1-u1-X17"}],"explanation":["㉠~㉢은 우리 자료예요.","㉣~㉥은 다른 나라 자료예요.","모두 독도를 우리 땅으로 나타냈어요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#9','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',4,'mc','auto','독도가 우리 땅이라는 증거로 다른 나라가 만든 자료가 특히 힘이 있는 까닭을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"독도가 우리 땅이라는 증거로 다른 나라가 만든 자료가 특히 힘이 있는 까닭을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"자기 나라에 이로울 것이 없는데도 독도를 조선 땅으로 나타냈으니 믿을 만하기 때문에","correct":true},{"t":"다른 나라 자료는 언제나 우리 자료보다 오래되었기 때문에","mis":"SO5-1-u1-X13"},{"t":"다른 나라 자료는 그림이 더 예쁘기 때문에","mis":"SO5-1-u1-X17"},{"t":"다른 나라 자료는 연도가 더 정확하기 때문에","mis":"SO5-1-u1-X13"}],"explanation":["자기 땅이라고 할 수도 있었어요.","그런데도 조선 땅이라 했어요.","그래서 믿을 만한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L09_challenge#10','soc',5,1,'u1','L09','g5_1_soc_u1_L09_challenge','lesson_challenge','SO5-1-u1-C9',4,'essay','teacher','독도에 관한 옛 자료 여섯 가운데 우리나라 자료 하나와 다른 나라 자료 하나를 골라 무엇을 말하는지 쓰고, 두 자료를 함께 볼 때 알 수 있는 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"essay","stem":"독도에 관한 옛 자료 여섯 가운데 우리나라 자료 하나와 다른 나라 자료 하나를 골라 무엇을 말하는지 쓰고, 두 자료를 함께 볼 때 알 수 있는 점을 쓰세요.","answer_guide":{"answer":"예: 우리나라 자료인 「팔도총도」에는 울릉도와 함께 우산도(독도)가 그려져 있어 조선이 동해에 두 섬이 있음을 알고 있었음을 보여 준다. 일본이 만든 「삼국접양지도」는 독도를 조선과 같은 색으로 칠했다. 두 자료를 함께 보면 우리나라뿐 아니라 일본도 옛날부터 독도를 조선의 영토로 여겼음을 알 수 있다.","scoring_points":["우리나라 자료의 내용을 바르게 썼는가","다른 나라 자료의 내용을 바르게 썼는가","두 자료를 견주어 알 수 있는 점을 썼는가"]},"explanation":["우리 자료를 하나 골라요.","다른 나라 자료도 하나 골라요.","함께 보면 더 분명해요."],"asset":{"type":"passage","lines":["㉠ 『삼국사기』(우리나라) — 우산국이 신라에 항복한 일","㉡ 『세종실록지리지』(우리나라) — 맑은 날 두 섬이 서로 보인다","㉢ 「팔도총도」(우리나라) — 독도가 그려진 가장 오래된 우리 옛 지도","㉣ 「태정관 지령」(일본 국가 문서) — 두 섬은 일본 땅이 아니다","㉤ 「삼국접양지도」(일본) — 독도를 조선과 같은 색으로 칠함","㉥ 「조선왕국전도」(프랑스) — 동해에 울릉도와 독도를 그림"],"title":"독도에 관한 옛 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#1','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'mc','auto','조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명한 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"mc","stem":"조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명한 사람은 누구인가요?","options":[{"t":"안용복","correct":true},{"t":"최종덕","mis":"SO5-1-u1-X18"},{"t":"홍순칠","mis":"SO5-1-u1-X18"},{"t":"이사부","mis":"SO5-1-u1-X17"}],"explanation":["조선 시대 사람이에요.","일본에 건너가 설명했어요.","안용복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#2','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'mc','auto','독도로 주민 등록을 옮겨 최초의 독도 주민이 된 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"mc","stem":"독도로 주민 등록을 옮겨 최초의 독도 주민이 된 사람은 누구인가요?","options":[{"t":"최종덕","correct":true},{"t":"안용복","mis":"SO5-1-u1-X18"},{"t":"홍순칠","mis":"SO5-1-u1-X18"},{"t":"이사부","mis":"SO5-1-u1-X17"}],"explanation":["울릉도의 어부였어요.","독도에 사람이 산다는 것을 알렸어요.","최종덕이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#3','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'sa','auto','정부가 독도에 파견해 주민과 관광객의 편의와 안전을 지키게 한 경찰을 무엇이라고 하나요? (□□ □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"sa","stem":"정부가 독도에 파견해 주민과 관광객의 편의와 안전을 지키게 한 경찰을 무엇이라고 하나요? (□□ □□□)","answer":["독도 경비대","독도경비대"],"explanation":["독도에 머무는 경찰이에요.","안전을 지키고 해안을 경계해요.","독도 경비대예요."],"mis":"SO5-1-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#4','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',1,'ox','auto','인공지능으로 그림을 만들 때는 조건을 구체적이고 자세하게 나타낼수록 원하는 그림에 가까워져요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C11","difficulty":1,"kind":"ox","stem":"인공지능으로 그림을 만들 때는 조건을 구체적이고 자세하게 나타낼수록 원하는 그림에 가까워져요.","answer":"O","reason_options":[{"t":"조건이 자세해야 무엇을 어떻게 그릴지 또렷해지기 때문에","correct":true},{"t":"인공지능은 조건이 짧을수록 더 잘 알아듣기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["흐린 조건은 그림을 정해 주지 못해요.","모습과 행동까지 적어요.","자세할수록 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#5','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'mc','auto','홍순칠과 독도 의용 수비대가 독도 바위에 「한국령」을 새긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"홍순칠과 독도 의용 수비대가 독도 바위에 「한국령」을 새긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"독도가 우리 영토임을 알리고 지키려는 의지를 나타내려고","correct":true},{"t":"바위의 이름을 붙여 관광객을 모으려고","mis":"SO5-1-u1-X18"},{"t":"배가 길을 잃지 않도록 방향을 알려 주려고","mis":"SO5-1-u1-X18"},{"t":"바위의 높이를 재어 기록해 두려고","mis":"SO5-1-u1-X13"}],"explanation":["「한국령」은 한국의 영토라는 뜻이에요.","우리 땅임을 알렸어요.","지키겠다는 의지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#6','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'match','auto','독도를 지킨 사람들 카드를 보고 카드와 알맞은 이름을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"match","stem":"독도를 지킨 사람들 카드를 보고 카드와 알맞은 이름을 이으세요.","pairs":[{"l":"㉠","r":"안용복"},{"l":"㉡","r":"홍순칠"},{"l":"㉢","r":"최종덕"},{"l":"㉣","r":"독도 경비대"}],"mis":"SO5-1-u1-X18","explanation":["㉠은 조선 시대 일본에 건너갔어요.","㉡은 의용 수비대, ㉢은 첫 주민이에요.","㉣은 지금 독도를 지키는 경찰이에요."],"asset":{"type":"passage","lines":["㉠ 조선 시대에 두 차례 일본으로 건너가 두 섬이 조선 땅이라고 설명했다.","㉡ 울릉도 청년들과 의용 수비대를 만들어 독도를 지켰다.","㉢ 울릉도의 어부로, 독도로 주민 등록을 옮겨 첫 독도 주민이 되었다.","㉣ 독도에 머물며 주민과 관광객의 안전을 지키고 해안을 경계한다."],"title":"독도를 지킨 사람들 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#7','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'mc','auto','오늘날 정부가 독도를 지키려고 하는 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"오늘날 정부가 독도를 지키려고 하는 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"독도에 큰 공항을 지어 관광객만 받는다","correct":true},{"t":"선착장·주민 숙소·등대를 만든다","mis":"SO5-1-u1-X18"},{"t":"독도와 주변 바다를 지키는 법과 정책을 만든다","mis":"SO5-1-u1-X18"},{"t":"세계 여러 나라에 독도가 우리 고유의 영토임을 알린다","mis":"SO5-1-u1-X18"}],"explanation":["정부는 시설을 만들고 경비대를 보내요.","법과 정책으로 지켜요.","세계에 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#8','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',2,'mc','auto','「우리나라의 아름다운 섬, 독도」 그림 조건 메모에서 독도와 어울리지 않는 조건은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X19']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C11","difficulty":2,"kind":"mc","stem":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모에서 독도와 어울리지 않는 조건은 어느 것인가요?","options":[{"t":"조건 ㉱","correct":true},{"t":"조건 ㉯","mis":"SO5-1-u1-X16"},{"t":"조건 ㉰","mis":"SO5-1-u1-X16"},{"t":"조건 ㉮","mis":"SO5-1-u1-X19"}],"explanation":["독도에는 목장이 없어요.","괭이갈매기·해국·사철나무는 독도의 모습이에요.","㉱는 독도와 맞지 않아요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#9','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'ox','auto','독도를 지키는 일은 정부와 경비대가 하니 나는 관심을 갖지 않아도 돼요.',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"ox","stem":"독도를 지키는 일은 정부와 경비대가 하니 나는 관심을 갖지 않아도 돼요.","answer":"X","reason_options":[{"t":"개인·학교·여러 단체가 함께 관심을 기울이고 노력해야 더 잘 지킬 수 있기 때문에","correct":true},{"t":"독도는 아무도 지킬 필요가 없는 섬이기 때문에","mis":"SO5-1-u1-X18"}],"mis":"SO5-1-u1-X18","explanation":["독도 지키기는 모두의 일이에요.","관심을 갖고 바르게 알아요.","알리는 활동에 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_basic#10','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',3,'mc','auto','그림 조건 메모의 조건 ㉮ 「예쁜 풍경」만으로는 원하는 그림을 얻기 어려운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"그림 조건 메모의 조건 ㉮ 「예쁜 풍경」만으로는 원하는 그림을 얻기 어려운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람마다 떠올리는 모습이 달라 무엇을 그릴지 정해 주지 못하기 때문에","correct":true},{"t":"글자 수가 너무 많기 때문에","mis":"SO5-1-u1-X19"},{"t":"인공지능이 우리말을 읽지 못하기 때문에","mis":"SO5-1-u1-X19"},{"t":"예쁜 것은 그릴 수 없기 때문에","mis":"SO5-1-u1-X19"}],"explanation":["「예쁜 풍경」은 뜻이 흐려요.","무엇을 그릴지 정해지지 않아요.","자세한 조건이 필요해요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#1','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',2,'mc','auto','바다에서 국민의 생명과 재산을 지키고 해상 교통 질서와 바다 환경을 지키는 직업은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"바다에서 국민의 생명과 재산을 지키고 해상 교통 질서와 바다 환경을 지키는 직업은 어느 것인가요?","options":[{"t":"해양 경찰","correct":true},{"t":"지질 공원 해설사","mis":"SO5-1-u1-X10"},{"t":"등대지기","mis":"SO5-1-u1-X18"},{"t":"선장","mis":"SO5-1-u1-X18"}],"explanation":["바다를 지키는 경찰이에요.","사고가 나면 사람을 구해요.","바다 오염도 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#2','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',2,'sa','auto','홍순칠과 독도 의용 수비대가 독도 바위에 새긴 세 글자는 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"sa","stem":"홍순칠과 독도 의용 수비대가 독도 바위에 새긴 세 글자는 무엇인가요?","answer":["한국령"],"explanation":["「한국의 영토」라는 뜻이에요.","바위에 새겼어요.","한국령이에요."],"mis":"SO5-1-u1-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#3','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'mc','auto','독도에 군인이 아니라 경찰인 독도 경비대가 머무는 것이 뜻하는 바로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"독도에 군인이 아니라 경찰인 독도 경비대가 머무는 것이 뜻하는 바로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라가 독도를 우리 영토로서 평소처럼 다스리고 있다는 뜻","correct":true},{"t":"독도가 아직 어느 나라 땅인지 정해지지 않았다는 뜻","mis":"SO5-1-u1-X18"},{"t":"독도에는 사람이 살 수 없다는 뜻","mis":"SO5-1-u1-X15"},{"t":"독도에 관광객이 오지 못한다는 뜻","mis":"SO5-1-u1-X14"}],"explanation":["경찰은 나라 안의 질서를 지켜요.","독도도 우리 땅 안이에요.","평소처럼 다스린다는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#4','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'mc','auto','사이버 외교 사절단이 독도에 관한 잘못된 정보를 찾아 고치도록 하는 활동이 필요한 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"사이버 외교 사절단이 독도에 관한 잘못된 정보를 찾아 고치도록 하는 활동이 필요한 까닭은 무엇인가요?","options":[{"t":"세계 사람들이 독도를 우리 땅으로 바르게 알도록 하려고","correct":true},{"t":"독도를 찾는 관광객 수를 늘리려고","mis":"SO5-1-u1-X15"},{"t":"독도에 새로운 시설을 지으려고","mis":"SO5-1-u1-X18"},{"t":"독도의 옛 이름을 새로 정하려고","mis":"SO5-1-u1-X17"}],"explanation":["잘못된 정보는 오해를 낳아요.","틀린 내용을 바로잡아요.","세계가 바르게 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#5','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',3,'ox','auto','인공지능이 만든 그림을 소개할 때는 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 돼요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"ox","stem":"인공지능이 만든 그림을 소개할 때는 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 돼요.","answer":"X","reason_options":[{"t":"조건을 생각하고 고른 사람은 나이므로 어떤 조건으로 무엇을 표현했는지 스스로 설명해야 하기 때문에","correct":true},{"t":"인공지능 그림은 이름을 붙일 수 없기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["조건을 고른 사람은 나예요.","그림 이름을 말해요.","어떤 조건으로 무엇을 표현했는지 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#6','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'error','auto','독도를 지킨 사람들 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"error","stem":"독도를 지킨 사람들 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「㉢은 조선 시대에 일본에 건너간 안용복이야.」","correct":true,"mis_target":"SO5-1-u1-X18"},{"t":"보민 — 「㉣은 지금도 독도에 머무는 경찰이야.」","mis":"SO5-1-u1-X18"},{"t":"지유 — 「㉡은 울릉도 청년들과 함께 독도를 지켰어.」","mis":"SO5-1-u1-X18"}],"explanation":["㉢은 첫 독도 주민이에요.","첫 독도 주민은 최종덕이에요.","안용복은 ㉠이에요."],"asset":{"type":"passage","lines":["㉠ 조선 시대에 두 차례 일본으로 건너가 두 섬이 조선 땅이라고 설명했다.","㉡ 울릉도 청년들과 의용 수비대를 만들어 독도를 지켰다.","㉢ 울릉도의 어부로, 독도로 주민 등록을 옮겨 첫 독도 주민이 되었다.","㉣ 독도에 머물며 주민과 관광객의 안전을 지키고 해안을 경계한다."],"title":"독도를 지킨 사람들 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#7','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',3,'mc','auto','표현하고 싶은 경관이 제대로 그려지지 않았을 때 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"표현하고 싶은 경관이 제대로 그려지지 않았을 때 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조건을 더하거나 다르게 입력해 마음에 들 때까지 다시 만든다","correct":true},{"t":"그리기를 그만둔다","mis":"SO5-1-u1-X19"},{"t":"아무 그림이나 골라서 쓴다","mis":"SO5-1-u1-X19"},{"t":"조건을 모두 지우고 그냥 둔다","mis":"SO5-1-u1-X19"}],"explanation":["한 번에 안 되어도 괜찮아요.","조건을 고쳐 보아요.","여러 번 다시 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#8','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',4,'mc','auto','초등학생들이 독도에 찾아가 경비대를 만나고, 명예시민 등록과 각국 대사관에 편지 쓰기를 하기로 했어요. 이 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"mc","stem":"초등학생들이 독도에 찾아가 경비대를 만나고, 명예시민 등록과 각국 대사관에 편지 쓰기를 하기로 했어요. 이 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"개인과 학교도 독도에 관심을 불러일으키고 세계에 독도가 우리 땅임을 알리는 데 함께한다","correct":true},{"t":"독도를 지키는 일은 학생과 관계없다","mis":"SO5-1-u1-X18"},{"t":"독도에 학교를 새로 지으려는 것이다","mis":"SO5-1-u1-X18"},{"t":"독도에 사는 동물 수를 세려는 것이다","mis":"SO5-1-u1-X16"}],"explanation":["방문하고 알리는 활동이에요.","세계에 바른 역사를 알려요.","학생도 함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#9','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',4,'mc','auto','「우리나라의 아름다운 섬, 독도」 그림을 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19','SO5-1-u1-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C11","difficulty":4,"kind":"mc","stem":"「우리나라의 아름다운 섬, 독도」 그림을 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그림 이름은 「아침의 독도」입니다. 동도와 서도, 하늘을 나는 괭이갈매기, 바위에 핀 해국을 조건으로 독도의 자연을 표현했습니다.」","correct":true},{"t":"「인공지능이 만들었으니 제 생각은 없어요.」","mis":"SO5-1-u1-X19"},{"t":"「이름은 없지만 예쁘니까 봐 주세요.」","mis":"SO5-1-u1-X19"},{"t":"「산 위 목장의 소를 넣어 독도를 표현했습니다.」","mis":"SO5-1-u1-X16"}],"explanation":["그림 이름을 말해요.","어떤 조건을 썼는지 말해요.","무엇을 표현했는지 설명해요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_L10_challenge#10','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',4,'essay','teacher','독도를 지키려고 노력한 사람이나 집단 두 곳을 골라 한 일을 쓰고, 내가 독도를 알리려고 할 수 있는 일을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"essay","stem":"독도를 지키려고 노력한 사람이나 집단 두 곳을 골라 한 일을 쓰고, 내가 독도를 알리려고 할 수 있는 일을 하나 쓰세요.","answer_guide":{"answer":"예: 안용복은 조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명했다. 정부는 독도 경비대를 파견하고 선착장과 등대를 만들어 독도를 지킨다. 나는 독도의 위치와 자연환경, 옛 지도에 나타난 독도를 소개하는 그림을 만들어 친구들과 가족에게 알리겠다.","scoring_points":["노력한 사람이나 집단을 둘 골랐는가","각각 한 일을 바르게 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["옛날과 오늘의 노력을 골라요.","한 일을 바르게 짝지어요.","나도 함께할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#1','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C1',1,'mc','auto','새봄이네가 여행하며 만난 산지·하천·평야·해안·섬을 함께 이르는 말은 어느 것인가요?',ARRAY['SO5-1-u1-X01','SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"새봄이네가 여행하며 만난 산지·하천·평야·해안·섬을 함께 이르는 말은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO5-1-u1-X01"},{"t":"인구","mis":"SO5-1-u1-X01"},{"t":"항로","mis":"SO5-1-u1-X14"}],"explanation":["모두 땅의 생김새예요.","땅의 생김새를 지형이라고 해요.","기후는 날씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#2','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C2',1,'mc','auto','새봄이네 수첩 ①의 산지가 지형도에서 진한 갈색인 것은 무엇을 뜻하나요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ①의 산지가 지형도에서 진한 갈색인 것은 무엇을 뜻하나요?","options":[{"t":"땅이 아주 높다","correct":true},{"t":"땅이 아주 낮다","mis":"SO5-1-u1-X04"},{"t":"바다가 깊다","mis":"SO5-1-u1-X04"},{"t":"사람이 많이 산다","mis":"SO5-1-u1-X04"}],"explanation":["범례를 보면 알 수 있어요.","진한 갈색은 높은 땅이에요.","높은 산지예요."],"asset":{"type":"passage","lines":["첫째 날 — 북동쪽의 높은 산지에 갔다.","험한 봉우리가 줄지어 있고 바람이 세게 불었다.","지형도에서 이곳은 진한 갈색으로 칠해져 있었다."],"title":"새봄이네 수첩 ① 높은 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#3','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',1,'mc','auto','새봄이네 수첩 ②에서 물줄기가 서쪽의 낮은 곳으로 흘러간 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ②에서 물줄기가 서쪽의 낮은 곳으로 흘러간 까닭은 무엇인가요?","options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"물은 낮은 곳에서 높은 곳으로 흐르기 때문에","mis":"SO5-1-u1-X05"},{"t":"물은 언제나 동쪽으로 흐르기 때문에","mis":"SO5-1-u1-X05"},{"t":"바람이 물을 밀었기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 아래로 흘러요.","서쪽이 더 낮아요.","그래서 서쪽으로 흘렀어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#4','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',1,'mc','auto','새봄이네 수첩 ③처럼 바닷물이 빠지면 드러나는 넓은 진흙 땅을 무엇이라고 하나요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ③처럼 바닷물이 빠지면 드러나는 넓은 진흙 땅을 무엇이라고 하나요?","options":[{"t":"갯벌","correct":true},{"t":"모래사장","mis":"SO5-1-u1-X08"},{"t":"해안 절벽","mis":"SO5-1-u1-X08"},{"t":"평야","mis":"SO5-1-u1-X06"}],"explanation":["바닷물이 드나드는 진흙 땅이에요.","조개를 캘 수 있어요.","갯벌이에요."],"asset":{"type":"passage","lines":["바닷물이 빠지자 넓은 진흙 땅이 드러났다.","동생과 조개를 캤다.","지도를 보니 해안선이 들쭉날쭉하고 섬이 많았다."],"title":"새봄이네 수첩 ③ 진흙 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#5','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C5',1,'mc','auto','새봄이네 수첩 ⑤에서 바위가 생긴 까닭과 옛이야기를 들려준 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑤에서 바위가 생긴 까닭과 옛이야기를 들려준 사람은 누구인가요?","options":[{"t":"지질 공원 해설사","correct":true},{"t":"해양 경찰","mis":"SO5-1-u1-X18"},{"t":"독도 경비대원","mis":"SO5-1-u1-X18"},{"t":"여행사 직원","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원에서 일해요.","지질·지형·역사를 엮어 설명해요.","지질 공원 해설사예요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#6','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',1,'mc','auto','국토 여행 계획을 세우는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"국토 여행 계획을 세우는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 여행지 조사 → 경로 표시 → 계획 공유","correct":true},{"t":"여행지 조사 → 주제 정하기 → 경로 표시 → 계획 공유","mis":"SO5-1-u1-X11"},{"t":"경로 표시 → 주제 정하기 → 계획 공유 → 여행지 조사","mis":"SO5-1-u1-X11"},{"t":"계획 공유 → 경로 표시 → 여행지 조사 → 주제 정하기","mis":"SO5-1-u1-X11"}],"explanation":["주제가 먼저예요.","조사한 뒤 경로를 이어요.","마지막에 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#7','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',1,'mc','auto','새봄이네 수첩 ⑥에서 독도에 가기 전에 들른 섬은 어디인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑥에서 독도에 가기 전에 들른 섬은 어디인가요?","options":[{"t":"울릉도","correct":true},{"t":"제주도","mis":"SO5-1-u1-X14"},{"t":"강화도","mis":"SO5-1-u1-X14"},{"t":"거제도","mis":"SO5-1-u1-X14"}],"explanation":["동해안 항구에서 배를 탔어요.","먼저 울릉도에 갔어요.","그다음 독도로 갔어요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#8','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C8',1,'mc','auto','새봄이네 수첩 ⑦에 나온 독도의 두 큰 섬은 무엇인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑦에 나온 독도의 두 큰 섬은 무엇인가요?","options":[{"t":"동도와 서도","correct":true},{"t":"남도와 북도","mis":"SO5-1-u1-X16"},{"t":"울릉도와 제주도","mis":"SO5-1-u1-X14"},{"t":"큰섬과 작은섬","mis":"SO5-1-u1-X16"}],"explanation":["동쪽 섬과 서쪽 섬이에요.","동도와 서도예요.","주변에 바위섬이 많아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#9','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C2',2,'mc','auto','새봄이네 수첩 ①의 산지가 북동쪽에 있는 것과 가장 관계 깊은 우리나라 땅의 특징은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ①의 산지가 북동쪽에 있는 것과 가장 관계 깊은 우리나라 땅의 특징은 어느 것인가요?","options":[{"t":"높고 험한 산지가 북쪽과 동쪽에 몰려 있다","correct":true},{"t":"높은 산지가 남쪽과 서쪽에 몰려 있다","mis":"SO5-1-u1-X03"},{"t":"우리나라는 어디나 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"높은 산지는 바다 한가운데에 있다","mis":"SO5-1-u1-X03"}],"explanation":["수첩 ①은 북동쪽이에요.","높은 산지가 북·동쪽에 있어요.","그래서 북동쪽이 높아요."],"asset":{"type":"passage","lines":["첫째 날 — 북동쪽의 높은 산지에 갔다.","험한 봉우리가 줄지어 있고 바람이 세게 불었다.","지형도에서 이곳은 진한 갈색으로 칠해져 있었다."],"title":"새봄이네 수첩 ① 높은 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#10','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',2,'mc','auto','새봄이네 수첩 ②의 「아래쪽에는 논이 넓게 펼쳐져 있었다」는 모습이 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ②의 「아래쪽에는 논이 넓게 펼쳐져 있었다」는 모습이 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하천 주변의 낮고 평평한 땅에 평야가 발달했기 때문에","correct":true},{"t":"높은 산꼭대기에 평야가 생겼기 때문에","mis":"SO5-1-u1-X06"},{"t":"바닷물이 빠져 진흙 땅이 드러났기 때문에","mis":"SO5-1-u1-X08"},{"t":"파도가 바위를 깎았기 때문에","mis":"SO5-1-u1-X08"}],"explanation":["하천 아래쪽은 낮아요.","평평한 땅이 넓어요.","평야에 논이 많아요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#11','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',2,'mc','auto','새봄이네 수첩 ③과 ④를 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ③과 ④를 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"③은 해안선이 들쭉날쭉하고 갯벌이 있고, ④는 해안선이 곧고 모래사장이 넓다","correct":true},{"t":"③은 모래사장이 넓고, ④는 갯벌이 넓다","mis":"SO5-1-u1-X07"},{"t":"③과 ④는 해안선 모습이 같다","mis":"SO5-1-u1-X07"},{"t":"③은 동해안, ④는 서해안의 모습이다","mis":"SO5-1-u1-X07"}],"explanation":["③은 갯벌과 복잡한 해안선이에요.","④는 곧은 해안선과 모래사장이에요.","바다마다 모습이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#12','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C5',2,'mc','auto','새봄이네 수첩 ⑤에서 아빠가 동생을 말린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑤에서 아빠가 동생을 말린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오랜 시간이 만든 자연이라 가져가면 되돌릴 수 없기 때문에","correct":true},{"t":"돌 조각이 너무 무거워서","mis":"SO5-1-u1-X10"},{"t":"돌은 사서 가져가야 하기 때문에","mis":"SO5-1-u1-X10"},{"t":"해설사가 돌을 팔기 때문에","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원의 돌은 오랜 시간이 만들었어요.","가져가면 되돌릴 수 없어요.","눈으로만 봐요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#13','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',2,'mc','auto','새봄이네처럼 「산에서 바다까지 여러 지형을 만나는 여행」을 하려고 해요. 경로를 정할 때 알맞은 생각은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"새봄이네처럼 「산에서 바다까지 여러 지형을 만나는 여행」을 하려고 해요. 경로를 정할 때 알맞은 생각은 어느 것인가요?","options":[{"t":"이동 거리가 너무 길어지지 않게, 여행 목적에 맞는 차례로 화살표를 잇는다","correct":true},{"t":"가장 먼 곳끼리 번갈아 다닌다","mis":"SO5-1-u1-X11"},{"t":"조사하지 않은 곳을 많이 넣는다","mis":"SO5-1-u1-X11"},{"t":"여행지 이름만 나열하고 경로는 그리지 않는다","mis":"SO5-1-u1-X11"}],"explanation":["동선이 길지 않게 해요.","목적에 맞는 차례로 해요.","화살표로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#14','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',2,'mc','auto','새봄이네 수첩 ⑥의 「맑은 날 전망대에서 멀리 독도가 보였다」가 뜻하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X16']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑥의 「맑은 날 전망대에서 멀리 독도가 보였다」가 뜻하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"울릉도 사람들은 오래전부터 독도를 알고 우리 영토로 여겨 왔다","correct":true},{"t":"독도와 울릉도는 땅으로 이어져 있다","mis":"SO5-1-u1-X14"},{"t":"독도는 울릉도보다 훨씬 크다","mis":"SO5-1-u1-X16"},{"t":"독도에는 공항이 있다","mis":"SO5-1-u1-X14"}],"explanation":["눈에 보일 만큼 가까워요.","오래전부터 알았어요.","우리 영토로 여겼어요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#15','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C8',2,'mc','auto','새봄이네 수첩 ⑦에서 안개가 끼었다 걷힌 것과 관계 깊은 독도의 날씨 특징은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑦에서 안개가 끼었다 걷힌 것과 관계 깊은 독도의 날씨 특징은 어느 것인가요?","options":[{"t":"대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다","correct":true},{"t":"일 년 내내 눈이 쌓여 있다","mis":"SO5-1-u1-X16"},{"t":"비가 전혀 오지 않는다","mis":"SO5-1-u1-X16"},{"t":"사막처럼 늘 건조하다","mis":"SO5-1-u1-X16"}],"explanation":["독도는 바다 한가운데예요.","안개가 자주 껴요.","흐린 날이 많아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#16','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C9',2,'mc','auto','새봄이네 수첩 ⑧에서 본 옛 지도로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 본 옛 지도로 알 수 있는 것은 어느 것인가요?","options":[{"t":"당시 일본에서도 독도를 조선의 영토로 여겼다","correct":true},{"t":"독도는 옛날에 일본 땅이었다","mis":"SO5-1-u1-X17"},{"t":"옛날에는 동해에 섬이 없었다","mis":"SO5-1-u1-X17"},{"t":"지도를 만든 나라는 조선이다","mis":"SO5-1-u1-X17"}],"explanation":["일본이 만든 지도예요.","독도를 조선 색으로 칠했어요.","일본도 조선 땅으로 여겼어요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#17','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',3,'mc','auto','새봄이네 수첩 ①에서 ②로 이어지는 여행을 지형도에 그린다면 물줄기를 따라간 방향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X04']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ①에서 ②로 이어지는 여행을 지형도에 그린다면 물줄기를 따라간 방향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북동쪽의 진한 색 땅에서 서쪽의 옅은 색 땅으로","correct":true},{"t":"서쪽의 옅은 색 땅에서 북동쪽의 진한 색 땅으로","mis":"SO5-1-u1-X05"},{"t":"초록색 땅에서 진한 갈색 땅으로","mis":"SO5-1-u1-X04"},{"t":"높이가 같은 땅을 따라 옆으로만","mis":"SO5-1-u1-X05"}],"explanation":["물은 높은 곳에서 출발해요.","진한 색이 높은 곳이에요.","옅은 색 낮은 곳으로 흘러요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#18','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',3,'mc','auto','새봄이네 수첩 ④의 바닷가에 서핑하는 사람과 해수욕장이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ④의 바닷가에 서핑하는 사람과 해수욕장이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해안선이 단순하고 넓은 모래사장이 펼쳐진 동해안이기 때문에","correct":true},{"t":"물이 빠지면 넓은 갯벌이 드러나기 때문에","mis":"SO5-1-u1-X08"},{"t":"섬이 아주 많아 다도해이기 때문에","mis":"SO5-1-u1-X07"},{"t":"높은 산지 위에 있기 때문에","mis":"SO5-1-u1-X09"}],"explanation":["모래사장이 넓어요.","해수욕장이 발달해요.","파도를 타기도 좋아요."],"asset":{"type":"passage","lines":["해안선이 곧게 뻗은 바닷가에 갔다.","넓은 모래사장에서 해수욕을 했다.","파도를 타며 서핑을 하는 사람도 많았다."],"title":"새봄이네 수첩 ④ 모래 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#19','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',3,'mc','auto','새봄이가 「다양한 해안 지형을 견주어 보는 여행」을 주제로 다시 계획한다면 넣기 가장 알맞은 수첩 꼭지 묶음은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"새봄이가 「다양한 해안 지형을 견주어 보는 여행」을 주제로 다시 계획한다면 넣기 가장 알맞은 수첩 꼭지 묶음은 어느 것인가요?","options":[{"t":"③과 ④","correct":true},{"t":"①과 ②","mis":"SO5-1-u1-X09"},{"t":"⑥과 ⑧","mis":"SO5-1-u1-X09"},{"t":"①과 ⑤","mis":"SO5-1-u1-X09"}],"explanation":["해안 지형을 견주어요.","③은 갯벌, ④는 모래사장이에요.","두 바닷가를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#20','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',3,'mc','auto','새봄이네 수첩 ⑥과 ⑦을 함께 볼 때 다른 나라 사람이 독도에 간다면 어떻게 가야 할까요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑥과 ⑦을 함께 볼 때 다른 나라 사람이 독도에 간다면 어떻게 가야 할까요?","options":[{"t":"우리나라에 들어와 동해안 항구에서 배를 타고 울릉도를 거쳐 간다","correct":true},{"t":"자기 나라에서 비행기로 독도에 바로 간다","mis":"SO5-1-u1-X14"},{"t":"아무 나라에서나 배를 타고 바로 간다","mis":"SO5-1-u1-X14"},{"t":"다른 나라 사람은 독도에 갈 수 없다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 우리 영토예요.","우리와 같은 방법으로 가요.","항구 → 울릉도 → 독도예요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#21','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C9',3,'mc','auto','새봄이네 수첩 ⑧의 옛 지도가 독도가 우리 땅이라는 증거로 특히 힘이 있는 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X13']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑧의 옛 지도가 독도가 우리 땅이라는 증거로 특히 힘이 있는 까닭은 어느 것인가요?","options":[{"t":"자기 나라 땅이라 할 수도 있었던 일본이 독도를 조선 색으로 칠했기 때문에","correct":true},{"t":"지도가 아주 크고 화려하기 때문에","mis":"SO5-1-u1-X17"},{"t":"우리나라가 만든 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"연도가 가장 정확하게 적혀 있기 때문에","mis":"SO5-1-u1-X13"}],"explanation":["만든 나라가 일본이에요.","그런데도 조선 색이에요.","그래서 더 믿을 만해요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#22','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C11',3,'mc','auto','새봄이네 수첩 ⑧에서 새봄이가 독도를 알리는 그림을 만들 때 넣기 가장 알맞은 조건은 어느 것인가요?',ARRAY['SO5-1-u1-X19','SO5-1-u1-X16']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 새봄이가 독도를 알리는 그림을 만들 때 넣기 가장 알맞은 조건은 어느 것인가요?","options":[{"t":"동도와 서도 사이를 나는 괭이갈매기와 바위에 핀 해국","correct":true},{"t":"예쁜 풍경","mis":"SO5-1-u1-X19"},{"t":"산 위 목장에서 풀을 뜯는 소","mis":"SO5-1-u1-X16"},{"t":"넓은 모래사장의 해수욕장","mis":"SO5-1-u1-X16"}],"explanation":["수첩 ⑦에서 본 것을 떠올려요.","독도의 모습을 자세히 적어요.","흐린 조건은 안 돼요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#23','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C1',4,'mc','auto','「우리나라 국토 여행」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X13','SO5-1-u1-X05']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"「우리나라 국토 여행」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"우리 국토는 북동쪽이 높고 남서쪽이 낮아 산지·하천·평야·해안이 어우러지고, 동쪽 끝 독도는 예로부터 우리 땅으로 함께 지켜 왔다","correct":true},{"t":"우리 국토는 어디나 평평하고 독도는 최근에 알려진 섬이다","mis":"SO5-1-u1-X03"},{"t":"지형은 이름만 외우면 되고 독도는 정부만 지키면 된다","mis":"SO5-1-u1-X13"},{"t":"하천은 동쪽으로 흐르고 독도는 서쪽 끝에 있다","mis":"SO5-1-u1-X05"}],"explanation":["높낮이가 지형을 이어 줘요.","독도는 동쪽 끝이에요.","옛날부터 함께 지켜 왔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#24','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',4,'essay','teacher','새봄이네 수첩 ①과 ②를 보고 물줄기가 서쪽으로 흘러간 까닭을 우리나라 땅의 높낮이와 함께 쓰고, 물줄기 아래쪽에 논이 넓게 펼쳐진 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ①과 ②를 보고 물줄기가 서쪽으로 흘러간 까닭을 우리나라 땅의 높낮이와 함께 쓰고, 물줄기 아래쪽에 논이 넓게 펼쳐진 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리나라는 높고 험한 산지가 북쪽과 동쪽에 몰려 있어 북동쪽이 높고 남서쪽이 낮다. 물은 높은 곳에서 낮은 곳으로 흐르므로 북동쪽 산에서 시작한 계곡물이 낮은 서쪽으로 흘러갔다. 물줄기 아래쪽은 낮고 평평한 땅이어서 평야가 발달했고 그래서 논이 넓게 펼쳐져 있다.","scoring_points":["북동쪽이 높고 남서쪽이 낮다고 썼는가","물이 낮은 곳으로 흐른다는 까닭을 썼는가","하천 주변 평야와 논을 이어 썼는가"]},"explanation":["높낮이가 방향을 정해요.","물은 낮은 곳으로 흘러요.","하천 주변에 평야가 있어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_a#25','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',4,'essay','teacher','새봄이네 수첩 ⑥을 보고 독도까지 가는 길을 차례대로 쓰고, 독도의 위치를 쓴 뒤, 독도가 중요한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑥을 보고 독도까지 가는 길을 차례대로 쓰고, 독도의 위치를 쓴 뒤, 독도가 중요한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 동해안의 항구에서 배를 타고 울릉도에 간 뒤 다시 배를 타고 독도로 간다. 독도에는 공항이 없기 때문이다. 독도는 우리나라 영토의 동쪽 끝, 동해에 있다. 독도는 우리 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요하다.","scoring_points":["항구 → 울릉도 → 독도의 차례를 썼는가","위치를 썼는가","중요한 까닭 두 가지를 썼는가"]},"explanation":["배로 울릉도를 거쳐요.","동쪽 끝이에요.","경계·교통·군사·연구·자원이에요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#1','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C1',1,'sa','auto','산봉우리가 길게 이어져 솟아 있는 땅을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"sa","stem":"산봉우리가 길게 이어져 솟아 있는 땅을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["산지"],"explanation":["높이 솟은 땅이에요.","우리 국토의 약 70%예요.","산지예요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#2','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C2',1,'mc','auto','우리나라 땅에서 높고 험한 산지가 많은 쪽은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"우리나라 땅에서 높고 험한 산지가 많은 쪽은 어느 것인가요?","options":[{"t":"북쪽과 동쪽","correct":true},{"t":"남쪽과 서쪽","mis":"SO5-1-u1-X03"},{"t":"남쪽만","mis":"SO5-1-u1-X03"},{"t":"서쪽만","mis":"SO5-1-u1-X03"}],"explanation":["높은 산이 몰려 있어요.","북쪽과 동쪽이에요.","그래서 북동쪽이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#3','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C3',1,'sa','auto','크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? (□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"sa","stem":"크고 작은 물줄기가 높은 곳에서 낮은 곳으로 흐르는 곳을 무엇이라고 하나요? (□□)","answer":["하천"],"explanation":["물이 흐르는 지형이에요.","강과 시내예요.","하천이에요."],"mis":"SO5-1-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#4','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',1,'mc','auto','새봄이네 수첩 ④의 바닷가는 어느 바다일 가능성이 가장 큰가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ④의 바닷가는 어느 바다일 가능성이 가장 큰가요?","options":[{"t":"동해안","correct":true},{"t":"서해안","mis":"SO5-1-u1-X07"},{"t":"남해안","mis":"SO5-1-u1-X07"},{"t":"호숫가","mis":"SO5-1-u1-X08"}],"explanation":["해안선이 곧게 뻗었어요.","모래사장이 넓어요.","동해안의 모습이에요."],"asset":{"type":"passage","lines":["해안선이 곧게 뻗은 바닷가에 갔다.","넓은 모래사장에서 해수욕을 했다.","파도를 타며 서핑을 하는 사람도 많았다."],"title":"새봄이네 수첩 ④ 모래 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#5','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C5',1,'mc','auto','지질적 가치가 뛰어난 경관을 보전하려고 국제기구가 인증하는 곳은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"mc","stem":"지질적 가치가 뛰어난 경관을 보전하려고 국제기구가 인증하는 곳은 어느 것인가요?","options":[{"t":"세계 지질 공원","correct":true},{"t":"놀이공원","mis":"SO5-1-u1-X10"},{"t":"대형 할인점","mis":"SO5-1-u1-X10"},{"t":"공항","mis":"SO5-1-u1-X14"}],"explanation":["지질 가치가 뛰어나요.","국제기구가 인증해요.","세계 지질 공원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#6','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C6',1,'mc','auto','여행지의 실제 모습을 확대해 살펴보는 데 쓰는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"mc","stem":"여행지의 실제 모습을 확대해 살펴보는 데 쓰는 것은 어느 것인가요?","options":[{"t":"디지털 영상 지도","correct":true},{"t":"일기장","mis":"SO5-1-u1-X11"},{"t":"저금통","mis":"SO5-1-u1-X11"},{"t":"계산기","mis":"SO5-1-u1-X11"}],"explanation":["영상 지도는 실제 모습을 보여 줘요.","확대할 수 있어요.","지형의 특징을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#7','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C7',1,'mc','auto','독도의 행정구역은 어느 것인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도의 행정구역은 어느 것인가요?","options":[{"t":"경상북도 울릉군","correct":true},{"t":"강원특별자치도 강릉시","mis":"SO5-1-u1-X14"},{"t":"제주특별자치도","mis":"SO5-1-u1-X14"},{"t":"전라남도 여수시","mis":"SO5-1-u1-X14"}],"explanation":["울릉도와 같은 군이에요.","경상북도에 속해요.","울릉군이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#8','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C10',1,'mc','auto','새봄이네 수첩 ⑧에서 조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람은 누구인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람은 누구인가요?","options":[{"t":"안용복","correct":true},{"t":"최종덕","mis":"SO5-1-u1-X18"},{"t":"홍순칠","mis":"SO5-1-u1-X18"},{"t":"이사부","mis":"SO5-1-u1-X17"}],"explanation":["조선 시대 사람이에요.","두 차례 일본에 건너갔어요.","안용복이에요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#9','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C1',2,'mc','auto','새봄이네 수첩 ②에서 함께 만난 두 지형을 바르게 고른 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ②에서 함께 만난 두 지형을 바르게 고른 것은 어느 것인가요?","options":[{"t":"하천과 평야","correct":true},{"t":"해안과 섬","mis":"SO5-1-u1-X02"},{"t":"갯벌과 모래사장","mis":"SO5-1-u1-X08"},{"t":"섬과 해안 절벽","mis":"SO5-1-u1-X08"}],"explanation":["계곡물은 하천이에요.","논이 펼쳐진 땅은 평야예요.","하천과 평야를 만났어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#10','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C3',2,'mc','auto','물이 갈림길에서 900 m · 600 m · 300 m 세 곳 가운데 하나를 고른다면 어디로 갈까요? (지금 있는 곳은 700 m)',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"물이 갈림길에서 900 m · 600 m · 300 m 세 곳 가운데 하나를 고른다면 어디로 갈까요? (지금 있는 곳은 700 m)","options":[{"t":"300 m","correct":true},{"t":"900 m","mis":"SO5-1-u1-X05"},{"t":"세 곳 모두","mis":"SO5-1-u1-X05"},{"t":"갈 곳이 없다","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 가요.","700 m보다 낮은 곳은 600 m와 300 m예요.","가장 낮은 300 m로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#11','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',2,'mc','auto','새봄이네 수첩 ③에서 조개를 캘 수 있었던 까닭과 가장 관계 깊은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X09']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ③에서 조개를 캘 수 있었던 까닭과 가장 관계 깊은 것은 어느 것인가요?","options":[{"t":"넓은 갯벌이 발달한 바다였다","correct":true},{"t":"넓은 모래사장이 있는 바다였다","mis":"SO5-1-u1-X08"},{"t":"파도가 깎은 절벽이 있는 바다였다","mis":"SO5-1-u1-X08"},{"t":"높은 산지 위였다","mis":"SO5-1-u1-X09"}],"explanation":["조개는 갯벌에 살아요.","물이 빠지면 캘 수 있어요.","갯벌이 넓은 바다예요."],"asset":{"type":"passage","lines":["바닷물이 빠지자 넓은 진흙 땅이 드러났다.","동생과 조개를 캤다.","지도를 보니 해안선이 들쭉날쭉하고 섬이 많았다."],"title":"새봄이네 수첩 ③ 진흙 바닷가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#12','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C5',2,'mc','auto','지질 공원 해설사가 마을 옛이야기까지 들려준 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"지질 공원 해설사가 마을 옛이야기까지 들려준 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설사는 지질·지형·자연·역사를 엮어 알기 쉽게 설명하기 때문에","correct":true},{"t":"해설사는 지형을 몰라서","mis":"SO5-1-u1-X10"},{"t":"옛이야기는 지질 공원과 관계없지만 재미있어서","mis":"SO5-1-u1-X10"},{"t":"해설사는 역사만 설명하기 때문에","mis":"SO5-1-u1-X10"}],"explanation":["해설사는 여러 이야기를 엮어요.","지질·지형·자연·역사예요.","알기 쉽게 설명해요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#13','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C6',2,'mc','auto','지역별 관광 안내 누리집을 찾을 때 검색창에 넣기 알맞은 말은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"지역별 관광 안내 누리집을 찾을 때 검색창에 넣기 알맞은 말은 어느 것인가요?","options":[{"t":"지역명 + 문화 관광","correct":true},{"t":"친구 이름 + 놀이","mis":"SO5-1-u1-X11"},{"t":"오늘 날씨","mis":"SO5-1-u1-X11"},{"t":"학교 이름 + 급식","mis":"SO5-1-u1-X11"}],"explanation":["지역 누리집을 찾아요.","지역명과 문화 관광을 넣어요.","그러면 연결돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#14','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C7',2,'mc','auto','독도가 동해에 있어 교통과 군사 면에서 중요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"독도가 동해에 있어 교통과 군사 면에서 중요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"동해를 지나는 배와 비행기를 살필 수 있기 때문에","correct":true},{"t":"독도에서 농사를 많이 짓기 때문에","mis":"SO5-1-u1-X15"},{"t":"독도에 큰 공항이 있기 때문에","mis":"SO5-1-u1-X14"},{"t":"독도에 사람이 가장 많이 살기 때문에","mis":"SO5-1-u1-X15"}],"explanation":["동해는 세 나라가 둘러싸요.","많은 배와 비행기가 지나가요.","살피고 지키는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#15','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C8',2,'mc','auto','독도 주변 바다가 좋은 어장을 이루는 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"독도 주변 바다가 좋은 어장을 이루는 까닭은 어느 것인가요?","options":[{"t":"차가운 바닷물과 따뜻한 바닷물이 만나기 때문에","correct":true},{"t":"바닷물이 아주 얕기 때문에","mis":"SO5-1-u1-X16"},{"t":"바다에 섬이 하나도 없기 때문에","mis":"SO5-1-u1-X16"},{"t":"파도가 전혀 치지 않기 때문에","mis":"SO5-1-u1-X16"}],"explanation":["두 바닷물이 만나요.","해양 생물이 살기 좋아요.","좋은 어장이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#16','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C10',2,'mc','auto','새봄이네 수첩 ⑦에서 독도 경비대원이 사람들을 안내한 것처럼, 정부가 독도 경비대를 보낸 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑦에서 독도 경비대원이 사람들을 안내한 것처럼, 정부가 독도 경비대를 보낸 까닭은 어느 것인가요?","options":[{"t":"주민과 관광객의 편의와 안전을 지키고 해안을 경계하려고","correct":true},{"t":"독도의 바위를 캐려고","mis":"SO5-1-u1-X18"},{"t":"독도에 목장을 만들려고","mis":"SO5-1-u1-X18"},{"t":"독도에 사람이 못 오게 막으려고","mis":"SO5-1-u1-X18"}],"explanation":["경비대는 경찰이에요.","안전을 지키고 경계해요.","독도를 평소처럼 다스려요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#17','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C2',3,'mc','auto','서쪽 바닷가에서 동쪽 바닷가까지 땅을 잘라 본 단면의 모양으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X04']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C2","difficulty":3,"kind":"mc","stem":"서쪽 바닷가에서 동쪽 바닷가까지 땅을 잘라 본 단면의 모양으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서쪽은 낮고 넓게 이어지다가 동쪽 가까이에서 높이 솟는다","correct":true},{"t":"서쪽이 높이 솟고 동쪽은 낮고 넓다","mis":"SO5-1-u1-X03"},{"t":"처음부터 끝까지 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"가운데만 깊게 파였다","mis":"SO5-1-u1-X04"}],"explanation":["서쪽은 낮아요.","동쪽에 높은 산이 몰려 있어요.","동쪽 가까이에서 솟아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#18','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',3,'error','auto','새봄이네 수첩 ③과 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ③과 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세린 — 「③은 해안선이 곧아서 지도에 따라 그리기 쉬워.」","correct":true,"mis_target":"SO5-1-u1-X07"},{"t":"도하 — 「④에서는 해수욕을 즐겼어.」","mis":"SO5-1-u1-X08"},{"t":"예서 — 「③에서는 갯벌에서 조개를 캤어.」","mis":"SO5-1-u1-X08"}],"explanation":["③은 해안선이 들쭉날쭉해요.","따라 그리기 어려워요.","곧은 해안선은 ④예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#19','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C6',3,'error','auto','여행 계획을 세우는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"error","stem":"여행 계획을 세우는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지환 — 「여행지부터 아무 데나 고르고 주제는 맨 마지막에 정하면 돼.」","correct":true,"mis_target":"SO5-1-u1-X11"},{"t":"수빈 — 「주제를 먼저 정해야 어디를 조사할지 알 수 있어.」","mis":"SO5-1-u1-X11"},{"t":"주원 — 「조사한 곳은 디지털 영상 지도로 모습을 확인해.」","mis":"SO5-1-u1-X11"}],"explanation":["주제가 먼저예요.","주제가 조사할 곳을 정해 줘요.","지환의 차례가 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#20','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C8',3,'error','auto','새봄이네 수첩 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「독도는 땅이 평평해서 넓은 들판과 목장이 있어.」","correct":true,"mis_target":"SO5-1-u1-X16"},{"t":"지안 — 「바위에 해국 같은 식물이 자라.」","mis":"SO5-1-u1-X16"},{"t":"서진 — 「괭이갈매기 같은 새가 살아.」","mis":"SO5-1-u1-X16"}],"explanation":["독도는 화산이 만든 바위섬이에요.","들판과 목장은 없어요.","새와 바위 식물이 살아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#21','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C9',3,'error','auto','옛 자료를 살펴보는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"error","stem":"옛 자료를 살펴보는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태경 — 「옛 자료는 연도를 다 외워야만 무엇을 말하는지 알 수 있어.」","correct":true,"mis_target":"SO5-1-u1-X13"},{"t":"나연 — 「누가 만들었는지 살펴봐야 해.」","mis":"SO5-1-u1-X17"},{"t":"찬우 — 「여러 나라 자료를 함께 견주어 봐야 해.」","mis":"SO5-1-u1-X17"}],"explanation":["연도보다 내용을 읽어요.","누가 만들었는지 봐요.","함께 견주면 분명해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#22','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C10',3,'error','auto','독도를 지키는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"error","stem":"독도를 지키는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"규리 — 「경비대가 있으니 우리는 독도에 관심 없어도 돼.」","correct":true,"mis_target":"SO5-1-u1-X18"},{"t":"민재 — 「독도에 관한 잘못된 정보를 보면 바로잡도록 알려야 해.」","mis":"SO5-1-u1-X18"},{"t":"혜원 — 「독도를 알리는 활동에 참여할 수 있어.」","mis":"SO5-1-u1-X18"}],"explanation":["독도 지키기는 모두의 일이에요.","바로잡고 알리는 일도 해요.","관심이 첫걸음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#23','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C3',4,'mc','auto','새봄이네 수첩 ①·②·④를 차례로 이어 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06','SO5-1-u1-X07']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ①·②·④를 차례로 이어 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북동쪽 높은 산에서 시작한 물줄기는 낮은 서쪽으로 흐르며 주변에 평야를 만들고, 동쪽 바닷가는 산이 바다 가까이까지 이어진다","correct":true},{"t":"물줄기는 동쪽 바닷가에서 시작해 산꼭대기로 올라간다","mis":"SO5-1-u1-X05"},{"t":"평야는 북동쪽의 높은 산 위에 넓게 펼쳐진다","mis":"SO5-1-u1-X06"},{"t":"동쪽 바닷가는 갯벌이 넓어 해안선이 들쭉날쭉하다","mis":"SO5-1-u1-X07"}],"explanation":["①은 높은 산, ②는 물줄기와 평야예요.","④는 곧은 동해안이에요.","높낮이가 모두를 이어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#24','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C4',4,'essay','teacher','새봄이네 수첩 ③과 ④의 바닷가를 해안선과 바닷가 땅으로 견주어 쓰고, 각각 어느 바다일지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C4","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ③과 ④의 바닷가를 해안선과 바닷가 땅으로 견주어 쓰고, 각각 어느 바다일지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ③은 해안선이 들쭉날쭉하고 섬이 많으며 바닷물이 빠지면 넓은 갯벌이 드러난다. ④는 해안선이 곧게 뻗어 있고 넓은 모래사장이 있다. 그래서 ③은 갯벌이 발달하고 해안선이 복잡한 서해안, ④는 해안선이 단순하고 모래사장이 넓은 동해안이라고 생각한다.","scoring_points":["해안선을 견주었는가","갯벌과 모래사장을 견주었는가","바다를 까닭과 함께 골랐는가"]},"explanation":["③ — 복잡·갯벌이에요.","④ — 단순·모래사장이에요.","서해안과 동해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_b#25','soc',5,1,'u1','','g5_1_soc_u1_review_b','unit_review','SO5-1-u1-C8',4,'essay','teacher','새봄이네 수첩 ⑦을 보고 독도의 자연환경을 생김새·날씨·생물로 나누어 쓰고, 독도 전체를 천연기념물로 지정해 보호해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C8","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑦을 보고 독도의 자연환경을 생김새·날씨·생물로 나누어 쓰고, 독도 전체를 천연기념물로 지정해 보호해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 독도는 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌다. 날씨는 대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다. 괭이갈매기 같은 새와 해국 같은 식물이 산다. 독도는 화산섬이라 연구 가치가 크고 다양한 생물이 함께 어우러진 생태계를 지녔으므로 한 가지만이 아니라 전체를 보호해야 한다.","scoring_points":["생김새를 썼는가","날씨와 생물을 썼는가","전체를 보호해야 하는 까닭을 썼는가"]},"explanation":["동도·서도·바위섬이에요.","안개가 잦아요.","생태계 전체를 지켜요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#1','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C1',1,'mc','auto','새봄이네 수첩 ②에서 아래쪽에 넓게 펼쳐진 논이 있는 땅은 어떤 지형인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ②에서 아래쪽에 넓게 펼쳐진 논이 있는 땅은 어떤 지형인가요?","options":[{"t":"평야","correct":true},{"t":"산지","mis":"SO5-1-u1-X06"},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"}],"explanation":["넓고 평평한 땅이에요.","물줄기 아래쪽에 있어요.","평야예요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#2','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C2',1,'sa','auto','지형도에서 색이 뜻하는 높이를 알려 주는 부분을 무엇이라고 하나요? (□□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"sa","stem":"지형도에서 색이 뜻하는 높이를 알려 주는 부분을 무엇이라고 하나요? (□□)","answer":["범례"],"explanation":["지도 한쪽에 있어요.","색과 높이를 짝지어요.","범례예요."],"mis":"SO5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#3','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',1,'mc','auto','하천 주변의 땅은 대부분 어떠한가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X02']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"하천 주변의 땅은 대부분 어떠한가요?","options":[{"t":"200 m 미만의 낮고 평평한 땅이다","correct":true},{"t":"2,000 m가 넘는 높은 땅이다","mis":"SO5-1-u1-X06"},{"t":"험한 봉우리가 이어진 땅이다","mis":"SO5-1-u1-X06"},{"t":"바다로 둘러싸인 땅이다","mis":"SO5-1-u1-X02"}],"explanation":["하천은 낮은 곳으로 흘러요.","주변도 낮아요.","평야가 발달해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#4','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C4',1,'sa','auto','우리나라는 동·서·남 몇 면이 바다와 맞닿아 있나요? (숫자로)','{}'::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"sa","stem":"우리나라는 동·서·남 몇 면이 바다와 맞닿아 있나요? (숫자로)","answer":["3","세","삼"],"explanation":["동쪽·서쪽·남쪽이에요.","세 면이에요.","삼면이 바다예요."],"mis":"SO5-1-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#5','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',1,'ox','auto','아름다운 지형은 많은 사람이 찾는 관광지가 되기도 해요.',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"ox","stem":"아름다운 지형은 많은 사람이 찾는 관광지가 되기도 해요.","answer":"O","reason_options":[{"t":"독특하고 아름다운 경관을 보려고 사람들이 찾아가기 때문에","correct":true},{"t":"지형은 관광과 아무 관계가 없기 때문에","mis":"SO5-1-u1-X09"}],"mis":"SO5-1-u1-X09","explanation":["산지·하천·해안에 관광지가 있어요.","경관이 아름다워요.","사람들이 찾아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#6','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',1,'sa','auto','한 지역 안에서만 여행할 때 경로를 알아보기 쉽게 표시하려고 쓰는, 그 지역만 크게 나타낸 지도를 무엇이라고 하나요? (□□□)','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"sa","stem":"한 지역 안에서만 여행할 때 경로를 알아보기 쉽게 표시하려고 쓰는, 그 지역만 크게 나타낸 지도를 무엇이라고 하나요? (□□□)","answer":["백지도"],"explanation":["하얀 바탕 지도예요.","그 지역만 크게 나와요.","백지도예요."],"mis":"SO5-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#7','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C7',1,'sa','auto','독도는 우리나라 영토의 어느 쪽 끝에 있나요? (□쪽)','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"sa","stem":"독도는 우리나라 영토의 어느 쪽 끝에 있나요? (□쪽)","answer":["동쪽","동"],"explanation":["동해에 있어요.","해가 일찍 떠요.","동쪽 끝이에요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#8','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',1,'sa','auto','독도가 그려진 가장 오래된 우리나라 옛 지도의 이름은 무엇인가요? 「□□□□」','{}'::text[],false,'{"seq":8,"concept":"SO5-1-u1-C9","difficulty":1,"kind":"sa","stem":"독도가 그려진 가장 오래된 우리나라 옛 지도의 이름은 무엇인가요? 「□□□□」","answer":["팔도총도","「팔도총도」"],"explanation":["『신증동국여지승람』에 실렸어요.","우산도가 그려져 있어요.","「팔도총도」예요."],"mis":"SO5-1-u1-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#9','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C2',2,'ox','auto','지형도에서 초록색으로 칠해진 땅은 진한 갈색으로 칠해진 땅보다 높아요.',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"ox","stem":"지형도에서 초록색으로 칠해진 땅은 진한 갈색으로 칠해진 땅보다 높아요.","answer":"X","reason_options":[{"t":"범례에서 진한 갈색은 높은 땅, 초록색은 낮은 땅이기 때문에","correct":true},{"t":"초록색은 언제나 가장 높은 땅을 뜻하기 때문에","mis":"SO5-1-u1-X04"}],"mis":"SO5-1-u1-X04","explanation":["범례로 확인해요.","진할수록 높아요.","초록색은 낮은 땅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#10','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',2,'ox','auto','하천은 오랜 시간 땅을 깎아 새로운 지형을 만들기도 해요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"하천은 오랜 시간 땅을 깎아 새로운 지형을 만들기도 해요.","answer":"O","reason_options":[{"t":"흐르는 물이 오랜 시간 골짜기를 깎아 내기 때문에","correct":true},{"t":"하천은 땅에 아무 영향을 주지 않기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["물은 땅을 깎아요.","골짜기와 모양 지형이 생겨요.","한반도 모양 지형도 그래요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#11','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C4',2,'ox','auto','남해안은 섬이 아주 많아 다도해라고도 불러요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"ox","stem":"남해안은 섬이 아주 많아 다도해라고도 불러요.","answer":"O","reason_options":[{"t":"해안선이 복잡하고 크고 작은 섬이 많기 때문에","correct":true},{"t":"남해안에는 섬이 하나도 없기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["남해안은 섬이 많아요.","다도해라고 불러요.","해안선도 복잡해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#12','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',2,'ox','auto','파도가 바위를 깎아 만든 절벽과 동굴은 하천이 만든 경관이에요.',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"ox","stem":"파도가 바위를 깎아 만든 절벽과 동굴은 하천이 만든 경관이에요.","answer":"X","reason_options":[{"t":"바닷가에서 파도가 만든 해안의 경관이기 때문에","correct":true},{"t":"절벽과 동굴은 높은 산에서만 생기기 때문에","mis":"SO5-1-u1-X09"}],"mis":"SO5-1-u1-X09","explanation":["파도는 바다에서 쳐요.","해안의 바위를 깎아요.","해안이 만든 경관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#13','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',2,'ox','auto','여행 주제에는 정답이 없어서 내가 보고 싶은 것과 그 까닭을 생각해 정하면 돼요.',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"ox","stem":"여행 주제에는 정답이 없어서 내가 보고 싶은 것과 그 까닭을 생각해 정하면 돼요.","answer":"O","reason_options":[{"t":"내 관심이 곧 주제이고 까닭을 함께 생각하면 되기 때문에","correct":true},{"t":"선생님이 정해 준 주제만 쓸 수 있기 때문에","mis":"SO5-1-u1-X11"}],"mis":"SO5-1-u1-X11","explanation":["주제는 내가 정해요.","보고 싶은 것과 까닭을 생각해요.","정답은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#14','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C7',2,'ox','auto','독도는 우리 영토의 동쪽 경계를 알려 주는 섬이에요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"ox","stem":"독도는 우리 영토의 동쪽 경계를 알려 주는 섬이에요.","answer":"O","reason_options":[{"t":"우리나라 영토의 동쪽 끝에 있기 때문에","correct":true},{"t":"독도는 우리 영토의 서쪽 끝에 있기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도는 동쪽 끝이에요.","영토의 경계를 알려요.","그래서 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#15','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C8',2,'ox','auto','독도 바다 밑에는 「불타는 얼음」이라 불리는 가스 하이드레이트가 묻혀 있어요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"ox","stem":"독도 바다 밑에는 「불타는 얼음」이라 불리는 가스 하이드레이트가 묻혀 있어요.","answer":"O","reason_options":[{"t":"고체 형태의 천연가스가 바다 밑바닥에 묻혀 있기 때문에","correct":true},{"t":"가스 하이드레이트는 바다 위에 떠다니는 얼음이기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["고체로 된 천연가스예요.","바다 밑에 있어요.","미래 에너지 자원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#16','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',2,'ox','auto','「태정관 지령」은 일본이 만든 문서인데도 울릉도와 독도가 일본 땅이 아니라고 밝혔어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"ox","stem":"「태정관 지령」은 일본이 만든 문서인데도 울릉도와 독도가 일본 땅이 아니라고 밝혔어요.","answer":"O","reason_options":[{"t":"일본 스스로 두 섬이 자기 나라 땅이 아니라고 적은 국가 문서이기 때문에","correct":true},{"t":"「태정관 지령」은 우리나라가 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["일본의 국가 문서예요.","두 섬이 일본 땅이 아니라고 했어요.","그래서 더 분명한 증거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#17','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',3,'error','auto','새봄이네 수첩 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「물줄기가 서쪽으로 간 걸 보니 서쪽 땅이 더 높아.」","correct":true,"mis_target":"SO5-1-u1-X05"},{"t":"가은 — 「물줄기 아래쪽의 논은 평야에 있어.」","mis":"SO5-1-u1-X06"},{"t":"태린 — 「계곡물은 높은 산지에서 시작했어.」","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","서쪽으로 갔다면 서쪽이 낮아요.","윤호의 말이 거꾸로예요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#18','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',3,'mc','auto','새봄이네 수첩 ⑤처럼 지질 공원에서 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑤처럼 지질 공원에서 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설을 들으며 눈으로 보고 마음에 담되 자연물은 그대로 둔다","correct":true},{"t":"기념으로 작은 돌 조각을 가져간다","mis":"SO5-1-u1-X10"},{"t":"바위에 이름을 새겨 다녀간 표시를 한다","mis":"SO5-1-u1-X10"},{"t":"해설은 듣지 않고 사진만 찍는다","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원은 보전하는 곳이에요.","보고 배워요.","자연물은 그대로 둬요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#19','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',3,'mc','auto','친구의 계획서에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"친구의 계획서에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「해 질 녘 해안 사진이 정말 아름다워요. 저도 가 보고 싶어요!」","correct":true},{"t":"「이게 무슨 여행이야, 재미없겠다.」","mis":"SO5-1-u1-X12"},{"t":"「글씨가 엉망이네, 다시 써.」","mis":"SO5-1-u1-X12"},{"t":"「ㅋㅋㅋ」","mis":"SO5-1-u1-X12"}],"explanation":["느낀 점을 예의 있게 써요.","좋은 점을 칭찬해요.","놀리는 말은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#20','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C8',3,'mc','auto','독도에 사는 새와 식물, 주변 바다 생물을 함께 지키려고 우리나라가 한 일은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X10','SO5-1-u1-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도에 사는 새와 식물, 주변 바다 생물을 함께 지키려고 우리나라가 한 일은 어느 것인가요?","options":[{"t":"독도 전체를 천연기념물로 지정했다","correct":true},{"t":"독도에 큰 공항을 지었다","mis":"SO5-1-u1-X14"},{"t":"독도 바위를 캐어 박물관에 옮겼다","mis":"SO5-1-u1-X10"},{"t":"독도의 새를 모두 다른 섬으로 옮겼다","mis":"SO5-1-u1-X16"}],"explanation":["생물은 서로 이어져 있어요.","전체를 지켜야 해요.","천연기념물로 지정했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#21','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',3,'mc','auto','「조선왕국전도」와 「팔도총도」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「조선왕국전도」와 「팔도총도」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 사람뿐 아니라 멀리 유럽 사람들도 동해에 울릉도와 독도가 있음을 알았다","correct":true},{"t":"두 지도 모두 일본에서 만들었다","mis":"SO5-1-u1-X17"},{"t":"두 지도에는 독도가 그려지지 않았다","mis":"SO5-1-u1-X17"},{"t":"유럽 사람만 독도를 알았다","mis":"SO5-1-u1-X17"}],"explanation":["「팔도총도」는 우리 지도예요.","「조선왕국전도」는 프랑스 지도예요.","두 섬을 모두 그렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#22','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C10',3,'mc','auto','정부가 독도에 선착장·주민 숙소·등대를 만든 것의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"정부가 독도에 선착장·주민 숙소·등대를 만든 것의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 오가고 머물며 독도를 우리 땅으로 다스리는 데 필요한 시설을 갖춘 것이다","correct":true},{"t":"독도를 다른 나라에 빌려주려는 것이다","mis":"SO5-1-u1-X18"},{"t":"독도의 바위를 캐내려는 것이다","mis":"SO5-1-u1-X10"},{"t":"독도에 아무도 오지 못하게 하려는 것이다","mis":"SO5-1-u1-X18"}],"explanation":["시설이 있어야 오갈 수 있어요.","주민과 경비대가 머물러요.","우리 땅으로 다스려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#23','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',4,'mc','auto','새봄이네 수첩 ⑥과 ⑧을 함께 볼 때 독도가 우리 땅임을 보여 주는 근거를 가장 잘 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X16','SO5-1-u1-X17']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ⑥과 ⑧을 함께 볼 때 독도가 우리 땅임을 보여 주는 근거를 가장 잘 묶은 것은 어느 것인가요?","options":[{"t":"울릉도에서 눈으로 보일 만큼 가까워 예로부터 알았고, 일본이 만든 옛 지도도 조선 땅으로 나타냈다","correct":true},{"t":"독도에는 공항이 없고 안개가 자주 낀다","mis":"SO5-1-u1-X15"},{"t":"독도는 화산섬이라 바위가 많다","mis":"SO5-1-u1-X16"},{"t":"새봄이가 독도를 알리는 그림을 그리기로 했다","mis":"SO5-1-u1-X17"}],"explanation":["⑥ — 보이는 거리예요.","⑧ — 다른 나라 지도예요.","둘 다 영토의 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#24','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',4,'essay','teacher','새봄이네 수첩 ⑤에서 지질 공원 해설사가 한 일을 쓰고, 동생의 행동이 왜 바르지 않은지 쓴 뒤, 지질 공원을 지키려고 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C5","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑤에서 지질 공원 해설사가 한 일을 쓰고, 동생의 행동이 왜 바르지 않은지 쓴 뒤, 지질 공원을 지키려고 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 해설사는 바위가 생긴 까닭과 마을의 옛이야기를 엮어 알기 쉽게 설명해 주었다. 지질 공원의 돌은 오랜 시간이 만든 단 하나뿐인 자연이라 가져가면 되돌릴 수 없으므로 동생의 행동은 바르지 않다. 나는 해설을 귀 기울여 듣고, 바위를 만지거나 가져가지 않고 눈으로만 보며, 쓰레기를 되가져오겠다.","scoring_points":["해설사가 한 일을 썼는가","동생의 행동이 바르지 않은 까닭을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["해설사는 엮어서 설명해요.","자연물은 되돌릴 수 없어요.","보고 배우되 그대로 둬요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_c#25','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',4,'essay','teacher','새봄이네 수첩 ⑧에 나온 옛 지도와 사람 이야기가 각각 무엇을 말해 주는지 쓰고, 이 둘이 독도가 우리 땅이라는 근거가 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑧에 나온 옛 지도와 사람 이야기가 각각 무엇을 말해 주는지 쓰고, 이 둘이 독도가 우리 땅이라는 근거가 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 일본이 만든 옛 지도는 독도를 조선과 같은 색으로 칠해 당시 일본도 독도를 조선의 영토로 여겼음을 보여 준다. 안용복 이야기는 조선 사람이 일본에 건너가 두 섬이 조선 땅이라고 설명했고 일본도 이를 인정했음을 보여 준다. 다른 나라가 만든 자료와 옛사람의 노력 모두 독도를 우리 땅으로 나타내므로 우리 땅이라는 근거가 된다.","scoring_points":["옛 지도가 말하는 것을 썼는가","안용복 이야기가 말하는 것을 썼는가","두 가지가 근거가 되는 까닭을 썼는가"]},"explanation":["지도는 일본이 만들었어요.","안용복은 일본에 건너가 설명했어요.","둘 다 우리 땅을 보여 줘요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#1','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C1',1,'ox','auto','둘레가 바다로 둘러싸인 땅을 섬이라고 해요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"둘레가 바다로 둘러싸인 땅을 섬이라고 해요.","answer":"O","reason_options":[{"t":"사방이 바다와 맞닿아 있는 땅이기 때문에","correct":true},{"t":"섬은 하천 주변의 넓은 땅이기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["섬은 바다에 둘러싸여요.","배를 타고 가요.","독도도 섬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#2','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C2',1,'ox','auto','우리나라 땅은 북동쪽이 높고 남서쪽이 낮아요.',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"ox","stem":"우리나라 땅은 북동쪽이 높고 남서쪽이 낮아요.","answer":"O","reason_options":[{"t":"높은 산이 북쪽과 동쪽에 몰려 있기 때문에","correct":true},{"t":"높은 산이 남쪽과 서쪽에 몰려 있기 때문에","mis":"SO5-1-u1-X03"}],"mis":"SO5-1-u1-X03","explanation":["북쪽·동쪽에 높은 산이 많아요.","남쪽·서쪽은 낮아요.","북동쪽이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#3','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C3',1,'ox','auto','우리나라의 큰 하천은 대부분 북쪽과 동쪽으로 흘러요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"ox","stem":"우리나라의 큰 하천은 대부분 북쪽과 동쪽으로 흘러요.","answer":"X","reason_options":[{"t":"땅이 낮은 남쪽과 서쪽으로 흐르기 때문에","correct":true},{"t":"하천은 늘 높은 쪽으로 흐르기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["물은 낮은 곳으로 흘러요.","남쪽·서쪽이 낮아요.","그쪽으로 흘러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#4','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',1,'ox','auto','서해안은 해안선이 단순하고 섬이 거의 없어요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"ox","stem":"서해안은 해안선이 단순하고 섬이 거의 없어요.","answer":"X","reason_options":[{"t":"서해안은 해안선이 복잡하고 섬이 많기 때문에","correct":true},{"t":"서해안은 바다와 맞닿지 않았기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["서해안은 들쭉날쭉해요.","섬도 많아요.","단순한 쪽은 동해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#5','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C5',1,'mc','auto','우리나라에서 처음으로 세계 지질 공원 인증을 받은 곳은 어디인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":1,"kind":"mc","stem":"우리나라에서 처음으로 세계 지질 공원 인증을 받은 곳은 어디인가요?","options":[{"t":"제주특별자치도","correct":true},{"t":"울릉도","mis":"SO5-1-u1-X10"},{"t":"독도","mis":"SO5-1-u1-X10"},{"t":"서울","mis":"SO5-1-u1-X10"}],"explanation":["화산섬이에요.","2010년에 인증받았어요.","제주특별자치도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#6','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',1,'ox','auto','친구의 여행 계획서에는 놀리는 댓글을 남겨도 괜찮아요.',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C6","difficulty":1,"kind":"ox","stem":"친구의 여행 계획서에는 놀리는 댓글을 남겨도 괜찮아요.","answer":"X","reason_options":[{"t":"온라인에서도 예절을 지켜 느낀 점과 칭찬을 써야 하기 때문에","correct":true},{"t":"온라인에서는 예절이 필요 없기 때문에","mis":"SO5-1-u1-X12"}],"mis":"SO5-1-u1-X12","explanation":["놀리는 말은 상처를 줘요.","느낀 점을 예의 있게 써요.","좋은 점을 칭찬해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#7','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',1,'ox','auto','새봄이네가 독도에 비행기를 타지 않고 배를 탄 것은 독도에 공항이 없기 때문이에요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"ox","stem":"새봄이네가 독도에 비행기를 타지 않고 배를 탄 것은 독도에 공항이 없기 때문이에요.","answer":"O","reason_options":[{"t":"공항이 없어 항구에서 배를 타고 울릉도를 거쳐 가야 하기 때문에","correct":true},{"t":"비행기 표가 비쌌기 때문일 뿐이기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도에는 공항이 없어요.","배를 타고 가요.","울릉도를 거쳐요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#8','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C8',1,'ox','auto','독도는 오래전 바닷속 화산 활동으로 만들어졌어요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"ox","stem":"독도는 오래전 바닷속 화산 활동으로 만들어졌어요.","answer":"O","reason_options":[{"t":"바닷속에서 화산이 터져 생긴 화산섬이기 때문에","correct":true},{"t":"사람들이 흙을 쌓아 만든 섬이기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["독도는 화산섬이에요.","독특한 지형이 많아요.","연구 가치가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#9','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C1',2,'match','auto','새봄이네 수첩의 꼭지와 그날 만난 지형을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"새봄이네 수첩의 꼭지와 그날 만난 지형을 알맞게 이으세요.","pairs":[{"l":"①","r":"산지"},{"l":"②","r":"하천과 평야"},{"l":"③","r":"갯벌이 넓은 해안"},{"l":"④","r":"모래사장이 넓은 해안"}],"mis":"SO5-1-u1-X02","explanation":["①은 높은 산이에요.","②는 물줄기와 논이에요.","③은 갯벌, ④는 모래사장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#10','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C9',2,'mc','auto','두 물줄기가 합쳐지는 강가 마을과 지평선이 보이는 평야의 공통점은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"두 물줄기가 합쳐지는 강가 마을과 지평선이 보이는 평야의 공통점은 어느 것인가요?","options":[{"t":"둘 다 하천과 관계있는 경관이다","correct":true},{"t":"둘 다 높은 산지에 있다","mis":"SO5-1-u1-X09"},{"t":"둘 다 바다와 맞닿아 있다","mis":"SO5-1-u1-X09"},{"t":"둘 다 화산이 만든 섬이다","mis":"SO5-1-u1-X09"}],"explanation":["강가 마을은 하천이에요.","평야는 하천 주변에 생겨요.","둘 다 하천과 관계있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#11','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',2,'mc','auto','갯벌을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X09','SO5-1-u1-X06']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"갯벌을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?","options":[{"t":"서해안","correct":true},{"t":"동해안","mis":"SO5-1-u1-X07"},{"t":"높은 산지","mis":"SO5-1-u1-X09"},{"t":"하천의 상류","mis":"SO5-1-u1-X06"}],"explanation":["갯벌을 막는 일이에요.","갯벌은 서해안에 넓어요.","간척이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#12','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C5',2,'match','auto','경관과 그 경관을 만든 지형을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"match","stem":"경관과 그 경관을 만든 지형을 알맞게 이으세요.","pairs":[{"l":"바위 봉우리와 폭포가 있는 산","r":"산지"},{"l":"지평선이 보이는 들판","r":"평야"},{"l":"갯벌과 갈대밭이 펼쳐진 습지","r":"해안"}],"mis":"SO5-1-u1-X09","explanation":["봉우리와 폭포는 산지예요.","넓은 들판은 평야예요.","갯벌과 갈대밭은 해안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#13','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',2,'sa','auto','여행 계획서를 사진으로 찍어 올려 친구들과 나눌 때 쓰는 도구를 무엇이라고 하나요? (□□ □□□□□□)','{}'::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"sa","stem":"여행 계획서를 사진으로 찍어 올려 친구들과 나눌 때 쓰는 도구를 무엇이라고 하나요? (□□ □□□□□□)","answer":["공유 애플리케이션","공유애플리케이션","공유 앱"],"explanation":["함께 나누는 도구예요.","자리에서 언제든 볼 수 있어요.","공유 애플리케이션이에요."],"mis":"SO5-1-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#14','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',2,'sa','auto','독도가 있는 바다의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"sa","stem":"독도가 있는 바다의 이름을 두 글자로 쓰세요.","answer":["동해"],"explanation":["우리나라 동쪽 바다예요.","세 나라가 둘러싸요.","동해예요."],"mis":"SO5-1-u1-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#15','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C8',2,'match','auto','독도에서 볼 수 있는 것과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"match","stem":"독도에서 볼 수 있는 것과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"괭이갈매기","r":"새"},{"l":"해국","r":"식물"},{"l":"해양 심층수","r":"바다 자원"}],"mis":"SO5-1-u1-X16","explanation":["괭이갈매기는 새예요.","해국은 바위에 피는 식물이에요.","해양 심층수는 바다 자원이에요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#16','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C10',2,'mc','auto','홍순칠과 울릉도 청년들이 독도를 지키려고 만든 모임은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"홍순칠과 울릉도 청년들이 독도를 지키려고 만든 모임은 어느 것인가요?","options":[{"t":"독도 의용 수비대","correct":true},{"t":"독도 경비대","mis":"SO5-1-u1-X18"},{"t":"사이버 외교 사절단","mis":"SO5-1-u1-X18"},{"t":"지질 공원 해설단","mis":"SO5-1-u1-X10"}],"explanation":["울릉도 청년들이 함께했어요.","스스로 독도를 지켰어요.","독도 의용 수비대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#17','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C3',3,'ox','auto','평야가 하천 주변에 발달한 것과 우리나라 땅이 북동쪽은 높고 남서쪽은 낮은 것은 서로 관계가 있어요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"ox","stem":"평야가 하천 주변에 발달한 것과 우리나라 땅이 북동쪽은 높고 남서쪽은 낮은 것은 서로 관계가 있어요.","answer":"O","reason_options":[{"t":"높낮이가 하천의 방향을 정하고 하천이 흐르는 낮은 땅 주변에 평야가 펼쳐지기 때문에","correct":true},{"t":"평야는 땅의 높낮이와 상관없이 아무 데나 생기기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["높낮이 → 하천의 방향이에요.","하천이 흐르는 곳은 낮아요.","그 주변에 평야가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#18','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',3,'ox','auto','해안의 모습에 따라 해산물을 얻는 곳, 해수욕장, 간척지처럼 사람들의 생활 모습이 달라져요.',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"ox","stem":"해안의 모습에 따라 해산물을 얻는 곳, 해수욕장, 간척지처럼 사람들의 생활 모습이 달라져요.","answer":"O","reason_options":[{"t":"갯벌·모래사장 같은 해안 지형을 생활에 맞게 이용하기 때문에","correct":true},{"t":"해안 사람들은 지형과 상관없이 똑같이 살기 때문에","mis":"SO5-1-u1-X08"}],"mis":"SO5-1-u1-X08","explanation":["지형에 맞게 살아요.","갯벌에서는 해산물, 모래사장에서는 해수욕이에요.","간척도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#19','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',3,'ox','auto','새봄이네처럼 여러 지역을 두루 다니는 여행은 우리나라 전체 지도에, 한 지역 안의 여행은 그 지역 백지도에 경로를 그리는 것이 알맞아요.',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"ox","stem":"새봄이네처럼 여러 지역을 두루 다니는 여행은 우리나라 전체 지도에, 한 지역 안의 여행은 그 지역 백지도에 경로를 그리는 것이 알맞아요.","answer":"O","reason_options":[{"t":"경로의 넓이에 맞는 지도를 써야 알아보기 쉽기 때문에","correct":true},{"t":"어떤 여행이든 지도는 쓰지 않는 것이 좋기 때문에","mis":"SO5-1-u1-X11"}],"mis":"SO5-1-u1-X11","explanation":["넓은 여행은 전국 지도예요.","좁은 여행은 그 지역 백지도예요.","알아보기 쉬운 지도를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#20','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',3,'ox','auto','독도 주변 바다는 어업을 하는 우리 국민을 보호하고 배가 급할 때 대피할 수 있는 곳이기도 해요.',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"ox","stem":"독도 주변 바다는 어업을 하는 우리 국민을 보호하고 배가 급할 때 대피할 수 있는 곳이기도 해요.","answer":"O","reason_options":[{"t":"동해 한가운데의 섬이라 바다에서 일하는 사람들을 지켜 줄 수 있기 때문에","correct":true},{"t":"독도 주변에서는 배가 다닐 수 없기 때문에","mis":"SO5-1-u1-X15"}],"mis":"SO5-1-u1-X15","explanation":["독도는 바다 한가운데예요.","어업하는 국민을 지켜요.","급할 때 피할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#21','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C9',3,'ox','auto','대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 것은 독도가 우리 땅임을 나라가 분명히 밝힌 기록이에요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"ox","stem":"대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 것은 독도가 우리 땅임을 나라가 분명히 밝힌 기록이에요.","answer":"O","reason_options":[{"t":"나라가 공식 문서로 독도를 다스리는 곳을 정했기 때문에","correct":true},{"t":"칙령은 다른 나라가 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["칙령은 나라의 명령이에요.","울릉군이 독도를 다스려요.","10월 25일 독도의 날이 됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#22','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C11',3,'ox','auto','인공지능으로 만든 그림이 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만들면 돼요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"ox","stem":"인공지능으로 만든 그림이 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만들면 돼요.","answer":"O","reason_options":[{"t":"조건을 고칠수록 원하는 그림에 가까워지기 때문에","correct":true},{"t":"한 번 만든 그림은 다시 만들 수 없기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["고칠 수 있는 것은 조건이에요.","여러 번 다시 만들어요.","마음에 들 때까지 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#23','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C10',4,'mc','auto','새봄이네 수첩 ⑦과 ⑧을 함께 볼 때 독도를 지키는 사람들을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ⑦과 ⑧을 함께 볼 때 독도를 지키는 사람들을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"옛날의 안용복부터 오늘의 독도 경비대, 그리고 독도를 알리려는 새봄이까지 모두가 지킨다","correct":true},{"t":"독도 경비대 혼자서만 지킨다","mis":"SO5-1-u1-X18"},{"t":"옛날 사람들만 지켰고 지금은 아무도 지키지 않는다","mis":"SO5-1-u1-X18"},{"t":"관광객은 독도를 지키는 일과 관계없다","mis":"SO5-1-u1-X18"}],"explanation":["옛사람과 오늘의 경비대가 있어요.","새봄이도 알리기로 했어요.","모두가 함께 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#24','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',4,'essay','teacher','새봄이네 수첩 ①~④를 참고해 「여러 지형을 만나는 국토 여행」 계획을 세우세요. 주제와 까닭, 여행지 두 곳과 지형, 경로를 정할 때 생각할 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ①~④를 참고해 「여러 지형을 만나는 국토 여행」 계획을 세우세요. 주제와 까닭, 여행지 두 곳과 지형, 경로를 정할 때 생각할 점을 쓰세요.","answer_guide":{"answer":"예: 나의 주제는 「산에서 바다까지 물을 따라가는 여행」이다. 땅의 높낮이가 지형을 어떻게 만드는지 직접 보고 싶기 때문이다. 먼저 북동쪽의 높은 산지에서 계곡을 보고, 물줄기를 따라 내려가 넓은 평야를 본 뒤 서해안의 갯벌에 가겠다. 경로는 이동 거리가 너무 길어지지 않게 물이 흐르는 차례에 맞추어 화살표로 잇겠다.","scoring_points":["주제와 까닭을 썼는가","여행지와 지형을 맞게 썼는가","경로를 정할 때 생각할 점을 썼는가"]},"explanation":["주제를 먼저 정해요.","여행지의 지형을 써요.","동선과 목적을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u1_review_d#25','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C11',4,'essay','teacher','새봄이처럼 독도를 알리는 그림을 인공지능으로 만든다고 생각하고, 그림 이름과 자세한 조건 세 가지를 쓴 뒤, 친구들에게 소개할 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C11","difficulty":4,"kind":"essay","stem":"새봄이처럼 독도를 알리는 그림을 인공지능으로 만든다고 생각하고, 그림 이름과 자세한 조건 세 가지를 쓴 뒤, 친구들에게 소개할 말을 쓰세요.","answer_guide":{"answer":"예: 그림 이름은 「안개 걷힌 아침의 독도」이다. 조건은 ① 동도와 서도가 나란히 보이는 바다, ② 하늘을 나는 괭이갈매기 무리, ③ 바위에 핀 해국과 사철나무이다. 소개할 말: 「제 그림의 이름은 「안개 걷힌 아침의 독도」입니다. 동도와 서도, 괭이갈매기, 바위에 핀 해국을 조건으로 독도의 아름다운 자연을 표현했습니다.」","scoring_points":["그림 이름을 붙였는가","독도에 맞는 자세한 조건 세 가지를 썼는가","조건과 표현한 것을 넣어 소개했는가"]},"explanation":["이름을 붙여요.","조건은 자세하게 써요.","무엇을 표현했는지 소개해요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C1','soc',5,1,'u2',1,'날씨와 기후 — 날씨는 짧은 시간 동안의 대기(공기) 상태로 하루 사이에도 바뀌고, 기후는 오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태 · 기후를 구성하는 요소는 기온(공기의 따뜻하고 차가운 정도)·강수(비·눈처럼 땅에 내린 물)·바람(공기가 움직이는 현상)이고 여러 해에 걸친 기록을 모아야 드러남 · 「사계절이 뚜렷하다」는 기후, 「오늘은 맑다」는 날씨',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C2','soc',5,1,'u2',1,'기후와 생활 — 기후는 의식주 생활과 산업 발전에 영향을 줌(기온이 높고 비가 많은 곳은 벼농사가 활발해 쌀 음식이 발달, 바람이 강한 곳은 바람으로 전기를 만드는 시설, 계절에 맞는 옷, 눈이 많은 겨울에 여는 축제) · 하루의 비로 행사를 못 하는 것은 날씨의 영향이고, 여러 해 되풀이되는 모습에 맞춘 생활이 기후의 영향',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C3','soc',5,1,'u2',2,'계절에 따른 바람과 기온 — 여름에는 남쪽 바다에서 뜨겁고 습한 바람이, 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어옴(바람이 지나온 곳이 바다냐 육지냐가 성질을 정함) · 우리나라는 남북으로 길어 대체로 남쪽으로 갈수록 기온이 높고, 남북 기온 차이는 여름보다 겨울에 훨씬 큼(여름엔 모두 덥고 겨울엔 북쪽만 크게 추워짐) · 등온선은 기온이 같은 곳을 이은 선',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C4','soc',5,1,'u2',2,'강수의 분포와 계절 — 연 강수량은 대체로 남쪽으로 갈수록 많아짐(분포도의 파란색이 진할수록 많음) · 계절로는 여름에 연 강수량의 절반 이상이 내리고 겨울에는 대체로 적음 · 봄은 온화하고 건조, 여름은 덥고 비가 잦음, 가을은 맑고 건조, 겨울은 춥고 건조하며 눈이 옴 — 통계 지도와 그래프에서 읽어 냄',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C5','soc',5,1,'u2',3,'계절별 자연재해 — 자연재해는 피할 수 없는 자연 현상으로 사람들이 입는 생명이나 재산상의 피해(자연 현상만으로는 재해가 아님) · 계절마다 바람·기온·강수가 달라 자주 생기는 재해도 다름: 봄 — 황사(사막의 모래 먼지가 바람을 타고 옴)·가뭄, 여름 — 폭염·호우(비가 많이 내림)·홍수(물이 흘러넘침), 여름과 가을 사이 — 태풍(많은 비와 강한 바람, 대체로 남서쪽에서 북동쪽으로), 겨울 — 폭설·한파',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C6','soc',5,1,'u2',3,'자연재해 피해를 줄이는 노력 — 자연재해는 막을 수 없지만 피해는 줄일 수 있음 · 저수지·댐·제방 같은 시설을 마련하고 재난 대비 훈련을 함 · 기상 특보(주의보·경보로 미리 알리는 정보)와 긴급 재난 문자로 알림 · 국민 행동 요령은 어린이를 포함한 국민 누구나 알고 실천함(태풍 때 외출 삼가기·시설물 정리) · 숲을 농경지로 일구거나 물길을 바꾸면 피해가 커지기도 함 · 예보 분석관이 날씨를 예측함',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C7','soc',5,1,'u2',4,'기후변화와 심해지는 자연재해 — 숲 파괴·석유와 석탄을 지나치게 쓰는 인간 활동으로 지구 온난화(지구의 기온이 높아지는 현상)가 심해져 전 세계에 기후변화가 나타남 · 우리나라는 연평균 기온이 꾸준히 올라가고(약 백 년 동안 1.9 ℃) 여름은 길어지고 겨울은 짧아짐 · 자연재해를 예측하기 어려워지고 강도가 세지며 횟수도 늘어 피해가 커짐(폭염·이상 고온·극한 호우·예측이 어려운 태풍)',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C8','soc',5,1,'u2',4,'기후 행동 — 기후변화를 막으려는 모든 노력 · 세계 여러 나라(파리 협정으로 기온 상승을 막기로 약속)·정부와 국회(기구 설치, 법과 제도)·기업(친환경 재료, 오염 물질 줄이기)·개인(에너지 아끼기, 대중교통, 일회용품 줄이기, 급식 남기지 않기, 빈 교실 전등 끄기)이 저마다 함 · 누구나 참여할 수 있고 매일 스스로 실천할 일을 골라 실천한 뒤 돌아보고 다시 이어 감',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C9','soc',5,1,'u2',5,'인구 분포와 인구 밀도 — 인구는 일정한 지역에 사는 사람의 수, 인구 분포는 그 인구가 모이거나 흩어져 있는 정도 · 인구 분포는 기후·지형 같은 자연환경과 일자리·교통·교육 같은 인문환경의 영향을 받음 · 인구 밀도는 일정한 넓이(1 km²) 안에 사는 사람의 수로 인구가 모여 있는 정도를 알려 줌 — 사람 수와 땅 넓이를 함께 봐야 함(좁은 땅에 많은 사람이면 높음) · 대체로 도시가 발달한 지역에서 높음',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C10','soc',5,1,'u2',6,'우리나라 인구 분포의 변화 — 과거(1960년 무렵)에는 벼농사 중심의 농업 사회라 자연환경의 영향을 많이 받아 기후가 온화하고 평야가 발달한 국토의 남서쪽에 모여 살았고, 기온이 낮고 산지가 많은 곳은 인구 밀도가 낮았음 · 1960년대 이후 산업화로 도시가 발달하며 많은 사람이 촌락에서 도시로 옮겨 인구 100명 중 92명 정도가 도시에 살고, 일자리·교통 같은 인문환경의 영향이 커져 수도권(서울특별시·인천광역시·경기도)과 대도시에 모임 — 인구의 절반 정도가 수도권, 옮겨 온 가장 큰 까닭은 직업',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C11','soc',5,1,'u2',6,'수도권과 비수도권의 인구 구조 — 인구 구조는 인구를 나이·성별 등으로 나누어 본 짜임새(유소년층 14세 이하·청장년층 15~64세·노년층 65세 이상) · 일자리와 교육 기회를 찾아 청장년층이 모인 수도권은 청장년층 비율이 높고, 청장년층이 빠져나간 비수도권은 노년층 비율이 더 높음',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C12','soc',5,1,'u2',7,'인구 분포의 불균형에 따른 문제 — 인구가 집중하는 수도권: 주택 부족과 가격 상승, 교통 혼잡과 주차 문제, 쓰레기와 환경 문제, 시설 부족, 삶의 질 저하 · 인구가 줄어드는 비수도권: 상점·병원·학교 같은 시설과 일자리 감소, 빈집과 폐교, 생활 편의 시설 감소, 청장년층 유출로 일손 부족, 식품 사막 · 두 지역의 일이 서로를 밀어붙이며 되풀이되어 지역 격차가 커지고 국가 경쟁력(다른 나라와 경쟁하는 힘)이 떨어질 수 있음 · 순이동은 들어온 인구수에서 나간 인구수를 뺀 값(20대 청년이 취업과 학업 때문에 수도권으로)',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C13','soc',5,1,'u2',8,'인구 분포의 불균형을 해결하는 노력 — 정부: 국가 균형 발전 기구·제도와 법, 공공 기관의 지방 이전(직원과 가족이 함께 옮겨 감)과 혁신 도시(공공 기관 이전을 계기로 새 성장 동력을 만드는 미래형 도시), 고향 사랑 기부제(고향이나 관심 지역에 기부, 답례품과 세금 혜택), 로컬 브랜딩(지역의 자원·문화로 지역만의 매력), 청년 마을 만들기(청년 정착 지원), 디지털 관광 주민증, 작은 학교 살리기 · 지역 스스로: 새 일자리, 주거·교육 환경 개선, 문화생활·창업 지원, 주민이 참여하는 발전 사업(소득 증가 → 지역 경제 활발 → 인구 증가) · 로컬 크리에이터 — 함께 잘 사는 국토',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C14','soc',5,1,'u2',8,'해결 방안을 평가하는 세 잣대 — 떠올린 방안은 ① 문제의 원인을 해결하는 데 도움이 되는가 ② 도덕적으로 옳은가(누구에게 억지로 시키거나 벌주지 않는가) ③ 드는 비용과 노력을 생각할 때 실현할 수 있는가를 모두 살핌 — 하나만 보면 좋아 보이던 방안도 다른 잣대에서 걸릴 수 있음 · 방안을 떠올릴 때는 원인을 줄이는 법, 수도권 인구를 나누는 법, 비수도권에 사람이 모이게 하는 법을 생각함',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO5-1-u2-C15','soc',5,1,'u2',9,'공부한 내용을 동시와 시화로 표현하기 — 단원에서 공부한 내용(기후·자연재해·기후 행동·인구 분포·불균형) 가운데 주제를 고름 → 주제에 대한 내 생각과 경험, 공부한 내용이 드러나게 순서를 생각하며 이야기로 씀 → 하고 싶은 말만 남겨 짧게 줄이고 운율(읽을 때 느껴지는 가락)을 살려 동시로 지음 → 다시 읽으며 이야기 내용이 잘 나타나게 고침 → 동시의 내용을 나타내는 장면을 그려 시화를 완성하고 친구와 바꿔 보며 좋은 점을 말해 줌',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X01','soc',5,'u2',ARRAY['SO5-1-u2-C1']::text[],'날씨와 기후를 바꾸어 쓴다(하루의 하늘을 기후라고, 여러 해의 모습을 날씨라고 한다)','하루 = 날씨 · 여러 해 = 기후') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X02','soc',5,'u2',ARRAY['SO5-1-u2-C1']::text[],'기후를 구성하는 요소(기온·강수·바람)를 놓치거나 지형·인구처럼 대기 상태가 아닌 것을 넣는다','기온 · 강수 · 바람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X03','soc',5,'u2',ARRAY['SO5-1-u2-C2']::text[],'기후와 생활 모습(음식·옷·시설·축제·산업)을 맞지 않게 짝짓거나, 그날의 날씨 때문에 생긴 일을 기후의 영향으로 여긴다','여러 해 되풀이되는 모습에 맞춘 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X04','soc',5,'u2',ARRAY['SO5-1-u2-C3']::text[],'계절마다 불어오는 바람의 방향과 성질을 바꾸어 안다(여름에 북서쪽 육지 바람, 겨울에 남쪽 바다 바람 등)','여름 — 남쪽 바다·뜨겁고 습함 · 겨울 — 북서쪽 육지·차갑고 건조') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X05','soc',5,'u2',ARRAY['SO5-1-u2-C3']::text[],'남북의 기온 차이를 거꾸로 안다(북쪽이 더 따뜻하다고, 또는 차이가 여름에 더 크다고)','남쪽일수록 따뜻 · 차이는 겨울에 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X06','soc',5,'u2',ARRAY['SO5-1-u2-C3','SO5-1-u2-C4']::text[],'등온선·분포도·그래프를 잘못 읽는다(등온선을 강수량이나 높이가 같은 선으로, 진한 색을 적다고 읽는 등)','등온선 = 기온이 같은 곳 · 진할수록 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X07','soc',5,'u2',ARRAY['SO5-1-u2-C4']::text[],'강수의 계절·지역 분포를 거꾸로 안다(겨울에 가장 많다고, 북쪽일수록 많다고)','여름에 절반 이상 · 남쪽으로 갈수록 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X08','soc',5,'u2',ARRAY['SO5-1-u2-C5']::text[],'자연재해의 뜻을 잘못 안다(사람이 일으킨 사고나 피해 없는 자연 현상도 자연재해라고 여긴다)','피할 수 없는 자연 현상 + 사람의 피해') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X09','soc',5,'u2',ARRAY['SO5-1-u2-C5']::text[],'계절과 자연재해, 자연재해와 그 특징을 바꾸어 짝짓는다','봄 황사·가뭄 · 여름 폭염·호우·홍수 · 태풍 · 겨울 폭설·한파') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X10','soc',5,'u2',ARRAY['SO5-1-u2-C6']::text[],'기상 특보·국민 행동 요령의 뜻을 오해하거나, 행동 요령은 어른만 알면 된다고, 특보가 나와도 평소처럼 지내도 된다고 여긴다','미리 알리는 정보 · 나를 지키는 것도 내 몫') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X11','soc',5,'u2',ARRAY['SO5-1-u2-C6']::text[],'사람이 땅의 모습을 바꾸는 일(숲을 일구기·물길 바꾸기)이 자연재해의 피해와 상관없다고 여긴다','숲과 물길은 물을 머금고 흘려보내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X12','soc',5,'u2',ARRAY['SO5-1-u2-C7']::text[],'기후변화의 원인과 방향을 거꾸로 안다(기온이 내려간다고, 겨울이 길어진다고, 숲 가꾸기가 원인이라고)','인간 활동 → 지구 온난화 → 기온 상승') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X13','soc',5,'u2',ARRAY['SO5-1-u2-C7']::text[],'자연재해가 잦고 세진 것을 우연으로 여겨 기후변화와의 관계를 놓친다','더 자주 · 더 세게 · 예측은 더 어렵게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X14','soc',5,'u2',ARRAY['SO5-1-u2-C8']::text[],'기후 행동의 뜻과 주체를 헷갈린다(관찰·기록으로 여기거나, 특별한 사람이나 나라만 하는 일로, 나 하나 해도 소용없다고 여긴다)','막으려는 모든 노력 · 누구나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X15','soc',5,'u2',ARRAY['SO5-1-u2-C8']::text[],'기후 행동을 고르기만 하고 실천과 돌아보기를 놓치거나, 잘 안 된 날 그만둔다','고르기 → 실천하기 → 돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X16','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구·인구 분포·인구 밀도의 뜻을 서로 바꾸어 안다','사람 수 · 모인 정도 · 1 km² 안의 사람 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X17','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구 분포에 영향을 주는 환경을 자연환경과 인문환경으로 잘못 나눈다','자연 — 기후·지형 · 인문 — 일자리·교통·교육') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X18','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구 밀도를 사람 수만으로, 또는 땅 넓이만으로 판단한다(넓은 땅이라서 밀도가 높다고 여기는 등)','사람 수와 넓이를 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X19','soc',5,'u2',ARRAY['SO5-1-u2-C10']::text[],'과거와 오늘날의 인구 분포와 그 까닭을 바꾸어 안다(옛날부터 수도권에 모였다고, 사람들이 도시에서 촌락으로 옮겼다고, 오늘날에도 자연환경의 영향이 가장 크다고)','과거 남서쪽 평야·자연 · 오늘 수도권·인문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X20','soc',5,'u2',ARRAY['SO5-1-u2-C10','SO5-1-u2-C11']::text[],'수도권의 범위나 수도권·비수도권의 인구 구조를 잘못 안다','서울·인천·경기 · 수도권은 청장년층이 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X21','soc',5,'u2',ARRAY['SO5-1-u2-C12']::text[],'수도권의 문제와 비수도권의 문제를 바꾸어 짝짓는다(수도권에 빈집·폐교, 비수도권에 집값 상승·교통 혼잡)','몰리는 곳 · 빠져나가는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X22','soc',5,'u2',ARRAY['SO5-1-u2-C12']::text[],'인구 분포의 불균형이 저절로 풀린다고, 한 지역만의 문제라고, 나라 전체의 힘과 관계없다고 여긴다','되풀이되는 두 고리 · 국가 경쟁력') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X23','soc',5,'u2',ARRAY['SO5-1-u2-C13']::text[],'불균형을 해결하는 노력의 뜻이나 방향을 헷갈린다(공공 기관을 수도권으로 모은다고, 고향에 사는 사람만 기부한다고 여기는 등)','사람과 일자리가 고르게 · 함께 잘 사는 국토') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X24','soc',5,'u2',ARRAY['SO5-1-u2-C14']::text[],'해결 방안을 한 가지 잣대로만 보아, 억지로 옮기게 하거나 벌주는 방안, 비용이 지나친 방안, 원인과 이어지지 않는 방안도 좋다고 여긴다','원인 · 옳음 · 실현 — 셋 다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X25','soc',5,'u2',ARRAY['SO5-1-u2-C2','SO5-1-u2-C4','SO5-1-u2-C10','SO5-1-u2-C12']::text[],'기후와 인구 공부를 통계 수치·연도를 외우는 것으로 여겨 자료에서 특징과 까닭을 읽어 내는 것을 놓친다','외우기보다 자료를 읽고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO5-1-u2-X26','soc',5,'u2',ARRAY['SO5-1-u2-C15']::text[],'동시를 지을 때 겪지 않은 일을 넣거나, 이야기를 그대로 옮기거나, 고치지 않거나, 동시와 상관없는 그림을 그린다','내 이야기 · 짧게 · 다시 읽고 고치기 · 내용을 나타내는 그림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#1','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'mc','auto','어떤 날은 맑고 어떤 날은 비가 오는 것처럼, 짧은 시간 동안의 대기 상태를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"어떤 날은 맑고 어떤 날은 비가 오는 것처럼, 짧은 시간 동안의 대기 상태를 무엇이라고 하나요?","options":[{"t":"날씨","correct":true},{"t":"기후","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"인구","mis":"SO5-1-u2-X02"}],"explanation":["하루 사이에도 바뀌어요.","나가기 전에 확인해요.","이것을 날씨라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#2','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'mc','auto','오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태는 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태는 어느 것인가요?","options":[{"t":"기후","correct":true},{"t":"날씨","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"계절","mis":"SO5-1-u2-X01"}],"explanation":["여러 해를 모아야 보여요.","평균적이고 종합적인 모습이에요.","기후라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#3','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'sa','auto','공기의 따뜻하고 차가운 정도를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"sa","stem":"공기의 따뜻하고 차가운 정도를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기온"],"explanation":["덥다·춥다를 나타내요.","온도계로 재요.","기온이에요."],"mis":"SO5-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#4','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'ox','auto','기온·강수·바람은 기후를 구성하는 요소예요.',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"ox","stem":"기온·강수·바람은 기후를 구성하는 요소예요.","answer":"O","reason_options":[{"t":"이 셋을 여러 해 동안 살펴보면 그 지역의 대기 상태가 드러나기 때문에","correct":true},{"t":"기후는 땅의 생김새로만 알 수 있기 때문에","mis":"SO5-1-u2-X02"}],"mis":"SO5-1-u2-X02","explanation":["기온은 따뜻하고 차가운 정도예요.","강수는 비·눈, 바람은 공기의 움직임이에요.","셋이 기후를 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#5','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','세 친구의 말 가운데 기후를 바르게 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"세 친구의 말 가운데 기후를 바르게 말한 친구는 누구인가요?","options":[{"t":"세아","correct":true},{"t":"하람","mis":"SO5-1-u2-X01"},{"t":"도윤","mis":"SO5-1-u2-X01"},{"t":"세 친구 모두","mis":"SO5-1-u2-X01"}],"explanation":["맑은 하늘은 오늘 하루의 일이에요.","매일 바뀌는 것은 날씨예요.","사계절이 뚜렷한 것이 기후예요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"오늘은 하늘이 맑아서 기후가 참 좋네."},{"who":"도윤","text":"어제는 비가 왔으니 기후가 매일 바뀌는 거야."},{"who":"세아","text":"우리나라는 봄·여름·가을·겨울이 뚜렷한 기후야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#6','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','기후를 구성하는 요소가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"기후를 구성하는 요소가 아닌 것은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"기온","mis":"SO5-1-u2-X02"},{"t":"강수","mis":"SO5-1-u2-X02"},{"t":"바람","mis":"SO5-1-u2-X02"}],"explanation":["기후는 대기의 상태예요.","기온·강수·바람이 요소예요.","지형은 땅의 생김새예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#7','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','눈이나 비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"눈이나 비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요?","options":[{"t":"강수","correct":true},{"t":"기온","mis":"SO5-1-u2-X02"},{"t":"바람","mis":"SO5-1-u2-X02"},{"t":"습지","mis":"SO5-1-u2-X02"}],"explanation":["비도 눈도 하늘에서 내려요.","땅에 내린 물이에요.","강수라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#8','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C2',2,'mc','auto','기온이 높고 비가 많이 내리는 지역에서 발달하기 쉬운 음식 문화는 어느 것인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"기온이 높고 비가 많이 내리는 지역에서 발달하기 쉬운 음식 문화는 어느 것인가요?","options":[{"t":"벼농사가 활발해 쌀로 만든 음식","correct":true},{"t":"얼음으로만 만든 음식","mis":"SO5-1-u2-X03"},{"t":"물을 거의 쓰지 않는 음식","mis":"SO5-1-u2-X03"},{"t":"바람에 말린 음식만","mis":"SO5-1-u2-X03"}],"explanation":["벼는 물이 많이 필요해요.","덥고 비가 많으면 벼가 잘 자라요.","쌀 음식이 발달했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#9','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C2',2,'ox','auto','바람이 강하게 부는 지역에서는 바람의 힘으로 전기를 만드는 시설이 발달하기 쉬워요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"ox","stem":"바람이 강하게 부는 지역에서는 바람의 힘으로 전기를 만드는 시설이 발달하기 쉬워요.","answer":"O","reason_options":[{"t":"그 지역의 기후를 이용해 산업을 일으키기 때문에","correct":true},{"t":"바람은 기후와 아무 관계가 없기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["기후는 산업에도 영향을 줘요.","바람이 세면 그 힘을 써요.","바람으로 전기를 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_basic#10','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',3,'error','auto','날씨와 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"error","stem":"날씨와 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「내일 소풍 가니까 기후를 꼭 확인해야겠어.」","correct":true,"mis_target":"SO5-1-u2-X01"},{"t":"준혁 — 「기후는 여러 해 기록을 모아야 알 수 있어.」","mis":"SO5-1-u2-X01"},{"t":"나린 — 「날씨는 하루 사이에도 바뀌어.」","mis":"SO5-1-u2-X01"}],"explanation":["내일 하루의 대기 상태는 날씨예요.","소풍 전에는 날씨를 봐요.","윤서는 기후라고 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#1','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',2,'sa','auto','날씨와 달리 여러 해에 걸쳐 나타나는 평균적이며 종합적인 대기 상태를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"sa","stem":"날씨와 달리 여러 해에 걸쳐 나타나는 평균적이며 종합적인 대기 상태를 두 글자로 무엇이라고 하나요?","answer":["기후"],"explanation":["하루가 아니라 오랜 기간이에요.","평균적인 모습이에요.","기후예요."],"mis":"SO5-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#2','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',2,'match','auto','생활 모습 카드를 보고 카드와 영향을 준 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"match","stem":"생활 모습 카드를 보고 카드와 영향을 준 것을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"덥고 비가 많은 기후"},{"l":"㉡","r":"바람이 센 기후"},{"l":"㉢","r":"눈이 많은 겨울 기후"},{"l":"㉣","r":"그날의 날씨"}],"mis":"SO5-1-u2-X03","explanation":["㉠은 벼농사, ㉡은 바람 발전이에요.","㉢은 해마다 같은 때 여는 축제예요.","㉣은 그날 하루의 소나기 때문이에요."],"asset":{"type":"passage","lines":["㉠ 기온이 높고 비가 많은 들판 — 논이 넓고 밥을 지어 먹는다.","㉡ 바람이 늘 세게 부는 언덕 — 커다란 날개가 돌아간다.","㉢ 겨울에 눈이 많이 쌓이는 마을 — 해마다 같은 때 축제를 연다.","㉣ 지난 토요일 — 소나기가 와서 운동회를 미루었다."],"title":"생활 모습 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#3','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',3,'mc','auto','「오늘은 맑고 쾌청한 기후래요」라는 말이 알맞지 않은 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"mc","stem":"「오늘은 맑고 쾌청한 기후래요」라는 말이 알맞지 않은 까닭은 어느 것인가요?","options":[{"t":"하루의 대기 상태는 기후가 아니라 날씨이기 때문에","correct":true},{"t":"기후는 비가 오는 날에만 쓰는 말이기 때문에","mis":"SO5-1-u2-X01"},{"t":"맑은 날에는 대기가 없기 때문에","mis":"SO5-1-u2-X02"},{"t":"기후는 바람이 불 때만 쓰는 말이기 때문에","mis":"SO5-1-u2-X02"}],"explanation":["「오늘」은 하루예요.","하루의 대기 상태는 날씨예요.","기후는 여러 해를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#4','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',3,'mc','auto','생활 모습 카드 가운데 기후가 아니라 날씨의 영향을 받은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"mc","stem":"생활 모습 카드 가운데 기후가 아니라 날씨의 영향을 받은 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SO5-1-u2-X03"},{"t":"㉡","mis":"SO5-1-u2-X03"},{"t":"㉢","mis":"SO5-1-u2-X03"}],"explanation":["㉠~㉢은 해마다 되풀이되는 모습이에요.","㉣은 지난 토요일 하루의 일이에요.","그래서 날씨의 영향이에요."],"asset":{"type":"passage","lines":["㉠ 기온이 높고 비가 많은 들판 — 논이 넓고 밥을 지어 먹는다.","㉡ 바람이 늘 세게 부는 언덕 — 커다란 날개가 돌아간다.","㉢ 겨울에 눈이 많이 쌓이는 마을 — 해마다 같은 때 축제를 연다.","㉣ 지난 토요일 — 소나기가 와서 운동회를 미루었다."],"title":"생활 모습 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#5','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',3,'mc','auto','세 해 동안 계절마다 기온·강수·바람을 기록해 모았어요. 이 기록으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"mc","stem":"세 해 동안 계절마다 기온·강수·바람을 기록해 모았어요. 이 기록으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"그 지역 계절별 기후의 특징","correct":true},{"t":"내일 비가 올지","mis":"SO5-1-u2-X01"},{"t":"그 지역에 사는 사람 수","mis":"SO5-1-u2-X02"},{"t":"그 지역 산의 높이","mis":"SO5-1-u2-X02"}],"explanation":["여러 해 기록을 모았어요.","평균적인 모습이 드러나요.","앞날의 날씨는 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#6','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',3,'ox','auto','계절마다 입는 옷이 다른 것도 기후가 생활에 주는 영향이에요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"ox","stem":"계절마다 입는 옷이 다른 것도 기후가 생활에 주는 영향이에요.","answer":"O","reason_options":[{"t":"해마다 되풀이되는 계절의 기온에 맞추어 옷을 입기 때문에","correct":true},{"t":"옷은 기후가 아니라 땅의 생김새에 따라 정하기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["여름엔 얇은 옷을 입어요.","겨울엔 두꺼운 옷을 입어요.","기후에 맞춘 의생활이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#7','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',3,'error','auto','기후와 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"error","stem":"기후와 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「비 때문에 체육 대회가 미뤄진 건 우리 지역 기후 탓이야.」","correct":true,"mis_target":"SO5-1-u2-X03"},{"t":"민지 — 「겨울에 눈이 많은 곳은 눈 축제를 열기 좋아.」","mis":"SO5-1-u2-X03"},{"t":"하율 — 「기후는 사람들이 먹고 입고 사는 모습에 영향을 줘.」","mis":"SO5-1-u2-X03"}],"explanation":["하루의 비는 날씨예요.","기후 탓이라고 할 수 없어요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#8','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',4,'mc','auto','기후를 알아보는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02','SO5-1-u2-X25']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C1","difficulty":4,"kind":"mc","stem":"기후를 알아보는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 해 동안 쌓인 기온·강수·바람 기록을 함께 살펴보고 생활과 이어 생각한다","correct":true},{"t":"오늘 하루 하늘만 보고 그 지역의 기후를 정한다","mis":"SO5-1-u2-X01"},{"t":"기온만 재면 되므로 비와 바람은 살피지 않는다","mis":"SO5-1-u2-X02"},{"t":"기후는 생활과 관계없으니 기록만 외운다","mis":"SO5-1-u2-X25"}],"explanation":["여러 해를 모아요.","세 요소를 두루 봐요.","생활과 이어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#9','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C2',4,'mc','auto','기후가 우리 생활에 주는 영향을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X03','SO5-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":4,"kind":"mc","stem":"기후가 우리 생활에 주는 영향을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"먹는 음식, 입는 옷과 사는 집, 산업 발전까지 두루 영향을 준다","correct":true},{"t":"입는 옷에만 영향을 주고 음식과는 관계없다","mis":"SO5-1-u2-X03"},{"t":"산업에만 영향을 주고 생활과는 관계없다","mis":"SO5-1-u2-X03"},{"t":"비가 오는 날에만 생활에 영향을 준다","mis":"SO5-1-u2-X01"}],"explanation":["의식주 모두에 영향을 줘요.","산업에도 영향을 줘요.","기후에 맞추어 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L01_challenge#10','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',4,'essay','teacher','날씨와 기후의 차이를 쓰고, 기후가 우리 생활에 주는 영향을 보기 하나를 들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C1","difficulty":4,"kind":"essay","stem":"날씨와 기후의 차이를 쓰고, 기후가 우리 생활에 주는 영향을 보기 하나를 들어 쓰세요.","answer_guide":{"answer":"예: 날씨는 짧은 시간 동안의 대기 상태라 하루 사이에도 바뀌고, 기후는 오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태이다. 기온이 높고 비가 많은 지역에서는 벼농사가 활발해 쌀로 만든 음식이 발달했다.","scoring_points":["날씨의 뜻을 썼는가","기후의 뜻을 날씨와 견주어 썼는가","기후와 생활을 잇는 보기를 들었는가"]},"explanation":["날씨는 짧은 시간이에요.","기후는 여러 해의 평균이에요.","생활과 이어 보기를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#1','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',1,'mc','auto','여름에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"여름에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?","options":[{"t":"남쪽 바다에서 오는 뜨겁고 습한 바람","correct":true},{"t":"북서쪽 육지에서 오는 차갑고 건조한 바람","mis":"SO5-1-u2-X04"},{"t":"동쪽 하늘 높은 곳에서 내려오는 서늘한 바람","mis":"SO5-1-u2-X04"},{"t":"서쪽에서 오는 메마른 바람","mis":"SO5-1-u2-X04"}],"explanation":["여름 바람은 바다에서 와요.","바다를 지나 물기가 많아요.","그래서 덥고 비가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#2','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',1,'mc','auto','겨울에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"겨울에 우리나라로 불어오는 바람으로 알맞은 것은 어느 것인가요?","options":[{"t":"북서쪽 육지에서 오는 차갑고 건조한 바람","correct":true},{"t":"남쪽 바다에서 오는 뜨겁고 습한 바람","mis":"SO5-1-u2-X04"},{"t":"동쪽 바다에서 오는 따뜻한 바람","mis":"SO5-1-u2-X04"},{"t":"남서쪽에서 오는 습한 바람","mis":"SO5-1-u2-X04"}],"explanation":["겨울 바람은 손발을 시리게 해요.","넓은 육지를 지나와요.","차갑고 건조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#3','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',1,'sa','auto','평균 기온 분포도에서 기온이 같은 곳을 이은 선을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"sa","stem":"평균 기온 분포도에서 기온이 같은 곳을 이은 선을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["등온선"],"explanation":["같을 등, 따뜻할 온이에요.","기온이 같은 곳을 이어요.","등온선이에요."],"mis":"SO5-1-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#4','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C4',1,'ox','auto','우리나라에서 강수량이 가장 많은 계절은 겨울이에요.',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"ox","stem":"우리나라에서 강수량이 가장 많은 계절은 겨울이에요.","answer":"X","reason_options":[{"t":"연 강수량의 절반 이상이 여름에 내리기 때문에","correct":true},{"t":"겨울에는 날마다 눈이 많이 쌓이기 때문에","mis":"SO5-1-u2-X07"}],"mis":"SO5-1-u2-X07","explanation":["여름에 비가 몰려요.","7월·8월 막대가 높아요.","겨울은 대체로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#5','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',2,'mc','auto','우리나라에서 대체로 남쪽으로 갈수록 기온은 어떻게 되나요?',ARRAY['SO5-1-u2-X05']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"mc","stem":"우리나라에서 대체로 남쪽으로 갈수록 기온은 어떻게 되나요?","options":[{"t":"높아진다","correct":true},{"t":"낮아진다","mis":"SO5-1-u2-X05"},{"t":"똑같다","mis":"SO5-1-u2-X05"},{"t":"계절마다 반대로 바뀐다","mis":"SO5-1-u2-X05"}],"explanation":["우리나라는 남북으로 길어요.","남쪽이 더 따뜻해요.","남쪽으로 갈수록 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#6','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',2,'mc','auto','남쪽과 북쪽의 계절별 평균 기온 자료에서 두 곳의 기온 차이가 더 큰 계절은 언제인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"mc","stem":"남쪽과 북쪽의 계절별 평균 기온 자료에서 두 곳의 기온 차이가 더 큰 계절은 언제인가요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"SO5-1-u2-X05"},{"t":"두 계절이 같다","mis":"SO5-1-u2-X05"},{"t":"자료로 알 수 없다","mis":"SO5-1-u2-X06"}],"explanation":["여름 차이는 3.5 ℃예요.","겨울 차이는 21.1 ℃예요.","겨울에 훨씬 커요."],"asset":{"type":"passage","lines":["여름 평균 기온 — 북쪽 중강진 21.4 ℃ · 남쪽 서귀포 24.9 ℃","여름 두 곳의 차이 — 3.5 ℃","겨울 평균 기온 — 북쪽 중강진 -12.8 ℃ · 남쪽 서귀포 8.3 ℃","겨울 두 곳의 차이 — 21.1 ℃"],"title":"남쪽과 북쪽의 계절별 평균 기온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#7','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C4',2,'mc','auto','강수량 자료 메모에서 연 강수량이 가장 많은 곳은 어디인가요?',ARRAY['SO5-1-u2-X07','SO5-1-u2-X06']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C4","difficulty":2,"kind":"mc","stem":"강수량 자료 메모에서 연 강수량이 가장 많은 곳은 어디인가요?","options":[{"t":"제주","correct":true},{"t":"중강진","mis":"SO5-1-u2-X07"},{"t":"서울","mis":"SO5-1-u2-X06"},{"t":"세 곳이 같다","mis":"SO5-1-u2-X06"}],"explanation":["세 수를 견주어요.","제주가 가장 커요.","남쪽으로 갈수록 많아요."],"asset":{"type":"passage","lines":["연 강수량 — 북쪽 중강진 약 638 mm · 서울 약 1,418 mm · 제주 약 1,502 mm","서울의 달별 강수량 — 7월과 8월 막대가 가장 높다.","서울의 달별 강수량 — 12월·1월·2월 막대는 아주 낮다.","분포도 — 파란색이 진할수록 강수량이 많다."],"title":"강수량 자료 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#8','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C3',2,'mc','auto','일기 예보는 어느 계절의 예보일까요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X06']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"mc","stem":"일기 예보는 어느 계절의 예보일까요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"SO5-1-u2-X04"},{"t":"봄","mis":"SO5-1-u2-X04"},{"t":"계절을 알 수 없다","mis":"SO5-1-u2-X06"}],"explanation":["북서쪽에서 찬 바람이 분대요.","기온이 크게 떨어진대요.","겨울철 예보예요."],"asset":{"type":"passage","lines":["비가 그친 뒤 오늘 밤부터 기온이 크게 떨어지겠습니다.","북서쪽에서 찬 바람이 불어오겠습니다.","내일 아침은 오늘보다 5~10 ℃ 낮겠습니다."],"title":"어느 날의 일기 예보(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#9','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C4',2,'ox','auto','연 강수량 분포도에서 파란색이 진할수록 강수량이 많아요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C4","difficulty":2,"kind":"ox","stem":"연 강수량 분포도에서 파란색이 진할수록 강수량이 많아요.","answer":"O","reason_options":[{"t":"분포도는 강수량이 많은 곳을 더 진한 색으로 나타내기 때문에","correct":true},{"t":"진한 파란색은 바다를 나타내기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["분포도에는 범례가 있어요.","진할수록 많아요.","남쪽이 더 진해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_basic#10','soc',5,1,'u2','L02','g5_1_soc_u2_L02_basic','lesson_basic','SO5-1-u2-C2',3,'mc','auto','같은 2월에 인천에는 눈이 쌓였는데 제주에서는 밭에서 무를 거두었어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X07']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"mc","stem":"같은 2월에 인천에는 눈이 쌓였는데 제주에서는 밭에서 무를 거두었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"제주가 더 남쪽에 있어 겨울 평균 기온이 높기 때문에","correct":true},{"t":"인천이 제주보다 남쪽에 있기 때문에","mis":"SO5-1-u2-X05"},{"t":"제주에는 겨울이 없기 때문에","mis":"SO5-1-u2-X05"},{"t":"두 곳의 강수량이 같기 때문에","mis":"SO5-1-u2-X07"}],"explanation":["제주는 남쪽에 있어요.","겨울에도 따뜻해요.","그래서 밭농사를 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#1','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C4',2,'match','auto','계절과 그 계절의 기후 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C4","difficulty":2,"kind":"match","stem":"계절과 그 계절의 기후 특징을 알맞게 이으세요.","pairs":[{"l":"봄","r":"온화하고 건조하다"},{"l":"여름","r":"덥고 비가 자주 온다"},{"l":"가을","r":"맑고 건조하다"},{"l":"겨울","r":"춥고 건조하며 눈이 온다"}],"mis":"SO5-1-u2-X07","explanation":["봄과 가을은 건조해요.","여름은 비가 많아요.","겨울은 춥고 눈이 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#2','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',2,'sa','auto','여름 바람은 바다에서, 겨울 바람은 어디에서 불어오나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":2,"kind":"sa","stem":"여름 바람은 바다에서, 겨울 바람은 어디에서 불어오나요? 두 글자로 쓰세요.","answer":["육지"],"explanation":["겨울 바람은 북서쪽에서 와요.","넓은 땅을 지나와요.","육지예요."],"mis":"SO5-1-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#3','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',3,'mc','auto','여름과 겨울에 남북의 기온 차이가 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X04']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"mc","stem":"여름과 겨울에 남북의 기온 차이가 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여름에는 남북 모두 덥지만 겨울에는 북쪽이 크게 추워지기 때문에","correct":true},{"t":"여름에는 북쪽만 크게 더워지기 때문에","mis":"SO5-1-u2-X05"},{"t":"겨울에는 남쪽이 북쪽보다 더 추워지기 때문에","mis":"SO5-1-u2-X05"},{"t":"두 계절의 바람이 똑같기 때문에","mis":"SO5-1-u2-X04"}],"explanation":["여름 차이는 작아요.","겨울 차이는 커요.","북쪽이 크게 추워져서예요."],"asset":{"type":"passage","lines":["여름 평균 기온 — 북쪽 중강진 21.4 ℃ · 남쪽 서귀포 24.9 ℃","여름 두 곳의 차이 — 3.5 ℃","겨울 평균 기온 — 북쪽 중강진 -12.8 ℃ · 남쪽 서귀포 8.3 ℃","겨울 두 곳의 차이 — 21.1 ℃"],"title":"남쪽과 북쪽의 계절별 평균 기온"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#4','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',3,'mc','auto','바람이 계절마다 다른 성질을 띠는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"mc","stem":"바람이 계절마다 다른 성질을 띠는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바람이 지나온 곳이 바다인지 육지인지가 다르기 때문에","correct":true},{"t":"바람은 하늘 높은 곳에서만 생기기 때문에","mis":"SO5-1-u2-X04"},{"t":"바람은 계절과 상관없이 늘 같기 때문에","mis":"SO5-1-u2-X04"},{"t":"사람들이 바람의 방향을 정하기 때문에","mis":"SO5-1-u2-X04"}],"explanation":["바다를 지나면 습해요.","육지를 지나면 건조해요.","지나온 곳이 성질을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#5','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C4',3,'mc','auto','강수량 자료 메모를 보고 알 수 있는 것을 가장 바르게 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"mc","stem":"강수량 자료 메모를 보고 알 수 있는 것을 가장 바르게 묶은 것은 어느 것인가요?","options":[{"t":"남쪽으로 갈수록 연 강수량이 많고, 비는 여름에 몰린다","correct":true},{"t":"북쪽으로 갈수록 연 강수량이 많고, 비는 겨울에 몰린다","mis":"SO5-1-u2-X07"},{"t":"어디나 강수량이 같고, 비는 봄에 몰린다","mis":"SO5-1-u2-X07"},{"t":"남쪽으로 갈수록 적고, 달마다 비가 고르게 온다","mis":"SO5-1-u2-X07"}],"explanation":["중강진·서울·제주를 견줘요.","남쪽으로 갈수록 많아요.","7·8월 막대가 높아요."],"asset":{"type":"passage","lines":["연 강수량 — 북쪽 중강진 약 638 mm · 서울 약 1,418 mm · 제주 약 1,502 mm","서울의 달별 강수량 — 7월과 8월 막대가 가장 높다.","서울의 달별 강수량 — 12월·1월·2월 막대는 아주 낮다.","분포도 — 파란색이 진할수록 강수량이 많다."],"title":"강수량 자료 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#6','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C2',3,'ox','auto','눈꽃 축제는 불꽃 축제보다 기후의 영향을 더 많이 받는 축제예요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C2","difficulty":3,"kind":"ox","stem":"눈꽃 축제는 불꽃 축제보다 기후의 영향을 더 많이 받는 축제예요.","answer":"O","reason_options":[{"t":"눈이 많이 내리는 겨울에 해마다 열기 알맞기 때문에","correct":true},{"t":"불꽃 축제는 비가 오면 못 여니 기후의 영향이 가장 크기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["눈꽃 축제는 겨울 기후에 맞춰 열어요.","불꽃 축제가 비로 미뤄지는 건 날씨 때문이에요.","그래서 눈꽃 축제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#7','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',3,'error','auto','등온선을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X06','SO5-1-u2-X05']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"error","stem":"등온선을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「등온선은 비가 같은 만큼 내린 곳을 이은 선이야.」","correct":true,"mis_target":"SO5-1-u2-X06"},{"t":"채원 — 「선 끝에 적힌 숫자로 그곳 기온을 알 수 있어.」","mis":"SO5-1-u2-X06"},{"t":"지후 — 「등온선을 보면 남쪽이 더 따뜻한 걸 알 수 있어.」","mis":"SO5-1-u2-X05"}],"explanation":["등온선은 기온이 같은 곳을 이어요.","강수량을 잇는 선이 아니에요.","은우가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#8','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C4',4,'mc','auto','여름에 비가 많이 내리는 까닭을 바람과 이어 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X05']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C4","difficulty":4,"kind":"mc","stem":"여름에 비가 많이 내리는 까닭을 바람과 이어 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"남쪽 바다를 지나온 바람이 물기를 많이 머금고 불어오기 때문에","correct":true},{"t":"북서쪽 육지를 지나온 바람이 물기를 가져오기 때문에","mis":"SO5-1-u2-X04"},{"t":"여름에는 바람이 전혀 불지 않기 때문에","mis":"SO5-1-u2-X04"},{"t":"여름에는 기온이 낮아 구름이 잘 생기기 때문에","mis":"SO5-1-u2-X05"}],"explanation":["여름 바람은 바다에서 와요.","바다를 지나 습해요.","그래서 비가 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#9','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',4,'mc','auto','「계절 → 바람이 불어오는 곳 → 바람의 성질 → 기온과 강수」 차례로 겨울을 바르게 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X07']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C3","difficulty":4,"kind":"mc","stem":"「계절 → 바람이 불어오는 곳 → 바람의 성질 → 기온과 강수」 차례로 겨울을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"겨울 → 북서쪽 육지 → 차갑고 건조함 → 기온이 낮고 강수가 적음","correct":true},{"t":"겨울 → 남쪽 바다 → 뜨겁고 습함 → 기온이 높고 강수가 많음","mis":"SO5-1-u2-X04"},{"t":"겨울 → 북서쪽 육지 → 뜨겁고 습함 → 기온이 높고 강수가 적음","mis":"SO5-1-u2-X04"},{"t":"겨울 → 동쪽 바다 → 차갑고 습함 → 기온이 낮고 강수가 많음","mis":"SO5-1-u2-X07"}],"explanation":["겨울 바람은 북서쪽 육지에서 와요.","차갑고 건조해요.","그래서 춥고 강수가 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L02_challenge#10','soc',5,1,'u2','L02','g5_1_soc_u2_L02_challenge','lesson_challenge','SO5-1-u2-C3',4,'essay','teacher','여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 바람 때문에 두 계절의 기온과 강수가 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C3","difficulty":4,"kind":"essay","stem":"여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 바람 때문에 두 계절의 기온과 강수가 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 여름에는 남쪽 바다에서 뜨겁고 습한 바람이 불어와 기온이 높고 비가 많이 내린다. 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어와 기온이 낮고 강수가 적다.","scoring_points":["여름 바람의 방향과 성질을 썼는가","겨울 바람의 방향과 성질을 썼는가","바람과 기온·강수를 이어 썼는가"]},"explanation":["여름 — 남쪽 바다예요.","겨울 — 북서쪽 육지예요.","바람이 기온과 강수를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#1','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',1,'mc','auto','자연재해의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X08','SO5-1-u2-X03','SO5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"자연재해의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"피할 수 없는 자연 현상으로 사람들이 입는 생명이나 재산상의 피해","correct":true},{"t":"사람이 일부러 일으킨 사고","mis":"SO5-1-u2-X08"},{"t":"계절마다 달라지는 옷차림","mis":"SO5-1-u2-X03"},{"t":"여러 해 동안 나타나는 평균적인 날씨","mis":"SO5-1-u2-X01"}],"explanation":["자연 현상에서 시작해요.","사람이 피해를 입어요.","그래서 자연재해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#2','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',1,'mc','auto','봄에 우리나라에서 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"봄에 우리나라에서 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?","options":[{"t":"황사와 가뭄","correct":true},{"t":"폭설과 한파","mis":"SO5-1-u2-X09"},{"t":"폭염과 호우","mis":"SO5-1-u2-X09"},{"t":"태풍과 홍수","mis":"SO5-1-u2-X09"}],"explanation":["모래 먼지가 날아오는 때예요.","비가 오래 오지 않기도 해요.","봄은 황사와 가뭄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#3','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',1,'sa','auto','많은 비와 강한 바람을 몰고 와 여름과 가을 사이에 우리나라에 영향을 주는 자연재해를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"sa","stem":"많은 비와 강한 바람을 몰고 와 여름과 가을 사이에 우리나라에 영향을 주는 자연재해를 쓰세요.","answer":["태풍"],"explanation":["비와 바람이 함께 몰아쳐요.","남서쪽에서 북동쪽으로 지나가요.","태풍이에요."],"mis":"SO5-1-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#4','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C6',1,'ox','auto','기상 특보는 자연재해를 주의시키려고 미리 알려 주는 정보예요.',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C6","difficulty":1,"kind":"ox","stem":"기상 특보는 자연재해를 주의시키려고 미리 알려 주는 정보예요.","answer":"O","reason_options":[{"t":"주의보·경보로 피해가 생기기 전에 알려 주기 때문에","correct":true},{"t":"자연재해가 끝난 뒤 피해를 세어 알려 주는 것이기 때문에","mis":"SO5-1-u2-X10"}],"mis":"SO5-1-u2-X10","explanation":["「○○ 주의보」처럼 알려요.","더 큰 피해가 걱정되면 경보예요.","미리 알려 주는 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#5','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'match','auto','재해 소식 카드를 보고 카드와 자연재해를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"match","stem":"재해 소식 카드를 보고 카드와 자연재해를 알맞게 이으세요.","pairs":[{"l":"㉠","r":"황사"},{"l":"㉡","r":"가뭄"},{"l":"㉣","r":"홍수"},{"l":"㉥","r":"한파"}],"mis":"SO5-1-u2-X09","explanation":["㉠은 모래 먼지, ㉡은 비가 오지 않음이에요.","㉣은 하천이 넘쳤어요.","㉥은 갑자기 추워졌어요."],"asset":{"type":"passage","lines":["㉠ 사막의 모래 먼지가 바람을 타고 날아와 하늘이 뿌옇다.","㉡ 오랫동안 비가 오지 않아 논밭이 갈라졌다.","㉢ 일상생활이 힘들 만큼 무더운 날이 이어진다.","㉣ 많은 비가 내려 하천이 넘치고 도로가 잠겼다.","㉤ 강한 바람과 많은 비가 남서쪽에서 북동쪽으로 지나갔다.","㉥ 기온이 갑자기 내려가 수도관이 얼었다."],"title":"재해 소식 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#6','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'mc','auto','재해 소식 카드 ㉤은 어떤 자연재해인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"mc","stem":"재해 소식 카드 ㉤은 어떤 자연재해인가요?","options":[{"t":"태풍","correct":true},{"t":"폭설","mis":"SO5-1-u2-X09"},{"t":"황사","mis":"SO5-1-u2-X09"},{"t":"폭염","mis":"SO5-1-u2-X09"}],"explanation":["강한 바람과 많은 비예요.","남서쪽에서 북동쪽으로 지나갔어요.","태풍이에요."],"asset":{"type":"passage","lines":["㉠ 사막의 모래 먼지가 바람을 타고 날아와 하늘이 뿌옇다.","㉡ 오랫동안 비가 오지 않아 논밭이 갈라졌다.","㉢ 일상생활이 힘들 만큼 무더운 날이 이어진다.","㉣ 많은 비가 내려 하천이 넘치고 도로가 잠겼다.","㉤ 강한 바람과 많은 비가 남서쪽에서 북동쪽으로 지나갔다.","㉥ 기온이 갑자기 내려가 수도관이 얼었다."],"title":"재해 소식 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#7','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'mc','auto','겨울에 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"mc","stem":"겨울에 자주 발생하는 자연재해를 묶은 것은 어느 것인가요?","options":[{"t":"폭설과 한파","correct":true},{"t":"황사와 가뭄","mis":"SO5-1-u2-X09"},{"t":"폭염과 호우","mis":"SO5-1-u2-X09"},{"t":"홍수와 태풍","mis":"SO5-1-u2-X09"}],"explanation":["짧은 시간에 눈이 많이 내려요.","기온이 갑자기 내려가요.","폭설과 한파예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#8','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C6',2,'mc','auto','태풍 주의보가 내려졌을 때 알맞은 행동은 어느 것인가요?',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"mc","stem":"태풍 주의보가 내려졌을 때 알맞은 행동은 어느 것인가요?","options":[{"t":"외출을 삼가고 바람에 넘어지기 쉬운 물건을 미리 정리한다","correct":true},{"t":"바닷가에 나가 큰 파도를 구경한다","mis":"SO5-1-u2-X10"},{"t":"창문을 활짝 열어 바람이 지나가게 한다","mis":"SO5-1-u2-X10"},{"t":"특보는 어른들의 일이니 평소처럼 밖에서 논다","mis":"SO5-1-u2-X10"}],"explanation":["강한 바람은 위험해요.","밖에 나가지 않아요.","날아갈 물건을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#9','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',2,'ox','auto','비가 많이 내리는 현상을 호우, 비가 많이 내려 물이 흘러넘치는 현상을 홍수라고 해요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C5","difficulty":2,"kind":"ox","stem":"비가 많이 내리는 현상을 호우, 비가 많이 내려 물이 흘러넘치는 현상을 홍수라고 해요.","answer":"O","reason_options":[{"t":"호우는 비가 많이 오는 것이고 홍수는 그 물이 넘치는 것이기 때문에","correct":true},{"t":"호우와 홍수는 겨울에 눈이 많이 내리는 현상이기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["호우는 많은 비예요.","홍수는 넘치는 물이에요.","둘 다 여름에 잦아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_basic#10','soc',5,1,'u2','L03','g5_1_soc_u2_L03_basic','lesson_basic','SO5-1-u2-C5',3,'mc','auto','우리나라에서 계절마다 다른 자연재해가 자주 발생하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X08','SO5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"mc","stem":"우리나라에서 계절마다 다른 자연재해가 자주 발생하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"계절마다 바람·기온·강수의 정도가 달라 기후 특성이 다르기 때문에","correct":true},{"t":"지역마다 사는 사람 수가 다르기 때문에","mis":"SO5-1-u2-X08"},{"t":"자연재해는 아무 때나 똑같이 일어나기 때문에","mis":"SO5-1-u2-X09"},{"t":"여름에만 자연재해가 일어나기 때문에","mis":"SO5-1-u2-X09"}],"explanation":["지난 차시를 떠올려요.","계절마다 기후가 달라요.","그래서 재해도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#1','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',2,'match','auto','자연재해와 그에 대비하는 시설을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"match","stem":"자연재해와 그에 대비하는 시설을 알맞게 이으세요.","pairs":[{"l":"가뭄","r":"저수지와 댐"},{"l":"호우·홍수","r":"제방"},{"l":"폭염","r":"그늘막과 무더위 쉼터"}],"mis":"SO5-1-u2-X10","explanation":["가뭄에는 물을 모아 둬요.","홍수에는 둑을 쌓아요.","폭염에는 더위를 피할 곳을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#2','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',2,'sa','auto','자연재해가 예상될 때 휴대 전화로 보내 위험을 알려 주는 것은 무엇인가요? (긴급 재난 □□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"sa","stem":"자연재해가 예상될 때 휴대 전화로 보내 위험을 알려 주는 것은 무엇인가요? (긴급 재난 □□)","answer":["문자"],"explanation":["주머니에서 울려요.","위험을 미리 알려요.","긴급 재난 문자예요."],"mis":"SO5-1-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#3','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',3,'mc','auto','신문 기사에서 기상청이 대비하라고 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09','SO5-1-u2-X08']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"mc","stem":"신문 기사에서 기상청이 대비하라고 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"태풍이 많은 비와 강한 바람으로 주택·도로·농작물에 피해를 줄 수 있기 때문에","correct":true},{"t":"태풍이 오면 기온이 갑자기 크게 떨어지기 때문에","mis":"SO5-1-u2-X09"},{"t":"태풍은 오랫동안 비가 오지 않게 하기 때문에","mis":"SO5-1-u2-X09"},{"t":"태풍은 사람이 일으키는 사고이기 때문에","mis":"SO5-1-u2-X08"}],"explanation":["태풍은 비와 바람을 몰고 와요.","집과 길이 잠기기도 해요.","그래서 미리 대비해요."],"asset":{"type":"passage","lines":["오늘 오후 남해안으로 태풍이 올라올 것으로 보인다.","전국 곳곳에 태풍 주의보와 경보가 내려졌다.","기상청은 인명과 재산 피해가 없도록 대비해 달라고 했다."],"title":"어느 해 여름의 신문 기사(예시)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#4','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',3,'mc','auto','사람이 하는 일이 자연재해의 피해를 더 키우기도 한다는 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X11']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"mc","stem":"사람이 하는 일이 자연재해의 피해를 더 키우기도 한다는 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"숲을 농경지로 일구거나 물길을 바꾸면 가뭄이나 홍수 피해가 커지기도 한다","correct":true},{"t":"사람이 하는 일은 자연재해와 아무 관계가 없다","mis":"SO5-1-u2-X11"},{"t":"나무를 심으면 가뭄이 더 심해진다","mis":"SO5-1-u2-X11"},{"t":"도로를 만들면 자연재해가 사라진다","mis":"SO5-1-u2-X11"}],"explanation":["숲은 물을 머금어요.","물길을 바꾸면 흐름이 달라져요.","피해가 커지기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#5','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C5',3,'ox','auto','비가 많이 내렸지만 아무도 다치지 않고 재산 피해도 없었다면 그 비 자체를 자연재해라고 부르기는 어려워요.',ARRAY['SO5-1-u2-X08']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"ox","stem":"비가 많이 내렸지만 아무도 다치지 않고 재산 피해도 없었다면 그 비 자체를 자연재해라고 부르기는 어려워요.","answer":"O","reason_options":[{"t":"자연재해는 자연 현상으로 사람이 피해를 입었을 때를 말하기 때문에","correct":true},{"t":"비가 내리기만 하면 언제나 자연재해이기 때문에","mis":"SO5-1-u2-X08"}],"mis":"SO5-1-u2-X08","explanation":["자연 현상만으로는 재해가 아니에요.","사람의 피해가 있어야 해요.","그래서 부르기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#6','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',3,'error','auto','자연재해에 대비하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"error","stem":"자연재해에 대비하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서율 — 「국민 행동 요령은 어른들이 알면 되니 나는 몰라도 돼.」","correct":true,"mis_target":"SO5-1-u2-X10"},{"t":"지환 — 「기상 특보가 나오면 방송이나 인터넷으로 확인해.」","mis":"SO5-1-u2-X10"},{"t":"예린 — 「우리 지역의 대비 시설을 조사해 친구들과 나눠 볼래.」","mis":"SO5-1-u2-X10"}],"explanation":["국민 행동 요령은 국민 누구나의 몫이에요.","어린이도 알아야 해요.","나를 지키는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#7','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C5',3,'mc','auto','재해 소식 카드 가운데 여름에 자주 발생하는 자연재해만 고른 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"mc","stem":"재해 소식 카드 가운데 여름에 자주 발생하는 자연재해만 고른 것은 어느 것인가요?","options":[{"t":"㉢과 ㉣","correct":true},{"t":"㉠과 ㉡","mis":"SO5-1-u2-X09"},{"t":"㉥과 ㉠","mis":"SO5-1-u2-X09"},{"t":"㉡과 ㉥","mis":"SO5-1-u2-X09"}],"explanation":["㉢은 폭염이에요.","㉣은 홍수예요.","둘 다 여름에 잦아요."],"asset":{"type":"passage","lines":["㉠ 사막의 모래 먼지가 바람을 타고 날아와 하늘이 뿌옇다.","㉡ 오랫동안 비가 오지 않아 논밭이 갈라졌다.","㉢ 일상생활이 힘들 만큼 무더운 날이 이어진다.","㉣ 많은 비가 내려 하천이 넘치고 도로가 잠겼다.","㉤ 강한 바람과 많은 비가 남서쪽에서 북동쪽으로 지나갔다.","㉥ 기온이 갑자기 내려가 수도관이 얼었다."],"title":"재해 소식 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#8','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',4,'mc','auto','자연재해를 대하는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X10','SO5-1-u2-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"mc","stem":"자연재해를 대하는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연재해는 막을 수 없지만 시설·훈련·특보와 국민 행동 요령으로 피해를 줄일 수 있다","correct":true},{"t":"자연재해는 막을 수 없으니 아무 준비도 하지 않아도 된다","mis":"SO5-1-u2-X10"},{"t":"시설만 지어 두면 사람은 아무것도 하지 않아도 된다","mis":"SO5-1-u2-X10"},{"t":"자연재해는 사람이 일으키니 그 사람만 조심하면 된다","mis":"SO5-1-u2-X08"}],"explanation":["재해는 피할 수 없어요.","피해는 줄일 수 있어요.","시설·훈련·특보·행동 요령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#9','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',4,'mc','auto','날씨를 예측해 알려 주는 예보 분석관이 되려는 사람에게 가장 필요한 자세는 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X25','SO5-1-u2-X10']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"mc","stem":"날씨를 예측해 알려 주는 예보 분석관이 되려는 사람에게 가장 필요한 자세는 어느 것인가요?","options":[{"t":"하늘의 기상 현상에 관심을 두고 새로운 기술과 지식을 꾸준히 배우는 자세","correct":true},{"t":"하루 날씨만 보고 그 지역 기후를 정하는 자세","mis":"SO5-1-u2-X01"},{"t":"지형 이름을 빠짐없이 외우는 자세","mis":"SO5-1-u2-X25"},{"t":"특보는 미리 알리지 않고 지나간 뒤에 알리는 자세","mis":"SO5-1-u2-X10"}],"explanation":["기상학 지식이 필요해요.","하늘에 관심을 둬요.","계속 배우려는 자세가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L03_challenge#10','soc',5,1,'u2','L03','g5_1_soc_u2_L03_challenge','lesson_challenge','SO5-1-u2-C6',4,'essay','teacher','태풍 주의보가 내려졌다는 소식을 들었어요. 태풍이 어떤 피해를 줄 수 있는지 쓰고, 내가 실천할 국민 행동 요령 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"essay","stem":"태풍 주의보가 내려졌다는 소식을 들었어요. 태풍이 어떤 피해를 줄 수 있는지 쓰고, 내가 실천할 국민 행동 요령 두 가지를 쓰세요.","answer_guide":{"answer":"예: 태풍은 많은 비와 강한 바람을 몰고 와 도로와 주택이 물에 잠기고 농작물이 쓰러지거나 나무가 부러질 수 있다. 나는 외출을 삼가고 집에 머물며, 베란다나 마당에 바람에 날아가기 쉬운 물건을 미리 안으로 들여놓겠다.","scoring_points":["태풍의 피해를 썼는가","알맞은 행동 요령을 두 가지 썼는가","내가 실천할 일로 썼는가"]},"explanation":["비와 바람의 피해예요.","외출을 삼가요.","날아갈 물건을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#1','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',1,'mc','auto','지구의 기온이 높아지는 현상을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X09','SO5-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"지구의 기온이 높아지는 현상을 무엇이라고 하나요?","options":[{"t":"지구 온난화","correct":true},{"t":"지구 한랭화","mis":"SO5-1-u2-X12"},{"t":"황사","mis":"SO5-1-u2-X09"},{"t":"인구 이동","mis":"SO5-1-u2-X16"}],"explanation":["기온이 높아져요.","따뜻할 온, 될 화예요.","지구 온난화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#2','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',1,'mc','auto','지구 온난화를 심하게 만드는 인간 활동은 어느 것인가요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"지구 온난화를 심하게 만드는 인간 활동은 어느 것인가요?","options":[{"t":"숲을 파괴하고 석유와 석탄을 지나치게 쓰는 일","correct":true},{"t":"나무를 심고 숲을 가꾸는 일","mis":"SO5-1-u2-X12"},{"t":"대중교통을 이용하는 일","mis":"SO5-1-u2-X12"},{"t":"빈 교실의 전등을 끄는 일","mis":"SO5-1-u2-X12"}],"explanation":["기온을 높이는 일을 찾아요.","숲이 줄고 연료를 많이 써요.","나머지는 막는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#3','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',1,'sa','auto','기후변화를 막으려는 모든 노력을 무엇이라고 하나요? (기후 □□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C8","difficulty":1,"kind":"sa","stem":"기후변화를 막으려는 모든 노력을 무엇이라고 하나요? (기후 □□)","answer":["행동"],"explanation":["막으려는 노력이에요.","누구나 할 수 있어요.","기후 행동이에요."],"mis":"SO5-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#4','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',1,'ox','auto','우리나라의 연평균 기온은 오랜 기간에 걸쳐 꾸준히 내려가고 있어요.',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"ox","stem":"우리나라의 연평균 기온은 오랜 기간에 걸쳐 꾸준히 내려가고 있어요.","answer":"X","reason_options":[{"t":"지구 온난화로 연평균 기온이 꾸준히 올라가고 있기 때문에","correct":true},{"t":"기후변화가 일어나면 기온은 언제나 내려가기 때문에","mis":"SO5-1-u2-X12"}],"mis":"SO5-1-u2-X12","explanation":["기온이 올라가고 있어요.","약 백 년 동안 높아졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#5','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'mc','auto','우리나라 기후의 변화 자료에서 계절 길이는 어떻게 달라졌나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"mc","stem":"우리나라 기후의 변화 자료에서 계절 길이는 어떻게 달라졌나요?","options":[{"t":"여름이 길어지고 겨울이 짧아졌다","correct":true},{"t":"여름이 짧아지고 겨울이 길어졌다","mis":"SO5-1-u2-X12"},{"t":"봄과 가을만 크게 길어졌다","mis":"SO5-1-u2-X12"},{"t":"네 계절의 길이가 그대로이다","mis":"SO5-1-u2-X12"}],"explanation":["여름은 98일에서 118일이에요.","겨울은 109일에서 87일이에요.","여름이 늘고 겨울이 줄었어요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#6','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'mc','auto','우리나라 기후의 변화 자료에서 연평균 기온은 어떻게 달라졌나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"mc","stem":"우리나라 기후의 변화 자료에서 연평균 기온은 어떻게 달라졌나요?","options":[{"t":"12.0 ℃에서 13.9 ℃로 올라갔다","correct":true},{"t":"13.9 ℃에서 12.0 ℃로 내려갔다","mis":"SO5-1-u2-X12"},{"t":"거의 달라지지 않았다","mis":"SO5-1-u2-X12"},{"t":"여름에만 올라갔다","mis":"SO5-1-u2-X12"}],"explanation":["두 수를 견주어요.","13.9가 더 커요.","기온이 올라갔어요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#7','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',2,'mc','auto','「친환경 재료로 제품을 만들고 생산 과정의 오염 물질을 줄인다」는 누구의 기후 행동인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"「친환경 재료로 제품을 만들고 생산 과정의 오염 물질을 줄인다」는 누구의 기후 행동인가요?","options":[{"t":"기업","correct":true},{"t":"세계 여러 나라","mis":"SO5-1-u2-X14"},{"t":"정부와 국회","mis":"SO5-1-u2-X14"},{"t":"학교 학생","mis":"SO5-1-u2-X14"}],"explanation":["제품을 만드는 곳이에요.","생산하는 주체예요.","기업의 기후 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#8','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',2,'mc','auto','학교에서 할 수 있는 기후 행동으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"학교에서 할 수 있는 기후 행동으로 알맞은 것은 어느 것인가요?","options":[{"t":"급식을 남기지 않고 빈 교실과 화장실의 전등을 끈다","correct":true},{"t":"빈 교실의 냉방기를 켜 둔다","mis":"SO5-1-u2-X14"},{"t":"가까운 거리도 자가용을 타고 온다","mis":"SO5-1-u2-X14"},{"t":"일회용 컵을 하루에 여러 개 쓴다","mis":"SO5-1-u2-X14"}],"explanation":["음식과 에너지를 아껴요.","전등을 꺼요.","학교에서도 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#9','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'ox','auto','기후변화의 영향으로 자연재해를 예측하기 어려워지고 그 강도도 세지고 있어요.',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"ox","stem":"기후변화의 영향으로 자연재해를 예측하기 어려워지고 그 강도도 세지고 있어요.","answer":"O","reason_options":[{"t":"기후변화로 자연재해의 발생 횟수와 강도가 모두 늘고 있기 때문에","correct":true},{"t":"자연재해는 기후변화와 아무 관계가 없기 때문에","mis":"SO5-1-u2-X13"}],"mis":"SO5-1-u2-X13","explanation":["재해가 더 잦아요.","더 세졌어요.","예측도 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_basic#10','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',3,'mc','auto','기후 행동을 실천하고 돌아봤더니 잘 안 된 날이 있었어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"기후 행동을 실천하고 돌아봤더니 잘 안 된 날이 있었어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"어려웠던 까닭을 생각해 보고 다음에도 이어서 실천한다","correct":true},{"t":"잘 안 된 행동은 목록에서 모두 지운다","mis":"SO5-1-u2-X15"},{"t":"나 하나 해도 달라지지 않으니 그만둔다","mis":"SO5-1-u2-X14"},{"t":"어른이 될 때까지 기후 행동을 미룬다","mis":"SO5-1-u2-X14"}],"explanation":["실천이 어려운 날도 있어요.","까닭을 돌아봐요.","다시 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#1','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',2,'match','auto','기후 행동 카드를 보고 카드와 기후 행동을 하는 주체를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"match","stem":"기후 행동 카드를 보고 카드와 기후 행동을 하는 주체를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"세계 여러 나라"},{"l":"㉯","r":"정부와 국회"},{"l":"㉰","r":"기업"},{"l":"㉱","r":"개인"}],"mis":"SO5-1-u2-X14","explanation":["㉮는 나라들의 약속이에요.","㉯는 법과 제도, ㉰는 제품이에요.","㉱는 내가 매일 할 수 있어요."],"asset":{"type":"passage","lines":["㉮ 기온이 크게 오르지 않도록 함께 약속을 맺었다.","㉯ 기후변화를 막는 법과 제도를 만들었다.","㉰ 친환경 재료로 제품을 만들고 오염 물질을 줄였다.","㉱ 가까운 길은 걷고 휴지 대신 손수건을 쓴다."],"title":"기후 행동 카드 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#2','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',2,'sa','auto','2015년 세계 여러 나라가 기온 상승을 막기로 약속하며 채택한 협정의 이름을 쓰세요. (□□ 협정)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"sa","stem":"2015년 세계 여러 나라가 기온 상승을 막기로 약속하며 채택한 협정의 이름을 쓰세요. (□□ 협정)","answer":["파리"],"explanation":["여러 나라가 함께 맺었어요.","기온 상승을 막기로 했어요.","파리 협정이에요."],"mis":"SO5-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#3','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'mc','auto','어느 해에 역대 가장 긴 가뭄과 가장 많은 장맛비, 이상 고온과 한파가 한 해에 모두 나타났어요. 가장 알맞은 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"어느 해에 역대 가장 긴 가뭄과 가장 많은 장맛비, 이상 고온과 한파가 한 해에 모두 나타났어요. 가장 알맞은 까닭은 어느 것인가요?","options":[{"t":"기후변화로 자연재해가 더 잦아지고 세졌기 때문에","correct":true},{"t":"그해에만 우연히 생긴 일이기 때문에","mis":"SO5-1-u2-X13"},{"t":"우리나라에 계절이 넷이기 때문에","mis":"SO5-1-u2-X13"},{"t":"자연재해는 원래 미리 다 알 수 있기 때문에","mis":"SO5-1-u2-X13"}],"explanation":["「역대」라는 말이 잦아요.","재해가 더 자주, 더 세게 와요.","기후변화의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#4','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'mc','auto','기후변화가 일어나는 과정을 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"기후변화가 일어나는 과정을 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"인간 활동 → 지구 온난화 → 기후변화","correct":true},{"t":"기후변화 → 인간 활동 → 지구 온난화","mis":"SO5-1-u2-X12"},{"t":"지구 온난화 → 인간 활동 → 기후변화","mis":"SO5-1-u2-X12"},{"t":"기후 행동 → 지구 온난화 → 인간 활동","mis":"SO5-1-u2-X14"}],"explanation":["사람의 활동이 먼저예요.","그래서 지구가 더워져요.","그 결과 기후가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#5','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',3,'mc','auto','「나의 기후 행동 수첩」에 적기 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"「나의 기후 행동 수첩」에 적기 가장 알맞은 것은 어느 것인가요?","options":[{"t":"휴지 대신 손수건 쓰기","correct":true},{"t":"기후변화를 막는 법 만들기","mis":"SO5-1-u2-X15"},{"t":"생산 과정의 오염 물질 줄이는 기술 개발하기","mis":"SO5-1-u2-X15"},{"t":"에어컨을 세게 틀어 시원하게 지내기","mis":"SO5-1-u2-X14"}],"explanation":["수첩에는 내가 매일 할 일을 적어요.","법은 국회, 기술은 기업의 일이에요.","손수건은 내가 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#6','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',3,'ox','auto','기후 행동 수첩은 행동을 고르고 적는 데서 끝내고, 실천한 결과는 돌아보지 않아도 돼요.',ARRAY['SO5-1-u2-X15']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"ox","stem":"기후 행동 수첩은 행동을 고르고 적는 데서 끝내고, 실천한 결과는 돌아보지 않아도 돼요.","answer":"X","reason_options":[{"t":"실천한 뒤 돌아보는 일까지 이어져야 생활 속에서 계속할 수 있기 때문에","correct":true},{"t":"기후 행동은 적어 두기만 하면 저절로 이루어지기 때문에","mis":"SO5-1-u2-X15"}],"mis":"SO5-1-u2-X15","explanation":["고르고 실천하고 돌아봐요.","돌아보기까지가 기후 행동이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#7','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'error','auto','기후변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X13']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"error","stem":"기후변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「기후변화로 우리나라는 겨울이 길어지고 여름이 짧아지고 있어.」","correct":true,"mis_target":"SO5-1-u2-X12"},{"t":"수안 — 「연평균 기온이 꾸준히 올라가고 있어.」","mis":"SO5-1-u2-X12"},{"t":"도경 — 「폭염과 극한 호우가 더 심해지고 있어.」","mis":"SO5-1-u2-X13"}],"explanation":["여름이 길어지고 있어요.","겨울은 짧아지고 있어요.","하준의 말이 거꾸로예요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#8','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',4,'mc','auto','기후 행동을 가장 바르게 이해한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X14','SO5-1-u2-X15']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C8","difficulty":4,"kind":"mc","stem":"기후 행동을 가장 바르게 이해한 것은 어느 것인가요?","options":[{"t":"세계·정부와 국회·기업·개인이 저마다 할 수 있는 일을 하므로 나도 오늘부터 참여할 수 있다","correct":true},{"t":"기후 행동은 나라가 하는 일이라 개인은 할 수 없다","mis":"SO5-1-u2-X14"},{"t":"기후 행동은 기후를 매일 관찰해 기록하는 일이다","mis":"SO5-1-u2-X14"},{"t":"기후 행동은 한 번 하면 끝나는 일이다","mis":"SO5-1-u2-X15"}],"explanation":["여러 주체가 함께해요.","누구나 참여해요.","날마다 실천하고 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#9','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',4,'mc','auto','주제 「우리나라의 기후」에서 배운 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X13','SO5-1-u2-X14']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C7","difficulty":4,"kind":"mc","stem":"주제 「우리나라의 기후」에서 배운 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리나라의 기후는 매일 다르게 나타난다","correct":true},{"t":"대체로 남쪽으로 갈수록 기온이 높다","mis":"SO5-1-u2-X05"},{"t":"기후변화로 자연재해가 점점 심해지고 있다","mis":"SO5-1-u2-X13"},{"t":"기후 행동은 누구나 참여할 수 있다","mis":"SO5-1-u2-X14"}],"explanation":["매일 달라지는 것은 날씨예요.","기후는 오랜 기간의 평균이에요.","그래서 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L04_challenge#10','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',4,'essay','teacher','기후변화가 우리나라에 가져온 변화 두 가지를 쓰고, 내가 매일 실천할 기후 행동 두 가지와 실천한 뒤 할 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C8","difficulty":4,"kind":"essay","stem":"기후변화가 우리나라에 가져온 변화 두 가지를 쓰고, 내가 매일 실천할 기후 행동 두 가지와 실천한 뒤 할 일을 쓰세요.","answer_guide":{"answer":"예: 기후변화로 우리나라의 연평균 기온이 꾸준히 올라가고 여름은 길어지고 겨울은 짧아졌다. 또 폭염과 극한 호우 같은 자연재해가 더 자주, 더 세게 나타난다. 나는 가까운 거리는 걸어 다니고 급식을 남기지 않겠다. 실천한 뒤에는 수첩에 결과를 표시하고 잘 안 된 날은 까닭을 생각해 다시 실천하겠다.","scoring_points":["기후변화가 가져온 변화를 두 가지 썼는가","내가 매일 할 수 있는 기후 행동을 두 가지 썼는가","실천한 뒤 돌아보기를 썼는가"]},"explanation":["기온이 오르고 계절이 바뀌어요.","내가 매일 할 일을 골라요.","돌아보고 다시 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#1','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'mc','auto','일정한 지역에 살고 있는 사람의 수를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"일정한 지역에 살고 있는 사람의 수를 무엇이라고 하나요?","options":[{"t":"인구","correct":true},{"t":"인구 분포","mis":"SO5-1-u2-X16"},{"t":"인구 밀도","mis":"SO5-1-u2-X16"},{"t":"기후","mis":"SO5-1-u2-X01"}],"explanation":["사람의 수예요.","한 지역에 사는 사람이에요.","인구라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#2','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'mc','auto','인구가 모이거나 흩어져 있는 정도를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"인구가 모이거나 흩어져 있는 정도를 무엇이라고 하나요?","options":[{"t":"인구 분포","correct":true},{"t":"인구","mis":"SO5-1-u2-X16"},{"t":"인구 밀도","mis":"SO5-1-u2-X16"},{"t":"인구 이동","mis":"SO5-1-u2-X16"}],"explanation":["모이거나 흩어진 모양이에요.","분포는 퍼져 있는 모양이에요.","인구 분포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#3','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'sa','auto','일정한 넓이(1 km²) 안에 사는 사람의 수를 무엇이라고 하나요? (인구 □□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"sa","stem":"일정한 넓이(1 km²) 안에 사는 사람의 수를 무엇이라고 하나요? (인구 □□)","answer":["밀도"],"explanation":["빽빽한 정도예요.","1 km² 안을 봐요.","인구 밀도예요."],"mis":"SO5-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#4','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',1,'ox','auto','기후와 지형은 인구 분포에 영향을 주는 자연환경이에요.',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"ox","stem":"기후와 지형은 인구 분포에 영향을 주는 자연환경이에요.","answer":"O","reason_options":[{"t":"기후와 지형은 사람이 만든 것이 아니라 자연이 만든 환경이기 때문에","correct":true},{"t":"기후와 지형은 사람이 만든 인문환경이기 때문에","mis":"SO5-1-u2-X17"}],"mis":"SO5-1-u2-X17","explanation":["날씨와 땅의 생김새예요.","자연이 만들었어요.","자연환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#5','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','인구 분포에 영향을 주는 인문환경끼리 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"인구 분포에 영향을 주는 인문환경끼리 묶인 것은 어느 것인가요?","options":[{"t":"일자리·교통·교육","correct":true},{"t":"기후·지형·하천","mis":"SO5-1-u2-X17"},{"t":"기후·일자리·지형","mis":"SO5-1-u2-X17"},{"t":"지형·교통·기후","mis":"SO5-1-u2-X17"}],"explanation":["사람이 만든 환경이에요.","일할 곳, 다닐 길, 배울 곳이에요.","일자리·교통·교육이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#6','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','「이 지역에 있는 회사에 취직해서 이사 왔어요」라는 말에서 사는 곳을 정하는 데 영향을 준 환경은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"「이 지역에 있는 회사에 취직해서 이사 왔어요」라는 말에서 사는 곳을 정하는 데 영향을 준 환경은 어느 것인가요?","options":[{"t":"일자리","correct":true},{"t":"기후","mis":"SO5-1-u2-X17"},{"t":"지형","mis":"SO5-1-u2-X17"},{"t":"교육","mis":"SO5-1-u2-X17"}],"explanation":["회사에 취직했어요.","일할 곳 때문에 왔어요.","일자리예요."],"asset":{"type":"speech","turns":[{"who":"회사원","text":"이 지역 회사에 취직해서 이사 왔어요."},{"who":"부모님","text":"아이 공부를 생각해서 이 동네에 살아요."},{"who":"할아버지","text":"날씨가 따뜻하고 좋아서 이곳에 살아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#7','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','인구 밀도를 살펴보면 무엇을 알 수 있나요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"인구 밀도를 살펴보면 무엇을 알 수 있나요?","options":[{"t":"인구가 모여 있는 정도","correct":true},{"t":"그 지역까지 가는 길","mis":"SO5-1-u2-X16"},{"t":"그 지역 사람들의 나이","mis":"SO5-1-u2-X16"},{"t":"그 지역의 산 높이","mis":"SO5-1-u2-X16"}],"explanation":["1 km² 안의 사람 수예요.","빽빽한 정도를 알려 줘요.","모여 있는 정도를 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#8','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'mc','auto','두 지역 자료를 알맞게 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"두 지역 자료를 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"서울특별시는 강원특별자치도보다 면적이 좁지만 사람이 많아 인구 밀도가 높다","correct":true},{"t":"서울특별시는 면적이 넓어서 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"강원특별자치도는 면적이 넓어서 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"두 지역의 인구 밀도는 거의 같다","mis":"SO5-1-u2-X18"}],"explanation":["서울은 넓이가 좁아요.","그런데 사람이 많아요.","그래서 밀도가 높아요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#9','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',2,'ox','auto','대체로 도시가 발달한 지역에서 인구 밀도가 높게 나타나요.',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"ox","stem":"대체로 도시가 발달한 지역에서 인구 밀도가 높게 나타나요.","answer":"O","reason_options":[{"t":"일자리·교통·교육 같은 인문환경이 잘 갖춰져 사람이 모이기 때문에","correct":true},{"t":"도시는 땅이 넓어 사람들이 흩어져 살기 때문에","mis":"SO5-1-u2-X18"}],"mis":"SO5-1-u2-X18","explanation":["도시에는 일할 곳이 많아요.","교통과 학교도 많아요.","그래서 사람이 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_basic#10','soc',5,1,'u2','L05','g5_1_soc_u2_L05_basic','lesson_basic','SO5-1-u2-C9',3,'mc','auto','어느 곳에 사람이 더 모여 사는지 알아볼 때 사는 사람의 수만 세면 부족한 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X03']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"어느 곳에 사람이 더 모여 사는지 알아볼 때 사는 사람의 수만 세면 부족한 까닭은 어느 것인가요?","options":[{"t":"땅의 넓이에 따라 모여 사는 정도가 달라지기 때문에","correct":true},{"t":"사람 수는 해마다 달라지기 때문에","mis":"SO5-1-u2-X18"},{"t":"사람마다 집 크기가 다르기 때문에","mis":"SO5-1-u2-X18"},{"t":"지역마다 계절이 다르기 때문에","mis":"SO5-1-u2-X03"}],"explanation":["사람 수가 같아도 땅이 넓으면 흩어져요.","좁으면 모여요.","넓이도 함께 봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#1','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',2,'match','auto','세 사람의 말을 보고 말한 사람과 사는 곳을 정하는 데 영향을 준 환경을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"match","stem":"세 사람의 말을 보고 말한 사람과 사는 곳을 정하는 데 영향을 준 환경을 알맞게 이으세요.","pairs":[{"l":"회사원","r":"일자리"},{"l":"부모님","r":"교육"},{"l":"할아버지","r":"기후"}],"mis":"SO5-1-u2-X17","explanation":["취직은 일자리예요.","아이 공부는 교육이에요.","날씨가 좋은 것은 기후예요."],"asset":{"type":"speech","turns":[{"who":"회사원","text":"이 지역 회사에 취직해서 이사 왔어요."},{"who":"부모님","text":"아이 공부를 생각해서 이 동네에 살아요."},{"who":"할아버지","text":"날씨가 따뜻하고 좋아서 이곳에 살아요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#2','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',2,'sa','auto','일자리·교통·교육처럼 사람이 만든 환경을 무엇이라고 하나요? (□□환경)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"sa","stem":"일자리·교통·교육처럼 사람이 만든 환경을 무엇이라고 하나요? (□□환경)","answer":["인문"],"explanation":["자연이 만든 것이 아니에요.","사람이 만들었어요.","인문환경이에요."],"mis":"SO5-1-u2-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#3','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'mc','auto','두 마을에 똑같이 여덟 명이 사는데, 한 마을은 한쪽에 몰려 살고 다른 마을은 골고루 퍼져 살아요. 이것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"두 마을에 똑같이 여덟 명이 사는데, 한 마을은 한쪽에 몰려 살고 다른 마을은 골고루 퍼져 살아요. 이것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"인구가 같아도 인구 분포는 다를 수 있다","correct":true},{"t":"인구가 같으면 인구 분포도 언제나 같다","mis":"SO5-1-u2-X16"},{"t":"인구 분포는 사람 수만 뜻한다","mis":"SO5-1-u2-X16"},{"t":"두 마을의 인구 밀도는 볼 필요가 없다","mis":"SO5-1-u2-X18"}],"explanation":["사람 수는 같아요.","모인 모양은 달라요.","인구 분포가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#4','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'mc','auto','두 지역 자료에서 인구 밀도를 견주려면 꼭 함께 보아야 하는 두 가지는 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"두 지역 자료에서 인구 밀도를 견주려면 꼭 함께 보아야 하는 두 가지는 어느 것인가요?","options":[{"t":"땅 넓이와 사는 사람의 수","correct":true},{"t":"사는 사람의 수와 사람들의 나이","mis":"SO5-1-u2-X18"},{"t":"땅 넓이와 산의 높이","mis":"SO5-1-u2-X18"},{"t":"기온과 강수량","mis":"SO5-1-u2-X02"}],"explanation":["인구 밀도는 1 km² 안의 사람 수예요.","사람 수를 넓이로 나눠요.","두 가지가 꼭 필요해요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#5','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'mc','auto','「산지보다 평평한 땅에 사람이 많이 산다」는 것은 어떤 환경이 인구 분포에 준 영향인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"「산지보다 평평한 땅에 사람이 많이 산다」는 것은 어떤 환경이 인구 분포에 준 영향인가요?","options":[{"t":"지형 — 자연환경","correct":true},{"t":"지형 — 인문환경","mis":"SO5-1-u2-X17"},{"t":"교통 — 자연환경","mis":"SO5-1-u2-X17"},{"t":"교육 — 인문환경","mis":"SO5-1-u2-X17"}],"explanation":["땅의 생김새는 지형이에요.","지형은 자연이 만들었어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#6','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'ox','auto','인구 분포에 영향을 주는 환경의 정도는 시간이 흘러 사람들이 하는 일이 바뀌어도 늘 똑같아요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"ox","stem":"인구 분포에 영향을 주는 환경의 정도는 시간이 흘러 사람들이 하는 일이 바뀌어도 늘 똑같아요.","answer":"X","reason_options":[{"t":"사람들의 생각이나 하는 일이 바뀌면 영향을 주는 정도도 달라지기 때문에","correct":true},{"t":"한 번 정해진 인구 분포는 절대 바뀌지 않기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["영향의 정도는 저마다 달라요.","시간이 흐르면 바뀌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#7','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',3,'error','auto','인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X16']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"error","stem":"인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「강원특별자치도는 땅이 넓으니까 인구 밀도도 높을 거야.」","correct":true,"mis_target":"SO5-1-u2-X18"},{"t":"시우 — 「인구 밀도를 보려면 사람 수와 넓이를 함께 봐야 해.」","mis":"SO5-1-u2-X18"},{"t":"다인 — 「인구가 모이거나 흩어진 정도가 인구 분포야.」","mis":"SO5-1-u2-X16"}],"explanation":["넓은 땅에 사람이 적으면 밀도가 낮아요.","강원은 약 91명/km²예요.","라온의 말이 틀렸어요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#8','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',4,'mc','auto','「인구 분포」 마인드맵을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X02']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"mc","stem":"「인구 분포」 마인드맵을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"뜻 — 인구가 모이거나 흩어진 정도 / 영향 — 자연환경·인문환경 / 알아보는 방법 — 인구 밀도","correct":true},{"t":"뜻 — 한 지역의 사람 수 / 영향 — 인문환경만 / 알아보는 방법 — 땅 넓이","mis":"SO5-1-u2-X16"},{"t":"뜻 — 1 km² 안의 사람 수 / 영향 — 자연환경만 / 알아보는 방법 — 인구수","mis":"SO5-1-u2-X16"},{"t":"뜻 — 대기의 상태 / 영향 — 지형 / 알아보는 방법 — 등온선","mis":"SO5-1-u2-X02"}],"explanation":["뜻은 모인 정도예요.","두 환경의 영향을 받아요.","인구 밀도로 알아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#9','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',4,'mc','auto','사람이 너무 많이 모여 활력이 넘치지만 살 집이 부족해진 ◇◇시를 설명한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X17','SO5-1-u2-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"mc","stem":"사람이 너무 많이 모여 활력이 넘치지만 살 집이 부족해진 ◇◇시를 설명한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일자리·교육 같은 인문환경이 좋아 사람이 모여 인구 밀도가 높아진 곳이다","correct":true},{"t":"땅이 넓어 사람이 흩어져 사는 곳이다","mis":"SO5-1-u2-X18"},{"t":"기후가 나빠 사람이 떠나는 곳이다","mis":"SO5-1-u2-X17"},{"t":"인구는 많지만 인구 분포와는 관계없는 곳이다","mis":"SO5-1-u2-X16"}],"explanation":["일자리·대학교가 있어 모였어요.","인문환경의 영향이에요.","좁은 곳에 사람이 많아졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L05_challenge#10','soc',5,1,'u2','L05','g5_1_soc_u2_L05_challenge','lesson_challenge','SO5-1-u2-C9',4,'essay','teacher','두 지역 자료를 보고 어느 지역의 인구 밀도가 더 높은지 쓰고, 그 까닭을 넓이와 인구를 함께 들어 쓰세요. 또 인구 밀도가 높은 곳에 사람이 모이는 까닭을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"essay","stem":"두 지역 자료를 보고 어느 지역의 인구 밀도가 더 높은지 쓰고, 그 까닭을 넓이와 인구를 함께 들어 쓰세요. 또 인구 밀도가 높은 곳에 사람이 모이는 까닭을 한 가지 쓰세요.","answer_guide":{"answer":"예: 서울특별시의 인구 밀도가 더 높다. 서울특별시는 강원특별자치도보다 넓이가 훨씬 좁지만 사는 사람은 훨씬 많기 때문이다. 서울특별시처럼 도시가 발달한 곳에는 일자리와 교통, 교육 같은 인문환경이 잘 갖춰져 사람이 모인다.","scoring_points":["인구 밀도가 높은 지역을 바르게 골랐는가","넓이와 인구를 함께 들어 까닭을 썼는가","사람이 모이는 까닭을 썼는가"]},"explanation":["서울이 더 높아요.","좁은 땅에 사람이 많아요.","인문환경이 사람을 모아요."],"asset":{"type":"passage","lines":["서울특별시 — 넓이 약 605 km² · 인구 약 938만 명","서울특별시 — 인구 밀도 약 15,506명/km²","강원특별자치도 — 넓이 약 16,831 km² · 인구 약 153만 명","강원특별자치도 — 인구 밀도 약 91명/km²"],"title":"두 지역의 넓이·인구·인구 밀도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#1','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'mc','auto','1960년 무렵까지 우리나라 사람들은 주로 어디에 모여 살았나요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"1960년 무렵까지 우리나라 사람들은 주로 어디에 모여 살았나요?","options":[{"t":"국토의 남서쪽 평야 지대","correct":true},{"t":"국토의 북동쪽 산지","mis":"SO5-1-u2-X19"},{"t":"바다 위의 작은 섬","mis":"SO5-1-u2-X19"},{"t":"연평균 기온이 낮은 곳","mis":"SO5-1-u2-X19"}],"explanation":["벼농사를 짓던 때예요.","평야가 농사짓기 좋아요.","남서쪽 평야에 모였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#2','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'mc','auto','우리나라의 수도권에 속하는 곳끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"우리나라의 수도권에 속하는 곳끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"서울특별시·인천광역시·경기도","correct":true},{"t":"서울특별시·부산광역시·제주특별자치도","mis":"SO5-1-u2-X20"},{"t":"인천광역시·대구광역시·강원특별자치도","mis":"SO5-1-u2-X20"},{"t":"경기도·전라남도·경상북도","mis":"SO5-1-u2-X20"}],"explanation":["수도를 가운데 두고 이어져요.","서울과 맞닿은 곳이에요.","서울·인천·경기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#3','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C11',1,'sa','auto','인구를 나이·성별 등의 기준으로 나누어 본 짜임새를 무엇이라고 하나요? (인구 □□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C11","difficulty":1,"kind":"sa","stem":"인구를 나이·성별 등의 기준으로 나누어 본 짜임새를 무엇이라고 하나요? (인구 □□)","answer":["구조"],"explanation":["짜임새를 뜻해요.","나이별로 나누어 봐요.","인구 구조예요."],"mis":"SO5-1-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#4','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'ox','auto','오늘날 우리나라 인구의 절반 정도가 수도권에 모여 살아요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"ox","stem":"오늘날 우리나라 인구의 절반 정도가 수도권에 모여 살아요.","answer":"O","reason_options":[{"t":"산업화로 일자리와 교통이 갖춰진 수도권에 인구가 집중했기 때문에","correct":true},{"t":"수도권은 평야가 넓어 농사짓기가 가장 좋기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["수도권으로 사람이 모였어요.","일자리가 많아서예요.","절반 정도가 살아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#5','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'mc','auto','두 시기 인구분포도 읽기 메모에서 1960년에 인구가 몰린 곳은 어떤 곳인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 시기 인구분포도 읽기 메모에서 1960년에 인구가 몰린 곳은 어떤 곳인가요?","options":[{"t":"평야가 발달하고 기후가 온화한 서쪽과 남쪽 바닷가 가까이","correct":true},{"t":"산지가 많고 기온이 낮은 동쪽과 북쪽","mis":"SO5-1-u2-X19"},{"t":"바다에서 멀리 떨어진 안쪽 땅","mis":"SO5-1-u2-X19"},{"t":"서울 둘레의 대도시","mis":"SO5-1-u2-X19"}],"explanation":["진한 칸은 서쪽과 남쪽이에요.","평야가 넓고 따뜻해요.","농사짓기 좋은 곳이에요."],"asset":{"type":"passage","lines":["1960년 — 진한 색 칸이 서쪽과 남쪽 바닷가 가까이에 몰려 있다.","1960년 — 산지가 많은 동쪽과 북쪽 칸은 색이 옅다.","2023년 — 서울 둘레의 칸이 가장 진하다.","2023년 — 몇몇 대도시 칸도 진하고 촌락 칸은 옅어졌다."],"title":"두 시기 인구분포도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#6','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'mc','auto','두 시기 인구분포도 읽기 메모에서 2023년에 가장 진한 칸은 어디인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 시기 인구분포도 읽기 메모에서 2023년에 가장 진한 칸은 어디인가요?","options":[{"t":"서울 둘레의 수도권","correct":true},{"t":"농사짓기 좋은 촌락","mis":"SO5-1-u2-X19"},{"t":"산과 숲이 많은 곳","mis":"SO5-1-u2-X19"},{"t":"남서쪽 평야 지대","mis":"SO5-1-u2-X19"}],"explanation":["서울 둘레 칸이 가장 진해요.","대도시도 진해요.","촌락은 옅어졌어요."],"asset":{"type":"passage","lines":["1960년 — 진한 색 칸이 서쪽과 남쪽 바닷가 가까이에 몰려 있다.","1960년 — 산지가 많은 동쪽과 북쪽 칸은 색이 옅다.","2023년 — 서울 둘레의 칸이 가장 진하다.","2023년 — 몇몇 대도시 칸도 진하고 촌락 칸은 옅어졌다."],"title":"두 시기 인구분포도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#7','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'mc','auto','오늘날 우리나라의 인구 분포에 더 큰 영향을 주는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"mc","stem":"오늘날 우리나라의 인구 분포에 더 큰 영향을 주는 것은 어느 것인가요?","options":[{"t":"일자리·교통 같은 인문환경","correct":true},{"t":"기후·지형 같은 자연환경","mis":"SO5-1-u2-X19"},{"t":"환경의 영향이 모두 사라졌다","mis":"SO5-1-u2-X19"},{"t":"평야의 넓이","mis":"SO5-1-u2-X19"}],"explanation":["공업과 서비스업에서 많이 일해요.","사람이 만든 환경이 중요해요.","인문환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#8','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C11',2,'mc','auto','수도권과 비수도권 인구 자료에서 수도권인 경기도가 비수도권인 경상북도보다 비율이 더 높은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"mc","stem":"수도권과 비수도권 인구 자료에서 수도권인 경기도가 비수도권인 경상북도보다 비율이 더 높은 것은 어느 것인가요?","options":[{"t":"청장년층","correct":true},{"t":"노년층","mis":"SO5-1-u2-X20"},{"t":"유소년층과 노년층 모두","mis":"SO5-1-u2-X20"},{"t":"비율이 모두 같다","mis":"SO5-1-u2-X20"}],"explanation":["경기도 청장년층은 약 73%예요.","경상북도는 약 66%예요.","수도권이 더 높아요."],"asset":{"type":"passage","lines":["경기도(수도권) — 청장년층 약 73% · 노년층이 비교적 적다.","경상북도(비수도권) — 청장년층 약 66% · 노년층이 비교적 많다.","수도권으로 옮겨 온 까닭 — 직업이 가장 많다.","우리나라 인구의 절반 정도가 수도권에 산다."],"title":"수도권과 비수도권 인구 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#9','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',2,'ox','auto','산업화로 도시가 발달하면서 많은 사람이 도시에서 촌락으로 옮겨 갔어요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"ox","stem":"산업화로 도시가 발달하면서 많은 사람이 도시에서 촌락으로 옮겨 갔어요.","answer":"X","reason_options":[{"t":"많은 사람이 일자리를 찾아 촌락에서 도시로 옮겨 갔기 때문에","correct":true},{"t":"도시에는 일자리가 없어 사람들이 떠났기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["방향이 반대예요.","촌락에서 도시로 갔어요.","그래서 도시 인구가 늘었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_basic#10','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',3,'mc','auto','과거 우리나라 사람들이 남서쪽 평야 지대에 모여 산 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"과거 우리나라 사람들이 남서쪽 평야 지대에 모여 산 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벼농사 중심의 농업 사회라 기후가 온화하고 평야가 발달한 곳이 살기 좋았기 때문에","correct":true},{"t":"그곳에 공장과 회사가 가장 많았기 때문에","mis":"SO5-1-u2-X19"},{"t":"그곳에 높은 산이 많았기 때문에","mis":"SO5-1-u2-X19"},{"t":"그곳에 큰 대학교가 몰려 있었기 때문에","mis":"SO5-1-u2-X19"}],"explanation":["그때는 농사를 많이 지었어요.","평야와 따뜻한 기후가 중요했어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#1','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C11',2,'match','auto','인구 구조의 세 무리와 나이를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"match","stem":"인구 구조의 세 무리와 나이를 알맞게 이으세요.","pairs":[{"l":"유소년층","r":"14세 이하"},{"l":"청장년층","r":"15~64세"},{"l":"노년층","r":"65세 이상"}],"mis":"SO5-1-u2-X20","explanation":["어린이는 유소년층이에요.","일하는 나이는 청장년층이에요.","65세부터 노년층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#2','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',2,'sa','auto','수도를 중심으로 이루어진 대도시권을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C10","difficulty":2,"kind":"sa","stem":"수도를 중심으로 이루어진 대도시권을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["수도권"],"explanation":["수도를 가운데 둬요.","서울·인천·경기예요.","수도권이에요."],"mis":"SO5-1-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#3','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'mc','auto','수도권으로 옮겨 온 까닭 가운데 「직업」이 가장 많았다는 자료로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"수도권으로 옮겨 온 까닭 가운데 「직업」이 가장 많았다는 자료로 알 수 있는 것은 어느 것인가요?","options":[{"t":"수도권에 일자리가 많아 사람을 끌어모은다","correct":true},{"t":"수도권에는 평야가 넓게 펼쳐져 있다","mis":"SO5-1-u2-X19"},{"t":"수도권은 기후가 가장 온화하다","mis":"SO5-1-u2-X19"},{"t":"수도권으로 오는 사람은 거의 없다","mis":"SO5-1-u2-X19"}],"explanation":["직업 때문에 옮겨 왔어요.","일할 곳이 많다는 뜻이에요.","일자리는 인문환경이에요."],"asset":{"type":"passage","lines":["경기도(수도권) — 청장년층 약 73% · 노년층이 비교적 적다.","경상북도(비수도권) — 청장년층 약 66% · 노년층이 비교적 많다.","수도권으로 옮겨 온 까닭 — 직업이 가장 많다.","우리나라 인구의 절반 정도가 수도권에 산다."],"title":"수도권과 비수도권 인구 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#4','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C11',3,'mc','auto','비수도권이 수도권보다 노년층 인구 비율이 높게 나타나는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C11","difficulty":3,"kind":"mc","stem":"비수도권이 수도권보다 노년층 인구 비율이 높게 나타나는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일자리와 교육 기회를 찾아 청장년층이 수도권으로 빠져나갔기 때문에","correct":true},{"t":"비수도권에 아기가 가장 많이 태어나기 때문에","mis":"SO5-1-u2-X20"},{"t":"노년층이 모두 수도권을 떠나 왔기 때문에","mis":"SO5-1-u2-X20"},{"t":"비수도권은 기온이 높아 살기 어렵기 때문에","mis":"SO5-1-u2-X20"}],"explanation":["청장년층이 수도권으로 갔어요.","남은 사람 가운데 노년층이 많아요.","그래서 비율이 높아요."],"asset":{"type":"passage","lines":["경기도(수도권) — 청장년층 약 73% · 노년층이 비교적 적다.","경상북도(비수도권) — 청장년층 약 66% · 노년층이 비교적 많다.","수도권으로 옮겨 온 까닭 — 직업이 가장 많다.","우리나라 인구의 절반 정도가 수도권에 산다."],"title":"수도권과 비수도권 인구 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#5','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'mc','auto','두 시기 인구분포도 읽기 메모를 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 시기 인구분포도 읽기 메모를 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"인구가 남서쪽 평야에서 수도권과 대도시로 옮겨 모였다","correct":true},{"t":"인구가 수도권에서 남서쪽 평야로 옮겨 갔다","mis":"SO5-1-u2-X19"},{"t":"두 시기의 인구 분포가 똑같다","mis":"SO5-1-u2-X19"},{"t":"두 시기 모두 산지에 가장 많이 산다","mis":"SO5-1-u2-X19"}],"explanation":["1960년엔 서쪽·남쪽 바닷가예요.","2023년엔 서울 둘레와 대도시예요.","모이는 곳이 바뀌었어요."],"asset":{"type":"passage","lines":["1960년 — 진한 색 칸이 서쪽과 남쪽 바닷가 가까이에 몰려 있다.","1960년 — 산지가 많은 동쪽과 북쪽 칸은 색이 옅다.","2023년 — 서울 둘레의 칸이 가장 진하다.","2023년 — 몇몇 대도시 칸도 진하고 촌락 칸은 옅어졌다."],"title":"두 시기 인구분포도 읽기 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#6','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'ox','auto','인구분포도에서는 색이 진할수록 인구 밀도가 높은 지역이에요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"ox","stem":"인구분포도에서는 색이 진할수록 인구 밀도가 높은 지역이에요.","answer":"O","reason_options":[{"t":"인구 밀도를 몇 단계로 나누어 높을수록 진한 색으로 칠하기 때문에","correct":true},{"t":"진한 색은 땅이 높은 산지를 나타내기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["인구 밀도를 단계로 나눠요.","높을수록 진하게 칠해요.","진한 곳이 많이 모인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#7','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',3,'error','auto','우리나라 인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X19','SO5-1-u2-X20']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"error","stem":"우리나라 인구 분포를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「옛날이나 지금이나 인구 분포는 기후와 지형만 보면 다 알 수 있어.」","correct":true,"mis_target":"SO5-1-u2-X19"},{"t":"선호 — 「오늘날에는 인구 100명 중 92명 정도가 도시에 살아.」","mis":"SO5-1-u2-X19"},{"t":"보미 — 「수도권에는 청장년층 비율이 높아.」","mis":"SO5-1-u2-X20"}],"explanation":["옛날엔 자연환경의 영향이 컸어요.","오늘날엔 인문환경의 영향이 커요.","지율의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#8','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',4,'mc','auto','1960년과 오늘날의 인구 분포를 가장 바르게 견준 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"1960년과 오늘날의 인구 분포를 가장 바르게 견준 것은 어느 것인가요?","options":[{"t":"1960년에는 자연환경의 영향으로 남서쪽 평야에, 오늘날에는 인문환경의 영향으로 수도권과 대도시에 모여 산다","correct":true},{"t":"1960년에는 인문환경의 영향으로 수도권에, 오늘날에는 자연환경의 영향으로 평야에 모여 산다","mis":"SO5-1-u2-X19"},{"t":"두 시기 모두 인구가 전국에 고르게 퍼져 있다","mis":"SO5-1-u2-X19"},{"t":"두 시기 모두 산지가 많은 동쪽에 모여 산다","mis":"SO5-1-u2-X19"}],"explanation":["그때는 농업 사회였어요.","지금은 산업화된 도시 사회예요.","영향을 준 환경이 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#9','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',4,'mc','auto','「우리나라 인구의 절반 정도가 수도권에 산다」는 사실과 「1학년 신입생이 없는 학교가 대부분 비수도권에 있다」는 사실을 이어 보면 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20','SO5-1-u2-X22']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"「우리나라 인구의 절반 정도가 수도권에 산다」는 사실과 「1학년 신입생이 없는 학교가 대부분 비수도권에 있다」는 사실을 이어 보면 알 수 있는 것은 어느 것인가요?","options":[{"t":"인구가 수도권으로 몰리면서 인구 분포의 불균형이 커지고 있다","correct":true},{"t":"비수도권에 아이들이 가장 많이 산다","mis":"SO5-1-u2-X20"},{"t":"인구가 전국에 고르게 나뉘어 있다","mis":"SO5-1-u2-X22"},{"t":"두 사실은 서로 관계가 없다","mis":"SO5-1-u2-X22"}],"explanation":["사람이 수도권으로 몰려요.","비수도권에는 학생이 줄어요.","불균형이 커지고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L06_challenge#10','soc',5,1,'u2','L06','g5_1_soc_u2_L06_challenge','lesson_challenge','SO5-1-u2-C10',4,'essay','teacher','과거와 오늘날 우리나라 인구 분포의 특징을 각각 쓰고, 영향을 준 환경이 어떻게 달라졌는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"essay","stem":"과거와 오늘날 우리나라 인구 분포의 특징을 각각 쓰고, 영향을 준 환경이 어떻게 달라졌는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 과거에는 국토의 남서쪽 평야 지대에 많은 사람이 모여 살았다. 벼농사 중심의 농업 사회라 기후가 온화하고 평야가 발달한 곳이 살기 좋았기 때문에 자연환경의 영향을 크게 받았다. 오늘날에는 수도권과 대도시에 인구가 모여 인구의 절반 정도가 수도권에 산다. 산업화로 도시가 발달해 일자리와 교통 같은 인문환경의 영향을 크게 받기 때문이다.","scoring_points":["과거 인구 분포의 특징을 썼는가","오늘날 인구 분포의 특징을 썼는가","자연환경에서 인문환경으로 바뀐 까닭을 썼는가"]},"explanation":["과거 — 남서쪽 평야예요.","오늘 — 수도권과 대도시예요.","농업 사회에서 산업 사회로 바뀌었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#1','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'mc','auto','인구가 지나치게 몰리는 수도권에서 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"인구가 지나치게 몰리는 수도권에서 나타나는 문제는 어느 것인가요?","options":[{"t":"도로에 차가 많아 교통 체증이 생긴다","correct":true},{"t":"학교에 1학년 신입생이 없다","mis":"SO5-1-u2-X21"},{"t":"일손이 부족해 일할 사람을 구하기 어렵다","mis":"SO5-1-u2-X21"},{"t":"빈집이 늘어난다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 많아서 생기는 문제예요.","차가 많아 길이 막혀요.","나머지는 사람이 줄어드는 곳의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#2','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'mc','auto','인구가 줄어드는 비수도권에서 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"인구가 줄어드는 비수도권에서 나타나는 문제는 어느 것인가요?","options":[{"t":"빈집과 폐교가 늘어난다","correct":true},{"t":"주택 가격이 크게 오른다","mis":"SO5-1-u2-X21"},{"t":"지하철에 승객이 너무 많다","mis":"SO5-1-u2-X21"},{"t":"쓰레기가 너무 많아 처리하기 어렵다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 빠져나갔어요.","집과 학교가 비어요.","나머지는 몰리는 곳의 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#3','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'sa','auto','한 나라가 경제·기술·사회·정치 등 여러 분야에서 다른 나라와 경쟁하는 힘을 무엇이라고 하나요? (국가 □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"sa","stem":"한 나라가 경제·기술·사회·정치 등 여러 분야에서 다른 나라와 경쟁하는 힘을 무엇이라고 하나요? (국가 □□□)","answer":["경쟁력"],"explanation":["나라와 나라 사이의 힘이에요.","경쟁하는 힘이에요.","국가 경쟁력이에요."],"mis":"SO5-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#4','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',1,'ox','auto','인구 분포의 불균형은 국가 경쟁력을 떨어뜨릴 수 있어요.',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"ox","stem":"인구 분포의 불균형은 국가 경쟁력을 떨어뜨릴 수 있어요.","answer":"O","reason_options":[{"t":"지역 격차가 커지면 나라 전체가 힘을 잃을 수 있기 때문에","correct":true},{"t":"불균형은 비수도권 한 곳만의 문제이기 때문에","mis":"SO5-1-u2-X22"}],"mis":"SO5-1-u2-X22","explanation":["격차가 커져요.","나라 전체의 힘이 약해져요.","그래서 균형 발전이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#5','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','되풀이되는 두 고리에서 ㉮ 고리가 계속 돌면 수도권에 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"되풀이되는 두 고리에서 ㉮ 고리가 계속 돌면 수도권에 나타나는 문제는 어느 것인가요?","options":[{"t":"주택이 부족해지고 교통과 환경 문제가 심해진다","correct":true},{"t":"빈집이 늘고 학교가 문을 닫는다","mis":"SO5-1-u2-X21"},{"t":"일손이 부족해진다","mis":"SO5-1-u2-X21"},{"t":"상점과 병원이 줄어든다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 계속 모여요.","좁은 곳에 너무 많아요.","집·교통·환경 문제가 생겨요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#6','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','되풀이되는 두 고리에서 ㉯ 고리가 계속 돌면 비수도권에 나타나는 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"되풀이되는 두 고리에서 ㉯ 고리가 계속 돌면 비수도권에 나타나는 문제는 어느 것인가요?","options":[{"t":"빈집과 폐교가 늘고 일손이 부족해진다","correct":true},{"t":"집값이 크게 오른다","mis":"SO5-1-u2-X21"},{"t":"교통 체증이 심해진다","mis":"SO5-1-u2-X21"},{"t":"쓰레기를 묻을 자리가 모자란다","mis":"SO5-1-u2-X21"}],"explanation":["사람이 계속 떠나요.","시설이 더 줄어요.","빈집·폐교·일손 부족이에요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#7','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','불균형을 보여 주는 자료에서 1학년 신입생이 없는 초등학교가 많은 곳은 어디인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X25']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"불균형을 보여 주는 자료에서 1학년 신입생이 없는 초등학교가 많은 곳은 어디인가요?","options":[{"t":"비수도권","correct":true},{"t":"수도권","mis":"SO5-1-u2-X21"},{"t":"두 곳이 같다","mis":"SO5-1-u2-X21"},{"t":"자료로 알 수 없다","mis":"SO5-1-u2-X25"}],"explanation":["수도권은 9곳이에요.","비수도권은 148곳이에요.","비수도권이 훨씬 많아요."],"asset":{"type":"passage","lines":["1학년 신입생이 없는 초등학교 — 2022년 121곳 → 2024년 157곳","2024년 157곳 가운데 — 수도권 9곳 · 비수도권 148곳","최근 10년 동안 비수도권 20대 약 60만 명이 수도권으로 옮겨 갔다.","옮겨 간 가장 큰 까닭 — 취업과 학업"],"title":"불균형을 보여 주는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#8','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'mc','auto','비수도권의 20대 청년이 수도권으로 옮겨 간 가장 큰 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"비수도권의 20대 청년이 수도권으로 옮겨 간 가장 큰 까닭은 어느 것인가요?","options":[{"t":"취업과 학업","correct":true},{"t":"기후와 지형","mis":"SO5-1-u2-X17"},{"t":"관광과 휴식","mis":"SO5-1-u2-X17"},{"t":"농사와 고기잡이","mis":"SO5-1-u2-X17"}],"explanation":["일할 곳과 배울 곳이에요.","인문환경과 이어져요.","취업과 학업이에요."],"asset":{"type":"passage","lines":["1학년 신입생이 없는 초등학교 — 2022년 121곳 → 2024년 157곳","2024년 157곳 가운데 — 수도권 9곳 · 비수도권 148곳","최근 10년 동안 비수도권 20대 약 60만 명이 수도권으로 옮겨 갔다.","옮겨 간 가장 큰 까닭 — 취업과 학업"],"title":"불균형을 보여 주는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#9','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',2,'ox','auto','거주지를 옮겨 들어온 인구수에서 나간 인구수를 뺀 값을 순이동이라고 해요.',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"ox","stem":"거주지를 옮겨 들어온 인구수에서 나간 인구수를 뺀 값을 순이동이라고 해요.","answer":"O","reason_options":[{"t":"들어온 사람과 나간 사람을 견주어 남은 값을 보기 때문에","correct":true},{"t":"순이동은 한 해에 새로 태어난 아기의 수이기 때문에","mis":"SO5-1-u2-X16"}],"mis":"SO5-1-u2-X16","explanation":["들어온 수에서 나간 수를 빼요.","빼고 남은 값이에요.","순이동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_basic#10','soc',5,1,'u2','L07','g5_1_soc_u2_L07_basic','lesson_basic','SO5-1-u2-C12',3,'mc','auto','신선 식품을 손쉽게 구할 수 없는 「식품 사막」이 생기는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"신선 식품을 손쉽게 구할 수 없는 「식품 사막」이 생기는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"인구가 줄어 신선 식품이 팔리지 않자 상점이 들여놓지 않기 때문에","correct":true},{"t":"신선 식품을 사려는 사람이 너무 많기 때문에","mis":"SO5-1-u2-X21"},{"t":"신선 식품 값이 크게 내렸기 때문에","mis":"SO5-1-u2-X21"},{"t":"도로가 넓어져 상점이 많아졌기 때문에","mis":"SO5-1-u2-X21"}],"explanation":["사는 사람이 줄었어요.","팔리지 않으면 들여놓지 않아요.","그래서 식품 사막이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#1','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',2,'match','auto','문제와 그 문제가 주로 나타나는 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"match","stem":"문제와 그 문제가 주로 나타나는 곳을 알맞게 이으세요.","pairs":[{"l":"주택 가격 상승","r":"인구가 몰리는 수도권"},{"l":"폐교 증가","r":"인구가 줄어드는 비수도권"},{"l":"지하철 혼잡","r":"사람이 붐비는 대도시"},{"l":"식품 사막","r":"상점이 사라진 작은 마을"}],"mis":"SO5-1-u2-X21","explanation":["집값과 지하철은 사람이 몰리는 곳이에요.","폐교와 식품 사막은 사람이 줄어든 곳이에요.","두 곳의 문제가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#2','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',2,'sa','auto','수도권과 비수도권 사이처럼 지역 사이에 생기는 차이를 무엇이라고 하나요? (지역 □□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"sa","stem":"수도권과 비수도권 사이처럼 지역 사이에 생기는 차이를 무엇이라고 하나요? (지역 □□)","answer":["격차"],"explanation":["두 지역의 차이예요.","불균형이 심하면 커져요.","지역 격차예요."],"mis":"SO5-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#3','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'mc','auto','불균형을 보여 주는 자료에서 신입생이 없는 학교가 2022년 121곳에서 2024년 157곳으로 늘어난 것으로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X25','SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"불균형을 보여 주는 자료에서 신입생이 없는 학교가 2022년 121곳에서 2024년 157곳으로 늘어난 것으로 알 수 있는 것은 어느 것인가요?","options":[{"t":"비수도권을 중심으로 학생 수가 계속 줄고 있다","correct":true},{"t":"전국에 학교가 새로 많이 생기고 있다","mis":"SO5-1-u2-X25"},{"t":"수도권의 학생 수가 가장 크게 줄고 있다","mis":"SO5-1-u2-X21"},{"t":"학생 수 변화는 인구 분포와 관계없다","mis":"SO5-1-u2-X22"}],"explanation":["신입생 없는 학교가 늘었어요.","대부분 비수도권이에요.","학생 수가 줄고 있어요."],"asset":{"type":"passage","lines":["1학년 신입생이 없는 초등학교 — 2022년 121곳 → 2024년 157곳","2024년 157곳 가운데 — 수도권 9곳 · 비수도권 148곳","최근 10년 동안 비수도권 20대 약 60만 명이 수도권으로 옮겨 갔다.","옮겨 간 가장 큰 까닭 — 취업과 학업"],"title":"불균형을 보여 주는 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#4','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'mc','auto','상점이나 공장이 사라진 마을에서 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"상점이나 공장이 사라진 마을에서 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"물건을 구하기 어렵고 일자리가 줄어 다른 지역으로 떠나는 사람이 늘어난다","correct":true},{"t":"일자리가 늘어 사람들이 더 모여든다","mis":"SO5-1-u2-X21"},{"t":"집값이 크게 올라 집을 구하기 어렵다","mis":"SO5-1-u2-X21"},{"t":"아무 일도 일어나지 않는다","mis":"SO5-1-u2-X22"}],"explanation":["생활이 불편해져요.","일할 곳도 줄어요.","사람들이 또 떠나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#5','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'mc','auto','되풀이되는 두 고리에서 두 고리가 함께 돌 때 우리나라 전체에 생기는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"되풀이되는 두 고리에서 두 고리가 함께 돌 때 우리나라 전체에 생기는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지역 격차가 커져 국가 경쟁력이 떨어질 수 있다","correct":true},{"t":"두 지역의 인구가 저절로 비슷해진다","mis":"SO5-1-u2-X22"},{"t":"비수도권만 어려워지고 수도권은 문제가 없다","mis":"SO5-1-u2-X22"},{"t":"나라 전체의 힘이 저절로 강해진다","mis":"SO5-1-u2-X22"}],"explanation":["두 고리가 서로를 밀어붙여요.","격차가 점점 커져요.","나라 전체가 힘을 잃어요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#6','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'ox','auto','수도권은 사람이 많은 곳이라 주택과 시설이 늘 넉넉해요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"ox","stem":"수도권은 사람이 많은 곳이라 주택과 시설이 늘 넉넉해요.","answer":"X","reason_options":[{"t":"사람이 너무 많아 주택이 부족해지고 가격이 오르며 시설도 부족해지기 때문에","correct":true},{"t":"사람이 많을수록 집과 시설은 저절로 남기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["사람이 너무 많아요.","집이 모자라요.","시설도 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#7','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',3,'error','auto','인구 분포의 불균형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"error","stem":"인구 분포의 불균형을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「비수도권에서는 집이 모자라서 집값이 크게 오르고 있어.」","correct":true,"mis_target":"SO5-1-u2-X21"},{"t":"정우 — 「비수도권에서는 청장년층이 빠져나가 일손이 부족해.」","mis":"SO5-1-u2-X21"},{"t":"소율 — 「수도권에서는 쓰레기가 많아 처리하기 어려워.」","mis":"SO5-1-u2-X21"}],"explanation":["집값 상승은 몰리는 곳의 문제예요.","비수도권에는 빈집이 늘어요.","하린의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#8','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',4,'mc','auto','되풀이되는 두 고리를 보고 인구 분포의 불균형을 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"mc","stem":"되풀이되는 두 고리를 보고 인구 분포의 불균형을 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"한쪽은 모여서 더 모이고 다른 쪽은 떠나서 더 떠나는 일이 되풀이되어, 두 지역 모두 문제가 커진다","correct":true},{"t":"사람이 모이는 곳은 문제가 없고 떠나는 곳에만 문제가 생긴다","mis":"SO5-1-u2-X22"},{"t":"시간이 지나면 두 고리가 저절로 멈춘다","mis":"SO5-1-u2-X22"},{"t":"두 고리는 서로 아무 관계가 없다","mis":"SO5-1-u2-X22"}],"explanation":["㉮는 모여서 더 모여요.","㉯는 떠나서 더 떠나요.","두 곳 모두 문제가 생겨요."],"asset":{"type":"passage","lines":["㉮ 사람이 모인다 → 일자리와 시설이 늘어난다 → 더 많은 사람이 모인다","㉯ 사람이 떠난다 → 상점·병원·학교가 줄어든다 → 더 많은 사람이 떠난다"],"title":"되풀이되는 두 고리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#9','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',4,'mc','auto','인구가 줄어든 마을에 「찾아가는 이동형 상점」이 대안으로 떠오른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24','SO5-1-u2-X21']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"mc","stem":"인구가 줄어든 마을에 「찾아가는 이동형 상점」이 대안으로 떠오른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상점이 없어진 곳에 물건이 찾아가 주민이 신선 식품을 구할 수 있게 하기 때문에","correct":true},{"t":"마을 사람들을 도시로 옮겨 살게 하기 때문에","mis":"SO5-1-u2-X24"},{"t":"도시의 큰 상점을 더 넓히기 때문에","mis":"SO5-1-u2-X24"},{"t":"마을에 사람이 더 줄게 만들기 때문에","mis":"SO5-1-u2-X21"}],"explanation":["식품 사막의 문제를 풀어요.","물건이 마을을 찾아가요.","사는 곳에서 돕는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L07_challenge#10','soc',5,1,'u2','L07','g5_1_soc_u2_L07_challenge','lesson_challenge','SO5-1-u2-C12',4,'essay','teacher','인구가 몰리는 수도권과 인구가 줄어드는 비수도권에서 나타나는 문제를 각각 두 가지씩 쓰고, 이 문제가 나라 전체에 어떤 영향을 줄 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"essay","stem":"인구가 몰리는 수도권과 인구가 줄어드는 비수도권에서 나타나는 문제를 각각 두 가지씩 쓰고, 이 문제가 나라 전체에 어떤 영향을 줄 수 있는지 쓰세요.","answer_guide":{"answer":"예: 수도권에서는 집이 부족해 주택 가격이 오르고, 도로와 지하철이 붐벼 교통 혼잡이 심하다. 비수도권에서는 빈집과 폐교가 늘고, 청장년층이 빠져나가 일손이 부족해진다. 이런 일이 되풀이되면 지역 격차가 커져 나라 전체의 국가 경쟁력이 떨어질 수 있다.","scoring_points":["수도권의 문제를 두 가지 썼는가","비수도권의 문제를 두 가지 썼는가","국가 경쟁력과 이어 썼는가"]},"explanation":["몰리는 곳의 문제예요.","빠져나가는 곳의 문제예요.","나라 전체의 힘이 약해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#1','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'mc','auto','공공 기관을 수도권에서 전국 곳곳으로 옮기는 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"mc","stem":"공공 기관을 수도권에서 전국 곳곳으로 옮기는 까닭은 어느 것인가요?","options":[{"t":"인구 이동과 지역 발전을 이끌기 위해서","correct":true},{"t":"수도권에 사람을 더 모으기 위해서","mis":"SO5-1-u2-X23"},{"t":"수도권 건물을 더 높이 짓기 위해서","mis":"SO5-1-u2-X23"},{"t":"공공 기관의 수를 줄이기 위해서","mis":"SO5-1-u2-X23"}],"explanation":["직원과 가족도 함께 옮겨 가요.","그곳에 일자리가 생겨요.","지역이 발전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#2','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'mc','auto','고향이나 관심 있는 지역에 기부하면 답례품과 세금 혜택을 주는 제도는 어느 것인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X10']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"mc","stem":"고향이나 관심 있는 지역에 기부하면 답례품과 세금 혜택을 주는 제도는 어느 것인가요?","options":[{"t":"고향 사랑 기부제","correct":true},{"t":"디지털 관광 주민증","mis":"SO5-1-u2-X23"},{"t":"기상 특보","mis":"SO5-1-u2-X10"},{"t":"청년 마을 만들기","mis":"SO5-1-u2-X23"}],"explanation":["기부를 하는 제도예요.","답례품을 받아요.","고향 사랑 기부제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#3','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'sa','auto','공공 기관의 이전을 계기로 지역의 새로운 성장 동력을 만드는 미래형 도시를 무엇이라고 하나요? (□□ 도시)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"sa","stem":"공공 기관의 이전을 계기로 지역의 새로운 성장 동력을 만드는 미래형 도시를 무엇이라고 하나요? (□□ 도시)","answer":["혁신"],"explanation":["공공 기관이 옮겨 와요.","새로 자라날 힘을 만들어요.","혁신 도시예요."],"mis":"SO5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#4','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',1,'ox','auto','로컬 브랜딩은 지역의 자원과 문화를 살려 그 지역만의 매력을 만드는 일이에요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C13","difficulty":1,"kind":"ox","stem":"로컬 브랜딩은 지역의 자원과 문화를 살려 그 지역만의 매력을 만드는 일이에요.","answer":"O","reason_options":[{"t":"그 지역에만 있는 것을 살려 사람들을 끌어모으기 때문에","correct":true},{"t":"전국 모든 마을을 똑같은 모습으로 만드는 일이기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["지역만의 것을 살려요.","알릴 거리를 만들어요.","사람들이 찾아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#5','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'match','auto','균형 발전 노력 카드를 보고 카드와 노력의 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"match","stem":"균형 발전 노력 카드를 보고 카드와 노력의 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"공공 기관 이전"},{"l":"㉯","r":"고향 사랑 기부제"},{"l":"㉰","r":"로컬 브랜딩"},{"l":"㉱","r":"청년 마을 만들기"}],"mis":"SO5-1-u2-X23","explanation":["㉮는 기관이 옮겨 가요.","㉯는 기부, ㉰는 지역의 매력이에요.","㉱는 청년이 머물게 도와요."],"asset":{"type":"passage","lines":["㉮ 공공 기관을 수도권에서 여러 지역으로 옮긴다.","㉯ 고향이나 관심 지역에 기부하면 답례품을 준다.","㉰ 지역의 자원과 문화로 지역만의 매력을 만든다.","㉱ 청년이 지역에 머물며 살아 보도록 돕는다.","㉲ 작은 학교에 특별한 교육과정과 시설을 지원한다.","㉳ 살지 않아도 관광객이 주민처럼 혜택을 받게 한다."],"title":"균형 발전 노력 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#6','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'mc','auto','균형 발전 노력 카드 ㉲에 알맞은 노력은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"균형 발전 노력 카드 ㉲에 알맞은 노력은 어느 것인가요?","options":[{"t":"작은 학교 살리기","correct":true},{"t":"디지털 관광 주민증","mis":"SO5-1-u2-X23"},{"t":"공공 기관 이전","mis":"SO5-1-u2-X23"},{"t":"로컬 브랜딩","mis":"SO5-1-u2-X23"}],"explanation":["학교를 지원해요.","특별한 교육과정이 있어요.","작은 학교 살리기예요."],"asset":{"type":"passage","lines":["㉮ 공공 기관을 수도권에서 여러 지역으로 옮긴다.","㉯ 고향이나 관심 지역에 기부하면 답례품을 준다.","㉰ 지역의 자원과 문화로 지역만의 매력을 만든다.","㉱ 청년이 지역에 머물며 살아 보도록 돕는다.","㉲ 작은 학교에 특별한 교육과정과 시설을 지원한다.","㉳ 살지 않아도 관광객이 주민처럼 혜택을 받게 한다."],"title":"균형 발전 노력 카드 여섯 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#7','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'mc','auto','청년 마을 만들기 사업이 하려는 일은 어느 것인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X24']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"청년 마을 만들기 사업이 하려는 일은 어느 것인가요?","options":[{"t":"청년의 정착을 도와 지역 청년이 빠져나가는 것을 줄인다","correct":true},{"t":"청년들을 모두 수도권으로 보낸다","mis":"SO5-1-u2-X23"},{"t":"청년만 살 수 있게 다른 사람은 못 들어오게 한다","mis":"SO5-1-u2-X24"},{"t":"청년에게 농사만 짓게 한다","mis":"SO5-1-u2-X24"}],"explanation":["청년이 떠나고 있었어요.","머물러 살아 보게 도와요.","정착을 지원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#8','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C14',2,'mc','auto','내가 생각한 해결 방안을 평가할 때 살펴보지 않아도 되는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"mc","stem":"내가 생각한 해결 방안을 평가할 때 살펴보지 않아도 되는 것은 어느 것인가요?","options":[{"t":"다른 나라에서 먼저 해 본 적이 있는지","correct":true},{"t":"문제의 원인을 해결하는 데 도움이 되는지","mis":"SO5-1-u2-X24"},{"t":"도덕적으로 옳은 방안인지","mis":"SO5-1-u2-X24"},{"t":"비용과 노력을 생각할 때 실현할 수 있는지","mis":"SO5-1-u2-X24"}],"explanation":["잣대는 셋이에요.","원인·옳음·실현이에요.","먼저 한 나라는 조건이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#9','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',2,'ox','auto','인구가 빠져나간 지역에서는 주거·교육 환경을 고치고 창업을 지원하는 등 스스로 노력하기도 해요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"ox","stem":"인구가 빠져나간 지역에서는 주거·교육 환경을 고치고 창업을 지원하는 등 스스로 노력하기도 해요.","answer":"O","reason_options":[{"t":"살기 좋은 지역을 만들어 인구를 끌어들이려 하기 때문에","correct":true},{"t":"지역은 스스로 할 수 있는 일이 하나도 없기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["지역도 노력해요.","새 일자리를 만들어요.","살기 좋은 곳으로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_basic#10','soc',5,1,'u2','L08','g5_1_soc_u2_L08_basic','lesson_basic','SO5-1-u2-C13',3,'mc','auto','어느 바닷가 마을 이야기에서 인구가 다시 늘기 시작한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24','SO5-1-u2-X23','SO5-1-u2-X22']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"mc","stem":"어느 바닷가 마을 이야기에서 인구가 다시 늘기 시작한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주민이 참여한 사업으로 소득이 늘고 지역 경제가 활발해졌기 때문에","correct":true},{"t":"수도권 사람들을 억지로 옮겨 오게 했기 때문에","mis":"SO5-1-u2-X24"},{"t":"마을의 학교를 모두 닫았기 때문에","mis":"SO5-1-u2-X23"},{"t":"그해에 우연히 사람이 몰렸기 때문에","mis":"SO5-1-u2-X22"}],"explanation":["주민이 직접 참여했어요.","소득이 늘었어요.","경제가 살아나 사람이 늘었어요."],"asset":{"type":"passage","lines":["① 마을이 주민도 참여할 수 있는 햇빛 발전 사업을 만들었다.","② 주민들이 사업에 적극 참여했다.","③ 수익을 나누어 받아 주민 소득이 늘었다.","④ 지역 경제가 활발해지고 새로운 일거리가 생겼다.","⑤ 줄어들던 인구가 다시 늘기 시작했다."],"title":"어느 바닷가 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#1','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',2,'match','auto','해결 방안을 평가하는 세 잣대와 그 잣대가 묻는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"match","stem":"해결 방안을 평가하는 세 잣대와 그 잣대가 묻는 것을 알맞게 이으세요.","pairs":[{"l":"원인","r":"문제의 원인을 푸는 데 도움이 되는가"},{"l":"옳음","r":"누구에게 억지로 시키지 않는 옳은 방안인가"},{"l":"실현","r":"비용과 노력을 생각할 때 해낼 수 있는가"}],"mis":"SO5-1-u2-X24","explanation":["먼저 원인과 이어지는지 봐요.","옳은 방안인지 봐요.","해낼 수 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#2','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',2,'sa','auto','지역의 자원과 문화에 새로운 생각을 더해 상품과 가치를 만드는 사람을 무엇이라고 하나요? (로컬 □□□□□)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"sa","stem":"지역의 자원과 문화에 새로운 생각을 더해 상품과 가치를 만드는 사람을 무엇이라고 하나요? (로컬 □□□□□)","answer":["크리에이터"],"explanation":["지역에 활력을 가져와요.","지역만의 상품을 만들어요.","로컬 크리에이터예요."],"mis":"SO5-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#3','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',3,'mc','auto','모둠 방안 메모에서 세 잣대를 모두 지나는 방안은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"mc","stem":"모둠 방안 메모에서 세 잣대를 모두 지나는 방안은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"SO5-1-u2-X24"},{"t":"㉯","mis":"SO5-1-u2-X24"},{"t":"㉱","mis":"SO5-1-u2-X24"}],"explanation":["㉮는 억지로 시켜 옳지 않아요.","㉯는 비용이 너무 커요.","㉱는 원인과 이어지지 않아요."],"asset":{"type":"passage","lines":["문제 — 비수도권에 일자리가 줄어 청장년층이 떠난다.","방안 ㉮ 수도권 사람들을 억지로 옮겨 살게 한다.","방안 ㉯ 모든 마을에 큰 회사 본사를 하나씩 새로 짓는다.","방안 ㉰ 비수도권에 공장을 세우면 건설 비용을 지원한다.","방안 ㉱ 수도권 회사에 다니는 사람에게 상을 준다."],"title":"모둠 방안 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#4','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',3,'mc','auto','모둠 방안 메모의 방안 ㉮가 걸리는 잣대는 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"mc","stem":"모둠 방안 메모의 방안 ㉮가 걸리는 잣대는 어느 것인가요?","options":[{"t":"도덕적으로 옳은가","correct":true},{"t":"원인 해결에 도움이 되는가","mis":"SO5-1-u2-X24"},{"t":"실현할 수 있는가","mis":"SO5-1-u2-X24"},{"t":"세 잣대를 모두 지난다","mis":"SO5-1-u2-X24"}],"explanation":["사는 곳은 스스로 정해요.","억지로 옮기게 하면 안 돼요.","옳음에서 걸려요."],"asset":{"type":"passage","lines":["문제 — 비수도권에 일자리가 줄어 청장년층이 떠난다.","방안 ㉮ 수도권 사람들을 억지로 옮겨 살게 한다.","방안 ㉯ 모든 마을에 큰 회사 본사를 하나씩 새로 짓는다.","방안 ㉰ 비수도권에 공장을 세우면 건설 비용을 지원한다.","방안 ㉱ 수도권 회사에 다니는 사람에게 상을 준다."],"title":"모둠 방안 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#5','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',3,'mc','auto','어느 바닷가 마을 이야기의 차례에서 가장 먼저 있어야 할 일은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"mc","stem":"어느 바닷가 마을 이야기의 차례에서 가장 먼저 있어야 할 일은 어느 것인가요?","options":[{"t":"주민이 참여할 수 있는 사업을 만드는 일","correct":true},{"t":"인구가 늘어나는 일","mis":"SO5-1-u2-X23"},{"t":"지역 경제가 활발해지는 일","mis":"SO5-1-u2-X23"},{"t":"주민 소득이 늘어나는 일","mis":"SO5-1-u2-X23"}],"explanation":["①이 출발점이에요.","사업이 있어야 참여해요.","그다음 소득이 늘어요."],"asset":{"type":"passage","lines":["① 마을이 주민도 참여할 수 있는 햇빛 발전 사업을 만들었다.","② 주민들이 사업에 적극 참여했다.","③ 수익을 나누어 받아 주민 소득이 늘었다.","④ 지역 경제가 활발해지고 새로운 일거리가 생겼다.","⑤ 줄어들던 인구가 다시 늘기 시작했다."],"title":"어느 바닷가 마을 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#6','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',3,'ox','auto','공공 기관을 비수도권으로 옮기면 직원과 가족도 함께 옮겨 가 그 지역에 일자리와 인구가 늘 수 있어요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"ox","stem":"공공 기관을 비수도권으로 옮기면 직원과 가족도 함께 옮겨 가 그 지역에 일자리와 인구가 늘 수 있어요.","answer":"O","reason_options":[{"t":"기관과 함께 사람이 옮겨 가고 그곳에 일거리가 생기기 때문에","correct":true},{"t":"공공 기관은 사람 없이 건물만 옮기기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["사람도 함께 옮겨요.","일자리가 생겨요.","인구가 고르게 살도록 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#7','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',3,'error','auto','균형 발전 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"error","stem":"균형 발전 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「고향 사랑 기부제는 그 지역에서 태어난 사람만 할 수 있어.」","correct":true,"mis_target":"SO5-1-u2-X23"},{"t":"준서 — 「디지털 관광 주민증은 관광객도 주민처럼 혜택을 받게 해 줘.」","mis":"SO5-1-u2-X23"},{"t":"가온 — 「작은 학교 살리기는 학교가 다닐 만한 곳이 되게 해.」","mis":"SO5-1-u2-X23"}],"explanation":["고향뿐 아니라 관심 지역에도 해요.","태어난 곳이 아니어도 돼요.","태린의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#8','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',4,'mc','auto','「학생이 줄어 문을 닫는 학교가 늘어요」라는 문제에 세 잣대를 모두 지나는 방안으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C14","difficulty":4,"kind":"mc","stem":"「학생이 줄어 문을 닫는 학교가 늘어요」라는 문제에 세 잣대를 모두 지나는 방안으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 학교에 특별한 교육과정과 시설 개선을 지원한다","correct":true},{"t":"학생이 적은 학교는 모두 닫고 먼 학교로 다니게 한다","mis":"SO5-1-u2-X24"},{"t":"작은 학교로 전학 오지 않는 집에 벌을 준다","mis":"SO5-1-u2-X24"},{"t":"학생이 한 명뿐인 학교에도 선생님을 백 분씩 보낸다","mis":"SO5-1-u2-X24"}],"explanation":["닫으면 문제가 더 커져요.","벌주는 것은 옳지 않아요.","지나친 비용은 해내기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#9','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C13',4,'mc','auto','인구 분포의 불균형을 해결하는 노력을 가장 바르게 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X24']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C13","difficulty":4,"kind":"mc","stem":"인구 분포의 불균형을 해결하는 노력을 가장 바르게 정리한 것은 어느 것인가요?","options":[{"t":"정부와 지역, 주민이 함께 일자리와 살기 좋은 환경을 만들어 사람들이 고르게 살도록 돕는다","correct":true},{"t":"정부만 노력하면 되고 지역과 주민은 기다리면 된다","mis":"SO5-1-u2-X23"},{"t":"공공 기관을 수도권으로 더 모아야 불균형이 풀린다","mis":"SO5-1-u2-X23"},{"t":"사람들을 정해진 곳에 억지로 옮겨 살게 해야 한다","mis":"SO5-1-u2-X24"}],"explanation":["정부도 지역도 노력해요.","주민도 함께해요.","함께 잘 사는 국토예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L08_challenge#10','soc',5,1,'u2','L08','g5_1_soc_u2_L08_challenge','lesson_challenge','SO5-1-u2-C14',4,'essay','teacher','인구가 줄어드는 지역의 문제 하나를 골라 해결 방안을 한 가지 쓰고, 그 방안을 세 잣대(원인·옳음·실현)에 대어 평가하세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C14","difficulty":4,"kind":"essay","stem":"인구가 줄어드는 지역의 문제 하나를 골라 해결 방안을 한 가지 쓰고, 그 방안을 세 잣대(원인·옳음·실현)에 대어 평가하세요.","answer_guide":{"answer":"예: 상점과 병원이 줄어 생활이 불편한 문제를 골랐다. 방안은 물건을 싣고 마을을 찾아가는 이동형 상점을 지원하는 것이다. 상점이 없어 불편한 것이 원인이므로 물건이 찾아가면 원인 해결에 도움이 된다. 누구에게도 억지로 이사하게 하지 않으니 옳은 방안이다. 차 한 대로도 시작할 수 있어 비용과 노력을 생각할 때 실현할 수 있다.","scoring_points":["문제와 방안을 썼는가","원인·옳음·실현 세 잣대에 모두 대어 보았는가","각 잣대의 까닭을 썼는가"]},"explanation":["문제를 먼저 골라요.","세 잣대에 모두 대요.","까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#1','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'mc','auto','이 단원에서 공부한 내용을 동시로 표현할 때 주제로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"mc","stem":"이 단원에서 공부한 내용을 동시로 표현할 때 주제로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리 반이 좋아하는 급식 반찬","correct":true},{"t":"기후변화에 대응하는 기후 행동","mis":"SO5-1-u2-X26"},{"t":"자연재해에 대비하는 노력","mis":"SO5-1-u2-X26"},{"t":"우리나라 인구 분포의 불균형","mis":"SO5-1-u2-X26"}],"explanation":["단원에서 공부한 내용을 골라요.","기후·재해·인구가 있었어요.","급식 반찬은 공부한 내용이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#2','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'mc','auto','동시와 그림이 함께 있는 작품을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"mc","stem":"동시와 그림이 함께 있는 작품을 무엇이라고 하나요?","options":[{"t":"시화","correct":true},{"t":"만화","mis":"SO5-1-u2-X26"},{"t":"일기","mis":"SO5-1-u2-X26"},{"t":"신문","mis":"SO5-1-u2-X26"}],"explanation":["시와 그림이에요.","동시를 그림으로 꾸며요.","시화라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#3','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'sa','auto','동시를 소리 내어 읽을 때 느껴지는 가락을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"sa","stem":"동시를 소리 내어 읽을 때 느껴지는 가락을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["운율"],"explanation":["읽는 맛이에요.","비슷한 길이로 끊어 살려요.","운율이에요."],"mis":"SO5-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#4','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',1,'ox','auto','동시를 짓기 전에 먼저 주제에 대한 내 경험과 생각을 이야기로 써요.',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C15","difficulty":1,"kind":"ox","stem":"동시를 짓기 전에 먼저 주제에 대한 내 경험과 생각을 이야기로 써요.","answer":"O","reason_options":[{"t":"이야기가 있어야 그것을 줄여 동시로 지을 수 있기 때문에","correct":true},{"t":"동시는 이야기 없이 아무 말이나 늘어놓는 글이기 때문에","mis":"SO5-1-u2-X26"}],"mis":"SO5-1-u2-X26","explanation":["먼저 이야기를 써요.","이야기가 바탕이에요.","그다음 동시로 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#5','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','고른 주제를 이야기로 쓸 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"고른 주제를 이야기로 쓸 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"주제에 대한 내 생각과 경험, 공부한 내용이 잘 드러나게 쓴다","correct":true},{"t":"어려운 낱말을 되도록 많이 넣어 쓴다","mis":"SO5-1-u2-X26"},{"t":"친구가 쓴 이야기를 그대로 옮겨 쓴다","mis":"SO5-1-u2-X26"},{"t":"주제와 상관없는 재미있는 일만 쓴다","mis":"SO5-1-u2-X26"}],"explanation":["내 경험이 바탕이에요.","공부한 내용도 드러나요.","글의 순서도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#6','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','내가 쓴 이야기를 동시로 옮길 때 첫 줄로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"내가 쓴 이야기를 동시로 옮길 때 첫 줄로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구가 내게 준 노란 손수건","correct":true},{"t":"북극곰이 나에게 편지를 보내 왔다","mis":"SO5-1-u2-X26"},{"t":"오늘 급식은 참 맛있었다","mis":"SO5-1-u2-X26"},{"t":"손을 씻고 무심코 휴지를 뜯어 물기를 닦았는데 친구가 그것을 유심히 보았다","mis":"SO5-1-u2-X26"}],"explanation":["이야기에 나온 일이에요.","짧게 줄였어요.","기후 행동과 이어져요."],"asset":{"type":"passage","lines":["손을 씻고 무심코 휴지를 뜯어 물기를 닦았다.","친구가 노란 손수건을 건네며 기후변화를 막자고 했다.","기후 행동에 앞장서겠다던 다짐이 떠올라 부끄러웠다."],"title":"내가 쓴 이야기(주제 — 기후 행동)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#7','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','지은 동시를 다시 읽어 볼 때 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"지은 동시를 다시 읽어 볼 때 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"이야기로 쓴 내용이 잘 나타나도록 고칠 곳을 고친다","correct":true},{"t":"잘못된 곳이 있어도 처음 지은 대로 둔다","mis":"SO5-1-u2-X26"},{"t":"줄마다 글자 수가 같은지만 센다","mis":"SO5-1-u2-X26"},{"t":"친구의 동시와 똑같아지도록 고친다","mis":"SO5-1-u2-X26"}],"explanation":["다시 읽어 봐요.","고칠 곳만 고쳐요.","고치는 일까지가 동시 짓기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#8','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'mc','auto','동시와 어울리는 그림을 그릴 때 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"동시와 어울리는 그림을 그릴 때 알맞은 것은 어느 것인가요?","options":[{"t":"동시의 내용을 잘 나타내는 장면을 그린다","correct":true},{"t":"가장 좋아하는 색만 골라 칠한다","mis":"SO5-1-u2-X26"},{"t":"동시와 상관없어도 예쁜 그림을 그린다","mis":"SO5-1-u2-X26"},{"t":"글씨가 안 보이게 그림을 크게 그린다","mis":"SO5-1-u2-X26"}],"explanation":["그림은 동시를 보여 줘요.","동시가 말하는 장면이에요.","내용을 나타내게 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#9','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',2,'ox','auto','친구들과 시화를 바꿔 볼 때는 잘 지은 작품과 못 지은 작품을 가르는 데 힘써요.',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"ox","stem":"친구들과 시화를 바꿔 볼 때는 잘 지은 작품과 못 지은 작품을 가르는 데 힘써요.","answer":"X","reason_options":[{"t":"서로의 시화에서 좋은 점을 찾아 콕 집어 말해 주는 시간이기 때문에","correct":true},{"t":"시화는 점수를 매기려고 만드는 것이기 때문에","mis":"SO5-1-u2-X26"}],"mis":"SO5-1-u2-X26","explanation":["좋은 점을 찾아요.","무엇이 좋았는지 말해요.","가르는 시간이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_basic#10','soc',5,1,'u2','L09','g5_1_soc_u2_L09_basic','lesson_basic','SO5-1-u2-C15',3,'mc','auto','이야기를 동시로 옮길 때 한 줄로 쓰기에 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"이야기를 동시로 옮길 때 한 줄로 쓰기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"학교에서는 너무 많은 학생이 한꺼번에 운동장에서 놀다가 다치지 않도록 학년별로 요일을 정했다","correct":true},{"t":"학생이 너무 많아 우리 학교는 운동장 요일제","mis":"SO5-1-u2-X26"},{"t":"우리 학년은 목요일에만 쓸 수 있는 운동장","mis":"SO5-1-u2-X26"},{"t":"나는 목요일이 가장 좋다","mis":"SO5-1-u2-X26"}],"explanation":["동시는 짧게 줄여요.","긴 문장을 그대로 옮기면 안 돼요.","하고 싶은 말만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#1','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',2,'match','auto','동시를 짓는 차례에 맞게 순서와 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"match","stem":"동시를 짓는 차례에 맞게 순서와 할 일을 알맞게 이으세요.","pairs":[{"l":"첫째","r":"주제 고르기"},{"l":"둘째","r":"경험을 이야기로 쓰기"},{"l":"셋째","r":"줄여서 동시 짓기"},{"l":"넷째","r":"다시 읽고 고친 뒤 그림 그리기"}],"mis":"SO5-1-u2-X26","explanation":["주제를 먼저 골라요.","이야기로 쓰고 동시로 줄여요.","고친 뒤 그림을 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#2','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',2,'sa','auto','이야기를 동시로 옮길 때 하고 싶은 말만 남기고 어떻게 쓰나요? (□□ 줄여서 쓴다)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"sa","stem":"이야기를 동시로 옮길 때 하고 싶은 말만 남기고 어떻게 쓰나요? (□□ 줄여서 쓴다)","answer":["짧게"],"explanation":["이야기보다 훨씬 짧아요.","하고 싶은 말만 남겨요.","짧게 줄여 써요."],"mis":"SO5-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#3','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'mc','auto','내가 쓴 이야기로 지은 동시에 어울리는 그림은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"내가 쓴 이야기로 지은 동시에 어울리는 그림은 어느 것인가요?","options":[{"t":"친구에게 노란 손수건을 건네받는 장면","correct":true},{"t":"밤하늘에 별이 가득한 그림","mis":"SO5-1-u2-X26"},{"t":"공장 굴뚝에서 연기가 솟는 그림","mis":"SO5-1-u2-X26"},{"t":"바닷가에서 조개를 줍는 그림","mis":"SO5-1-u2-X26"}],"explanation":["동시의 한가운데 장면이에요.","손수건을 건네받았어요.","내용을 나타내는 장면을 그려요."],"asset":{"type":"passage","lines":["손을 씻고 무심코 휴지를 뜯어 물기를 닦았다.","친구가 노란 손수건을 건네며 기후변화를 막자고 했다.","기후 행동에 앞장서겠다던 다짐이 떠올라 부끄러웠다."],"title":"내가 쓴 이야기(주제 — 기후 행동)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#4','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'mc','auto','동시를 짓다가 내가 겪지 않은 일을 넣고 싶어졌어요. 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"동시를 짓다가 내가 겪지 않은 일을 넣고 싶어졌어요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"내 생각과 경험이 드러나도록 이야기에서 나온 내용으로 쓴다","correct":true},{"t":"더 재미있어 보이니 그대로 넣는다","mis":"SO5-1-u2-X26"},{"t":"친구의 경험을 내가 겪은 일처럼 쓴다","mis":"SO5-1-u2-X26"},{"t":"주제를 아예 다른 것으로 바꾼다","mis":"SO5-1-u2-X26"}],"explanation":["내 이야기가 바탕이에요.","겪지 않은 일은 내 이야기가 아니에요.","이야기에서 나온 내용으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#5','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'mc','auto','「긴급 재난 문자 덕분에 물이 찬 낮은 길을 피해 높은 길로 돌아온 일」로 동시를 지을 때, 함께 드러나는 공부한 내용은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"mc","stem":"「긴급 재난 문자 덕분에 물이 찬 낮은 길을 피해 높은 길로 돌아온 일」로 동시를 지을 때, 함께 드러나는 공부한 내용은 어느 것인가요?","options":[{"t":"자연재해에 대비하는 노력","correct":true},{"t":"인구 분포의 불균형","mis":"SO5-1-u2-X26"},{"t":"기후 행동","mis":"SO5-1-u2-X26"},{"t":"계절별 바람의 방향","mis":"SO5-1-u2-X26"}],"explanation":["긴급 재난 문자가 나와요.","위험을 미리 알렸어요.","자연재해 대비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#6','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'ox','auto','이 활동은 사회에서 배운 것을 국어(동시)와 미술(그림)로 이어 표현하는 창의·융합 활동이에요.',ARRAY['SO5-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"ox","stem":"이 활동은 사회에서 배운 것을 국어(동시)와 미술(그림)로 이어 표현하는 창의·융합 활동이에요.","answer":"O","reason_options":[{"t":"공부한 내용을 골라 동시와 그림으로 새롭게 바꾸기 때문에","correct":true},{"t":"배운 내용을 외워 그대로 적는 활동이기 때문에","mis":"SO5-1-u2-X25"}],"mis":"SO5-1-u2-X25","explanation":["사회 내용을 골라요.","동시와 그림으로 바꿔요.","세 과목이 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#7','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',3,'error','auto','동시 짓기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C15","difficulty":3,"kind":"error","stem":"동시 짓기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「동시는 한 번에 지어야 하니까 다 짓고 나면 고치지 않아.」","correct":true,"mis_target":"SO5-1-u2-X26"},{"t":"이준 — 「줄의 차례를 생각하며 흐름을 살려 써.」","mis":"SO5-1-u2-X26"},{"t":"채이 — 「공부한 내용이 드러나도록 주제를 살려 써.」","mis":"SO5-1-u2-X26"}],"explanation":["동시는 다시 읽고 고쳐요.","고칠수록 또렷해져요.","로아의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#8','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',4,'mc','auto','「운동장 요일제」 동시가 「인구 분포의 불균형」이라는 주제를 잘 드러내는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"mc","stem":"「운동장 요일제」 동시가 「인구 분포의 불균형」이라는 주제를 잘 드러내는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"수도권에 사람이 많이 모여 학생이 넘치는 내 경험으로 인구가 몰린 곳의 모습을 보여 주기 때문에","correct":true},{"t":"운동장이라는 낱말이 들어 있기 때문에","mis":"SO5-1-u2-X26"},{"t":"요일이 많이 나와 운율이 살기 때문에","mis":"SO5-1-u2-X26"},{"t":"인구 분포와 상관없이 재미있기 때문에","mis":"SO5-1-u2-X26"}],"explanation":["학생이 너무 많았어요.","사람이 몰린 수도권의 일이에요.","경험으로 주제를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#9','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',4,'mc','auto','좋은 시화를 가장 잘 설명한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X26','SO5-1-u2-X25']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"mc","stem":"좋은 시화를 가장 잘 설명한 것은 어느 것인가요?","options":[{"t":"공부한 내용과 내 경험이 담긴 짧은 동시에, 그 내용을 나타내는 장면을 그린 것","correct":true},{"t":"어려운 낱말이 많고 그림이 화려한 것","mis":"SO5-1-u2-X26"},{"t":"교과서 문장을 그대로 옮기고 아무 그림이나 그린 것","mis":"SO5-1-u2-X25"},{"t":"내가 겪지 않은 재미있는 일만 모은 것","mis":"SO5-1-u2-X26"}],"explanation":["공부한 내용이 담겨요.","내 경험이 담겨요.","그림이 동시를 보여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_L09_challenge#10','soc',5,1,'u2','L09','g5_1_soc_u2_L09_challenge','lesson_challenge','SO5-1-u2-C15',4,'essay','teacher','이 단원에서 공부한 내용 가운데 주제 하나를 골라, 그 주제와 관련한 내 경험을 두세 문장으로 쓰고 그것을 짧게 줄인 동시 세 줄과 그릴 장면을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"essay","stem":"이 단원에서 공부한 내용 가운데 주제 하나를 골라, 그 주제와 관련한 내 경험을 두세 문장으로 쓰고 그것을 짧게 줄인 동시 세 줄과 그릴 장면을 쓰세요.","answer_guide":{"answer":"예: 주제 — 기후변화에 대응하는 기후 행동. 경험 — 엄마와 마트에 갈 때 장바구니를 깜빡했다. 비닐봉지를 사려다가 기후 행동을 하겠다던 다짐이 떠올라 손으로 물건을 들고 왔다. 동시 — 깜빡 잊은 장바구니 / 두 손 가득 사과와 우유 / 무거워도 지구는 가볍게. 그릴 장면 — 두 손 가득 물건을 들고 웃으며 걷는 나.","scoring_points":["단원에서 공부한 주제를 골랐는가","내 경험을 이야기로 썼는가","짧게 줄인 동시와 내용에 맞는 장면을 썼는가"]},"explanation":["주제를 골라요.","내 경험을 써요.","짧게 줄이고 장면을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#1','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C1',1,'mc','auto','다온이 일기 ②에서 「며칠째 굵은 비가 쏟아졌다」는 것은 날씨와 기후 가운데 무엇에 대한 이야기인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"다온이 일기 ②에서 「며칠째 굵은 비가 쏟아졌다」는 것은 날씨와 기후 가운데 무엇에 대한 이야기인가요?","options":[{"t":"날씨","correct":true},{"t":"기후","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"인구","mis":"SO5-1-u2-X02"}],"explanation":["며칠 동안의 일이에요.","짧은 시간의 대기 상태예요.","날씨예요."],"asset":{"type":"passage","lines":["7월 — 며칠째 굵은 비가 쏟아졌다. 하천 물이 불어 낮은 길이 잠겼다.","집에 오는 길에 휴대 전화로 긴급 재난 문자가 왔다.","물이 찬 길로 다니지 말라는 안내를 보고 높은 길로 돌아왔다."],"title":"다온이 일기 ② 여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#2','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C3',1,'mc','auto','다온이 일기 ④의 겨울에 불어온 바람은 어디에서 왔나요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"다온이 일기 ④의 겨울에 불어온 바람은 어디에서 왔나요?","options":[{"t":"북서쪽 육지","correct":true},{"t":"남쪽 바다","mis":"SO5-1-u2-X04"},{"t":"동쪽 바다","mis":"SO5-1-u2-X04"},{"t":"남서쪽 바다","mis":"SO5-1-u2-X04"}],"explanation":["차고 건조한 바람이에요.","넓은 육지를 지나왔어요.","북서쪽 육지예요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#3','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C4',1,'mc','auto','우리나라에서 연 강수량의 절반 이상이 내리는 계절은 언제인가요?',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라에서 연 강수량의 절반 이상이 내리는 계절은 언제인가요?","options":[{"t":"여름","correct":true},{"t":"겨울","mis":"SO5-1-u2-X07"},{"t":"봄","mis":"SO5-1-u2-X07"},{"t":"가을","mis":"SO5-1-u2-X07"}],"explanation":["장맛비가 내려요.","7·8월에 몰려요.","여름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#4','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C5',1,'mc','auto','다온이 일기 ①에서 날아온 모래 먼지는 어떤 자연재해인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"다온이 일기 ①에서 날아온 모래 먼지는 어떤 자연재해인가요?","options":[{"t":"황사","correct":true},{"t":"폭설","mis":"SO5-1-u2-X09"},{"t":"한파","mis":"SO5-1-u2-X09"},{"t":"태풍","mis":"SO5-1-u2-X09"}],"explanation":["사막의 모래 먼지예요.","봄에 날아와요.","황사예요."],"asset":{"type":"passage","lines":["4월 — 아침 하늘이 누렇게 뿌옜다. 모래 먼지가 날아왔다고 했다.","엄마가 마스크를 꼭 쓰라고 하셨다.","할머니가 사는 솔내 마을은 몇 주째 비가 오지 않아 논바닥이 갈라졌다."],"title":"다온이 일기 ① 봄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#5','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C7',1,'mc','auto','다온이 일기 ⑤의 뉴스처럼 「여름이 점점 길어진다」는 것은 무엇 때문에 나타나는 변화인가요?',ARRAY['SO5-1-u2-X16','SO5-1-u2-X12','SO5-1-u2-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"다온이 일기 ⑤의 뉴스처럼 「여름이 점점 길어진다」는 것은 무엇 때문에 나타나는 변화인가요?","options":[{"t":"기후변화","correct":true},{"t":"인구 이동","mis":"SO5-1-u2-X16"},{"t":"지형 변화","mis":"SO5-1-u2-X12"},{"t":"하루의 날씨","mis":"SO5-1-u2-X01"}],"explanation":["기온이 꾸준히 올라요.","계절 길이가 달라져요.","기후변화 때문이에요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#6','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C9',1,'mc','auto','일정한 넓이(1 km²) 안에 사는 사람의 수를 나타내는 말은 어느 것인가요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"일정한 넓이(1 km²) 안에 사는 사람의 수를 나타내는 말은 어느 것인가요?","options":[{"t":"인구 밀도","correct":true},{"t":"인구","mis":"SO5-1-u2-X16"},{"t":"인구 분포","mis":"SO5-1-u2-X16"},{"t":"인구 구조","mis":"SO5-1-u2-X16"}],"explanation":["1 km² 안을 봐요.","빽빽한 정도예요.","인구 밀도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#7','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C10',1,'mc','auto','다온이네 한빛시가 있는 경기도는 어디에 속하나요?',ARRAY['SO5-1-u2-X20','SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"다온이네 한빛시가 있는 경기도는 어디에 속하나요?","options":[{"t":"수도권","correct":true},{"t":"비수도권","mis":"SO5-1-u2-X20"},{"t":"촌락","mis":"SO5-1-u2-X19"},{"t":"남서쪽 평야 지대","mis":"SO5-1-u2-X19"}],"explanation":["서울과 맞닿아 있어요.","서울·인천·경기예요.","수도권이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#8','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',1,'mc','auto','다온이 일기 ⑥에서 아빠 출근길 지하철이 꽉 차는 것은 어떤 문제인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"다온이 일기 ⑥에서 아빠 출근길 지하철이 꽉 차는 것은 어떤 문제인가요?","options":[{"t":"교통 혼잡","correct":true},{"t":"일손 부족","mis":"SO5-1-u2-X21"},{"t":"폐교","mis":"SO5-1-u2-X21"},{"t":"빈집 증가","mis":"SO5-1-u2-X21"}],"explanation":["사람이 너무 많아요.","지하철이 붐벼요.","교통 혼잡이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#9','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C2',2,'mc','auto','다온이 일기 ④에서 이모가 한겨울에 밭에서 무를 거둘 수 있는 것은 무엇의 영향인가요?',ARRAY['SO5-1-u2-X03','SO5-1-u2-X17','SO5-1-u2-X04']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"다온이 일기 ④에서 이모가 한겨울에 밭에서 무를 거둘 수 있는 것은 무엇의 영향인가요?","options":[{"t":"겨울에도 따뜻한 남쪽의 기후","correct":true},{"t":"그날 하루의 맑은 날씨","mis":"SO5-1-u2-X03"},{"t":"이모네 마을의 인구","mis":"SO5-1-u2-X17"},{"t":"북서쪽에서 부는 차가운 바람","mis":"SO5-1-u2-X04"}],"explanation":["남쪽 섬은 겨울에도 따뜻해요.","해마다 되풀이돼요.","기후의 영향이에요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#10','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C6',2,'mc','auto','다온이 일기 ②에서 다온이가 높은 길로 돌아올 수 있었던 것은 어떤 노력 덕분인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X15','SO5-1-u2-X11']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"mc","stem":"다온이 일기 ②에서 다온이가 높은 길로 돌아올 수 있었던 것은 어떤 노력 덕분인가요?","options":[{"t":"긴급 재난 문자로 미리 위험을 알린 노력","correct":true},{"t":"사람들을 수도권으로 옮긴 노력","mis":"SO5-1-u2-X23"},{"t":"기후 행동 수첩을 쓴 노력","mis":"SO5-1-u2-X15"},{"t":"하천 물길을 함부로 바꾼 일","mis":"SO5-1-u2-X11"}],"explanation":["휴대 전화로 문자가 왔어요.","물이 찬 길을 알렸어요.","미리 알리는 노력이에요."],"asset":{"type":"passage","lines":["7월 — 며칠째 굵은 비가 쏟아졌다. 하천 물이 불어 낮은 길이 잠겼다.","집에 오는 길에 휴대 전화로 긴급 재난 문자가 왔다.","물이 찬 길로 다니지 말라는 안내를 보고 높은 길로 돌아왔다."],"title":"다온이 일기 ② 여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#11','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C8',2,'mc','auto','다온이 일기 ⑤의 수첩에 적힌 일은 어떤 주체의 기후 행동인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑤의 수첩에 적힌 일은 어떤 주체의 기후 행동인가요?","options":[{"t":"개인","correct":true},{"t":"기업","mis":"SO5-1-u2-X14"},{"t":"정부와 국회","mis":"SO5-1-u2-X14"},{"t":"세계 여러 나라","mis":"SO5-1-u2-X14"}],"explanation":["다온이가 매일 해요.","손수건과 걷기예요.","개인의 기후 행동이에요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#12','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C9',2,'mc','auto','다온이 일기 ⑦에서 젊은 사람들이 도시로 떠난 까닭과 가장 가까운 환경은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦에서 젊은 사람들이 도시로 떠난 까닭과 가장 가까운 환경은 어느 것인가요?","options":[{"t":"일자리 같은 인문환경","correct":true},{"t":"기후 같은 자연환경","mis":"SO5-1-u2-X17"},{"t":"지형 같은 자연환경","mis":"SO5-1-u2-X17"},{"t":"하천 같은 자연환경","mis":"SO5-1-u2-X17"}],"explanation":["도시에는 일할 곳이 많아요.","사람이 만든 환경이에요.","인문환경이에요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#13','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C11',2,'mc','auto','다온이 일기 ⑦의 솔내 마을처럼 젊은 사람이 떠난 곳은 어떤 인구층의 비율이 높아지기 쉬운가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦의 솔내 마을처럼 젊은 사람이 떠난 곳은 어떤 인구층의 비율이 높아지기 쉬운가요?","options":[{"t":"노년층","correct":true},{"t":"청장년층","mis":"SO5-1-u2-X20"},{"t":"유소년층","mis":"SO5-1-u2-X20"},{"t":"세 층이 모두 같아진다","mis":"SO5-1-u2-X20"}],"explanation":["젊은 사람이 떠났어요.","어르신이 많이 남아요.","노년층 비율이 높아요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#14','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',2,'mc','auto','다온이 일기 ⑦에서 마을 가게가 문을 닫아 채소를 사기 어려워진 지역을 무엇이라고 부르나요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X20']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦에서 마을 가게가 문을 닫아 채소를 사기 어려워진 지역을 무엇이라고 부르나요?","options":[{"t":"식품 사막","correct":true},{"t":"혁신 도시","mis":"SO5-1-u2-X23"},{"t":"수도권","mis":"SO5-1-u2-X20"},{"t":"지질 공원","mis":"SO5-1-u2-X23"}],"explanation":["신선 식품을 구하기 어려워요.","가게가 문을 닫았어요.","식품 사막이에요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#15','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C13',2,'mc','auto','다온이 일기 ⑧에서 엄마가 한 일은 어떤 제도인가요?',ARRAY['SO5-1-u2-X23','SO5-1-u2-X10']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑧에서 엄마가 한 일은 어떤 제도인가요?","options":[{"t":"고향 사랑 기부제","correct":true},{"t":"디지털 관광 주민증","mis":"SO5-1-u2-X23"},{"t":"공공 기관 이전","mis":"SO5-1-u2-X23"},{"t":"기상 특보","mis":"SO5-1-u2-X10"}],"explanation":["고향에 기부했어요.","답례품으로 쌀을 받았어요.","고향 사랑 기부제예요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#16','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C14',2,'mc','auto','해결 방안을 평가하는 세 잣대가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"mc","stem":"해결 방안을 평가하는 세 잣대가 아닌 것은 어느 것인가요?","options":[{"t":"방안 이름이 멋지게 들리는가","correct":true},{"t":"문제의 원인을 해결하는 데 도움이 되는가","mis":"SO5-1-u2-X24"},{"t":"도덕적으로 옳은가","mis":"SO5-1-u2-X24"},{"t":"비용과 노력을 생각할 때 실현할 수 있는가","mis":"SO5-1-u2-X24"}],"explanation":["잣대는 원인·옳음·실현이에요.","이름은 잣대가 아니에요.","셋을 모두 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#17','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C3',3,'mc','auto','다온이 일기 ④에서 다온이네는 몹시 추웠고 남쪽 섬은 밭일을 할 만큼 따뜻했어요. 이것과 같은 까닭으로 설명할 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X05','SO5-1-u2-X07']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"mc","stem":"다온이 일기 ④에서 다온이네는 몹시 추웠고 남쪽 섬은 밭일을 할 만큼 따뜻했어요. 이것과 같은 까닭으로 설명할 수 있는 것은 어느 것인가요?","options":[{"t":"남북의 기온 차이가 여름보다 겨울에 훨씬 크다","correct":true},{"t":"여름에 남북의 기온 차이가 가장 크다","mis":"SO5-1-u2-X05"},{"t":"남쪽으로 갈수록 기온이 낮아진다","mis":"SO5-1-u2-X05"},{"t":"겨울에 강수량이 가장 많다","mis":"SO5-1-u2-X07"}],"explanation":["겨울엔 북쪽이 크게 추워요.","남쪽은 덜 추워요.","그래서 차이가 커요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#18','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C5',3,'mc','auto','다온이 일기 ①~④에 나온 자연재해를 계절 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"mc","stem":"다온이 일기 ①~④에 나온 자연재해를 계절 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"황사·가뭄 → 호우·홍수 → 태풍 → 한파","correct":true},{"t":"한파 → 태풍 → 호우·홍수 → 황사·가뭄","mis":"SO5-1-u2-X09"},{"t":"태풍 → 황사·가뭄 → 한파 → 호우·홍수","mis":"SO5-1-u2-X09"},{"t":"호우·홍수 → 한파 → 황사·가뭄 → 태풍","mis":"SO5-1-u2-X09"}],"explanation":["①은 4월, ②는 7월이에요.","③은 9월 초, ④는 1월이에요.","계절 차례로 놓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#19','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C7',3,'mc','auto','다온이 일기 ⑤의 뉴스에 나온 「역대 가장 긴 폭염」이 자주 들리는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X13','SO5-1-u2-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑤의 뉴스에 나온 「역대 가장 긴 폭염」이 자주 들리는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기후변화로 자연재해가 더 잦아지고 강해졌기 때문에","correct":true},{"t":"그해에만 우연히 더웠기 때문에","mis":"SO5-1-u2-X13"},{"t":"겨울이 점점 길어지기 때문에","mis":"SO5-1-u2-X12"},{"t":"사람들이 숲을 많이 가꾸었기 때문에","mis":"SO5-1-u2-X12"}],"explanation":["「역대」가 자주 나와요.","재해가 더 세졌어요.","기후변화의 영향이에요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#20','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C10',3,'mc','auto','다온이 일기 ⑥과 ⑦을 견줄 때 두 곳의 인구 분포를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X18','SO5-1-u2-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑥과 ⑦을 견줄 때 두 곳의 인구 분포를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"한빛시는 사람이 몰려 인구 밀도가 높고, 솔내 마을은 사람이 줄어 인구 밀도가 낮다","correct":true},{"t":"두 곳 모두 사람이 몰려 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"솔내 마을이 한빛시보다 인구 밀도가 높다","mis":"SO5-1-u2-X18"},{"t":"두 곳의 인구 분포는 견줄 수 없다","mis":"SO5-1-u2-X16"}],"explanation":["한빛시는 지하철이 꽉 차요.","솔내 마을은 사람이 떠났어요.","밀도가 서로 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#21','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',3,'mc','auto','다온이 일기 ⑥과 ⑦에 나온 일이 계속 되풀이된다면 나라 전체에 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑥과 ⑦에 나온 일이 계속 되풀이된다면 나라 전체에 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 격차가 커져 국가 경쟁력이 떨어질 수 있다","correct":true},{"t":"두 지역의 인구가 저절로 비슷해진다","mis":"SO5-1-u2-X22"},{"t":"수도권만 좋아지고 나라 전체에는 문제가 없다","mis":"SO5-1-u2-X22"},{"t":"솔내 마을에 사람이 저절로 돌아온다","mis":"SO5-1-u2-X22"}],"explanation":["한빛시는 더 붐벼요.","솔내는 더 비어요.","격차가 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#22','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C13',3,'mc','auto','다온이 일기 ⑧의 햇빛 발전 사업이 솔내 마을에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X24','SO5-1-u2-X23']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑧의 햇빛 발전 사업이 솔내 마을에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주민이 직접 참여해 소득이 늘면 지역 경제가 살아나 사람이 모일 수 있기 때문에","correct":true},{"t":"사람들을 억지로 마을로 옮겨 오게 하기 때문에","mis":"SO5-1-u2-X24"},{"t":"마을 학교를 닫게 하기 때문에","mis":"SO5-1-u2-X23"},{"t":"수도권에 사람을 더 모으기 때문에","mis":"SO5-1-u2-X23"}],"explanation":["주민이 참여했어요.","수익을 나누었어요.","경제가 살아나요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#23','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C1',4,'mc','auto','「우리나라 지리 탐구」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X01','SO5-1-u2-X25']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C1","difficulty":4,"kind":"mc","stem":"「우리나라 지리 탐구」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"우리나라는 계절마다 기후가 달라 계절별 자연재해가 생기고 기후변화로 심해지며, 인구는 수도권에 몰려 불균형 문제를 함께 풀어 가야 한다","correct":true},{"t":"우리나라는 계절이 바뀌어도 기후가 같고 인구는 전국에 고르게 퍼져 있다","mis":"SO5-1-u2-X04"},{"t":"기후는 매일 바뀌고 인구 문제는 수도권에만 있다","mis":"SO5-1-u2-X01"},{"t":"기후변화와 인구 문제는 수치와 연도만 외우면 된다","mis":"SO5-1-u2-X25"}],"explanation":["계절별 기후와 재해예요.","기후변화로 심해져요.","인구 불균형을 함께 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#24','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C3',4,'essay','teacher','다온이 일기 ②와 ④를 보고 여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 때문에 두 계절의 기온과 강수가 어떻게 다른지, 그리고 남북 기온 차이가 어느 계절에 더 큰지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C3","difficulty":4,"kind":"essay","stem":"다온이 일기 ②와 ④를 보고 여름과 겨울에 불어오는 바람의 방향과 성질을 쓰고, 그 때문에 두 계절의 기온과 강수가 어떻게 다른지, 그리고 남북 기온 차이가 어느 계절에 더 큰지 쓰세요.","answer_guide":{"answer":"예: 여름에는 남쪽 바다에서 뜨겁고 습한 바람이 불어와 기온이 높고 일기 ②처럼 비가 많이 내린다. 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어와 기온이 낮고 강수가 적다. 남북의 기온 차이는 겨울에 더 커서 일기 ④처럼 다온이네가 추운 날에도 남쪽 섬에서는 밭일을 할 수 있다.","scoring_points":["두 계절 바람의 방향과 성질을 썼는가","바람과 기온·강수를 이어 썼는가","남북 기온 차이가 겨울에 더 크다고 썼는가"]},"explanation":["여름 — 남쪽 바다예요.","겨울 — 북서쪽 육지예요.","남북 차이는 겨울에 커요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_a#25','soc',5,1,'u2','','g5_1_soc_u2_review_a','unit_review','SO5-1-u2-C12',4,'essay','teacher','다온이 일기 ⑥과 ⑦에 나온 문제를 수도권과 비수도권으로 나누어 각각 두 가지씩 쓰고, 이 문제들이 되풀이되면 어떤 일이 생기는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑥과 ⑦에 나온 문제를 수도권과 비수도권으로 나누어 각각 두 가지씩 쓰고, 이 문제들이 되풀이되면 어떤 일이 생기는지 쓰세요.","answer_guide":{"answer":"예: 수도권인 한빛시에서는 지하철이 꽉 차는 교통 혼잡과 집값이 오르는 주택 문제가 있다. 비수도권인 솔내 마을에서는 신입생이 없는 학교와 가게가 문을 닫아 채소를 사기 어려운 문제가 있다. 사람이 몰리는 곳은 더 몰리고 떠나는 곳은 더 떠나는 일이 되풀이되면 지역 격차가 커지고 국가 경쟁력이 떨어질 수 있다.","scoring_points":["수도권의 문제를 두 가지 썼는가","비수도권의 문제를 두 가지 썼는가","되풀이될 때의 결과를 썼는가"]},"explanation":["몰린 곳의 문제예요.","빈 곳의 문제예요.","격차가 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#1','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C1',1,'sa','auto','오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"sa","stem":"오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기후"],"explanation":["여러 해를 모아요.","평균적인 모습이에요.","기후예요."],"mis":"SO5-1-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#2','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C3',1,'mc','auto','여름에 남쪽 바다에서 불어오는 바람의 성질은 어느 것인가요?',ARRAY['SO5-1-u2-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"mc","stem":"여름에 남쪽 바다에서 불어오는 바람의 성질은 어느 것인가요?","options":[{"t":"뜨겁고 습하다","correct":true},{"t":"차갑고 건조하다","mis":"SO5-1-u2-X04"},{"t":"차갑고 습하다","mis":"SO5-1-u2-X04"},{"t":"뜨겁고 건조하다","mis":"SO5-1-u2-X04"}],"explanation":["바다를 지나와요.","물기를 많이 머금어요.","뜨겁고 습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#3','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C4',1,'mc','auto','우리나라의 연 강수량은 대체로 어느 쪽으로 갈수록 많아지나요?',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"mc","stem":"우리나라의 연 강수량은 대체로 어느 쪽으로 갈수록 많아지나요?","options":[{"t":"남쪽","correct":true},{"t":"북쪽","mis":"SO5-1-u2-X07"},{"t":"어디나 같다","mis":"SO5-1-u2-X07"},{"t":"동쪽에서만","mis":"SO5-1-u2-X07"}],"explanation":["제주가 서울보다 많아요.","서울이 중강진보다 많아요.","남쪽으로 갈수록 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#4','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C5',1,'mc','auto','다온이 일기 ①에서 솔내 마을의 논바닥이 갈라진 것은 어떤 자연재해 때문인가요?',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"mc","stem":"다온이 일기 ①에서 솔내 마을의 논바닥이 갈라진 것은 어떤 자연재해 때문인가요?","options":[{"t":"가뭄","correct":true},{"t":"홍수","mis":"SO5-1-u2-X09"},{"t":"호우","mis":"SO5-1-u2-X09"},{"t":"폭설","mis":"SO5-1-u2-X09"}],"explanation":["비가 몇 주째 오지 않았어요.","물이 말랐어요.","가뭄이에요."],"asset":{"type":"passage","lines":["4월 — 아침 하늘이 누렇게 뿌옜다. 모래 먼지가 날아왔다고 했다.","엄마가 마스크를 꼭 쓰라고 하셨다.","할머니가 사는 솔내 마을은 몇 주째 비가 오지 않아 논바닥이 갈라졌다."],"title":"다온이 일기 ① 봄"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#5','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C7',1,'mc','auto','기후변화로 우리나라의 겨울은 어떻게 달라지고 있나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"mc","stem":"기후변화로 우리나라의 겨울은 어떻게 달라지고 있나요?","options":[{"t":"짧아지고 있다","correct":true},{"t":"길어지고 있다","mis":"SO5-1-u2-X12"},{"t":"그대로이다","mis":"SO5-1-u2-X12"},{"t":"여름보다 길어지고 있다","mis":"SO5-1-u2-X12"}],"explanation":["여름은 길어져요.","겨울은 짧아져요.","22일쯤 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#6','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C9',1,'mc','auto','인구가 모이거나 흩어져 있는 정도를 나타내는 말은 어느 것인가요?',ARRAY['SO5-1-u2-X16']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"mc","stem":"인구가 모이거나 흩어져 있는 정도를 나타내는 말은 어느 것인가요?","options":[{"t":"인구 분포","correct":true},{"t":"인구","mis":"SO5-1-u2-X16"},{"t":"인구 밀도","mis":"SO5-1-u2-X16"},{"t":"순이동","mis":"SO5-1-u2-X16"}],"explanation":["퍼져 있는 모양이에요.","모였는지 흩어졌는지 봐요.","인구 분포예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#7','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C10',1,'mc','auto','오늘날 우리나라 인구의 절반 정도가 모여 사는 곳은 어디인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"오늘날 우리나라 인구의 절반 정도가 모여 사는 곳은 어디인가요?","options":[{"t":"수도권","correct":true},{"t":"남서쪽 평야 지대","mis":"SO5-1-u2-X19"},{"t":"북동쪽 산지","mis":"SO5-1-u2-X19"},{"t":"바닷가 작은 섬","mis":"SO5-1-u2-X19"}],"explanation":["일자리가 많은 곳이에요.","서울 둘레예요.","수도권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#8','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C12',1,'mc','auto','다온이 일기 ⑦에서 1학년 신입생이 한 명도 없는 학교가 생긴 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"mc","stem":"다온이 일기 ⑦에서 1학년 신입생이 한 명도 없는 학교가 생긴 까닭은 어느 것인가요?","options":[{"t":"마을의 인구가 줄었기 때문에","correct":true},{"t":"마을의 인구가 너무 많기 때문에","mis":"SO5-1-u2-X21"},{"t":"마을에 학교가 새로 많이 생겼기 때문에","mis":"SO5-1-u2-X21"},{"t":"마을의 기후가 바뀌었기 때문에","mis":"SO5-1-u2-X22"}],"explanation":["젊은 사람이 떠났어요.","아이도 줄었어요.","그래서 신입생이 없어요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#9','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C2',2,'mc','auto','기후가 산업에 준 영향으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X03','SO5-1-u2-X17']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"기후가 산업에 준 영향으로 알맞은 것은 어느 것인가요?","options":[{"t":"바람이 센 곳에 바람으로 전기를 만드는 시설이 생겼다","correct":true},{"t":"하루 비가 와서 축구 경기가 미뤄졌다","mis":"SO5-1-u2-X03"},{"t":"사람이 많은 도시에 지하철이 생겼다","mis":"SO5-1-u2-X17"},{"t":"산이 많은 곳에 터널을 뚫었다","mis":"SO5-1-u2-X03"}],"explanation":["바람이 늘 세요.","그 힘을 이용해요.","기후가 산업을 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#10','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C6',2,'mc','auto','다온이 일기 ③에서 아빠와 다온이가 한 일로 알맞은 설명은 어느 것인가요?',ARRAY['SO5-1-u2-X10','SO5-1-u2-X09']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"mc","stem":"다온이 일기 ③에서 아빠와 다온이가 한 일로 알맞은 설명은 어느 것인가요?","options":[{"t":"태풍 때의 국민 행동 요령을 실천했다","correct":true},{"t":"기상 특보를 무시하고 평소처럼 지냈다","mis":"SO5-1-u2-X10"},{"t":"한파에 대비해 수도관을 감쌌다","mis":"SO5-1-u2-X09"},{"t":"황사에 대비해 마스크를 썼다","mis":"SO5-1-u2-X09"}],"explanation":["날아갈 물건을 들여놓았어요.","밖에 나가지 않았어요.","태풍 행동 요령이에요."],"asset":{"type":"passage","lines":["9월 초 — 남서쪽에서 태풍이 올라온다며 태풍 주의보가 내려졌다.","아빠와 베란다의 화분과 빨래 건조대를 안으로 들여놓았다.","그날은 밖에 나가지 않고 집에서 보냈다."],"title":"다온이 일기 ③ 늦여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#11','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C8',2,'mc','auto','다온이 일기 ⑤에서 손수건을 깜빡한 날 다온이가 한 일로 가장 알맞은 설명은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑤에서 손수건을 깜빡한 날 다온이가 한 일로 가장 알맞은 설명은 어느 것인가요?","options":[{"t":"까닭을 돌아보고 다시 실천할 방법을 찾았다","correct":true},{"t":"그 행동을 수첩에서 지웠다","mis":"SO5-1-u2-X15"},{"t":"기후 행동을 그만두었다","mis":"SO5-1-u2-X14"},{"t":"다른 사람에게 대신 하라고 했다","mis":"SO5-1-u2-X14"}],"explanation":["△를 표시했어요.","왜 잊었는지 생각했어요.","손수건을 하나 더 챙겼어요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#12','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C9',2,'mc','auto','인구 분포에 영향을 주는 자연환경끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"mc","stem":"인구 분포에 영향을 주는 자연환경끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"기후·지형","correct":true},{"t":"일자리·교통","mis":"SO5-1-u2-X17"},{"t":"교육·교통","mis":"SO5-1-u2-X17"},{"t":"지형·일자리","mis":"SO5-1-u2-X17"}],"explanation":["자연이 만든 환경이에요.","날씨와 땅의 생김새예요.","기후·지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#13','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C11',2,'mc','auto','청장년층에 해당하는 나이는 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"mc","stem":"청장년층에 해당하는 나이는 어느 것인가요?","options":[{"t":"15~64세","correct":true},{"t":"14세 이하","mis":"SO5-1-u2-X20"},{"t":"65세 이상","mis":"SO5-1-u2-X20"},{"t":"10세 이하","mis":"SO5-1-u2-X20"}],"explanation":["일하는 나이예요.","15세부터 64세까지예요.","청장년층이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#14','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C12',2,'mc','auto','다온이 일기 ⑦에 나온 문제 가운데 청장년층이 빠져나가 생긴 문제는 어느 것인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑦에 나온 문제 가운데 청장년층이 빠져나가 생긴 문제는 어느 것인가요?","options":[{"t":"농사일을 도울 사람이 부족하다","correct":true},{"t":"지하철이 꽉 찬다","mis":"SO5-1-u2-X21"},{"t":"집값이 많이 오른다","mis":"SO5-1-u2-X21"},{"t":"운동장 쓰는 요일이 정해져 있다","mis":"SO5-1-u2-X21"}],"explanation":["젊은 사람이 떠났어요.","일할 사람이 줄었어요.","일손 부족이에요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#15','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C13',2,'mc','auto','다온이 일기 ⑧에서 도시 청년들이 솔내 마을에 머물며 살아 보게 돕는 노력은 어느 것인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑧에서 도시 청년들이 솔내 마을에 머물며 살아 보게 돕는 노력은 어느 것인가요?","options":[{"t":"청년 마을 만들기","correct":true},{"t":"로컬 브랜딩","mis":"SO5-1-u2-X23"},{"t":"작은 학교 살리기","mis":"SO5-1-u2-X23"},{"t":"공공 기관 이전","mis":"SO5-1-u2-X23"}],"explanation":["청년이 머물러요.","살아 보게 도와요.","청년 마을 만들기예요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#16','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C15',2,'mc','auto','다온이 일기 ⑧에서 다온이가 동시를 지으려면 먼저 해야 할 일은 어느 것인가요?',ARRAY['SO5-1-u2-X26','SO5-1-u2-X25']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"mc","stem":"다온이 일기 ⑧에서 다온이가 동시를 지으려면 먼저 해야 할 일은 어느 것인가요?","options":[{"t":"솔내 마을 이야기에서 내 경험과 생각을 이야기로 정리한다","correct":true},{"t":"그림부터 크게 그린다","mis":"SO5-1-u2-X26"},{"t":"친구의 동시를 그대로 베낀다","mis":"SO5-1-u2-X26"},{"t":"어려운 낱말 목록을 외운다","mis":"SO5-1-u2-X25"}],"explanation":["주제를 골랐어요.","이야기로 먼저 써요.","그다음 동시로 줄여요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#17','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C4',3,'mc','auto','다온이 일기 ②의 굵은 비와 ④의 차고 건조한 바람을 함께 볼 때 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X07']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"mc","stem":"다온이 일기 ②의 굵은 비와 ④의 차고 건조한 바람을 함께 볼 때 알 수 있는 것은 어느 것인가요?","options":[{"t":"여름에는 습한 바다 바람으로 비가 많고 겨울에는 건조한 육지 바람으로 강수가 적다","correct":true},{"t":"여름과 겨울 모두 바다 바람이 분다","mis":"SO5-1-u2-X04"},{"t":"겨울에 비가 가장 많이 내린다","mis":"SO5-1-u2-X07"},{"t":"바람과 강수는 서로 관계없다","mis":"SO5-1-u2-X04"}],"explanation":["여름 바람은 습해요.","겨울 바람은 건조해요.","그래서 강수가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#18','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C6',3,'mc','auto','다온이 일기 ②와 ③을 함께 볼 때 자연재해에 대한 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X10','SO5-1-u2-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"mc","stem":"다온이 일기 ②와 ③을 함께 볼 때 자연재해에 대한 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자연재해는 막을 수 없지만 미리 알리는 정보와 행동 요령으로 피해를 줄일 수 있다","correct":true},{"t":"자연재해는 미리 알 수 없으니 대비할 필요가 없다","mis":"SO5-1-u2-X10"},{"t":"자연재해 대비는 어른만 하면 된다","mis":"SO5-1-u2-X10"},{"t":"비와 바람은 언제나 자연재해이다","mis":"SO5-1-u2-X08"}],"explanation":["문자와 특보가 미리 알렸어요.","다온이도 행동했어요.","피해를 줄였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#19','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C8',3,'mc','auto','다온이 일기 ⑤의 수첩에 하나를 더 적는다면 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑤의 수첩에 하나를 더 적는다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"빈 교실과 화장실의 전등 끄기","correct":true},{"t":"기후변화를 막는 법 만들기","mis":"SO5-1-u2-X15"},{"t":"공장의 오염 물질 줄이는 기술 개발하기","mis":"SO5-1-u2-X15"},{"t":"가까운 거리도 자가용으로 다니기","mis":"SO5-1-u2-X14"}],"explanation":["내가 매일 할 수 있는 일이에요.","법은 국회, 기술은 기업이에요.","전등 끄기가 알맞아요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#20','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C9',3,'mc','auto','넓이가 같은 두 마을 가운데 ㉮ 마을에는 1,000명, ㉯ 마을에는 100명이 살아요. 알맞은 설명은 어느 것인가요?',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C9","difficulty":3,"kind":"mc","stem":"넓이가 같은 두 마을 가운데 ㉮ 마을에는 1,000명, ㉯ 마을에는 100명이 살아요. 알맞은 설명은 어느 것인가요?","options":[{"t":"㉮ 마을의 인구 밀도가 더 높다","correct":true},{"t":"㉯ 마을의 인구 밀도가 더 높다","mis":"SO5-1-u2-X18"},{"t":"두 마을의 인구 밀도는 같다","mis":"SO5-1-u2-X18"},{"t":"넓이가 같으면 인구 밀도를 견줄 수 없다","mis":"SO5-1-u2-X18"}],"explanation":["넓이가 같아요.","㉮에 사람이 더 많아요.","㉮가 더 빽빽해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#21','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C12',3,'mc','auto','다온이 일기 ⑦에서 가게가 문을 닫은 뒤 생기기 쉬운 일을 바르게 이은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X21','SO5-1-u2-X22']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"mc","stem":"다온이 일기 ⑦에서 가게가 문을 닫은 뒤 생기기 쉬운 일을 바르게 이은 것은 어느 것인가요?","options":[{"t":"생활이 불편해짐 → 사람들이 더 떠남 → 시설이 더 줄어듦","correct":true},{"t":"생활이 편해짐 → 사람이 더 모임 → 시설이 늘어남","mis":"SO5-1-u2-X21"},{"t":"가게가 닫힘 → 집값이 오름 → 교통이 붐빔","mis":"SO5-1-u2-X21"},{"t":"가게가 닫힘 → 아무 일도 없음 → 인구가 그대로","mis":"SO5-1-u2-X22"}],"explanation":["불편하면 떠나요.","떠나면 시설이 더 줄어요.","고리가 되풀이돼요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#22','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C14',3,'mc','auto','솔내 마을의 「농사일을 도울 사람이 부족하다」는 문제에 세 잣대를 모두 지나는 방안은 어느 것인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"mc","stem":"솔내 마을의 「농사일을 도울 사람이 부족하다」는 문제에 세 잣대를 모두 지나는 방안은 어느 것인가요?","options":[{"t":"농촌에서 일하고 살아 보려는 청년에게 집과 일거리를 연결해 준다","correct":true},{"t":"도시 청년을 억지로 마을에 보내 농사짓게 한다","mis":"SO5-1-u2-X24"},{"t":"마을마다 큰 공장을 열 개씩 새로 짓는다","mis":"SO5-1-u2-X24"},{"t":"도시 회사에 다니는 청년에게 상을 준다","mis":"SO5-1-u2-X24"}],"explanation":["억지로 보내면 옳지 않아요.","공장 열 개는 비용이 지나쳐요.","상은 원인과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#23','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C7',4,'mc','auto','다온이 일기 ①~⑤를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X09','SO5-1-u2-X13','SO5-1-u2-X14']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C7","difficulty":4,"kind":"mc","stem":"다온이 일기 ①~⑤를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"계절마다 다른 자연재해에 대비하는 동시에, 재해를 키우는 기후변화를 막는 기후 행동도 함께 해야 한다","correct":true},{"t":"자연재해는 겨울에만 생기므로 겨울에만 대비하면 된다","mis":"SO5-1-u2-X09"},{"t":"기후변화와 자연재해는 서로 관계가 없다","mis":"SO5-1-u2-X13"},{"t":"기후 행동은 어른과 기업만 하면 된다","mis":"SO5-1-u2-X14"}],"explanation":["①~④는 계절별 재해예요.","⑤는 기후 행동이에요.","대비와 막기를 함께 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#24','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C6',4,'essay','teacher','다온이 일기 ①~③에 나온 자연재해를 계절과 함께 쓰고, 그 가운데 하나를 골라 피해를 줄이려고 나라가 하는 일과 내가 할 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C6","difficulty":4,"kind":"essay","stem":"다온이 일기 ①~③에 나온 자연재해를 계절과 함께 쓰고, 그 가운데 하나를 골라 피해를 줄이려고 나라가 하는 일과 내가 할 일을 쓰세요.","answer_guide":{"answer":"예: 봄에는 황사와 가뭄, 여름에는 호우와 홍수, 늦여름에는 태풍이 있었다. 호우와 홍수에 대비해 나라는 제방을 쌓고 기상 특보와 긴급 재난 문자로 미리 알린다. 나는 특보나 문자를 확인하고 물이 찬 낮은 길로 다니지 않고 높은 곳으로 피하겠다.","scoring_points":["자연재해와 계절을 바르게 썼는가","나라가 하는 대비 노력을 썼는가","내가 할 행동 요령을 썼는가"]},"explanation":["계절별 재해를 써요.","시설과 특보가 있어요.","나도 행동 요령을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_b#25','soc',5,1,'u2','','g5_1_soc_u2_review_b','unit_review','SO5-1-u2-C13',4,'essay','teacher','다온이 일기 ⑧에 나온 솔내 마을의 노력 세 가지를 쓰고, 그 가운데 하나가 인구 분포의 불균형을 줄이는 데 어떻게 도움이 되는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C13","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑧에 나온 솔내 마을의 노력 세 가지를 쓰고, 그 가운데 하나가 인구 분포의 불균형을 줄이는 데 어떻게 도움이 되는지 쓰세요.","answer_guide":{"answer":"예: 솔내 마을의 노력은 주민이 참여하는 햇빛 발전 사업, 청년 마을, 고향 사랑 기부이다. 햇빛 발전 사업은 주민이 직접 참여해 수익을 나누므로 소득이 늘고 지역 경제가 활발해져 새로운 일거리가 생기고, 그래서 사람들이 마을에 머물거나 다시 모여 불균형을 줄이는 데 도움이 된다.","scoring_points":["세 가지 노력을 썼는가","하나를 골랐는가","불균형을 줄이는 까닭을 썼는가"]},"explanation":["햇빛 발전·청년 마을·기부예요.","하나를 골라요.","사람이 모이는 까닭을 써요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#1','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C1',1,'mc','auto','기후를 구성하는 요소끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"기후를 구성하는 요소끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"기온·강수·바람","correct":true},{"t":"기온·지형·인구","mis":"SO5-1-u2-X02"},{"t":"강수·하천·평야","mis":"SO5-1-u2-X02"},{"t":"바람·교통·일자리","mis":"SO5-1-u2-X02"}],"explanation":["대기의 상태예요.","따뜻함, 내린 물, 공기의 움직임이에요.","기온·강수·바람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#2','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C3',1,'sa','auto','우리나라는 대체로 남쪽과 북쪽 가운데 어느 쪽으로 갈수록 기온이 높아지나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"sa","stem":"우리나라는 대체로 남쪽과 북쪽 가운데 어느 쪽으로 갈수록 기온이 높아지나요? 두 글자로 쓰세요.","answer":["남쪽"],"explanation":["남북으로 길어요.","아래쪽이 따뜻해요.","남쪽이에요."],"mis":"SO5-1-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#3','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C4',1,'sa','auto','눈·비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"sa","stem":"눈·비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["강수"],"explanation":["비도 눈도 내려요.","땅에 내린 물이에요.","강수예요."],"mis":"SO5-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#4','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C5',1,'sa','auto','기온이 갑자기 크게 내려가 수도관이 얼기도 하는 겨울의 자연재해를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"sa","stem":"기온이 갑자기 크게 내려가 수도관이 얼기도 하는 겨울의 자연재해를 쓰세요.","answer":["한파"],"explanation":["갑자기 추워져요.","동상 피해도 생겨요.","한파예요."],"mis":"SO5-1-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#5','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C7',1,'sa','auto','인간 활동 때문에 지구의 기온이 높아지는 현상을 무엇이라고 하나요? (지구 □□□)','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"sa","stem":"인간 활동 때문에 지구의 기온이 높아지는 현상을 무엇이라고 하나요? (지구 □□□)","answer":["온난화"],"explanation":["지구가 더워져요.","기후변화를 일으켜요.","지구 온난화예요."],"mis":"SO5-1-u2-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#6','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C9',1,'sa','auto','일정한 지역에 살고 있는 사람의 수를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"sa","stem":"일정한 지역에 살고 있는 사람의 수를 두 글자로 무엇이라고 하나요?","answer":["인구"],"explanation":["사람의 수예요.","한 지역에 사는 사람이에요.","인구예요."],"mis":"SO5-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#7','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C10',1,'sa','auto','1960년대 이후 공장과 도시가 발달한 변화를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"sa","stem":"1960년대 이후 공장과 도시가 발달한 변화를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["산업화"],"explanation":["산업이 크게 자랐어요.","사람들이 도시로 갔어요.","산업화예요."],"mis":"SO5-1-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#8','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',1,'sa','auto','수도권에서 집이 모자라 집값이 오르는 문제를 무엇이라고 하나요? (□□ 문제)','{}'::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"sa","stem":"수도권에서 집이 모자라 집값이 오르는 문제를 무엇이라고 하나요? (□□ 문제)","answer":["주택"],"explanation":["살 집이 모자라요.","집값이 올라요.","주택 문제예요."],"mis":"SO5-1-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#9','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C2',2,'ox','auto','눈이 많이 오는 지역에서 해마다 겨울에 눈 축제를 여는 것은 기후의 영향을 받은 생활이에요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"ox","stem":"눈이 많이 오는 지역에서 해마다 겨울에 눈 축제를 여는 것은 기후의 영향을 받은 생활이에요.","answer":"O","reason_options":[{"t":"여러 해 되풀이되는 겨울 기후에 맞춰 축제를 열기 때문에","correct":true},{"t":"그날 하루 눈이 왔기 때문에 열기로 한 것이기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["해마다 눈이 많아요.","같은 때 축제를 열어요.","기후의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#10','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C6',2,'ox','auto','홍수에 대비해 제방을 쌓고, 가뭄에 대비해 저수지와 댐을 만들어요.',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"ox","stem":"홍수에 대비해 제방을 쌓고, 가뭄에 대비해 저수지와 댐을 만들어요.","answer":"O","reason_options":[{"t":"시설을 마련해 자연재해의 피해를 줄이기 때문에","correct":true},{"t":"시설을 만들면 자연재해가 아예 일어나지 않기 때문에","mis":"SO5-1-u2-X10"}],"mis":"SO5-1-u2-X10","explanation":["제방은 물이 넘치지 않게 해요.","저수지는 물을 모아 둬요.","피해를 줄이는 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#11','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C8',2,'ox','auto','기후 행동은 특별한 사람만 할 수 있는 일이에요.',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"ox","stem":"기후 행동은 특별한 사람만 할 수 있는 일이에요.","answer":"X","reason_options":[{"t":"기후변화를 막으려는 모든 노력이라 누구나 참여할 수 있기 때문에","correct":true},{"t":"나라와 기업만 기후 행동을 할 수 있기 때문에","mis":"SO5-1-u2-X14"}],"mis":"SO5-1-u2-X14","explanation":["작은 실천도 기후 행동이에요.","누구나 할 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#12','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C9',2,'ox','auto','교통이 편리하고 학교가 많은 곳에 사람이 모이는 것은 인문환경의 영향이에요.',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"ox","stem":"교통이 편리하고 학교가 많은 곳에 사람이 모이는 것은 인문환경의 영향이에요.","answer":"O","reason_options":[{"t":"교통과 교육은 사람이 만든 환경이기 때문에","correct":true},{"t":"교통과 교육은 자연이 만든 환경이기 때문에","mis":"SO5-1-u2-X17"}],"mis":"SO5-1-u2-X17","explanation":["길과 학교는 사람이 만들어요.","그래서 인문환경이에요.","사람이 모여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#13','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C11',2,'ox','auto','수도권은 비수도권보다 청장년층 인구 비율이 높아요.',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"ox","stem":"수도권은 비수도권보다 청장년층 인구 비율이 높아요.","answer":"O","reason_options":[{"t":"일자리와 교육 기회를 찾아 청장년층이 수도권으로 모이기 때문에","correct":true},{"t":"수도권에는 어르신만 모여 살기 때문에","mis":"SO5-1-u2-X20"}],"mis":"SO5-1-u2-X20","explanation":["경기도는 청장년층이 많아요.","일자리를 찾아 모여요.","그래서 비율이 높아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#14','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',2,'ox','auto','다온이 일기 ⑥의 집값 걱정은 인구가 줄어드는 지역에서 주로 나타나는 문제예요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"ox","stem":"다온이 일기 ⑥의 집값 걱정은 인구가 줄어드는 지역에서 주로 나타나는 문제예요.","answer":"X","reason_options":[{"t":"집값 상승은 사람이 몰리는 수도권에서 주로 나타나는 문제이기 때문에","correct":true},{"t":"인구가 줄면 집이 모자라 집값이 오르기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["한빛시는 수도권이에요.","사람이 몰려 집이 모자라요.","그래서 X예요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#15','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C13',2,'ox','auto','고향 사랑 기부는 태어난 곳이 아니어도 관심 있는 지역에 할 수 있어요.',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"ox","stem":"고향 사랑 기부는 태어난 곳이 아니어도 관심 있는 지역에 할 수 있어요.","answer":"O","reason_options":[{"t":"고향이나 관심 있는 지역 어디에나 기부할 수 있는 제도이기 때문에","correct":true},{"t":"그 지역에서 태어난 사람만 기부할 수 있기 때문에","mis":"SO5-1-u2-X23"}],"mis":"SO5-1-u2-X23","explanation":["관심 지역에도 해요.","답례품과 세금 혜택이 있어요.","지방 재정을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#16','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C14',2,'ox','auto','좋아 보이는 방안도 세 잣대 가운데 하나에서 걸릴 수 있으니 세 가지를 모두 살펴야 해요.',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C14","difficulty":2,"kind":"ox","stem":"좋아 보이는 방안도 세 잣대 가운데 하나에서 걸릴 수 있으니 세 가지를 모두 살펴야 해요.","answer":"O","reason_options":[{"t":"원인·옳음·실현 가운데 하나만 보면 다른 잣대의 문제를 놓치기 때문에","correct":true},{"t":"잣대 하나만 지나면 좋은 방안이기 때문에","mis":"SO5-1-u2-X24"}],"mis":"SO5-1-u2-X24","explanation":["하나만 보면 놓쳐요.","셋을 모두 대요.","그래야 좋은 방안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#17','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C3',3,'error','auto','계절별 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X04','SO5-1-u2-X07','SO5-1-u2-X05']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C3","difficulty":3,"kind":"error","stem":"계절별 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로하 — 「겨울에는 남쪽 바다에서 뜨겁고 습한 바람이 불어와.」","correct":true,"mis_target":"SO5-1-u2-X04"},{"t":"채민 — 「연 강수량은 남쪽으로 갈수록 많아.」","mis":"SO5-1-u2-X07"},{"t":"도율 — 「남북 기온 차이는 겨울에 더 커.」","mis":"SO5-1-u2-X05"}],"explanation":["겨울 바람은 북서쪽 육지에서 와요.","차갑고 건조해요.","로하가 바꿔 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#18','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C6',3,'error','auto','자연재해의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X11','SO5-1-u2-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"error","stem":"자연재해의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「숲을 없애고 물길을 바꿔도 홍수 피해와는 아무 상관 없어.」","correct":true,"mis_target":"SO5-1-u2-X11"},{"t":"시윤 — 「숲은 빗물을 머금어 피해를 줄여 줘.」","mis":"SO5-1-u2-X11"},{"t":"가윤 — 「자연 현상으로 사람이 피해를 입으면 자연재해야.」","mis":"SO5-1-u2-X08"}],"explanation":["숲과 물길은 물의 흐름을 정해요.","바꾸면 피해가 커지기도 해요.","하람이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#19','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C8',3,'error','auto','다온이 일기 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"error","stem":"다온이 일기 ⑤를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"세율 — 「△가 나왔으니 다온이의 기후 행동은 실패야. 그만두는 게 좋아.」","correct":true,"mis_target":"SO5-1-u2-X15"},{"t":"지온 — 「돌아보고 다시 하려는 게 좋은 기후 행동이야.」","mis":"SO5-1-u2-X15"},{"t":"하늬 — 「손수건 쓰기는 개인의 기후 행동이야.」","mis":"SO5-1-u2-X14"}],"explanation":["잘 안 된 날도 있어요.","돌아보고 다시 해요.","세율이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#20','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C10',3,'error','auto','우리나라 인구 분포의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"error","stem":"우리나라 인구 분포의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수호 — 「사람들이 도시에서 솔내 마을 같은 촌락으로 많이 옮겨 갔어.」","correct":true,"mis_target":"SO5-1-u2-X19"},{"t":"아린 — 「오늘날 인구 100명 중 92명 정도가 도시에 살아.」","mis":"SO5-1-u2-X19"},{"t":"재윤 — 「옛날엔 평야가 넓은 곳에 많이 살았어.」","mis":"SO5-1-u2-X19"}],"explanation":["촌락에서 도시로 옮겼어요.","도시 인구가 늘었어요.","수호가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#21','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',3,'error','auto','수도권과 비수도권의 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X22','SO5-1-u2-X21']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"error","stem":"수도권과 비수도권의 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예준 — 「수도권은 사람이 많으니까 문제가 하나도 없어.」","correct":true,"mis_target":"SO5-1-u2-X22"},{"t":"하윤 — 「수도권은 집이 부족하고 교통이 붐벼.」","mis":"SO5-1-u2-X21"},{"t":"서원 — 「비수도권은 빈집과 폐교가 늘어.」","mis":"SO5-1-u2-X21"}],"explanation":["수도권에도 문제가 있어요.","주택·교통·환경 문제예요.","예준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#22','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C14',3,'error','auto','해결 방안 평가를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C14","difficulty":3,"kind":"error","stem":"해결 방안 평가를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유준 — 「원인만 풀 수 있으면 사람들한테 벌을 줘도 좋은 방안이야.」","correct":true,"mis_target":"SO5-1-u2-X24"},{"t":"시은 — 「옳은 방안인지도 꼭 살펴야 해.」","mis":"SO5-1-u2-X24"},{"t":"도윤 — 「비용과 노력으로 해낼 수 있는지 봐야 해.」","mis":"SO5-1-u2-X24"}],"explanation":["잣대는 셋 다 지나야 해요.","벌주는 것은 옳지 않아요.","유준이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#23','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C12',4,'mc','auto','다온이 일기 ⑥·⑦·⑧을 차례로 이어 볼 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO5-1-u2-X22','SO5-1-u2-X24']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C12","difficulty":4,"kind":"mc","stem":"다온이 일기 ⑥·⑦·⑧을 차례로 이어 볼 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"수도권은 몰려서, 솔내 마을은 비어서 문제가 생기므로 정부·지역·주민이 함께 사람이 고르게 살 수 있게 노력해야 한다","correct":true},{"t":"수도권은 문제가 없으니 솔내 마을만 노력하면 된다","mis":"SO5-1-u2-X22"},{"t":"솔내 마을 사람들을 모두 한빛시로 옮기면 해결된다","mis":"SO5-1-u2-X24"},{"t":"두 곳의 문제는 저절로 사라진다","mis":"SO5-1-u2-X22"}],"explanation":["⑥은 몰린 곳이에요.","⑦은 빈 곳, ⑧은 노력이에요.","함께 고르게 살 길을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#24','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C8',4,'essay','teacher','다온이 일기 ⑤를 보고 기후변화가 우리 생활에 준 영향을 쓰고, 다온이의 기후 행동 수첩에서 본받을 점과 내가 더할 기후 행동 한 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C8","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑤를 보고 기후변화가 우리 생활에 준 영향을 쓰고, 다온이의 기후 행동 수첩에서 본받을 점과 내가 더할 기후 행동 한 가지를 쓰세요.","answer_guide":{"answer":"예: 기후변화로 여름이 길어지고 역대 가장 긴 폭염처럼 자연재해가 더 심해졌다. 다온이는 손수건을 잊은 날 그만두지 않고 까닭을 돌아보아 손수건을 하나 더 챙겼는데, 실천한 뒤 돌아보고 다시 하는 점을 본받고 싶다. 나는 일회용 컵 대신 개인 물병을 쓰겠다.","scoring_points":["기후변화의 영향을 썼는가","실천하고 돌아보는 점을 본받을 점으로 썼는가","내가 매일 할 수 있는 기후 행동을 썼는가"]},"explanation":["여름이 길어졌어요.","돌아보고 다시 했어요.","나도 매일 할 일을 더해요."],"asset":{"type":"passage","lines":["뉴스에서 「역대 가장 긴 폭염」, 「여름이 점점 길어진다」는 말을 들었다.","나의 기후 행동 수첩 — 손수건 쓰기 · 가까운 길 걷기 · 급식 남기지 않기","수요일에는 손수건을 깜빡해 △를 표시했다.","왜 잊었는지 생각해 보고 가방에 손수건을 하나 더 넣었다."],"title":"다온이 일기 ⑤ 기후 행동 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_c#25','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C14',4,'essay','teacher','솔내 마을의 「1학년 신입생이 없는 학교」 문제를 풀 방안을 한 가지 쓰고, 세 잣대(원인·옳음·실현)에 대어 평가하세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C14","difficulty":4,"kind":"essay","stem":"솔내 마을의 「1학년 신입생이 없는 학교」 문제를 풀 방안을 한 가지 쓰고, 세 잣대(원인·옳음·실현)에 대어 평가하세요.","answer_guide":{"answer":"예: 방안은 솔내 초등학교에 자연 속 특별 교육과정을 만들고 낡은 시설을 고쳐 다니고 싶은 학교로 만드는 것이다. 학교가 다닐 만한 곳이 되어 학생이 오게 하니 원인 해결에 도움이 된다. 누구에게도 억지로 전학을 시키지 않으니 옳은 방안이다. 이미 여러 지역에서 하는 일이라 비용과 노력을 생각할 때 해낼 수 있다.","scoring_points":["방안을 썼는가","세 잣대에 모두 대어 보았는가","각 잣대의 까닭을 썼는가"]},"explanation":["방안을 먼저 써요.","원인·옳음·실현에 대요.","까닭을 함께 써요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#1','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C1',1,'ox','auto','「우리나라는 사계절이 뚜렷하다」는 말은 기후에 대한 설명이에요.',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"ox","stem":"「우리나라는 사계절이 뚜렷하다」는 말은 기후에 대한 설명이에요.","answer":"O","reason_options":[{"t":"여러 해에 걸쳐 되풀이되어 나타나는 모습이기 때문에","correct":true},{"t":"오늘 하루의 하늘을 보고 한 말이기 때문에","mis":"SO5-1-u2-X01"}],"mis":"SO5-1-u2-X01","explanation":["사계절은 해마다 되풀이돼요.","여러 해의 모습이에요.","그래서 기후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#2','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C3',1,'ox','auto','다온이 일기 ④에서 같은 날 이모가 사는 남쪽 섬이 다온이네보다 따뜻했던 것은 우리나라 기온의 특징과 맞아요.',ARRAY['SO5-1-u2-X05']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C3","difficulty":1,"kind":"ox","stem":"다온이 일기 ④에서 같은 날 이모가 사는 남쪽 섬이 다온이네보다 따뜻했던 것은 우리나라 기온의 특징과 맞아요.","answer":"O","reason_options":[{"t":"대체로 남쪽으로 갈수록 기온이 높기 때문에","correct":true},{"t":"북쪽으로 갈수록 기온이 높기 때문에","mis":"SO5-1-u2-X05"}],"mis":"SO5-1-u2-X05","explanation":["이모는 남쪽 섬에 살아요.","겨울에도 밭에서 무를 거둬요.","남쪽이 더 따뜻해요."],"asset":{"type":"passage","lines":["1월 — 북서쪽에서 차고 건조한 바람이 불어 손발이 시렸다.","수도관이 얼지 않게 밤새 수도꼭지를 조금 틀어 두었다.","같은 날 남쪽 섬에 사는 이모는 밭에서 무를 거둔다고 영상 통화를 했다."],"title":"다온이 일기 ④ 겨울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#3','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C4',1,'ox','auto','다온이 일기 ②처럼 여름에 비가 많이 내리는 것은 우리나라 강수의 특징과 맞아요.',ARRAY['SO5-1-u2-X07']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C4","difficulty":1,"kind":"ox","stem":"다온이 일기 ②처럼 여름에 비가 많이 내리는 것은 우리나라 강수의 특징과 맞아요.","answer":"O","reason_options":[{"t":"연 강수량의 절반 이상이 여름에 내리기 때문에","correct":true},{"t":"우리나라는 겨울에 비가 가장 많기 때문에","mis":"SO5-1-u2-X07"}],"mis":"SO5-1-u2-X07","explanation":["여름에 비가 몰려요.","7월에 굵은 비가 왔어요.","특징과 맞아요."],"asset":{"type":"passage","lines":["7월 — 며칠째 굵은 비가 쏟아졌다. 하천 물이 불어 낮은 길이 잠겼다.","집에 오는 길에 휴대 전화로 긴급 재난 문자가 왔다.","물이 찬 길로 다니지 말라는 안내를 보고 높은 길로 돌아왔다."],"title":"다온이 일기 ② 여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#4','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C5',1,'ox','auto','태풍은 주로 겨울에 우리나라에 영향을 주는 자연재해예요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C5","difficulty":1,"kind":"ox","stem":"태풍은 주로 겨울에 우리나라에 영향을 주는 자연재해예요.","answer":"X","reason_options":[{"t":"태풍은 주로 여름과 가을 사이에 우리나라에 영향을 주기 때문에","correct":true},{"t":"태풍은 눈을 많이 내리는 겨울 재해이기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["다온이 일기 ③은 9월 초예요.","여름과 가을 사이에 와요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#5','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C7',1,'ox','auto','기후변화로 폭염 같은 자연재해가 더 잦아지고 세지고 있어요.',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C7","difficulty":1,"kind":"ox","stem":"기후변화로 폭염 같은 자연재해가 더 잦아지고 세지고 있어요.","answer":"O","reason_options":[{"t":"기후변화로 자연재해의 횟수와 강도가 모두 늘고 있기 때문에","correct":true},{"t":"기후변화는 자연재해와 관계가 없기 때문에","mis":"SO5-1-u2-X13"}],"mis":"SO5-1-u2-X13","explanation":["「역대」라는 말이 잦아요.","더 자주, 더 세게 와요.","기후변화의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#6','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',1,'ox','auto','다온이네 한빛시처럼 도시가 발달한 곳은 대체로 인구 밀도가 높아요.',ARRAY['SO5-1-u2-X18']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C9","difficulty":1,"kind":"ox","stem":"다온이네 한빛시처럼 도시가 발달한 곳은 대체로 인구 밀도가 높아요.","answer":"O","reason_options":[{"t":"일자리와 교통이 갖춰져 좁은 땅에 사람이 많이 모이기 때문에","correct":true},{"t":"도시는 땅이 넓어 사람이 흩어져 살기 때문에","mis":"SO5-1-u2-X18"}],"mis":"SO5-1-u2-X18","explanation":["지하철이 꽉 차요.","사람이 많이 모여요.","인구 밀도가 높아요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#7','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',1,'ox','auto','과거 우리나라는 벼농사 중심의 농업 사회라 남서쪽 평야 지대에 사람이 많이 살았어요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"ox","stem":"과거 우리나라는 벼농사 중심의 농업 사회라 남서쪽 평야 지대에 사람이 많이 살았어요.","answer":"O","reason_options":[{"t":"기후가 온화하고 평야가 넓은 곳이 농사짓기 좋았기 때문에","correct":true},{"t":"그곳에 공장과 회사가 가장 많았기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["그때는 농사가 중요했어요.","평야가 넓었어요.","자연환경의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#8','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',1,'ox','auto','인구 분포의 불균형은 수도권과 비수도권 모두에 문제를 낳아요.',ARRAY['SO5-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C12","difficulty":1,"kind":"ox","stem":"인구 분포의 불균형은 수도권과 비수도권 모두에 문제를 낳아요.","answer":"O","reason_options":[{"t":"몰리는 곳은 혼잡하고 빠져나가는 곳은 시설이 줄기 때문에","correct":true},{"t":"불균형은 수도권에만 문제를 낳기 때문에","mis":"SO5-1-u2-X22"}],"mis":"SO5-1-u2-X22","explanation":["수도권엔 혼잡이 생겨요.","비수도권엔 빈집이 생겨요.","두 곳 모두 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#9','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C2',2,'error','auto','기후가 생활에 주는 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"error","stem":"기후가 생활에 주는 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다빈 — 「오늘 소나기로 소풍이 취소된 건 기후가 생활에 준 영향이야.」","correct":true,"mis_target":"SO5-1-u2-X03"},{"t":"주안 — 「덥고 비가 많은 곳은 벼농사가 활발해.」","mis":"SO5-1-u2-X03"},{"t":"예나 — 「계절마다 입는 옷이 달라져.」","mis":"SO5-1-u2-X03"}],"explanation":["오늘 소나기는 날씨예요.","기후의 영향이 아니에요.","다빈이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#10','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C6',2,'error','auto','자연재해 대비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C6","difficulty":2,"kind":"error","stem":"자연재해 대비를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「태풍 주의보가 나오면 바닷가에 가서 큰 파도를 구경하자.」","correct":true,"mis_target":"SO5-1-u2-X10"},{"t":"시아 — 「기상 특보가 나오면 뉴스를 확인해.」","mis":"SO5-1-u2-X10"},{"t":"로운 — 「학교에서 재난 대비 훈련을 해.」","mis":"SO5-1-u2-X10"}],"explanation":["태풍 때 바닷가는 위험해요.","외출을 삼가야 해요.","이안이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#11','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C8',2,'error','auto','기후 행동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X14','SO5-1-u2-X15']::text[],false,'{"seq":11,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"error","stem":"기후 행동을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「나 하나 손수건 쓴다고 달라지는 건 없으니 안 할래.」","correct":true,"mis_target":"SO5-1-u2-X14"},{"t":"유나 — 「빈 교실 전등을 끄는 것도 기후 행동이야.」","mis":"SO5-1-u2-X14"},{"t":"건우 — 「실천한 뒤에 수첩을 보며 돌아봐야 해.」","mis":"SO5-1-u2-X15"}],"explanation":["한 사람의 실천이 모여요.","누구나 참여해요.","시후가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#12','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',2,'error','auto','인구 분포에 영향을 주는 환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"error","stem":"인구 분포에 영향을 주는 환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하온 — 「일자리는 자연이 만든 환경이야.」","correct":true,"mis_target":"SO5-1-u2-X17"},{"t":"지아 — 「평평한 땅에 사람이 더 많이 살아.」","mis":"SO5-1-u2-X17"},{"t":"도하 — 「교통은 사람이 만든 인문환경이야.」","mis":"SO5-1-u2-X17"}],"explanation":["일자리는 사람이 만들어요.","인문환경이에요.","하온이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#13','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C11',2,'error','auto','인구 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":13,"concept":"SO5-1-u2-C11","difficulty":2,"kind":"error","stem":"인구 구조를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은재 — 「인구 구조를 보면 그 지역의 땅 넓이를 알 수 있어.」","correct":true,"mis_target":"SO5-1-u2-X20"},{"t":"서진 — 「인구 구조는 나이별로 나누어 본 짜임새야.」","mis":"SO5-1-u2-X20"},{"t":"라희 — 「비수도권은 노년층 비율이 더 높아.」","mis":"SO5-1-u2-X20"}],"explanation":["인구 구조는 나이·성별 짜임새예요.","땅 넓이와는 관계없어요.","은재가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#14','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',2,'error','auto','다온이 일기 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":14,"concept":"SO5-1-u2-C12","difficulty":2,"kind":"error","stem":"다온이 일기 ⑦을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「솔내 마을은 사람이 너무 많아서 가게가 문을 닫은 거야.」","correct":true,"mis_target":"SO5-1-u2-X21"},{"t":"나은 — 「사람이 줄어 물건이 안 팔려 가게가 문을 닫았어.」","mis":"SO5-1-u2-X21"},{"t":"준우 — 「트럭 상점은 가게가 없는 마을을 도와.」","mis":"SO5-1-u2-X21"}],"explanation":["솔내 마을은 사람이 줄었어요.","물건이 안 팔렸어요.","태윤이 거꾸로 말했어요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#15','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C13',2,'error','auto','불균형을 해결하는 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X23']::text[],false,'{"seq":15,"concept":"SO5-1-u2-C13","difficulty":2,"kind":"error","stem":"불균형을 해결하는 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민우 — 「공공 기관을 수도권으로 더 모으면 인구가 고르게 살게 돼.」","correct":true,"mis_target":"SO5-1-u2-X23"},{"t":"해나 — 「로컬 브랜딩은 지역만의 매력을 만들어.」","mis":"SO5-1-u2-X23"},{"t":"지성 — 「혁신 도시는 일자리를 늘려 사람을 모아.」","mis":"SO5-1-u2-X23"}],"explanation":["공공 기관은 비수도권으로 옮겨요.","수도권으로 모으면 더 몰려요.","민우가 거꾸로 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#16','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C15',2,'error','auto','시화 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X26']::text[],false,'{"seq":16,"concept":"SO5-1-u2-C15","difficulty":2,"kind":"error","stem":"시화 만들기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「동시와 상관없어도 예쁜 그림이면 돼.」","correct":true,"mis_target":"SO5-1-u2-X26"},{"t":"서아 — 「그림은 동시의 내용을 나타내야 해.」","mis":"SO5-1-u2-X26"},{"t":"윤재 — 「친구 시화의 좋은 점을 찾아 말해 줘.」","mis":"SO5-1-u2-X26"}],"explanation":["그림은 동시를 보여 줘요.","내용을 나타내야 해요.","하늘이 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#17','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C4',3,'ox','auto','연 강수량 분포도에서 남쪽으로 갈수록 파란색이 진해지는 것은 남쪽의 강수량이 더 많다는 뜻이에요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"ox","stem":"연 강수량 분포도에서 남쪽으로 갈수록 파란색이 진해지는 것은 남쪽의 강수량이 더 많다는 뜻이에요.","answer":"O","reason_options":[{"t":"분포도에서 진한 파란색일수록 강수량이 많기 때문에","correct":true},{"t":"진한 파란색일수록 기온이 낮기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["파란색은 강수량이에요.","진할수록 많아요.","남쪽이 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#18','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C5',3,'ox','auto','다온이 일기 ③의 태풍이 남서쪽에서 올라온 것은 태풍이 대체로 지나가는 길과 맞아요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"ox","stem":"다온이 일기 ③의 태풍이 남서쪽에서 올라온 것은 태풍이 대체로 지나가는 길과 맞아요.","answer":"O","reason_options":[{"t":"태풍은 대체로 남서쪽에서 북동쪽으로 지나가기 때문에","correct":true},{"t":"태풍은 언제나 북쪽에서 남쪽으로 내려오기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["남서쪽에서 올라왔어요.","북동쪽으로 지나가요.","태풍의 길과 맞아요."],"asset":{"type":"passage","lines":["9월 초 — 남서쪽에서 태풍이 올라온다며 태풍 주의보가 내려졌다.","아빠와 베란다의 화분과 빨래 건조대를 안으로 들여놓았다.","그날은 밖에 나가지 않고 집에서 보냈다."],"title":"다온이 일기 ③ 늦여름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#19','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C7',3,'ox','auto','기후변화는 숲을 파괴하고 석유·석탄을 지나치게 쓰는 인간 활동과 관계가 있어요.',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"ox","stem":"기후변화는 숲을 파괴하고 석유·석탄을 지나치게 쓰는 인간 활동과 관계가 있어요.","answer":"O","reason_options":[{"t":"이런 인간 활동이 지구 온난화를 심하게 만들기 때문에","correct":true},{"t":"기후변화는 사람과 아무 관계 없이 일어나기 때문에","mis":"SO5-1-u2-X12"}],"mis":"SO5-1-u2-X12","explanation":["사람의 활동이 원인이에요.","지구가 더워져요.","기후가 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#20','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',3,'ox','auto','오늘날 수도권으로 사람이 모이는 까닭은 주로 기후가 온화하고 평야가 넓기 때문이에요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"ox","stem":"오늘날 수도권으로 사람이 모이는 까닭은 주로 기후가 온화하고 평야가 넓기 때문이에요.","answer":"X","reason_options":[{"t":"오늘날에는 일자리·교통 같은 인문환경의 영향이 크기 때문에","correct":true},{"t":"수도권은 우리나라에서 평야가 가장 넓은 곳이기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["옮겨 온 까닭 1위는 직업이에요.","인문환경의 영향이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#21','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',3,'ox','auto','다온이 학교의 운동장 요일제는 학생이 너무 많은 수도권 학교의 모습을 보여 줘요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"ox","stem":"다온이 학교의 운동장 요일제는 학생이 너무 많은 수도권 학교의 모습을 보여 줘요.","answer":"O","reason_options":[{"t":"인구가 몰린 곳은 시설이 부족해 나누어 써야 하기 때문에","correct":true},{"t":"학생이 줄어든 학교라 운동장이 남기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["학생이 많아요.","운동장이 부족해요.","몰린 곳의 모습이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#22','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C13',3,'ox','auto','솔내 마을의 트럭 상점처럼 물건을 싣고 마을을 찾아가는 방법은 사는 곳에서 주민을 돕는 노력이에요.',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"ox","stem":"솔내 마을의 트럭 상점처럼 물건을 싣고 마을을 찾아가는 방법은 사는 곳에서 주민을 돕는 노력이에요.","answer":"O","reason_options":[{"t":"주민을 이사 보내지 않고 부족한 상점을 채워 주기 때문에","correct":true},{"t":"주민을 도시로 옮겨 살게 하는 방법이기 때문에","mis":"SO5-1-u2-X24"}],"mis":"SO5-1-u2-X24","explanation":["물건이 마을로 가요.","주민은 그대로 살아요.","사는 곳에서 도와요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#23','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',4,'mc','auto','다온이 일기 ⑦과 ⑧을 함께 볼 때 솔내 마을의 노력이 인구 분포의 변화와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19','SO5-1-u2-X18']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"다온이 일기 ⑦과 ⑧을 함께 볼 때 솔내 마을의 노력이 인구 분포의 변화와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오늘날 인구 분포는 일자리 같은 인문환경의 영향이 크므로 일거리와 살기 좋은 환경을 만들면 사람을 다시 모을 수 있기 때문에","correct":true},{"t":"오늘날 인구 분포는 기후만 바꾸면 달라지기 때문에","mis":"SO5-1-u2-X19"},{"t":"솔내 마을의 땅을 넓히면 인구 밀도가 높아지기 때문에","mis":"SO5-1-u2-X18"},{"t":"인구 분포는 한 번 정해지면 바뀌지 않기 때문에","mis":"SO5-1-u2-X19"}],"explanation":["사람은 일자리를 찾아 움직여요.","인문환경의 영향이 커요.","일거리가 사람을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#24','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',4,'essay','teacher','다온이 일기 ⑥과 ⑦을 견주어 두 곳의 인구 밀도가 어떻게 다를지 쓰고, 그렇게 된 까닭을 자연환경과 인문환경 가운데 하나와 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑥과 ⑦을 견주어 두 곳의 인구 밀도가 어떻게 다를지 쓰고, 그렇게 된 까닭을 자연환경과 인문환경 가운데 하나와 이어 쓰세요.","answer_guide":{"answer":"예: 한빛시는 지하철이 늘 꽉 차고 학생이 많을 만큼 사람이 몰려 인구 밀도가 높을 것이고, 솔내 마을은 신입생이 없을 만큼 사람이 줄어 인구 밀도가 낮을 것이다. 한빛시에는 일자리와 교통 같은 인문환경이 잘 갖춰져 사람이 모이고, 솔내 마을은 일자리가 적어 젊은 사람이 떠났기 때문이다.","scoring_points":["한빛시의 인구 밀도를 썼는가","솔내 마을의 인구 밀도를 썼는가","환경과 이어 까닭을 썼는가"]},"explanation":["한빛시는 높아요.","솔내 마을은 낮아요.","일자리가 사람을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_soc_u2_review_d#25','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C15',4,'essay','teacher','다온이처럼 이 단원에서 공부한 내용으로 동시를 짓는다고 생각하고, 주제와 바탕이 될 내 경험을 쓴 뒤 동시 세 줄과 시화에 그릴 장면을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"essay","stem":"다온이처럼 이 단원에서 공부한 내용으로 동시를 짓는다고 생각하고, 주제와 바탕이 될 내 경험을 쓴 뒤 동시 세 줄과 시화에 그릴 장면을 쓰세요.","answer_guide":{"answer":"예: 주제는 자연재해에 대비하는 노력이다. 경험 — 비가 세차게 내린 날 긴급 재난 문자를 보고 높은 길로 돌아왔다. 동시 — 하늘에 구멍 났나 쏟아지는 비 / 주머니에서 울리는 고마운 문자 / 나는 높은 길로 천천히. 장면 — 우산을 쓰고 물이 찬 낮은 길을 피해 높은 길로 걷는 나.","scoring_points":["단원에서 공부한 주제를 골랐는가","내 경험을 썼는가","짧게 줄인 동시 세 줄과 알맞은 장면을 썼는가"]},"explanation":["주제를 골라요.","내 경험이 바탕이에요.","짧게 줄이고 장면을 정해요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C1','kor',5,2,'u1',1,'인상적인 부분의 뜻 — 작품을 읽으며 마음이 움직이거나 궁금증 · 깨달음이 생기는 부분으로, 내 경험이 떠오르는 곳이나 기억에 남는 문장도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C2','kor',5,2,'u1',1,'사람마다 다른 인상적인 부분 — 같은 작품을 읽어도 마음에 남는 부분은 사람마다 다를 수 있어서, 인상적인 부분에는 하나로 정해진 정답이 없다',ARRAY['6국05-04 문학']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C3','kor',5,2,'u1',1,'부분과 까닭은 한 짝 — 인상적인 부분은 아무 곳이나 고르는 것이 아니라 그 부분이 인상적인 까닭을 작품 속 말이나 내 경험과 이어서 함께 말해야 서로의 생각을 알 수 있다',ARRAY['6국05-04 문학']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C4','kor',5,2,'u1',1,'시와 이야기에서 살필 것 — 시에서는 표현 · 말하는 이의 마음 · 분위기를, 이야기에서는 인물 · 사건 · 때와 곳, 인물의 말과 행동, 사건의 흐름을 살피며 인상적인 부분을 찾는다',ARRAY['6국05-04 문학']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C5','kor',5,2,'u1',1,'단원의 흐름 — 시를 읽고 까닭을 들어 인상적인 부분을 말하고 → 시에 대한 의견을 나누고 → 이야기로 넓힌 뒤 → 서평을 쓰고 → 우리 반 「이달의 책」을 고른다',ARRAY['6국05-04 문학']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C6','kor',5,2,'u1',2,'시를 여러 번 읽고 내용 · 주제 알기 — 시는 여러 번 읽으며 장면을 떠올리고, 무엇을 말하는지(내용)와 말하는 이가 가장 전하고 싶은 생각(주제)을 찾는다',ARRAY['6국05-04 문학']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C7','kor',5,2,'u1',2,'독특하고 재미있는 표현 — 흉내 내는 말 · 빗대어 나타낸 말처럼 독특하고 재미있는 표현은 인상적인 부분이 되기 쉬우며, 그 표현이 어떤 느낌을 주는지까지 말한다',ARRAY['6국05-04 문학']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C8','kor',5,2,'u1',2,'경험과 이어지는 공감 — 시 속 일이 내가 겪은 일과 닮아 「나도 그랬지」 하고 공감되는 부분도 인상적인 부분이며, 그때 떠오른 내 경험이 곧 까닭이 된다',ARRAY['6국05-04 문학']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C9','kor',5,2,'u1',2,'주제가 잘 드러나는 부분 — 말하는 이가 하고 싶은 말이 또렷이 드러나거나 특별한 생각이 들게 하는 부분도 인상적인 부분이며, 제목만으로는 주제를 다 알 수 없어 시 전체를 읽고 찾는다',ARRAY['6국05-04 문학']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C10','kor',5,2,'u1',2,'마음과 분위기도 인상적인 부분 — 인상적인 부분은 한 구절에만 머물지 않아 말하는 이의 마음이나 시 전체의 분위기처럼 시 전체에서 느낀 것도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C11','kor',5,2,'u1',2,'빗댄 표현을 경험과 이어 읽기 — 「말은 마음에 찍히는 발자국」처럼 빗대어 나타낸 표현은 글자 그대로가 아니라 닮은 점(말이 마음에 남는다)을 찾아, 내 경험이나 배경지식과 이어 이해한다',ARRAY['6국05-04 문학']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C12','kor',5,2,'u1',2,'느낌을 살려 낭송하기 — 인상적인 부분의 느낌이 살도록 빠르기 · 목소리 크기 · 쉬는 곳을 바꾸어 낭송하며, 모두 같은 소리로 크게만 읽는 것이 아니다',ARRAY['6국05-04 문학']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C13','kor',5,2,'u1',4,'공감하며 읽은 시 소개하기 — 수업이나 도서관에서 읽은 시 가운데 공감한 시를 골라 어떤 시인지와 공감한 까닭을 친구에게 소개하며, 꼭 똑같은 일을 겪지 않아도 비슷한 마음을 느껴 보았으면 공감할 수 있다',ARRAY['6국05-04 문학']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C14','kor',5,2,'u1',4,'낱말의 뜻을 알고 읽기 — 모르는 낱말은 앞뒤 문장으로 짐작하고 뜻을 확인하며 읽고(괜스레 — 까닭이나 실속 없이), 낱말을 넣어 문장을 만들어 본다',ARRAY['6국05-04 문학']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C15','kor',5,2,'u1',4,'말하는 이의 마음 흐름 — 시 속 말하는 이의 마음은 처음부터 끝까지 같지 않을 수 있어서(속상함 → 답답함 → 스스로 달래기), 연마다 행동과 말이 어떻게 바뀌는지 따라가며 읽는다',ARRAY['6국05-04 문학']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C16','kor',5,2,'u1',4,'마음 흐름에 맞춘 낭송 — 마음이 바뀌는 곳에서 빠르기와 강약을 바꾸고, 모둠이 연을 나누어 맡아 이어 읽으며 시의 분위기를 살린다',ARRAY['6국05-04 문학']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C17','kor',5,2,'u1',4,'까닭이 다른 까닭 — 친구마다 경험 · 관심사 · 배경지식이 달라 같은 시에서도 인상적인 부분과 그 까닭이 다를 수 있으며, 그렇다고 어느 한쪽이 잘못 읽은 것은 아니다',ARRAY['6국05-04 문학']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C18','kor',5,2,'u1',4,'경청하며 의견 나누기 — 친구의 의견을 끝까지 듣고 나와 같은 점 · 다른 점을 찾으면 미처 생각하지 못한 관점으로 작품을 다시 보게 되어 생각이 넓어진다',ARRAY['6국01-06 듣기·말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C19','kor',5,2,'u1',4,'그림으로 감상 넓히기 — 다른 시를 한 편 더 읽고 인상적인 부분을 그림으로 그린 뒤 그 부분을 고른 까닭을 말하며, 그림은 잘 그렸는지가 아니라 무엇을 왜 골랐는지가 중요하다',ARRAY['6국05-04 문학']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C20','kor',5,2,'u1',7,'전기문의 뜻 — 전기문은 실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글로, 인물이 겪은 일 · 한 일 · 생각을 알려 주어 감동과 교훈을 준다',ARRAY['6국05-04 문학']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C21','kor',5,2,'u1',7,'사실과 다시 꾸민 부분 — 전기문의 사건은 대체로 역사적 사실에 바탕을 두지만 인물이 한 말이나 행동은 작가가 상상하거나 다시 꾸며 표현한 것일 수 있어, 사실과 꾸민 부분을 가려 읽는다',ARRAY['6국05-04 문학']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C22','kor',5,2,'u1',7,'시대적 상황 알기 — 이야기 속 인물이 살았던 때와 곳(나라를 빼앗긴 일제 강점기처럼)을 알아야 인물이 왜 그런 일을 했는지 이해할 수 있다',ARRAY['6국05-04 문학']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C23','kor',5,2,'u1',7,'처한 상황과 말 · 행동 잇기 — 인물이 처한 상황과 그때 한 말이나 행동을 이어 보면 인물의 마음과 생각이 보이며, 말 · 행동만 떼어 보면 그 뜻을 놓친다',ARRAY['6국05-04 문학']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C24','kor',5,2,'u1',7,'이야기에서 인상적인 부분 — 이야기에서는 사건의 흐름 · 인물의 변화 · 기억에 남는 말이나 행동이 인상적인 부분이 되기 쉽고, 이야기의 주제나 분위기도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C25','kor',5,2,'u1',7,'인상적인 부분으로 질문 만들기 — 인상적인 부분을 중심으로 인물에게 하고 싶은 질문(「그때 무섭지 않았나요?」)을 만들어 친구와 묻고 답하면 인물의 마음에 더 깊이 공감한다',ARRAY['6국05-04 문학']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C26','kor',5,2,'u1',7,'인물의 삶과 나의 삶 — 전기문 속 인물의 삶에서 본받을 점을 찾고 지금 우리의 삶과 이어 보면, 옛사람의 이야기도 오늘의 나에게 뜻이 있음을 알게 된다',ARRAY['6국05-04 문학']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C27','kor',5,2,'u1',10,'서평의 뜻 — 서평은 책을 읽고 그 책에 대한 자신의 의견이나 평가를 까닭과 함께 밝힌 글이다',ARRAY['6국05-04 문학']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C28','kor',5,2,'u1',10,'서평에 들어갈 내용 — 서평에는 제목 · 책 소개(제목 · 지은이 · 대상 독자 · 주제) · 줄거리 · 인상적인 부분과 그 까닭 · 책에 대한 평가가 들어간다',ARRAY['6국05-04 문학']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C29','kor',5,2,'u1',10,'줄거리는 간단히 — 서평의 줄거리는 일어난 일 가운데 중요한 일만 골라 차례대로 간단히 쓰며, 서평의 중심은 줄거리가 아니라 인상적인 부분과 평가다',ARRAY['6국05-04 문학']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C30','kor',5,2,'u1',10,'평가 — 좋은 점 · 아쉬운 점 · 추천 — 평가에는 좋은 점뿐 아니라 아쉬운 점도 까닭과 함께 쓸 수 있고, 누구에게 왜 추천하는지를 쓴다',ARRAY['6국05-04 문학']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C31','kor',5,2,'u1',10,'독서 감상문과 서평 — 독서 감상문은 책을 읽고 떠오른 생각이나 느낌을 자유롭게 쓴 글이고, 서평은 책의 좋은 점이나 아쉬운 점을 평가하고 그렇게 생각한 까닭을 함께 밝힌 글이다',ARRAY['6국05-04 문학']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C32','kor',5,2,'u1',10,'서평의 제목 붙이기 — 서평의 제목은 책 제목을 그대로 옮기기보다 읽을 사람의 관심을 끌고 책의 핵심 내용이나 내 평가가 드러나게 붙인다',ARRAY['6국05-04 문학']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C33','kor',5,2,'u1',10,'계획하고 쓰고 고쳐 쓰기 — 쓸 내용을 칸마다 정리해 계획하고, 「이 책이 재미있는 까닭은?」처럼 스스로 물으며 쓴 뒤, 친구와 돌려 읽고 받은 의견으로 고쳐 쓴다',ARRAY['6국05-04 문학']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C34','kor',5,2,'u1',12,'추천할 책과 까닭 정리하기 — 「이달의 책」에 어울리는 조건(흥미로운 이야기 · 교훈을 주는 이야기)을 생각해 추천할 책과 추천하는 까닭, 인상적인 부분을 정리하며, 너무 어렵거나 한 분야에만 치우친 책은 피한다',ARRAY['6국05-04 문학']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C35','kor',5,2,'u1',12,'의견 견주기 — 모둠 친구들의 추천 까닭을 끝까지 듣고 같은 점과 다른 점을 견주어 정리한다',ARRAY['6국01-06 듣기·말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C36','kor',5,2,'u1',12,'기준을 세워 조정하기 — 의견이 갈리면 「반 친구들에게 두루 도움이 되는가」처럼 함께 정한 기준에 대어 견주고 조정해 고르며, 목소리 크기나 말한 차례로 정하지 않는다',ARRAY['6국01-06 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C37','kor',5,2,'u1',12,'뽑히지 않은 의견도 존중 — 토의는 의견을 견주고 조정하는 과정이어서 뽑히지 않은 책의 추천 까닭도 친구들이 새 책을 알게 하고 다음 후보가 될 수 있으므로, 다양한 의견을 인정한다',ARRAY['6국01-06 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C38','kor',5,2,'u1',12,'소개 자료 만들기 — 고른 책은 간단한 소개 · 추천 까닭 · 인상적인 문장을 모아 광고지나 발표 자료로 만들어 반 친구들에게 알린다',ARRAY['6국05-04 문학']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C39','kor',5,2,'u1',14,'인상적인 문장 — 인상적인 문장은 어렵고 긴 문장이 아니라 마음이 움직이거나 깨달음이 생긴 문장이어서, 짧고 쉬운 문장도 내 경험과 이어지면 가장 인상적인 문장이 된다',ARRAY['6국05-04 문학']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u1-C40','kor',5,2,'u1',14,'분류하다 · 분석하다 · 분배하다 — 분류하다(기준에 따라 종류별로 나누거나 묶다) · 분석하다(복잡한 것을 부분으로 나누어 자세히 살피다) · 분배하다(몫으로 나누어 주다)는 모두 「나누다」와 관계있지만 쓰이는 곳이 다르다 (기초 다지기)',ARRAY['기초 다지기(낱말)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X01','kor',5,'u1',ARRAY['K5-2-u1-C1']::text[],'인상적인 부분을 글자 수가 많거나 어려운 낱말이 든 부분으로 여긴다','마음이 움직인 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X02','kor',5,'u1',ARRAY['K5-2-u1-C2']::text[],'작품의 인상적인 부분에는 하나로 정해진 정답이 있다고 여긴다','사람마다 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X03','kor',5,'u1',ARRAY['K5-2-u1-C3']::text[],'인상적인 부분을 고르고 「그냥 좋아서」처럼 까닭을 말하지 않는다','부분과 까닭은 한 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X04','kor',5,'u1',ARRAY['K5-2-u1-C3','K5-2-u1-C2']::text[],'정답이 없으니 작품과 이어지지 않는 아무 까닭이나 대도 된다고 여긴다','까닭은 작품과 이어져야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X05','kor',5,'u1',ARRAY['K5-2-u1-C4','K5-2-u1-C5']::text[],'시와 이야기에서 살필 것을 헷갈리거나, 단원의 활동 차례를 거꾸로 안다','시 → 이야기 → 서평') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X06','kor',5,'u1',ARRAY['K5-2-u1-C6']::text[],'시를 한 번 훑어 읽고 내용과 주제를 다 알았다고 여긴다','여러 번 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X07','kor',5,'u1',ARRAY['K5-2-u1-C10']::text[],'인상적인 부분은 멋진 구절 하나뿐이라 여겨, 말하는 이의 마음이나 분위기는 인상적인 부분이 될 수 없다고 본다','시 전체에서 느낀 것도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X08','kor',5,'u1',ARRAY['K5-2-u1-C8','K5-2-u1-C13']::text[],'내 경험이 떠올라 고른 부분은 작품과 관계없는 내 이야기라서 까닭이 될 수 없다고 여긴다','「나도 그랬지」도 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X09','kor',5,'u1',ARRAY['K5-2-u1-C11','K5-2-u1-C7']::text[],'빗대어 나타낸 표현을 글자 그대로 받아들인다(말이 정말 발자국을 남긴다)','닮은 점을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X10','kor',5,'u1',ARRAY['K5-2-u1-C12','K5-2-u1-C16']::text[],'낭송은 모든 줄을 같은 빠르기로 크게만 읽으면 된다고 여긴다','느낌 따라 빠르기 · 강약') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X11','kor',5,'u1',ARRAY['K5-2-u1-C9','K5-2-u1-C6']::text[],'시의 주제는 제목만 보면 다 알 수 있다고 여겨 시 전체를 살피지 않는다','시 전체에서 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X12','kor',5,'u1',ARRAY['K5-2-u1-C13']::text[],'공감은 시와 똑같은 일을 겪어 본 사람만 할 수 있다고 여긴다','비슷한 마음이면 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X13','kor',5,'u1',ARRAY['K5-2-u1-C14']::text[],'모르는 낱말을 짐작하거나 확인하지 않고 넘어가 뜻을 잘못 안다(괜스레 → 괜찮게)','앞뒤 문장으로 짐작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X14','kor',5,'u1',ARRAY['K5-2-u1-C15']::text[],'말하는 이의 마음은 시의 처음부터 끝까지 같다고 여긴다','연마다 따라가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X15','kor',5,'u1',ARRAY['K5-2-u1-C17']::text[],'친구와 인상적인 부분이 다르면 둘 가운데 한 사람은 잘못 읽은 것이라 여긴다','경험 · 관심사 · 배경지식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X16','kor',5,'u1',ARRAY['K5-2-u1-C18','K5-2-u1-C35']::text[],'친구의 의견을 끝까지 듣지 않거나, 나와 다르면 바로 깎아내린다','끝까지 듣고 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X17','kor',5,'u1',ARRAY['K5-2-u1-C19']::text[],'그림으로 감상할 때 잘 그렸는지가 가장 중요하다고 여긴다','무엇을 왜 골랐나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X18','kor',5,'u1',ARRAY['K5-2-u1-C20']::text[],'전기문을 지어낸 인물의 이야기로 여기거나, 사실을 담은 글이라 감동은 주지 못한다고 여긴다','실제 인물 · 사실 바탕') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X19','kor',5,'u1',ARRAY['K5-2-u1-C21']::text[],'전기문 속 인물의 말과 행동은 모두 그날 그대로 받아 적은 것이라 여긴다','다시 꾸몄을 수도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X20','kor',5,'u1',ARRAY['K5-2-u1-C22']::text[],'인물이 살았던 시대의 상황을 몰라도 인물이 한 일을 이해할 수 있다고 여긴다','때와 곳을 알아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X21','kor',5,'u1',ARRAY['K5-2-u1-C23']::text[],'인물의 말 · 행동을 처한 상황과 잇지 않고 따로 떼어 본다','상황 + 말 · 행동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X22','kor',5,'u1',ARRAY['K5-2-u1-C24']::text[],'이야기에서 인상적인 부분은 가장 큰 사건 한 장면뿐이라 여긴다','흐름 · 변화 · 말 · 분위기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X23','kor',5,'u1',ARRAY['K5-2-u1-C25']::text[],'인물에게 하는 질문을 인상적인 부분과 관계없이 글에 답이 그대로 적힌 것만 만든다','인상적인 부분에서 출발') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X24','kor',5,'u1',ARRAY['K5-2-u1-C26']::text[],'옛날 인물의 이야기는 지금의 나와 아무 관계가 없다고 여긴다','본받을 점 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X25','kor',5,'u1',ARRAY['K5-2-u1-C29','K5-2-u1-C28']::text[],'서평은 책의 줄거리를 처음부터 끝까지 자세히 쓰는 글이라 여긴다','줄거리는 간단히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X26','kor',5,'u1',ARRAY['K5-2-u1-C30']::text[],'서평에는 책의 좋은 점만 써야 한다고 여긴다','아쉬운 점도 까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X27','kor',5,'u1',ARRAY['K5-2-u1-C31','K5-2-u1-C27']::text[],'서평과 독서 감상문을 같은 글로 여긴다','평가와 까닭이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X28','kor',5,'u1',ARRAY['K5-2-u1-C27','K5-2-u1-C30']::text[],'서평의 평가를 「재미있다」처럼 까닭 없이 쓴다','왜 그렇게 평가했나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X29','kor',5,'u1',ARRAY['K5-2-u1-C32']::text[],'서평의 제목은 책 제목을 그대로 쓰면 된다고 여긴다','관심 · 핵심이 드러나게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X30','kor',5,'u1',ARRAY['K5-2-u1-C33']::text[],'서평을 한 번 쓰면 고쳐 쓸 필요가 없다고 여기거나 친구의 의견을 받지 않는다','돌려 읽고 고쳐 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X31','kor',5,'u1',ARRAY['K5-2-u1-C34']::text[],'내가 좋아하는 책이면 어렵거나 한 분야에 치우쳐도 반 친구 모두에게 맞는 「이달의 책」이라 여긴다','반 친구들의 눈으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X32','kor',5,'u1',ARRAY['K5-2-u1-C36']::text[],'의견이 갈리면 목소리가 큰 쪽이나 먼저 말한 쪽으로 정한다','함께 정한 기준에 대어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X33','kor',5,'u1',ARRAY['K5-2-u1-C37']::text[],'내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었다고 여긴다','견주고 조정하는 과정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X34','kor',5,'u1',ARRAY['K5-2-u1-C38']::text[],'소개 자료에는 책 제목만 크게 쓰면 된다고 여긴다','소개 · 까닭 · 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X35','kor',5,'u1',ARRAY['K5-2-u1-C39']::text[],'인상적인 문장은 길고 어려운 낱말이 많은 문장이어야 한다고 여긴다','짧고 쉬운 문장도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u1-X36','kor',5,'u1',ARRAY['K5-2-u1-C40']::text[],'분류하다 · 분석하다 · 분배하다의 뜻을 헷갈려 바꾸어 쓴다','묶기 · 살피기 · 나눠 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#1','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C1',1,'mc','auto','작품에서 「인상적인 부분」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C1","difficulty":1,"kind":"mc","stem":"작품에서 「인상적인 부분」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽으며 마음이 움직이거나 궁금증 · 깨달음이 생기는 부분","correct":true},{"t":"글자 수가 가장 많은 부분","mis":"K5-2-u1-X01"},{"t":"선생님이 정해 주신 한 부분","mis":"K5-2-u1-X02"},{"t":"어려운 낱말이 가장 많이 든 부분","mis":"K5-2-u1-X01"}],"explanation":["길이와는 관계없어요.","정해 준 정답이 있는 게 아니에요.","내 마음이 움직인 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#2','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C2',1,'ox','auto','같은 시를 읽으면 모든 사람의 인상적인 부분이 똑같아요.',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"같은 시를 읽으면 모든 사람의 인상적인 부분이 똑같아요.","answer":"X","reason_options":[{"t":"사람마다 마음에 남는 부분이 다를 수 있기 때문에","correct":true},{"t":"시에는 하나로 정해진 인상적인 부분이 있기 때문에","mis":"K5-2-u1-X02"}],"mis":"K5-2-u1-X02","explanation":["같은 시도 다르게 남아요.","정답이 하나로 정해져 있지 않아요.","그래서 서로 이야기 나눌 거리가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#3','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C2',1,'mc','auto','시우와 나은이가 「우산 셋」에서 고른 부분을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X01']::text[],false,'{"seq":3,"concept":"K5-2-u1-C2","difficulty":1,"kind":"mc","stem":"시우와 나은이가 「우산 셋」에서 고른 부분을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"같은 시를 읽어도 인상적인 부분이 다를 수 있다","correct":true},{"t":"둘 중 한 사람은 시를 잘못 읽었다","mis":"K5-2-u1-X15"},{"t":"인상적인 부분은 첫째 연에만 있다","mis":"K5-2-u1-X02"},{"t":"긴 연을 고른 사람이 더 잘 읽었다","mis":"K5-2-u1-X01"}],"explanation":["잘못 읽은 사람은 없어요.","어느 연이든 될 수 있어요.","고른 곳이 달라도 둘 다 까닭이 있어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#4','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',1,'blank','auto','인상적인 부분을 말할 때에는 고른 부분과 함께 그 부분이 인상적인 (     )을/를 말해요.',ARRAY['K5-2-u1-X01','K5-2-u1-X04']::text[],false,'{"seq":4,"concept":"K5-2-u1-C3","difficulty":1,"kind":"blank","stem":"인상적인 부분을 말할 때에는 고른 부분과 함께 그 부분이 인상적인 (     )을/를 말해요.","options":[{"t":"까닭","correct":true},{"t":"글자 수","mis":"K5-2-u1-X01"},{"t":"쪽수","mis":"K5-2-u1-X04"},{"t":"지은이 나이","mis":"K5-2-u1-X04"}],"explanation":["글자 수는 묻지 않아요.","쪽수는 까닭이 아니에요.","왜 마음에 남았는지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#5','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C1',2,'mc','auto','「우산 셋」을 읽고 고른 인상적인 부분 가운데 「궁금증이 생긴 곳」에 가장 가까운 말은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":5,"concept":"K5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「우산 셋」을 읽고 고른 인상적인 부분 가운데 「궁금증이 생긴 곳」에 가장 가까운 말은 어느 것인가요?","options":[{"t":"「파란 우산은 왜 꽃집 앞에 멈췄을까?」 하고 궁금했어.","correct":true},{"t":"「빨간 우산 이야기가 제일 길어서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「그냥 넷째 연이 좋아.」","mis":"K5-2-u1-X03"},{"t":"「우산이 세 개라서 골랐어.」","mis":"K5-2-u1-X04"}],"explanation":["길이는 까닭이 못 돼요.","까닭이 빠졌어요.","궁금증이 생긴 곳도 인상적인 부분이에요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#6','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',2,'mc','auto','나은이가 「친구 우산 밑으로 쏙 들어갔다」를 고른 까닭은 무엇인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":6,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"나은이가 「친구 우산 밑으로 쏙 들어갔다」를 고른 까닭은 무엇인가요?","options":[{"t":"짝꿍이 우산을 씌워 준 일이 떠올라서","correct":true},{"t":"빗물 튀는 소리가 들리는 것 같아서","mis":"K5-2-u1-X03"},{"t":"시의 맨 처음 연이라서","mis":"K5-2-u1-X04"},{"t":"빨간색을 가장 좋아해서","mis":"K5-2-u1-X04"}],"explanation":["그건 시우가 든 까닭이에요.","그 행은 처음 연이 아니에요.","내 경험이 떠오른 것도 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#7','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C4',2,'match','auto','작품의 종류와 인상적인 부분을 찾을 때 살필 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u1-C4","difficulty":2,"kind":"match","stem":"작품의 종류와 인상적인 부분을 찾을 때 살필 것을 알맞게 이으세요.","pairs":[{"l":"시","r":"표현 · 말하는 이의 마음 · 분위기"},{"l":"이야기","r":"인물 · 사건 · 인물의 말과 행동"},{"l":"서평","r":"책에 대한 평가와 그 까닭"}],"mis":"K5-2-u1-X05","explanation":["시는 표현과 마음을 봐요.","이야기는 인물과 사건을 봐요.","서평은 평가를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#8','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',2,'error','auto','「우산 셋」을 읽고 친구들이 한 말이에요. 인상적인 부분을 알맞게 말하지 못한 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":8,"concept":"K5-2-u1-C3","difficulty":2,"kind":"error","stem":"「우산 셋」을 읽고 친구들이 한 말이에요. 인상적인 부분을 알맞게 말하지 못한 것은 어느 것인가요?","options":[{"t":"「넷째 연이 인상적이야. 이유는 없어.」","correct":true,"mis_target":"K5-2-u1-X03"},{"t":"「넷째 연이 인상적이야. 하늘이 우산을 말려 준다는 말이 다정하게 느껴져.」","mis":"K5-2-u1-X03"},{"t":"「셋째 연이 인상적이야. 친구를 챙기는 모습이 따뜻해서.」","mis":"K5-2-u1-X04"}],"explanation":["까닭이 시 속 말과 이어져요.","까닭이 장면과 이어져요.","부분만 있고 까닭이 없어요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#9','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C5',2,'mc','auto','이 단원에서 배울 내용의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X05']::text[],false,'{"seq":9,"concept":"K5-2-u1-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 배울 내용의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 → 이야기 → 서평 쓰기 → 「이달의 책」 고르기","correct":true},{"t":"서평 쓰기 → 시 → 이야기 → 「이달의 책」 고르기","mis":"K5-2-u1-X05"},{"t":"「이달의 책」 고르기 → 서평 쓰기 → 시","mis":"K5-2-u1-X05"},{"t":"이야기 → 「이달의 책」 고르기 → 시","mis":"K5-2-u1-X05"}],"explanation":["서평은 이야기를 읽은 뒤에 써요.","「이달의 책」은 맨 끝에 골라요.","시에서 시작해 책으로 넓혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_basic#10','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C4',3,'mc','auto','「작품에 대한 의견을 나누어요」 단원에서 가장 중요하게 기를 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X03','K5-2-u1-X15']::text[],false,'{"seq":10,"concept":"K5-2-u1-C4","difficulty":3,"kind":"mc","stem":"「작품에 대한 의견을 나누어요」 단원에서 가장 중요하게 기를 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭을 들어 내 생각을 말하고 친구의 다른 생각도 귀 기울여 듣는 태도","correct":true},{"t":"하나뿐인 정답 부분을 먼저 찾아 외우는 태도","mis":"K5-2-u1-X02"},{"t":"까닭은 빼고 좋아하는 부분만 빨리 말하는 태도","mis":"K5-2-u1-X03"},{"t":"나와 다른 의견은 틀렸다고 알려 주는 태도","mis":"K5-2-u1-X15"}],"explanation":["정답 부분이 따로 있지 않아요.","까닭이 함께 가야 해요.","다른 의견에서 배울 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#1','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C1',2,'mc','auto','다음 가운데 인상적인 부분이 될 수 없는 것은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X01','K5-2-u1-X35']::text[],false,'{"seq":1,"concept":"K5-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 인상적인 부분이 될 수 없는 것은 어느 것인가요?","options":[{"t":"읽었는데 아무 느낌도 남지 않은 부분","correct":true},{"t":"내 경험이 떠올라 고개가 끄덕여진 부분","mis":"K5-2-u1-X08"},{"t":"「왜 그럴까?」 하고 궁금해진 부분","mis":"K5-2-u1-X01"},{"t":"짧지만 오래 기억에 남는 문장","mis":"K5-2-u1-X35"}],"explanation":["경험이 떠오른 곳도 인상적이에요.","궁금증이 생긴 곳도 인상적이에요.","짧은 문장도 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#2','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C4',2,'ox','auto','정답이 하나가 아니니까 작품과 아무 관계없는 까닭을 대도 괜찮아요.',ARRAY['K5-2-u1-X04']::text[],false,'{"seq":2,"concept":"K5-2-u1-C4","difficulty":2,"kind":"ox","stem":"정답이 하나가 아니니까 작품과 아무 관계없는 까닭을 대도 괜찮아요.","answer":"X","reason_options":[{"t":"까닭은 작품 속 말이나 장면, 그와 이어진 내 경험과 닿아 있어야 하기 때문에","correct":true},{"t":"인상적인 부분은 사람마다 다르니 무엇이든 까닭이 되기 때문에","mis":"K5-2-u1-X04"}],"mis":"K5-2-u1-X04","explanation":["정답이 없다는 말이 아무거나라는 뜻은 아니에요.","작품과 이어져야 서로 이해해요.","열려 있되 까닭은 작품에 닿아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#3','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C3',3,'mc','auto','시우의 까닭 「빗물 튀는 소리가 들리는 것 같아」는 시의 어느 말과 이어지나요?',ARRAY['K5-2-u1-X04']::text[],false,'{"seq":3,"concept":"K5-2-u1-C3","difficulty":3,"kind":"mc","stem":"시우의 까닭 「빗물 튀는 소리가 들리는 것 같아」는 시의 어느 말과 이어지나요?","options":[{"t":"「폴짝폴짝」","correct":true},{"t":"「느릿느릿」","mis":"K5-2-u1-X04"},{"t":"「나란히」","mis":"K5-2-u1-X04"},{"t":"「쏙」","mis":"K5-2-u1-X04"}],"explanation":["「느릿느릿」은 파란 우산이에요.","「나란히」는 넷째 연이에요.","뛰어 건너는 소리를 흉내 낸 말이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#4','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',3,'mc','auto','시우와 나은이의 말에서 알 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X08','K5-2-u1-X15']::text[],false,'{"seq":4,"concept":"K5-2-u1-C2","difficulty":3,"kind":"mc","stem":"시우와 나은이의 말에서 알 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고른 부분이 달라도 까닭이 있으면 둘 다 의미 있는 감상이다","correct":true},{"t":"먼저 말한 시우의 감상이 정답이다","mis":"K5-2-u1-X02"},{"t":"나은이는 시와 상관없는 이야기를 했다","mis":"K5-2-u1-X08"},{"t":"고른 부분이 다르면 다시 읽어 하나로 맞춰야 한다","mis":"K5-2-u1-X15"}],"explanation":["먼저 말했다고 정답이 아니에요.","경험이 떠오른 것도 까닭이에요.","하나로 맞출 필요가 없어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#5','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C4',3,'mc','auto','이야기를 읽고 인상적인 부분을 찾을 때 가장 먼저 살필 것은 어느 것인가요?',ARRAY['K5-2-u1-X05','K5-2-u1-X01']::text[],false,'{"seq":5,"concept":"K5-2-u1-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 인상적인 부분을 찾을 때 가장 먼저 살필 것은 어느 것인가요?","options":[{"t":"인물이 처한 상황과 그때 한 말이나 행동","correct":true},{"t":"행마다 반복되는 흉내 내는 말의 개수","mis":"K5-2-u1-X05"},{"t":"책의 쪽수와 글씨 크기","mis":"K5-2-u1-X01"},{"t":"연과 행이 몇 개인지","mis":"K5-2-u1-X05"}],"explanation":["그건 시의 표현을 볼 때예요.","쪽수는 감상과 관계없어요.","이야기는 인물과 사건을 따라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#6','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',3,'error','auto','「우산 셋」을 읽고 나눈 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X16','K5-2-u1-X03']::text[],false,'{"seq":6,"concept":"K5-2-u1-C2","difficulty":3,"kind":"error","stem":"「우산 셋」을 읽고 나눈 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「다들 첫째 연을 골라야 맞아. 시의 처음이니까.」","correct":true,"mis_target":"K5-2-u1-X02"},{"t":"「나는 넷째 연이 다정해서 골랐는데, 네가 고른 연도 들어 볼래.」","mis":"K5-2-u1-X16"},{"t":"「나는 셋째 연을 골랐어. 친구를 챙기는 모습이 좋아서.」","mis":"K5-2-u1-X03"}],"explanation":["다른 생각도 들으려 해요.","부분과 까닭을 함께 말했어요.","처음 연이 정답인 것은 아니에요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#7','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C5',3,'mc','auto','이 단원의 마지막 활동인 「이달의 책」 고르기에 앞에서 배운 것이 쓰이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X05','K5-2-u1-X34','K5-2-u1-X31']::text[],false,'{"seq":7,"concept":"K5-2-u1-C5","difficulty":3,"kind":"mc","stem":"이 단원의 마지막 활동인 「이달의 책」 고르기에 앞에서 배운 것이 쓰이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책을 추천할 때 인상적인 부분과 그 까닭을 들어 말해야 하기 때문에","correct":true},{"t":"「이달의 책」은 시집만 고를 수 있기 때문에","mis":"K5-2-u1-X05"},{"t":"책 제목만 알면 고를 수 있기 때문에","mis":"K5-2-u1-X34"},{"t":"가장 두꺼운 책을 골라야 하기 때문에","mis":"K5-2-u1-X31"}],"explanation":["시집만 고르는 게 아니에요.","제목만으로는 추천이 안 돼요.","두께는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#8','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C3',4,'essay','teacher','「우산 셋」에서 내가 고른 인상적인 부분을 하나 쓰고, 그 부분이 인상적인 까닭을 시 속 말과 이어서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「우산 셋」에서 내가 고른 인상적인 부분을 하나 쓰고, 그 부분이 인상적인 까닭을 시 속 말과 이어서 쓰세요.","answer_guide":{"answer":"예: 넷째 연 「비 그친 하늘이 / 세 우산을 나란히 말려 준다」가 인상적이다. 하늘이 사람처럼 우산을 말려 준다는 말에서 비가 그친 뒤의 맑고 다정한 느낌이 들기 때문이다. 서로 다른 길을 간 우산들이 마지막에 나란히 놓이는 모습도 따뜻하게 느껴졌다.","scoring_points":["인상적인 부분을 시에서 골라 썼는가","까닭을 썼는가","까닭이 시 속 말이나 장면과 이어지는가"]},"explanation":["한 부분을 골라요.","왜 남았는지 써요.","시 속 말과 이어요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#9','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',4,'essay','teacher','「인상적인 부분에는 정답이 없지만, 아무거나 골라도 되는 것은 아니다」라는 말의 뜻을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「인상적인 부분에는 정답이 없지만, 아무거나 골라도 되는 것은 아니다」라는 말의 뜻을 쓰세요.","answer_guide":{"answer":"예: 같은 작품을 읽어도 사람마다 경험과 생각이 달라 마음에 남는 부분이 다를 수 있으므로 정답이 하나로 정해져 있지 않다. 하지만 그 부분이 왜 인상적인지 작품 속 말이나 장면, 그와 이어진 내 경험으로 까닭을 대야 친구도 내 생각을 이해할 수 있다. 까닭 없이 고르거나 작품과 상관없는 까닭을 대는 것은 감상이라고 하기 어렵다.","scoring_points":["정답이 없는 까닭을 썼는가","까닭이 작품과 이어져야 함을 썼는가","두 가지를 함께 정리했는가"]},"explanation":["사람마다 다른 까닭을 떠올려요.","까닭의 조건을 써요.","두 말을 이어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L01_challenge#10','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C1',4,'essay','teacher','내가 재미있게 읽었던 이야기나 시를 하나 떠올려, 인상적인 부분이 「마음이 움직인 곳 · 궁금증이 생긴 곳 · 깨달음이 생긴 곳」 가운데 어디에 가까운지 쓰고 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C1","difficulty":4,"kind":"essay","stem":"내가 재미있게 읽었던 이야기나 시를 하나 떠올려, 인상적인 부분이 「마음이 움직인 곳 · 궁금증이 생긴 곳 · 깨달음이 생긴 곳」 가운데 어디에 가까운지 쓰고 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 동화에서 주인공이 잃어버린 강아지를 찾으려고 비 오는 밤에 골목을 헤매는 장면이 인상적이었다. 마음이 움직인 곳에 가깝다. 강아지를 애타게 부르는 주인공의 목소리가 들리는 것 같아 나도 가슴이 조마조마했기 때문이다.","scoring_points":["작품과 인상적인 부분을 썼는가","세 가지 가운데 하나를 골랐는가","까닭을 작품과 이어 썼는가"]},"explanation":["읽은 작품을 떠올려요.","어떤 마음이 들었는지 골라요.","까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#1','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C6',1,'mc','auto','「말의 온도」에서 따뜻한 말을 들었을 때의 모습은 어떠한가요?',ARRAY['K5-2-u1-X06','K5-2-u1-X09']::text[],false,'{"seq":1,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「말의 온도」에서 따뜻한 말을 들었을 때의 모습은 어떠한가요?","options":[{"t":"두 볼이 발그레해진다","correct":true},{"t":"어깨가 움츠러든다","mis":"K5-2-u1-X06"},{"t":"마음이 따끔따끔하다","mis":"K5-2-u1-X06"},{"t":"발자국이 찍힌다","mis":"K5-2-u1-X09"}],"explanation":["차가운 말을 들었을 때예요.","뾰족한 말을 들었을 때예요.","따뜻한 말은 볼을 발그레하게 해요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#2','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C9',1,'mc','auto','「말의 온도」의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X11','K5-2-u1-X09','K5-2-u1-X06']::text[],false,'{"seq":2,"concept":"K5-2-u1-C9","difficulty":1,"kind":"mc","stem":"「말의 온도」의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 듣는 사람의 마음에 남으니 조심해서 말해야 한다","correct":true},{"t":"겨울에는 따뜻하게 입어야 한다","mis":"K5-2-u1-X11"},{"t":"발자국은 사뿐사뿐 남겨야 한다","mis":"K5-2-u1-X09"},{"t":"뾰족한 물건은 위험하다","mis":"K5-2-u1-X06"}],"explanation":["온도는 날씨 이야기가 아니에요.","발자국은 빗댄 말이에요.","마지막 연에 하고 싶은 말이 드러나요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#3','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C7',1,'ox','auto','「따끔따끔」처럼 느낌을 흉내 낸 말도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X01']::text[],false,'{"seq":3,"concept":"K5-2-u1-C7","difficulty":1,"kind":"ox","stem":"「따끔따끔」처럼 느낌을 흉내 낸 말도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"독특하고 재미있는 표현은 읽는 사람의 마음에 남기 쉽기 때문에","correct":true},{"t":"흉내 내는 말은 쉬운 말이라 인상적일 수 없기 때문에","mis":"K5-2-u1-X01"}],"mis":"K5-2-u1-X01","explanation":["쉬운 말도 마음에 남아요.","느낌이 살아나는 표현이에요.","표현이 주는 느낌까지 말해요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#4','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C7',1,'match','auto','인상적인 부분을 찾는 방법과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-2-u1-C7","difficulty":1,"kind":"match","stem":"인상적인 부분을 찾는 방법과 그 예를 알맞게 이으세요.","pairs":[{"l":"독특하고 재미있는 표현","r":"「마음이 따끔따끔」이 바늘에 찔린 듯 느껴져서"},{"l":"내 경험과 이어지는 공감","r":"나도 차가운 말을 듣고 어깨가 움츠러든 적이 있어서"},{"l":"주제가 잘 드러나는 부분","r":"「사뿐사뿐 디뎌야 해」에 하고 싶은 말이 담겨서"}],"mis":"K5-2-u1-X08","explanation":["표현의 느낌을 말했어요.","내 경험을 말했어요.","하고 싶은 말을 짚었어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#5','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C11',2,'mc','auto','「말은 마음에 찍히는 발자국」에서 말과 발자국의 닮은 점은 무엇인가요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":5,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「말은 마음에 찍히는 발자국」에서 말과 발자국의 닮은 점은 무엇인가요?","options":[{"t":"한번 남으면 쉽게 지워지지 않는다","correct":true},{"t":"둘 다 발로 만든다","mis":"K5-2-u1-X09"},{"t":"둘 다 눈 위에만 생긴다","mis":"K5-2-u1-X09"},{"t":"둘 다 소리가 크다","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로 읽지 않아요.","눈 이야기가 아니에요.","마음에 남는다는 점이 닮았어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#6','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C8',2,'error','auto','「말의 온도」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X03','K5-2-u1-X09']::text[],false,'{"seq":6,"concept":"K5-2-u1-C8","difficulty":2,"kind":"error","stem":"「말의 온도」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「내 경험이 떠올라 고른 건 시와 상관없으니 까닭이 안 돼.」","correct":true,"mis_target":"K5-2-u1-X08"},{"t":"「친구에게 따뜻한 말을 듣고 볼이 뜨거워진 적이 있어서 첫째 연을 골랐어.」","mis":"K5-2-u1-X03"},{"t":"「발자국에 빗댄 말이 새로워서 마지막 연을 골랐어.」","mis":"K5-2-u1-X09"}],"explanation":["경험과 이어진 좋은 까닭이에요.","표현을 까닭으로 들었어요.","내 경험이 떠오른 것도 까닭이 돼요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#7','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C10',2,'mc','auto','「말의 온도」에서 시 전체를 읽고 느낀 것을 인상적인 부분으로 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X11']::text[],false,'{"seq":7,"concept":"K5-2-u1-C10","difficulty":2,"kind":"mc","stem":"「말의 온도」에서 시 전체를 읽고 느낀 것을 인상적인 부분으로 말한 것은 어느 것인가요?","options":[{"t":"「말을 조심하자고 다정하게 타이르는 듯한 분위기가 좋아.」","correct":true},{"t":"「〈발그레〉라는 낱말이 어려워서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「셋째 연이 가장 길어서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「제목에 온도가 들어가서 날씨 시인 줄 알았어.」","mis":"K5-2-u1-X11"}],"explanation":["어려운 낱말이 까닭이 아니에요.","길이는 까닭이 아니에요.","분위기도 인상적인 부분이 돼요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#8','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C12',2,'mc','auto','「마음이 따끔따끔」의 느낌을 살려 낭송하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":8,"concept":"K5-2-u1-C12","difficulty":2,"kind":"mc","stem":"「마음이 따끔따끔」의 느낌을 살려 낭송하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「따끔따끔」을 짧게 끊어 또렷하게 읽는다","correct":true},{"t":"모든 행을 같은 빠르기로 크게 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 작은 소리로 웅얼거린다","mis":"K5-2-u1-X10"},{"t":"「따끔따끔」만 빼고 읽는다","mis":"K5-2-u1-X10"}],"explanation":["같은 소리로만 읽으면 느낌이 안 살아요.","들리지 않으면 느낌도 안 전해져요.","찔리는 느낌을 소리로 살려요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#9','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C6',2,'blank','auto','시는 (     ) 읽으며 장면을 떠올리고, 다시 읽고 싶은 부분을 찾아요.',ARRAY['K5-2-u1-X06','K5-2-u1-X11']::text[],false,'{"seq":9,"concept":"K5-2-u1-C6","difficulty":2,"kind":"blank","stem":"시는 (     ) 읽으며 장면을 떠올리고, 다시 읽고 싶은 부분을 찾아요.","options":[{"t":"여러 번","correct":true},{"t":"한 번만 훑어","mis":"K5-2-u1-X06"},{"t":"제목만","mis":"K5-2-u1-X11"},{"t":"거꾸로","mis":"K5-2-u1-X06"}],"explanation":["한 번으로는 놓치는 게 많아요.","제목만으로는 부족해요.","읽을수록 새로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_basic#10','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C3',3,'mc','auto','「말의 온도」에서 인상적인 부분을 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04','K5-2-u1-X07']::text[],false,'{"seq":10,"concept":"K5-2-u1-C3","difficulty":3,"kind":"mc","stem":"「말의 온도」에서 인상적인 부분을 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「〈사뿐사뿐 디뎌야 해〉가 인상적이야. 친구 마음을 밟지 않게 말을 고르라는 뜻 같아서.」","correct":true},{"t":"「셋째 연이 인상적이야. 그냥.」","mis":"K5-2-u1-X03"},{"t":"「첫째 연이 인상적이야. 오늘 점심이 맛있었거든.」","mis":"K5-2-u1-X04"},{"t":"「모든 연이 똑같이 인상적이야.」","mis":"K5-2-u1-X07"}],"explanation":["까닭이 빠졌어요.","까닭이 시와 이어지지 않아요.","부분과 까닭이 시 속 말로 이어져요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#1','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C11',2,'mc','auto','「뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다」를 바르게 이해한 것은 어느 것인가요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":1,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다」를 바르게 이해한 것은 어느 것인가요?","options":[{"t":"연필을 깎으니 생각도 또렷해지는 것 같다는 느낌을 빗댄 말이다","correct":true},{"t":"머릿속에 연필깎이가 들어 있다는 말이다","mis":"K5-2-u1-X09"},{"t":"생각이 아파서 따끔거린다는 말이다","mis":"K5-2-u1-X09"},{"t":"연필이 생각을 한다는 말이다","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로가 아니에요.","아프다는 말은 없어요.","또렷해지는 느낌이 닮았어요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#2','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C7',2,'mc','auto','「연필깎이」에서 소리를 흉내 낸 재미있는 표현은 어느 것인가요?',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":2,"concept":"K5-2-u1-C7","difficulty":2,"kind":"mc","stem":"「연필깎이」에서 소리를 흉내 낸 재미있는 표현은 어느 것인가요?","options":[{"t":"드르륵드르륵","correct":true},{"t":"뭉툭한","mis":"K5-2-u1-X07"},{"t":"금방","mis":"K5-2-u1-X07"},{"t":"딱 한 번","mis":"K5-2-u1-X07"}],"explanation":["모양을 나타내는 말이에요.","때를 나타내는 말이에요.","깎는 소리를 흉내 냈어요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#3','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C9',3,'mc','auto','「연필깎이」에서 말하는 이의 생각이 가장 잘 드러난 부분은 어느 것인가요?',ARRAY['K5-2-u1-X11','K5-2-u1-X06']::text[],false,'{"seq":3,"concept":"K5-2-u1-C9","difficulty":3,"kind":"mc","stem":"「연필깎이」에서 말하는 이의 생각이 가장 잘 드러난 부분은 어느 것인가요?","options":[{"t":"「오늘은 / 딱 한 번만 돌려야지」","correct":true},{"t":"「드르륵드르륵 / 연필깎이가 노래하면」","mis":"K5-2-u1-X11"},{"t":"제목 「연필깎이」","mis":"K5-2-u1-X11"},{"t":"「뭉툭한 내 생각도」","mis":"K5-2-u1-X06"}],"explanation":["소리를 나타낸 부분이에요.","제목만으로는 생각을 다 알 수 없어요.","아껴 쓰겠다는 다짐이 드러나요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#4','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C10',3,'ox','auto','「연필깎이」에서는 짧아질까 봐 아끼려는 말하는 이의 마음도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":4,"concept":"K5-2-u1-C10","difficulty":3,"kind":"ox","stem":"「연필깎이」에서는 짧아질까 봐 아끼려는 말하는 이의 마음도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"인상적인 부분은 구절만이 아니라 말하는 이의 마음이나 분위기도 될 수 있기 때문에","correct":true},{"t":"인상적인 부분은 멋진 낱말이 든 한 구절뿐이기 때문에","mis":"K5-2-u1-X07"}],"mis":"K5-2-u1-X07","explanation":["마음도 인상적인 부분이에요.","시 전체에서 느낀 것도 돼요.","구절에만 머물지 않아요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#5','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C12',3,'match','auto','「연필깎이」의 연과 어울리는 낭송 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-2-u1-C12","difficulty":3,"kind":"match","stem":"「연필깎이」의 연과 어울리는 낭송 방법을 알맞게 이으세요.","pairs":[{"l":"첫째 연","r":"「드르륵드르륵」을 경쾌하게 빠르게"},{"l":"셋째 연","r":"「너무 깎으면」에서 조금 느리고 걱정스럽게"},{"l":"넷째 연","r":"「딱 한 번만」을 또박또박 다짐하듯"}],"mis":"K5-2-u1-X10","explanation":["신나는 소리는 빠르게 살려요.","걱정이 드는 곳은 느리게 읽어요.","다짐은 또박또박 읽어요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#6','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C3',3,'error','auto','「연필깎이」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X08','K5-2-u1-X07']::text[],false,'{"seq":6,"concept":"K5-2-u1-C3","difficulty":3,"kind":"error","stem":"「연필깎이」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「넷째 연이 인상적이다. 나는 연필보다 볼펜을 좋아하기 때문이다.」","correct":true,"mis_target":"K5-2-u1-X04"},{"t":"「셋째 연이 인상적이다. 나도 새 연필을 재미 삼아 깎다가 몽당연필로 만든 적이 있다.」","mis":"K5-2-u1-X08"},{"t":"「첫째 연이 인상적이다. 연필깎이가 노래한다는 표현이 재미있다.」","mis":"K5-2-u1-X07"}],"explanation":["경험과 이어진 까닭이에요.","표현과 이어진 까닭이에요.","까닭이 시의 내용과 이어지지 않아요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#7','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C8',3,'mc','auto','「말의 온도」의 둘째 연 「차가운 말 들으면 / 어깨가 움츠러들고」에 공감한 친구가 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X01','K5-2-u1-X02']::text[],false,'{"seq":7,"concept":"K5-2-u1-C8","difficulty":3,"kind":"mc","stem":"「말의 온도」의 둘째 연 「차가운 말 들으면 / 어깨가 움츠러들고」에 공감한 친구가 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「놀림을 받았을 때 나도 어깨가 저절로 움츠러들었어.」","correct":true},{"t":"「겨울에 손이 시려서 장갑을 꼈어.」","mis":"K5-2-u1-X09"},{"t":"「어깨라는 낱말이 들어가서 좋아.」","mis":"K5-2-u1-X01"},{"t":"「둘째 연은 정답이 아니라서 공감하면 안 돼.」","mis":"K5-2-u1-X02"}],"explanation":["차가운 말 이야기예요, 날씨가 아니에요.","낱말 하나로는 공감이 아니에요.","비슷한 일을 떠올렸어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#8','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C11',4,'essay','teacher','「말은 마음에 찍히는 발자국」이라는 표현이 무엇을 무엇에 빗댄 것인지 쓰고, 둘의 닮은 점과 이 표현이 인상적인 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C11","difficulty":4,"kind":"essay","stem":"「말은 마음에 찍히는 발자국」이라는 표현이 무엇을 무엇에 빗댄 것인지 쓰고, 둘의 닮은 점과 이 표현이 인상적인 까닭을 쓰세요.","answer_guide":{"answer":"예: 말을 발자국에 빗댄 표현이다. 발자국이 땅에 찍혀 오래 남듯이 말도 듣는 사람의 마음에 남아 쉽게 지워지지 않는다는 점이 닮았다. 내가 친구에게 무심코 한 말이 오래 마음에 남았다는 이야기를 들은 적이 있어서, 이 표현을 읽고 말을 조심해야겠다는 생각이 들어 인상적이었다.","scoring_points":["무엇을 무엇에 빗댔는지 썼는가","닮은 점을 썼는가","인상적인 까닭을 썼는가"]},"explanation":["빗댄 두 가지를 찾아요.","닮은 점을 생각해요.","까닭을 경험과 이어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#9','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C12',4,'essay','teacher','「말의 온도」에서 인상적인 부분을 하나 고르고, 그 느낌을 살려 낭송하려면 빠르기 · 목소리를 어떻게 하면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C12","difficulty":4,"kind":"essay","stem":"「말의 온도」에서 인상적인 부분을 하나 고르고, 그 느낌을 살려 낭송하려면 빠르기 · 목소리를 어떻게 하면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 넷째 연 「말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해」를 골랐다. 앞의 연보다 조금 느리게, 부드럽고 낮은 목소리로 읽겠다. 「사뿐사뿐」에서는 발끝으로 걷듯 살짝 끊어 읽겠다. 말을 조심하자고 다정하게 타이르는 느낌이 잘 살아나기 때문이다.","scoring_points":["인상적인 부분을 골랐는가","빠르기와 목소리를 정했는가","느낌과 이어진 까닭을 썼는가"]},"explanation":["한 연을 골라요.","어떻게 읽을지 정해요.","그 느낌과 이어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L02_challenge#10','kor',5,2,'u1','L02','g5_2_kor_u1_L02_challenge','lesson_challenge','K5-2-u1-C9',4,'essay','teacher','「연필깎이」의 주제를 한 문장으로 쓰고, 주제가 잘 드러난 부분과 그 부분을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C9","difficulty":4,"kind":"essay","stem":"「연필깎이」의 주제를 한 문장으로 쓰고, 주제가 잘 드러난 부분과 그 부분을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 주제 — 물건을 아껴 쓰자. 주제가 잘 드러난 부분은 넷째 연 「오늘은 / 딱 한 번만 돌려야지」이다. 셋째 연에서 너무 깎으면 연필이 짧아진다는 것을 깨닫고, 마지막에 한 번만 돌리겠다고 다짐하는 데에서 아껴 쓰려는 마음이 가장 또렷하게 보이기 때문이다.","scoring_points":["주제를 한 문장으로 썼는가","주제가 드러난 부분을 골랐는가","까닭을 시의 흐름과 이어 썼는가"]},"explanation":["하고 싶은 말을 찾아요.","그 말이 드러난 연을 골라요.","앞 연과 이어 까닭을 써요."],"asset":{"type":"passage","lines":["드르륵드르륵 / 연필깎이가 노래하면","뭉툭한 내 생각도 / 뾰족하게 깎이는 것 같다","그런데 너무 깎으면 / 연필이 금방 짧아지지","오늘은 / 딱 한 번만 돌려야지"],"title":"시 「연필깎이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#1','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C14',1,'mc','auto','「괜찮아, 나」에 나온 「괜스레」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X13']::text[],false,'{"seq":1,"concept":"K5-2-u1-C14","difficulty":1,"kind":"mc","stem":"「괜찮아, 나」에 나온 「괜스레」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭이나 실속 없이","correct":true},{"t":"괜찮게, 아무렇지 않게","mis":"K5-2-u1-X13"},{"t":"아주 빠르게","mis":"K5-2-u1-X13"},{"t":"조심스럽게","mis":"K5-2-u1-X13"}],"explanation":["「괜찮다」와 소리만 비슷해요.","빠르기를 뜻하지 않아요.","까닭 없이 문지르는 마음이에요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#2','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C15',1,'mc','auto','「괜찮아, 나」에서 말하는 이가 처음에 겪은 일은 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":2,"concept":"K5-2-u1-C15","difficulty":1,"kind":"mc","stem":"「괜찮아, 나」에서 말하는 이가 처음에 겪은 일은 무엇인가요?","options":[{"t":"틀린 글씨를 지우다가 종이가 찢어졌다","correct":true},{"t":"지우개를 잃어버렸다","mis":"K5-2-u1-X06"},{"t":"친구와 다투었다","mis":"K5-2-u1-X06"},{"t":"시험에서 백 점을 받았다","mis":"K5-2-u1-X06"}],"explanation":["지우개는 손에 있어요.","친구 이야기는 없어요.","첫째 연에 나와요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#3','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C15',1,'ox','auto','「괜찮아, 나」에서 말하는 이의 마음은 처음부터 끝까지 똑같아요.',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":3,"concept":"K5-2-u1-C15","difficulty":1,"kind":"ox","stem":"「괜찮아, 나」에서 말하는 이의 마음은 처음부터 끝까지 똑같아요.","answer":"X","reason_options":[{"t":"속상하고 답답하던 마음이 마지막 연에서 스스로를 달래는 마음으로 바뀌기 때문에","correct":true},{"t":"시 속 말하는 이의 마음은 늘 하나로 정해져 있기 때문에","mis":"K5-2-u1-X14"}],"mis":"K5-2-u1-X14","explanation":["연마다 마음을 따라가요.","마지막 연에서 달라져요.","말하는 이의 마음도 흘러가요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#4','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C15',1,'match','auto','「괜찮아, 나」의 연과 말하는 이의 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-2-u1-C15","difficulty":1,"kind":"match","stem":"「괜찮아, 나」의 연과 말하는 이의 마음을 알맞게 이으세요.","pairs":[{"l":"첫째 연 — 종이가 북 찢어졌다","r":"속상함"},{"l":"둘째 연 — 지우개만 박박 문지른다","r":"답답함"},{"l":"넷째 연 — 나에게 말해 본다","r":"스스로 달래기"}],"mis":"K5-2-u1-X14","explanation":["놀라고 속상해요.","어쩔 줄 몰라 답답해요.","스스로 다독여요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#5','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C17',2,'mc','auto','다인이와 로운이가 고른 인상적인 부분이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":5,"concept":"K5-2-u1-C17","difficulty":2,"kind":"mc","stem":"다인이와 로운이가 고른 인상적인 부분이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"둘의 경험과 관심이 서로 달라서","correct":true},{"t":"둘 중 한 사람이 시를 잘못 읽어서","mis":"K5-2-u1-X15"},{"t":"시에 인상적인 부분이 하나뿐이어서","mis":"K5-2-u1-X02"},{"t":"둘 다 까닭을 말하지 않아서","mis":"K5-2-u1-X03"}],"explanation":["잘못 읽은 사람은 없어요.","정답 부분이 하나인 게 아니에요.","둘 다 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#6','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C18',2,'mc','auto','다인이와 로운이가 의견을 나눈 뒤 생긴 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X02','K5-2-u1-X15']::text[],false,'{"seq":6,"concept":"K5-2-u1-C18","difficulty":2,"kind":"mc","stem":"다인이와 로운이가 의견을 나눈 뒤 생긴 일로 알맞은 것은 어느 것인가요?","options":[{"t":"친구의 의견을 듣고 시를 새로운 관점으로 다시 보게 되었다","correct":true},{"t":"서로 다른 의견 때문에 시가 싫어졌다","mis":"K5-2-u1-X16"},{"t":"먼저 말한 다인이의 의견만 맞게 되었다","mis":"K5-2-u1-X02"},{"t":"둘 다 고른 부분을 바꾸어야 했다","mis":"K5-2-u1-X15"}],"explanation":["다른 의견이 시를 넓혀 줬어요.","먼저 말한 의견이 정답은 아니에요.","바꿀 필요는 없어요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#7','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C13',2,'mc','auto','공감하며 읽은 시를 친구에게 소개할 때 함께 말하면 좋은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X01']::text[],false,'{"seq":7,"concept":"K5-2-u1-C13","difficulty":2,"kind":"mc","stem":"공감하며 읽은 시를 친구에게 소개할 때 함께 말하면 좋은 것은 어느 것인가요?","options":[{"t":"그 시에 공감한 까닭","correct":true},{"t":"시가 실린 책의 값","mis":"K5-2-u1-X03"},{"t":"시를 읽은 시각","mis":"K5-2-u1-X03"},{"t":"시의 글자 수","mis":"K5-2-u1-X01"}],"explanation":["값은 공감과 관계없어요.","시각은 까닭이 아니에요.","왜 공감했는지 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#8','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C16',2,'blank','auto','「괜찮아, 나」를 낭송할 때 마지막 「괜찮아」는 마음이 바뀌는 곳이므로 (     ) 읽으면 좋아요.',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":8,"concept":"K5-2-u1-C16","difficulty":2,"kind":"blank","stem":"「괜찮아, 나」를 낭송할 때 마지막 「괜찮아」는 마음이 바뀌는 곳이므로 (     ) 읽으면 좋아요.","options":[{"t":"천천히 다독이듯","correct":true},{"t":"가장 빠르게 소리치듯","mis":"K5-2-u1-X10"},{"t":"앞 연과 똑같은 빠르기로","mis":"K5-2-u1-X10"},{"t":"아주 작게 웅얼거리듯","mis":"K5-2-u1-X10"}],"explanation":["달래는 마음과 어울리지 않아요.","마음이 바뀌는 곳은 다르게 읽어요.","스스로를 달래는 느낌을 살려요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#9','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C19',2,'mc','auto','「방학 마지막 날」을 그림으로 감상할 때 가장 중요한 것은 어느 것인가요?',ARRAY['K5-2-u1-X17','K5-2-u1-X02']::text[],false,'{"seq":9,"concept":"K5-2-u1-C19","difficulty":2,"kind":"mc","stem":"「방학 마지막 날」을 그림으로 감상할 때 가장 중요한 것은 어느 것인가요?","options":[{"t":"어떤 부분을 왜 골라 그렸는지 말하는 것","correct":true},{"t":"누가 가장 잘 그렸는지 겨루는 것","mis":"K5-2-u1-X17"},{"t":"모두 같은 장면을 그리는 것","mis":"K5-2-u1-X02"},{"t":"색칠을 빈틈없이 하는 것","mis":"K5-2-u1-X17"}],"explanation":["솜씨를 겨루는 활동이 아니에요.","고른 장면은 달라도 돼요.","고른 부분과 까닭이 중요해요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_basic#10','kor',5,2,'u1','L04','g5_2_kor_u1_L04_basic','lesson_basic','K5-2-u1-C14',3,'mc','auto','「괜스레」를 넣어 만든 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X13']::text[],false,'{"seq":10,"concept":"K5-2-u1-C14","difficulty":3,"kind":"mc","stem":"「괜스레」를 넣어 만든 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말을 꺼내기 어려워서 괜스레 연필만 만지작거렸다.","correct":true},{"t":"숙제를 다 해서 괜스레 마음이 놓였다.","mis":"K5-2-u1-X13"},{"t":"넘어졌지만 괜스레 다치지 않았다.","mis":"K5-2-u1-X13"},{"t":"비가 와서 괜스레 우산을 썼다.","mis":"K5-2-u1-X13"}],"explanation":["까닭이 분명히 있는 일이에요.","「괜찮게」로 잘못 썼어요.","까닭이 분명한 일에는 어울리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#1','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C15',2,'mc','auto','「괜찮아, 나」에서 말하는 이의 행동이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X14','K5-2-u1-X06']::text[],false,'{"seq":1,"concept":"K5-2-u1-C15","difficulty":2,"kind":"mc","stem":"「괜찮아, 나」에서 말하는 이의 행동이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?","options":[{"t":"지우개를 박박 문지르다가, 손바닥으로 종이를 펴며 스스로를 달랜다","correct":true},{"t":"처음부터 끝까지 지우개만 문지른다","mis":"K5-2-u1-X14"},{"t":"종이를 펴다가 다시 찢어 버린다","mis":"K5-2-u1-X14"},{"t":"친구에게 새 종이를 빌린다","mis":"K5-2-u1-X06"}],"explanation":["행동이 바뀌어요.","찢어 버리지 않았어요.","친구 이야기는 없어요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#2','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C17',2,'mc','auto','같은 시에서 친구마다 까닭이 다른 이유가 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C17","difficulty":2,"kind":"mc","stem":"같은 시에서 친구마다 까닭이 다른 이유가 아닌 것은 어느 것인가요?","options":[{"t":"한 사람만 시를 바르게 읽었기 때문에","correct":true},{"t":"겪어 본 일이 달라서","mis":"K5-2-u1-X15"},{"t":"관심 있는 것이 달라서","mis":"K5-2-u1-X15"},{"t":"알고 있는 배경지식이 달라서","mis":"K5-2-u1-X15"}],"explanation":["경험이 다르면 까닭도 달라요.","관심이 다르면 눈길이 가는 곳도 달라요.","바르게 읽은 사람이 한 명뿐인 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#3','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C18',3,'error','auto','다인이와 로운이처럼 모둠에서 의견을 나누었어요. 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X15','K5-2-u1-X03']::text[],false,'{"seq":3,"concept":"K5-2-u1-C18","difficulty":3,"kind":"error","stem":"다인이와 로운이처럼 모둠에서 의견을 나누었어요. 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"「내 생각과 다르니까 네 말은 들을 필요가 없어.」","correct":true,"mis_target":"K5-2-u1-X16"},{"t":"「네가 고른 부분은 나와 다르지만, 그 까닭을 들으니 새롭게 보여.」","mis":"K5-2-u1-X15"},{"t":"「너는 왜 그 연을 골랐는지 끝까지 들어 볼게.」","mis":"K5-2-u1-X03"}],"explanation":["다른 의견에서 배웠어요.","끝까지 들으려 해요.","다른 의견을 끝까지 듣고 견줘요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#4','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C13',3,'mc','auto','공감하며 읽은 시를 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X12']::text[],false,'{"seq":4,"concept":"K5-2-u1-C13","difficulty":3,"kind":"mc","stem":"공감하며 읽은 시를 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이 시는 이사 간 친구를 그리워하는 시야. 나도 친한 친구가 전학 가서 같은 마음이었어.」","correct":true},{"t":"「이 시는 짧아서 좋아.」","mis":"K5-2-u1-X03"},{"t":"「나는 이사를 가 본 적이 없어서 이 시에 공감할 수 없어.」","mis":"K5-2-u1-X12"},{"t":"「이 시는 우리 반에서 나만 읽었어.」","mis":"K5-2-u1-X03"}],"explanation":["짧다는 건 공감의 까닭이 아니에요.","똑같은 일이 아니어도 비슷한 마음이면 공감해요.","어떤 시인지와 공감한 까닭을 함께 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#5','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C19',3,'ox','auto','「방학 마지막 날」을 읽고 친구는 이불 속 장면을, 나는 시곗바늘 장면을 그렸다면 둘 중 하나는 잘못 감상한 거예요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":5,"concept":"K5-2-u1-C19","difficulty":3,"kind":"ox","stem":"「방학 마지막 날」을 읽고 친구는 이불 속 장면을, 나는 시곗바늘 장면을 그렸다면 둘 중 하나는 잘못 감상한 거예요.","answer":"X","reason_options":[{"t":"같은 시에서도 인상적인 부분은 다를 수 있고, 고른 까닭을 말하면 둘 다 의미 있는 감상이기 때문에","correct":true},{"t":"한 시에서 그릴 장면은 하나로 정해져 있기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["고른 장면은 달라도 돼요.","까닭을 말하면 돼요.","다른 그림이 생각을 넓혀 줘요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#6','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C11',3,'mc','auto','「해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X14']::text[],false,'{"seq":6,"concept":"K5-2-u1-C11","difficulty":3,"kind":"mc","stem":"「해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"방학이 끝나는 것이 아쉬워 시간을 붙잡고 싶은 마음","correct":true},{"t":"시계가 고장 나서 고치고 싶은 마음","mis":"K5-2-u1-X09"},{"t":"지붕에 올라가고 싶은 마음","mis":"K5-2-u1-X09"},{"t":"빨리 학교에 가고 싶은 마음","mis":"K5-2-u1-X14"}],"explanation":["정말 시계를 붙잡는 게 아니에요.","지붕에 오르려는 게 아니에요.","해 지는 게 아쉬운 마음이에요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#7','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C16',3,'mc','auto','「괜찮아, 나」를 모둠이 연을 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u1-X10','K5-2-u1-X14']::text[],false,'{"seq":7,"concept":"K5-2-u1-C16","difficulty":3,"kind":"mc","stem":"「괜찮아, 나」를 모둠이 연을 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"앞의 두 연은 속상하고 빠르게, 마지막 연은 천천히 다독이듯 읽는다","correct":true},{"t":"네 연을 모두 같은 크기와 빠르기로 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 목소리 큰 친구가 혼자 다 읽는다","mis":"K5-2-u1-X10"},{"t":"마지막 연을 가장 빠르게 소리친다","mis":"K5-2-u1-X14"}],"explanation":["마음이 바뀌는 곳을 살려요.","나누어 맡아 이어 읽어요.","달래는 마음과 어울리지 않아요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#8','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C17',4,'essay','teacher','「괜찮아, 나」에서 내가 고른 인상적인 부분과 까닭을 쓰고, 다인이나 로운이의 의견을 듣고 새롭게 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C17","difficulty":4,"kind":"essay","stem":"「괜찮아, 나」에서 내가 고른 인상적인 부분과 까닭을 쓰고, 다인이나 로운이의 의견을 듣고 새롭게 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 나는 셋째 연 「내 마음도 / 찢어진 종이처럼 구겨진다」가 인상적이다. 마음을 구겨진 종이에 빗대어 속상함이 눈에 보이는 것 같기 때문이다. 로운이의 말을 듣고 마지막 「괜찮아」가 스스로를 위로하는 말이라는 것을 알게 되어, 이 시가 속상함에서 끝나지 않고 위로로 끝나는 시라는 것을 새롭게 보았다.","scoring_points":["인상적인 부분을 골랐는가","까닭을 시와 이어 썼는가","친구 의견에서 새롭게 안 점을 썼는가"]},"explanation":["내 부분을 골라요.","까닭을 써요.","친구 말에서 넓어진 생각을 써요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#9','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C19',4,'essay','teacher','「방학 마지막 날」에서 그림으로 그리고 싶은 장면을 하나 골라, 그림에 무엇을 그릴지와 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C19","difficulty":4,"kind":"essay","stem":"「방학 마지막 날」에서 그림으로 그리고 싶은 장면을 하나 골라, 그림에 무엇을 그릴지와 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 셋째 연 「나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다」를 그리겠다. 이불을 머리끝까지 덮은 아이와, 종이처럼 접힌 달력 한 장을 그리겠다. 하루를 접어 둔다는 표현이 방학을 아끼고 싶은 마음을 재미있게 보여 주고, 나도 방학 마지막 날에 일찍 자기 싫었던 적이 있어서 이 장면을 골랐다.","scoring_points":["장면을 시에서 골랐는가","그릴 모습을 썼는가","고른 까닭을 썼는가"]},"explanation":["장면을 골라요.","무엇을 그릴지 정해요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L04_challenge#10','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C18',4,'essay','teacher','친구와 시에 대한 의견을 나눌 때 지켜야 할 태도 두 가지를 쓰고, 그렇게 하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C18","difficulty":4,"kind":"essay","stem":"친구와 시에 대한 의견을 나눌 때 지켜야 할 태도 두 가지를 쓰고, 그렇게 하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 첫째, 친구의 의견을 끝까지 듣는다. 둘째, 나와 다른 의견이라도 틀렸다고 하지 않고 그 까닭을 들어 본다. 이렇게 하면 내가 미처 생각하지 못한 부분을 알게 되어 같은 시를 새로운 관점으로 다시 볼 수 있다.","scoring_points":["태도 두 가지를 썼는가","경청과 존중이 드러나는가","좋은 점을 썼는가"]},"explanation":["듣는 태도를 떠올려요.","다른 의견을 대하는 태도를 써요.","좋은 점을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#1','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C20',1,'mc','auto','「전기문」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X18','K5-2-u1-X27']::text[],false,'{"seq":1,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"「전기문」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글","correct":true},{"t":"지어낸 인물이 나오는 옛이야기","mis":"K5-2-u1-X18"},{"t":"날마다 겪은 일을 쓴 일기","mis":"K5-2-u1-X18"},{"t":"책을 읽고 평가한 글","mis":"K5-2-u1-X27"}],"explanation":["지어낸 인물이 아니에요.","일기와 달라요.","그건 서평이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#2','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C22',1,'mc','auto','유관순이 살았던 시대의 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":2,"concept":"K5-2-u1-C22","difficulty":1,"kind":"mc","stem":"유관순이 살았던 시대의 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"일본에 나라를 빼앗긴 일제 강점기","correct":true},{"t":"나라를 처음 세운 때","mis":"K5-2-u1-X20"},{"t":"한글을 처음 만든 때","mis":"K5-2-u1-X20"},{"t":"오늘날과 똑같은 때","mis":"K5-2-u1-X20"}],"explanation":["나라를 세운 때가 아니에요.","한글은 훨씬 전에 만들었어요.","만세를 부른 까닭이 이 상황에 있어요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#3','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C20',1,'ox','auto','「유관순」은 실제로 살았던 인물의 이야기예요.',ARRAY['K5-2-u1-X18']::text[],false,'{"seq":3,"concept":"K5-2-u1-C20","difficulty":1,"kind":"ox","stem":"「유관순」은 실제로 살았던 인물의 이야기예요.","answer":"O","reason_options":[{"t":"실제 인물의 삶을 사실에 근거하여 쓴 전기문이기 때문에","correct":true},{"t":"지어낸 이야기에 나오는 인물이기 때문에","mis":"K5-2-u1-X18"}],"mis":"K5-2-u1-X18","explanation":["실제 인물이에요.","사실에 근거해요.","그래서 전기문이라고 해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#4','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C23',1,'mc','auto','유관순이 방학이면 고향 사람들에게 글을 가르친 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":4,"concept":"K5-2-u1-C23","difficulty":1,"kind":"mc","stem":"유관순이 방학이면 고향 사람들에게 글을 가르친 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"배운 것을 나누어 사람들의 힘을 기르고 싶어서","correct":true},{"t":"방학 숙제였기 때문에","mis":"K5-2-u1-X21"},{"t":"고향이 심심해서","mis":"K5-2-u1-X21"},{"t":"글을 가르치면 돈을 받아서","mis":"K5-2-u1-X21"}],"explanation":["숙제 이야기는 없어요.","심심해서가 아니에요.","아버지의 말과 이어 생각해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#5','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C23',2,'match','auto','유관순이 처한 상황과 그때 한 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-2-u1-C23","difficulty":2,"kind":"match","stem":"유관순이 처한 상황과 그때 한 일을 알맞게 이으세요.","pairs":[{"l":"일본이 학교 문을 닫았을 때","r":"고향으로 돌아와 만세 운동을 준비했다"},{"l":"함께할 사람이 필요했을 때","r":"이 마을 저 마을을 다니며 부탁했다"},{"l":"붙잡혀 재판을 받을 때","r":"조금도 굽히지 않았다"}],"mis":"K5-2-u1-X21","explanation":["학교가 닫히자 고향에서 준비했어요.","사람을 모으려 다녔어요.","끝까지 뜻을 지켰어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#6','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C21',2,'mc','auto','전기문에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18']::text[],false,'{"seq":6,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"전기문에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"사건은 사실에 바탕을 두지만 인물의 말은 작가가 다시 꾸몄을 수도 있다","correct":true},{"t":"인물의 말은 모두 그날 그대로 받아 적은 것이다","mis":"K5-2-u1-X19"},{"t":"사실과 상관없이 마음대로 지어낸 글이다","mis":"K5-2-u1-X18"},{"t":"인물의 말은 하나도 실을 수 없다","mis":"K5-2-u1-X19"}],"explanation":["그대로 받아 적었다고 단정할 수 없어요.","사실에 근거해요.","말을 실을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#7','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C24',2,'mc','auto','「유관순」 ②에서 인상적인 부분으로 고를 수 있는 것을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":7,"concept":"K5-2-u1-C24","difficulty":2,"kind":"mc","stem":"「유관순」 ②에서 인상적인 부분으로 고를 수 있는 것을 바르게 말한 것은 어느 것인가요?","options":[{"t":"사건의 흐름, 인물의 말과 행동, 이야기의 분위기 모두 고를 수 있다","correct":true},{"t":"아우내 장터 장면 하나만 고를 수 있다","mis":"K5-2-u1-X22"},{"t":"글의 첫 문장만 고를 수 있다","mis":"K5-2-u1-X22"},{"t":"인물의 이름만 고를 수 있다","mis":"K5-2-u1-X01"}],"explanation":["큰 사건 하나만이 아니에요.","첫 문장만이 아니에요.","여러 가지가 인상적인 부분이 돼요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#8','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C25',2,'mc','auto','인상적인 부분을 중심으로 유관순에게 할 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X23']::text[],false,'{"seq":8,"concept":"K5-2-u1-C25","difficulty":2,"kind":"mc","stem":"인상적인 부분을 중심으로 유관순에게 할 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「붙잡혀서도 굽히지 않을 수 있었던 힘은 무엇이었나요?」","correct":true},{"t":"「태어난 해가 언제인가요?」","mis":"K5-2-u1-X23"},{"t":"「좋아하는 음식은 무엇인가요?」","mis":"K5-2-u1-X23"},{"t":"「이화학당은 어느 도시에 있었나요?」","mis":"K5-2-u1-X23"}],"explanation":["글에 답이 그대로 있는 질문이에요.","인상적인 부분과 관계없어요.","마음을 깊이 묻는 질문이에요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#9','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C22',2,'blank','auto','유관순이 「나라를 되찾아야 합니다」라고 외친 까닭은 그때 우리나라가 (     ) 상황이었기 때문이에요.',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":9,"concept":"K5-2-u1-C22","difficulty":2,"kind":"blank","stem":"유관순이 「나라를 되찾아야 합니다」라고 외친 까닭은 그때 우리나라가 (     ) 상황이었기 때문이에요.","options":[{"t":"일본에 나라를 빼앗긴","correct":true},{"t":"다른 나라와 친하게 지내던","mis":"K5-2-u1-X20"},{"t":"새 임금을 뽑던","mis":"K5-2-u1-X20"},{"t":"학교가 처음 생기던","mis":"K5-2-u1-X20"}],"explanation":["시대 상황과 맞지 않아요.","임금을 뽑던 때가 아니에요.","시대 상황을 알면 외침이 이해돼요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_basic#10','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C26',3,'mc','auto','「유관순」을 읽고 오늘의 나와 이어 생각한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21','K5-2-u1-X18']::text[],false,'{"seq":10,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「유관순」을 읽고 오늘의 나와 이어 생각한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「내가 옳다고 믿는 일을 끝까지 지키는 용기를 본받고 싶어.」","correct":true},{"t":"「옛날 일이라 지금의 나와는 관계없어.」","mis":"K5-2-u1-X24"},{"t":"「만세를 부르는 장면은 크게 소리 지르는 연습이야.」","mis":"K5-2-u1-X21"},{"t":"「전기문은 다 지어낸 이야기니까 본받을 건 없어.」","mis":"K5-2-u1-X18"}],"explanation":["옛이야기도 오늘에 뜻이 있어요.","상황과 떼어 읽었어요.","실제 인물의 삶이에요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#1','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C21',2,'mc','auto','「유관순」 ①에서 작가가 다시 꾸며 표현했을 수 있는 부분으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":1,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"「유관순」 ①에서 작가가 다시 꾸며 표현했을 수 있는 부분으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아버지가 한 말 「나라의 힘을 기르려면 새 학문을 배워야 한다」","correct":true},{"t":"1902년에 태어났다는 것","mis":"K5-2-u1-X19"},{"t":"이화학당에 다녔다는 것","mis":"K5-2-u1-X19"},{"t":"1919년 3월 1일에 만세를 불렀다는 것","mis":"K5-2-u1-X19"}],"explanation":["기록으로 확인되는 사실이에요.","기록으로 확인되는 사실이에요.","그날의 말 그대로인지는 알 수 없어요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#2','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C22',2,'mc','auto','전기문을 읽을 때 시대적 상황을 알아야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X20','K5-2-u1-X21']::text[],false,'{"seq":2,"concept":"K5-2-u1-C22","difficulty":2,"kind":"mc","stem":"전기문을 읽을 때 시대적 상황을 알아야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"인물이 왜 그런 일을 했는지 이해할 수 있기 때문에","correct":true},{"t":"연도를 외우면 시험을 잘 보기 때문에","mis":"K5-2-u1-X20"},{"t":"시대만 알면 인물을 몰라도 되기 때문에","mis":"K5-2-u1-X21"},{"t":"시대 상황은 이야기와 관계없기 때문에","mis":"K5-2-u1-X20"}],"explanation":["외우기가 목적이 아니에요.","인물의 말과 행동도 함께 봐요.","상황이 행동의 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#3','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C21',3,'error','auto','「유관순」 ②를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X22']::text[],false,'{"seq":3,"concept":"K5-2-u1-C21","difficulty":3,"kind":"error","stem":"「유관순」 ②를 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「장터에서 외친 말은 기록이 남은 그날 그대로의 말이 틀림없어.」","correct":true,"mis_target":"K5-2-u1-X19"},{"t":"「아우내 장터에서 만세 운동이 있었던 것은 역사적 사실이야.」","mis":"K5-2-u1-X18"},{"t":"「밤에 가족과 태극기를 만든 장면에서 긴장된 마음이 느껴져.」","mis":"K5-2-u1-X22"}],"explanation":["사실을 바르게 말했어요.","장면과 이어 감상했어요.","말은 작가가 다시 꾸몄을 수 있어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#4','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C23',3,'mc','auto','유관순이 「이 마을 저 마을을 다니며 함께하자고 부탁한」 행동에서 짐작할 수 있는 마음은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":4,"concept":"K5-2-u1-C23","difficulty":3,"kind":"mc","stem":"유관순이 「이 마을 저 마을을 다니며 함께하자고 부탁한」 행동에서 짐작할 수 있는 마음은 어느 것인가요?","options":[{"t":"여럿이 함께해야 나라를 되찾을 수 있다는 마음","correct":true},{"t":"마을 구경을 하고 싶은 마음","mis":"K5-2-u1-X21"},{"t":"혼자서도 충분하다는 마음","mis":"K5-2-u1-X21"},{"t":"학교에 빨리 돌아가고 싶은 마음","mis":"K5-2-u1-X21"}],"explanation":["구경이 목적이 아니에요.","함께하자고 부탁했어요.","상황과 행동을 이어 짐작해요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#5','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C24',3,'mc','auto','「유관순」 ①과 ②를 이어 읽을 때 인상적인 부분으로 고를 만한 「인물의 변화」는 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":5,"concept":"K5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「유관순」 ①과 ②를 이어 읽을 때 인상적인 부분으로 고를 만한 「인물의 변화」는 어느 것인가요?","options":[{"t":"배우던 학생이 고향 사람들을 모아 만세 운동을 이끄는 사람이 된다","correct":true},{"t":"태어난 마을의 이름이 바뀐다","mis":"K5-2-u1-X22"},{"t":"태극기의 색이 바뀐다","mis":"K5-2-u1-X22"},{"t":"글의 첫 문장이 바뀐다","mis":"K5-2-u1-X01"}],"explanation":["마을 이름 이야기는 없어요.","태극기 이야기가 아니에요.","인물이 어떻게 달라졌는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#6','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C25',3,'ox','auto','「태어난 해는 언제인가요?」는 인상적인 부분을 중심으로 인물에게 하는 좋은 질문이에요.',ARRAY['K5-2-u1-X23']::text[],false,'{"seq":6,"concept":"K5-2-u1-C25","difficulty":3,"kind":"ox","stem":"「태어난 해는 언제인가요?」는 인상적인 부분을 중심으로 인물에게 하는 좋은 질문이에요.","answer":"X","reason_options":[{"t":"글에 답이 그대로 있어 인물의 마음을 깊이 생각하게 하지 못하기 때문에","correct":true},{"t":"인물에 대한 질문이면 무엇이든 좋은 질문이기 때문에","mis":"K5-2-u1-X23"}],"mis":"K5-2-u1-X23","explanation":["글에 답이 그대로 있어요.","마음을 묻는 질문이 좋아요.","인상적인 부분에서 출발해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#7','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C26',3,'mc','auto','「유관순」에서 본받을 점을 지금 우리 생활과 바르게 이은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21']::text[],false,'{"seq":7,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「유관순」에서 본받을 점을 지금 우리 생활과 바르게 이은 것은 어느 것인가요?","options":[{"t":"배운 것을 혼자 갖지 않고 나누었듯, 내가 아는 것을 친구에게 알려 준다","correct":true},{"t":"옛날 일이라 지금 생활과 이을 수 없다","mis":"K5-2-u1-X24"},{"t":"만세를 부르듯 교실에서 크게 소리친다","mis":"K5-2-u1-X21"},{"t":"재판을 받는 장면을 흉내 낸다","mis":"K5-2-u1-X21"}],"explanation":["옛이야기도 오늘과 이어져요.","상황과 떼어 흉내 내면 뜻을 놓쳐요.","흉내가 본받기는 아니에요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#8','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C24',4,'essay','teacher','「유관순」에서 인상적인 부분을 하나 고르고, 그 부분이 인상적인 까닭을 인물이 처한 상황과 이어서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C24","difficulty":4,"kind":"essay","stem":"「유관순」에서 인상적인 부분을 하나 고르고, 그 부분이 인상적인 까닭을 인물이 처한 상황과 이어서 쓰세요.","answer_guide":{"answer":"예: 「붙잡혀 재판을 받을 때도 조금도 굽히지 않았고」가 인상적이다. 나라를 빼앗겨 바른말을 하면 붙잡히던 때였는데도 뜻을 꺾지 않았기 때문이다. 나라면 무서워서 말을 바꾸었을지도 모르는데, 그 상황에서 끝까지 굽히지 않은 용기가 크게 느껴졌다.","scoring_points":["인상적인 부분을 글에서 골랐는가","인물이 처한 상황을 썼는가","상황과 이어 까닭을 썼는가"]},"explanation":["한 부분을 골라요.","그때의 상황을 떠올려요.","상황과 까닭을 이어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#9','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C25',4,'essay','teacher','「유관순」에서 인상적인 부분을 하나 고르고, 그 부분에서 유관순에게 묻고 싶은 질문과 내가 짐작한 유관순의 대답을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C25","difficulty":4,"kind":"essay","stem":"「유관순」에서 인상적인 부분을 하나 고르고, 그 부분에서 유관순에게 묻고 싶은 질문과 내가 짐작한 유관순의 대답을 쓰세요.","answer_guide":{"answer":"예: 인상적인 부분 — 밤에 가족과 태극기를 만든 장면. 질문 — 「들키면 위험한데 어떤 마음으로 태극기를 만들었나요?」 짐작한 대답 — 「무서웠지만 다음 날 많은 사람이 태극기를 들고 함께 외칠 모습을 떠올리며 한 장 한 장 정성껏 만들었어요.」","scoring_points":["인상적인 부분을 골랐는가","그 부분에서 나온 질문을 썼는가","상황에 맞게 대답을 짐작했는가"]},"explanation":["인상적인 부분에서 출발해요.","마음을 묻는 질문을 만들어요.","상황에 맞게 짐작해요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L07_challenge#10','kor',5,2,'u1','L07','g5_2_kor_u1_L07_challenge','lesson_challenge','K5-2-u1-C21',4,'essay','teacher','전기문을 읽을 때 「사실」과 「작가가 다시 꾸몄을 수 있는 부분」을 가려 읽어야 하는 까닭을 쓰고, 「유관순」에서 각각 예를 하나씩 드세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C21","difficulty":4,"kind":"essay","stem":"전기문을 읽을 때 「사실」과 「작가가 다시 꾸몄을 수 있는 부분」을 가려 읽어야 하는 까닭을 쓰고, 「유관순」에서 각각 예를 하나씩 드세요.","answer_guide":{"answer":"예: 전기문은 실제 인물의 삶을 사실에 근거하여 쓰지만, 인물이 한 말이나 행동은 기록이 다 남아 있지 않아 작가가 상상하여 다시 꾸민 것일 수 있다. 그래서 무엇이 확인된 사실인지 가려 읽어야 인물을 바르게 알 수 있다. 사실 — 1919년 4월 1일 아우내 장터에서 만세 운동이 있었다. 다시 꾸몄을 수 있는 부분 — 아버지가 「새 학문을 배워야 한다」고 한 말.","scoring_points":["가려 읽어야 하는 까닭을 썼는가","사실의 예를 들었는가","다시 꾸몄을 수 있는 부분의 예를 들었는가"]},"explanation":["전기문의 특성을 떠올려요.","확인된 일을 찾아요.","말과 행동을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#1','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C27',1,'mc','auto','「서평」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X27','K5-2-u1-X26']::text[],false,'{"seq":1,"concept":"K5-2-u1-C27","difficulty":1,"kind":"mc","stem":"「서평」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"책에 대한 자신의 의견이나 평가를 까닭과 함께 밝힌 글","correct":true},{"t":"책의 줄거리를 처음부터 끝까지 옮겨 쓴 글","mis":"K5-2-u1-X25"},{"t":"책을 읽고 느낌만 자유롭게 쓴 글","mis":"K5-2-u1-X27"},{"t":"책의 좋은 점만 모아 쓴 광고","mis":"K5-2-u1-X26"}],"explanation":["줄거리를 다 옮기는 글이 아니에요.","그건 독서 감상문에 가까워요.","좋은 점만 쓰는 글이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#2','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',1,'match','auto','서평 「수요일의 텃밭」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-2-u1-C28","difficulty":1,"kind":"match","stem":"서평 「수요일의 텃밭」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요","r":"책 소개"},{"l":"상추가 뽑히자 서로 의심하다가 다시 씨앗을 심기로 해요","r":"줄거리"},{"l":"뒷부분이 조금 서둘러 끝나는 점은 아쉬워요","r":"책에 대한 평가"}],"mis":"K5-2-u1-X25","explanation":["어떤 책인지 알려 줘요.","중요한 일만 간추렸어요.","아쉬운 점을 평가했어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#3','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',1,'mc','auto','서평 「수요일의 텃밭」에서 인상적인 부분으로 고른 장면은 어느 것인가요?',ARRAY['K5-2-u1-X22']::text[],false,'{"seq":3,"concept":"K5-2-u1-C28","difficulty":1,"kind":"mc","stem":"서평 「수요일의 텃밭」에서 인상적인 부분으로 고른 장면은 어느 것인가요?","options":[{"t":"의심받던 친구가 흙 묻은 손을 내미는 장면","correct":true},{"t":"상추가 밤사이 모두 뽑힌 장면","mis":"K5-2-u1-X22"},{"t":"아이들이 처음 텃밭을 가꾸는 장면","mis":"K5-2-u1-X22"},{"t":"책이 끝나는 마지막 장면","mis":"K5-2-u1-X22"}],"explanation":["일어난 일로 소개했어요.","인상적인 부분으로 고르지 않았어요.","오해가 풀리는 순간을 골랐어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#4','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C30',1,'ox','auto','서평에는 책의 좋은 점만 써야 해요.',ARRAY['K5-2-u1-X26']::text[],false,'{"seq":4,"concept":"K5-2-u1-C30","difficulty":1,"kind":"ox","stem":"서평에는 책의 좋은 점만 써야 해요.","answer":"X","reason_options":[{"t":"아쉬운 점도 그렇게 생각한 까닭과 함께 쓸 수 있기 때문에","correct":true},{"t":"서평은 책을 칭찬하는 글이기 때문에","mis":"K5-2-u1-X26"}],"mis":"K5-2-u1-X26","explanation":["아쉬운 점도 평가예요.","까닭과 함께 써요.","「수요일의 텃밭」 서평에도 아쉬운 점이 있어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#5','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C29',2,'mc','auto','서평에 줄거리를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29','K5-2-u1-X28']::text[],false,'{"seq":5,"concept":"K5-2-u1-C29","difficulty":2,"kind":"mc","stem":"서평에 줄거리를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"중요한 일만 골라 차례대로 간단히 쓴다","correct":true},{"t":"처음부터 끝까지 빠짐없이 자세히 쓴다","mis":"K5-2-u1-X25"},{"t":"마지막 장면만 쓴다","mis":"K5-2-u1-X29"},{"t":"줄거리는 쓰지 않는다","mis":"K5-2-u1-X28"}],"explanation":["서평의 중심은 줄거리가 아니에요.","중요한 일을 차례대로 써요.","간단한 줄거리는 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#6','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C30',2,'blank','auto','「수요일의 텃밭」 서평은 (     ) 친구들에게 이 책을 권했어요.',ARRAY['K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C30","difficulty":2,"kind":"blank","stem":"「수요일의 텃밭」 서평은 (     ) 친구들에게 이 책을 권했어요.","options":[{"t":"친구와 다투어 마음이 무거운","correct":true},{"t":"텃밭이 없는 학교의","mis":"K5-2-u1-X28"},{"t":"상추를 싫어하는","mis":"K5-2-u1-X28"},{"t":"책을 많이 읽은","mis":"K5-2-u1-X28"}],"explanation":["추천 대상이 달라요.","글에 없는 말이에요.","누구에게 왜 추천하는지 썼어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#7','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C31',2,'mc','auto','「어떤 친구가 쓴 글」이 서평이 아니라 독서 감상문에 가까운 까닭은 무엇인가요?',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":7,"concept":"K5-2-u1-C31","difficulty":2,"kind":"mc","stem":"「어떤 친구가 쓴 글」이 서평이 아니라 독서 감상문에 가까운 까닭은 무엇인가요?","options":[{"t":"느낀 점만 쓰고 책에 대한 평가와 그 까닭은 쓰지 않았기 때문에","correct":true},{"t":"글이 너무 짧기 때문에","mis":"K5-2-u1-X27"},{"t":"책 제목을 썼기 때문에","mis":"K5-2-u1-X27"},{"t":"「텃밭」이라는 낱말이 나오기 때문에","mis":"K5-2-u1-X27"}],"explanation":["길이로 가르지 않아요.","제목은 둘 다 쓸 수 있어요.","평가와 까닭이 있는지 봐요."],"asset":{"type":"passage","lines":["「수요일의 텃밭」을 읽고 나도 텃밭을 가꾸고 싶어졌다.","상추가 뽑혔을 때 내가 다 속상했다.","친구가 손을 내밀 때는 눈물이 날 뻔했다.","다 읽고 나니 마음이 따뜻해졌다."],"title":"어떤 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#8','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C32',2,'mc','auto','서평 「수요일의 텃밭」의 제목 「흙 묻은 손으로 맺은 약속」이 좋은 까닭은 무엇인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X01']::text[],false,'{"seq":8,"concept":"K5-2-u1-C32","difficulty":2,"kind":"mc","stem":"서평 「수요일의 텃밭」의 제목 「흙 묻은 손으로 맺은 약속」이 좋은 까닭은 무엇인가요?","options":[{"t":"읽을 사람의 관심을 끌고 책의 핵심 장면을 드러내서","correct":true},{"t":"책 제목과 똑같아서","mis":"K5-2-u1-X29"},{"t":"글자 수가 가장 많아서","mis":"K5-2-u1-X01"},{"t":"어려운 낱말을 써서","mis":"K5-2-u1-X01"}],"explanation":["책 제목과 달라요.","길이는 상관없어요.","핵심을 짧게 담았어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#9','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',2,'error','auto','서평의 평가를 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X28','K5-2-u1-X30','K5-2-u1-X26']::text[],false,'{"seq":9,"concept":"K5-2-u1-C28","difficulty":2,"kind":"error","stem":"서평의 평가를 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「이 책은 재미있다. 끝.」","correct":true,"mis_target":"K5-2-u1-X28"},{"t":"「오해가 풀리는 장면이 생생해서 친구와 다툰 사람에게 권한다.」","mis":"K5-2-u1-X30"},{"t":"「뒷부분이 서둘러 끝나 조금 아쉽다.」","mis":"K5-2-u1-X26"}],"explanation":["까닭과 추천 대상이 있어요.","아쉬운 점도 평가예요.","까닭 없이 「재미있다」만 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_basic#10','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C33',3,'mc','auto','서평을 쓴 뒤 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":10,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 쓴 뒤 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구와 돌려 읽고 받은 의견을 살펴 빠진 내용을 보탠다","correct":true},{"t":"한 번 썼으니 고치지 않는다","mis":"K5-2-u1-X30"},{"t":"글씨만 더 예쁘게 다시 쓴다","mis":"K5-2-u1-X30"},{"t":"줄거리를 더 길게 늘린다","mis":"K5-2-u1-X25"}],"explanation":["고쳐 쓰면 더 좋아져요.","글씨보다 내용을 살펴요.","줄거리를 늘리는 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#1','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C25',2,'mc','auto','서평 첫 초안 「등대 아래 도서관」의 가장 큰 문제는 무엇인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X26']::text[],false,'{"seq":1,"concept":"K5-2-u1-C25","difficulty":2,"kind":"mc","stem":"서평 첫 초안 「등대 아래 도서관」의 가장 큰 문제는 무엇인가요?","options":[{"t":"줄거리만 길게 쓰고 인상적인 부분과 평가는 거의 쓰지 않았다","correct":true},{"t":"책 제목이 들어가 있다","mis":"K5-2-u1-X29"},{"t":"줄거리를 너무 짧게 썼다","mis":"K5-2-u1-X29"},{"t":"아쉬운 점을 썼다","mis":"K5-2-u1-X26"}],"explanation":["제목이 있는 건 문제가 아니에요.","오히려 너무 길어요.","아쉬운 점은 쓰지 않았어요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#2','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C28',2,'mc','auto','서평 첫 초안 「등대 아래 도서관」에 빠진 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":2,"concept":"K5-2-u1-C28","difficulty":2,"kind":"mc","stem":"서평 첫 초안 「등대 아래 도서관」에 빠진 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"인상적인 부분과 그 부분이 인상적인 까닭","correct":true},{"t":"줄거리","mis":"K5-2-u1-X25"},{"t":"책 제목","mis":"K5-2-u1-X29"},{"t":"등장인물의 이름","mis":"K5-2-u1-X25"}],"explanation":["줄거리는 넘칠 만큼 있어요.","제목은 있어요.","인물 이름은 있어요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#3','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C29',3,'mc','auto','초안의 「그다음 날에는 ……」을 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X28','K5-2-u1-X29']::text[],false,'{"seq":3,"concept":"K5-2-u1-C29","difficulty":3,"kind":"mc","stem":"초안의 「그다음 날에는 ……」을 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「해솔이가 낡은 도서관을 발견하고, 할머니에게 책 고치는 법을 배워 친구들과 도서관을 다시 연다」처럼 줄인다","correct":true},{"t":"「그다음 날에는」을 열 번 더 써서 자세히 한다","mis":"K5-2-u1-X25"},{"t":"줄거리를 다 지우고 「재미있다」만 남긴다","mis":"K5-2-u1-X28"},{"t":"마지막 날 이야기 한 줄만 남긴다","mis":"K5-2-u1-X29"}],"explanation":["더 늘리면 안 돼요.","평가에도 까닭이 필요해요.","중요한 일을 차례대로 골라요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#4','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C32',3,'ox','auto','서평의 제목은 책 제목 「등대 아래 도서관」을 그대로 쓰는 것이 가장 좋아요.',ARRAY['K5-2-u1-X29']::text[],false,'{"seq":4,"concept":"K5-2-u1-C32","difficulty":3,"kind":"ox","stem":"서평의 제목은 책 제목 「등대 아래 도서관」을 그대로 쓰는 것이 가장 좋아요.","answer":"X","reason_options":[{"t":"서평의 제목은 읽을 사람의 관심을 끌고 책의 핵심이나 내 평가가 드러나게 붙이기 때문에","correct":true},{"t":"서평의 제목은 책 제목과 같아야 하기 때문에","mis":"K5-2-u1-X29"}],"mis":"K5-2-u1-X29","explanation":["책 제목을 옮기기만 하면 아쉬워요.","관심을 끄는 제목을 붙여요.","핵심이 드러나게 해요."],"asset":{"type":"passage","lines":["〔제목〕 등대 아래 도서관","바닷가 마을 아이 해솔이가 등대 아래 낡은 도서관을 발견한다. 다음 날 해솔이는 또 갔다.","그다음 날에는 동생을 데려갔다. 그다음 날에는 사서 할머니를 만났다.","할머니는 책을 고치는 법을 알려 주었다. 그다음 날에는 비가 왔다. 그래도 갔다.","그다음 날에는 친구들이 따라왔다. 그다음 날에는 …… (이렇게 열 줄이 더 이어진다)","이 책은 재미있다."],"title":"서평 첫 초안 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#5','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C31',3,'mc','auto','같은 책을 읽고 쓴 두 글 가운데 서평의 특징이 드러난 문장은 어느 것인가요?',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":5,"concept":"K5-2-u1-C31","difficulty":3,"kind":"mc","stem":"같은 책을 읽고 쓴 두 글 가운데 서평의 특징이 드러난 문장은 어느 것인가요?","options":[{"t":"「오해가 풀리는 장면이 생생해서, 친구와 다툰 사람에게 이 책을 권한다.」","correct":true},{"t":"「상추가 뽑혔을 때 내가 다 속상했다.」","mis":"K5-2-u1-X27"},{"t":"「다 읽고 나니 마음이 따뜻해졌다.」","mis":"K5-2-u1-X27"},{"t":"「나도 텃밭을 가꾸고 싶어졌다.」","mis":"K5-2-u1-X27"}],"explanation":["느낌을 쓴 문장이에요.","느낌을 쓴 문장이에요.","평가와 까닭, 추천이 담겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#6','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C30',3,'error','auto','서평에 들어갈 평가를 쓴 친구들의 말이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X30','K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C30","difficulty":3,"kind":"error","stem":"서평에 들어갈 평가를 쓴 친구들의 말이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「아쉬운 점을 쓰면 서평이 아니게 되니까 좋은 점만 써야 해.」","correct":true,"mis_target":"K5-2-u1-X26"},{"t":"「책을 아끼는 마음을 기르고 싶은 친구에게 권한다고 쓸래.」","mis":"K5-2-u1-X30"},{"t":"「할머니가 왜 도서관을 지켰는지 안 나와서 아쉽다고 까닭을 쓸래.」","mis":"K5-2-u1-X28"}],"explanation":["누구에게 왜 권하는지 썼어요.","아쉬운 점에 까닭을 붙였어요.","아쉬운 점도 평가가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#7','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C33',3,'mc','auto','서평을 쓸 때 스스로에게 할 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":7,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 쓸 때 스스로에게 할 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이 책이 친구들에게 도움이 되는 까닭은 무엇일까?」","correct":true},{"t":"「이 책은 몇 쪽일까?」","mis":"K5-2-u1-X30"},{"t":"「줄거리를 하나도 빠짐없이 썼을까?」","mis":"K5-2-u1-X25"},{"t":"「책값은 얼마일까?」","mis":"K5-2-u1-X30"}],"explanation":["쪽수는 평가와 관계없어요.","빠짐없이 쓰는 게 목적이 아니에요.","평가의 까닭을 찾는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#8','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C31',4,'essay','teacher','「어떤 친구가 쓴 글」을 서평으로 고쳐 쓴다고 할 때, 더 넣어야 할 내용 두 가지를 쓰고 그 내용을 넣은 문장을 하나 만들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C31","difficulty":4,"kind":"essay","stem":"「어떤 친구가 쓴 글」을 서평으로 고쳐 쓴다고 할 때, 더 넣어야 할 내용 두 가지를 쓰고 그 내용을 넣은 문장을 하나 만들어 쓰세요.","answer_guide":{"answer":"예: 더 넣어야 할 내용 — 책에 대한 평가와 그 까닭, 누구에게 왜 추천하는지. 문장 — 「의심하던 친구들이 다시 마음을 모으는 과정이 잘 그려져 있어서, 친구와 오해가 생겨 고민하는 친구들에게 이 책을 권하고 싶다.」","scoring_points":["더 넣을 내용 두 가지를 썼는가","평가와 까닭이 담긴 문장을 썼는가","추천 대상과 까닭을 썼는가"]},"explanation":["감상문과 서평의 차이를 떠올려요.","평가와 까닭을 넣어요.","추천을 써요."],"asset":{"type":"passage","lines":["「수요일의 텃밭」을 읽고 나도 텃밭을 가꾸고 싶어졌다.","상추가 뽑혔을 때 내가 다 속상했다.","친구가 손을 내밀 때는 눈물이 날 뻔했다.","다 읽고 나니 마음이 따뜻해졌다."],"title":"어떤 친구가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#9','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C28',4,'essay','teacher','최근에 읽은 책 한 권을 떠올려 서평의 다섯 칸(제목 · 책 소개 · 줄거리 · 인상적인 부분과 까닭 · 평가)을 짧게 계획해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C28","difficulty":4,"kind":"essay","stem":"최근에 읽은 책 한 권을 떠올려 서평의 다섯 칸(제목 · 책 소개 · 줄거리 · 인상적인 부분과 까닭 · 평가)을 짧게 계획해 쓰세요.","answer_guide":{"answer":"예: 제목 — 「느려도 끝까지 가는 편지」. 책 소개 — 「달팽이 우체부 느림이」는 느린 달팽이가 숲속 친구들에게 편지를 전하는 동화이다. 줄거리 — 느림이는 비바람에 늦어지지만 포기하지 않고 마지막 편지까지 전한다. 인상적인 부분과 까닭 — 마지막 편지를 받은 다람쥐가 우는 장면. 기다림이 기쁨으로 바뀌는 순간이 따뜻해서. 평가 — 끝까지 하는 마음을 배우고 싶은 친구에게 권한다. 다만 중간에 비슷한 장면이 되풀이되어 조금 지루하다.","scoring_points":["다섯 칸을 모두 계획했는가","줄거리를 간단히 썼는가","평가에 까닭을 붙였는가"]},"explanation":["책을 떠올려요.","칸마다 짧게 써요.","평가에 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L10_challenge#10','kor',5,2,'u1','L10','g5_2_kor_u1_L10_challenge','lesson_challenge','K5-2-u1-C33',4,'essay','teacher','서평 첫 초안과 고쳐 쓴 글 「낡은 책이 다시 숨 쉬는 곳」을 견주어, 고쳐 쓰면서 나아진 점 세 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C33","difficulty":4,"kind":"essay","stem":"서평 첫 초안과 고쳐 쓴 글 「낡은 책이 다시 숨 쉬는 곳」을 견주어, 고쳐 쓰면서 나아진 점 세 가지를 쓰세요.","answer_guide":{"answer":"예: 첫째, 제목을 책 제목 그대로 쓰지 않고 「낡은 책이 다시 숨 쉬는 곳」으로 바꾸어 관심을 끈다. 둘째, 날마다 일어난 일을 늘어놓던 줄거리를 중요한 일만 간추려 두 문장으로 줄였다. 셋째, 「재미있다」만 있던 평가에 인상적인 부분과 까닭, 추천할 사람, 아쉬운 점을 까닭과 함께 넣었다.","scoring_points":["제목이 나아진 점을 썼는가","줄거리가 나아진 점을 썼는가","평가가 나아진 점을 썼는가"]},"explanation":["두 글을 나란히 봐요.","칸마다 견줘요.","나아진 점을 정리해요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#1','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C34',1,'mc','auto','「이달의 책」을 추천할 때 정리할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X31','K5-2-u1-X34']::text[],false,'{"seq":1,"concept":"K5-2-u1-C34","difficulty":1,"kind":"mc","stem":"「이달의 책」을 추천할 때 정리할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"추천할 책, 추천하는 까닭, 인상적인 부분","correct":true},{"t":"책의 값과 쪽수","mis":"K5-2-u1-X31"},{"t":"내가 그 책을 산 날짜","mis":"K5-2-u1-X31"},{"t":"책 표지의 색깔","mis":"K5-2-u1-X34"}],"explanation":["값은 추천 까닭이 아니에요.","산 날은 상관없어요.","표지 색만으로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#2','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C35',1,'mc','auto','모둠 토의에서 친구의 추천 까닭을 들을 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":2,"concept":"K5-2-u1-C35","difficulty":1,"kind":"mc","stem":"모둠 토의에서 친구의 추천 까닭을 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"끝까지 듣고 나와 같은 점과 다른 점을 견준다","correct":true},{"t":"내 차례가 오기 전에 말을 끊는다","mis":"K5-2-u1-X16"},{"t":"나와 다르면 바로 틀렸다고 한다","mis":"K5-2-u1-X16"},{"t":"듣지 않고 내 책만 생각한다","mis":"K5-2-u1-X16"}],"explanation":["끝까지 들어요.","다른 의견도 견줘요.","들어야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#3','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C37',1,'ox','auto','내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었던 거예요.',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":3,"concept":"K5-2-u1-C37","difficulty":1,"kind":"ox","stem":"내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었던 거예요.","answer":"X","reason_options":[{"t":"뽑히지 않은 책의 추천 까닭도 친구들이 새 책을 알게 하고 다음 후보가 될 수 있기 때문에","correct":true},{"t":"토의에서는 뽑힌 의견만 의미가 있기 때문에","mis":"K5-2-u1-X33"}],"mis":"K5-2-u1-X33","explanation":["다른 의견도 쓸모가 있어요.","다음 달 후보가 돼요.","토의는 견주고 조정하는 과정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#4','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C36',1,'mc','auto','나은이가 의견이 갈렸을 때 제안한 방법은 무엇인가요?',ARRAY['K5-2-u1-X32']::text[],false,'{"seq":4,"concept":"K5-2-u1-C36","difficulty":1,"kind":"mc","stem":"나은이가 의견이 갈렸을 때 제안한 방법은 무엇인가요?","options":[{"t":"반 친구들 모두에게 두루 도움이 되는지로 견주기","correct":true},{"t":"목소리가 가장 큰 친구의 책으로 정하기","mis":"K5-2-u1-X32"},{"t":"가장 먼저 말한 친구의 책으로 정하기","mis":"K5-2-u1-X32"},{"t":"제비뽑기로만 정하기","mis":"K5-2-u1-X32"}],"explanation":["목소리로 정하지 않아요.","말한 차례로 정하지 않아요.","함께 정한 기준에 대어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#5','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C34',2,'mc','auto','다인이가 추천한 책이 「이달의 책」으로 아쉬운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X34','K5-2-u1-X32','K5-2-u1-X31']::text[],false,'{"seq":5,"concept":"K5-2-u1-C34","difficulty":2,"kind":"mc","stem":"다인이가 추천한 책이 「이달의 책」으로 아쉬운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 분야에 치우쳐 별을 좋아하는 친구만 좋아할 수 있어서","correct":true},{"t":"제목이 너무 짧아서","mis":"K5-2-u1-X34"},{"t":"다인이가 먼저 말하지 않아서","mis":"K5-2-u1-X32"},{"t":"별 이야기는 책이 될 수 없어서","mis":"K5-2-u1-X31"}],"explanation":["제목 길이는 상관없어요.","말한 차례와는 관계없어요.","별 책도 좋은 책이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#6','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C35',2,'match','auto','친구와 그 친구가 든 추천 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u1-C35","difficulty":2,"kind":"match","stem":"친구와 그 친구가 든 추천 까닭을 알맞게 이으세요.","pairs":[{"l":"시우","r":"느려도 끝까지 편지를 전하는 모습이 인상적이다"},{"l":"다인","r":"별자리 이름이 많이 나온다"},{"l":"로운","r":"책을 고치는 장면이 따뜻하고 누구나 읽기 쉽다"}],"mis":"K5-2-u1-X16","explanation":["시우는 인물의 모습을 들었어요.","다인이는 담긴 지식을 들었어요.","로운이는 장면과 읽기 쉬움을 들었어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#7','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C37',2,'mc','auto','다인이가 「다음 달 후보로 남겨 둘래」라고 한 말에서 알 수 있는 태도는 어느 것인가요?',ARRAY['K5-2-u1-X33','K5-2-u1-X16','K5-2-u1-X32']::text[],false,'{"seq":7,"concept":"K5-2-u1-C37","difficulty":2,"kind":"mc","stem":"다인이가 「다음 달 후보로 남겨 둘래」라고 한 말에서 알 수 있는 태도는 어느 것인가요?","options":[{"t":"조정된 의견을 받아들이면서 내 의견도 소중히 여기는 태도","correct":true},{"t":"내 책이 안 되면 토의를 그만두는 태도","mis":"K5-2-u1-X33"},{"t":"다른 친구 책을 깎아내리는 태도","mis":"K5-2-u1-X16"},{"t":"기준 없이 아무 책이나 고르는 태도","mis":"K5-2-u1-X32"}],"explanation":["토의를 이어 가요.","깎아내리지 않았어요.","기준에 대어 스스로 견줬어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#8','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C38',2,'blank','auto','고른 「이달의 책」을 알리는 소개 자료에는 간단한 책 소개, 추천 까닭, (     )을/를 담아요.',ARRAY['K5-2-u1-X34']::text[],false,'{"seq":8,"concept":"K5-2-u1-C38","difficulty":2,"kind":"blank","stem":"고른 「이달의 책」을 알리는 소개 자료에는 간단한 책 소개, 추천 까닭, (     )을/를 담아요.","options":[{"t":"인상적인 문장","correct":true},{"t":"책값","mis":"K5-2-u1-X34"},{"t":"지은이의 주소","mis":"K5-2-u1-X34"},{"t":"다 읽는 데 걸린 날짜","mis":"K5-2-u1-X34"}],"explanation":["값은 알릴 거리가 아니에요.","주소는 필요 없어요.","마음에 남은 문장을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#9','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C36',2,'mc','auto','모둠에서 「이달의 책」 고르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X31','K5-2-u1-X32']::text[],false,'{"seq":9,"concept":"K5-2-u1-C36","difficulty":2,"kind":"mc","stem":"모둠에서 「이달의 책」 고르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"반 친구들이 두루 흥미롭게 읽을 수 있는가","correct":true},{"t":"가장 두꺼운 책인가","mis":"K5-2-u1-X31"},{"t":"추천한 친구가 반장인가","mis":"K5-2-u1-X32"},{"t":"가장 비싼 책인가","mis":"K5-2-u1-X31"}],"explanation":["두께가 기준은 아니에요.","누가 추천했는지가 기준은 아니에요.","반 친구 모두를 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_basic#10','kor',5,2,'u1','L12','g5_2_kor_u1_L12_basic','lesson_basic','K5-2-u1-C38',3,'mc','auto','「이달의 책」 소개 자료로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X34','K5-2-u1-X25','K5-2-u1-X28']::text[],false,'{"seq":10,"concept":"K5-2-u1-C38","difficulty":3,"kind":"mc","stem":"「이달의 책」 소개 자료로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책 소개 한 줄, 추천 까닭, 인상적인 문장을 함께 담은 광고지","correct":true},{"t":"책 제목만 크게 쓴 종이","mis":"K5-2-u1-X34"},{"t":"줄거리를 처음부터 끝까지 옮긴 종이","mis":"K5-2-u1-X25"},{"t":"「무조건 읽어!」만 쓴 종이","mis":"K5-2-u1-X28"}],"explanation":["제목만으로는 왜 읽을지 몰라요.","줄거리를 다 옮기지 않아요.","까닭 없는 말은 설득이 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#1','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C34',2,'mc','auto','「이달의 책」에 어울리는 조건으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X31']::text[],false,'{"seq":1,"concept":"K5-2-u1-C34","difficulty":2,"kind":"mc","stem":"「이달의 책」에 어울리는 조건으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"반에서 한두 명만 읽을 수 있을 만큼 어려운 이야기","correct":true},{"t":"흥미로운 이야기","mis":"K5-2-u1-X31"},{"t":"교훈을 주는 이야기","mis":"K5-2-u1-X31"},{"t":"여러 친구가 함께 이야기 나눌 거리가 있는 책","mis":"K5-2-u1-X31"}],"explanation":["흥미는 좋은 조건이에요.","교훈도 좋은 조건이에요.","너무 어려운 책은 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#2','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C36',2,'error','auto','모둠 토의에서 의견이 갈렸을 때 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X32','K5-2-u1-X36','K5-2-u1-X35']::text[],false,'{"seq":2,"concept":"K5-2-u1-C36","difficulty":2,"kind":"error","stem":"모둠 토의에서 의견이 갈렸을 때 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「내가 제일 먼저 말했으니까 내 책으로 하자.」","correct":true,"mis_target":"K5-2-u1-X32"},{"t":"「반 친구들에게 두루 도움이 되는지로 견주어 보자.」","mis":"K5-2-u1-X36"},{"t":"「두 책의 추천 까닭에서 같은 점부터 찾아보자.」","mis":"K5-2-u1-X35"}],"explanation":["기준을 세웠어요.","견주기부터 했어요.","말한 차례로 정하지 않아요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#3','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C35',3,'mc','auto','시우와 로운이의 추천 까닭에서 같은 점은 무엇인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X31','K5-2-u1-X03']::text[],false,'{"seq":3,"concept":"K5-2-u1-C35","difficulty":3,"kind":"mc","stem":"시우와 로운이의 추천 까닭에서 같은 점은 무엇인가요?","options":[{"t":"둘 다 책 속 장면이나 인물의 모습을 까닭으로 들었다","correct":true},{"t":"둘 다 지식이 많이 나온다는 것을 들었다","mis":"K5-2-u1-X16"},{"t":"둘 다 책값이 싸다는 것을 들었다","mis":"K5-2-u1-X31"},{"t":"둘 다 까닭을 말하지 않았다","mis":"K5-2-u1-X03"}],"explanation":["지식은 다인이가 든 까닭이에요.","값 이야기는 없어요.","같은 점을 찾으면 조정이 쉬워요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#4','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C36',3,'mc','auto','나은이가 제안한 기준에 대면 가장 알맞게 고른 책은 어느 것이고, 왜 그런가요?',ARRAY['K5-2-u1-X31','K5-2-u1-X32','K5-2-u1-X04']::text[],false,'{"seq":4,"concept":"K5-2-u1-C36","difficulty":3,"kind":"mc","stem":"나은이가 제안한 기준에 대면 가장 알맞게 고른 책은 어느 것이고, 왜 그런가요?","options":[{"t":"「등대 아래 도서관」 — 누구나 읽기 쉽고 따뜻한 장면이 있어 반 친구들에게 두루 맞아서","correct":true},{"t":"「밤하늘 별자리 백과」 — 이름이 가장 많이 나와서","mis":"K5-2-u1-X31"},{"t":"「달팽이 우체부 느림이」 — 시우가 먼저 말해서","mis":"K5-2-u1-X32"},{"t":"아무 책이나 — 어차피 정답이 없어서","mis":"K5-2-u1-X04"}],"explanation":["한 분야에 치우칠 수 있어요.","말한 차례는 기준이 아니에요.","기준에 대어 까닭을 들었어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「달팽이 우체부 느림이」를 추천해. 느려도 끝까지 편지를 전하는 모습이 인상적이었어."},{"who":"다인","text":"나는 「밤하늘 별자리 백과」! 별자리 이름이 엄청 많이 나와서 좋아."},{"who":"로운","text":"「등대 아래 도서관」은 어때? 책을 고치는 장면이 따뜻하고 누구나 읽기 쉬워."},{"who":"나은","text":"의견이 셋으로 갈렸네. 우리 반 친구들 모두에게 두루 도움이 되는지로 견주어 보자."},{"who":"다인","text":"내 책은 별을 좋아하는 친구만 좋아할 수도 있겠다. 다음 달 후보로 남겨 둘래."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#5','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C37',3,'ox','auto','「이달의 책」을 알릴 때 아깝게 뽑히지 않은 책 목록도 함께 나누면 좋아요.',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":5,"concept":"K5-2-u1-C37","difficulty":3,"kind":"ox","stem":"「이달의 책」을 알릴 때 아깝게 뽑히지 않은 책 목록도 함께 나누면 좋아요.","answer":"O","reason_options":[{"t":"다른 의견도 인정하고 친구들이 더 많은 책을 알게 되기 때문에","correct":true},{"t":"뽑히지 않은 책은 나쁜 책이라고 알려 주어야 하기 때문에","mis":"K5-2-u1-X33"}],"mis":"K5-2-u1-X33","explanation":["뽑히지 않았다고 나쁜 책이 아니에요.","다음 후보가 될 수 있어요.","다양한 의견을 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#6','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C38',3,'mc','auto','「이달의 책」 광고지의 문구로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X34','K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C38","difficulty":3,"kind":"mc","stem":"「이달의 책」 광고지의 문구로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「젖은 책을 한 장씩 말리는 아이 — 작은 일을 끝까지 해내는 마음을 만나 보세요.」","correct":true},{"t":"「이달의 책! 꼭 읽어!」","mis":"K5-2-u1-X34"},{"t":"「이 책은 이백 쪽입니다.」","mis":"K5-2-u1-X34"},{"t":"「안 읽으면 후회함!」","mis":"K5-2-u1-X28"}],"explanation":["까닭이 빠졌어요.","쪽수는 끌림이 없어요.","인상적인 장면과 까닭을 담았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#7','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C18',3,'mc','auto','모둠 토의를 마친 뒤 되돌아보기로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33','K5-2-u1-X32','K5-2-u1-X16']::text[],false,'{"seq":7,"concept":"K5-2-u1-C18","difficulty":3,"kind":"mc","stem":"모둠 토의를 마친 뒤 되돌아보기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「친구의 추천 까닭을 듣고 내가 몰랐던 책의 좋은 점을 알게 되었다.」","correct":true},{"t":"「내 책이 안 뽑혀서 아무것도 얻지 못했다.」","mis":"K5-2-u1-X33"},{"t":"「목소리가 큰 친구가 이겨서 다행이다.」","mis":"K5-2-u1-X32"},{"t":"「다른 친구 말은 듣지 않아도 됐다.」","mis":"K5-2-u1-X16"}],"explanation":["얻은 것이 있어요.","목소리로 정하지 않아요.","들었기에 배운 게 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#8','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C34',4,'essay','teacher','내가 「이달의 책」으로 추천할 책을 하나 정해, 추천하는 까닭과 인상적인 부분을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C34","difficulty":4,"kind":"essay","stem":"내가 「이달의 책」으로 추천할 책을 하나 정해, 추천하는 까닭과 인상적인 부분을 함께 쓰세요.","answer_guide":{"answer":"예: 「달팽이 우체부 느림이」를 추천한다. 느린 달팽이가 비바람 속에서도 포기하지 않고 마지막 편지까지 전하는 이야기여서, 무엇이든 빨리 하려다 쉽게 그만두는 우리에게 끝까지 하는 마음을 알려 준다. 인상적인 부분은 편지를 받은 다람쥐가 기쁨에 우는 장면이다. 기다림이 기쁨으로 바뀌는 순간이 따뜻하게 느껴졌기 때문이다.","scoring_points":["추천할 책을 정했는가","반 친구들을 생각한 추천 까닭을 썼는가","인상적인 부분과 까닭을 썼는가"]},"explanation":["책을 정해요.","반 친구들에게 맞는 까닭을 써요.","인상적인 부분을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#9','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C36',4,'essay','teacher','모둠의 의견이 둘로 갈렸을 때 의견을 조정하는 방법을 차례대로 쓰고, 그렇게 하면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C36","difficulty":4,"kind":"essay","stem":"모둠의 의견이 둘로 갈렸을 때 의견을 조정하는 방법을 차례대로 쓰고, 그렇게 하면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 먼저 서로의 추천 까닭을 끝까지 듣는다. 다음으로 두 의견의 같은 점과 다른 점을 견준다. 그리고 「반 친구들에게 두루 도움이 되는가」처럼 함께 기준을 정해 대어 본다. 마지막으로 기준에 더 맞는 책을 고르고, 뽑히지 않은 책은 다음 달 후보로 남긴다. 이렇게 하면 목소리 크기나 차례가 아니라 까닭에 따라 정하게 되어 모두가 받아들이기 쉽다.","scoring_points":["듣기 · 견주기 · 기준 세우기를 차례대로 썼는가","뽑히지 않은 의견을 존중하는 내용이 있는가","좋은 까닭을 썼는가"]},"explanation":["듣기부터 시작해요.","기준에 대어요.","모두가 받아들이기 쉬운 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_L12_challenge#10','kor',5,2,'u1','L12','g5_2_kor_u1_L12_challenge','lesson_challenge','K5-2-u1-C38',4,'essay','teacher','고른 「이달의 책」을 반 친구들에게 알리는 광고지에 넣을 내용 세 가지를 쓰고, 그 가운데 하나를 실제 문구로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C38","difficulty":4,"kind":"essay","stem":"고른 「이달의 책」을 반 친구들에게 알리는 광고지에 넣을 내용 세 가지를 쓰고, 그 가운데 하나를 실제 문구로 쓰세요.","answer_guide":{"answer":"예: 넣을 내용 — 책을 간단히 소개하는 한 줄, 추천하는 까닭, 책 속 인상적인 문장. 실제 문구 — 「〈조금씩이라도 매일 가면 끝내 닿아.〉 느린 달팽이가 알려 주는 끝까지 하는 힘, 이번 달 우리 반이 함께 읽어요!」","scoring_points":["넣을 내용 세 가지를 썼는가","실제 문구를 썼는가","문구가 친구들의 관심을 끌 수 있는가"]},"explanation":["소개 · 까닭 · 문장을 떠올려요.","하나를 골라 써요.","관심을 끌게 다듬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#1','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C39',1,'mc','auto','인상적인 문장에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"mc","stem":"인상적인 문장에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"짧고 쉬운 문장도 마음이 움직였다면 인상적인 문장이 된다","correct":true},{"t":"어려운 낱말이 많을수록 인상적인 문장이다","mis":"K5-2-u1-X35"},{"t":"가장 긴 문장이 인상적인 문장이다","mis":"K5-2-u1-X35"},{"t":"책의 첫 문장만 인상적인 문장이다","mis":"K5-2-u1-X02"}],"explanation":["어려움은 기준이 아니에요.","길이는 기준이 아니에요.","마음이 움직였는지가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#2','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C2',1,'ox','auto','「운동장 그림자」를 읽고 하람이와 도윤이가 고른 연이 다르니 한 사람은 틀렸어요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"「운동장 그림자」를 읽고 하람이와 도윤이가 고른 연이 다르니 한 사람은 틀렸어요.","answer":"X","reason_options":[{"t":"같은 시를 읽어도 사람마다 인상적인 부분이 다를 수 있기 때문에","correct":true},{"t":"한 시에서 인상적인 연은 하나로 정해져 있기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["다르게 고를 수 있어요.","둘 다 까닭이 있어요.","틀린 사람은 없어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#3','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C40',1,'mc','auto','「책을 주제별로 (     )」에 들어갈 낱말로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「책을 주제별로 (     )」에 들어갈 낱말로 알맞은 것은 어느 것인가요?","options":[{"t":"분류하다","correct":true},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분실하다","mis":"K5-2-u1-X36"}],"explanation":["몫을 나누어 주는 게 아니에요.","자세히 살피는 게 아니에요.","기준에 따라 종류별로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#4','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C40',1,'mc','auto','「축구 감독이 선수들의 움직임을 (     )」에 들어갈 낱말은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「축구 감독이 선수들의 움직임을 (     )」에 들어갈 낱말은 어느 것인가요?","options":[{"t":"분석하다","correct":true},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분리하다","mis":"K5-2-u1-X36"}],"explanation":["종류별로 나누는 게 아니에요.","몫을 나누는 게 아니에요.","움직임을 자세히 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#5','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C20',1,'mc','auto','「세종 대왕」 같은 글을 무엇이라고 하나요?',ARRAY['K5-2-u1-X27','K5-2-u1-X18']::text[],false,'{"seq":5,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"「세종 대왕」 같은 글을 무엇이라고 하나요?","options":[{"t":"전기문","correct":true},{"t":"서평","mis":"K5-2-u1-X27"},{"t":"동시","mis":"K5-2-u1-X18"},{"t":"일기","mis":"K5-2-u1-X18"}],"explanation":["책을 평가한 글이 아니에요.","시가 아니에요.","실제 인물의 삶을 쓴 글이에요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#6','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C31',1,'mc','auto','독서 감상문과 서평의 차이로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X27']::text[],false,'{"seq":6,"concept":"K5-2-u1-C31","difficulty":1,"kind":"mc","stem":"독서 감상문과 서평의 차이로 알맞은 것은 어느 것인가요?","options":[{"t":"서평은 책을 평가하고 그 까닭을 밝힌다","correct":true},{"t":"서평은 줄거리만 쓴다","mis":"K5-2-u1-X25"},{"t":"독서 감상문은 책의 아쉬운 점을 꼭 쓴다","mis":"K5-2-u1-X27"},{"t":"둘은 같은 글이다","mis":"K5-2-u1-X27"}],"explanation":["줄거리만 쓰는 글이 아니에요.","아쉬운 점은 서평의 평가예요.","둘은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#7','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C6',1,'mc','auto','「종이비행기」에서 말하는 이가 괜찮다고 한 것은 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 말하는 이가 괜찮다고 한 것은 무엇인가요?","options":[{"t":"접는 선이 삐뚤어진 것","correct":true},{"t":"비행기를 잃어버린 것","mis":"K5-2-u1-X06"},{"t":"비행기를 접지 않은 것","mis":"K5-2-u1-X06"},{"t":"비행기가 찢어진 것","mis":"K5-2-u1-X06"}],"explanation":["잃어버린 이야기는 없어요.","접은 것을 칭찬해요.","첫째 줄에 나와요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#8','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C18',1,'mc','auto','친구와 작품에 대한 의견을 나눌 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C18","difficulty":1,"kind":"mc","stem":"친구와 작품에 대한 의견을 나눌 때 알맞은 태도는 어느 것인가요?","options":[{"t":"친구의 의견을 끝까지 듣고 존중한다","correct":true},{"t":"나와 다르면 말을 끊는다","mis":"K5-2-u1-X16"},{"t":"내 의견만 여러 번 말한다","mis":"K5-2-u1-X16"},{"t":"친구 의견은 듣지 않는다","mis":"K5-2-u1-X16"}],"explanation":["끝까지 들어요.","번갈아 나눠요.","들어야 생각이 넓어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#9','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C3',2,'mc','auto','하람이의 말 「셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어」에서 까닭에 해당하는 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"하람이의 말 「셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어」에서 까닭에 해당하는 것은 어느 것인가요?","options":[{"t":"그림자가 먼저 집으로 달려간다는 표현이 재미있다","correct":true},{"t":"셋째 연을 골랐다","mis":"K5-2-u1-X03"},{"t":"하람이가 그림자를 좋아한다","mis":"K5-2-u1-X04"},{"t":"저녁에 운동장에 갔다","mis":"K5-2-u1-X04"}],"explanation":["그건 고른 부분이에요.","글에 없는 말이에요.","표현이 주는 느낌이 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#10','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C8',2,'mc','auto','하람이가 도윤이에게 한 말 「그건 시랑 상관없는 네 이야기잖아」에 대한 판단으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"mc","stem":"하람이가 도윤이에게 한 말 「그건 시랑 상관없는 네 이야기잖아」에 대한 판단으로 알맞은 것은 어느 것인가요?","options":[{"t":"도윤이가 떠올린 경험은 시의 마지막 연과 이어지므로 까닭이 될 수 있다","correct":true},{"t":"하람이 말이 맞다. 경험은 까닭이 될 수 없다","mis":"K5-2-u1-X08"},{"t":"둘 다 틀렸다. 인상적인 부분은 셋째 연뿐이다","mis":"K5-2-u1-X02"},{"t":"도윤이는 까닭을 말하지 않았다","mis":"K5-2-u1-X03"}],"explanation":["경험도 까닭이 돼요.","정해진 연이 없어요.","도윤이는 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#11','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C11',2,'mc','auto','「그림자가 발밑에 쪼그려 앉고」를 바르게 이해한 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X06']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「그림자가 발밑에 쪼그려 앉고」를 바르게 이해한 것은 어느 것인가요?","options":[{"t":"해가 높이 뜬 점심에 그림자가 아주 짧아진 모습을 사람처럼 나타냈다","correct":true},{"t":"그림자가 정말 다리를 굽혀 앉았다","mis":"K5-2-u1-X09"},{"t":"그림자가 다쳐서 주저앉았다","mis":"K5-2-u1-X09"},{"t":"점심에는 그림자가 사라진다","mis":"K5-2-u1-X06"}],"explanation":["글자 그대로가 아니에요.","다친 게 아니에요.","짧아진 모습을 빗댔어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#12','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C21',2,'mc','auto','「세종 대왕」에서 작가가 다시 꾸며 표현한 부분으로 볼 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"「세종 대왕」에서 작가가 다시 꾸며 표현한 부분으로 볼 수 있는 것은 어느 것인가요?","options":[{"t":"촛불 아래에서 「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다는 장면","correct":true},{"t":"조선의 넷째 임금이었다는 것","mis":"K5-2-u1-X19"},{"t":"학자들과 함께 훈민정음을 만들었다는 것","mis":"K5-2-u1-X19"},{"t":"백성들이 한자를 어려워했다는 것","mis":"K5-2-u1-X19"}],"explanation":["확인되는 사실이에요.","확인되는 사실이에요.","「어떤 책에서는 …… 그려요」라고 밝혔어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#13','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C23',2,'mc','auto','세종 대왕이 훈민정음을 만든 까닭을 그 무렵 상황과 이어 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":13,"concept":"K5-2-u1-C23","difficulty":2,"kind":"mc","stem":"세종 대왕이 훈민정음을 만든 까닭을 그 무렵 상황과 이어 말한 것은 어느 것인가요?","options":[{"t":"백성들이 한자를 몰라 하고 싶은 말을 글로 남기지 못했기 때문이다","correct":true},{"t":"임금이 글자 놀이를 좋아했기 때문이다","mis":"K5-2-u1-X21"},{"t":"다른 나라에 자랑하려고 했기 때문이다","mis":"K5-2-u1-X21"},{"t":"학자들이 심심해했기 때문이다","mis":"K5-2-u1-X21"}],"explanation":["글에 없는 짐작이에요.","글에 없는 짐작이에요.","상황과 행동을 이어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#14','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C28',2,'match','auto','서평 「낡은 책이 다시 숨 쉬는 곳」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"match","stem":"서평 「낡은 책이 다시 숨 쉬는 곳」의 문장과 서평에 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요","r":"책 소개"},{"l":"젖은 책을 한 장씩 말리는 장면이에요","r":"인상적인 부분"},{"l":"책을 아끼는 마음을 기르고 싶은 친구들에게 권해요","r":"책에 대한 평가"}],"mis":"K5-2-u1-X25","explanation":["어떤 책인지 알려요.","기억에 남는 장면이에요.","추천은 평가에 들어가요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#15','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C36',2,'mc','auto','「이달의 책」 고르기에서 의견이 갈렸을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u1-X32','K5-2-u1-X33']::text[],false,'{"seq":15,"concept":"K5-2-u1-C36","difficulty":2,"kind":"mc","stem":"「이달의 책」 고르기에서 의견이 갈렸을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"함께 정한 기준에 각 책을 대어 견준다","correct":true},{"t":"목소리가 가장 큰 친구의 책으로 한다","mis":"K5-2-u1-X32"},{"t":"가장 먼저 말한 친구의 책으로 한다","mis":"K5-2-u1-X32"},{"t":"토의를 그만두고 선생님께 맡긴다","mis":"K5-2-u1-X33"}],"explanation":["목소리로 정하지 않아요.","차례로 정하지 않아요.","기준에 대어 조정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#16','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C40',2,'blank','auto','「실험에서 얻은 자료를 (     )」에 들어갈 낱말은 무엇인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"blank","stem":"「실험에서 얻은 자료를 (     )」에 들어갈 낱말은 무엇인가요?","options":[{"t":"분석하다","correct":true},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분실하다","mis":"K5-2-u1-X36"}],"explanation":["자료를 나눠 주지 않아요.","종류별로 묶는 게 아니에요.","자세히 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#17','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C10',3,'mc','auto','「종이비행기」 전체에서 느껴지는 분위기로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X07','K5-2-u1-X11']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"mc","stem":"「종이비행기」 전체에서 느껴지는 분위기로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실수해도 괜찮다고 다정하게 응원하는 분위기","correct":true},{"t":"잘못을 꾸짖는 무서운 분위기","mis":"K5-2-u1-X07"},{"t":"비행기 접는 법을 알려 주는 설명 같은 분위기","mis":"K5-2-u1-X11"},{"t":"멀리 날린 사람만 칭찬하는 분위기","mis":"K5-2-u1-X07"}],"explanation":["꾸짖는 말은 없어요.","접는 법을 설명하는 시가 아니에요.","멀리 가지 않아도 좋다고 했어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#18','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C12',3,'mc','auto','「운동장 그림자」를 낭송할 때 셋째 연 「그림자가 먼저 집으로 달려간다」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":18,"concept":"K5-2-u1-C12","difficulty":3,"kind":"mc","stem":"「운동장 그림자」를 낭송할 때 셋째 연 「그림자가 먼저 집으로 달려간다」를 읽는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"앞 연보다 조금 빠르고 경쾌하게 읽는다","correct":true},{"t":"모든 연과 똑같은 빠르기로 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 느리고 슬프게 읽는다","mis":"K5-2-u1-X10"},{"t":"읽지 않고 건너뛴다","mis":"K5-2-u1-X10"}],"explanation":["느낌이 살지 않아요.","달려가는 느낌과 어울리지 않아요.","달려가는 느낌을 살려요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#19','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C25',3,'mc','auto','「세종 대왕」의 인상적인 부분을 중심으로 만든 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X23']::text[],false,'{"seq":19,"concept":"K5-2-u1-C25","difficulty":3,"kind":"mc","stem":"「세종 대왕」의 인상적인 부분을 중심으로 만든 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「글자를 만들다 지칠 때 무엇을 떠올리며 힘을 냈나요?」","correct":true},{"t":"「몇째 임금이었나요?」","mis":"K5-2-u1-X23"},{"t":"「좋아하는 음식은 무엇이었나요?」","mis":"K5-2-u1-X23"},{"t":"「궁궐은 몇 칸이었나요?」","mis":"K5-2-u1-X23"}],"explanation":["글에 답이 그대로 있어요.","인상적인 부분과 관계없어요.","마음을 깊이 묻는 질문이에요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#20','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C30',3,'mc','auto','「낡은 책이 다시 숨 쉬는 곳」의 아쉬운 점 평가가 알맞은 까닭은 무엇인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":20,"concept":"K5-2-u1-C30","difficulty":3,"kind":"mc","stem":"「낡은 책이 다시 숨 쉬는 곳」의 아쉬운 점 평가가 알맞은 까닭은 무엇인가요?","options":[{"t":"아쉬운 점과 함께 그렇게 생각한 까닭을 밝혔기 때문에","correct":true},{"t":"아쉬운 점은 서평에 쓰면 안 되기 때문에","mis":"K5-2-u1-X26"},{"t":"줄거리를 길게 썼기 때문에","mis":"K5-2-u1-X25"},{"t":"책 제목을 그대로 썼기 때문에","mis":"K5-2-u1-X29"}],"explanation":["아쉬운 점도 쓸 수 있어요.","줄거리는 짧아요.","제목은 바꾸었어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#21','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C17',3,'mc','auto','하람이와 도윤이가 고른 연이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":21,"concept":"K5-2-u1-C17","difficulty":3,"kind":"mc","stem":"하람이와 도윤이가 고른 연이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하람이는 표현의 재미에, 도윤이는 자기 경험에 마음이 움직여서","correct":true},{"t":"도윤이가 시를 잘못 읽어서","mis":"K5-2-u1-X15"},{"t":"셋째 연만 정답이라서","mis":"K5-2-u1-X02"},{"t":"하람이가 까닭을 말하지 않아서","mis":"K5-2-u1-X03"}],"explanation":["잘못 읽은 게 아니에요.","정답 연은 없어요.","하람이도 까닭을 말했어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#22','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C39',3,'mc','auto','좋아하는 책에서 인상적인 문장을 골라 친구와 나누는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X03']::text[],false,'{"seq":22,"concept":"K5-2-u1-C39","difficulty":3,"kind":"mc","stem":"좋아하는 책에서 인상적인 문장을 골라 친구와 나누는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문장과 그 문장이 인상적인 까닭을 함께 써서 돌려 읽는다","correct":true},{"t":"가장 긴 문장을 골라 낭독만 한다","mis":"K5-2-u1-X35"},{"t":"어려운 낱말이 많은 문장을 고른다","mis":"K5-2-u1-X35"},{"t":"문장만 쓰고 까닭은 쓰지 않는다","mis":"K5-2-u1-X03"}],"explanation":["길이가 기준이 아니에요.","어려움이 기준이 아니에요.","까닭이 함께 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#23','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C3',4,'essay','teacher','「운동장 그림자」에서 내가 고른 인상적인 부분과 그 까닭을 시 속 말과 이어 쓰고, 그 부분의 느낌을 살려 낭송할 방법을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「운동장 그림자」에서 내가 고른 인상적인 부분과 그 까닭을 시 속 말과 이어 쓰고, 그 부분의 느낌을 살려 낭송할 방법을 쓰세요.","answer_guide":{"answer":"예: 둘째 연 「점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고」가 인상적이다. 해가 높이 뜬 점심에 그림자가 짧아진 모습을 쪼그려 앉는 아이처럼 나타내어 귀엽게 느껴지기 때문이다. 「쪼그려 앉고」를 조금 작고 느리게, 몸을 웅크리듯 읽겠다.","scoring_points":["인상적인 부분을 골랐는가","까닭을 시 속 말과 이어 썼는가","느낌에 맞는 낭송 방법을 썼는가"]},"explanation":["한 연을 골라요.","까닭을 시와 이어요.","느낌을 소리로 살려요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#24','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C21',4,'essay','teacher','「세종 대왕」에서 확인된 사실 두 가지와 작가가 다시 꾸며 표현한 부분 한 가지를 찾아 쓰고, 그렇게 가려 읽어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C21","difficulty":4,"kind":"essay","stem":"「세종 대왕」에서 확인된 사실 두 가지와 작가가 다시 꾸며 표현한 부분 한 가지를 찾아 쓰고, 그렇게 가려 읽어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 사실 — 세종 대왕은 조선의 넷째 임금이다. 학자들과 함께 훈민정음을 만들었다. 다시 꾸민 부분 — 촛불 아래에서 「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다는 장면. 전기문은 사실에 근거하지만 인물의 말이나 행동은 작가가 상상해 꾸밀 수 있으므로, 가려 읽어야 인물을 바르게 알 수 있다.","scoring_points":["사실 두 가지를 썼는가","다시 꾸민 부분을 찾았는가","가려 읽는 까닭을 썼는가"]},"explanation":["확인된 일을 찾아요.","「어떤 책에서는」을 봐요.","까닭을 정리해요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_a#25','kor',5,2,'u1','','g5_2_kor_u1_review_a','unit_review','K5-2-u1-C2',4,'essay','teacher','이 단원에서 배운 「작품에 대한 의견을 나눌 때 꼭 지킬 것」 세 가지를 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C2","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「작품에 대한 의견을 나눌 때 꼭 지킬 것」 세 가지를 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 인상적인 부분을 고르고 그 까닭을 작품과 이어 말한다. 둘째, 친구의 의견을 끝까지 듣고 존중한다. 셋째, 나와 다른 의견도 틀렸다고 하지 않고 그 까닭을 들어 본다. 같은 작품도 사람마다 다르게 느낄 수 있어서, 까닭을 나누고 들어야 서로의 생각을 이해하고 작품을 더 넓게 볼 수 있기 때문이다.","scoring_points":["까닭 들어 말하기를 썼는가","경청 · 존중을 썼는가","다른 의견을 인정하는 까닭을 썼는가"]},"explanation":["말하기를 떠올려요.","듣기를 떠올려요.","까닭을 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#1','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C39',1,'ox','auto','「네가 접었다는 게 중요해」처럼 짧은 문장도 인상적인 문장이 될 수 있어요.',ARRAY['K5-2-u1-X35']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"ox","stem":"「네가 접었다는 게 중요해」처럼 짧은 문장도 인상적인 문장이 될 수 있어요.","answer":"O","reason_options":[{"t":"마음이 움직이거나 깨달음이 생기면 짧고 쉬운 문장도 인상적이기 때문에","correct":true},{"t":"인상적인 문장은 길고 어려워야 하기 때문에","mis":"K5-2-u1-X35"}],"mis":"K5-2-u1-X35","explanation":["짧아도 마음에 남아요.","쉬운 말도 깊어요.","내 경험과 이어지면 더 그래요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#2','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C2',1,'mc','auto','「종이비행기」를 반 친구들이 읽고 인상적인 부분을 고르면 어떻게 될까요?',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"mc","stem":"「종이비행기」를 반 친구들이 읽고 인상적인 부분을 고르면 어떻게 될까요?","options":[{"t":"친구마다 고른 부분이 다를 수 있다","correct":true},{"t":"모두 첫째 줄을 고르게 된다","mis":"K5-2-u1-X02"},{"t":"정답인 줄을 고른 친구만 맞는다","mis":"K5-2-u1-X02"},{"t":"아무도 고를 수 없다","mis":"K5-2-u1-X02"}],"explanation":["모두 같지 않아요.","정답 줄이 따로 있지 않아요.","누구나 고를 수 있어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#3','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C40',1,'mc','auto','「분류하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「분류하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"기준에 따라 종류별로 나누거나 묶다","correct":true},{"t":"몫으로 나누어 주다","mis":"K5-2-u1-X36"},{"t":"여러 부분으로 나누어 자세히 살피다","mis":"K5-2-u1-X36"},{"t":"물건을 잃어버리다","mis":"K5-2-u1-X36"}],"explanation":["그건 분배하다예요.","그건 분석하다예요.","종류별로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#4','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C40',1,'mc','auto','「모둠마다 색종이를 고르게 (     )」에 들어갈 낱말은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「모둠마다 색종이를 고르게 (     )」에 들어갈 낱말은 어느 것인가요?","options":[{"t":"분배하다","correct":true},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분해하다","mis":"K5-2-u1-X36"}],"explanation":["자세히 살피는 게 아니에요.","종류별 나누기가 아니에요.","몫으로 나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#5','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C20',1,'ox','auto','전기문은 지어낸 인물의 이야기예요.',ARRAY['K5-2-u1-X18']::text[],false,'{"seq":5,"concept":"K5-2-u1-C20","difficulty":1,"kind":"ox","stem":"전기문은 지어낸 인물의 이야기예요.","answer":"X","reason_options":[{"t":"실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글이기 때문에","correct":true},{"t":"작가가 마음대로 꾸며 낸 인물이 나오기 때문에","mis":"K5-2-u1-X18"}],"mis":"K5-2-u1-X18","explanation":["실제 인물이에요.","사실에 근거해요.","그래서 감동과 교훈을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#6','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C31',1,'ox','auto','서평과 독서 감상문은 같은 글이에요.',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":6,"concept":"K5-2-u1-C31","difficulty":1,"kind":"ox","stem":"서평과 독서 감상문은 같은 글이에요.","answer":"X","reason_options":[{"t":"서평은 느낌을 넘어 책을 평가하고 그 까닭을 밝힌 글이기 때문에","correct":true},{"t":"둘 다 책을 읽고 쓴 글이기 때문에","mis":"K5-2-u1-X27"}],"mis":"K5-2-u1-X27","explanation":["책을 읽고 쓴 것은 같아요.","평가와 까닭이 있는지 달라요.","서평은 추천도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#7','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C6',1,'mc','auto','「운동장 그림자」에서 점심 운동장의 그림자는 어떠한가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「운동장 그림자」에서 점심 운동장의 그림자는 어떠한가요?","options":[{"t":"발밑에 쪼그려 앉는다","correct":true},{"t":"나보다 길다","mis":"K5-2-u1-X06"},{"t":"먼저 집으로 달려간다","mis":"K5-2-u1-X06"},{"t":"사라져 버린다","mis":"K5-2-u1-X06"}],"explanation":["아침 그림자예요.","저녁 그림자예요.","둘째 연에 나와요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#8','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C18',1,'ox','auto','친구의 다른 의견을 들으면 작품을 새로운 관점으로 볼 수 있어요.',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C18","difficulty":1,"kind":"ox","stem":"친구의 다른 의견을 들으면 작품을 새로운 관점으로 볼 수 있어요.","answer":"O","reason_options":[{"t":"내가 미처 생각하지 못한 부분을 알게 되기 때문에","correct":true},{"t":"다른 의견은 내 생각을 헷갈리게만 하기 때문에","mis":"K5-2-u1-X16"}],"mis":"K5-2-u1-X16","explanation":["다른 의견이 생각을 넓혀요.","헷갈리게 하는 게 아니에요.","귀 기울여 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#9','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C3',2,'error','auto','「운동장 그림자」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X01','K5-2-u1-X07']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"error","stem":"「운동장 그림자」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「넷째 연이 좋다. 그냥 좋다.」","correct":true,"mis_target":"K5-2-u1-X03"},{"t":"「첫째 연이 인상적이다. 아침 그림자가 나보다 길다는 것을 처음 알아차리게 되었다.」","mis":"K5-2-u1-X01"},{"t":"「둘째 연이 인상적이다. 그림자가 쪼그려 앉는다는 말이 귀엽다.」","mis":"K5-2-u1-X07"}],"explanation":["깨달음이 까닭이에요.","표현이 주는 느낌이 까닭이에요.","까닭이 없어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#10','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C8',2,'ox','auto','도윤이처럼 「혼자 있을 때 그림자가 친구 같았던 경험」을 까닭으로 드는 것은 알맞아요.',ARRAY['K5-2-u1-X08']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"ox","stem":"도윤이처럼 「혼자 있을 때 그림자가 친구 같았던 경험」을 까닭으로 드는 것은 알맞아요.","answer":"O","reason_options":[{"t":"시의 마지막 연과 이어지는 내 경험은 인상적인 까닭이 될 수 있기 때문에","correct":true},{"t":"내 경험은 작품 밖의 이야기라 까닭이 될 수 없기 때문에","mis":"K5-2-u1-X08"}],"mis":"K5-2-u1-X08","explanation":["공감도 까닭이에요.","시와 이어진 경험이에요.","「나도 그랬지」가 까닭이 돼요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#11','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C11',2,'mc','auto','「그림자가 먼저 집으로 달려간다」에서 그림자를 무엇처럼 나타냈나요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「그림자가 먼저 집으로 달려간다」에서 그림자를 무엇처럼 나타냈나요?","options":[{"t":"먼저 뛰어가는 사람이나 친구","correct":true},{"t":"멈춰 있는 돌","mis":"K5-2-u1-X09"},{"t":"하늘의 구름","mis":"K5-2-u1-X09"},{"t":"운동장의 모래","mis":"K5-2-u1-X09"}],"explanation":["움직이는 모습이에요.","구름 이야기는 없어요.","사람처럼 나타냈어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#12','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C21',2,'ox','auto','「세종 대왕」에 나온 혼잣말은 그날 그대로 받아 적은 말이 틀림없어요.',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"ox","stem":"「세종 대왕」에 나온 혼잣말은 그날 그대로 받아 적은 말이 틀림없어요.","answer":"X","reason_options":[{"t":"전기문 속 인물의 말은 작가가 상상하거나 다시 꾸며 표현한 것일 수 있기 때문에","correct":true},{"t":"전기문에 나온 말은 모두 그대로 받아 적은 것이기 때문에","mis":"K5-2-u1-X19"}],"mis":"K5-2-u1-X19","explanation":["「어떤 책에서는 그려요」라고 했어요.","그대로라고 단정할 수 없어요.","사실과 꾸민 부분을 가려요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#13','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C22',2,'mc','auto','전기문 속 인물이 한 일을 이해하려면 무엇을 함께 알아야 하나요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":13,"concept":"K5-2-u1-C22","difficulty":2,"kind":"mc","stem":"전기문 속 인물이 한 일을 이해하려면 무엇을 함께 알아야 하나요?","options":[{"t":"인물이 살았던 때와 곳의 상황","correct":true},{"t":"인물의 키와 몸무게","mis":"K5-2-u1-X20"},{"t":"인물이 좋아한 색깔","mis":"K5-2-u1-X20"},{"t":"책의 쪽수","mis":"K5-2-u1-X20"}],"explanation":["행동의 까닭과 관계없어요.","행동의 까닭과 관계없어요.","시대 상황이 행동의 까닭이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#14','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C29',2,'mc','auto','고쳐 쓴 서평 「낡은 책이 다시 숨 쉬는 곳」에서 줄거리는 어떻게 쓰였나요?',ARRAY['K5-2-u1-X25','K5-2-u1-X28','K5-2-u1-X29']::text[],false,'{"seq":14,"concept":"K5-2-u1-C29","difficulty":2,"kind":"mc","stem":"고쳐 쓴 서평 「낡은 책이 다시 숨 쉬는 곳」에서 줄거리는 어떻게 쓰였나요?","options":[{"t":"중요한 일만 골라 한 문장으로 간추렸다","correct":true},{"t":"날마다 일어난 일을 빠짐없이 썼다","mis":"K5-2-u1-X25"},{"t":"줄거리를 하나도 쓰지 않았다","mis":"K5-2-u1-X28"},{"t":"마지막 장면만 썼다","mis":"K5-2-u1-X29"}],"explanation":["첫 초안이 그랬어요.","간단한 줄거리는 있어요.","중요한 일을 차례대로 썼어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#15','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C36',2,'ox','auto','의견이 갈리면 먼저 말한 친구의 책으로 정하는 것이 공평해요.',ARRAY['K5-2-u1-X32']::text[],false,'{"seq":15,"concept":"K5-2-u1-C36","difficulty":2,"kind":"ox","stem":"의견이 갈리면 먼저 말한 친구의 책으로 정하는 것이 공평해요.","answer":"X","reason_options":[{"t":"말한 차례가 아니라 함께 정한 기준에 대어 견주어야 모두가 받아들일 수 있기 때문에","correct":true},{"t":"먼저 말한 친구가 가장 깊이 생각했기 때문에","mis":"K5-2-u1-X32"}],"mis":"K5-2-u1-X32","explanation":["차례는 기준이 아니에요.","기준을 함께 정해요.","까닭으로 조정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#16','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C40',2,'blank','auto','「수확한 감자를 마을 사람들에게 (     )」에 들어갈 낱말은 무엇인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"blank","stem":"「수확한 감자를 마을 사람들에게 (     )」에 들어갈 낱말은 무엇인가요?","options":[{"t":"분배하다","correct":true},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분류하다","mis":"K5-2-u1-X36"},{"t":"분해하다","mis":"K5-2-u1-X36"}],"explanation":["살피는 게 아니에요.","종류별로 묶는 게 아니에요.","몫으로 나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#17','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C10',3,'mc','auto','「종이비행기」의 말하는 이는 누구에게 말하는 것 같나요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"mc","stem":"「종이비행기」의 말하는 이는 누구에게 말하는 것 같나요?","options":[{"t":"처음 무엇을 해 보며 실수할까 걱정하는 친구","correct":true},{"t":"비행기를 만드는 공장 사람","mis":"K5-2-u1-X09"},{"t":"종이비행기 대회 심사 위원","mis":"K5-2-u1-X09"},{"t":"하늘을 나는 새","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로만 읽었어요.","대회 이야기는 없어요.","「너」에게 응원하는 말이에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#18','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C15',3,'mc','auto','「운동장 그림자」에서 그림자의 모습은 어떻게 바뀌나요?',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":18,"concept":"K5-2-u1-C15","difficulty":3,"kind":"mc","stem":"「운동장 그림자」에서 그림자의 모습은 어떻게 바뀌나요?","options":[{"t":"길다가 → 발밑에 짧게 쪼그렸다가 → 먼저 달려간다","correct":true},{"t":"하루 종일 똑같이 길다","mis":"K5-2-u1-X14"},{"t":"짧다가 → 사라졌다가 → 다시 짧아진다","mis":"K5-2-u1-X14"},{"t":"아침부터 저녁까지 보이지 않는다","mis":"K5-2-u1-X14"}],"explanation":["하루 동안 바뀌어요.","사라지지 않아요.","연마다 따라가요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#19','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C24',3,'mc','auto','「세종 대왕」에서 인상적인 부분으로 고를 만한 것을 가장 넓게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":19,"concept":"K5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「세종 대왕」에서 인상적인 부분으로 고를 만한 것을 가장 넓게 말한 것은 어느 것인가요?","options":[{"t":"백성의 어려움을 살핀 마음, 오랜 연구, 촛불 아래 장면처럼 여러 가지가 될 수 있다","correct":true},{"t":"훈민정음을 만든 한 문장뿐이다","mis":"K5-2-u1-X22"},{"t":"첫 문장뿐이다","mis":"K5-2-u1-X22"},{"t":"임금이라는 낱말뿐이다","mis":"K5-2-u1-X01"}],"explanation":["하나만이 아니에요.","첫 문장만이 아니에요.","여러 가지가 될 수 있어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#20','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C32',3,'mc','auto','「등대 아래 도서관」 서평의 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X28']::text[],false,'{"seq":20,"concept":"K5-2-u1-C32","difficulty":3,"kind":"mc","stem":"「등대 아래 도서관」 서평의 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「젖은 책을 말리던 손, 다시 열린 도서관」","correct":true},{"t":"「등대 아래 도서관」","mis":"K5-2-u1-X29"},{"t":"「서평」","mis":"K5-2-u1-X29"},{"t":"「재미있는 책」","mis":"K5-2-u1-X28"}],"explanation":["책 제목 그대로예요.","무엇에 대한 글인지 몰라요.","핵심 장면이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#21','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C18',3,'error','auto','「운동장 그림자」를 읽고 모둠에서 나눈 말이에요. 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X18','K5-2-u1-X17']::text[],false,'{"seq":21,"concept":"K5-2-u1-C18","difficulty":3,"kind":"error","stem":"「운동장 그림자」를 읽고 모둠에서 나눈 말이에요. 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"「그건 시랑 상관없는 네 이야기잖아.」","correct":true,"mis_target":"K5-2-u1-X16"},{"t":"「네 경험을 들으니 마지막 연이 다르게 읽혀.」","mis":"K5-2-u1-X18"},{"t":"「나는 셋째 연을 골랐는데, 네가 고른 까닭도 들어 볼래.」","mis":"K5-2-u1-X17"}],"explanation":["친구 말에서 배웠어요.","끝까지 들으려 해요.","친구의 까닭을 듣기 전에 깎아내렸어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#22','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C26',3,'mc','auto','「세종 대왕」에서 본받을 점을 오늘의 나와 바르게 이은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21']::text[],false,'{"seq":22,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「세종 대왕」에서 본받을 점을 오늘의 나와 바르게 이은 것은 어느 것인가요?","options":[{"t":"어려워하는 친구를 위해 쉽게 설명하는 방법을 고민한다","correct":true},{"t":"옛날 임금 이야기라 나와는 관계없다","mis":"K5-2-u1-X24"},{"t":"글자를 새로 만들어 친구들에게 쓰라고 한다","mis":"K5-2-u1-X21"},{"t":"밤늦게 촛불을 켜고 공부한다","mis":"K5-2-u1-X21"}],"explanation":["옛이야기도 오늘과 이어져요.","흉내가 본받기는 아니에요.","장면만 따라 하면 뜻을 놓쳐요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#23','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C10',4,'essay','teacher','「종이비행기」의 말하는 이가 누구에게 어떤 마음으로 하는 말인지 쓰고, 시 전체의 분위기와 그렇게 느낀 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C10","difficulty":4,"kind":"essay","stem":"「종이비행기」의 말하는 이가 누구에게 어떤 마음으로 하는 말인지 쓰고, 시 전체의 분위기와 그렇게 느낀 까닭을 쓰세요.","answer_guide":{"answer":"예: 처음 무엇을 해 보며 실수할까 걱정하는 친구에게 응원하는 마음으로 하는 말이다. 시 전체가 다정하고 따뜻한 분위기이다. 「삐뚤어도 괜찮아」, 「빙글 돌아와도 좋아」처럼 잘못해도 괜찮다고 감싸 주는 말이 이어지고, 마지막에 「네가 접었다는 게 중요해」라고 해서 잘 날았는지보다 해 본 것을 칭찬하기 때문이다.","scoring_points":["누구에게 하는 말인지 썼는가","말하는 이의 마음을 썼는가","분위기와 까닭을 시와 이어 썼는가"]},"explanation":["「너」가 누구일지 떠올려요.","마음을 짐작해요.","분위기의 까닭을 시에서 찾아요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#24','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C23',4,'essay','teacher','「세종 대왕」에서 인상적인 부분을 하나 고르고, 그 무렵의 상황과 이어 인상적인 까닭을 쓴 뒤 세종 대왕에게 묻고 싶은 질문을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C23","difficulty":4,"kind":"essay","stem":"「세종 대왕」에서 인상적인 부분을 하나 고르고, 그 무렵의 상황과 이어 인상적인 까닭을 쓴 뒤 세종 대왕에게 묻고 싶은 질문을 하나 쓰세요.","answer_guide":{"answer":"예: 학자들과 오랫동안 연구하여 훈민정음을 만든 부분이 인상적이다. 그 무렵 백성들은 한자를 몰라 억울한 일이 있어도 글로 남기지 못했는데, 임금이 그 어려움을 살펴 누구나 쓸 수 있는 글자를 만들었기 때문이다. 질문 — 「글자를 만들자고 했을 때 반대하는 사람은 없었나요? 그때 어떻게 마음을 지켰나요?」","scoring_points":["인상적인 부분을 골랐는가","시대 상황과 이어 까닭을 썼는가","인상적인 부분에서 나온 질문을 썼는가"]},"explanation":["부분을 골라요.","그 무렵 상황과 이어요.","마음을 묻는 질문을 만들어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_b#25','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C4',4,'essay','teacher','시와 이야기에서 인상적인 부분을 찾을 때 살피는 것이 어떻게 다른지 쓰고, 이 단원에서 읽은 작품으로 예를 하나씩 드세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C4","difficulty":4,"kind":"essay","stem":"시와 이야기에서 인상적인 부분을 찾을 때 살피는 것이 어떻게 다른지 쓰고, 이 단원에서 읽은 작품으로 예를 하나씩 드세요.","answer_guide":{"answer":"예: 시에서는 독특한 표현, 말하는 이의 마음, 분위기를 살핀다. 예를 들어 「말의 온도」에서는 「말은 마음에 찍히는 발자국」이라는 빗댄 표현이 인상적이다. 이야기에서는 인물이 처한 상황, 인물의 말과 행동, 사건의 흐름을 살핀다. 예를 들어 「유관순」에서는 재판에서도 굽히지 않은 행동이 나라를 빼앗긴 상황과 이어져 인상적이다.","scoring_points":["시에서 살필 것을 썼는가","이야기에서 살필 것을 썼는가","작품 예를 하나씩 들었는가"]},"explanation":["시를 떠올려요.","이야기를 떠올려요.","예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#1','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C39',1,'mc','auto','「종이비행기」에서 「나도 실수했을 때 이런 말을 듣고 싶었어」라는 까닭과 가장 잘 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X11']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 「나도 실수했을 때 이런 말을 듣고 싶었어」라는 까닭과 가장 잘 어울리는 문장은 어느 것인가요?","options":[{"t":"「접는 선이 삐뚤어도 괜찮아」","correct":true},{"t":"「멀리 가도 좋고」","mis":"K5-2-u1-X04"},{"t":"「너의 비행기는 날 수 있어」","mis":"K5-2-u1-X04"},{"t":"제목 「종이비행기」","mis":"K5-2-u1-X11"}],"explanation":["실수 이야기와 이어지지 않아요.","실수 이야기와 이어지지 않아요.","실수를 감싸 주는 말이에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#2','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C17',1,'mc','auto','친구마다 인상적인 부분이 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C17","difficulty":1,"kind":"mc","stem":"친구마다 인상적인 부분이 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"경험 · 관심사 · 배경지식이 서로 달라서","correct":true},{"t":"시를 읽는 속도가 달라서","mis":"K5-2-u1-X15"},{"t":"앉은 줄이 달라서","mis":"K5-2-u1-X15"},{"t":"한 사람만 시를 바르게 읽어서","mis":"K5-2-u1-X15"}],"explanation":["속도가 까닭이 아니에요.","앉은 곳과 관계없어요.","바르게 읽은 사람이 하나인 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#3','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C40',1,'ox','auto','「옷을 계절별로 분류하다」는 낱말을 알맞게 쓴 문장이에요.',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"ox","stem":"「옷을 계절별로 분류하다」는 낱말을 알맞게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"계절이라는 기준에 따라 종류별로 나누는 일이기 때문에","correct":true},{"t":"옷을 여러 사람에게 몫으로 나누어 주는 일이기 때문에","mis":"K5-2-u1-X36"}],"mis":"K5-2-u1-X36","explanation":["기준이 있어요.","종류별로 나눠요.","분류하다가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#4','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C40',1,'match','auto','낱말과 알맞은 문장을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"match","stem":"낱말과 알맞은 문장을 이으세요.","pairs":[{"l":"분류하다","r":"자료를 시대별로 나누어 묶는다"},{"l":"분석하다","r":"인물의 성격을 자세히 살핀다"},{"l":"분배하다","r":"도시락을 사람들에게 나누어 준다"}],"mis":"K5-2-u1-X36","explanation":["기준에 따라 묶어요.","부분으로 나누어 살펴요.","몫으로 나누어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#5','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C22',1,'mc','auto','「세종 대왕」에서 그 무렵 백성들이 겪은 어려움은 무엇인가요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":5,"concept":"K5-2-u1-C22","difficulty":1,"kind":"mc","stem":"「세종 대왕」에서 그 무렵 백성들이 겪은 어려움은 무엇인가요?","options":[{"t":"어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했다","correct":true},{"t":"먹을 것이 너무 많았다","mis":"K5-2-u1-X20"},{"t":"글자가 너무 많아 고르기 어려웠다","mis":"K5-2-u1-X20"},{"t":"학교가 너무 멀었다","mis":"K5-2-u1-X20"}],"explanation":["글에 없는 말이에요.","글자가 많아서가 아니에요.","이 상황이 훈민정음을 만든 까닭이에요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#6','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C31',1,'match','auto','글의 종류와 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u1-C31","difficulty":1,"kind":"match","stem":"글의 종류와 그 특징을 알맞게 이으세요.","pairs":[{"l":"독서 감상문","r":"떠오른 생각이나 느낌을 자유롭게 쓴다"},{"l":"서평","r":"좋은 점 · 아쉬운 점을 평가하고 까닭을 밝힌다"},{"l":"전기문","r":"실제 인물의 삶을 사실에 근거해 쓴다"}],"mis":"K5-2-u1-X27","explanation":["느낌을 자유롭게 써요.","평가와 까닭을 밝혀요.","실제 인물의 삶을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#7','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C6',1,'mc','auto','「운동장 그림자」에서 「나를 따라다니는 친구」는 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「운동장 그림자」에서 「나를 따라다니는 친구」는 무엇인가요?","options":[{"t":"내 그림자","correct":true},{"t":"짝꿍","mis":"K5-2-u1-X06"},{"t":"운동장","mis":"K5-2-u1-X06"},{"t":"해","mis":"K5-2-u1-X06"}],"explanation":["사람 친구가 아니에요.","운동장은 곳이에요.","하루 종일 따라다니는 것은 그림자예요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#8','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C37',1,'mc','auto','모둠 토의에서 다양한 의견을 대하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33','K5-2-u1-X32','K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C37","difficulty":1,"kind":"mc","stem":"모둠 토의에서 다양한 의견을 대하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"나와 다른 의견도 인정한다","correct":true},{"t":"뽑히지 않은 의견은 무시한다","mis":"K5-2-u1-X33"},{"t":"내 의견이 뽑힐 때까지 고집한다","mis":"K5-2-u1-X32"},{"t":"다른 의견은 놀린다","mis":"K5-2-u1-X16"}],"explanation":["뽑히지 않은 의견도 소중해요.","기준에 대어 조정해요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#9','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C4',2,'mc','auto','「종이비행기」에서 인상적인 부분을 말할 때 정답이 없다는 것의 바른 뜻은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X02','K5-2-u1-X03']::text[],false,'{"seq":9,"concept":"K5-2-u1-C4","difficulty":2,"kind":"mc","stem":"「종이비행기」에서 인상적인 부분을 말할 때 정답이 없다는 것의 바른 뜻은 어느 것인가요?","options":[{"t":"어느 줄을 골라도 되지만 그 까닭은 시와 이어져야 한다","correct":true},{"t":"아무 까닭이나 대도 된다","mis":"K5-2-u1-X04"},{"t":"첫째 줄만 골라야 한다","mis":"K5-2-u1-X02"},{"t":"까닭은 말하지 않아도 된다","mis":"K5-2-u1-X03"}],"explanation":["까닭은 시와 이어져야 해요.","정해진 줄이 없어요.","까닭이 함께 가요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#10','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C13',2,'mc','auto','「종이비행기」에 공감한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X12','K5-2-u1-X01']::text[],false,'{"seq":10,"concept":"K5-2-u1-C13","difficulty":2,"kind":"mc","stem":"「종이비행기」에 공감한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「만들기를 망쳤을 때 선생님이 〈네가 만든 게 중요해〉라고 해 주셔서 힘이 났던 일이 떠올라.」","correct":true},{"t":"「나는 비행기를 타 본 적이 없어서 공감할 수 없어.」","mis":"K5-2-u1-X12"},{"t":"「종이라는 낱말이 쉬워서.」","mis":"K5-2-u1-X01"},{"t":"「다섯 줄이라서.」","mis":"K5-2-u1-X01"}],"explanation":["똑같은 일을 겪지 않아도 공감해요.","낱말이 쉬운 것은 까닭이 아니에요.","줄 수는 까닭이 아니에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#11','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C11',2,'ox','auto','「종이비행기」의 「처음 접은 한 줄」은 처음 시작한 마음을 빗대어 나타냈다고 볼 수 있어요.',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"ox","stem":"「종이비행기」의 「처음 접은 한 줄」은 처음 시작한 마음을 빗대어 나타냈다고 볼 수 있어요.","answer":"O","reason_options":[{"t":"첫 줄을 기억하면 날 수 있다는 말이 처음 마음을 잃지 말라는 뜻과 닮았기 때문에","correct":true},{"t":"종이에 접은 선 한 줄만을 글자 그대로 말하기 때문에","mis":"K5-2-u1-X09"}],"mis":"K5-2-u1-X09","explanation":["닮은 점을 찾아요.","글자 그대로만 읽지 않아요.","처음 마음과 닮았어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#12','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C21',2,'mc','auto','전기문을 바르게 읽는 방법은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X20']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"mc","stem":"전기문을 바르게 읽는 방법은 어느 것인가요?","options":[{"t":"확인된 사실과 작가가 다시 꾸몄을 수 있는 부분을 가려 읽는다","correct":true},{"t":"적힌 말을 모두 그날 그대로의 말로 믿는다","mis":"K5-2-u1-X19"},{"t":"지어낸 이야기로 여기고 가볍게 읽는다","mis":"K5-2-u1-X18"},{"t":"연도만 골라 외운다","mis":"K5-2-u1-X20"}],"explanation":["그대로라고 단정할 수 없어요.","사실에 근거한 글이에요.","외우기가 목적이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#13','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C22',2,'ox','auto','유관순과 세종 대왕이 한 일은 그 시대의 상황을 알아야 더 잘 이해할 수 있어요.',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":13,"concept":"K5-2-u1-C22","difficulty":2,"kind":"ox","stem":"유관순과 세종 대왕이 한 일은 그 시대의 상황을 알아야 더 잘 이해할 수 있어요.","answer":"O","reason_options":[{"t":"인물이 처한 상황이 그 일을 한 까닭이 되기 때문에","correct":true},{"t":"인물이 한 일은 시대와 관계없이 이해되기 때문에","mis":"K5-2-u1-X20"}],"mis":"K5-2-u1-X20","explanation":["시대가 까닭을 알려 줘요.","상황과 행동을 이어요.","때와 곳을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#14','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C28',2,'mc','auto','서평에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X26']::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"mc","stem":"서평에 꼭 들어갈 내용이 아닌 것은 어느 것인가요?","options":[{"t":"책을 산 가게의 이름","correct":true},{"t":"인상적인 부분과 그 까닭","mis":"K5-2-u1-X25"},{"t":"책에 대한 평가","mis":"K5-2-u1-X26"},{"t":"간단한 줄거리","mis":"K5-2-u1-X25"}],"explanation":["서평에 들어가요.","서평에 들어가요.","서평에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#15','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C34',2,'mc','auto','「이달의 책」 후보로 가장 알맞지 않은 책은 어느 것인가요?',ARRAY['K5-2-u1-X31']::text[],false,'{"seq":15,"concept":"K5-2-u1-C34","difficulty":2,"kind":"mc","stem":"「이달의 책」 후보로 가장 알맞지 않은 책은 어느 것인가요?","options":[{"t":"어려운 낱말이 가득해 반에서 한두 명만 읽을 수 있는 책","correct":true},{"t":"친구와의 우정을 다룬 흥미로운 동화","mis":"K5-2-u1-X31"},{"t":"끝까지 하는 마음을 알려 주는 이야기","mis":"K5-2-u1-X31"},{"t":"누구나 읽기 쉬운 따뜻한 이야기","mis":"K5-2-u1-X31"}],"explanation":["흥미로운 이야기는 좋아요.","교훈을 주는 이야기는 좋아요.","너무 어려운 책은 피해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#16','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C40',2,'blank','auto','「도서관 책을 과학 · 역사 · 동화로 (     )」에 들어갈 낱말은 무엇인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"blank","stem":"「도서관 책을 과학 · 역사 · 동화로 (     )」에 들어갈 낱말은 무엇인가요?","options":[{"t":"분류하다","correct":true},{"t":"분배하다","mis":"K5-2-u1-X36"},{"t":"분석하다","mis":"K5-2-u1-X36"},{"t":"분리수거하다","mis":"K5-2-u1-X36"}],"explanation":["나누어 주는 게 아니에요.","살피는 게 아니에요.","종류별로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#17','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C10',3,'mc','auto','「운동장 그림자」의 말하는 이의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"mc","stem":"「운동장 그림자」의 말하는 이의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"하루 종일 함께하는 그림자가 친구처럼 반갑고 든든한 마음","correct":true},{"t":"그림자가 무서운 마음","mis":"K5-2-u1-X07"},{"t":"그림자가 귀찮은 마음","mis":"K5-2-u1-X07"},{"t":"운동장이 싫은 마음","mis":"K5-2-u1-X07"}],"explanation":["무섭다는 말은 없어요.","귀찮다는 말은 없어요.","마지막 연에서 친구라고 했어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#18','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C16',3,'mc','auto','「종이비행기」를 모둠이 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":18,"concept":"K5-2-u1-C16","difficulty":3,"kind":"mc","stem":"「종이비행기」를 모둠이 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"마지막 줄 「네가 접었다는 게 중요해」를 모두 함께 힘주어 천천히 읽는다","correct":true},{"t":"한 사람이 모든 줄을 빠르게 읽는다","mis":"K5-2-u1-X10"},{"t":"마지막 줄만 빼고 읽는다","mis":"K5-2-u1-X10"},{"t":"모든 줄을 같은 크기로 읽는다","mis":"K5-2-u1-X10"}],"explanation":["나누어 맡아요.","하고 싶은 말이 마지막 줄에 있어요.","강약을 살려요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#19','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C25',3,'error','auto','「유관순」을 읽고 만든 질문이에요. 인상적인 부분을 중심으로 만든 질문이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X23','K5-2-u1-X25']::text[],false,'{"seq":19,"concept":"K5-2-u1-C25","difficulty":3,"kind":"error","stem":"「유관순」을 읽고 만든 질문이에요. 인상적인 부분을 중심으로 만든 질문이 아닌 것은 어느 것인가요?","options":[{"t":"「충청남도는 어디에 있나요?」","correct":true,"mis_target":"K5-2-u1-X23"},{"t":"「사람들 앞에서 외칠 때 떨리지 않았나요?」","mis":"K5-2-u1-X25"},{"t":"「고향 사람들에게 글을 가르치며 무엇을 바랐나요?」","mis":"K5-2-u1-X25"}],"explanation":["장면에서 나온 질문이에요.","장면에서 나온 질문이에요.","인물의 마음과 관계없는 질문이에요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#20','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C30',3,'error','auto','「등대 아래 도서관」의 평가로 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X30']::text[],false,'{"seq":20,"concept":"K5-2-u1-C30","difficulty":3,"kind":"error","stem":"「등대 아래 도서관」의 평가로 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「완벽한 책이다. 아쉬운 점은 쓰면 안 된다.」","correct":true,"mis_target":"K5-2-u1-X26"},{"t":"「작은 일을 끝까지 해내는 마음이 잘 보여 책을 아끼는 친구에게 권한다.」","mis":"K5-2-u1-X30"},{"t":"「할머니 이야기가 더 나오지 않아 아쉽다.」","mis":"K5-2-u1-X30"}],"explanation":["까닭과 추천이 있어요.","아쉬운 점도 평가예요.","좋은 점만 쓰려 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#21','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C18',3,'mc','auto','하람이가 도윤이의 말을 끝까지 들었다면 얻을 수 있었던 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X15','K5-2-u1-X06']::text[],false,'{"seq":21,"concept":"K5-2-u1-C18","difficulty":3,"kind":"mc","stem":"하람이가 도윤이의 말을 끝까지 들었다면 얻을 수 있었던 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 연을 외로울 때 곁을 지켜 주는 친구 이야기로 새롭게 읽게 된다","correct":true},{"t":"셋째 연이 정답이라는 확신","mis":"K5-2-u1-X02"},{"t":"도윤이가 틀렸다는 증거","mis":"K5-2-u1-X15"},{"t":"시를 다시 읽지 않아도 된다는 생각","mis":"K5-2-u1-X06"}],"explanation":["정답 연은 없어요.","틀린 사람은 없어요.","다른 의견이 생각을 넓혀요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#22','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C39',3,'error','auto','친구들이 고른 인상적인 문장과 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X08','K5-2-u1-X01']::text[],false,'{"seq":22,"concept":"K5-2-u1-C39","difficulty":3,"kind":"error","stem":"친구들이 고른 인상적인 문장과 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「〈괜찮아〉는 너무 짧고 쉬워서 인상적인 문장이 될 수 없어.」","correct":true,"mis_target":"K5-2-u1-X35"},{"t":"「〈괜찮아〉가 속상할 때 나를 다독이던 엄마 말 같아서 골랐어.」","mis":"K5-2-u1-X08"},{"t":"「〈사뿐사뿐 디뎌야 해〉에서 말을 조심하자는 깨달음이 생겼어.」","mis":"K5-2-u1-X01"}],"explanation":["경험과 이어진 까닭이에요.","깨달음이 까닭이에요.","짧은 문장도 인상적일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#23','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C8',4,'essay','teacher','하람이가 「그건 시랑 상관없는 네 이야기잖아」라고 했을 때, 도윤이 편에서 해 줄 말을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C8","difficulty":4,"kind":"essay","stem":"하람이가 「그건 시랑 상관없는 네 이야기잖아」라고 했을 때, 도윤이 편에서 해 줄 말을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도윤이가 고른 마지막 연은 「하루 종일 / 나를 따라다니는 친구가 있다」이다. 혼자 있을 때 그림자가 친구 같았던 경험은 바로 이 연의 내용과 이어진다. 시 속 일과 닮은 내 경험이 떠올라 공감하는 것도 인상적인 까닭이 될 수 있으니, 도윤이의 까닭도 들어 볼 만하다.","scoring_points":["도윤이가 고른 연을 짚었는가","경험이 시와 이어짐을 썼는가","경험도 까닭이 된다는 뜻을 썼는가"]},"explanation":["도윤이가 고른 연을 봐요.","경험과 시를 이어요.","공감도 까닭임을 말해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#24','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C30',4,'essay','teacher','「낡은 책이 다시 숨 쉬는 곳」을 읽고 이 서평의 좋은 점 한 가지와 더 보태면 좋을 점 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C30","difficulty":4,"kind":"essay","stem":"「낡은 책이 다시 숨 쉬는 곳」을 읽고 이 서평의 좋은 점 한 가지와 더 보태면 좋을 점 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 인상적인 부분으로 젖은 책을 말리는 장면을 고르고, 작은 일을 끝까지 해내는 마음이 보인다는 까닭을 들어 읽는 사람도 그 장면이 궁금해진다. 보탤 점 — 지은이와 이 책이 어떤 독자를 위한 책인지 책 소개에 더 넣으면 좋겠다. 책을 고를 때 누가 읽기 좋은지 미리 알 수 있기 때문이다.","scoring_points":["좋은 점을 까닭과 함께 썼는가","보탤 점을 까닭과 함께 썼는가","서평에 들어갈 내용과 이어 썼는가"]},"explanation":["잘된 칸을 찾아요.","빠진 칸을 찾아요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_c#25','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C31',4,'essay','teacher','독서 감상문과 서평의 차이를 쓰고, 친구에게 책을 추천하려면 어느 글이 더 알맞은지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C31","difficulty":4,"kind":"essay","stem":"독서 감상문과 서평의 차이를 쓰고, 친구에게 책을 추천하려면 어느 글이 더 알맞은지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 독서 감상문은 책을 읽고 떠오른 생각이나 느낌을 자유롭게 쓴 글이고, 서평은 책의 좋은 점이나 아쉬운 점을 평가하고 그렇게 생각한 까닭을 함께 밝힌 글이다. 친구에게 책을 추천하려면 서평이 더 알맞다. 서평에는 누구에게 왜 이 책을 권하는지가 들어 있어 친구가 읽을지 말지 판단하기 쉽기 때문이다.","scoring_points":["두 글의 차이를 썼는가","어느 글이 알맞은지 골랐는가","까닭을 썼는가"]},"explanation":["두 글을 견줘요.","추천에 맞는 글을 골라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#1','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C39',1,'blank','auto','인상적인 문장은 길고 어려운 문장이 아니라 (     ) 문장이에요.',ARRAY['K5-2-u1-X35','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"blank","stem":"인상적인 문장은 길고 어려운 문장이 아니라 (     ) 문장이에요.","options":[{"t":"마음이 움직이거나 깨달음이 생긴","correct":true},{"t":"어려운 낱말이 가장 많은","mis":"K5-2-u1-X35"},{"t":"책에서 가장 긴","mis":"K5-2-u1-X35"},{"t":"선생님이 밑줄 그어 준","mis":"K5-2-u1-X02"}],"explanation":["낱말의 어려움이 기준이 아니에요.","길이가 기준이 아니에요.","정해 준 문장이 따로 있지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#2','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C2',1,'ox','auto','작품의 인상적인 부분은 사람마다 다를 수 있어요.',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"작품의 인상적인 부분은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"같은 작품도 저마다의 경험과 생각에 따라 마음에 남는 곳이 다르기 때문에","correct":true},{"t":"작품마다 정답인 부분이 하나씩 있기 때문에","mis":"K5-2-u1-X02"}],"mis":"K5-2-u1-X02","explanation":["사람마다 달라요.","정답이 하나가 아니에요.","그래서 의견을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#3','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',1,'mc','auto','「분류하다」를 알맞게 쓴 문장은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":3,"concept":"K5-2-u1-C40","difficulty":1,"kind":"mc","stem":"「분류하다」를 알맞게 쓴 문장은 어느 것인가요?","options":[{"t":"식물을 잎의 모양에 따라 분류했다.","correct":true},{"t":"우승 상금을 고르게 분류했다.","mis":"K5-2-u1-X36"},{"t":"실험에서 얻은 자료를 꼼꼼히 분류했다.","mis":"K5-2-u1-X36"},{"t":"간식을 친구들에게 분류했다.","mis":"K5-2-u1-X36"}],"explanation":["상금은 분배해요.","자료를 살필 때는 분석해요.","간식은 나누어 주니 분배해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#4','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',1,'ox','auto','「인물의 성격을 분배하다」는 낱말을 알맞게 쓴 문장이에요.',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":4,"concept":"K5-2-u1-C40","difficulty":1,"kind":"ox","stem":"「인물의 성격을 분배하다」는 낱말을 알맞게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"성격을 자세히 살피는 일이므로 「분석하다」가 알맞기 때문에","correct":true},{"t":"「분배하다」는 무엇이든 나눌 때 쓰기 때문에","mis":"K5-2-u1-X36"}],"mis":"K5-2-u1-X36","explanation":["몫으로 나누어 주는 일이 아니에요.","자세히 살피는 일이에요.","분석하다가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#5','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C20',1,'mc','auto','전기문을 읽으면 얻을 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X18','K5-2-u1-X24']::text[],false,'{"seq":5,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"전기문을 읽으면 얻을 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실제 인물의 삶에서 감동과 교훈","correct":true},{"t":"지어낸 마법 이야기의 재미","mis":"K5-2-u1-X18"},{"t":"날씨를 맞히는 방법","mis":"K5-2-u1-X24"},{"t":"책값을 아끼는 방법","mis":"K5-2-u1-X24"}],"explanation":["지어낸 이야기가 아니에요.","날씨와 관계없어요.","인물의 삶에서 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#6','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C27',1,'mc','auto','서평 「낡은 책이 다시 숨 쉬는 곳」에서 평가가 드러난 문장은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":6,"concept":"K5-2-u1-C27","difficulty":1,"kind":"mc","stem":"서평 「낡은 책이 다시 숨 쉬는 곳」에서 평가가 드러난 문장은 어느 것인가요?","options":[{"t":"「할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요.」","correct":true},{"t":"「바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.」","mis":"K5-2-u1-X25"},{"t":"「친구들과 도서관을 다시 열어요.」","mis":"K5-2-u1-X25"},{"t":"제목 「낡은 책이 다시 숨 쉬는 곳」","mis":"K5-2-u1-X29"}],"explanation":["책 소개예요.","줄거리예요.","아쉬운 점과 까닭이 있어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#7','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C6',1,'mc','auto','「종이비행기」에서 비행기가 날 수 있다고 한 조건은 무엇인가요?',ARRAY['K5-2-u1-X06']::text[],false,'{"seq":7,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 비행기가 날 수 있다고 한 조건은 무엇인가요?","options":[{"t":"처음 접은 한 줄을 기억하는 것","correct":true},{"t":"선을 반듯하게 접는 것","mis":"K5-2-u1-X06"},{"t":"멀리 던지는 것","mis":"K5-2-u1-X06"},{"t":"비싼 종이를 쓰는 것","mis":"K5-2-u1-X06"}],"explanation":["삐뚤어도 괜찮다고 했어요.","멀리 가는 건 조건이 아니에요.","둘째 줄에 나와요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#8','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C35',1,'mc','auto','친구의 추천 까닭을 듣고 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X34']::text[],false,'{"seq":8,"concept":"K5-2-u1-C35","difficulty":1,"kind":"mc","stem":"친구의 추천 까닭을 듣고 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"나와 같은 점과 다른 점을 견주어 본다","correct":true},{"t":"바로 내 책이 더 좋다고 말한다","mis":"K5-2-u1-X16"},{"t":"듣지 않고 내 차례를 기다린다","mis":"K5-2-u1-X16"},{"t":"친구 책 제목만 적는다","mis":"K5-2-u1-X34"}],"explanation":["견주기 전에 정하지 않아요.","들어야 견줘요.","제목만으로는 부족해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#9','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C3',2,'mc','auto','인상적인 부분을 말하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04','K5-2-u1-X02']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"인상적인 부분을 말하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고른 부분을 말하고 그 부분이 인상적인 까닭을 작품과 이어 말한다","correct":true},{"t":"고른 부분만 짧게 말한다","mis":"K5-2-u1-X03"},{"t":"작품과 상관없는 내 하루 일을 말한다","mis":"K5-2-u1-X04"},{"t":"친구가 고른 부분을 따라 말한다","mis":"K5-2-u1-X02"}],"explanation":["까닭이 빠졌어요.","작품과 이어지지 않아요.","내 생각을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#10','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C8',2,'error','auto','「종이비행기」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X07']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"error","stem":"「종이비행기」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「내 경험으로 고른 건 시와 상관없어서 말하면 안 돼.」","correct":true,"mis_target":"K5-2-u1-X08"},{"t":"「나도 실수할 때 괜찮다는 말을 듣고 싶었어서 첫째 줄을 골랐어.」","mis":"K5-2-u1-X08"},{"t":"「〈빙글 돌아와도 좋아〉에서 실패해도 괜찮다는 느낌이 들었어.」","mis":"K5-2-u1-X07"}],"explanation":["경험과 이어진 까닭이에요.","표현과 이어진 까닭이에요.","내 경험도 까닭이 돼요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#11','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C7',2,'mc','auto','「운동장 그림자」에서 독특하고 재미있는 표현은 어느 것인가요?',ARRAY['K5-2-u1-X01']::text[],false,'{"seq":11,"concept":"K5-2-u1-C7","difficulty":2,"kind":"mc","stem":"「운동장 그림자」에서 독특하고 재미있는 표현은 어느 것인가요?","options":[{"t":"「그림자가 먼저 집으로 달려간다」","correct":true},{"t":"「아침 운동장에선」","mis":"K5-2-u1-X01"},{"t":"「저녁 운동장에선」","mis":"K5-2-u1-X01"},{"t":"「나는 하루 종일」","mis":"K5-2-u1-X01"}],"explanation":["때를 나타낸 말이에요.","때를 나타낸 말이에요.","그림자를 사람처럼 나타냈어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#12','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C21',2,'error','auto','「세종 대왕」을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X21']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"error","stem":"「세종 대왕」을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「혼잣말 장면은 누가 옆에서 받아 적은 거니까 사실이야.」","correct":true,"mis_target":"K5-2-u1-X19"},{"t":"「훈민정음을 만든 것은 역사적 사실이야.」","mis":"K5-2-u1-X18"},{"t":"「촛불 장면은 작가가 그때 마음을 상상해 그린 것 같아.」","mis":"K5-2-u1-X21"}],"explanation":["사실을 바르게 말했어요.","꾸민 부분을 알아봤어요.","꾸민 장면을 사실로 단정했어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#13','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C23',2,'mc','auto','「밤늦도록 촛불 아래에서 글자를 다듬었다」는 장면에서 짐작할 수 있는 마음은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":13,"concept":"K5-2-u1-C23","difficulty":2,"kind":"mc","stem":"「밤늦도록 촛불 아래에서 글자를 다듬었다」는 장면에서 짐작할 수 있는 마음은 어느 것인가요?","options":[{"t":"백성을 위해 쉬운 글자를 꼭 만들고 싶은 마음","correct":true},{"t":"잠이 오지 않아 심심한 마음","mis":"K5-2-u1-X21"},{"t":"촛불을 아끼고 싶은 마음","mis":"K5-2-u1-X21"},{"t":"학자들을 혼내고 싶은 마음","mis":"K5-2-u1-X21"}],"explanation":["백성의 어려움과 이어 봐요.","촛불이 중심이 아니에요.","상황과 행동을 이어 짐작해요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#14','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C28',2,'blank','auto','서평에 들어갈 내용은 제목, 책 소개, 줄거리, 인상적인 부분과 그 까닭, (     )예요.',ARRAY['K5-2-u1-X25']::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"blank","stem":"서평에 들어갈 내용은 제목, 책 소개, 줄거리, 인상적인 부분과 그 까닭, (     )예요.","options":[{"t":"책에 대한 평가","correct":true},{"t":"책의 값","mis":"K5-2-u1-X25"},{"t":"지은이의 사진","mis":"K5-2-u1-X25"},{"t":"다 읽은 날짜","mis":"K5-2-u1-X25"}],"explanation":["값은 들어가지 않아요.","사진은 들어가지 않아요.","좋은 점 · 아쉬운 점 · 추천을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#15','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C37',2,'mc','auto','「이달의 책」으로 뽑히지 않은 책을 대하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":15,"concept":"K5-2-u1-C37","difficulty":2,"kind":"mc","stem":"「이달의 책」으로 뽑히지 않은 책을 대하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"다음 달 후보로 남기고 목록을 함께 나눈다","correct":true},{"t":"나쁜 책이라고 알린다","mis":"K5-2-u1-X33"},{"t":"추천한 친구의 의견은 쓸모없었다고 한다","mis":"K5-2-u1-X33"},{"t":"다시는 말하지 않는다","mis":"K5-2-u1-X33"}],"explanation":["뽑히지 않았다고 나쁜 책이 아니에요.","추천 까닭도 쓸모가 있어요.","다양한 의견을 인정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#16','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',2,'error','auto','낱말을 쓴 문장이에요. 알맞지 않은 문장은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"error","stem":"낱말을 쓴 문장이에요. 알맞지 않은 문장은 어느 것인가요?","options":[{"t":"「간식을 모둠마다 고르게 분석했다.」","correct":true,"mis_target":"K5-2-u1-X36"},{"t":"「모은 자료를 시대별로 분류했다.」","mis":"K5-2-u1-X36"},{"t":"「이야기 속 인물의 성격을 분석했다.」","mis":"K5-2-u1-X36"}],"explanation":["바르게 썼어요.","바르게 썼어요.","나누어 주는 일은 「분배하다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#17','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C10',3,'ox','auto','「종이비행기」에서는 한 구절이 아니라 시 전체의 다정한 분위기를 인상적인 부분으로 말할 수 있어요.',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"ox","stem":"「종이비행기」에서는 한 구절이 아니라 시 전체의 다정한 분위기를 인상적인 부분으로 말할 수 있어요.","answer":"O","reason_options":[{"t":"말하는 이의 마음이나 시 전체의 분위기도 인상적인 부분이 되기 때문에","correct":true},{"t":"인상적인 부분은 한 구절에서만 골라야 하기 때문에","mis":"K5-2-u1-X07"}],"mis":"K5-2-u1-X07","explanation":["분위기도 돼요.","구절에만 머물지 않아요.","시 전체에서 느낀 것도 돼요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#18','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C15',3,'ox','auto','「괜찮아, 나」와 「운동장 그림자」처럼 시 속 모습이나 마음은 연마다 바뀔 수 있어요.',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":18,"concept":"K5-2-u1-C15","difficulty":3,"kind":"ox","stem":"「괜찮아, 나」와 「운동장 그림자」처럼 시 속 모습이나 마음은 연마다 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"연을 따라 읽으면 마음이나 모습이 어떻게 바뀌는지 보이기 때문에","correct":true},{"t":"시는 처음 연에서 모든 것이 정해지기 때문에","mis":"K5-2-u1-X14"}],"mis":"K5-2-u1-X14","explanation":["연마다 따라가요.","처음 연이 다가 아니에요.","흐름을 보며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#19','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C24',3,'ox','auto','이야기에서는 사건의 흐름이나 인물의 변화도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X22']::text[],false,'{"seq":19,"concept":"K5-2-u1-C24","difficulty":3,"kind":"ox","stem":"이야기에서는 사건의 흐름이나 인물의 변화도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"이야기는 인물 · 사건 · 때와 곳이 작품을 이해하는 데 영향을 주기 때문에","correct":true},{"t":"이야기에서는 가장 큰 사건 한 장면만 인상적이기 때문에","mis":"K5-2-u1-X22"}],"mis":"K5-2-u1-X22","explanation":["흐름도 돼요.","변화도 돼요.","여러 가지를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#20','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C33',3,'mc','auto','서평을 돌려 읽은 친구가 「인상적인 부분은 있는데 왜 인상적인지가 없어」라고 했을 때 고쳐 쓰는 방법은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":20,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 돌려 읽은 친구가 「인상적인 부분은 있는데 왜 인상적인지가 없어」라고 했을 때 고쳐 쓰는 방법은 어느 것인가요?","options":[{"t":"그 장면이 왜 마음에 남았는지 까닭을 한 문장 보탠다","correct":true},{"t":"인상적인 부분을 지운다","mis":"K5-2-u1-X30"},{"t":"줄거리를 더 길게 쓴다","mis":"K5-2-u1-X25"},{"t":"친구 의견은 듣지 않고 그대로 둔다","mis":"K5-2-u1-X30"}],"explanation":["지우면 중심이 빠져요.","줄거리가 문제가 아니에요.","받은 의견을 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#21','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C17',3,'ox','auto','배경지식이 다르면 같은 시에서도 인상적인 까닭이 달라질 수 있어요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":21,"concept":"K5-2-u1-C17","difficulty":3,"kind":"ox","stem":"배경지식이 다르면 같은 시에서도 인상적인 까닭이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"아는 것이 다르면 같은 표현에서도 떠오르는 생각이 다르기 때문에","correct":true},{"t":"배경지식은 시 감상과 관계없기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["아는 것이 생각을 바꿔요.","경험 · 관심사 · 배경지식","그래서 서로 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#22','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C26',3,'ox','auto','오래전 인물의 전기문도 오늘 나의 생활에 도움을 줄 수 있어요.',ARRAY['K5-2-u1-X24']::text[],false,'{"seq":22,"concept":"K5-2-u1-C26","difficulty":3,"kind":"ox","stem":"오래전 인물의 전기문도 오늘 나의 생활에 도움을 줄 수 있어요.","answer":"O","reason_options":[{"t":"인물의 삶에서 본받을 점을 찾아 지금의 삶과 이어 볼 수 있기 때문에","correct":true},{"t":"옛날 인물은 지금과 사는 모습이 달라 배울 것이 없기 때문에","mis":"K5-2-u1-X24"}],"mis":"K5-2-u1-X24","explanation":["본받을 점을 찾아요.","오늘과 이어요.","시대가 달라도 배울 게 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#23','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C39',4,'essay','teacher','「종이비행기」나 이 단원에서 읽은 시에서 가장 인상적인 문장 하나를 골라, 내 경험과 이어 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C39","difficulty":4,"kind":"essay","stem":"「종이비행기」나 이 단원에서 읽은 시에서 가장 인상적인 문장 하나를 골라, 내 경험과 이어 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「네가 접었다는 게 중요해」가 가장 인상적이다. 미술 시간에 만든 작품이 친구 것보다 못나 보여 속상했을 때, 선생님이 끝까지 만든 것이 멋지다고 해 주셔서 힘이 났던 일이 떠올랐다. 잘하고 못하고보다 해 보는 것이 중요하다는 깨달음을 주어서 이 문장을 골랐다.","scoring_points":["문장을 골랐는가","내 경험을 썼는가","경험과 문장을 이어 까닭을 썼는가"]},"explanation":["한 문장을 골라요.","떠오른 경험을 써요.","둘을 이어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#24','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C36',4,'essay','teacher','모둠에서 「이달의 책」을 고르다 의견이 갈렸어요. 기준을 하나 세워 쓰고, 그 기준으로 조정하는 과정과 뽑히지 않은 책을 대하는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C36","difficulty":4,"kind":"essay","stem":"모둠에서 「이달의 책」을 고르다 의견이 갈렸어요. 기준을 하나 세워 쓰고, 그 기준으로 조정하는 과정과 뽑히지 않은 책을 대하는 방법을 쓰세요.","answer_guide":{"answer":"예: 기준 — 「반 친구들 모두가 흥미롭게 읽을 수 있는가」. 먼저 친구들의 추천 까닭을 끝까지 듣고, 각 책을 이 기준에 대어 견준다. 누구나 읽기 쉽고 이야기 나눌 거리가 많은 책을 고른다. 뽑히지 않은 책은 목록에 적어 다음 달 후보로 남기고, 추천한 친구 덕분에 새 책을 알게 되었다고 고마움을 전한다.","scoring_points":["기준을 세웠는가","기준에 대어 조정하는 과정을 썼는가","뽑히지 않은 책을 존중하는 방법을 썼는가"]},"explanation":["기준을 정해요.","대어 견줘요.","다른 의견을 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u1_review_d#25','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C5',4,'essay','teacher','이 단원에서 한 활동(시 · 이야기 · 서평 · 「이달의 책」) 가운데 가장 기억에 남는 활동 하나를 고르고, 그 활동에서 배운 점과 앞으로 책을 읽을 때 해 보고 싶은 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C5","difficulty":4,"kind":"essay","stem":"이 단원에서 한 활동(시 · 이야기 · 서평 · 「이달의 책」) 가운데 가장 기억에 남는 활동 하나를 고르고, 그 활동에서 배운 점과 앞으로 책을 읽을 때 해 보고 싶은 일을 쓰세요.","answer_guide":{"answer":"예: 「이달의 책」 고르기가 가장 기억에 남는다. 내가 추천한 책은 뽑히지 않았지만, 친구들의 추천 까닭을 들으며 몰랐던 책의 좋은 점을 알게 되었고 기준을 정해 의견을 조정하는 방법을 배웠다. 앞으로 책을 읽으면 인상적인 문장과 그 까닭을 공책에 적어 두었다가 친구에게 추천할 때 써 보고 싶다.","scoring_points":["활동을 하나 골랐는가","배운 점을 썼는가","앞으로 해 보고 싶은 일을 썼는가"]},"explanation":["활동을 떠올려요.","배운 점을 써요.","다음 다짐을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C1','kor',5,2,'u3',1,'지역마다 다른 인사말 — 「어서 오세요 · 어서 오슈 · 어서 오이소 · 혼저 옵서예」처럼 뜻은 같아도 지역에 따라 끝말과 말소리가 다르다',ARRAY['6국04-02 문법']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C2','kor',5,2,'u3',1,'표준어의 뜻 — 우리나라 사람들이 공통으로 쓸 수 있도록 정한 말로, 어느 지역 사람이든 함께 알아듣게 해 준다',ARRAY['6국04-02 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C3','kor',5,2,'u3',1,'방언의 뜻 — 특정 지역에서 주로 쓰는, 표준어가 아닌 말로 도시든 시골이든 그 지역 사람들이 오랫동안 써 온 우리말이다',ARRAY['6국04-02 문법']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C4','kor',5,2,'u3',1,'단원의 흐름 — 표준어와 방언의 뜻 알기 → 쓰는 상황 조사하기 → 방언의 가치 알기 → 방언이 나오는 작품 감상하기 → 방언으로 작품 만들기',ARRAY['6국04-02 문법']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C5','kor',5,2,'u3',2,'방언이 생긴 까닭 — 옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고 이야기할 기회가 적어 지역마다 말이 조금씩 달라졌다(지리적 특성)',ARRAY['6국04-02 문법']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C6','kor',5,2,'u3',2,'표준어를 정한 까닭 — 지역마다 말이 다르면 뜻을 나누기 어려워서 사는 곳이 달라도 원활하게 이야기할 수 있도록 표준어를 정했다',ARRAY['6국04-02 문법']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C7','kor',5,2,'u3',2,'표준어를 정하는 곳과 기준 — 국립국어원이 사람들이 두루 쓰는지 · 문법에 맞는지 · 발음하기 편하고 자연스러운지를 살펴 정한다',ARRAY['6국04-02 문법']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C8','kor',5,2,'u3',2,'방언이 표준어가 되기도 해요 — 「멍게」처럼 방언이 표준어보다 더 널리 쓰이게 되면 표준어로 인정되기도 하여 둘 사이는 움직이는 경계이다',ARRAY['6국04-02 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C9','kor',5,2,'u3',2,'한 낱말을 가리키는 여러 방언 — 개구리(까구리 · 깨고락지) · 부추(분추 · 정구지 · 소풀 · 세우리) · 김치(짐끼 · 짐치)처럼 한 낱말을 지역마다 다르게 부른다',ARRAY['6국04-02 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C10','kor',5,2,'u3',2,'온라인 사전으로 방언 찾기 — 국립국어원 지역어 누리집에서 표준어 낱말을 검색하면 지역별 방언과 발음을 확인할 수 있어 짐작이 아닌 근거로 찾는다',ARRAY['6국04-02 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C11','kor',5,2,'u3',2,'방언은 정답이 하나가 아니에요 — 방언은 같은 지역 안에서도 마을마다 다르고 지역 경계와 똑같이 나뉘지 않아, 서로 다른 답을 근거로 함께 확인한다',ARRAY['6국04-02 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C12','kor',5,2,'u3',4,'상황에 따라 고르는 말 — 뜻이 같은 말도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓴다',ARRAY['6국04-02 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C13','kor',5,2,'u3',4,'표준어가 어울리는 상황 — 뉴스 · 많은 사람 앞 발표 · 학교 방송처럼 여러 지역 사람에게 공식적으로 정확히 전할 때는 주로 표준어를 쓴다',ARRAY['6국04-02 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C14','kor',5,2,'u3',4,'방언이 어울리는 상황 — 고향 친구와 통화 · 시장 단골손님과 대화 · 지역 축제처럼 같은 지역 사람끼리 친근함과 정을 나눌 때 방언을 쓰기도 한다',ARRAY['6국04-02 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C15','kor',5,2,'u3',4,'표준어로 바꾸어 보는 까닭 — 방언을 표준어로 바꾸어 보는 것은 고치기 위해서가 아니라 같은 뜻이 상황에 따라 다르게 골라 쓰인다는 것을 알기 위해서이다',ARRAY['6국04-02 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C16','kor',5,2,'u3',4,'사용 상황 조사의 세 가지 — 누구에게 · 어떤 상황에서 · 어떤 사이인지 살피고, 그 말을 고른 까닭까지 적어야 상황과 말의 관계가 보인다',ARRAY['6국04-02 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C17','kor',5,2,'u3',6,'방언에 담긴 생활 모습 — 올레(좁은 돌담길) · 정낭(대문 가로대) · 삼춘(마을 어른) · 물허벅(물동이)처럼 방언에는 그 마을의 생활과 관계가 담겨 있다',ARRAY['6국04-02 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C18','kor',5,2,'u3',6,'방언에 담긴 자연환경 — 감재옹심이(산이 많은 강원의 감자) · 뻘(넓은 갯벌) · 돔배기(절인 상어고기)처럼 방언에는 지역의 자연과 먹을거리가 반영된다',ARRAY['6국04-02 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C19','kor',5,2,'u3',6,'방언의 가치 — 방언은 지역의 자연환경과 생활 모습, 우리말의 옛 모습, 지역 사람들의 정서를 간직한 지역 문화의 자산이다',ARRAY['6국04-02 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C20','kor',5,2,'u3',6,'방언을 지키는 일 — 방언이 사라지면 그 말에 담긴 생활과 이야기도 잊힐 수 있어 방언 사전 · 그림책처럼 기록해 물려주려는 노력을 한다',ARRAY['6국04-02 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C21','kor',5,2,'u3',8,'줄거리와 인물의 마음 — 방언이 나오는 작품도 먼저 일어난 일과 인물의 마음이 어떻게 바뀌는지를 파악하며 읽는다',ARRAY['6국05-06 문학']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C22','kor',5,2,'u3',8,'앞뒤 장면으로 뜻 짐작하기 — 작품 속 방언의 뜻을 모를 때는 앞뒤 장면으로 짐작하고 사전이나 지역어 누리집으로 확인한다',ARRAY['6국05-06 문학']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C23','kor',5,2,'u3',8,'방언과 표준어로 읽고 느낌 견주기 — 방언을 표준어로 바꾸어도 뜻은 같지만 인물의 목소리와 분위기 같은 느낌은 달라지므로 소리 내어 읽고 견준다',ARRAY['6국05-06 문학']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C24','kor',5,2,'u3',8,'작품에 방언을 쓰면 좋은 점 — 인물이 어디에 사는 누구인지 생생해지고, 인물 사이의 정과 분위기가 살아나며, 지역의 말을 기록하고 지킨다',ARRAY['6국05-06 문학']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C25','kor',5,2,'u3',8,'내 삶과 이어 감상하기 — 방언을 들었던 내 경험과 작품 장면을 이어 보면 인물의 마음을 더 가깝게 느끼고 내 언어생활을 돌아볼 수 있다',ARRAY['6국05-06 문학']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C26','kor',5,2,'u3',10,'방언으로 만드는 작품 — 우리 반 방언 지도 · 방언 노랫말 · 방언 상황극 가운데 고르고, 반 전체 · 모둠 · 짝 · 혼자 가운데 할 방식도 함께 정한다',ARRAY['6국04-02 문법']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C27','kor',5,2,'u3',10,'방언 지도 만드는 차례 — 주제 정하기 → 모둠별 지역 나누기(고른 까닭) → 방언 · 뜻 · 생활 조사하기 → 지도에 지역명과 함께 붙이기',ARRAY['6국04-02 문법']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C28','kor',5,2,'u3',10,'개수보다 뜻과 생활 — 좋은 방언 지도는 방언을 많이 모은 지도가 아니라 방언과 뜻, 그 말과 이어지는 생활이 함께 드러난 지도이다',ARRAY['6국04-02 문법']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C29','kor',5,2,'u3',10,'방언을 존중하는 태도 — 방언을 흉내 내거나 웃음거리로 삼지 않고, 낯선 말도 그 지역 사람의 마음과 생활을 살려 궁금한 마음으로 대한다',ARRAY['6국04-02 문법']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C30','kor',5,2,'u3',12,'함께 어우러지는 우리말 — 표준어는 원활한 의사소통을, 방언은 지역의 특성과 정서를 지켜 주므로 둘은 겨루는 말이 아니라 함께 소중한 우리말이다',ARRAY['6국04-02 문법']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C31','kor',5,2,'u3',12,'상황 카드 — 까닭과 함께 고르기 — 뉴스 · 회의는 표준어, 고향 친구 · 지역 축제는 방언처럼 고르되 까닭을 함께 말하고, 표준어를 쓰는 지역이라면 표준어도 답이 된다',ARRAY['6국04-02 문법']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u3-C32','kor',5,2,'u3',12,'동형어 — 배 · 눈 · 말 · 김 · 쓰다 · 장수처럼 글자 모양은 같지만 뜻이 다른 말을 동형어라 하고, 문장의 앞뒤 말로 뜻을 가린다 (기초 다지기)',ARRAY['기초 다지기(동형어)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X01','kor',5,'u3',ARRAY['K5-2-u3-C3']::text[],'방언은 표준어를 잘못 말한 틀린 말이라고 여긴다','오랫동안 써 온 우리말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X02','kor',5,'u3',ARRAY['K5-2-u3-C1']::text[],'지역마다 인사말의 말소리가 다르면 뜻도 서로 다르다고 여긴다','뜻은 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X03','kor',5,'u3',ARRAY['K5-2-u3-C2','K5-2-u3-C3']::text[],'표준어는 서울 사람만 쓰는 말이고 방언은 시골에서만 쓰는 말이라고 여긴다','도시에도 방언') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X04','kor',5,'u3',ARRAY['K5-2-u3-C4']::text[],'단원에서 배우는 차례를 거꾸로 알거나 작품 감상부터 한다고 여긴다','뜻 → 상황 → 가치 → 작품') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X05','kor',5,'u3',ARRAY['K5-2-u3-C5']::text[],'방언은 옛사람들이 일부러 말을 바꾸었거나 표준어를 몰라서 생겼다고 여긴다','오가기 어려웠어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X06','kor',5,'u3',ARRAY['K5-2-u3-C6']::text[],'표준어는 방언보다 더 높고 고운 말이라서 정했다고 여긴다','함께 알아듣게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X07','kor',5,'u3',ARRAY['K5-2-u3-C7']::text[],'표준어를 아무나 마음대로 정하거나 글자 수 같은 엉뚱한 기준으로 정한다고 여긴다','두루 · 문법 · 발음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X08','kor',5,'u3',ARRAY['K5-2-u3-C8']::text[],'방언은 어떤 경우에도 표준어가 될 수 없다고 여긴다','멍게를 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X09','kor',5,'u3',ARRAY['K5-2-u3-C9']::text[],'한 낱말을 가리키는 방언은 하나뿐이라고 여기거나 서로 다른 방언을 다른 대상으로 여긴다','한 낱말, 여러 이름') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X10','kor',5,'u3',ARRAY['K5-2-u3-C10']::text[],'방언의 뜻을 근거 없이 짐작만으로 정하고 확인하지 않는다','지역어 누리집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X11','kor',5,'u3',ARRAY['K5-2-u3-C11']::text[],'같은 지역이면 방언이 모두 똑같아서 다른 답은 틀렸다고 여긴다','정답은 하나가 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X12','kor',5,'u3',ARRAY['K5-2-u3-C12']::text[],'같은 말을 누구에게나 어떤 자리에서나 같은 말투로 써야 한다고 여긴다','누구에게 · 어디서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X13','kor',5,'u3',ARRAY['K5-2-u3-C13']::text[],'여러 지역 사람에게 전하는 방송이나 발표에서도 방언만 쓰면 똑같이 잘 전해진다고 여긴다','모두가 알아듣게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X14','kor',5,'u3',ARRAY['K5-2-u3-C14']::text[],'방언은 쓰면 안 되는 말이라 고향 사람과도 표준어만 써야 한다고 여긴다','친근함과 정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X15','kor',5,'u3',ARRAY['K5-2-u3-C15']::text[],'방언을 표준어로 바꾸어 보는 것을 틀린 말을 고치는 일로 여긴다','고치기가 아니라 선택') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X16','kor',5,'u3',ARRAY['K5-2-u3-C16']::text[],'사용 상황을 조사할 때 쓴 말만 적고 누구에게 · 어떤 상황 · 어떤 사이 · 고른 까닭을 빠뜨린다','세 가지 + 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X17','kor',5,'u3',ARRAY['K5-2-u3-C17']::text[],'방언은 말투만 다를 뿐 마을의 생활 모습은 담겨 있지 않다고 여긴다','말에 담긴 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X18','kor',5,'u3',ARRAY['K5-2-u3-C18']::text[],'방언과 표준어를 짝짓기만 하고 지역의 자연환경 · 먹을거리와 잇지 않는다','자연과 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X19','kor',5,'u3',ARRAY['K5-2-u3-C19']::text[],'방언은 쓸모없는 옛말이라 소중하지 않다고 여긴다','지역 문화의 자산') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X20','kor',5,'u3',ARRAY['K5-2-u3-C20','K5-2-u3-C19']::text[],'방언이 사라져도 표준어가 있으니 잃는 것이 없다고 여기거나 방언을 소통을 막는 말로만 본다','함께 잊히는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X21','kor',5,'u3',ARRAY['K5-2-u3-C21']::text[],'작품 속 방언 뜻만 맞히고 줄거리와 인물의 마음을 놓친다','일어난 일 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X22','kor',5,'u3',ARRAY['K5-2-u3-C22']::text[],'모르는 방언이 나오면 건너뛰거나 앞뒤 장면을 보지 않고 아무 뜻으로 넘겨짚는다','앞뒤 장면으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X23','kor',5,'u3',ARRAY['K5-2-u3-C23']::text[],'방언을 표준어로 바꾸어 읽어도 느낌까지 똑같다고 여기거나 뜻까지 달라진다고 여긴다','뜻은 같고 느낌은 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X24','kor',5,'u3',ARRAY['K5-2-u3-C24']::text[],'방언이 나오는 작품은 읽기 어려우니 표준어로 쓴 글이 더 좋은 글이라고 여긴다','생동감과 정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X25','kor',5,'u3',ARRAY['K5-2-u3-C25']::text[],'작품을 내 경험과 잇지 않고 근거 없는 느낌이나 작품과 관계없는 말만 한다','내 경험과 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X26','kor',5,'u3',ARRAY['K5-2-u3-C26']::text[],'방언으로 만들 수 있는 작품은 정해진 한 가지뿐이라고 여기거나 할 방식을 함께 정하지 않는다','지도 · 노랫말 · 상황극') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X27','kor',5,'u3',ARRAY['K5-2-u3-C27']::text[],'방언 지도 만드는 차례를 섞어 지도부터 꾸미고 주제는 나중에 정한다','주제가 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X28','kor',5,'u3',ARRAY['K5-2-u3-C28']::text[],'방언 지도는 방언을 많이 모을수록 잘 만든 것이라고 여긴다','개수보다 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X29','kor',5,'u3',ARRAY['K5-2-u3-C29']::text[],'방언을 과장해 흉내 내거나 웃음거리로 삼아도 괜찮다고 여긴다','마음을 살려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X30','kor',5,'u3',ARRAY['K5-2-u3-C30']::text[],'표준어와 방언 가운데 어느 한쪽이 언제나 더 좋은 말이라고 여긴다','둘 다 소중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X31','kor',5,'u3',ARRAY['K5-2-u3-C31']::text[],'상황을 살피지 않고 까닭 없이 고르거나 축제면 무조건 방언이라고 외운다','듣는 사람 · 목적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u3-X32','kor',5,'u3',ARRAY['K5-2-u3-C32']::text[],'동형어를 한 가지 뜻으로만 알고 앞뒤 말을 보지 않는다','앞뒤 말로 가려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#1','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C1',1,'mc','auto','휴게소 안내판의 「어서 오이소.」와 뜻이 같은 표준어 인사말은 어느 것인가요?',ARRAY['K5-2-u3-X02']::text[],false,'{"seq":1,"concept":"K5-2-u3-C1","difficulty":1,"kind":"mc","stem":"휴게소 안내판의 「어서 오이소.」와 뜻이 같은 표준어 인사말은 어느 것인가요?","options":[{"t":"어서 오세요.","correct":true},{"t":"안녕히 가세요.","mis":"K5-2-u3-X02"},{"t":"잘 먹겠습니다.","mis":"K5-2-u3-X02"},{"t":"다녀오겠습니다.","mis":"K5-2-u3-X02"}],"explanation":["헤어질 때 하는 인사예요.","밥 먹기 전 인사예요.","손님을 맞는 같은 뜻이에요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#2','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C2',1,'mc','auto','우리나라 사람들이 공통으로 쓸 수 있도록 정한 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":2,"concept":"K5-2-u3-C2","difficulty":1,"kind":"mc","stem":"우리나라 사람들이 공통으로 쓸 수 있도록 정한 말을 무엇이라고 하나요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X03"},{"t":"외래어","mis":"K5-2-u3-X01"},{"t":"줄임말","mis":"K5-2-u3-X01"}],"explanation":["방언은 특정 지역의 말이에요.","다른 나라에서 온 말이에요.","모두가 함께 쓰도록 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#3','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',1,'mc','auto','특정 지역에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01','K5-2-u3-X29']::text[],false,'{"seq":3,"concept":"K5-2-u3-C3","difficulty":1,"kind":"mc","stem":"특정 지역에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요?","options":[{"t":"방언","correct":true},{"t":"표준어","mis":"K5-2-u3-X03"},{"t":"높임말","mis":"K5-2-u3-X01"},{"t":"흉내 말","mis":"K5-2-u3-X29"}],"explanation":["표준어는 함께 쓰도록 정한 말이에요.","높이는 말이에요.","지역의 말을 방언이라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#4','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',1,'ox','auto','방언은 표준어를 잘못 말한 틀린 말이에요.',ARRAY['K5-2-u3-X01']::text[],false,'{"seq":4,"concept":"K5-2-u3-C3","difficulty":1,"kind":"ox","stem":"방언은 표준어를 잘못 말한 틀린 말이에요.","answer":"X","reason_options":[{"t":"그 지역 사람들이 오랫동안 써 온 우리말이기 때문에","correct":true},{"t":"표준어와 다르면 모두 틀린 말이기 때문에","mis":"K5-2-u3-X01"}],"mis":"K5-2-u3-X01","explanation":["방언도 우리말이에요.","틀린 말이 아니에요.","지역의 삶이 담긴 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#5','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',2,'mc','auto','시 「감재 한 바구니」에 나온 방언과 표준어를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C3","difficulty":2,"kind":"mc","stem":"시 「감재 한 바구니」에 나온 방언과 표준어를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"감재 — 감자, 옥시기 — 옥수수","correct":true},{"t":"감재 — 고추, 옥시기 — 옥수수","mis":"K5-2-u3-X10"},{"t":"감재 — 감자, 옥시기 — 감","mis":"K5-2-u3-X10"},{"t":"감재 — 감, 옥시기 — 오이","mis":"K5-2-u3-X10"}],"explanation":["시 넷째 줄을 다시 봐요.","옥시기는 키가 큰 옥수수예요.","시 넷째 줄에 나와요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#6','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C1',2,'mc','auto','네 지역의 인사말을 보고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X02','K5-2-u3-X01']::text[],false,'{"seq":6,"concept":"K5-2-u3-C1","difficulty":2,"kind":"mc","stem":"네 지역의 인사말을 보고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 지역에 따라 끝말과 말소리가 다르다","correct":true},{"t":"지역마다 손님을 맞는 뜻이 다르다","mis":"K5-2-u3-X02"},{"t":"서울·경기 지역 인사만 바른 말이다","mis":"K5-2-u3-X01"},{"t":"제주 지역 인사는 우리말이 아니다","mis":"K5-2-u3-X01"}],"explanation":["뜻은 모두 같아요.","모두 바른 우리말이에요.","말소리만 달라요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#7','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C4',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u3-C4","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"표준어와 방언","r":"뜻과 생긴 까닭 알기"},{"l":"사용 상황","r":"누구에게 어떤 자리에서 쓰는지 조사하기"},{"l":"작품 속 방언","r":"방언이 하는 역할 감상하기"}],"mis":"K5-2-u3-X04","explanation":["뜻부터 알아요.","쓰는 자리를 조사해요.","작품에서 감상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#8','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',2,'error','auto','시를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X30','K5-2-u3-X03']::text[],false,'{"seq":8,"concept":"K5-2-u3-C3","difficulty":2,"kind":"error","stem":"시를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「감재는 감자를 틀리게 쓴 말이니 고쳐 읽어야 해.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「부르는 이름은 달라도 똑같이 따끈하다는 줄이 좋아.」","mis":"K5-2-u3-X30"},{"t":"「감재와 옥시기는 강원 지역 방언이야.」","mis":"K5-2-u3-X03"}],"explanation":["시를 잘 느꼈어요.","바르게 알았어요.","방언은 틀린 말이 아니에요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#9','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C2',2,'mc','auto','기차역 안내 방송을 어느 지역에서든 표준어로 하는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X14','K5-2-u3-X03']::text[],false,'{"seq":9,"concept":"K5-2-u3-C2","difficulty":2,"kind":"mc","stem":"기차역 안내 방송을 어느 지역에서든 표준어로 하는 까닭은 무엇인가요?","options":[{"t":"어느 지역 사람이든 함께 알아들을 수 있게 하려고","correct":true},{"t":"표준어가 방언보다 더 높은 말이라서","mis":"K5-2-u3-X06"},{"t":"방언은 방송에서 쓰면 안 되는 말이라서","mis":"K5-2-u3-X14"},{"t":"안내하는 사람이 모두 서울 사람이라서","mis":"K5-2-u3-X03"}],"explanation":["높고 낮은 말이 아니에요.","방언이 금지된 것은 아니에요.","모두가 알아듣게 하려는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_basic#10','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',3,'mc','auto','할머니께서 「감재 쪄 놨다.」라고 하셨을 때 손녀의 행동으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X29','K5-2-u3-X19']::text[],false,'{"seq":10,"concept":"K5-2-u3-C3","difficulty":3,"kind":"mc","stem":"할머니께서 「감재 쪄 놨다.」라고 하셨을 때 손녀의 행동으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「감재가 뭐예요?」 하고 궁금한 마음으로 여쭈어본다","correct":true},{"t":"틀린 말이라며 표준어로 고쳐 드린다","mis":"K5-2-u3-X01"},{"t":"말투를 흉내 내며 웃는다","mis":"K5-2-u3-X29"},{"t":"모르는 말이니 못 들은 척한다","mis":"K5-2-u3-X19"}],"explanation":["방언은 틀린 말이 아니에요.","흉내는 예의가 아니에요.","모르는 것은 궁금한 마음으로 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#1','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',2,'ox','auto','「어서 오슈.」와 「혼저 옵서예.」는 모두 손님을 반갑게 맞는 같은 뜻의 인사예요.',ARRAY['K5-2-u3-X02']::text[],false,'{"seq":1,"concept":"K5-2-u3-C1","difficulty":2,"kind":"ox","stem":"「어서 오슈.」와 「혼저 옵서예.」는 모두 손님을 반갑게 맞는 같은 뜻의 인사예요.","answer":"O","reason_options":[{"t":"지역에 따라 끝말과 말소리만 다를 뿐 뜻은 같기 때문에","correct":true},{"t":"말소리가 다르면 뜻도 달라지기 때문에","mis":"K5-2-u3-X02"}],"mis":"K5-2-u3-X02","explanation":["뜻은 같아요.","말소리만 달라요.","모두 손님을 맞는 인사예요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#2','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C4',2,'mc','auto','이 단원에서 표준어와 방언의 뜻을 안 다음에 배우는 내용은 어느 것인가요?',ARRAY['K5-2-u3-X04']::text[],false,'{"seq":2,"concept":"K5-2-u3-C4","difficulty":2,"kind":"mc","stem":"이 단원에서 표준어와 방언의 뜻을 안 다음에 배우는 내용은 어느 것인가요?","options":[{"t":"표준어와 방언을 쓰는 상황 조사하기","correct":true},{"t":"우리 반 방언 지도를 맨 먼저 만들기","mis":"K5-2-u3-X04"},{"t":"문장 성분 찾기","mis":"K5-2-u3-X04"},{"t":"토론 절차 익히기","mis":"K5-2-u3-X04"}],"explanation":["방언 지도는 맨 끝이에요.","지난 단원이에요.","뜻 다음은 쓰는 상황이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#3','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C2',3,'mc','auto','표준어에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X06']::text[],false,'{"seq":3,"concept":"K5-2-u3-C2","difficulty":3,"kind":"mc","stem":"표준어에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 지역 사람이든 함께 알아듣도록 정한 말이다","correct":true},{"t":"서울에 사는 사람만 쓰는 말이다","mis":"K5-2-u3-X03"},{"t":"방언보다 더 고운 말이라서 정한 말이다","mis":"K5-2-u3-X06"},{"t":"시골에서는 쓰지 않는 말이다","mis":"K5-2-u3-X03"}],"explanation":["어디서나 써요.","곱고 덜 고운 말이 아니에요.","함께 알아듣게 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#4','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C3',3,'mc','auto','「방언은 시골에서만 쓰는 말이야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":4,"concept":"K5-2-u3-C3","difficulty":3,"kind":"mc","stem":"「방언은 시골에서만 쓰는 말이야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「큰 도시에서도 그 지역에서 주로 쓰는 방언이 있어.」","correct":true},{"t":"「맞아, 도시 사람은 모두 표준어만 써.」","mis":"K5-2-u3-X03"},{"t":"「방언은 틀린 말이니 어디서도 안 써.」","mis":"K5-2-u3-X01"},{"t":"「방언은 할머니들만 쓰는 말이야.」","mis":"K5-2-u3-X03"}],"explanation":["도시에서도 방언을 써요.","방언은 틀린 말이 아니에요.","방언은 그 지역의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#5','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',3,'error','auto','인사말 안내판을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X02','K5-2-u3-X12']::text[],false,'{"seq":5,"concept":"K5-2-u3-C1","difficulty":3,"kind":"error","stem":"인사말 안내판을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「어서 오세요만 바른 인사이고 나머지는 잘못된 인사야.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「말소리는 달라도 손님을 반기는 마음은 같아.」","mis":"K5-2-u3-X02"},{"t":"「우리 지역에서는 손님을 어떻게 맞는지 떠올려 보자.」","mis":"K5-2-u3-X12"}],"explanation":["마음은 같아요.","좋은 생각이에요.","모두 바른 우리말이에요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#6','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',3,'mc','auto','지역마다 인사말이 조금씩 다른 까닭을 짐작한 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X02','K5-2-u3-X05','K5-2-u3-X01']::text[],false,'{"seq":6,"concept":"K5-2-u3-C1","difficulty":3,"kind":"mc","stem":"지역마다 인사말이 조금씩 다른 까닭을 짐작한 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옛날에는 지역 사이를 오가기 어려워 말이 따로따로 자랐을 것이다","correct":true},{"t":"지역마다 손님을 반기는 마음이 달라서일 것이다","mis":"K5-2-u3-X02"},{"t":"한 지역 사람들이 일부러 말을 바꾸었을 것이다","mis":"K5-2-u3-X05"},{"t":"안내판을 만든 사람이 실수했을 것이다","mis":"K5-2-u3-X01"}],"explanation":["마음은 같아요.","일부러 바꾼 것이 아니에요.","오가기 어려워 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#7','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언을 처음 들었을 때의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X19','K5-2-u3-X01']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언을 처음 들었을 때의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"궁금한 마음으로 뜻을 묻고 정다운 느낌을 말해 본다","correct":true},{"t":"말투를 과장해 따라 하며 웃음거리로 삼는다","mis":"K5-2-u3-X29"},{"t":"모르는 말이니 들을 필요가 없다고 여긴다","mis":"K5-2-u3-X19"},{"t":"틀린 말이라고 바로 지적한다","mis":"K5-2-u3-X01"}],"explanation":["흉내는 예의가 아니에요.","들어 볼 가치가 있어요.","궁금한 마음으로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#8','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C3',4,'essay','teacher','시 「감재 한 바구니」에서 방언을 모두 찾아 표준어로 바꾸어 쓰고, 방언으로 읽을 때의 느낌을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C3","difficulty":4,"kind":"essay","stem":"시 「감재 한 바구니」에서 방언을 모두 찾아 표준어로 바꾸어 쓰고, 방언으로 읽을 때의 느낌을 쓰세요.","answer_guide":{"answer":"예: 방언은 「감재」와 「옥시기」이고, 표준어로 바꾸면 「감자」와 「옥수수」이다. 방언으로 읽으니 할머니가 밭에서 직접 말씀해 주시는 것처럼 정답고 따뜻하게 느껴진다.","scoring_points":["방언 두 개를 찾았는가","표준어로 바르게 바꾸었는가","방언으로 읽을 때의 느낌을 썼는가"]},"explanation":["감재 · 옥시기를 찾아요.","감자 · 옥수수로 바꿔요.","느낌을 써요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#9','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C2',4,'essay','teacher','표준어와 방언의 뜻을 각각 쓰고, 두 말이 하는 일의 다른 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C2","difficulty":4,"kind":"essay","stem":"표준어와 방언의 뜻을 각각 쓰고, 두 말이 하는 일의 다른 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 표준어는 우리나라 사람들이 공통으로 쓸 수 있도록 정한 말이고, 방언은 특정 지역에서 주로 쓰는 표준어가 아닌 말이다. 표준어는 어느 지역 사람과도 뜻이 통하게 해 주고, 방언은 그 지역 사람들의 생활과 정을 담아 준다.","scoring_points":["표준어의 뜻을 썼는가","방언의 뜻을 썼는가","하는 일의 다른 점을 썼는가"]},"explanation":["함께 쓰도록 정한 말이에요.","지역에서 주로 쓰는 말이에요.","하는 일을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L01_challenge#10','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C4',4,'essay','teacher','이 단원에서 가장 알고 싶은 것을 하나 쓰고, 그것을 알면 내 언어생활에 어떤 도움이 될지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C4","difficulty":4,"kind":"essay","stem":"이 단원에서 가장 알고 싶은 것을 하나 쓰고, 그것을 알면 내 언어생활에 어떤 도움이 될지 쓰세요.","answer_guide":{"answer":"예: 우리 할아버지께서 쓰시는 말이 어느 지역 방언인지 알고 싶다. 그것을 알면 할아버지 말씀을 더 잘 알아듣고, 친구들 앞에서는 표준어로, 가족끼리는 정다운 말로 상황에 맞게 골라 쓸 수 있을 것 같다.","scoring_points":["알고 싶은 것을 하나 썼는가","단원 내용과 이어지는가","언어생활에 주는 도움을 썼는가"]},"explanation":["알고 싶은 것을 골라요.","단원과 이어요.","도움을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#1','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C5',1,'mc','auto','「말에도 고향이 있어요」에서 방언이 생긴 까닭으로 든 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":1,"concept":"K5-2-u3-C5","difficulty":1,"kind":"mc","stem":"「말에도 고향이 있어요」에서 방언이 생긴 까닭으로 든 것은 어느 것인가요?","options":[{"t":"산과 강이 많아 지역 사이를 오가기 어려워서","correct":true},{"t":"표준어를 외우기 귀찮아서","mis":"K5-2-u3-X05"},{"t":"한 지역 사람들이 일부러 말을 바꾸어서","mis":"K5-2-u3-X05"},{"t":"책이 많지 않아서","mis":"K5-2-u3-X05"}],"explanation":["글에 없는 까닭이에요.","일부러 바꾼 것이 아니에요.","셋째 문장에 나와요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#2','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C7',1,'mc','auto','우리나라 표준어를 정하는 곳은 어디인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":2,"concept":"K5-2-u3-C7","difficulty":1,"kind":"mc","stem":"우리나라 표준어를 정하는 곳은 어디인가요?","options":[{"t":"국립국어원","correct":true},{"t":"각 지역 마을 회관","mis":"K5-2-u3-X07"},{"t":"방송국","mis":"K5-2-u3-X07"},{"t":"우리 학교 방송부","mis":"K5-2-u3-X07"}],"explanation":["마을 회관이 아니에요.","방송국은 표준어를 써요.","국립국어원이 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#3','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',1,'mc','auto','「까구리」와 「깨고락지」가 가리키는 동물을 표준어로 쓰면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":3,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「까구리」와 「깨고락지」가 가리키는 동물을 표준어로 쓰면 어느 것인가요?","options":[{"t":"개구리","correct":true},{"t":"고양이","mis":"K5-2-u3-X10"},{"t":"까치","mis":"K5-2-u3-X10"},{"t":"거북","mis":"K5-2-u3-X10"}],"explanation":["고양이는 겡이 · 고냉이예요.","새가 아니에요.","글 첫 문장에 나와요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#4','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C8',1,'ox','auto','원래 방언이었던 말이 표준어가 되기도 해요.',ARRAY['K5-2-u3-X08']::text[],false,'{"seq":4,"concept":"K5-2-u3-C8","difficulty":1,"kind":"ox","stem":"원래 방언이었던 말이 표준어가 되기도 해요.","answer":"O","reason_options":[{"t":"「멍게」처럼 표준어보다 더 널리 쓰이게 되면 표준어로 인정하기 때문에","correct":true},{"t":"방언은 어떤 경우에도 표준어가 될 수 없기 때문에","mis":"K5-2-u3-X08"}],"mis":"K5-2-u3-X08","explanation":["멍게를 떠올려요.","널리 쓰이면 인정해요.","움직이는 경계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#5','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C6',2,'mc','auto','표준어를 정한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X06','K5-2-u3-X07']::text[],false,'{"seq":5,"concept":"K5-2-u3-C6","difficulty":2,"kind":"mc","stem":"표준어를 정한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사는 지역이 달라도 서로 원활하게 이야기할 수 있게 하려고","correct":true},{"t":"방언을 쓰지 못하게 막으려고","mis":"K5-2-u3-X14"},{"t":"서울 말이 가장 고운 말이라서","mis":"K5-2-u3-X06"},{"t":"글자 수를 줄이려고","mis":"K5-2-u3-X07"}],"explanation":["막으려는 것이 아니에요.","곱고 덜 고운 말이 아니에요.","함께 이야기하려고 정했어요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#6','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C7',2,'mc','auto','국립국어원이 표준어를 정할 때 살펴보는 것이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":6,"concept":"K5-2-u3-C7","difficulty":2,"kind":"mc","stem":"국립국어원이 표준어를 정할 때 살펴보는 것이 아닌 것은 어느 것인가요?","options":[{"t":"글자 수가 가장 적은지","correct":true},{"t":"사람들이 두루 쓰는지","mis":"K5-2-u3-X07"},{"t":"문법에 맞는지","mis":"K5-2-u3-X07"},{"t":"발음하기 편하고 자연스러운지","mis":"K5-2-u3-X07"}],"explanation":["살펴보는 기준이에요.","살펴보는 기준이에요.","글자 수는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#7','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',2,'mc','auto','다섯 고개의 정답을 표준어로 쓰면 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X10']::text[],false,'{"seq":7,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"다섯 고개의 정답을 표준어로 쓰면 어느 것인가요?","options":[{"t":"김치","correct":true},{"t":"부추","mis":"K5-2-u3-X09"},{"t":"감자","mis":"K5-2-u3-X09"},{"t":"고추","mis":"K5-2-u3-X10"}],"explanation":["부추는 정구지 · 소풀이에요.","감자는 감재예요.","짐끼 · 짐치는 김치예요."],"asset":{"type":"speech","turns":[{"who":"첫째 고개","text":"제주 지역에서는 「짐끼」라고 해요."},{"who":"둘째 고개","text":"강원 지역에서는 「짐치」라고 해요."},{"who":"셋째 고개","text":"반찬으로 먹고 매운맛이 나요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#8','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',2,'match','auto','방언과 뜻이 같은 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C9","difficulty":2,"kind":"match","stem":"방언과 뜻이 같은 표준어를 알맞게 이으세요.","pairs":[{"l":"정구지","r":"부추"},{"l":"고냉이","r":"고양이"},{"l":"까구리","r":"개구리"}],"mis":"K5-2-u3-X09","explanation":["경상 지역에서 써요.","강원 지역에서 써요.","한 낱말을 여러 이름으로 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#9','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C8',2,'error','auto','「멍게」에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X08','K5-2-u3-X09','K5-2-u3-X07']::text[],false,'{"seq":9,"concept":"K5-2-u3-C8","difficulty":2,"kind":"error","stem":"「멍게」에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「멍게는 방언이라서 지금도 표준어로 쓸 수 없어.」","correct":true,"mis_target":"K5-2-u3-X08"},{"t":"「원래 경상 지역 방언이었어.」","mis":"K5-2-u3-X09"},{"t":"「우렁쉥이보다 더 널리 쓰여 표준어가 되었어.」","mis":"K5-2-u3-X07"}],"explanation":["맞는 말이에요.","맞는 말이에요.","지금은 표준어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_basic#10','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C10',3,'mc','auto','어떤 지역에서 「나무」를 어떻게 부르는지 정확히 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11']::text[],false,'{"seq":10,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"어떤 지역에서 「나무」를 어떻게 부르는지 정확히 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국립국어원 지역어 누리집에서 「나무」를 검색해 본다","correct":true},{"t":"뜻이 비슷한 말을 짐작해서 적는다","mis":"K5-2-u3-X10"},{"t":"친구 한 명의 말만 듣고 정답으로 정한다","mis":"K5-2-u3-X11"},{"t":"표준어 사전에서 「나무」의 뜻만 찾는다","mis":"K5-2-u3-X10"}],"explanation":["짐작은 확인이 필요해요.","한 사람 말만으로는 부족해요.","지역별 방언이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#1','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',2,'ox','auto','옛날 사람들이 일부러 지역마다 다른 말을 만들어 써서 방언이 생겼어요.',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":1,"concept":"K5-2-u3-C5","difficulty":2,"kind":"ox","stem":"옛날 사람들이 일부러 지역마다 다른 말을 만들어 써서 방언이 생겼어요.","answer":"X","reason_options":[{"t":"오가기 어려워 이야기할 기회가 적다 보니 말이 자연스럽게 달라졌기 때문에","correct":true},{"t":"지역끼리 서로 말이 통하지 않게 하려고 정했기 때문에","mis":"K5-2-u3-X05"}],"mis":"K5-2-u3-X05","explanation":["일부러가 아니에요.","자연스럽게 달라졌어요.","지리적 특성 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#2','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C9',2,'mc','auto','「겡이」, 「고냉이」, 「궤이」를 보고 알 수 있는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X11','K5-2-u3-X03']::text[],false,'{"seq":2,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「겡이」, 「고냉이」, 「궤이」를 보고 알 수 있는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 낱말을 가리키는 방언이 지역마다 여러 가지일 수 있다","correct":true},{"t":"세 말은 서로 다른 동물을 가리킨다","mis":"K5-2-u3-X09"},{"t":"셋 가운데 하나만 맞는 방언이다","mis":"K5-2-u3-X11"},{"t":"세 말은 모두 표준어이다","mis":"K5-2-u3-X03"}],"explanation":["모두 고양이예요.","모두 그 지역의 방언이에요.","한 낱말, 여러 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#3','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',3,'mc','auto','옛날에도 지금처럼 교통과 통신이 발달했다면 방언은 어떠했을지 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05','K5-2-u3-X06']::text[],false,'{"seq":3,"concept":"K5-2-u3-C5","difficulty":3,"kind":"mc","stem":"옛날에도 지금처럼 교통과 통신이 발달했다면 방언은 어떠했을지 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 사이에 자주 오가 말이 지금보다 덜 달랐을 것이다","correct":true},{"t":"방언이 지금보다 훨씬 많아졌을 것이다","mis":"K5-2-u3-X05"},{"t":"표준어가 저절로 사라졌을 것이다","mis":"K5-2-u3-X06"},{"t":"교통과 말은 아무 관계가 없을 것이다","mis":"K5-2-u3-X05"}],"explanation":["오가면 말이 닮아 가요.","표준어와 관계없어요.","오가기 어려워 말이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#4','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C6',3,'mc','auto','표준어가 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X08','K5-2-u3-X06']::text[],false,'{"seq":4,"concept":"K5-2-u3-C6","difficulty":3,"kind":"mc","stem":"표준어가 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다른 지역 사람과 공식적인 소식을 나눌 때 뜻을 잘못 알아들을 수 있다","correct":true},{"t":"모든 사람이 방언을 잊어버린다","mis":"K5-2-u3-X19"},{"t":"방언이 모두 표준어가 된다","mis":"K5-2-u3-X08"},{"t":"아무 문제도 생기지 않는다","mis":"K5-2-u3-X06"}],"explanation":["방언은 그대로예요.","방언이 다 바뀌지 않아요.","뜻을 나누기 어려워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#5','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C7',3,'error','auto','표준어를 정하는 방법에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X06','K5-2-u3-X08']::text[],false,'{"seq":5,"concept":"K5-2-u3-C7","difficulty":3,"kind":"error","stem":"표준어를 정하는 방법에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「목소리가 큰 사람들이 쓰는 말을 표준어로 정해.」","correct":true,"mis_target":"K5-2-u3-X07"},{"t":"「사람들이 두루 쓰는지 살펴.」","mis":"K5-2-u3-X06"},{"t":"「문법에 맞고 발음이 자연스러운지도 봐.」","mis":"K5-2-u3-X08"}],"explanation":["기준이 맞아요.","기준이 맞아요.","목소리 크기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#6','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C11',3,'mc','auto','방언 카드에 「가새기 — 경상 지역 — 가위」라고 쓴 친구와, 경상 지역 할머니께서 가위를 다르게 말씀하신다는 친구가 있어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X11','K5-2-u3-X01','K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C11","difficulty":3,"kind":"mc","stem":"방언 카드에 「가새기 — 경상 지역 — 가위」라고 쓴 친구와, 경상 지역 할머니께서 가위를 다르게 말씀하신다는 친구가 있어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"같은 지역 안에서도 마을마다 다를 수 있으니 누리집 같은 근거를 함께 찾아본다","correct":true},{"t":"카드를 쓴 친구가 틀렸으니 카드를 지운다","mis":"K5-2-u3-X11"},{"t":"할머니 말씀이 틀렸다고 말씀드린다","mis":"K5-2-u3-X01"},{"t":"둘 다 방언이니 아무렇게나 적어도 된다","mis":"K5-2-u3-X10"}],"explanation":["둘 다 맞을 수 있어요.","할머니 말씀도 그 마을의 방언이에요.","근거로 함께 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#7','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C10',3,'mc','auto','방언 카드 놀이에서 친구가 표준어를 잘 맞히지 못할 때 도와주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X10']::text[],false,'{"seq":7,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"방언 카드 놀이에서 친구가 표준어를 잘 맞히지 못할 때 도와주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"표준어의 첫 글자나 초성을 알려 준다","correct":true},{"t":"맞히지 못하면 놀이에서 빼 준다","mis":"K5-2-u3-X29"},{"t":"방언을 과장해 다시 흉내 낸다","mis":"K5-2-u3-X29"},{"t":"아무 표준어나 말하게 한다","mis":"K5-2-u3-X10"}],"explanation":["함께 해야 해요.","흉내는 예의가 아니에요.","첫 글자나 초성으로 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#8','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',4,'essay','teacher','방언이 생긴 까닭과 표준어를 정한 까닭을 이어서 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C5","difficulty":4,"kind":"essay","stem":"방언이 생긴 까닭과 표준어를 정한 까닭을 이어서 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 서로 이야기할 기회가 적어 지역마다 말이 조금씩 달라져 방언이 생겼다. 그런데 말이 다르면 다른 지역 사람과 뜻을 나누기 어렵기 때문에, 어디에 살든 원활하게 이야기할 수 있도록 표준어를 정했다.","scoring_points":["방언이 생긴 까닭을 썼는가","표준어를 정한 까닭을 썼는가","두 까닭을 앞뒤로 이어 설명했는가"]},"explanation":["지리적 특성이에요.","원활한 의사소통이에요.","이어서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#9','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C8',4,'essay','teacher','「멍게」가 표준어가 된 과정을 설명하고, 이를 보고 표준어와 방언의 관계에 대해 알 수 있는 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C8","difficulty":4,"kind":"essay","stem":"「멍게」가 표준어가 된 과정을 설명하고, 이를 보고 표준어와 방언의 관계에 대해 알 수 있는 점을 쓰세요.","answer_guide":{"answer":"예: 멍게는 원래 경상 지역 방언이었지만 표준어 「우렁쉥이」보다 더 널리 쓰이게 되어 지금은 둘 다 표준어가 되었다. 이를 보면 표준어와 방언 사이는 꽉 막힌 벽이 아니라, 사람들이 두루 쓰는 말에 따라 움직이는 경계라는 것을 알 수 있다.","scoring_points":["원래 방언이었음을 썼는가","더 널리 쓰여 표준어가 되었음을 썼는가","둘의 관계를 정리했는가"]},"explanation":["원래 지역을 써요.","널리 쓰인 것이 까닭이에요.","움직이는 경계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L02_challenge#10','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C9',4,'essay','teacher','내가 아는 낱말로 방언 고개 문제를 만들어 쓰세요. 고개를 셋 이상 만들고, 고개마다 지역과 방언 또는 특징을 넣은 뒤 정답을 표준어로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"내가 아는 낱말로 방언 고개 문제를 만들어 쓰세요. 고개를 셋 이상 만들고, 고개마다 지역과 방언 또는 특징을 넣은 뒤 정답을 표준어로 쓰세요.","answer_guide":{"answer":"예: 첫째 고개 — 경상 지역에서는 「정구지」라고 해요. 둘째 고개 — 전라 지역에서는 「소풀」이라고 해요. 셋째 고개 — 부침개에 넣는 초록색 채소예요. 정답 — 부추.","scoring_points":["고개를 셋 이상 만들었는가","지역과 방언 또는 특징을 넣었는가","정답을 표준어로 썼는가"]},"explanation":["고개를 만들어요.","지역과 방언을 넣어요.","정답은 표준어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#1','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C14',1,'mc','auto','「설날, 외할머니 댁에서」에서 엄마가 외삼촌과 이야기할 때 방언을 쓴 까닭은 무엇인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X03','K5-2-u3-X13']::text[],false,'{"seq":1,"concept":"K5-2-u3-C14","difficulty":1,"kind":"mc","stem":"「설날, 외할머니 댁에서」에서 엄마가 외삼촌과 이야기할 때 방언을 쓴 까닭은 무엇인가요?","options":[{"t":"고향 사람과 이야기하면 더 가깝게 느껴져서","correct":true},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"외삼촌이 표준어를 못 알아들어서","mis":"K5-2-u3-X03"},{"t":"방송에 나가야 해서","mis":"K5-2-u3-X13"}],"explanation":["엄마는 표준어도 써요.","외삼촌도 표준어를 알아요.","넷째 · 다섯째 줄에 나와요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#2','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C13',1,'mc','auto','기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 표준어로 말한 까닭은 무엇인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X14','K5-2-u3-X06']::text[],false,'{"seq":2,"concept":"K5-2-u3-C13","difficulty":1,"kind":"mc","stem":"기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 표준어로 말한 까닭은 무엇인가요?","options":[{"t":"전국 사람에게 똑같이 정확히 전하려고","correct":true},{"t":"방언은 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"고향 사람과 가까워지려고","mis":"K5-2-u3-X14"},{"t":"표준어가 더 높은 말이라서","mis":"K5-2-u3-X06"}],"explanation":["방언은 틀린 말이 아니에요.","그건 엄마의 까닭이에요.","여러 지역 사람에게 전해요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#3','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C15',1,'blank','auto','「길 막혀서 힘들었슈?」를 표준어로 바꾸면 「길 막혀서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X22','K5-2-u3-X09']::text[],false,'{"seq":3,"concept":"K5-2-u3-C15","difficulty":1,"kind":"blank","stem":"「길 막혀서 힘들었슈?」를 표준어로 바꾸면 「길 막혀서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"힘들었어요?","correct":true},{"t":"힘들었슈.","mis":"K5-2-u3-X15"},{"t":"힘들겠지?","mis":"K5-2-u3-X22"},{"t":"힘들었당께.","mis":"K5-2-u3-X09"}],"explanation":["그대로예요.","뜻이 바뀌었어요.","「~슈」는 「~어요」예요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#4','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C12',1,'ox','auto','뜻이 같은 말이라도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓸 수 있어요.',ARRAY['K5-2-u3-X12']::text[],false,'{"seq":4,"concept":"K5-2-u3-C12","difficulty":1,"kind":"ox","stem":"뜻이 같은 말이라도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"듣는 사람과 상황에 따라 어울리는 말이 다르기 때문에","correct":true},{"t":"어떤 자리에서든 같은 말투로만 말해야 하기 때문에","mis":"K5-2-u3-X12"}],"mis":"K5-2-u3-X12","explanation":["자리에 따라 골라요.","듣는 사람이 기준이에요.","같은 뜻도 달리 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#5','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C13',2,'mc','auto','주로 표준어를 쓰는 상황으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14']::text[],false,'{"seq":5,"concept":"K5-2-u3-C13","difficulty":2,"kind":"mc","stem":"주로 표준어를 쓰는 상황으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학교 방송으로 전교생에게 행사를 안내할 때","correct":true},{"t":"고향 친구와 오랜만에 통화할 때","mis":"K5-2-u3-X14"},{"t":"시장에서 단골손님과 이야기할 때","mis":"K5-2-u3-X14"},{"t":"지역 축제에서 고장 분위기를 살려 인사할 때","mis":"K5-2-u3-X14"}],"explanation":["방언을 쓰기도 해요.","방언을 쓰기도 해요.","여럿에게 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#6','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C14',2,'mc','auto','시장 상인이 단골손님에게 그 지역 방언으로 말하면 어떤 점이 좋을까요?',ARRAY['K5-2-u3-X13','K5-2-u3-X01','K5-2-u3-X12']::text[],false,'{"seq":6,"concept":"K5-2-u3-C14","difficulty":2,"kind":"mc","stem":"시장 상인이 단골손님에게 그 지역 방언으로 말하면 어떤 점이 좋을까요?","options":[{"t":"손님이 더 친근하고 정답게 느낄 수 있다","correct":true},{"t":"손님이 뜻을 하나도 알아듣지 못한다","mis":"K5-2-u3-X13"},{"t":"상인이 표준어를 모른다는 것을 알린다","mis":"K5-2-u3-X01"},{"t":"물건값이 저절로 싸진다","mis":"K5-2-u3-X12"}],"explanation":["같은 지역 사람은 알아들어요.","표준어를 몰라서가 아니에요.","정을 나누는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#7','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C15',2,'mc','auto','방언 문장을 표준어로 바꾸어 보는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X14','K5-2-u3-X07']::text[],false,'{"seq":7,"concept":"K5-2-u3-C15","difficulty":2,"kind":"mc","stem":"방언 문장을 표준어로 바꾸어 보는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 뜻이 상황에 따라 다르게 골라 쓰인다는 것을 알기 위해서","correct":true},{"t":"방언이 틀린 말이라 고치기 위해서","mis":"K5-2-u3-X15"},{"t":"방언을 쓰지 못하게 하려고","mis":"K5-2-u3-X14"},{"t":"글자 수를 줄이려고","mis":"K5-2-u3-X07"}],"explanation":["고치기가 아니에요.","금지하려는 게 아니에요.","상황에 따른 선택을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#8','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C16',2,'match','auto','「설날, 외할머니 댁에서」의 엄마 말을 조사표로 정리했어요. 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C16","difficulty":2,"kind":"match","stem":"「설날, 외할머니 댁에서」의 엄마 말을 조사표로 정리했어요. 알맞게 이으세요.","pairs":[{"l":"누구에게","r":"외삼촌에게"},{"l":"어떤 상황에서","r":"설날 고향 집 마당에서"},{"l":"어떤 사이","r":"어릴 때부터 함께 자란 가족"}],"mis":"K5-2-u3-X16","explanation":["듣는 사람이에요.","장소와 자리예요.","관계예요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#9','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C12',2,'error','auto','축제 날 두 무대를 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X12','K5-2-u3-X13','K5-2-u3-X14']::text[],false,'{"seq":9,"concept":"K5-2-u3-C12","difficulty":2,"kind":"error","stem":"축제 날 두 무대를 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「방송부원처럼 어르신도 표준어로만 말해야 했어.」","correct":true,"mis_target":"K5-2-u3-X12"},{"t":"「방송부원은 전교생에게 정확히 안내하려고 표준어를 썼어.」","mis":"K5-2-u3-X13"},{"t":"「어르신은 고향 말로 정다운 분위기를 살렸어.」","mis":"K5-2-u3-X14"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","자리마다 어울리는 말이 달라요."],"asset":{"type":"passage","lines":["학교 축제 날, 방송실에서는 방송부원이 전교생에게 행사 순서를","또박또박 표준어로 안내했다.","운동장 무대에서는 마을 어르신이 고향 말로 농악 공연을 소개했다.","어르신의 말에 관객들이 웃으며 손뼉을 쳤다."],"title":"축제 날 두 무대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_basic#10','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C16',3,'mc','auto','표준어 · 방언 사용 상황 조사표에 꼭 함께 적어야 할 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X16','K5-2-u3-X29']::text[],false,'{"seq":10,"concept":"K5-2-u3-C16","difficulty":3,"kind":"mc","stem":"표준어 · 방언 사용 상황 조사표에 꼭 함께 적어야 할 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 말을 고른 까닭","correct":true},{"t":"말한 사람의 키","mis":"K5-2-u3-X16"},{"t":"조사한 날의 날씨","mis":"K5-2-u3-X16"},{"t":"방언을 흉내 낸 우스운 그림","mis":"K5-2-u3-X29"}],"explanation":["관계없어요.","관계없어요.","까닭을 적어야 상황과 말이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#1','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C15',2,'ox','auto','방언은 고쳐야 할 말이라서 언제나 표준어로 바꾸어 말해야 해요.',ARRAY['K5-2-u3-X15']::text[],false,'{"seq":1,"concept":"K5-2-u3-C15","difficulty":2,"kind":"ox","stem":"방언은 고쳐야 할 말이라서 언제나 표준어로 바꾸어 말해야 해요.","answer":"X","reason_options":[{"t":"상황에 따라 방언이 더 어울리는 자리도 있기 때문에","correct":true},{"t":"방언은 틀린 말이기 때문에","mis":"K5-2-u3-X15"}],"mis":"K5-2-u3-X15","explanation":["고칠 말이 아니에요.","자리에 따라 골라요.","방언이 어울리는 자리도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#2','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C12',2,'mc','auto','「나」가 엄마의 말투에 고개를 갸웃한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":2,"concept":"K5-2-u3-C12","difficulty":2,"kind":"mc","stem":"「나」가 엄마의 말투에 고개를 갸웃한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"집에서와 다른 말투를 엄마가 고향 사람에게 썼기 때문에","correct":true},{"t":"엄마가 아파 보였기 때문에","mis":"K5-2-u3-X21"},{"t":"외삼촌이 늦게 왔기 때문에","mis":"K5-2-u3-X21"},{"t":"뉴스에서 눈 소식이 나왔기 때문에","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","일찍 왔다고 했어요.","셋째 줄을 봐요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#3','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C13',3,'mc','auto','여러 지역 사람이 함께 듣는 방송에서 방언만 쓰면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X12']::text[],false,'{"seq":3,"concept":"K5-2-u3-C13","difficulty":3,"kind":"mc","stem":"여러 지역 사람이 함께 듣는 방송에서 방언만 쓰면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말이 달라 내용을 잘 알아듣지 못하는 사람이 생길 수 있다","correct":true},{"t":"모든 사람이 더 정확히 알아듣는다","mis":"K5-2-u3-X13"},{"t":"방송이 저절로 짧아진다","mis":"K5-2-u3-X13"},{"t":"아무 일도 생기지 않는다","mis":"K5-2-u3-X12"}],"explanation":["오히려 어려워요.","관계없어요.","알아듣기 어려운 사람이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#4','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C14',3,'mc','auto','방언을 쓰기도 하는 상황끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X12']::text[],false,'{"seq":4,"concept":"K5-2-u3-C14","difficulty":3,"kind":"mc","stem":"방언을 쓰기도 하는 상황끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"고향 친구와 통화 · 지역 축제 사회","correct":true},{"t":"뉴스 일기 예보 · 전교생 앞 발표","mis":"K5-2-u3-X13"},{"t":"학교 방송 안내 · 고향 친구와 통화","mis":"K5-2-u3-X12"},{"t":"전국 어린이 회의 · 시장 단골 대화","mis":"K5-2-u3-X12"}],"explanation":["둘 다 표준어 자리예요.","학교 방송은 표준어예요.","정을 나누는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#5','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C16',3,'error','auto','조사표를 쓴 친구들이에요. 상황과 말의 관계가 잘 드러나지 않게 쓴 것은 어느 것인가요?',ARRAY['K5-2-u3-X16','K5-2-u3-X14','K5-2-u3-X13']::text[],false,'{"seq":5,"concept":"K5-2-u3-C16","difficulty":3,"kind":"error","stem":"조사표를 쓴 친구들이에요. 상황과 말의 관계가 잘 드러나지 않게 쓴 것은 어느 것인가요?","options":[{"t":"「할아버지 — 방언」","correct":true,"mis_target":"K5-2-u3-X16"},{"t":"「할아버지께서 고향 친구분과 통화하실 때 — 방언 — 편하고 정답게 이야기하시려고」","mis":"K5-2-u3-X14"},{"t":"「뉴스에서 전국 날씨를 전할 때 — 표준어 — 모두가 알아듣게 하려고」","mis":"K5-2-u3-X13"}],"explanation":["상황과 까닭이 있어요.","상황과 까닭이 있어요.","상황 · 사이 · 까닭이 빠졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#6','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C12',3,'mc','auto','학교 방송부가 「우리 고장 소개」 방송을 만들 때 두 말을 함께 살리는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X15','K5-2-u3-X12']::text[],false,'{"seq":6,"concept":"K5-2-u3-C12","difficulty":3,"kind":"mc","stem":"학교 방송부가 「우리 고장 소개」 방송을 만들 때 두 말을 함께 살리는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"소개는 표준어로 하고 어르신 인터뷰는 방언 그대로 싣는다","correct":true},{"t":"처음부터 끝까지 방언으로만 한다","mis":"K5-2-u3-X13"},{"t":"어르신 인터뷰도 모두 표준어로 고쳐 싣는다","mis":"K5-2-u3-X15"},{"t":"두 의견이 다르니 방송을 하지 않는다","mis":"K5-2-u3-X12"}],"explanation":["다른 지역 사람이 알아듣기 어려워요.","고장의 분위기가 줄어요.","듣는 사람과 목적에 맞게 함께 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#7','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C15',3,'mc','auto','「오빠, 일찍 왔네유.」를 고향 집 마당에서와 학교 발표에서 읽어 본 뒤 알 수 있는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X23','K5-2-u3-X12']::text[],false,'{"seq":7,"concept":"K5-2-u3-C15","difficulty":3,"kind":"mc","stem":"「오빠, 일찍 왔네유.」를 고향 집 마당에서와 학교 발표에서 읽어 본 뒤 알 수 있는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 말도 자리에 따라 어울리는 정도가 다르다","correct":true},{"t":"방언은 어디서 읽어도 틀린 문장이다","mis":"K5-2-u3-X15"},{"t":"표준어로 바꾸면 뜻이 달라진다","mis":"K5-2-u3-X23"},{"t":"두 자리에서 느낌이 똑같다","mis":"K5-2-u3-X12"}],"explanation":["틀린 문장이 아니에요.","뜻은 같아요.","자리마다 어울림이 달라요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#8','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C13',4,'essay','teacher','여러 사람에게 정보를 전하는 방송에서 방언만 쓰면 어떤 일이 생길지와, 같은 지역 사람끼리 방언을 쓰면 좋은 점을 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C13","difficulty":4,"kind":"essay","stem":"여러 사람에게 정보를 전하는 방송에서 방언만 쓰면 어떤 일이 생길지와, 같은 지역 사람끼리 방언을 쓰면 좋은 점을 함께 쓰세요.","answer_guide":{"answer":"예: 여러 지역 사람이 듣는 방송에서 방언만 쓰면 말이 달라 내용을 제대로 이해하지 못하는 사람이 생길 수 있다. 하지만 같은 지역 사람끼리 방언을 쓰면 어릴 때부터 쓰던 말로 이야기하니 더 친근하고 정답게 마음을 나눌 수 있다.","scoring_points":["방송에서 생길 수 있는 일을 썼는가","같은 지역 사람끼리의 좋은 점을 썼는가","두 가지를 함께 견주었는가"]},"explanation":["알아듣기 어려워요.","친근하고 정다워요.","둘을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#9','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C16',4,'essay','teacher','표준어나 방언을 쓰거나 들어 본 경험을 하나 골라 누구에게 · 어떤 상황에서 · 어떤 사이에서 썼는지와 그 말을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C16","difficulty":4,"kind":"essay","stem":"표준어나 방언을 쓰거나 들어 본 경험을 하나 골라 누구에게 · 어떤 상황에서 · 어떤 사이에서 썼는지와 그 말을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니께서 이모와 전화하실 때 고향 말을 쓰셨다. 누구에게 — 이모에게, 어떤 상황에서 — 명절 안부를 묻는 전화, 어떤 사이 — 같은 고향에서 자란 가족. 서로 편하고 정답게 이야기하시려고 방언을 고르신 것 같다.","scoring_points":["누구에게를 썼는가","어떤 상황 · 어떤 사이를 썼는가","그 말을 고른 까닭을 썼는가"]},"explanation":["듣는 사람을 써요.","상황과 관계를 써요.","까닭까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L04_challenge#10','kor',5,2,'u3','L04','g5_2_kor_u3_L04_challenge','lesson_challenge','K5-2-u3-C12',4,'essay','teacher','「설날, 외할머니 댁에서」의 엄마 말과 기상 캐스터의 말을 견주어, 말을 고르는 기준이 무엇인지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C12","difficulty":4,"kind":"essay","stem":"「설날, 외할머니 댁에서」의 엄마 말과 기상 캐스터의 말을 견주어, 말을 고르는 기준이 무엇인지 쓰세요.","answer_guide":{"answer":"예: 엄마는 고향 사람인 외삼촌과 더 가깝게 이야기하려고 방언을 썼고, 기상 캐스터는 전국 사람에게 똑같이 정확히 전하려고 표준어를 썼다. 이를 보면 말을 고르는 기준은 좋고 나쁨이 아니라 누구에게, 어떤 자리에서, 무엇을 위해 말하느냐이다.","scoring_points":["엄마가 방언을 쓴 까닭을 썼는가","기상 캐스터가 표준어를 쓴 까닭을 썼는가","말을 고르는 기준을 정리했는가"]},"explanation":["가까움이에요.","정확히 전하기예요.","기준은 듣는 사람과 자리예요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#1','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',1,'mc','auto','보고서에서 집과 집 사이 좁은 돌담길을 마을 사람들이 부른 말은 어느 것인가요?',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":1,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"보고서에서 집과 집 사이 좁은 돌담길을 마을 사람들이 부른 말은 어느 것인가요?","options":[{"t":"올레","correct":true},{"t":"정낭","mis":"K5-2-u3-X17"},{"t":"삼춘","mis":"K5-2-u3-X17"},{"t":"물허벅","mis":"K5-2-u3-X17"}],"explanation":["대문 가로대예요.","마을 어른이에요.","둘째 줄에 나와요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#2','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',1,'mc','auto','「정낭」에 걸린 막대 수로 알 수 있는 것은 무엇인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":2,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"「정낭」에 걸린 막대 수로 알 수 있는 것은 무엇인가요?","options":[{"t":"집주인이 집에 있는지","correct":true},{"t":"마을의 나이","mis":"K5-2-u3-X21"},{"t":"바닷물의 높이","mis":"K5-2-u3-X21"},{"t":"오늘의 날씨","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","넷째 줄에 나와요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#3','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C18',1,'mc','auto','갯벌이 넓은 전라 지역에서 갯벌을 가리키는 방언은 어느 것인가요?',ARRAY['K5-2-u3-X09']::text[],false,'{"seq":3,"concept":"K5-2-u3-C18","difficulty":1,"kind":"mc","stem":"갯벌이 넓은 전라 지역에서 갯벌을 가리키는 방언은 어느 것인가요?","options":[{"t":"뻘","correct":true},{"t":"돔배기","mis":"K5-2-u3-X09"},{"t":"정낭","mis":"K5-2-u3-X09"},{"t":"찌짐","mis":"K5-2-u3-X09"}],"explanation":["상어고기예요.","대문 가로대예요.","부침개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#4','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C19',1,'ox','auto','방언은 지역의 문화를 드러내는 소중한 자산이에요.',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":4,"concept":"K5-2-u3-C19","difficulty":1,"kind":"ox","stem":"방언은 지역의 문화를 드러내는 소중한 자산이에요.","answer":"O","reason_options":[{"t":"지역의 자연과 생활, 사람들의 정이 담겨 있기 때문에","correct":true},{"t":"말투만 다를 뿐 담긴 것이 없기 때문에","mis":"K5-2-u3-X17"}],"mis":"K5-2-u3-X17","explanation":["방언에는 생활이 담겨요.","자연도 담겨요.","지역 문화의 자산이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#5','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',2,'mc','auto','「삼춘」이라는 말에서 짐작할 수 있는 마을의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":5,"concept":"K5-2-u3-C17","difficulty":2,"kind":"mc","stem":"「삼춘」이라는 말에서 짐작할 수 있는 마을의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"피를 나누지 않은 이웃 어른도 가족처럼 여긴다","correct":true},{"t":"삼촌만 마을에 산다","mis":"K5-2-u3-X17"},{"t":"어른과 아이가 서로 말을 하지 않는다","mis":"K5-2-u3-X17"},{"t":"어른을 이름으로만 부른다","mis":"K5-2-u3-X17"}],"explanation":["이웃 어른을 불러요.","가깝게 지내요.","가족처럼 불러요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#6','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C18',2,'match','auto','방언과 그 말에 담긴 지역의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-2-u3-C18","difficulty":2,"kind":"match","stem":"방언과 그 말에 담긴 지역의 모습을 알맞게 이으세요.","pairs":[{"l":"감재옹심이","r":"산이 많아 감자 농사가 활발한 강원 지역"},{"l":"뻘","r":"갯벌이 넓은 전라 지역"},{"l":"돔배기","r":"상어를 소금에 절여 먹는 경상 지역"}],"mis":"K5-2-u3-X18","explanation":["감자 음식이에요.","갯벌이에요.","절인 상어고기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#7','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C19',2,'mc','auto','방언의 가치로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X20']::text[],false,'{"seq":7,"concept":"K5-2-u3-C19","difficulty":2,"kind":"mc","stem":"방언의 가치로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"다른 지역 사람과 말이 통하지 않게 막아 준다","correct":true},{"t":"지역의 자연환경과 생활 모습을 담고 있다","mis":"K5-2-u3-X19"},{"t":"우리말의 옛 모습을 간직하고 있다","mis":"K5-2-u3-X20"},{"t":"그 지역 사람들의 정서를 보여 준다","mis":"K5-2-u3-X19"}],"explanation":["방언의 가치예요.","방언의 가치예요.","막으려고 생긴 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#8','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C17',2,'error','auto','보고서를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X17','K5-2-u3-X19','K5-2-u3-X18']::text[],false,'{"seq":8,"concept":"K5-2-u3-C17","difficulty":2,"kind":"error","stem":"보고서를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「정낭은 그냥 막대 이름이라 마을 생활과는 관계없어.」","correct":true,"mis_target":"K5-2-u3-X17"},{"t":"「정낭에는 이웃을 믿고 살던 생활이 담겨 있어.」","mis":"K5-2-u3-X19"},{"t":"「물허벅으로 섬에서 물을 길어 나르던 모습을 알 수 있어.」","mis":"K5-2-u3-X18"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","막대 하나에도 생활이 담겨요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#9','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C20',2,'mc','auto','몇몇 지역에서 어르신들의 말을 녹음해 방언 사전을 만드는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X08','K5-2-u3-X29']::text[],false,'{"seq":9,"concept":"K5-2-u3-C20","difficulty":2,"kind":"mc","stem":"몇몇 지역에서 어르신들의 말을 녹음해 방언 사전을 만드는 까닭은 무엇인가요?","options":[{"t":"쓰는 사람이 줄어드는 말을 기록해 다음 세대에 물려주려고","correct":true},{"t":"방언을 쓰지 못하게 하려고","mis":"K5-2-u3-X14"},{"t":"표준어를 모두 바꾸려고","mis":"K5-2-u3-X08"},{"t":"방언을 흉내 내는 놀이를 하려고","mis":"K5-2-u3-X29"}],"explanation":["지키려는 일이에요.","표준어를 바꾸려는 게 아니에요.","기록해 물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_basic#10','kor',5,2,'u3','L06','g5_2_kor_u3_L06_basic','lesson_basic','K5-2-u3-C18',3,'mc','auto','「감재옹심이」라는 강원 지역 음식 이름에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X18','K5-2-u3-X17']::text[],false,'{"seq":10,"concept":"K5-2-u3-C18","difficulty":3,"kind":"mc","stem":"「감재옹심이」라는 강원 지역 음식 이름에서 짐작할 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산이 많은 강원 지역에서 감자를 즐겨 길러 먹었다","correct":true},{"t":"강원 지역에서는 감자가 나지 않았다","mis":"K5-2-u3-X18"},{"t":"바다에서 잡은 물고기로 만든 음식이다","mis":"K5-2-u3-X18"},{"t":"음식 이름과 생활은 아무 관계가 없다","mis":"K5-2-u3-X17"}],"explanation":["감재는 감자예요.","감자로 만들어요.","자연과 먹을거리가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#1','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C20',2,'ox','auto','방언이 사라져도 표준어가 있으니 잃는 것은 하나도 없어요.',ARRAY['K5-2-u3-X20']::text[],false,'{"seq":1,"concept":"K5-2-u3-C20","difficulty":2,"kind":"ox","stem":"방언이 사라져도 표준어가 있으니 잃는 것은 하나도 없어요.","answer":"X","reason_options":[{"t":"방언에 담긴 생활과 이야기도 함께 잊힐 수 있기 때문에","correct":true},{"t":"표준어만으로 모든 것을 똑같이 나타낼 수 있기 때문에","mis":"K5-2-u3-X20"}],"mis":"K5-2-u3-X20","explanation":["함께 잊히는 것이 있어요.","표준어로 다 담기 어려워요.","방언은 지켜야 할 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#2','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C17',2,'mc','auto','보고서 마지막 줄에서 글쓴이가 새롭게 알게 된 점은 무엇인가요?',ARRAY['K5-2-u3-X21','K5-2-u3-X19']::text[],false,'{"seq":2,"concept":"K5-2-u3-C17","difficulty":2,"kind":"mc","stem":"보고서 마지막 줄에서 글쓴이가 새롭게 알게 된 점은 무엇인가요?","options":[{"t":"방언 하나하나에 마을의 자연과 생활이 담겨 있다는 것","correct":true},{"t":"돌담 마을에는 길이 없다는 것","mis":"K5-2-u3-X21"},{"t":"방언은 외우기 어렵다는 것","mis":"K5-2-u3-X19"},{"t":"박물관이 아주 크다는 것","mis":"K5-2-u3-X21"}],"explanation":["올레라는 길이 있어요.","글에 없어요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#3','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C19',3,'mc','auto','「물허벅은 물동이니까 그냥 물동이라고 하면 되지 않아?」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X17','K5-2-u3-X15','K5-2-u3-X03']::text[],false,'{"seq":3,"concept":"K5-2-u3-C19","difficulty":3,"kind":"mc","stem":"「물허벅은 물동이니까 그냥 물동이라고 하면 되지 않아?」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「물허벅에는 섬에서 물을 길어 나르던 생활과 그 모양이 함께 담겨 있어.」","correct":true},{"t":"「맞아, 같은 뜻이니 아무거나 써도 돼.」","mis":"K5-2-u3-X17"},{"t":"「물허벅은 틀린 말이니 물동이로 고쳐야 해.」","mis":"K5-2-u3-X15"},{"t":"「물동이는 방언이고 물허벅이 표준어야.」","mis":"K5-2-u3-X03"}],"explanation":["담긴 생활이 달라요.","고칠 말이 아니에요.","바꾸면 느낌이 줄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#4','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C18',3,'mc','auto','「돔배기」라는 방언으로 경상 지역에 대해 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X18','K5-2-u3-X10','K5-2-u3-X17']::text[],false,'{"seq":4,"concept":"K5-2-u3-C18","difficulty":3,"kind":"mc","stem":"「돔배기」라는 방언으로 경상 지역에 대해 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바다에서 잡은 상어를 소금에 절여 먹는 문화가 있었다","correct":true},{"t":"바다와 멀어 물고기를 먹지 않았다","mis":"K5-2-u3-X18"},{"t":"돔배기는 산에서 캐는 나물이다","mis":"K5-2-u3-X10"},{"t":"돔배기와 지역 생활은 관계없다","mis":"K5-2-u3-X17"}],"explanation":["동해와 가까워요.","상어고기예요.","먹을거리 문화가 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#5','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C20',3,'mc','auto','「정낭」이라는 말을 쓰지 않고 그 막대와 쓰임을 설명해 보면 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X19','K5-2-u3-X30']::text[],false,'{"seq":5,"concept":"K5-2-u3-C20","difficulty":3,"kind":"mc","stem":"「정낭」이라는 말을 쓰지 않고 그 막대와 쓰임을 설명해 보면 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언 하나에 많은 생활 모습이 담겨 있어 설명이 길어진다","correct":true},{"t":"방언이 없어도 짧게 설명할 수 있다","mis":"K5-2-u3-X20"},{"t":"정낭은 쓸모없는 옛말이다","mis":"K5-2-u3-X19"},{"t":"표준어가 언제나 더 짧고 좋은 말이다","mis":"K5-2-u3-X30"}],"explanation":["설명이 길어져요.","쓸모없지 않아요.","말 하나에 많은 것이 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#6','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C19',3,'error','auto','방언의 가치를 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X17','K5-2-u3-X20']::text[],false,'{"seq":6,"concept":"K5-2-u3-C19","difficulty":3,"kind":"error","stem":"방언의 가치를 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「방언은 옛날 말이라 지금 생활과는 아무 관계가 없어.」","correct":true,"mis_target":"K5-2-u3-X19"},{"t":"「방언에는 이웃을 가족처럼 여기는 정이 담겨 있어.」","mis":"K5-2-u3-X17"},{"t":"「방언은 우리말의 옛 모습을 간직하고 있어.」","mis":"K5-2-u3-X20"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","지금도 쓰이며 문화를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#7','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언 속 지역 이야기 카드를 만들 때 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X01','K5-2-u3-X28']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언 속 지역 이야기 카드를 만들 때 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역의 말을 낮추어 보지 않고 생활을 존중하며 소개한다","correct":true},{"t":"재미있게 하려고 방언을 과장해 흉내 낸다","mis":"K5-2-u3-X29"},{"t":"낯선 방언은 이상한 말이라고 쓴다","mis":"K5-2-u3-X01"},{"t":"방언 뜻만 빠르게 많이 적는다","mis":"K5-2-u3-X28"}],"explanation":["흉내는 예의가 아니에요.","이상한 말이 아니에요.","생활을 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#8','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C18',4,'essay','teacher','「뻘」에 전라 지역의 어떤 자연환경이 담겨 있는지 쓰고, 우리 지역의 자연이나 생활이 담겼을 것 같은 말을 하나 떠올려 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C18","difficulty":4,"kind":"essay","stem":"「뻘」에 전라 지역의 어떤 자연환경이 담겨 있는지 쓰고, 우리 지역의 자연이나 생활이 담겼을 것 같은 말을 하나 떠올려 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「뻘」에는 서해안에 갯벌이 넓게 펼쳐진 전라 지역의 자연환경이 담겨 있다. 우리 지역은 바다와 가까워 할아버지께서 쓰시는 고기잡이 도구 이름에 바닷가 생활이 담겨 있을 것 같다. 바다에서 일하는 모습이 말에 그대로 남았을 것이기 때문이다.","scoring_points":["뻘에 담긴 자연환경을 썼는가","우리 지역 말을 하나 떠올렸는가","자연이나 생활과 이은 까닭을 썼는가"]},"explanation":["갯벌이에요.","우리 지역 말을 떠올려요.","까닭을 써요. 표준어를 쓰는 지역이면 그 말도 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#9','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C20',4,'essay','teacher','방언이 사라진다면 어떤 일이 생길지 상상해 쓰고, 방언이 소중한 까닭을 내 생각으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C20","difficulty":4,"kind":"essay","stem":"방언이 사라진다면 어떤 일이 생길지 상상해 쓰고, 방언이 소중한 까닭을 내 생각으로 쓰세요.","answer_guide":{"answer":"예: 방언이 사라지면 할머니께서 쓰시던 말과 그 말에 담긴 옛 생활 이야기를 아무도 모르게 될 것이다. 방언은 지역의 자연과 생활, 사람들의 정을 담고 있어서 그 지역의 문화를 지키는 말이기 때문에 소중하다.","scoring_points":["사라질 때 생길 일을 상상해 썼는가","방언이 소중한 까닭을 썼는가","까닭이 방언의 가치와 이어지는가"]},"explanation":["잊히는 것을 떠올려요.","까닭을 써요.","가치와 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L06_challenge#10','kor',5,2,'u3','L06','g5_2_kor_u3_L06_challenge','lesson_challenge','K5-2-u3-C17',4,'essay','teacher','「올레」, 「정낭」, 「삼춘」, 「물허벅」 가운데 하나를 골라 그 말에 담긴 마을의 생활 모습을 설명하는 카드 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C17","difficulty":4,"kind":"essay","stem":"「올레」, 「정낭」, 「삼춘」, 「물허벅」 가운데 하나를 골라 그 말에 담긴 마을의 생활 모습을 설명하는 카드 글을 쓰세요.","answer_guide":{"answer":"예: 정낭 — 제주 지역 집 앞에 대문 대신 가로로 걸어 둔 긴 나무 막대이다. 걸어 둔 막대 수로 집주인이 집에 있는지 알렸다. 대문을 잠그지 않고 이웃을 믿으며 살던 열린 생활이 담겨 있다.","scoring_points":["방언 하나를 골라 뜻을 썼는가","쓰임을 설명했는가","담긴 생활 모습을 썼는가"]},"explanation":["뜻을 써요.","쓰임을 써요.","생활 모습을 써요."],"asset":{"type":"passage","lines":["우리 모둠은 체험 학습으로 제주 지역의 돌담 마을에 다녀왔다.","집과 집 사이 좁은 돌담길을 마을 사람들은 「올레」라고 불렀다.","집 앞에는 대문 대신 긴 나무 막대 「정낭」이 걸려 있었는데,","걸린 막대 수로 주인이 집에 있는지 알 수 있다고 했다.","안내해 주신 어른을 마을 아이들은 「삼춘」이라고 불렀다.","피를 나누지 않아도 가족처럼 부르는 말이라고 한다.","박물관에서는 물을 길어 나르던 동이 「물허벅」을 보았다.","방언 하나하나에 이 마을의 자연과 생활이 담겨 있다는 것을 알게 되었다."],"title":"돌담 마을 체험 학습 보고서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#1','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C21',1,'mc','auto','「감 따는 날」에서 하준이가 가을 방학에 간 곳은 어디인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":1,"concept":"K5-2-u3-C21","difficulty":1,"kind":"mc","stem":"「감 따는 날」에서 하준이가 가을 방학에 간 곳은 어디인가요?","options":[{"t":"외할머니가 사시는 남쪽 바닷가 마을","correct":true},{"t":"큰 도시의 시장","mis":"K5-2-u3-X21"},{"t":"산속 마을의 절","mis":"K5-2-u3-X21"},{"t":"친구네 아파트","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","첫 줄에 나와요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#2','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',1,'mc','auto','외할머니가 부른 「아야」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":2,"concept":"K5-2-u3-C22","difficulty":1,"kind":"mc","stem":"외할머니가 부른 「아야」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"얘야","correct":true},{"t":"아파","mis":"K5-2-u3-X22"},{"t":"어머나","mis":"K5-2-u3-X22"},{"t":"잘 가","mis":"K5-2-u3-X22"}],"explanation":["아픈 소리가 아니에요.","놀란 소리가 아니에요.","하준이를 부르는 말이에요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#3','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',1,'blank','auto','「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸면 「못 보던 ( ? ), 누구 손주니?」예요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":3,"concept":"K5-2-u3-C22","difficulty":1,"kind":"blank","stem":"「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸면 「못 보던 ( ? ), 누구 손주니?」예요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"얼굴인데","correct":true},{"t":"얼굴이여","mis":"K5-2-u3-X22"},{"t":"얼굴이니까","mis":"K5-2-u3-X22"},{"t":"얼굴이겠지","mis":"K5-2-u3-X22"}],"explanation":["끝말이 그대로예요.","뜻이 달라요.","「~인디」는 「~인데」예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#4','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C24',1,'ox','auto','이야기에 방언을 쓰면 인물이 어디에 사는 누구인지 더 생생하게 느껴져요.',ARRAY['K5-2-u3-X24']::text[],false,'{"seq":4,"concept":"K5-2-u3-C24","difficulty":1,"kind":"ox","stem":"이야기에 방언을 쓰면 인물이 어디에 사는 누구인지 더 생생하게 느껴져요.","answer":"O","reason_options":[{"t":"방언이 인물의 목소리와 지역의 분위기를 살려 주기 때문에","correct":true},{"t":"방언은 읽기 어려워 인물을 알 수 없게 하기 때문에","mis":"K5-2-u3-X24"}],"mis":"K5-2-u3-X24","explanation":["생동감이 생겨요.","분위기가 살아나요.","인물이 생생해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#5','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C21',2,'mc','auto','할머니들이 「그러니께 얼굴이 하얗겄제.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":5,"concept":"K5-2-u3-C21","difficulty":2,"kind":"mc","stem":"할머니들이 「그러니께 얼굴이 하얗겄제.」라고 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하준이가 서울에서 왔다는 말을 들어서","correct":true},{"t":"하준이가 아파 보여서","mis":"K5-2-u3-X21"},{"t":"감이 하얘서","mis":"K5-2-u3-X21"},{"t":"날이 추워서","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","감 이야기가 아니에요.","셋째 줄 바로 뒤예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#6','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',2,'mc','auto','감나무 아래에서 「싸게싸게 와서」라고 부른 말의 뜻을 앞뒤 장면으로 짐작하면 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":6,"concept":"K5-2-u3-C22","difficulty":2,"kind":"mc","stem":"감나무 아래에서 「싸게싸게 와서」라고 부른 말의 뜻을 앞뒤 장면으로 짐작하면 어느 것인가요?","options":[{"t":"빨리빨리 와서","correct":true},{"t":"천천히 와서","mis":"K5-2-u3-X22"},{"t":"조심조심 와서","mis":"K5-2-u3-X22"},{"t":"살금살금 와서","mis":"K5-2-u3-X22"}],"explanation":["서두르라는 장면이에요.","바구니를 잡으라고 불러요.","「싸게싸게」는 빨리빨리예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#7','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C21',2,'mc','auto','하준이의 마음은 이야기 처음과 끝에서 어떻게 달라졌나요?',ARRAY['K5-2-u3-X21','K5-2-u3-X22']::text[],false,'{"seq":7,"concept":"K5-2-u3-C21","difficulty":2,"kind":"mc","stem":"하준이의 마음은 이야기 처음과 끝에서 어떻게 달라졌나요?","options":[{"t":"낯설던 말이 따뜻하게 들리게 되었다","correct":true},{"t":"따뜻하던 말이 무섭게 들리게 되었다","mis":"K5-2-u3-X21"},{"t":"처음부터 끝까지 지루했다","mis":"K5-2-u3-X21"},{"t":"할머니들 말을 끝까지 못 알아들어 속상했다","mis":"K5-2-u3-X22"}],"explanation":["거꾸로예요.","글에 없어요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#8','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C22',2,'match','auto','이야기 속 방언 끝말과 뜻이 같은 표준어 끝말을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C22","difficulty":2,"kind":"match","stem":"이야기 속 방언 끝말과 뜻이 같은 표준어 끝말을 알맞게 이으세요.","pairs":[{"l":"~인디","r":"~인데"},{"l":"~당께","r":"~다니까"},{"l":"~겄제","r":"~겠지"}],"mis":"K5-2-u3-X22","explanation":["얼굴인디 → 얼굴인데예요.","왔당께 → 왔다니까예요.","하얗겄제 → 하얗겠지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#9','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C23',2,'error','auto','방언 문장과 표준어 문장을 읽어 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X24','K5-2-u3-X15']::text[],false,'{"seq":9,"concept":"K5-2-u3-C23","difficulty":2,"kind":"error","stem":"방언 문장과 표준어 문장을 읽어 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「표준어로 바꾸면 뜻이 같으니 느낌도 똑같아.」","correct":true,"mis_target":"K5-2-u3-X23"},{"t":"「방언으로 읽으니 손주를 자랑하는 할머니 목소리가 들리는 것 같아.」","mis":"K5-2-u3-X24"},{"t":"「바꾸어 읽은 건 방언을 고치려는 게 아니라 느낌을 견주려는 거야.」","mis":"K5-2-u3-X15"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","뜻은 같아도 느낌은 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_basic#10','kor',5,2,'u3','L08','g5_2_kor_u3_L08_basic','lesson_basic','K5-2-u3-C24',3,'mc','auto','「감 따는 날」에서 방언이 한 역할로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X24','K5-2-u3-X21']::text[],false,'{"seq":10,"concept":"K5-2-u3-C24","difficulty":3,"kind":"mc","stem":"「감 따는 날」에서 방언이 한 역할로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마을 사람들이 하준이를 반갑게 맞는 정다운 분위기를 살렸다","correct":true},{"t":"이야기를 읽기 어렵게만 만들었다","mis":"K5-2-u3-X24"},{"t":"줄거리를 바꾸어 놓았다","mis":"K5-2-u3-X21"},{"t":"하준이가 서울에서 왔다는 것을 숨겼다","mis":"K5-2-u3-X21"}],"explanation":["생동감을 주었어요.","줄거리는 그대로예요.","정다운 분위기가 살아나요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#1','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C23',2,'ox','auto','이야기 속 방언을 표준어로 바꾸어 읽어 보는 것은 방언을 고쳐 쓰려는 것이에요.',ARRAY['K5-2-u3-X15']::text[],false,'{"seq":1,"concept":"K5-2-u3-C23","difficulty":2,"kind":"ox","stem":"이야기 속 방언을 표준어로 바꾸어 읽어 보는 것은 방언을 고쳐 쓰려는 것이에요.","answer":"X","reason_options":[{"t":"두 문장의 느낌을 견주어 방언이 하는 일을 알기 위한 것이기 때문에","correct":true},{"t":"방언은 이야기에 쓰면 안 되는 말이기 때문에","mis":"K5-2-u3-X15"}],"mis":"K5-2-u3-X15","explanation":["고치기가 아니에요.","느낌을 견주어요.","방언이 하는 일을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#2','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C25',2,'mc','auto','작품을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X25','K5-2-u3-X24']::text[],false,'{"seq":2,"concept":"K5-2-u3-C25","difficulty":2,"kind":"mc","stem":"작품을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나도 할머니 댁에서 정다운 고향 말을 들으면 반가웠는데, 하준이 마음을 알 것 같아.」","correct":true},{"t":"「감나무 잎은 초록색이야.」","mis":"K5-2-u3-X25"},{"t":"「이 이야기는 아주 짧아.」","mis":"K5-2-u3-X25"},{"t":"「방언은 어려우니 읽지 않을래.」","mis":"K5-2-u3-X24"}],"explanation":["작품과 내 삶이 이어지지 않아요.","감상이 아니에요.","내 경험과 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#3','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C23',3,'mc','auto','「우리 딸네 아들이여. 서울서 왔당께.」를 표준어로 바꾸면 줄어드는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X21']::text[],false,'{"seq":3,"concept":"K5-2-u3-C23","difficulty":3,"kind":"mc","stem":"「우리 딸네 아들이여. 서울서 왔당께.」를 표준어로 바꾸면 줄어드는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"손주를 자랑하는 외할머니의 정다운 목소리","correct":true},{"t":"외할머니가 한 말의 뜻","mis":"K5-2-u3-X23"},{"t":"하준이가 어디서 왔는지에 대한 정보","mis":"K5-2-u3-X23"},{"t":"이야기의 줄거리","mis":"K5-2-u3-X21"}],"explanation":["뜻은 같아요.","정보는 그대로예요.","목소리와 정이 줄어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#4','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C24',3,'mc','auto','이야기의 대사를 모두 표준어로 바꾸었더니 친구들이 「뭔가 허전하다.」라고 했어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X13','K5-2-u3-X24']::text[],false,'{"seq":4,"concept":"K5-2-u3-C24","difficulty":3,"kind":"mc","stem":"이야기의 대사를 모두 표준어로 바꾸었더니 친구들이 「뭔가 허전하다.」라고 했어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"할머니들의 목소리와 마을 분위기, 정다운 마음이 줄어들어서","correct":true},{"t":"줄거리가 완전히 바뀌어서","mis":"K5-2-u3-X23"},{"t":"뜻을 알아들을 수 없게 되어서","mis":"K5-2-u3-X13"},{"t":"글자 수가 늘어나서","mis":"K5-2-u3-X24"}],"explanation":["줄거리는 같아요.","오히려 뜻은 잘 알아요.","분위기와 정이 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#5','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C22',3,'mc','auto','작품을 읽다가 뜻을 모르는 방언을 만났을 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u3-X22','K5-2-u3-X10','K5-2-u3-X24']::text[],false,'{"seq":5,"concept":"K5-2-u3-C22","difficulty":3,"kind":"mc","stem":"작품을 읽다가 뜻을 모르는 방언을 만났을 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"앞뒤 장면으로 짐작하고 지역어 누리집이나 사전에서 확인한다","correct":true},{"t":"모르는 말은 건너뛰고 읽는다","mis":"K5-2-u3-X22"},{"t":"아무 뜻이나 넣어 읽는다","mis":"K5-2-u3-X10"},{"t":"방언이 나오는 책은 읽지 않는다","mis":"K5-2-u3-X24"}],"explanation":["놓치는 것이 생겨요.","근거가 없어요.","짐작하고 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#6','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C21',3,'error','auto','「감 따는 날」을 읽고 감상을 나눈 친구들이에요. 감상의 초점이 가장 어긋난 것은 어느 것인가요?',ARRAY['K5-2-u3-X21','K5-2-u3-X25','K5-2-u3-X24']::text[],false,'{"seq":6,"concept":"K5-2-u3-C21","difficulty":3,"kind":"error","stem":"「감 따는 날」을 읽고 감상을 나눈 친구들이에요. 감상의 초점이 가장 어긋난 것은 어느 것인가요?","options":[{"t":"「방언 뜻 맞히기만 하면 이 이야기는 다 읽은 거야.」","correct":true,"mis_target":"K5-2-u3-X21"},{"t":"「낯설던 말이 따뜻하게 들린 하준이 마음이 좋았어.」","mis":"K5-2-u3-X25"},{"t":"「정자 장면에서 마을 사람들이 반기는 분위기가 느껴졌어.」","mis":"K5-2-u3-X24"}],"explanation":["마음을 읽었어요.","분위기를 느꼈어요.","줄거리와 마음도 읽어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#7','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언 살려 낭독하기를 할 때 지켜야 할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X24','K5-2-u3-X22']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언 살려 낭독하기를 할 때 지켜야 할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"과장해 흉내 내지 않고 인물의 마음을 살려 읽는다","correct":true},{"t":"웃음을 끌려고 말투를 크게 부풀린다","mis":"K5-2-u3-X29"},{"t":"방언은 빼고 표준어로만 읽는다","mis":"K5-2-u3-X24"},{"t":"뜻을 몰라도 빨리 읽고 끝낸다","mis":"K5-2-u3-X22"}],"explanation":["웃음거리가 돼요.","방언 낭독이 아니에요.","마음을 살려 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#8','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C23',4,'essay','teacher','「서울서 왔당께.」를 표준어로 바꾸어 쓰고, 두 문장을 읽었을 때 느낌이 어떻게 다른지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C23","difficulty":4,"kind":"essay","stem":"「서울서 왔당께.」를 표준어로 바꾸어 쓰고, 두 문장을 읽었을 때 느낌이 어떻게 다른지 쓰세요.","answer_guide":{"answer":"예: 표준어로 바꾸면 「서울에서 왔다니까.」이다. 뜻은 같지만 방언으로 읽으면 손주를 자랑하고 싶은 외할머니의 정다운 목소리가 들리는 것 같고, 표준어로 읽으면 그 느낌이 조금 줄어든다.","scoring_points":["표준어로 바르게 바꾸었는가","뜻은 같다는 것을 알았는가","느낌의 차이를 썼는가"]},"explanation":["「~당께」는 「~다니까」예요.","뜻은 같아요.","느낌이 달라요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#9','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C25',4,'essay','teacher','「감 따는 날」에서 가장 인상 깊은 장면을 고르고, 그 장면에서 방언이 한 역할을 내 경험과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C25","difficulty":4,"kind":"essay","stem":"「감 따는 날」에서 가장 인상 깊은 장면을 고르고, 그 장면에서 방언이 한 역할을 내 경험과 이어 쓰세요.","answer_guide":{"answer":"예: 정자에서 할머니들이 하준이에게 누구 손주냐고 묻는 장면이 인상 깊다. 할머니들의 방언 덕분에 마을 사람들이 처음 온 아이를 반갑게 맞아 주는 분위기가 살아났다. 나도 시골 할머니 댁에 갔을 때 이웃 어르신들이 고향 말로 반겨 주셔서 마음이 따뜻했던 기억이 난다.","scoring_points":["장면을 하나 골랐는가","그 장면에서 방언의 역할을 썼는가","내 경험과 이었는가"]},"explanation":["장면을 골라요.","역할을 써요.","내 경험과 이어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L08_challenge#10','kor',5,2,'u3','L08','g5_2_kor_u3_L08_challenge','lesson_challenge','K5-2-u3-C24',4,'essay','teacher','이야기에 방언을 쓰면 좋은 점을 두 가지 쓰고, 「감 따는 날」에서 근거가 되는 장면을 하나씩 드세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C24","difficulty":4,"kind":"essay","stem":"이야기에 방언을 쓰면 좋은 점을 두 가지 쓰고, 「감 따는 날」에서 근거가 되는 장면을 하나씩 드세요.","answer_guide":{"answer":"예: 첫째, 인물이 어디에 사는 누구인지 생생하게 느껴진다. 할머니들의 「~인디, ~여」 하는 말에서 남쪽 바닷가 마을 할머니들이 떠오른다. 둘째, 인물 사이의 정이 살아난다. 외할머니가 「아야, 싸게싸게 와서」라고 부르는 장면에서 손주를 아끼는 마음이 느껴진다.","scoring_points":["좋은 점 두 가지를 썼는가","각각 장면 근거를 들었는가","근거가 좋은 점과 맞는가"]},"explanation":["좋은 점을 써요.","장면을 들어요.","근거를 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#1','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C27',1,'mc','auto','우리 반 방언 지도를 만드는 첫 단계로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X27']::text[],false,'{"seq":1,"concept":"K5-2-u3-C27","difficulty":1,"kind":"mc","stem":"우리 반 방언 지도를 만드는 첫 단계로 알맞은 것은 어느 것인가요?","options":[{"t":"조사할 방언 주제 정하기","correct":true},{"t":"지도에 색칠하기","mis":"K5-2-u3-X27"},{"t":"다른 반 지도 베끼기","mis":"K5-2-u3-X27"},{"t":"잘한 모둠에게 줄 상장 만들기","mis":"K5-2-u3-X27"}],"explanation":["주제가 먼저예요.","우리 반이 조사해요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#2','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C26',1,'mc','auto','방언을 활용해 만들 수 있는 작품이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X26']::text[],false,'{"seq":2,"concept":"K5-2-u3-C26","difficulty":1,"kind":"mc","stem":"방언을 활용해 만들 수 있는 작품이 아닌 것은 어느 것인가요?","options":[{"t":"곱셈 구구표","correct":true},{"t":"우리 반 방언 지도","mis":"K5-2-u3-X26"},{"t":"방언 노랫말","mis":"K5-2-u3-X26"},{"t":"방언 상황극","mis":"K5-2-u3-X26"}],"explanation":["방언 작품이에요.","방언 작품이에요.","방언과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#3','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C9',1,'mc','auto','조사표에서 명절이나 비 오는 날 즐겨 부쳐 먹는 음식으로 소개한 「찌짐」을 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":3,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"조사표에서 명절이나 비 오는 날 즐겨 부쳐 먹는 음식으로 소개한 「찌짐」을 표준어로 바꾸면 어느 것인가요?","options":[{"t":"부침개","correct":true},{"t":"떡국","mis":"K5-2-u3-X10"},{"t":"비빔밥","mis":"K5-2-u3-X10"},{"t":"김밥","mis":"K5-2-u3-X10"}],"explanation":["부쳐 먹는 음식이 아니에요.","부쳐 먹는 음식이 아니에요.","찌짐은 부침개예요."],"asset":{"type":"passage","lines":["찌짐 — 명절이나 비 오는 날 즐겨 부쳐 먹는 음식","무시 — 깍두기를 담그거나 국에 넣는 흰 뿌리채소","짐치 — 밥상에 빠지지 않는 매운 반찬","돔배기 — 소금에 절여 토막 낸 상어고기"],"title":"우리 반 방언 조사표 — 음식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#4','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',1,'ox','auto','방언 지도는 방언을 많이 모을수록 잘 만든 것이에요.',ARRAY['K5-2-u3-X28']::text[],false,'{"seq":4,"concept":"K5-2-u3-C28","difficulty":1,"kind":"ox","stem":"방언 지도는 방언을 많이 모을수록 잘 만든 것이에요.","answer":"X","reason_options":[{"t":"방언이 어떤 지역의 어떤 생활을 보여 주는지가 잘 드러나야 하기 때문에","correct":true},{"t":"개수가 많으면 저절로 지역이 잘 보이기 때문에","mis":"K5-2-u3-X28"}],"mis":"K5-2-u3-X28","explanation":["개수보다 내용이에요.","생활이 드러나야 해요.","뜻과 생활을 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#5','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',2,'mc','auto','방언 지도에 방언과 함께 적으면 좋은 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X18']::text[],false,'{"seq":5,"concept":"K5-2-u3-C28","difficulty":2,"kind":"mc","stem":"방언 지도에 방언과 함께 적으면 좋은 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"방언을 흉내 낸 우스운 그림","correct":true},{"t":"방언을 쓰는 지역 이름","mis":"K5-2-u3-X28"},{"t":"방언의 뜻","mis":"K5-2-u3-X28"},{"t":"방언과 이어지는 생활 모습","mis":"K5-2-u3-X18"}],"explanation":["함께 적어요.","함께 적어요.","웃음거리로 삼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#6','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C27',2,'mc','auto','방언 지도를 만드는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X27']::text[],false,'{"seq":6,"concept":"K5-2-u3-C27","difficulty":2,"kind":"mc","stem":"방언 지도를 만드는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 지역 나누기 → 조사하기 → 지도에 붙이기","correct":true},{"t":"지도에 붙이기 → 조사하기 → 주제 정하기 → 지역 나누기","mis":"K5-2-u3-X27"},{"t":"조사하기 → 주제 정하기 → 지도에 붙이기 → 지역 나누기","mis":"K5-2-u3-X27"},{"t":"지역 나누기 → 지도에 붙이기 → 주제 정하기 → 조사하기","mis":"K5-2-u3-X27"}],"explanation":["붙이기는 맨 끝이에요.","주제가 먼저예요.","주제 → 지역 → 조사 → 붙이기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#7','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C29',2,'mc','auto','방언 상황극을 할 때 조심할 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X26']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":2,"kind":"mc","stem":"방언 상황극을 할 때 조심할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"방언을 웃음거리로 흉내 내지 않고 그 지역 사람의 마음을 살린다","correct":true},{"t":"방언을 과장할수록 잘한 연기이다","mis":"K5-2-u3-X29"},{"t":"대사에 방언을 하나도 넣지 않는다","mis":"K5-2-u3-X26"},{"t":"관객이 웃도록 말투를 일부러 이상하게 한다","mis":"K5-2-u3-X29"}],"explanation":["과장은 흉내가 돼요.","방언이 들어가야 해요.","마음을 살려요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러분! 우리 강원 지역 감재 축제에 오신 걸 환영하드래요!"},{"who":"관객들","text":"반갑드래요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#8','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',2,'match','auto','조사표의 생활 설명을 보고 방언과 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C28","difficulty":2,"kind":"match","stem":"조사표의 생활 설명을 보고 방언과 표준어를 알맞게 이으세요.","pairs":[{"l":"찌짐","r":"부침개"},{"l":"무시","r":"무"},{"l":"짐치","r":"김치"}],"mis":"K5-2-u3-X10","explanation":["부쳐 먹는 음식이에요.","흰 뿌리채소예요.","매운 반찬이에요."],"asset":{"type":"passage","lines":["찌짐 — 명절이나 비 오는 날 즐겨 부쳐 먹는 음식","무시 — 깍두기를 담그거나 국에 넣는 흰 뿌리채소","짐치 — 밥상에 빠지지 않는 매운 반찬","돔배기 — 소금에 절여 토막 낸 상어고기"],"title":"우리 반 방언 조사표 — 음식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#9','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C26',2,'error','auto','방언 활동을 고르는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X26','K5-2-u3-X29','K5-2-u3-X27']::text[],false,'{"seq":9,"concept":"K5-2-u3-C26","difficulty":2,"kind":"error","stem":"방언 활동을 고르는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「방언 활동은 지도 만들기 한 가지뿐이니 다른 건 생각하지 말자.」","correct":true,"mis_target":"K5-2-u3-X26"},{"t":"「아는 노래를 방언으로 바꾸어 부르는 것도 좋겠어.」","mis":"K5-2-u3-X29"},{"t":"「반 전체로 할지 모둠으로 할지도 함께 정하자.」","mis":"K5-2-u3-X27"}],"explanation":["좋은 생각이에요.","좋은 생각이에요.","노랫말 · 상황극도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_basic#10','kor',5,2,'u3','L10','g5_2_kor_u3_L10_basic','lesson_basic','K5-2-u3-C28',3,'mc','auto','방언 지도 가운데 지역을 가장 잘 알려 주는 지도는 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X29']::text[],false,'{"seq":10,"concept":"K5-2-u3-C28","difficulty":3,"kind":"mc","stem":"방언 지도 가운데 지역을 가장 잘 알려 주는 지도는 어느 것인가요?","options":[{"t":"방언 셋에 뜻과 생활 이야기를 붙인 지도","correct":true},{"t":"방언만 아주 많이 붙인 지도","mis":"K5-2-u3-X28"},{"t":"지역 이름 없이 방언만 붙인 지도","mis":"K5-2-u3-X28"},{"t":"우스운 그림만 가득한 지도","mis":"K5-2-u3-X29"}],"explanation":["개수만 많아요.","어느 지역인지 몰라요.","뜻과 생활이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#1','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C11',2,'ox','auto','서로 다른 두 지역에 같은 방언 「짐치」가 붙었다면 한 모둠이 틀린 것이에요.',ARRAY['K5-2-u3-X11']::text[],false,'{"seq":1,"concept":"K5-2-u3-C11","difficulty":2,"kind":"ox","stem":"서로 다른 두 지역에 같은 방언 「짐치」가 붙었다면 한 모둠이 틀린 것이에요.","answer":"X","reason_options":[{"t":"「짐치」는 강원 · 경상 · 전라 등 여러 지역에서 쓰여 방언이 지역 경계와 똑같이 나뉘지 않기 때문에","correct":true},{"t":"한 방언은 꼭 한 지역에서만 쓰이기 때문에","mis":"K5-2-u3-X11"}],"mis":"K5-2-u3-X11","explanation":["여러 지역에서 써요.","둘 다 맞을 수 있어요.","근거로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#2','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C27',2,'mc','auto','모둠마다 조사할 지역을 정할 때 함께 말하면 좋은 것은 어느 것인가요?',ARRAY['K5-2-u3-X27','K5-2-u3-X28']::text[],false,'{"seq":2,"concept":"K5-2-u3-C27","difficulty":2,"kind":"mc","stem":"모둠마다 조사할 지역을 정할 때 함께 말하면 좋은 것은 어느 것인가요?","options":[{"t":"그 지역을 고른 까닭","correct":true},{"t":"그 지역에 가 본 횟수","mis":"K5-2-u3-X27"},{"t":"조사할 방언의 개수","mis":"K5-2-u3-X28"},{"t":"지도를 꾸밀 색깔","mis":"K5-2-u3-X27"}],"explanation":["관계가 적어요.","개수가 중요하지 않아요.","고른 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#3','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C28',3,'mc','auto','조사표의 「찌짐」 옆에 덧붙일 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X01','K5-2-u3-X30']::text[],false,'{"seq":3,"concept":"K5-2-u3-C28","difficulty":3,"kind":"mc","stem":"조사표의 「찌짐」 옆에 덧붙일 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"명절이나 비 오는 날 즐겨 부쳐 먹는 음식","correct":true},{"t":"찌짐 찌짐 찌짐","mis":"K5-2-u3-X28"},{"t":"뜻을 모르는 이상한 말","mis":"K5-2-u3-X01"},{"t":"표준어보다 못한 말","mis":"K5-2-u3-X30"}],"explanation":["되풀이일 뿐이에요.","이상한 말이 아니에요.","생활 이야기를 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#4','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C26',3,'mc','auto','상황극 대본에서 사회자의 방언 인사가 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X01','K5-2-u3-X29']::text[],false,'{"seq":4,"concept":"K5-2-u3-C26","difficulty":3,"kind":"mc","stem":"상황극 대본에서 사회자의 방언 인사가 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 축제의 분위기를 실감 나고 친근하게 살린다","correct":true},{"t":"관객이 뜻을 전혀 모르게 만든다","mis":"K5-2-u3-X13"},{"t":"사회자가 표준어를 모른다는 것을 보여 준다","mis":"K5-2-u3-X01"},{"t":"웃음거리로 삼기 위해 넣은 말이다","mis":"K5-2-u3-X29"}],"explanation":["관객도 함께 대답해요.","표준어를 몰라서가 아니에요.","축제 분위기가 살아나요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러분! 우리 강원 지역 감재 축제에 오신 걸 환영하드래요!"},{"who":"관객들","text":"반갑드래요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#5','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C28',3,'error','auto','우리 반 방언 지도를 보고 나눈 말이에요. 지도를 만드는 목적에서 가장 벗어난 말은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X09','K5-2-u3-X18']::text[],false,'{"seq":5,"concept":"K5-2-u3-C28","difficulty":3,"kind":"error","stem":"우리 반 방언 지도를 보고 나눈 말이에요. 지도를 만드는 목적에서 가장 벗어난 말은 어느 것인가요?","options":[{"t":"「우리 모둠이 제일 많이 붙였으니 우리가 이긴 거야.」","correct":true,"mis_target":"K5-2-u3-X28"},{"t":"「같은 김치도 지역마다 이름이 여러 가지라 신기해.」","mis":"K5-2-u3-X09"},{"t":"「돔배기 카드를 보니 경상 지역 바다 생활이 보여.」","mis":"K5-2-u3-X18"}],"explanation":["새롭게 안 점이에요.","생활을 읽었어요.","개수 겨루기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#6','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C27',3,'mc','auto','조사한 방언을 지도에 붙이기 전에 확인할 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11','K5-2-u3-X28']::text[],false,'{"seq":6,"concept":"K5-2-u3-C27","difficulty":3,"kind":"mc","stem":"조사한 방언을 지도에 붙이기 전에 확인할 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역어 누리집 같은 근거로 방언과 지역이 맞는지 확인한다","correct":true},{"t":"짐작한 대로 바로 붙인다","mis":"K5-2-u3-X10"},{"t":"친구가 붙인 것과 다르면 내 것을 뗀다","mis":"K5-2-u3-X11"},{"t":"방언 개수만 세어 본다","mis":"K5-2-u3-X28"}],"explanation":["근거가 없어요.","둘 다 맞을 수 있어요.","근거로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#7','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C26',3,'mc','auto','반 친구 한 명이 혼자서 방언 노랫말을 만들고 싶다고 해요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X26','K5-2-u3-X14']::text[],false,'{"seq":7,"concept":"K5-2-u3-C26","difficulty":3,"kind":"mc","stem":"반 친구 한 명이 혼자서 방언 노랫말을 만들고 싶다고 해요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"반 전체 · 모둠 · 짝 · 혼자 가운데 알맞은 방식을 함께 정할 수 있다","correct":true},{"t":"방언 활동은 반 전체로만 해야 한다","mis":"K5-2-u3-X26"},{"t":"혼자 하면 방언을 쓰면 안 된다","mis":"K5-2-u3-X14"},{"t":"노랫말은 방언 활동이 될 수 없다","mis":"K5-2-u3-X26"}],"explanation":["여러 방식이 있어요.","관계없어요.","노랫말도 방언 작품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#8','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C27',4,'essay','teacher','우리 반 방언 지도를 만든다고 할 때 정할 주제와 조사할 지역, 그 지역을 고른 까닭을 쓰고, 지도에 붙일 카드 한 장의 내용을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C27","difficulty":4,"kind":"essay","stem":"우리 반 방언 지도를 만든다고 할 때 정할 주제와 조사할 지역, 그 지역을 고른 까닭을 쓰고, 지도에 붙일 카드 한 장의 내용을 쓰세요.","answer_guide":{"answer":"예: 주제는 음식, 조사할 지역은 경상 지역이다. 할머니 고향이라 궁금했기 때문이다. 카드 — 돔배기 · 경상 지역 · 소금에 절여 토막 낸 상어고기 · 동해에서 잡은 상어를 절여 두고 명절 상에 올리던 생활이 담겨 있다.","scoring_points":["주제와 지역을 정했는가","지역을 고른 까닭을 썼는가","카드에 방언 · 뜻 · 생활을 담았는가"]},"explanation":["주제와 지역이에요.","까닭을 써요.","카드에 생활까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#9','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C29',4,'essay','teacher','방언이 실감 나는 상황극 장면을 하나 정하고 방언을 넣은 대사를 한 줄 쓴 뒤, 연기할 때 조심할 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C29","difficulty":4,"kind":"essay","stem":"방언이 실감 나는 상황극 장면을 하나 정하고 방언을 넣은 대사를 한 줄 쓴 뒤, 연기할 때 조심할 점을 쓰세요.","answer_guide":{"answer":"예: 시골 할아버지와 통화하는 장면 — 「할아버지, 진지 잡수셨슈?」 연기할 때에는 말투를 과장해 웃음거리로 만들지 않고, 할아버지를 걱정하는 손주의 마음을 살려 정답게 말한다.","scoring_points":["장면을 정했는가","방언을 넣은 대사를 썼는가","흉내 내지 않는 태도를 썼는가"]},"explanation":["장면을 정해요.","대사를 써요.","마음을 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_L10_challenge#10','kor',5,2,'u3','L10','g5_2_kor_u3_L10_challenge','lesson_challenge','K5-2-u3-C9',4,'essay','teacher','방언 지도에서 같은 「짐치」가 여러 지역에 붙은 것을 보고 알 수 있는 점과, 지도를 만들며 새롭게 안 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"방언 지도에서 같은 「짐치」가 여러 지역에 붙은 것을 보고 알 수 있는 점과, 지도를 만들며 새롭게 안 점을 쓰세요.","answer_guide":{"answer":"예: 「짐치」가 강원 · 경상 · 전라 지역에 함께 붙은 것을 보니 방언이 지역 경계에 딱 맞추어 나뉘지 않고 여러 지역에 퍼져 쓰인다는 것을 알 수 있다. 지도를 만들며 같은 김치도 「짐끼」처럼 여러 이름이 있다는 것을 새롭게 알았다.","scoring_points":["여러 지역에 퍼져 쓰임을 썼는가","지도를 만들며 새롭게 안 점을 썼는가","근거가 지도에서 나왔는가"]},"explanation":["퍼져 쓰여요.","새롭게 안 점을 써요.","지도를 근거로 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#1','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C2',1,'mc','auto','어디서나 누구와도 뜻이 통하도록 우리나라 사람들이 공통으로 쓰기로 정한 말은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X29','K5-2-u3-X19']::text[],false,'{"seq":1,"concept":"K5-2-u3-C2","difficulty":1,"kind":"mc","stem":"어디서나 누구와도 뜻이 통하도록 우리나라 사람들이 공통으로 쓰기로 정한 말은 어느 것인가요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X03"},{"t":"흉내 말","mis":"K5-2-u3-X29"},{"t":"옛말","mis":"K5-2-u3-X19"}],"explanation":["지역의 말이에요.","흉내는 말이 아니에요.","함께 쓰도록 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#2','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C32',1,'mc','auto','글자 모양은 같지만 뜻이 다른 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"mc","stem":"글자 모양은 같지만 뜻이 다른 말을 무엇이라고 하나요?","options":[{"t":"동형어","correct":true},{"t":"방언","mis":"K5-2-u3-X32"},{"t":"표준어","mis":"K5-2-u3-X32"},{"t":"높임말","mis":"K5-2-u3-X32"}],"explanation":["지역의 말이에요.","함께 쓰도록 정한 말이에요.","모양이 같고 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#3','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C5',1,'mc','auto','옛날에 방언이 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":3,"concept":"K5-2-u3-C5","difficulty":1,"kind":"mc","stem":"옛날에 방언이 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"산과 강 때문에 지역 사이를 오가기 어려워서","correct":true},{"t":"사람들이 표준어를 싫어해서","mis":"K5-2-u3-X05"},{"t":"지역마다 글자가 달라서","mis":"K5-2-u3-X05"},{"t":"방송이 방언을 가르쳐서","mis":"K5-2-u3-X05"}],"explanation":["싫어해서가 아니에요.","글자는 같아요.","지리적 특성 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#4','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',1,'mc','auto','상황 카드 ㉯ 「여러 지역 소식을 전하는 뉴스」에 가장 어울리는 말은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X31']::text[],false,'{"seq":4,"concept":"K5-2-u3-C31","difficulty":1,"kind":"mc","stem":"상황 카드 ㉯ 「여러 지역 소식을 전하는 뉴스」에 가장 어울리는 말은 어느 것인가요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X13"},{"t":"줄임말","mis":"K5-2-u3-X31"},{"t":"외국어","mis":"K5-2-u3-X31"}],"explanation":["여러 지역 사람이 봐요.","알맞지 않아요.","모두가 알아듣는 말이에요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#5','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C9',1,'mc','auto','「고냉이」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「고냉이」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"고양이","correct":true},{"t":"개구리","mis":"K5-2-u3-X10"},{"t":"거위","mis":"K5-2-u3-X10"},{"t":"고래","mis":"K5-2-u3-X10"}],"explanation":["까구리 · 깨고락지예요.","관계없어요.","고냉이는 고양이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#6','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C17',1,'mc','auto','제주 지역 마을에서 이웃 어른을 가족처럼 부르는 방언은 어느 것인가요?',ARRAY['K5-2-u3-X17']::text[],false,'{"seq":6,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"제주 지역 마을에서 이웃 어른을 가족처럼 부르는 방언은 어느 것인가요?","options":[{"t":"삼춘","correct":true},{"t":"올레","mis":"K5-2-u3-X17"},{"t":"정낭","mis":"K5-2-u3-X17"},{"t":"물허벅","mis":"K5-2-u3-X17"}],"explanation":["좁은 길이에요.","대문 가로대예요.","마을 어른을 불러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#7','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C12',1,'ox','auto','같은 사람도 듣는 사람과 자리에 따라 표준어와 방언을 골라 쓸 수 있어요.',ARRAY['K5-2-u3-X12']::text[],false,'{"seq":7,"concept":"K5-2-u3-C12","difficulty":1,"kind":"ox","stem":"같은 사람도 듣는 사람과 자리에 따라 표준어와 방언을 골라 쓸 수 있어요.","answer":"O","reason_options":[{"t":"말을 고르는 기준은 누구에게, 어떤 자리에서 말하느냐이기 때문에","correct":true},{"t":"한 사람은 한 가지 말만 써야 하기 때문에","mis":"K5-2-u3-X12"}],"mis":"K5-2-u3-X12","explanation":["자리에 따라 골라요.","듣는 사람이 기준이에요.","골라 쓸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#8','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C21',1,'mc','auto','「감 따는 날」에서 마을 정자에 모여 하준이에게 말을 건 사람은 누구인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":8,"concept":"K5-2-u3-C21","difficulty":1,"kind":"mc","stem":"「감 따는 날」에서 마을 정자에 모여 하준이에게 말을 건 사람은 누구인가요?","options":[{"t":"할머니들","correct":true},{"t":"하준이 친구들","mis":"K5-2-u3-X21"},{"t":"선생님들","mis":"K5-2-u3-X21"},{"t":"관광객들","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","둘째 줄에 나와요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#9','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C9',2,'mc','auto','「우리 집 말 조사 일지」에서 외할머니가 쓰시는 방언 「할망」의 표준어는 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":9,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 집 말 조사 일지」에서 외할머니가 쓰시는 방언 「할망」의 표준어는 어느 것인가요?","options":[{"t":"할머니","correct":true},{"t":"할아버지","mis":"K5-2-u3-X10"},{"t":"아주머니","mis":"K5-2-u3-X10"},{"t":"어머니","mis":"K5-2-u3-X10"}],"explanation":["다른 분이에요.","다른 분이에요.","할망은 할머니예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#10','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C8',2,'mc','auto','방언이 표준어가 된 예와 그 까닭을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X08']::text[],false,'{"seq":10,"concept":"K5-2-u3-C8","difficulty":2,"kind":"mc","stem":"방언이 표준어가 된 예와 그 까닭을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"멍게 — 표준어보다 더 널리 쓰이게 되어서","correct":true},{"t":"멍게 — 국립국어원이 아무렇게나 골라서","mis":"K5-2-u3-X07"},{"t":"개구리 — 원래 제주 지역 방언이라서","mis":"K5-2-u3-X08"},{"t":"정구지 — 글자 수가 적어서","mis":"K5-2-u3-X07"}],"explanation":["기준을 살펴 정해요.","개구리는 원래 표준어예요.","널리 쓰인 것이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#11','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',2,'mc','auto','상황 카드 네 장에 어울리는 말을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X31','K5-2-u3-X30']::text[],false,'{"seq":11,"concept":"K5-2-u3-C31","difficulty":2,"kind":"mc","stem":"상황 카드 네 장에 어울리는 말을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉮ 방언 · ㉯ 표준어 · ㉰ 표준어 · ㉱ 방언","correct":true},{"t":"㉮ 표준어 · ㉯ 방언 · ㉰ 방언 · ㉱ 표준어","mis":"K5-2-u3-X31"},{"t":"㉮ ㉯ ㉰ ㉱ 모두 표준어","mis":"K5-2-u3-X30"},{"t":"㉮ ㉯ ㉰ ㉱ 모두 방언","mis":"K5-2-u3-X30"}],"explanation":["거꾸로예요.","자리마다 달라요.","듣는 사람과 목적을 봐요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#12','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C19',2,'mc','auto','방언의 가치를 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X07','K5-2-u3-X19']::text[],false,'{"seq":12,"concept":"K5-2-u3-C19","difficulty":2,"kind":"mc","stem":"방언의 가치를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지역의 자연과 생활, 사람들의 정을 담아 지역의 문화를 지킨다","correct":true},{"t":"다른 지역과 말이 통하지 않게 막아 준다","mis":"K5-2-u3-X20"},{"t":"표준어보다 글자 수가 적다","mis":"K5-2-u3-X07"},{"t":"쓸모없는 옛말이라 곧 사라져도 된다","mis":"K5-2-u3-X19"}],"explanation":["막는 말이 아니에요.","관계없어요.","문화를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#13','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C22',2,'mc','auto','「하얗겄제」처럼 뜻을 모르는 방언 끝말이 나왔을 때 앞뒤 장면으로 짐작하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X22','K5-2-u3-X10']::text[],false,'{"seq":13,"concept":"K5-2-u3-C22","difficulty":2,"kind":"mc","stem":"「하얗겄제」처럼 뜻을 모르는 방언 끝말이 나왔을 때 앞뒤 장면으로 짐작하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"서울에서 왔다는 말을 듣고 한 말이니 「하얗겠지」로 짐작한다","correct":true},{"t":"뜻을 모르니 그 문장은 빼고 읽는다","mis":"K5-2-u3-X22"},{"t":"아무 뜻이 없는 소리라고 여긴다","mis":"K5-2-u3-X22"},{"t":"처음 떠오른 뜻을 확인 없이 정답으로 정한다","mis":"K5-2-u3-X10"}],"explanation":["놓치는 것이 생겨요.","뜻이 있어요.","앞뒤 장면이 근거예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#14','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C27',2,'mc','auto','방언 지도를 만들 때 조사하기 바로 앞에 하는 일은 어느 것인가요?',ARRAY['K5-2-u3-X27']::text[],false,'{"seq":14,"concept":"K5-2-u3-C27","difficulty":2,"kind":"mc","stem":"방언 지도를 만들 때 조사하기 바로 앞에 하는 일은 어느 것인가요?","options":[{"t":"모둠마다 조사할 지역 나누기","correct":true},{"t":"지도에 카드 붙이기","mis":"K5-2-u3-X27"},{"t":"둘러보며 이야기 나누기","mis":"K5-2-u3-X27"},{"t":"상장 나누어 주기","mis":"K5-2-u3-X27"}],"explanation":["맨 끝이에요.","맨 끝이에요.","지역을 나누고 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#15','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C16',2,'mc','auto','표준어와 방언 사용 상황을 조사할 때 살펴볼 세 가지로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X16','K5-2-u3-X15']::text[],false,'{"seq":15,"concept":"K5-2-u3-C16","difficulty":2,"kind":"mc","stem":"표준어와 방언 사용 상황을 조사할 때 살펴볼 세 가지로 알맞은 것은 어느 것인가요?","options":[{"t":"누구에게 · 어떤 상황에서 · 어떤 사이","correct":true},{"t":"언제 태어났는지 · 키 · 몸무게","mis":"K5-2-u3-X16"},{"t":"목소리 크기 · 말 빠르기 · 날씨","mis":"K5-2-u3-X16"},{"t":"글자 수 · 맞춤법 · 띄어쓰기","mis":"K5-2-u3-X15"}],"explanation":["관계없어요.","관계없어요.","듣는 사람 · 자리 · 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#16','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C32',2,'mc','auto','「장수」가 「군사를 거느리는 우두머리」의 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"「장수」가 「군사를 거느리는 우두머리」의 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"장수가 군사들을 이끌고 앞으로 나아갔다.","correct":true},{"t":"과일 장수에게서 사과를 샀다.","mis":"K5-2-u3-X32"},{"t":"거북은 장수하는 동물로 알려져 있다.","mis":"K5-2-u3-X32"},{"t":"시장의 생선 장수가 크게 외쳤다.","mis":"K5-2-u3-X32"}],"explanation":["장사하는 사람이에요.","오래도록 사는 것이에요.","군사를 이끌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#17','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C30',3,'mc','auto','「우리 집 말 조사 일지」 글쓴이의 생각과 가장 가까운 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X30']::text[],false,'{"seq":17,"concept":"K5-2-u3-C30","difficulty":3,"kind":"mc","stem":"「우리 집 말 조사 일지」 글쓴이의 생각과 가장 가까운 것은 어느 것인가요?","options":[{"t":"가족의 방언은 신기하고 소중하며, 여럿이 듣는 발표에서는 표준어로 바꾸되 뜻과 함께 소개한다","correct":true},{"t":"가족의 방언은 틀린 말이니 쓰지 않게 해야 한다","mis":"K5-2-u3-X01"},{"t":"방언만 소중하니 발표도 방언으로만 한다","mis":"K5-2-u3-X30"},{"t":"표준어만 소중하니 방언은 조사할 필요가 없다","mis":"K5-2-u3-X30"}],"explanation":["틀린 말이 아니에요.","듣는 친구들을 생각해요.","둘 다 살려요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#18','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',3,'mc','auto','표준어를 주로 쓰는 경기 지역 마을이 축제 홍보 문구를 정할 때 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X31']::text[],false,'{"seq":18,"concept":"K5-2-u3-C31","difficulty":3,"kind":"mc","stem":"표준어를 주로 쓰는 경기 지역 마을이 축제 홍보 문구를 정할 때 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"그 지역에서 실제로 쓰는 말이 표준어라면 표준어로 지역의 정서를 보여 줄 수도 있다","correct":true},{"t":"축제니까 무조건 방언을 써야 한다","mis":"K5-2-u3-X31"},{"t":"다른 지역 방언을 빌려 써야 한다","mis":"K5-2-u3-X31"},{"t":"홍보 문구에는 아무 말도 쓰지 않는다","mis":"K5-2-u3-X31"}],"explanation":["외워서 고르지 않아요.","그 지역의 말이 아니에요.","목적과 실제 쓰는 말이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#19','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C24',3,'mc','auto','「감 따는 날」의 할머니들 대사를 모두 표준어로 바꾼다면 가장 크게 달라지는 것은 어느 것인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":19,"concept":"K5-2-u3-C24","difficulty":3,"kind":"mc","stem":"「감 따는 날」의 할머니들 대사를 모두 표준어로 바꾼다면 가장 크게 달라지는 것은 어느 것인가요?","options":[{"t":"남쪽 바닷가 마을의 분위기와 할머니들의 정다운 목소리","correct":true},{"t":"하준이가 감을 딴 일","mis":"K5-2-u3-X21"},{"t":"이야기의 계절","mis":"K5-2-u3-X21"},{"t":"등장인물의 수","mis":"K5-2-u3-X21"}],"explanation":["줄거리는 같아요.","그대로예요.","분위기와 목소리가 달라져요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#20','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C18',3,'mc','auto','강원 지역의 「감재옹심이」와 전라 지역의 「뻘」에 공통으로 담긴 것은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X29','K5-2-u3-X17']::text[],false,'{"seq":20,"concept":"K5-2-u3-C18","difficulty":3,"kind":"mc","stem":"강원 지역의 「감재옹심이」와 전라 지역의 「뻘」에 공통으로 담긴 것은 어느 것인가요?","options":[{"t":"그 지역의 자연환경과 생활 모습","correct":true},{"t":"표준어를 정하는 기준","mis":"K5-2-u3-X07"},{"t":"웃음거리가 되는 말투","mis":"K5-2-u3-X29"},{"t":"아무 뜻 없는 소리","mis":"K5-2-u3-X17"}],"explanation":["관계없어요.","존중해야 해요.","자연과 생활이 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#21','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C29',3,'mc','auto','방언 지도를 둘러보다 낯선 방언이 나왔을 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X11','K5-2-u3-X19']::text[],false,'{"seq":21,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언 지도를 둘러보다 낯선 방언이 나왔을 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"어떤 생활과 이어지는 말인지 궁금해하며 묻는다","correct":true},{"t":"이상한 말이라며 웃는다","mis":"K5-2-u3-X29"},{"t":"틀린 카드라고 떼어 낸다","mis":"K5-2-u3-X11"},{"t":"못 본 척 지나간다","mis":"K5-2-u3-X19"}],"explanation":["웃음거리로 삼지 않아요.","틀린 것이 아니에요.","궁금한 마음으로 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#22','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C30',3,'mc','auto','표준어와 방언의 관계를 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u3-X30']::text[],false,'{"seq":22,"concept":"K5-2-u3-C30","difficulty":3,"kind":"mc","stem":"표준어와 방언의 관계를 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"서로 겨루는 말이 아니라 함께 어우러지는 우리말이다","correct":true},{"t":"표준어가 방언을 대신해야 한다","mis":"K5-2-u3-X30"},{"t":"방언이 표준어보다 늘 낫다","mis":"K5-2-u3-X30"},{"t":"둘 가운데 하나는 없어져야 한다","mis":"K5-2-u3-X30"}],"explanation":["둘 다 필요해요.","늘 나은 말은 없어요.","함께 어우러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#23','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C31',4,'essay','teacher','상황 카드 ㉮~㉱에서 각각 표준어와 방언 가운데 어울리는 말을 고르고, 그렇게 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C31","difficulty":4,"kind":"essay","stem":"상황 카드 ㉮~㉱에서 각각 표준어와 방언 가운데 어울리는 말을 고르고, 그렇게 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉮는 방언 — 어릴 적부터 함께 쓰던 말로 마음을 나누기 때문이다. ㉯는 표준어 — 여러 지역 사람들이 보기 때문이다. ㉰는 표준어 — 여러 지역 사람들이 서로 잘 이해해야 하기 때문이다. ㉱는 방언 — 지역의 정서와 특성을 보여 주어야 하기 때문이다(표준어를 쓰는 지역이라면 표준어도 답이 된다).","scoring_points":["네 상황에 어울리는 말을 골랐는가","상황마다 까닭을 썼는가","까닭이 듣는 사람이나 목적과 이어지는가"]},"explanation":["네 장을 모두 골라요.","까닭을 써요.","듣는 사람과 목적이 근거예요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#24','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C19',4,'essay','teacher','우리 가족이나 이웃이 쓰는 말 가운데 지키고 싶은 말을 하나 골라, 그 말에 담긴 생활이나 마음과 지키고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C19","difficulty":4,"kind":"essay","stem":"우리 가족이나 이웃이 쓰는 말 가운데 지키고 싶은 말을 하나 골라, 그 말에 담긴 생활이나 마음과 지키고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 할머니께서 나를 부르실 때 쓰시는 「아야」를 지키고 싶다. 이 말에는 손주를 아끼시는 할머니의 마음과 고향 마을의 정이 담겨 있다. 이 말이 사라지면 할머니와의 추억과 고향 이야기도 함께 잊힐 것 같아 지키고 싶다.","scoring_points":["지키고 싶은 말을 골랐는가","담긴 생활이나 마음을 썼는가","지키고 싶은 까닭을 썼는가"]},"explanation":["말을 골라요.","담긴 것을 써요.","까닭을 써요. 표준어 표현이어도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_a#25','kor',5,2,'u3','','g5_2_kor_u3_review_a','unit_review','K5-2-u3-C28',4,'essay','teacher','우리 반 방언 지도에 붙일 카드 한 장을 써 보세요. 방언, 쓰는 지역, 뜻, 이어지는 생활을 모두 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C28","difficulty":4,"kind":"essay","stem":"우리 반 방언 지도에 붙일 카드 한 장을 써 보세요. 방언, 쓰는 지역, 뜻, 이어지는 생활을 모두 넣으세요.","answer_guide":{"answer":"예: 방언 — 뻘, 쓰는 지역 — 전라 지역, 뜻 — 갯벌, 이어지는 생활 — 서해안에 넓게 펼쳐진 갯벌에서 조개를 캐고 물고기를 잡으며 살아온 마을 사람들의 생활이 담겨 있다.","scoring_points":["방언과 쓰는 지역을 썼는가","뜻을 썼는가","이어지는 생활을 썼는가"]},"explanation":["방언과 지역이에요.","뜻이에요.","생활까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#1','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C3',1,'mc','auto','특정 지역에서 주로 쓰고 그 지역의 생활과 정을 담은, 표준어가 아닌 말은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":1,"concept":"K5-2-u3-C3","difficulty":1,"kind":"mc","stem":"특정 지역에서 주로 쓰고 그 지역의 생활과 정을 담은, 표준어가 아닌 말은 어느 것인가요?","options":[{"t":"방언","correct":true},{"t":"표준어","mis":"K5-2-u3-X03"},{"t":"외래어","mis":"K5-2-u3-X01"},{"t":"줄임말","mis":"K5-2-u3-X01"}],"explanation":["함께 쓰도록 정한 말이에요.","다른 나라에서 온 말이에요.","지역의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#2','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C32',1,'mc','auto','「하늘에서 하얀 눈이 내린다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"mc","stem":"「하늘에서 하얀 눈이 내린다.」의 「눈」과 같은 뜻으로 쓰인 것은 어느 것인가요?","options":[{"t":"밤새 눈이 소복이 쌓였다.","correct":true},{"t":"눈을 감고 소원을 빌었다.","mis":"K5-2-u3-X32"},{"t":"눈이 나빠 안경을 썼다.","mis":"K5-2-u3-X32"},{"t":"눈으로 글자를 따라 읽었다.","mis":"K5-2-u3-X32"}],"explanation":["보는 눈이에요.","보는 눈이에요.","하늘에서 내리는 눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#3','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C6',1,'mc','auto','지역마다 말이 다르면 생기는 어려움을 덜려고 정한 말은 어느 것인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X32','K5-2-u3-X29']::text[],false,'{"seq":3,"concept":"K5-2-u3-C6","difficulty":1,"kind":"mc","stem":"지역마다 말이 다르면 생기는 어려움을 덜려고 정한 말은 어느 것인가요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X06"},{"t":"동형어","mis":"K5-2-u3-X32"},{"t":"흉내 말","mis":"K5-2-u3-X29"}],"explanation":["방언은 지역의 말이에요.","모양이 같은 말이에요.","함께 알아듣게 정한 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#4','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C31',1,'mc','auto','상황 카드 ㉮ 「고향 친구와 오랜만에 만나 이야기할 때」에 어울리기도 하는 말은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X31']::text[],false,'{"seq":4,"concept":"K5-2-u3-C31","difficulty":1,"kind":"mc","stem":"상황 카드 ㉮ 「고향 친구와 오랜만에 만나 이야기할 때」에 어울리기도 하는 말은 어느 것인가요?","options":[{"t":"방언","correct":true},{"t":"표준어만 써야 한다","mis":"K5-2-u3-X14"},{"t":"외국어","mis":"K5-2-u3-X31"},{"t":"아무 말도 하지 않는다","mis":"K5-2-u3-X31"}],"explanation":["방언도 어울려요.","알맞지 않아요.","어릴 적 함께 쓰던 말이에요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#5','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C9',1,'mc','auto','「정구지」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「정구지」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"부추","correct":true},{"t":"가위","mis":"K5-2-u3-X10"},{"t":"나무","mis":"K5-2-u3-X10"},{"t":"김치","mis":"K5-2-u3-X10"}],"explanation":["가새기예요.","낭구예요.","정구지는 부추예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#6','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C18',1,'mc','auto','「돔배기」는 무엇을 가리키는 방언인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C18","difficulty":1,"kind":"mc","stem":"「돔배기」는 무엇을 가리키는 방언인가요?","options":[{"t":"소금에 절여 토막 낸 상어고기","correct":true},{"t":"갯벌","mis":"K5-2-u3-X10"},{"t":"감자를 갈아 빚은 음식","mis":"K5-2-u3-X10"},{"t":"집과 집 사이 좁은 길","mis":"K5-2-u3-X10"}],"explanation":["뻘이에요.","감재옹심이예요.","경상 지역 먹을거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#7','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C15',1,'ox','auto','방언을 표준어로 바꾸어 보는 것은 틀린 방언을 고치는 일이에요.',ARRAY['K5-2-u3-X15']::text[],false,'{"seq":7,"concept":"K5-2-u3-C15","difficulty":1,"kind":"ox","stem":"방언을 표준어로 바꾸어 보는 것은 틀린 방언을 고치는 일이에요.","answer":"X","reason_options":[{"t":"상황에 따라 말이 달리 쓰인다는 것을 알기 위한 것이기 때문에","correct":true},{"t":"방언은 고쳐야 할 말이기 때문에","mis":"K5-2-u3-X15"}],"mis":"K5-2-u3-X15","explanation":["고치기가 아니에요.","선택을 알아요.","방언은 틀린 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#8','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C24',1,'mc','auto','이야기에 방언을 쓸 때 잘 살아나는 것은 어느 것인가요?',ARRAY['K5-2-u3-X24']::text[],false,'{"seq":8,"concept":"K5-2-u3-C24","difficulty":1,"kind":"mc","stem":"이야기에 방언을 쓸 때 잘 살아나는 것은 어느 것인가요?","options":[{"t":"인물 사이의 정과 마을 분위기","correct":true},{"t":"글자의 크기","mis":"K5-2-u3-X24"},{"t":"책의 쪽수","mis":"K5-2-u3-X24"},{"t":"표지의 색깔","mis":"K5-2-u3-X24"}],"explanation":["관계없어요.","관계없어요.","정과 분위기가 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#9','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C9',2,'mc','auto','「우리 집 말 조사 일지」의 「낭구」는 무엇을 가리키나요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":9,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 집 말 조사 일지」의 「낭구」는 무엇을 가리키나요?","options":[{"t":"나무","correct":true},{"t":"나물","mis":"K5-2-u3-X10"},{"t":"낫","mis":"K5-2-u3-X10"},{"t":"냇물","mis":"K5-2-u3-X10"}],"explanation":["뒷산에 빽빽한 것이에요.","도구가 아니에요.","낭구는 나무예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#10','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C7',2,'mc','auto','다음 가운데 표준어를 정하는 기준이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":10,"concept":"K5-2-u3-C7","difficulty":2,"kind":"mc","stem":"다음 가운데 표준어를 정하는 기준이 아닌 것은 어느 것인가요?","options":[{"t":"말하는 사람이 서울에 사는지","correct":true},{"t":"사람들이 두루 쓰는지","mis":"K5-2-u3-X07"},{"t":"문법에 맞는지","mis":"K5-2-u3-X07"},{"t":"발음하기 자연스러운지","mis":"K5-2-u3-X07"}],"explanation":["기준이에요.","기준이에요.","사는 곳은 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#11','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C31',2,'error','auto','상황 카드를 고른 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X31','K5-2-u3-X13','K5-2-u3-X14']::text[],false,'{"seq":11,"concept":"K5-2-u3-C31","difficulty":2,"kind":"error","stem":"상황 카드를 고른 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「까닭은 생각하지 않고 느낌대로 아무 말이나 고르면 돼.」","correct":true,"mis_target":"K5-2-u3-X31"},{"t":"「㉰는 여러 지역 사람이 서로 잘 알아들어야 하니 표준어야.」","mis":"K5-2-u3-X13"},{"t":"「㉮는 어릴 적부터 쓰던 말로 마음을 나누니 방언이야.」","mis":"K5-2-u3-X14"}],"explanation":["까닭이 있어요.","까닭이 있어요.","까닭과 함께 골라요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#12','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C19',2,'ox','auto','방언에는 우리말의 옛 모습이 간직되어 있어요.',ARRAY['K5-2-u3-X19']::text[],false,'{"seq":12,"concept":"K5-2-u3-C19","difficulty":2,"kind":"ox","stem":"방언에는 우리말의 옛 모습이 간직되어 있어요.","answer":"O","reason_options":[{"t":"지역의 삶과 함께 오랫동안 이어져 온 말이기 때문에","correct":true},{"t":"방언은 요즘 새로 만든 말이기 때문에","mis":"K5-2-u3-X19"}],"mis":"K5-2-u3-X19","explanation":["오래된 말이에요.","옛 모습이 남아요.","가치가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#13','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C23',2,'mc','auto','방언 문장과 표준어 문장을 견주어 읽을 때 살펴볼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X23','K5-2-u3-X24']::text[],false,'{"seq":13,"concept":"K5-2-u3-C23","difficulty":2,"kind":"mc","stem":"방언 문장과 표준어 문장을 견주어 읽을 때 살펴볼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 쪽에서 인물의 목소리와 마음이 더 생생한지","correct":true},{"t":"어느 쪽이 맞춤법에 맞는지만","mis":"K5-2-u3-X15"},{"t":"어느 쪽 글자 수가 많은지","mis":"K5-2-u3-X23"},{"t":"어느 쪽이 더 빨리 읽히는지만","mis":"K5-2-u3-X24"}],"explanation":["고치기가 아니에요.","관계없어요.","느낌을 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#14','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C28',2,'mc','auto','좋은 방언 지도의 조건으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28']::text[],false,'{"seq":14,"concept":"K5-2-u3-C28","difficulty":2,"kind":"mc","stem":"좋은 방언 지도의 조건으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언과 뜻, 그 말과 이어지는 생활이 함께 드러난다","correct":true},{"t":"방언 개수가 가장 많다","mis":"K5-2-u3-X28"},{"t":"그림이 가장 화려하다","mis":"K5-2-u3-X28"},{"t":"지역 이름이 없어도 된다","mis":"K5-2-u3-X28"}],"explanation":["개수보다 생활이에요.","꾸미기보다 내용이에요.","뜻과 생활이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#15','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C10',2,'mc','auto','방언을 온라인 사전으로 찾는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11']::text[],false,'{"seq":15,"concept":"K5-2-u3-C10","difficulty":2,"kind":"mc","stem":"방언을 온라인 사전으로 찾는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"국립국어원 지역어 누리집에서 표준어 낱말을 검색해 지역별 방언과 발음을 확인한다","correct":true},{"t":"짐작한 말을 적고 확인하지 않는다","mis":"K5-2-u3-X10"},{"t":"한 사람에게만 물어 정답으로 정한다","mis":"K5-2-u3-X11"},{"t":"외국어 사전에서 찾는다","mis":"K5-2-u3-X10"}],"explanation":["근거가 없어요.","정답은 하나가 아니에요.","지역어 누리집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#16','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C32',2,'mc','auto','「쓰다」가 「맛이 쓰다」의 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"「쓰다」가 「맛이 쓰다」의 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"약이 너무 써서 얼굴을 찡그렸다.","correct":true},{"t":"공책에 일기를 썼다.","mis":"K5-2-u3-X32"},{"t":"햇볕이 뜨거워 모자를 썼다.","mis":"K5-2-u3-X32"},{"t":"붓으로 이름을 썼다.","mis":"K5-2-u3-X32"}],"explanation":["글을 쓰다예요.","모자를 쓰다예요.","맛이 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#17','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C9',3,'mc','auto','「우리 집 말 조사 일지」를 읽고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X03']::text[],false,'{"seq":17,"concept":"K5-2-u3-C9","difficulty":3,"kind":"mc","stem":"「우리 집 말 조사 일지」를 읽고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 우리말이라도 지역마다 부르는 이름이 여러 가지이다","correct":true},{"t":"가족끼리는 모두 같은 말을 쓴다","mis":"K5-2-u3-X09"},{"t":"방언은 할머니만 쓰는 말이다","mis":"K5-2-u3-X03"},{"t":"표준어는 강원 지역 말이다","mis":"K5-2-u3-X03"}],"explanation":["가족마다 달라요.","고모 · 큰아버지도 써요.","부르는 이름이 여러 가지예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#18','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C13',3,'mc','auto','전국 어린이 회의가 끝난 뒤 쉬는 시간에 자기 고장 말로 인사를 나누는 모습에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X12','K5-2-u3-X14','K5-2-u3-X30']::text[],false,'{"seq":18,"concept":"K5-2-u3-C13","difficulty":3,"kind":"mc","stem":"전국 어린이 회의가 끝난 뒤 쉬는 시간에 자기 고장 말로 인사를 나누는 모습에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공식적인 회의와 쉬는 시간처럼 자리에 따라 어울리는 말을 고른다","correct":true},{"t":"회의에서 표준어를 쓴 것은 잘못이다","mis":"K5-2-u3-X12"},{"t":"쉬는 시간에도 표준어만 써야 한다","mis":"K5-2-u3-X14"},{"t":"고장 말로 인사하면 회의를 망친다","mis":"K5-2-u3-X30"}],"explanation":["회의에는 표준어가 알맞아요.","쉬는 시간엔 정을 나눠요.","자리에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#19','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C25',3,'mc','auto','「감 따는 날」을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X25','K5-2-u3-X29']::text[],false,'{"seq":19,"concept":"K5-2-u3-C25","difficulty":3,"kind":"mc","stem":"「감 따는 날」을 내 삶과 이어 감상한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「처음 간 친척 집에서 낯선 말이 어색했지만 반겨 주셔서 금방 정이 들었던 기억이 떠올랐어.」","correct":true},{"t":"「감나무는 가을에 열매가 익어.」","mis":"K5-2-u3-X25"},{"t":"「할머니들 말투가 웃기니까 따라 해 봐야지.」","mis":"K5-2-u3-X29"},{"t":"「줄거리만 알면 됐지 내 이야기는 필요 없어.」","mis":"K5-2-u3-X25"}],"explanation":["작품과 내 삶이 이어지지 않아요.","흉내는 예의가 아니에요.","하준이 마음과 내 경험을 이었어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#20','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C20',3,'mc','auto','방언이 사라지면 함께 잊힐 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X32']::text[],false,'{"seq":20,"concept":"K5-2-u3-C20","difficulty":3,"kind":"mc","stem":"방언이 사라지면 함께 잊힐 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 말에 담긴 지역의 생활과 이야기","correct":true},{"t":"표준어","mis":"K5-2-u3-X20"},{"t":"국립국어원","mis":"K5-2-u3-X20"},{"t":"동형어","mis":"K5-2-u3-X32"}],"explanation":["그대로 남아요.","그대로 남아요.","관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#21','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C11',3,'mc','auto','두 모둠이 「짐치」를 각각 경상 지역과 강원 지역에 붙였을 때 지도에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X11','K5-2-u3-X03','K5-2-u3-X09']::text[],false,'{"seq":21,"concept":"K5-2-u3-C11","difficulty":3,"kind":"mc","stem":"두 모둠이 「짐치」를 각각 경상 지역과 강원 지역에 붙였을 때 지도에서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 방언이 여러 지역에 퍼져 쓰이는 모습","correct":true},{"t":"한 모둠이 틀렸다는 것","mis":"K5-2-u3-X11"},{"t":"짐치는 표준어라는 것","mis":"K5-2-u3-X03"},{"t":"두 지역의 김치는 다른 음식이라는 것","mis":"K5-2-u3-X09"}],"explanation":["둘 다 맞아요.","방언이에요.","퍼져 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#22','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C4',3,'mc','auto','이 단원에서 배운 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X04']::text[],false,'{"seq":22,"concept":"K5-2-u3-C4","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻 알기 → 사용 상황 조사 → 방언의 가치 → 작품 감상 → 방언 지도","correct":true},{"t":"작품 감상 → 뜻 알기 → 방언 지도 → 사용 상황 조사 → 방언의 가치","mis":"K5-2-u3-X04"},{"t":"방언 지도 → 방언의 가치 → 뜻 알기 → 작품 감상 → 사용 상황 조사","mis":"K5-2-u3-X04"},{"t":"사용 상황 조사 → 방언 지도 → 작품 감상 → 뜻 알기 → 방언의 가치","mis":"K5-2-u3-X04"}],"explanation":["뜻이 먼저예요.","방언 지도는 끝이에요.","단원의 흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#23','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C30',4,'essay','teacher','표준어와 방언을 모두 소중히 여겨야 하는 까닭을 발표문 두세 문장으로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C30","difficulty":4,"kind":"essay","stem":"표준어와 방언을 모두 소중히 여겨야 하는 까닭을 발표문 두세 문장으로 쓰세요.","answer_guide":{"answer":"예: 여러분, 표준어는 어느 지역 사람과도 뜻이 통하게 해 줍니다. 방언은 지역의 자연과 생활, 사람들의 정을 담고 있습니다. 그래서 우리는 두 말을 상황에 맞게 아끼며 써야 합니다.","scoring_points":["표준어의 가치를 썼는가","방언의 가치를 썼는가","발표문 형식으로 두 말을 함께 아끼자고 정리했는가"]},"explanation":["표준어가 하는 일이에요.","방언이 하는 일이에요.","둘 다 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#24','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C25',4,'essay','teacher','방언이 나오는 이야기나 영상을 보았거나 방언을 들었던 경험을 떠올려, 그때의 느낌과 방언이 한 역할을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C25","difficulty":4,"kind":"essay","stem":"방언이 나오는 이야기나 영상을 보았거나 방언을 들었던 경험을 떠올려, 그때의 느낌과 방언이 한 역할을 쓰세요.","answer_guide":{"answer":"예: 명절에 큰집에 갔을 때 큰아버지께서 고향 말로 반겨 주셨다. 처음에는 낯설었지만 웃음이 섞인 말투에 마음이 금방 편해졌다. 방언이 오랜만에 만난 가족 사이를 더 가깝게 이어 주는 역할을 했다.","scoring_points":["경험을 떠올려 썼는가","그때의 느낌을 썼는가","방언이 한 역할을 썼는가"]},"explanation":["경험을 써요.","느낌을 써요.","역할을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_b#25','kor',5,2,'u3','','g5_2_kor_u3_review_b','unit_review','K5-2-u3-C24',4,'essay','teacher','「감 따는 날」의 한 장면을 골라 방언 대사와 표준어 대사를 견주고, 작품에 방언을 쓴 효과를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C24","difficulty":4,"kind":"essay","stem":"「감 따는 날」의 한 장면을 골라 방언 대사와 표준어 대사를 견주고, 작품에 방언을 쓴 효과를 쓰세요.","answer_guide":{"answer":"예: 외할머니가 「아야, 싸게싸게 와서 바구니 잡아라잉.」 하고 부르는 장면을 표준어로 바꾸면 「얘야, 빨리빨리 와서 바구니 잡아라.」이다. 뜻은 같지만 방언 대사에서 손주를 부르는 외할머니의 다정한 목소리와 바닷가 마을 분위기가 더 생생하게 살아난다.","scoring_points":["장면을 골라 방언 대사를 썼는가","표준어 대사로 바꾸어 견주었는가","방언을 쓴 효과를 썼는가"]},"explanation":["대사를 골라요.","바꾸어 견주어요.","효과를 써요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#1','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C2',1,'ox','auto','표준어는 서울에 사는 사람만 쓰는 말이에요.',ARRAY['K5-2-u3-X03']::text[],false,'{"seq":1,"concept":"K5-2-u3-C2","difficulty":1,"kind":"ox","stem":"표준어는 서울에 사는 사람만 쓰는 말이에요.","answer":"X","reason_options":[{"t":"어느 지역 사람이든 함께 알아듣도록 정한 말이기 때문에","correct":true},{"t":"서울 말이 가장 고운 말이기 때문에","mis":"K5-2-u3-X03"}],"mis":"K5-2-u3-X03","explanation":["어디서나 써요.","함께 알아듣게 정했어요.","모두의 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#2','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C32',1,'blank','auto','「( ? )을 먹다.」 · 「( ? )이 난다.」 · 「( ? )을 매다.」의 빈칸에 공통으로 들어갈 말은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"blank","stem":"「( ? )을 먹다.」 · 「( ? )이 난다.」 · 「( ? )을 매다.」의 빈칸에 공통으로 들어갈 말은 어느 것인가요?","options":[{"t":"김","correct":true},{"t":"밥","mis":"K5-2-u3-X32"},{"t":"물","mis":"K5-2-u3-X32"},{"t":"끈","mis":"K5-2-u3-X32"}],"explanation":["밥은 나지 않아요.","물은 매지 않아요.","먹는 김 · 나는 김 · 매는 김이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#3','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C7',1,'mc','auto','표준어를 정할 때 사람들이 두루 쓰는지, 문법에 맞는지 등을 살피는 곳은 어디인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":3,"concept":"K5-2-u3-C7","difficulty":1,"kind":"mc","stem":"표준어를 정할 때 사람들이 두루 쓰는지, 문법에 맞는지 등을 살피는 곳은 어디인가요?","options":[{"t":"국립국어원","correct":true},{"t":"지역 신문사","mis":"K5-2-u3-X07"},{"t":"기차역","mis":"K5-2-u3-X07"},{"t":"동네 시장","mis":"K5-2-u3-X07"}],"explanation":["정하는 곳이 아니에요.","정하는 곳이 아니에요.","국립국어원이 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#4','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C13',1,'mc','auto','상황 카드 ㉰ 「전국 어린이 회의에서 발표할 때」 표준어를 쓰는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X03','K5-2-u3-X06']::text[],false,'{"seq":4,"concept":"K5-2-u3-C13","difficulty":1,"kind":"mc","stem":"상황 카드 ㉰ 「전국 어린이 회의에서 발표할 때」 표준어를 쓰는 까닭은 무엇인가요?","options":[{"t":"여러 지역 사람들이 서로 잘 알아들어야 해서","correct":true},{"t":"방언은 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"발표자가 서울 사람이라서","mis":"K5-2-u3-X03"},{"t":"표준어가 더 높은 말이라서","mis":"K5-2-u3-X06"}],"explanation":["틀린 말이 아니에요.","사는 곳과 관계없어요.","서로 알아들어야 해요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#5','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C22',1,'mc','auto','「감 따는 날」의 「그러니께」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X22']::text[],false,'{"seq":5,"concept":"K5-2-u3-C22","difficulty":1,"kind":"mc","stem":"「감 따는 날」의 「그러니께」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"그러니까","correct":true},{"t":"그런데","mis":"K5-2-u3-X22"},{"t":"그래도","mis":"K5-2-u3-X22"},{"t":"그러므로","mis":"K5-2-u3-X22"}],"explanation":["뜻이 달라요.","뜻이 달라요.","그러니께는 그러니까예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#6','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C17',1,'mc','auto','「물허벅」은 무엇을 가리키는 방언인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C17","difficulty":1,"kind":"mc","stem":"「물허벅」은 무엇을 가리키는 방언인가요?","options":[{"t":"물을 길어 나르던 동이","correct":true},{"t":"대문 가로대","mis":"K5-2-u3-X10"},{"t":"마을 어른","mis":"K5-2-u3-X10"},{"t":"좁은 돌담길","mis":"K5-2-u3-X10"}],"explanation":["정낭이에요.","삼춘이에요.","물동이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#7','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C14',1,'ox','auto','고향 사람끼리 방언을 쓰면 더 친근하고 정답게 이야기할 수 있어요.',ARRAY['K5-2-u3-X14']::text[],false,'{"seq":7,"concept":"K5-2-u3-C14","difficulty":1,"kind":"ox","stem":"고향 사람끼리 방언을 쓰면 더 친근하고 정답게 이야기할 수 있어요.","answer":"O","reason_options":[{"t":"어릴 때부터 함께 쓰던 말로 마음을 나누기 때문에","correct":true},{"t":"방언은 친한 사이에서도 쓰면 안 되기 때문에","mis":"K5-2-u3-X14"}],"mis":"K5-2-u3-X14","explanation":["정을 나눠요.","친근해요.","고향 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#8','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C21',1,'mc','auto','「감 따는 날」에서 외할머니가 하준이에게 시킨 일은 무엇인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":8,"concept":"K5-2-u3-C21","difficulty":1,"kind":"mc","stem":"「감 따는 날」에서 외할머니가 하준이에게 시킨 일은 무엇인가요?","options":[{"t":"바구니 잡기","correct":true},{"t":"물 길어 오기","mis":"K5-2-u3-X21"},{"t":"정자 청소하기","mis":"K5-2-u3-X21"},{"t":"시장 다녀오기","mis":"K5-2-u3-X21"}],"explanation":["글에 없어요.","글에 없어요.","다섯째 줄에 나와요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#9','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C12',2,'mc','auto','글쓴이가 학교 발표에서 표준어로 바꾸어 소개하기로 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X19','K5-2-u3-X14']::text[],false,'{"seq":9,"concept":"K5-2-u3-C12","difficulty":2,"kind":"mc","stem":"글쓴이가 학교 발표에서 표준어로 바꾸어 소개하기로 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"반 친구들이 모두 알아듣게 하려고","correct":true},{"t":"가족의 방언이 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"가족의 말을 부끄럽게 여겨서","mis":"K5-2-u3-X19"},{"t":"선생님이 방언을 쓰지 말라고 해서","mis":"K5-2-u3-X14"}],"explanation":["틀린 말이 아니에요.","뜻과 함께 소개해요.","여러 친구가 들어요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#10','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C8',2,'mc','auto','표준어와 방언 사이를 가장 알맞게 설명한 것은 어느 것인가요?',ARRAY['K5-2-u3-X08','K5-2-u3-X06','K5-2-u3-X30']::text[],false,'{"seq":10,"concept":"K5-2-u3-C8","difficulty":2,"kind":"mc","stem":"표준어와 방언 사이를 가장 알맞게 설명한 것은 어느 것인가요?","options":[{"t":"꽉 막힌 벽이 아니라 널리 쓰이면 오가기도 하는 움직이는 경계이다","correct":true},{"t":"방언은 영원히 방언으로만 남는다","mis":"K5-2-u3-X08"},{"t":"표준어는 방언보다 높은 말이다","mis":"K5-2-u3-X06"},{"t":"둘은 서로 아무 관계가 없다","mis":"K5-2-u3-X30"}],"explanation":["멍게를 떠올려요.","높고 낮음이 없어요.","서로 오가기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#11','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C30',2,'mc','auto','상황 카드 고르기를 하고 나서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X30','K5-2-u3-X12']::text[],false,'{"seq":11,"concept":"K5-2-u3-C30","difficulty":2,"kind":"mc","stem":"상황 카드 고르기를 하고 나서 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 말이 늘 더 좋은 것이 아니라 상황에 따라 어울리는 말이 다르다","correct":true},{"t":"표준어가 언제나 정답이다","mis":"K5-2-u3-X30"},{"t":"방언이 언제나 정답이다","mis":"K5-2-u3-X30"},{"t":"상황과 말은 관계가 없다","mis":"K5-2-u3-X12"}],"explanation":["늘 정답은 없어요.","늘 정답은 없어요.","상황에 따라 골라요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#12','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C20',2,'mc','auto','방언을 지키려는 노력으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X15','K5-2-u3-X14']::text[],false,'{"seq":12,"concept":"K5-2-u3-C20","difficulty":2,"kind":"mc","stem":"방언을 지키려는 노력으로 알맞은 것은 어느 것인가요?","options":[{"t":"어르신들의 말을 녹음해 방언 사전이나 그림책을 만든다","correct":true},{"t":"방언을 쓰는 사람을 놀린다","mis":"K5-2-u3-X29"},{"t":"방언을 모두 표준어로 고쳐 쓴다","mis":"K5-2-u3-X15"},{"t":"방언을 쓰지 말자는 포스터를 붙인다","mis":"K5-2-u3-X14"}],"explanation":["존중해야 해요.","고치기가 아니에요.","기록해 물려줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#13','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C22',2,'blank','auto','「서울서 왔당께.」를 표준어로 바꾸면 「서울에서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u3-X22','K5-2-u3-X15']::text[],false,'{"seq":13,"concept":"K5-2-u3-C22","difficulty":2,"kind":"blank","stem":"「서울서 왔당께.」를 표준어로 바꾸면 「서울에서 ( ? )」예요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"왔다니까","correct":true},{"t":"왔겠지","mis":"K5-2-u3-X22"},{"t":"왔는데","mis":"K5-2-u3-X22"},{"t":"왔당께","mis":"K5-2-u3-X15"}],"explanation":["뜻이 달라요.","뜻이 달라요.","「~당께」는 「~다니까」예요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#14','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C26',2,'mc','auto','방언을 활용한 작품 활동끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['K5-2-u3-X26','K5-2-u3-X29']::text[],false,'{"seq":14,"concept":"K5-2-u3-C26","difficulty":2,"kind":"mc","stem":"방언을 활용한 작품 활동끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"방언 지도 · 방언 노랫말 · 방언 상황극","correct":true},{"t":"방언 지도 · 받아쓰기 시험 · 곱셈 구구표","mis":"K5-2-u3-X26"},{"t":"방언 흉내 대회 · 방언 노랫말 · 상황극","mis":"K5-2-u3-X29"},{"t":"방언 지도 한 가지뿐","mis":"K5-2-u3-X26"}],"explanation":["방언 작품이 아니에요.","흉내는 알맞지 않아요.","세 가지가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#15','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C11',2,'ox','auto','같은 지역 안에서도 마을에 따라 방언이 다를 수 있어요.',ARRAY['K5-2-u3-X11']::text[],false,'{"seq":15,"concept":"K5-2-u3-C11","difficulty":2,"kind":"ox","stem":"같은 지역 안에서도 마을에 따라 방언이 다를 수 있어요.","answer":"O","reason_options":[{"t":"방언은 지역 경계와 똑같이 나뉘지 않고 마을마다 다르기도 하기 때문에","correct":true},{"t":"같은 지역이면 방언이 모두 똑같기 때문에","mis":"K5-2-u3-X11"}],"mis":"K5-2-u3-X11","explanation":["마을마다 달라요.","정답은 하나가 아니에요.","근거로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#16','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C32',2,'mc','auto','동형어의 뜻을 가리는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"동형어의 뜻을 가리는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문장 속 앞뒤 말을 살펴본다","correct":true},{"t":"처음 떠오른 뜻으로 정한다","mis":"K5-2-u3-X32"},{"t":"글자 수를 세어 본다","mis":"K5-2-u3-X32"},{"t":"소리 내어 빨리 읽는다","mis":"K5-2-u3-X32"}],"explanation":["뜻이 여럿이에요.","글자 수는 같아요.","앞뒤 말로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#17','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C12',3,'error','auto','「우리 집 말 조사 일지」를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X13','K5-2-u3-X09']::text[],false,'{"seq":17,"concept":"K5-2-u3-C12","difficulty":3,"kind":"error","stem":"「우리 집 말 조사 일지」를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「글쓴이는 가족 앞에서도 표준어만 써야 해.」","correct":true,"mis_target":"K5-2-u3-X14"},{"t":"「발표 자리에서 표준어로 바꾸는 건 친구들이 알아듣게 하려는 거야.」","mis":"K5-2-u3-X13"},{"t":"「가족의 말을 조사하니 우리 집에도 여러 지역 말이 살아 있어.」","mis":"K5-2-u3-X09"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","가족과는 정다운 말도 어울려요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#18','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C14',3,'mc','auto','할아버지께서 고향 친구분과 통화하실 때 방언을 쓰시는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X03','K5-2-u3-X12']::text[],false,'{"seq":18,"concept":"K5-2-u3-C14","difficulty":3,"kind":"mc","stem":"할아버지께서 고향 친구분과 통화하실 때 방언을 쓰시는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어릴 적부터 함께 쓰던 말로 편하고 정답게 마음을 나누시려고","correct":true},{"t":"표준어를 모르셔서","mis":"K5-2-u3-X14"},{"t":"친구분이 표준어를 못 알아들으셔서","mis":"K5-2-u3-X03"},{"t":"전화로는 방언만 써야 해서","mis":"K5-2-u3-X12"}],"explanation":["몰라서가 아니에요.","알아들으세요.","정을 나누시려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#19','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C23',3,'error','auto','방언 낭독과 표준어 낭독을 견준 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X24','K5-2-u3-X23']::text[],false,'{"seq":19,"concept":"K5-2-u3-C23","difficulty":3,"kind":"error","stem":"방언 낭독과 표준어 낭독을 견준 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「표준어로 읽어야 바른 낭독이니 방언 낭독은 할 필요가 없어.」","correct":true,"mis_target":"K5-2-u3-X24"},{"t":"「방언 낭독에서 할머니 얼굴이 더 떠올랐어.」","mis":"K5-2-u3-X23"},{"t":"「표준어 낭독도 뜻은 잘 전해졌어.」","mis":"K5-2-u3-X23"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","방언 낭독에서 정이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#20','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C18',3,'error','auto','방언 속 지역 이야기 카드를 본 친구들의 말이에요. 방언의 가치를 가장 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u3-X18','K5-2-u3-X17']::text[],false,'{"seq":20,"concept":"K5-2-u3-C18","difficulty":3,"kind":"error","stem":"방언 속 지역 이야기 카드를 본 친구들의 말이에요. 방언의 가치를 가장 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「뜻만 적으면 됐지 그 지역 자연이나 생활은 적을 필요 없어.」","correct":true,"mis_target":"K5-2-u3-X18"},{"t":"「돔배기에는 동해와 가까운 생활이 담겨 있어.」","mis":"K5-2-u3-X18"},{"t":"「정낭에는 이웃을 믿던 마을 생활이 담겨 있어.」","mis":"K5-2-u3-X17"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","자연과 생활까지 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#21','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C27',3,'mc','auto','방언 지도를 만들며 「이 방언은 어떤 생활 모습과 관련이 있을까?」라고 묻는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X28','K5-2-u3-X29','K5-2-u3-X27']::text[],false,'{"seq":21,"concept":"K5-2-u3-C27","difficulty":3,"kind":"mc","stem":"방언 지도를 만들며 「이 방언은 어떤 생활 모습과 관련이 있을까?」라고 묻는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언의 뜻을 적는 데 그치지 않고 지역의 생활까지 조사하려고","correct":true},{"t":"방언 개수를 늘리려고","mis":"K5-2-u3-X28"},{"t":"흉내 낼 말을 고르려고","mis":"K5-2-u3-X29"},{"t":"지도를 빨리 마치려고","mis":"K5-2-u3-X27"}],"explanation":["개수가 목적이 아니에요.","흉내는 알맞지 않아요.","생활까지 조사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#22','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C6',3,'mc','auto','표준어를 정한 까닭과 방언이 소중한 까닭을 함께 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X03','K5-2-u3-X07']::text[],false,'{"seq":22,"concept":"K5-2-u3-C6","difficulty":3,"kind":"mc","stem":"표준어를 정한 까닭과 방언이 소중한 까닭을 함께 바르게 말한 것은 어느 것인가요?","options":[{"t":"표준어는 원활한 의사소통을, 방언은 지역의 특성과 정서를 지켜 준다","correct":true},{"t":"표준어는 고운 말이라서, 방언은 재미있는 말이라서","mis":"K5-2-u3-X06"},{"t":"표준어는 서울 말이라서, 방언은 시골 말이라서","mis":"K5-2-u3-X03"},{"t":"표준어는 짧아서, 방언은 길어서","mis":"K5-2-u3-X07"}],"explanation":["곱고 재미있음이 까닭이 아니에요.","사는 곳이 까닭이 아니에요.","하는 일이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#23','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C32',4,'essay','teacher','「배」 · 「눈」 · 「말」 가운데 하나를 골라 서로 다른 두 뜻으로 문장을 하나씩 만들어 쓰고, 뜻을 어떻게 가렸는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C32","difficulty":4,"kind":"essay","stem":"「배」 · 「눈」 · 「말」 가운데 하나를 골라 서로 다른 두 뜻으로 문장을 하나씩 만들어 쓰고, 뜻을 어떻게 가렸는지 쓰세요.","answer_guide":{"answer":"예: 눈 — 「눈이 소복이 쌓였다.」, 「눈을 크게 뜨고 바라보았다.」 앞 문장은 「쌓였다」를 보고 하늘에서 내리는 눈, 뒤 문장은 「뜨고」를 보고 보는 눈임을 알았다.","scoring_points":["낱말을 하나 골랐는가","서로 다른 두 뜻으로 문장을 만들었는가","앞뒤 말로 뜻을 가렸다고 썼는가"]},"explanation":["하나를 골라요.","두 뜻으로 써요.","앞뒤 말이 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#24','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C9',4,'essay','teacher','「우리 집 말 조사 일지」처럼 우리 가족이 쓰는 말을 하나 조사해 방언과 표준어, 쓰는 사람과 상황을 정리해 쓰세요. 방언이 떠오르지 않으면 가족이 즐겨 쓰는 표준어 표현으로 써도 돼요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"「우리 집 말 조사 일지」처럼 우리 가족이 쓰는 말을 하나 조사해 방언과 표준어, 쓰는 사람과 상황을 정리해 쓰세요. 방언이 떠오르지 않으면 가족이 즐겨 쓰는 표준어 표현으로 써도 돼요.","answer_guide":{"answer":"예: 방언 — 정구지, 표준어 — 부추, 쓰는 사람 — 경상 지역에 사시는 외할머니, 상황 — 부침개를 부치시며 「정구지 좀 더 넣자.」 하고 말씀하실 때. 가족끼리 편하게 이야기하실 때 쓰신다.","scoring_points":["조사한 말과 뜻을 썼는가","쓰는 사람을 썼는가","쓰는 상황을 썼는가"]},"explanation":["말과 뜻이에요.","누가 쓰는지예요.","어떤 상황인지예요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_c#25','kor',5,2,'u3','','g5_2_kor_u3_review_c','unit_review','K5-2-u3-C15',4,'essay','teacher','방언을 표준어로 바꾸어 보는 활동이 방언을 고치는 일이 아닌 까닭을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C15","difficulty":4,"kind":"essay","stem":"방언을 표준어로 바꾸어 보는 활동이 방언을 고치는 일이 아닌 까닭을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「일찍 왔네유.」를 「일찍 왔네요.」로 바꾸어도 뜻은 같다. 고향 집 마당에서는 방언이 정답고, 여러 사람 앞 발표에서는 표준어가 알맞다. 그러므로 바꾸어 보는 것은 틀린 말을 고치는 것이 아니라, 같은 뜻을 상황에 따라 골라 쓴다는 것을 알기 위한 활동이다.","scoring_points":["예를 들었는가","뜻은 같다는 것을 썼는가","상황에 따른 선택을 알기 위함을 썼는가"]},"explanation":["예를 들어요.","뜻은 같아요.","선택을 알기 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#1','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C3',1,'ox','auto','방언은 시골에서만 쓰는 말이에요.',ARRAY['K5-2-u3-X03']::text[],false,'{"seq":1,"concept":"K5-2-u3-C3","difficulty":1,"kind":"ox","stem":"방언은 시골에서만 쓰는 말이에요.","answer":"X","reason_options":[{"t":"큰 도시에서도 그 지역에서 주로 쓰는 말이 있기 때문에","correct":true},{"t":"도시 사람은 모두 표준어만 쓰기 때문에","mis":"K5-2-u3-X03"}],"mis":"K5-2-u3-X03","explanation":["도시에도 방언이 있어요.","지역의 말이에요.","시골 말만이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#2','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C32',1,'ox','auto','「배」는 먹는 배, 타는 배, 몸의 배처럼 여러 뜻으로 쓰여요.',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":2,"concept":"K5-2-u3-C32","difficulty":1,"kind":"ox","stem":"「배」는 먹는 배, 타는 배, 몸의 배처럼 여러 뜻으로 쓰여요.","answer":"O","reason_options":[{"t":"글자 모양은 같지만 뜻이 다른 동형어이기 때문에","correct":true},{"t":"한 낱말에는 뜻이 하나뿐이기 때문에","mis":"K5-2-u3-X32"}],"mis":"K5-2-u3-X32","explanation":["뜻이 여럿이에요.","앞뒤 말로 가려요.","동형어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#3','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C8',1,'ox','auto','「멍게」는 원래 방언이었지만 지금은 표준어예요.',ARRAY['K5-2-u3-X08']::text[],false,'{"seq":3,"concept":"K5-2-u3-C8","difficulty":1,"kind":"ox","stem":"「멍게」는 원래 방언이었지만 지금은 표준어예요.","answer":"O","reason_options":[{"t":"표준어 「우렁쉥이」보다 더 널리 쓰이게 되어 함께 표준어가 되었기 때문에","correct":true},{"t":"방언은 어떤 경우에도 표준어가 될 수 없기 때문에","mis":"K5-2-u3-X08"}],"mis":"K5-2-u3-X08","explanation":["널리 쓰였어요.","둘 다 표준어예요.","움직이는 경계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#4','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C14',1,'mc','auto','상황 카드 ㉱ 「우리 지역 축제를 홍보할 때」 방언을 쓰기도 하는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X20','K5-2-u3-X14','K5-2-u3-X29']::text[],false,'{"seq":4,"concept":"K5-2-u3-C14","difficulty":1,"kind":"mc","stem":"상황 카드 ㉱ 「우리 지역 축제를 홍보할 때」 방언을 쓰기도 하는 까닭은 무엇인가요?","options":[{"t":"지역의 정서와 특성을 잘 보여 주려고","correct":true},{"t":"다른 지역 사람이 오지 못하게 하려고","mis":"K5-2-u3-X20"},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"웃음거리로 삼으려고","mis":"K5-2-u3-X29"}],"explanation":["반기려는 거예요.","몰라서가 아니에요.","지역의 정서를 보여 줘요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#5','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C9',1,'mc','auto','「무시」를 표준어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「무시」를 표준어로 바꾸면 어느 것인가요?","options":[{"t":"무","correct":true},{"t":"배추","mis":"K5-2-u3-X10"},{"t":"파","mis":"K5-2-u3-X10"},{"t":"감자","mis":"K5-2-u3-X10"}],"explanation":["관계없어요.","관계없어요.","무시는 무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#6','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C18',1,'mc','auto','「뻘」이라는 방언과 이어지는 자연환경은 어느 것인가요?',ARRAY['K5-2-u3-X18']::text[],false,'{"seq":6,"concept":"K5-2-u3-C18","difficulty":1,"kind":"mc","stem":"「뻘」이라는 방언과 이어지는 자연환경은 어느 것인가요?","options":[{"t":"넓은 갯벌","correct":true},{"t":"높은 산","mis":"K5-2-u3-X18"},{"t":"넓은 사막","mis":"K5-2-u3-X18"},{"t":"깊은 동굴","mis":"K5-2-u3-X18"}],"explanation":["관계없어요.","관계없어요.","서해안 갯벌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#7','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C13',1,'ox','auto','전국에 방송되는 일기 예보는 방언만 써도 모두 똑같이 알아들어요.',ARRAY['K5-2-u3-X13']::text[],false,'{"seq":7,"concept":"K5-2-u3-C13","difficulty":1,"kind":"ox","stem":"전국에 방송되는 일기 예보는 방언만 써도 모두 똑같이 알아들어요.","answer":"X","reason_options":[{"t":"말이 달라 알아듣기 어려운 사람이 생길 수 있기 때문에","correct":true},{"t":"방언은 어느 지역 사람이든 다 알기 때문에","mis":"K5-2-u3-X13"}],"mis":"K5-2-u3-X13","explanation":["알아듣기 어려워요.","여러 지역 사람이 봐요.","표준어가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#8','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C24',1,'ox','auto','방언이 나오는 작품은 지역의 말을 기록하고 지키는 데에도 도움이 돼요.',ARRAY['K5-2-u3-X24']::text[],false,'{"seq":8,"concept":"K5-2-u3-C24","difficulty":1,"kind":"ox","stem":"방언이 나오는 작품은 지역의 말을 기록하고 지키는 데에도 도움이 돼요.","answer":"O","reason_options":[{"t":"작품에 담긴 방언이 글로 남아 다음 사람에게 전해지기 때문에","correct":true},{"t":"작품 속 방언은 아무도 읽지 않기 때문에","mis":"K5-2-u3-X24"}],"mis":"K5-2-u3-X24","explanation":["글로 남아요.","전해져요.","지역의 말을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#9','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C3',2,'mc','auto','「우리 집 말 조사 일지」에서 「깨깟허다」라고 말씀하시는 분은 누구인가요?',ARRAY['K5-2-u3-X21']::text[],false,'{"seq":9,"concept":"K5-2-u3-C3","difficulty":2,"kind":"mc","stem":"「우리 집 말 조사 일지」에서 「깨깟허다」라고 말씀하시는 분은 누구인가요?","options":[{"t":"충청 지역에 사시는 고모","correct":true},{"t":"제주 지역이 고향인 외할머니","mis":"K5-2-u3-X21"},{"t":"강원 지역 큰아버지","mis":"K5-2-u3-X21"},{"t":"글쓴이","mis":"K5-2-u3-X21"}],"explanation":["할망이라고 하세요.","낭구라고 하세요.","셋째 줄에 나와요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#10','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C5',2,'mc','auto','방언이 생긴 까닭과 가장 관계 깊은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":10,"concept":"K5-2-u3-C5","difficulty":2,"kind":"mc","stem":"방언이 생긴 까닭과 가장 관계 깊은 것은 어느 것인가요?","options":[{"t":"지역 사이에 이야기할 기회가 적었던 것","correct":true},{"t":"지역마다 글자를 따로 만든 것","mis":"K5-2-u3-X05"},{"t":"방송국이 지역마다 달랐던 것","mis":"K5-2-u3-X05"},{"t":"사람들이 표준어를 외우지 않은 것","mis":"K5-2-u3-X05"}],"explanation":["글자는 같아요.","옛날 일이에요.","오가기 어려웠어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#11','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C31',2,'match','auto','상황 카드와 그 말을 고른 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-2-u3-C31","difficulty":2,"kind":"match","stem":"상황 카드와 그 말을 고른 까닭을 알맞게 이으세요.","pairs":[{"l":"㉯ 뉴스","r":"여러 지역 사람들이 보기 때문에"},{"l":"㉮ 고향 친구","r":"어릴 적부터 쓰던 말로 마음을 나누기 때문에"},{"l":"㉱ 축제 홍보","r":"지역의 정서와 특성을 보여 주기 때문에"}],"mis":"K5-2-u3-X31","explanation":["표준어예요.","방언이에요.","방언을 쓰기도 해요."],"asset":{"type":"passage","lines":["㉮ 고향 친구와 오랜만에 만나 이야기할 때","㉯ 여러 지역 소식을 전하는 뉴스","㉰ 전국 어린이 회의에서 발표할 때","㉱ 우리 지역 축제를 홍보할 때"],"title":"상황 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#12','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C17',2,'error','auto','「삼춘」에 대해 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X17','K5-2-u3-X19']::text[],false,'{"seq":12,"concept":"K5-2-u3-C17","difficulty":2,"kind":"error","stem":"「삼춘」에 대해 말한 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「삼춘은 삼촌을 틀리게 쓴 말일 뿐이야.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「피를 나누지 않은 이웃 어른도 가족처럼 부르는 말이야.」","mis":"K5-2-u3-X17"},{"t":"「이웃을 가족처럼 여기는 마을 모습이 담겨 있어.」","mis":"K5-2-u3-X19"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","틀린 말이 아니라 담긴 생활이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#13','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C23',2,'ox','auto','「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸어도 뜻은 같아요.',ARRAY['K5-2-u3-X23']::text[],false,'{"seq":13,"concept":"K5-2-u3-C23","difficulty":2,"kind":"ox","stem":"「못 보던 얼굴인디, 누구 손주여?」를 표준어로 바꾸어도 뜻은 같아요.","answer":"O","reason_options":[{"t":"뜻은 같고 느낌이나 분위기가 달라지기 때문에","correct":true},{"t":"표준어로 바꾸면 뜻까지 완전히 달라지기 때문에","mis":"K5-2-u3-X23"}],"mis":"K5-2-u3-X23","explanation":["뜻은 같아요.","느낌이 달라요.","견주어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#14','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C29',2,'error','auto','방언 상황극을 준비하는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X26','K5-2-u3-X27']::text[],false,'{"seq":14,"concept":"K5-2-u3-C29","difficulty":2,"kind":"error","stem":"방언 상황극을 준비하는 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「말투를 크게 부풀려야 관객이 더 웃을 거야.」","correct":true,"mis_target":"K5-2-u3-X29"},{"t":"「방언이 실감 나는 장면을 먼저 정하자.」","mis":"K5-2-u3-X26"},{"t":"「그 지역 사람의 마음을 살려 연기하자.」","mis":"K5-2-u3-X27"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","흉내로 웃음거리를 만들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#15','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C16',2,'mc','auto','조사표 「시장에서 상인이 단골손님에게 — 방언」 뒤에 덧붙일 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X14','K5-2-u3-X16']::text[],false,'{"seq":15,"concept":"K5-2-u3-C16","difficulty":2,"kind":"mc","stem":"조사표 「시장에서 상인이 단골손님에게 — 방언」 뒤에 덧붙일 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"더 친근하고 정답게 이야기하려고","correct":true},{"t":"손님이 알아듣지 못하게 하려고","mis":"K5-2-u3-X13"},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"까닭은 적지 않아도 된다","mis":"K5-2-u3-X16"}],"explanation":["반기려는 말이에요.","몰라서가 아니에요.","정을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#16','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C32',2,'mc','auto','「말」이 「사람이 하는 말」의 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-2-u3-X32']::text[],false,'{"seq":16,"concept":"K5-2-u3-C32","difficulty":2,"kind":"mc","stem":"「말」이 「사람이 하는 말」의 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"친구에게 고맙다는 말을 했다.","correct":true},{"t":"목장에서 말을 탔다.","mis":"K5-2-u3-X32"},{"t":"말이 들판을 달린다.","mis":"K5-2-u3-X32"},{"t":"말에게 당근을 주었다.","mis":"K5-2-u3-X32"}],"explanation":["타는 말이에요.","동물이에요.","사람이 하는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#17','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C10',3,'mc','auto','글쓴이가 조사한 방언이 맞는지 더 확인하려면 어떻게 하는 것이 가장 좋을까요?',ARRAY['K5-2-u3-X11','K5-2-u3-X10','K5-2-u3-X19']::text[],false,'{"seq":17,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"글쓴이가 조사한 방언이 맞는지 더 확인하려면 어떻게 하는 것이 가장 좋을까요?","options":[{"t":"지역어 누리집에서 낱말을 찾아 쓰는 지역과 뜻을 확인한다","correct":true},{"t":"친구 한 명에게만 물어본다","mis":"K5-2-u3-X11"},{"t":"뜻을 짐작해 그대로 둔다","mis":"K5-2-u3-X10"},{"t":"조사한 말을 모두 지운다","mis":"K5-2-u3-X19"}],"explanation":["한 사람 말은 부족해요.","근거가 없어요.","근거로 확인해요."],"asset":{"type":"passage","lines":["방학 동안 나는 우리 가족이 쓰는 말을 조사했다.","제주 지역이 고향인 외할머니는 할머니를 「할망」이라고 하신다.","충청 지역에 사시는 고모는 방이 깨끗하면 「깨깟허다」라고 하신다.","강원 지역 큰아버지는 뒷산에 「낭구」가 빽빽하다고 말씀하신다.","같은 우리말인데 가족마다 부르는 이름이 달라 신기했다.","학교 발표에서는 반 친구들이 모두 알아듣도록 표준어로 바꾸어 소개하고,","가족의 말은 뜻과 함께 소개하기로 했다."],"title":"우리 집 말 조사 일지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#18','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C13',3,'error','auto','학교 방송부가 「우리 고장 소개」 방송 계획을 세웠어요. 듣는 사람을 가장 덜 생각한 계획은 어느 것인가요?',ARRAY['K5-2-u3-X13','K5-2-u3-X30','K5-2-u3-X22']::text[],false,'{"seq":18,"concept":"K5-2-u3-C13","difficulty":3,"kind":"error","stem":"학교 방송부가 「우리 고장 소개」 방송 계획을 세웠어요. 듣는 사람을 가장 덜 생각한 계획은 어느 것인가요?","options":[{"t":"「다른 지역 학교에도 보낼 방송이지만 설명까지 모두 방언으로만 하자.」","correct":true,"mis_target":"K5-2-u3-X13"},{"t":"「소개는 표준어로 하고 어르신 인터뷰는 방언 그대로 싣자.」","mis":"K5-2-u3-X30"},{"t":"「방언이 나오면 자막으로 뜻을 함께 보여 주자.」","mis":"K5-2-u3-X22"}],"explanation":["둘 다 살렸어요.","뜻을 도와요.","다른 지역 학생이 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#19','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C21',3,'mc','auto','「처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다.」에서 하준이 마음이 바뀐 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X23','K5-2-u3-X21']::text[],false,'{"seq":19,"concept":"K5-2-u3-C21","difficulty":3,"kind":"mc","stem":"「처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다.」에서 하준이 마음이 바뀐 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마을 사람들의 반가운 마음을 함께 지내며 느꼈기 때문에","correct":true},{"t":"할머니들이 표준어로 말을 바꾸었기 때문에","mis":"K5-2-u3-X23"},{"t":"하준이가 방언 뜻을 모두 외웠기 때문에","mis":"K5-2-u3-X21"},{"t":"감이 맛있었기 때문에","mis":"K5-2-u3-X21"}],"explanation":["말은 그대로예요.","외운 이야기는 없어요.","정을 느꼈어요."],"asset":{"type":"passage","lines":["가을 방학에 하준이는 외할머니가 사시는 남쪽 바닷가 마을에 갔다.","마을 정자에 모인 할머니들이 하준이를 보고 물었다. 「못 보던 얼굴인디, 누구 손주여?」","외할머니가 웃으며 대답했다. 「우리 딸네 아들이여. 서울서 왔당께.」","「그러니께 얼굴이 하얗겄제.」 할머니들이 손뼉을 치며 웃었다.","감나무 아래에서 외할머니가 불렀다. 「아야, 싸게싸게 와서 바구니 잡아라잉.」","처음엔 낯설던 말들이 감을 다 딸 즈음에는 하준이 귀에 따뜻하게 들렸다."],"title":"감 따는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#20','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C19',3,'mc','auto','「표준어만 있으면 충분하니 방언은 필요 없다.」라는 주장에 대한 반론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X30','K5-2-u3-X20','K5-2-u3-X19']::text[],false,'{"seq":20,"concept":"K5-2-u3-C19","difficulty":3,"kind":"mc","stem":"「표준어만 있으면 충분하니 방언은 필요 없다.」라는 주장에 대한 반론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방언에는 표준어로 다 담기 어려운 지역의 생활과 정서가 들어 있다","correct":true},{"t":"표준어는 쓸모없는 말이다","mis":"K5-2-u3-X30"},{"t":"방언은 다른 지역 사람과 소통을 막는다","mis":"K5-2-u3-X20"},{"t":"방언은 옛날 말이라 소중하지 않다","mis":"K5-2-u3-X19"}],"explanation":["표준어도 소중해요.","주장을 돕는 말이에요.","방언의 가치로 반론해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#21','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C26',3,'error','auto','방언 노랫말 만들기 계획이에요. 활동의 목적에서 가장 벗어난 계획은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X26','K5-2-u3-X28']::text[],false,'{"seq":21,"concept":"K5-2-u3-C26","difficulty":3,"kind":"error","stem":"방언 노랫말 만들기 계획이에요. 활동의 목적에서 가장 벗어난 계획은 어느 것인가요?","options":[{"t":"「뜻은 신경 쓰지 말고 웃긴 말투만 골라 넣자.」","correct":true,"mis_target":"K5-2-u3-X29"},{"t":"「아는 노래에 우리 지역 인사말을 넣어 바꾸어 부르자.」","mis":"K5-2-u3-X26"},{"t":"「넣은 방언의 뜻을 노랫말 아래에 함께 적자.」","mis":"K5-2-u3-X28"}],"explanation":["알맞은 계획이에요.","알맞은 계획이에요.","웃음거리로 삼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#22','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C15',3,'mc','auto','「일찍 왔네유.」를 「일찍 왔네요.」로 바꾸어 본 친구의 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X15','K5-2-u3-X23','K5-2-u3-X14']::text[],false,'{"seq":22,"concept":"K5-2-u3-C15","difficulty":3,"kind":"mc","stem":"「일찍 왔네유.」를 「일찍 왔네요.」로 바꾸어 본 친구의 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「뜻은 같지만 고향 집에서는 방언이, 발표에서는 표준어가 더 어울려.」","correct":true},{"t":"「이제 틀린 말을 고쳤어.」","mis":"K5-2-u3-X15"},{"t":"「바꾸었더니 뜻이 완전히 달라졌어.」","mis":"K5-2-u3-X23"},{"t":"「방언은 앞으로 쓰지 말아야겠어.」","mis":"K5-2-u3-X14"}],"explanation":["고치기가 아니에요.","뜻은 같아요.","자리에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#23','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C12',4,'essay','teacher','같은 날 전국 어린이 회의에서 발표하고 저녁에 할머니 고향 마을 잔치에 간다면 각 자리에서 어떤 말을 쓸지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u3-C12","difficulty":4,"kind":"essay","stem":"같은 날 전국 어린이 회의에서 발표하고 저녁에 할머니 고향 마을 잔치에 간다면 각 자리에서 어떤 말을 쓸지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 어린이 회의에서는 여러 지역 친구들이 모두 알아듣도록 표준어로 발표하겠다. 잔치에서는 할머니 고향 어르신들과 더 가깝게 이야기하고 싶어 어르신들이 쓰시는 말을 귀담아듣고 정답게 인사하겠다. 우리 집이 표준어를 쓰는 지역이라면 잔치에서도 표준어로 정답게 말하면 된다.","scoring_points":["회의 자리의 말과 까닭을 썼는가","잔치 자리의 말과 까닭을 썼는가","자리에 따라 고르는 기준이 드러나는가"]},"explanation":["회의 자리예요.","잔치 자리예요.","자리에 따라 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#24','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C5',4,'essay','teacher','방언이 생긴 까닭을 옛날의 지형과 교통과 이어 설명하고, 오늘날 방언이 어떻게 달라질지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u3-C5","difficulty":4,"kind":"essay","stem":"방언이 생긴 까닭을 옛날의 지형과 교통과 이어 설명하고, 오늘날 방언이 어떻게 달라질지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 산과 강이 많고 교통이 발달하지 않아 지역 사이를 오가기 어려웠고, 이야기할 기회가 적어 지역마다 말이 달라졌다. 오늘날에는 교통과 통신이 발달해 표준어와 닮아 가는 방언도 있겠지만, 지역 사람들이 아끼고 기록한다면 계속 남을 것이다.","scoring_points":["지형과 교통을 들어 까닭을 썼는가","오늘날의 변화를 짐작했는가","내 생각에 까닭이 있는가"]},"explanation":["지형과 교통이에요.","오늘날을 생각해요.","까닭을 덧붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u3_review_d#25','kor',5,2,'u3','','g5_2_kor_u3_review_d','unit_review','K5-2-u3-C29',4,'essay','teacher','이 단원을 배우며 방언을 대하는 내 생각이나 태도가 어떻게 달라졌는지 쓰고, 앞으로 실천할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u3-C29","difficulty":4,"kind":"essay","stem":"이 단원을 배우며 방언을 대하는 내 생각이나 태도가 어떻게 달라졌는지 쓰고, 앞으로 실천할 일을 쓰세요.","answer_guide":{"answer":"예: 전에는 방언을 들으면 우습다고 생각했는데, 이제는 그 말에 지역의 생활과 정이 담겨 있다는 것을 알게 되었다. 앞으로는 낯선 방언을 흉내 내지 않고 궁금한 마음으로 뜻을 묻고, 할머니께 고향 말을 여쭈어 기록해 보겠다.","scoring_points":["달라진 생각이나 태도를 썼는가","방언을 존중하는 까닭이 드러나는가","앞으로 실천할 일을 썼는가"]},"explanation":["달라진 점이에요.","존중하는 까닭이에요.","실천할 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C1','kor',5,2,'u4',1,'같은 문제, 서로 다른 의견 — 사람마다 생각과 겪은 일이 달라 한 가지 문제에 여러 의견이 나오는 것은 자연스럽다',ARRAY['6국01-06 듣기·말하기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C2','kor',5,2,'u4',1,'토의의 뜻 — 여럿이 함께 문제를 풀 방법을 찾는 말하기로, 누가 이기는지 겨루는 자리가 아니다',ARRAY['6국01-06 듣기·말하기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C3','kor',5,2,'u4',1,'의견 조정의 뜻 — 서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일로, 내 의견을 버리는 것이 아니다',ARRAY['6국01-06 듣기·말하기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C4','kor',5,2,'u4',1,'의견과 까닭 — 의견에는 그렇게 생각한 까닭이 함께 있어야 다른 의견과 견주어 따져 볼 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C5','kor',5,2,'u4',1,'단원의 흐름 — 의견을 조정하는 방법 알기 → 모둠 토의 → 학급 토의 → 주변의 문제 토의 → 우리 학교 문제 실천',ARRAY['6국01-06 듣기·말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C6','kor',5,2,'u4',2,'토의 대화에서 문제와 의견 찾기 — 사회자가 밝힌 풀려는 문제와 친구들이 제안한 의견, 그 까닭을 찾으며 읽는다',ARRAY['6국01-06 듣기·말하기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C7','kor',5,2,'u4',2,'검토 기준 마련하기 — 의견을 조정할 때 먼저 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 같은 기준을 함께 정한다',ARRAY['6국01-06 듣기·말하기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C8','kor',5,2,'u4',2,'기준은 문제마다 — 문제에 따라 기준을 다르게 정하거나 비용처럼 새 기준을 더할 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C9','kor',5,2,'u4',2,'장점과 단점 검토하기 — 정한 기준에 비추어 의견을 실천했을 때 기대되는 효과와 생길 수 있는 문제를 정리한다',ARRAY['6국01-06 듣기·말하기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C10','kor',5,2,'u4',2,'단점 말하기는 비난이 아니에요 — 단점을 따지는 것은 최선의 의견을 찾는 과정이므로, 사람이 아니라 의견을 두고 배려하며 말한다',ARRAY['6국01-06 듣기·말하기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C11','kor',5,2,'u4',2,'합의점 찾기 — 서로 조금씩 양보해 의견이 하나로 모이는 자리로, 장점은 살리고 단점은 보완해 찾는다',ARRAY['6국01-06 듣기·말하기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C12','kor',5,2,'u4',2,'합의점의 여러 모습 — 한 의견을 고르는 것뿐 아니라 새 의견을 만들거나 두 의견을 합치거나 둘 이상을 함께 고를 수도 있다',ARRAY['6국01-06 듣기·말하기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C13','kor',5,2,'u4',2,'오가는 조정 차례 — 기준 마련 → 장단점 검토 → 합의점 찾기는 고정된 길이 아니라 필요하면 앞 차례로 되돌아가 다시 따진다',ARRAY['6국01-06 듣기·말하기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C14','kor',5,2,'u4',2,'손을 들어 정할 때와 토의의 목적 — 끝내 합의가 어려우면 많은 쪽으로 정하기도 하지만, 토의의 목적은 의견을 조정해 합의점을 찾는 데 있다',ARRAY['6국01-06 듣기·말하기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C15','kor',5,2,'u4',4,'토의 주제 정하기 — 불평이나 탓하는 말이 아니라 「어떻게 하면 ~할까?」처럼 함께 방법을 찾는 물음으로 정한다',ARRAY['6국01-06 듣기·말하기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C16','kor',5,2,'u4',4,'주제를 고르는 기준 — 우리와 관련이 있고, 우리가 직접 풀 수 있고, 가장 먼저 풀어야 할 문제를 고른다',ARRAY['6국01-06 듣기·말하기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C17','kor',5,2,'u4',4,'질문하며 듣기 — 친구 의견을 들으며 궁금한 점을 질문하면 의견이 또렷해지고 빈틈을 보완할 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C18','kor',5,2,'u4',4,'공손한 질문 — 질문은 친구를 이기려는 공격이 아니라 「궁금해서 묻는데」처럼 의견을 함께 다듬으려는 물음이다',ARRAY['6국01-03 듣기·말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C19','kor',5,2,'u4',4,'모둠 의견으로 고치기 — 기준에 따라 의견마다 장단점을 정리하고, 장점을 살려 모두가 동의할 만한 하나의 의견으로 고친다',ARRAY['6국01-06 듣기·말하기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C20','kor',5,2,'u4',4,'참여의 가치 — 내 의견이 그대로 뽑히지 않아도 말하고 질문하며 함께 고친 과정 속에 내 생각이 들어 있다',ARRAY['6국01-06 듣기·말하기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C21','kor',5,2,'u4',4,'맞장구만 치면 — 모두 좋다고만 하면 단점을 따지는 과정이 빠져 실천할 때 생길 문제를 미리 찾지 못한다',ARRAY['6국01-06 듣기·말하기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C22','kor',5,2,'u4',6,'사회자의 일 — 사회자는 절차를 안내하고 나온 의견을 정리하며 여러 사람이 말하도록 돕는다',ARRAY['6국01-06 듣기·말하기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C23','kor',5,2,'u4',6,'학급 토의 절차 — 토의 주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기 차례로 한다',ARRAY['6국01-06 듣기·말하기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C24','kor',5,2,'u4',6,'의견 모으기 안의 조정 — 의견 모으기 안에 검토 기준 마련하기 · 장점과 단점 검토하기 · 합의점 찾기가 들어 있다',ARRAY['6국01-06 듣기·말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C25','kor',5,2,'u4',6,'칠판에 한눈에 — 의견이 많으면 칠판이나 화면에 의견과 기준, 장단점을 정리해 모두가 한눈에 보고 견준다',ARRAY['6국01-06 듣기·말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C26','kor',5,2,'u4',6,'모두가 참여하는 학급 토의 — 반 전체의 문제이므로 모두가 의견을 마련하고, 몇몇 친구의 의견만 중심이 되지 않게 여러 친구가 말한다',ARRAY['6국01-06 듣기·말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C27','kor',5,2,'u4',6,'회의와 토의 — 회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 의견을 조정해 합의된 쪽으로 정한다',ARRAY['6국01-06 듣기·말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C28','kor',5,2,'u4',6,'정한 의견 받아들이고 실천하기 — 정당한 절차로 정한 의견은 내 의견과 달라도 함께 실천하고, 해 보니 잘 안 되면 다시 토의해 고친다',ARRAY['6국01-06 듣기·말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C29','kor',5,2,'u4',8,'서로 다른 가치 — 사람마다 소중히 여기는 것이 달라서, 한쪽의 소중한 일이 다른 쪽에게 불편이 되어 부딪칠 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C30','kor',5,2,'u4',8,'존중과 양보 — 서로 다른 가치는 둘 다 소중할 수 있어 누가 옳은지 겨루기보다 서로 존중하며 조금씩 양보할 방법을 찾는다',ARRAY['6국01-06 듣기·말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C31','kor',5,2,'u4',8,'주변의 문제를 토의 주제로 — 주변의 부딪침 가운데 풀어야 할 필요가 있고 우리가 풀이에 도움을 줄 수 있는 문제를 고른다',ARRAY['6국01-06 듣기·말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C32','kor',5,2,'u4',8,'자료로 의견 다듬기 — 까닭은 타당하고 구체적이어야 하므로 책이나 누리집에서 자료를 찾아 의견을 다듬는다',ARRAY['6국01-06 듣기·말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C33','kor',5,2,'u4',8,'정한 의견 제안하기 — 우리가 정한 의견을 누구에게 어떻게 알릴지 정해, 의견과 까닭을 알맞은 곳에 제안한다',ARRAY['6국01-06 듣기·말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C34','kor',5,2,'u4',11,'학교 문제 토의 여섯 단계 — 토의 주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기 → 되돌아보기',ARRAY['6국01-06 듣기·말하기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C35','kor',5,2,'u4',11,'이견이 없는지 확인하기 — 의견을 정한 뒤에는 다른 생각이 남아 있지 않은지 확인해야 모두가 함께 실천할 수 있다',ARRAY['6국01-06 듣기·말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C36','kor',5,2,'u4',11,'합의점을 찾는 생각 도구 — 막힐 때 바꾸기 · 합치기 · 줄이기와 빼기 · 순서 바꾸기 물음을 던져 새 의견을 떠올린다',ARRAY['6국01-06 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C37','kor',5,2,'u4',11,'토의 되돌아보기 — 잘한 점과 보완할 점을 나누되 누구 잘못인지 따지기보다 다음에 함께 노력할 점을 찾는다',ARRAY['6국01-06 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C38','kor',5,2,'u4',13,'정답 의견은 없어요 — 처음부터 정해진 정답 의견은 없고, 견주고 질문하고 고치는 과정에서 처음보다 나아진 의견이 만들어진다',ARRAY['6국01-06 듣기·말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-2-u4-C39','kor',5,2,'u4',13,'순화어 — 지나치게 어려운 말이나 외래어를 알기 쉬운 우리말로 바꾼 말로, 언박싱 → 개봉 · 북 트레일러 → 책 소개 영상 · 큐레이터 → 전시 기획자 · 팩트 체크 → 사실 확인 · 여행 가이드 → 여행 안내원처럼 쓴다 (기초 다지기)',ARRAY['기초 다지기(순화어)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X01','kor',5,'u4',ARRAY['K5-2-u4-C1']::text[],'같은 문제에 의견이 서로 다르면 누군가 잘못 생각한 것이라고 여긴다','다른 게 자연스러워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X02','kor',5,'u4',ARRAY['K5-2-u4-C2']::text[],'토의를 누가 이기는지 겨루는 말하기로 여긴다','함께 방법 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X03','kor',5,'u4',ARRAY['K5-2-u4-C3','K5-2-u4-C11']::text[],'의견을 조정하면 내 의견은 모두 버려야 하거나 진 것이라고 여긴다','살리고 보완해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X04','kor',5,'u4',ARRAY['K5-2-u4-C4']::text[],'까닭 없이 의견만 말하거나 「그냥 좋아서」로 의견을 고른다','까닭이 있어야 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X05','kor',5,'u4',ARRAY['K5-2-u4-C5']::text[],'단원에서 배우는 차례를 섞거나 학교 문제 실천부터 한다고 여긴다','방법 → 모둠 → 학급 → 주변 → 학교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X06','kor',5,'u4',ARRAY['K5-2-u4-C6']::text[],'토의 대화에서 의견만 찾고 풀려는 문제나 누가 무슨 까닭을 들었는지 놓친다','문제 · 의견 · 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X07','kor',5,'u4',ARRAY['K5-2-u4-C7']::text[],'검토 기준을 정하지 않고 바로 마음에 드는 의견을 고른다','기준이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X08','kor',5,'u4',ARRAY['K5-2-u4-C7','K5-2-u4-C22']::text[],'목소리 크기나 먼저 말한 차례, 말한 사람을 의견을 견주는 기준으로 여긴다','의견을 기준으로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X09','kor',5,'u4',ARRAY['K5-2-u4-C8']::text[],'검토 기준은 어떤 문제든 늘 똑같은 세 가지뿐이라고 여긴다','문제마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X10','kor',5,'u4',ARRAY['K5-2-u4-C9']::text[],'좋은 의견에는 단점이 없다고 여기거나 단점이 하나라도 있으면 의견을 통째로 버린다','장점과 단점이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X11','kor',5,'u4',ARRAY['K5-2-u4-C10']::text[],'단점 말하기를 친구를 비난하는 일로 여겨 피하거나, 의견이 아니라 친구를 깎아내린다','사람 말고 의견을') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X12','kor',5,'u4',ARRAY['K5-2-u4-C12']::text[],'합의점은 여러 의견 가운데 하나를 그대로 고르는 것뿐이라고 여긴다','합치고 새로 만들기도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X13','kor',5,'u4',ARRAY['K5-2-u4-C13']::text[],'조정 차례는 한 방향으로만 가서 앞 차례로 되돌아갈 수 없다고 여긴다','필요하면 되돌아가요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X14','kor',5,'u4',ARRAY['K5-2-u4-C14']::text[],'손을 들어 정하면 그 전의 토의는 헛수고라고 여기거나 처음부터 손을 들면 된다고 여긴다','목적은 합의점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X15','kor',5,'u4',ARRAY['K5-2-u4-C15']::text[],'토의 주제를 불평이나 누구 탓인지 묻는 말로 정한다','어떻게 하면 ~할까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X16','kor',5,'u4',ARRAY['K5-2-u4-C16']::text[],'우리와 관련 없거나 우리가 풀 수 없는 문제, 재미만 있는 문제를 주제로 고른다','관련 · 실천 · 시급') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X17','kor',5,'u4',ARRAY['K5-2-u4-C17']::text[],'친구 의견을 듣기만 하고 궁금한 점을 묻지 않거나 질문을 토의를 방해하는 일로 여긴다','물으면 또렷해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X18','kor',5,'u4',ARRAY['K5-2-u4-C18']::text[],'질문을 친구를 이기거나 놀리는 공격처럼 한다','궁금해서 묻는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X19','kor',5,'u4',ARRAY['K5-2-u4-C19']::text[],'모둠 의견을 정할 때 한 의견만 남기고 다른 의견의 장점은 버린다','장점을 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X20','kor',5,'u4',ARRAY['K5-2-u4-C20']::text[],'내 의견이 그대로 뽑히지 않으면 토의에서 졌다고 여긴다','내 생각도 들어 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X21','kor',5,'u4',ARRAY['K5-2-u4-C21']::text[],'모두 좋다고 맞장구만 치면 좋은 토의라고 여긴다','따져야 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X22','kor',5,'u4',ARRAY['K5-2-u4-C22']::text[],'사회자는 자기 마음에 드는 의견으로 정해 주는 사람이라고 여긴다','안내하고 정리해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X23','kor',5,'u4',ARRAY['K5-2-u4-C23']::text[],'학급 토의 절차의 차례를 섞거나 한 절차를 빠뜨린다','주제 → 마련 → 나누기 → 모으기 → 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X24','kor',5,'u4',ARRAY['K5-2-u4-C24']::text[],'의견 조정하기가 학급 토의 절차의 어디에 드는지 모르고 다른 절차에 넣는다','의견 모으기 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X25','kor',5,'u4',ARRAY['K5-2-u4-C25']::text[],'의견이 많아도 정리하지 않고 말로만 오가게 둔다','칠판에 한눈에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X26','kor',5,'u4',ARRAY['K5-2-u4-C26']::text[],'학급 토의는 몇몇 친구만 말하고 나머지는 듣기만 하면 된다고 여긴다','모두가 참여') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X27','kor',5,'u4',ARRAY['K5-2-u4-C27']::text[],'회의와 토의는 정하는 방법이 똑같다고 여기거나 토의도 늘 손을 들어 바로 정한다고 여긴다','토의는 조정으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X28','kor',5,'u4',ARRAY['K5-2-u4-C28']::text[],'정한 의견이 내 의견과 다르면 따르지 않거나, 한 번 정하면 절대 바꿀 수 없다고 여긴다','함께 실천, 다시 토의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X29','kor',5,'u4',ARRAY['K5-2-u4-C29']::text[],'소중히 여기는 것이 달라 부딪치면 한쪽을 나쁜 사람으로 여긴다','서로 다른 가치') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X30','kor',5,'u4',ARRAY['K5-2-u4-C30']::text[],'서로 다른 가치가 부딪치면 더 옳은 한쪽만 골라 이기게 해야 한다고 여긴다','존중하고 양보해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X31','kor',5,'u4',ARRAY['K5-2-u4-C31']::text[],'주변의 문제는 어른들만 풀 수 있어 어린이와 관계없다고 여긴다','우리도 도울 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X32','kor',5,'u4',ARRAY['K5-2-u4-C32']::text[],'자료를 찾지 않고 짐작만으로 까닭을 대거나 크게 말하면 타당해진다고 여긴다','자료로 다듬어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X33','kor',5,'u4',ARRAY['K5-2-u4-C33']::text[],'정한 의견을 누구에게 어떻게 알릴지 정하지 않고 「알린다」로만 끝낸다','누구에게 · 어떻게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X34','kor',5,'u4',ARRAY['K5-2-u4-C35']::text[],'의견을 정한 뒤 다른 생각이 남아 있는지 확인하지 않는다','이견 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X35','kor',5,'u4',ARRAY['K5-2-u4-C34']::text[],'학교 문제 토의에서 되돌아보기를 빼먹거나 여섯 단계의 차례를 섞는다','마지막은 되돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X36','kor',5,'u4',ARRAY['K5-2-u4-C36']::text[],'합의점이 막히면 생각 도구를 쓰지 않고 포기하거나 한 의견만 고른다','바꾸기 · 합치기 · 빼기 · 순서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X37','kor',5,'u4',ARRAY['K5-2-u4-C37']::text[],'토의 되돌아보기를 누구 잘못인지 따지는 시간으로 여긴다','함께 노력할 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X38','kor',5,'u4',ARRAY['K5-2-u4-C38']::text[],'토의에는 처음부터 정해진 정답 의견이 있어 그것을 맞히기만 하면 된다고 여긴다','과정에서 나아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-2-u4-X39','kor',5,'u4',ARRAY['K5-2-u4-C39']::text[],'외래어와 순화어를 짝짓지 못하거나 순화어 쓰기를 장난스럽게 여긴다','누구나 알기 쉬운 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#1','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C2',1,'mc','auto','여럿이 함께 문제를 풀 방법을 찾는 말하기를 무엇이라고 하나요?',ARRAY['K5-2-u4-X02','K5-2-u4-X06']::text[],false,'{"seq":1,"concept":"K5-2-u4-C2","difficulty":1,"kind":"mc","stem":"여럿이 함께 문제를 풀 방법을 찾는 말하기를 무엇이라고 하나요?","options":[{"t":"토의","correct":true},{"t":"토론","mis":"K5-2-u4-X02"},{"t":"연설","mis":"K5-2-u4-X02"},{"t":"면담","mis":"K5-2-u4-X06"}],"explanation":["토론은 찬성과 반대로 맞서는 말하기예요.","여러 사람 앞에서 혼자 주장하는 말이에요.","함께 방법을 찾는 말하기는 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#2','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C3',1,'mc','auto','서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일을 무엇이라고 하나요?',ARRAY['K5-2-u4-X03','K5-2-u4-X08','K5-2-u4-X14']::text[],false,'{"seq":2,"concept":"K5-2-u4-C3","difficulty":1,"kind":"mc","stem":"서로 다른 의견을 견주고 고쳐 가며 모두가 받아들일 만한 의견을 찾는 일을 무엇이라고 하나요?","options":[{"t":"의견 조정","correct":true},{"t":"의견 버리기","mis":"K5-2-u4-X03"},{"t":"목소리 겨루기","mis":"K5-2-u4-X08"},{"t":"손들기 놀이","mis":"K5-2-u4-X14"}],"explanation":["내 의견을 버리는 일이 아니에요.","목소리로 정하지 않아요.","견주고 고쳐 가는 일이 의견 조정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#3','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C1',1,'mc','auto','두 대표가 함께 풀려고 하는 문제는 무엇인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X16']::text[],false,'{"seq":3,"concept":"K5-2-u4-C1","difficulty":1,"kind":"mc","stem":"두 대표가 함께 풀려고 하는 문제는 무엇인가요?","options":[{"t":"비 오는 날 체육관을 쓰는 방법","correct":true},{"t":"급식 차례를 바꾸는 방법","mis":"K5-2-u4-X06"},{"t":"교실 청소 당번을 정하는 방법","mis":"K5-2-u4-X06"},{"t":"새 체육관을 짓는 방법","mis":"K5-2-u4-X16"}],"explanation":["두 대표의 말에 없어요.","두 대표의 말에 없어요.","두 대표 모두 비 오는 날 체육관 이야기를 했어요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#4','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C1',1,'ox','auto','같은 문제에 서로 다른 의견이 나오는 것은 자연스러운 일이에요.',ARRAY['K5-2-u4-X01']::text[],false,'{"seq":4,"concept":"K5-2-u4-C1","difficulty":1,"kind":"ox","stem":"같은 문제에 서로 다른 의견이 나오는 것은 자연스러운 일이에요.","answer":"O","reason_options":[{"t":"사람마다 생각과 겪은 일이 달라 여러 의견이 나올 수 있기 때문에","correct":true},{"t":"의견이 다르면 누군가 잘못 생각한 것이기 때문에","mis":"K5-2-u4-X01"}],"mis":"K5-2-u4-X01","explanation":["생각은 저마다 달라요.","틀린 쪽이 있는 것이 아니에요.","다른 의견은 자연스러워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#5','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C4',2,'mc','auto','저학년 대표가 든 까닭은 무엇인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X04']::text[],false,'{"seq":5,"concept":"K5-2-u4-C4","difficulty":2,"kind":"mc","stem":"저학년 대표가 든 까닭은 무엇인가요?","options":[{"t":"모든 학년이 고르게 쓸 수 있어서","correct":true},{"t":"큰 학년이 질서를 잘 지켜서","mis":"K5-2-u4-X06"},{"t":"저학년이 먼저 와서","mis":"K5-2-u4-X04"},{"t":"체육관이 너무 좁아서","mis":"K5-2-u4-X06"}],"explanation":["고학년 대표의 까닭이에요.","말하지 않은 까닭이에요.","고르게 쓰자는 까닭을 들었어요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#6','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C7',2,'mc','auto','의견을 견주는 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X07']::text[],false,'{"seq":6,"concept":"K5-2-u4-C7","difficulty":2,"kind":"mc","stem":"의견을 견주는 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"목소리가 가장 큰 사람의 의견인가?","correct":true},{"t":"우리가 실천할 수 있는 방법인가?","mis":"K5-2-u4-X07"},{"t":"문제를 푸는 데 효과가 있는 방법인가?","mis":"K5-2-u4-X07"},{"t":"여러 사람에게 도움이 되는 방법인가?","mis":"K5-2-u4-X07"}],"explanation":["알맞은 기준이에요.","알맞은 기준이에요.","목소리 크기는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#7','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C5',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C5","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"의견 조정 방법","r":"토의 대화를 보며 차례 알기"},{"l":"학급 토의","r":"반 전체가 절차에 따라 정하기"},{"l":"주변의 문제","r":"서로 다른 가치를 존중하며 풀기"}],"mis":"K5-2-u4-X05","explanation":["방법부터 알아요.","반 전체가 함께해요.","교실 밖 문제까지 풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#8','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C2',2,'error','auto','두 의견을 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X04','K5-2-u4-X03']::text[],false,'{"seq":8,"concept":"K5-2-u4-C2","difficulty":2,"kind":"error","stem":"두 의견을 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「어느 쪽이 이기는지 끝까지 겨뤄 보자.」","correct":true,"mis_target":"K5-2-u4-X02"},{"t":"「두 의견의 까닭을 먼저 들어 보자.」","mis":"K5-2-u4-X04"},{"t":"「모두가 기분 좋게 쓸 방법을 함께 찾자.」","mis":"K5-2-u4-X03"}],"explanation":["까닭부터 들어요.","함께 찾는 자리예요.","토의는 겨루는 자리가 아니에요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#9','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C3',2,'mc','auto','의견을 조정한다는 것에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X08','K5-2-u4-X01']::text[],false,'{"seq":9,"concept":"K5-2-u4-C3","difficulty":2,"kind":"mc","stem":"의견을 조정한다는 것에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로의 의견을 견주어 모두가 받아들일 만한 쪽으로 고쳐 가는 것","correct":true},{"t":"한쪽 의견을 무조건 버리는 것","mis":"K5-2-u4-X03"},{"t":"목소리가 큰 쪽을 따르는 것","mis":"K5-2-u4-X08"},{"t":"의견이 다르면 토의를 그만두는 것","mis":"K5-2-u4-X01"}],"explanation":["버리는 것이 아니에요.","목소리로 정하지 않아요.","견주고 고쳐 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_basic#10','kor',5,2,'u4','L01','g5_2_kor_u4_L01_basic','lesson_basic','K5-2-u4-C4',3,'mc','auto','「그냥 좋아서요.」라고만 말한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X04','K5-2-u4-X01','K5-2-u4-X08']::text[],false,'{"seq":10,"concept":"K5-2-u4-C4","difficulty":3,"kind":"mc","stem":"「그냥 좋아서요.」라고만 말한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 의견이 좋은 까닭을 함께 말해 주면 견주기 쉬워.」","correct":true},{"t":"「좋으면 됐지, 까닭은 필요 없어.」","mis":"K5-2-u4-X04"},{"t":"「네 의견은 틀렸으니 다시 말해.」","mis":"K5-2-u4-X01"},{"t":"「목소리를 더 크게 하면 뽑힐 거야.」","mis":"K5-2-u4-X08"}],"explanation":["까닭이 있어야 견줘요.","틀린 의견이 아니에요.","까닭을 함께 말하도록 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#1','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C3',2,'ox','auto','의견을 조정하면 내 의견은 모두 버려야 해요.',ARRAY['K5-2-u4-X03']::text[],false,'{"seq":1,"concept":"K5-2-u4-C3","difficulty":2,"kind":"ox","stem":"의견을 조정하면 내 의견은 모두 버려야 해요.","answer":"X","reason_options":[{"t":"장점은 살리고 단점은 보완해 더 나은 의견으로 고쳐 가는 것이기 때문에","correct":true},{"t":"모두의 의견을 들으려면 내 생각은 없어야 하기 때문에","mis":"K5-2-u4-X03"}],"mis":"K5-2-u4-X03","explanation":["버리지 않아요.","내 생각도 함께 들어가요.","살리고 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#2','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C5',2,'mc','auto','이 단원에서 의견을 조정하는 방법을 안 다음에 하는 활동은 어느 것인가요?',ARRAY['K5-2-u4-X05']::text[],false,'{"seq":2,"concept":"K5-2-u4-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 의견을 조정하는 방법을 안 다음에 하는 활동은 어느 것인가요?","options":[{"t":"모둠에서 의견을 조정하며 토의하기","correct":true},{"t":"우리 학교 문제 실천을 맨 먼저 하기","mis":"K5-2-u4-X05"},{"t":"표준어와 방언 알아보기","mis":"K5-2-u4-X05"},{"t":"방언 지도 만들기","mis":"K5-2-u4-X05"}],"explanation":["실천은 맨 끝이에요.","지난 단원이에요.","방법 다음은 모둠 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#3','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C1',3,'mc','auto','「의견이 서로 다르니 이 토의는 실패야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X01','K5-2-u4-X08','K5-2-u4-X26']::text[],false,'{"seq":3,"concept":"K5-2-u4-C1","difficulty":3,"kind":"mc","stem":"「의견이 서로 다르니 이 토의는 실패야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「생각이 다른 게 자연스러우니 견주어 보며 더 나은 방법을 찾자.」","correct":true},{"t":"「맞아, 의견이 다르면 토의할 필요가 없어.」","mis":"K5-2-u4-X01"},{"t":"「목소리 큰 쪽으로 빨리 정하자.」","mis":"K5-2-u4-X08"},{"t":"「다른 의견을 낸 친구를 빼고 정하자.」","mis":"K5-2-u4-X26"}],"explanation":["다르니까 토의해요.","목소리로 정하지 않아요.","다른 의견은 견주어 볼 재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#4','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C7',3,'mc','auto','「고학년이 먼저 쓰자」 의견을 「여러 사람에게 도움이 되는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X07','K5-2-u4-X10']::text[],false,'{"seq":4,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"「고학년이 먼저 쓰자」 의견을 「여러 사람에게 도움이 되는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"저학년은 비 오는 날 체육관을 쓰기 어려워 모든 학년에 도움이 되지는 않는다","correct":true},{"t":"고학년이 말했으니 가장 좋은 의견이다","mis":"K5-2-u4-X08"},{"t":"기준으로 따질 필요 없이 바로 정하면 된다","mis":"K5-2-u4-X07"},{"t":"단점이 하나도 없는 의견이다","mis":"K5-2-u4-X10"}],"explanation":["말한 사람이 기준이 아니에요.","기준으로 따져요.","누구에게 도움이 되는지 살펴요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#5','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C3',3,'error','auto','토의를 마친 뒤 친구들이 나눈 말이에요. 의견 조정을 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X12','K5-2-u4-X11']::text[],false,'{"seq":5,"concept":"K5-2-u4-C3","difficulty":3,"kind":"error","stem":"토의를 마친 뒤 친구들이 나눈 말이에요. 의견 조정을 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「내 의견이 조금 바뀌었으니 내가 진 거야.」","correct":true,"mis_target":"K5-2-u4-X03"},{"t":"「두 의견의 좋은 점을 모아서 더 나아졌어.」","mis":"K5-2-u4-X12"},{"t":"「서로 조금씩 양보하니 모두 받아들일 수 있었어.」","mis":"K5-2-u4-X11"}],"explanation":["알맞게 이해했어요.","알맞게 이해했어요.","바뀐 것은 진 것이 아니라 나아진 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#6','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C2',3,'mc','auto','토의에 대한 설명으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X38','K5-2-u4-X08']::text[],false,'{"seq":6,"concept":"K5-2-u4-C2","difficulty":3,"kind":"mc","stem":"토의에 대한 설명으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여럿이 함께 더 나은 방법을 찾는 자리이다","correct":true},{"t":"누가 말을 잘하는지 겨루는 자리이다","mis":"K5-2-u4-X02"},{"t":"선생님이 정답을 알려 주는 자리이다","mis":"K5-2-u4-X38"},{"t":"먼저 말한 사람의 의견을 따르는 자리이다","mis":"K5-2-u4-X08"}],"explanation":["겨루지 않아요.","정해진 정답은 없어요.","함께 찾는 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#7','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C4',3,'mc','auto','의견을 말할 때 까닭이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X04','K5-2-u4-X26']::text[],false,'{"seq":7,"concept":"K5-2-u4-C4","difficulty":3,"kind":"mc","stem":"의견을 말할 때 까닭이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"까닭이 있어야 다른 의견과 견주어 따져 볼 수 있어서","correct":true},{"t":"까닭이 길수록 뽑히기 쉬워서","mis":"K5-2-u4-X04"},{"t":"까닭을 말하면 다른 친구가 말을 못 해서","mis":"K5-2-u4-X26"},{"t":"까닭은 선생님만 들으면 되어서","mis":"K5-2-u4-X04"}],"explanation":["길이가 중요하지 않아요.","모두가 말해야 해요.","견주려면 까닭이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#8','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C1',4,'essay','teacher','두 대표의 의견을 각각 쓰고, 두 의견의 좋은 점을 살린 내 의견을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C1","difficulty":4,"kind":"essay","stem":"두 대표의 의견을 각각 쓰고, 두 의견의 좋은 점을 살린 내 의견을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 고학년 대표는 고학년이 먼저 쓰자고 했고, 저학년 대표는 요일을 학년별로 정하자고 했다. 나는 요일을 학년별로 나누되, 고학년이 쓰는 날에는 저학년 몇 반도 함께 쓰며 고학년이 질서를 도와주자고 하겠다. 모든 학년이 고르게 쓰면서 질서도 지킬 수 있기 때문이다.","scoring_points":["두 의견을 바르게 썼는가","두 의견의 좋은 점을 살렸는가","내 의견에 까닭이 있는가"]},"explanation":["두 의견을 찾아요.","좋은 점을 살려요.","까닭을 덧붙여요."],"asset":{"type":"speech","turns":[{"who":"고학년 대표","text":"비 오는 날 체육관은 고학년이 먼저 쓰면 좋겠습니다. 큰 학년이 질서를 잘 지키기 때문입니다."},{"who":"저학년 대표","text":"체육관 쓰는 요일을 학년별로 정하면 좋겠습니다. 그래야 모든 학년이 고르게 쓸 수 있습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#9','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C3',4,'essay','teacher','의견을 조정해 정하는 것과 처음부터 손을 들어 많은 쪽으로 정하는 것을 견주어, 의견을 조정하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C3","difficulty":4,"kind":"essay","stem":"의견을 조정해 정하는 것과 처음부터 손을 들어 많은 쪽으로 정하는 것을 견주어, 의견을 조정하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 손을 들어 바로 정하면 빠르지만 적은 쪽 친구들의 생각은 반영되지 않는다. 의견을 조정하면 시간이 걸려도 여러 의견의 좋은 점을 살려 더 많은 친구가 받아들이고 함께 실천할 수 있다.","scoring_points":["손을 들어 정하는 방법의 특징을 썼는가","의견 조정의 특징을 썼는가","의견 조정의 좋은 점을 썼는가"]},"explanation":["빠르지만 아쉬움이 있어요.","함께 고쳐 가요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L01_challenge#10','kor',5,2,'u4','L01','g5_2_kor_u4_L01_challenge','lesson_challenge','K5-2-u4-C5',4,'essay','teacher','의견이 맞지 않아 정하기 어려웠던 경험을 하나 쓰고, 그때 어떤 말이나 행동이 있었으면 좋았을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C5","difficulty":4,"kind":"essay","stem":"의견이 맞지 않아 정하기 어려웠던 경험을 하나 쓰고, 그때 어떤 말이나 행동이 있었으면 좋았을지 쓰세요.","answer_guide":{"answer":"예: 모둠 발표 주제를 정할 때 두 친구가 서로 자기 주제만 하자고 해서 시간이 다 지나 버렸다. 그때 누가 맞는지 따지기보다 「두 주제의 좋은 점을 먼저 말해 보자.」라고 했다면 함께 정할 수 있었을 것 같다.","scoring_points":["경험을 구체적으로 썼는가","필요했던 말이나 행동을 썼는가","탓하기가 아니라 방법을 찾았는가"]},"explanation":["경험을 떠올려요.","필요한 말을 찾아요.","탓하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#1','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C6',1,'mc','auto','토의를 통해 풀려는 문제는 무엇인가요?',ARRAY['K5-2-u4-X06']::text[],false,'{"seq":1,"concept":"K5-2-u4-C6","difficulty":1,"kind":"mc","stem":"토의를 통해 풀려는 문제는 무엇인가요?","options":[{"t":"복도에서 뛰다가 부딪치는 문제","correct":true},{"t":"급식이 남는 문제","mis":"K5-2-u4-X06"},{"t":"교실이 더러운 문제","mis":"K5-2-u4-X06"},{"t":"포스터가 찢어지는 문제","mis":"K5-2-u4-X06"}],"explanation":["토의에 없는 문제예요.","토의에 없는 문제예요.","사회자가 처음에 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간마다 복도에서 뛰다가 부딪치는 일이 잦습니다. 복도를 안전하게 쓰는 방법을 토의해 봅시다."},{"who":"도윤","text":"복도 지킴이를 정하면 좋겠습니다. 뛰는 친구에게 바로 「걸어 주세요.」라고 알려 줄 수 있기 때문입니다."},{"who":"서아","text":"복도 안전 포스터를 만들어 붙이면 어떨까요? 오가며 볼 때마다 조심하게 될 것입니다."},{"who":"지후","text":"복도에서 뛴 사람은 다음 쉬는 시간에 교실에만 있기로 하면 좋겠습니다. 그러면 금방 줄어들 것입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#2','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C7',1,'mc','auto','의견을 조정할 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X07']::text[],false,'{"seq":2,"concept":"K5-2-u4-C7","difficulty":1,"kind":"mc","stem":"의견을 조정할 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"의견을 검토할 기준 마련하기","correct":true},{"t":"합의점 찾기","mis":"K5-2-u4-X13"},{"t":"실천할 의견 정하기","mis":"K5-2-u4-X13"},{"t":"마음에 드는 의견 고르기","mis":"K5-2-u4-X07"}],"explanation":["마지막 차례예요.","조정을 마친 뒤예요.","기준이 있어야 견줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#3','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C11',1,'mc','auto','서로 조금씩 양보해 의견이 하나로 모이는 자리를 무엇이라고 하나요?',ARRAY['K5-2-u4-X11','K5-2-u4-X10','K5-2-u4-X07']::text[],false,'{"seq":3,"concept":"K5-2-u4-C11","difficulty":1,"kind":"mc","stem":"서로 조금씩 양보해 의견이 하나로 모이는 자리를 무엇이라고 하나요?","options":[{"t":"합의점","correct":true},{"t":"출발점","mis":"K5-2-u4-X11"},{"t":"단점","mis":"K5-2-u4-X10"},{"t":"기준","mis":"K5-2-u4-X07"}],"explanation":["처음 자리예요.","아쉬운 점이에요.","의견이 모이는 자리가 합의점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#4','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C10',1,'ox','auto','토의에서 친구 의견의 단점을 말하는 것은 친구를 비난하는 일이에요.',ARRAY['K5-2-u4-X11']::text[],false,'{"seq":4,"concept":"K5-2-u4-C10","difficulty":1,"kind":"ox","stem":"토의에서 친구 의견의 단점을 말하는 것은 친구를 비난하는 일이에요.","answer":"X","reason_options":[{"t":"단점을 따져야 더 나은 의견을 찾을 수 있기 때문에","correct":true},{"t":"단점을 들으면 친구가 속상하기 때문에","mis":"K5-2-u4-X11"}],"mis":"K5-2-u4-X11","explanation":["단점 말하기는 필요한 과정이에요.","의견을 두고 말해요.","최선의 의견을 찾기 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#5','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C6',2,'mc','auto','서아가 제안한 의견은 무엇인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X16']::text[],false,'{"seq":5,"concept":"K5-2-u4-C6","difficulty":2,"kind":"mc","stem":"서아가 제안한 의견은 무엇인가요?","options":[{"t":"복도 안전 포스터를 만들어 붙이자","correct":true},{"t":"복도 지킴이를 정하자","mis":"K5-2-u4-X06"},{"t":"뛴 사람은 교실에만 있자","mis":"K5-2-u4-X06"},{"t":"복도를 넓히자","mis":"K5-2-u4-X16"}],"explanation":["도윤이의 의견이에요.","지후의 의견이에요.","서아는 포스터를 제안했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간마다 복도에서 뛰다가 부딪치는 일이 잦습니다. 복도를 안전하게 쓰는 방법을 토의해 봅시다."},{"who":"도윤","text":"복도 지킴이를 정하면 좋겠습니다. 뛰는 친구에게 바로 「걸어 주세요.」라고 알려 줄 수 있기 때문입니다."},{"who":"서아","text":"복도 안전 포스터를 만들어 붙이면 어떨까요? 오가며 볼 때마다 조심하게 될 것입니다."},{"who":"지후","text":"복도에서 뛴 사람은 다음 쉬는 시간에 교실에만 있기로 하면 좋겠습니다. 그러면 금방 줄어들 것입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#6','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C9',2,'mc','auto','「교실에 남기」 의견의 단점으로 표에 나온 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X09']::text[],false,'{"seq":6,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"「교실에 남기」 의견의 단점으로 표에 나온 것은 어느 것인가요?","options":[{"t":"쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","correct":true},{"t":"뛰는 일이 빨리 줄 수 있다","mis":"K5-2-u4-X10"},{"t":"우리가 쉽게 만들 수 있다","mis":"K5-2-u4-X09"},{"t":"단점은 하나도 없다","mis":"K5-2-u4-X10"}],"explanation":["장점이에요.","포스터의 장점이에요.","표의 단점 칸을 봐요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#7','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C9',2,'match','auto','의견을 조정하는 차례와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C9","difficulty":2,"kind":"match","stem":"의견을 조정하는 차례와 하는 일을 알맞게 이으세요.","pairs":[{"l":"기준 마련","r":"무엇으로 견줄지 함께 정하기"},{"l":"장단점 검토","r":"기준에 비추어 좋은 점과 아쉬운 점 따지기"},{"l":"합의점 찾기","r":"장점을 살려 모두가 동의할 의견 만들기"}],"mis":"K5-2-u4-X13","explanation":["먼저 기준을 정해요.","기준으로 따져요.","장점을 살려 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#8','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C10',2,'error','auto','단점을 말하는 친구들이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X09','K5-2-u4-X10']::text[],false,'{"seq":8,"concept":"K5-2-u4-C10","difficulty":2,"kind":"error","stem":"단점을 말하는 친구들이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「지후는 늘 엉뚱한 말만 하니까 이번 의견도 별로야.」","correct":true,"mis_target":"K5-2-u4-X11"},{"t":"「지킴이를 몇 명만 맡으면 힘들 것 같아.」","mis":"K5-2-u4-X09"},{"t":"「포스터는 시간이 지나면 눈에 덜 띌 것 같아.」","mis":"K5-2-u4-X10"}],"explanation":["의견을 두고 말했어요.","의견을 두고 말했어요.","사람이 아니라 의견을 두고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#9','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C12',2,'mc','auto','표의 합의점은 어떻게 만든 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X08','K5-2-u4-X03']::text[],false,'{"seq":9,"concept":"K5-2-u4-C12","difficulty":2,"kind":"mc","stem":"표의 합의점은 어떻게 만든 것인가요?","options":[{"t":"두 의견의 장점을 합쳤다","correct":true},{"t":"한 의견만 그대로 골랐다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 의견을 따랐다","mis":"K5-2-u4-X08"},{"t":"세 의견을 모두 버렸다","mis":"K5-2-u4-X03"}],"explanation":["그대로 고르지 않았어요.","목소리로 정하지 않았어요.","지킴이와 포스터를 합쳤어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_basic#10','kor',5,2,'u4','L02','g5_2_kor_u4_L02_basic','lesson_basic','K5-2-u4-C13',3,'mc','auto','장단점을 따지다 보니 기준이 부족하다는 것을 알았을 때 가장 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X01','K5-2-u4-X08']::text[],false,'{"seq":10,"concept":"K5-2-u4-C13","difficulty":3,"kind":"mc","stem":"장단점을 따지다 보니 기준이 부족하다는 것을 알았을 때 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"기준 마련하기로 되돌아가 기준을 더한다","correct":true},{"t":"차례를 거꾸로 갈 수 없으니 그대로 정한다","mis":"K5-2-u4-X13"},{"t":"토의를 그만둔다","mis":"K5-2-u4-X01"},{"t":"가장 먼저 나온 의견으로 정한다","mis":"K5-2-u4-X08"}],"explanation":["되돌아갈 수 있어요.","그만두지 않아요.","필요하면 앞 차례로 돌아가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#1','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C13',2,'ox','auto','의견을 조정하는 차례는 한 방향으로만 가야 해서 앞 차례로 되돌아갈 수 없어요.',ARRAY['K5-2-u4-X13']::text[],false,'{"seq":1,"concept":"K5-2-u4-C13","difficulty":2,"kind":"ox","stem":"의견을 조정하는 차례는 한 방향으로만 가야 해서 앞 차례로 되돌아갈 수 없어요.","answer":"X","reason_options":[{"t":"필요하면 앞 차례로 되돌아가 다시 따져 볼 수 있기 때문에","correct":true},{"t":"차례를 바꾸면 토의가 틀리기 때문에","mis":"K5-2-u4-X13"}],"mis":"K5-2-u4-X13","explanation":["고정된 길이 아니에요.","오가며 조정해요.","되돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#2','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C8',2,'mc','auto','복도 문제를 토의할 때 더할 수 있는 검토 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X09','K5-2-u4-X16']::text[],false,'{"seq":2,"concept":"K5-2-u4-C8","difficulty":2,"kind":"mc","stem":"복도 문제를 토의할 때 더할 수 있는 검토 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"돈이 많이 들지 않는가?","correct":true},{"t":"누가 먼저 말했는가?","mis":"K5-2-u4-X08"},{"t":"글자 수가 적은가?","mis":"K5-2-u4-X09"},{"t":"가장 재미있게 들리는가?","mis":"K5-2-u4-X16"}],"explanation":["차례는 기준이 아니에요.","글자 수는 관계없어요.","비용도 기준이 될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#3','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C14',3,'mc','auto','끝내 합의점을 찾지 못해 손을 들어 많은 쪽으로 정했을 때의 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X14','K5-2-u4-X01']::text[],false,'{"seq":3,"concept":"K5-2-u4-C14","difficulty":3,"kind":"mc","stem":"끝내 합의점을 찾지 못해 손을 들어 많은 쪽으로 정했을 때의 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 전에 장단점을 따진 덕분에 모두가 의견을 잘 알고 정할 수 있었다","correct":true},{"t":"토의는 헛수고였다","mis":"K5-2-u4-X14"},{"t":"처음부터 손을 들어 정했으면 됐다","mis":"K5-2-u4-X14"},{"t":"적은 쪽 친구들의 생각은 틀린 것이다","mis":"K5-2-u4-X01"}],"explanation":["헛수고가 아니에요.","목적은 합의점이에요.","따져 본 과정이 쓸모 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#4','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C10',3,'mc','auto','단점을 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X10']::text[],false,'{"seq":4,"concept":"K5-2-u4-C10","difficulty":3,"kind":"mc","stem":"단점을 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「포스터는 쉽게 만들 수 있지만, 오래 지나면 눈에 덜 띌 것 같아.」","correct":true},{"t":"「포스터 같은 건 아무도 안 봐.」","mis":"K5-2-u4-X11"},{"t":"「서아 의견은 늘 별로야.」","mis":"K5-2-u4-X11"},{"t":"「단점은 말하지 않을게.」","mis":"K5-2-u4-X10"}],"explanation":["함부로 깎아내리는 말이에요.","사람을 두고 한 말이에요.","장점도 인정하고 의견을 두고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#5','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C12',3,'error','auto','합의점에 대한 친구들의 말이에요. 잘못 이해한 말은 어느 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X11','K5-2-u4-X19']::text[],false,'{"seq":5,"concept":"K5-2-u4-C12","difficulty":3,"kind":"error","stem":"합의점에 대한 친구들의 말이에요. 잘못 이해한 말은 어느 것인가요?","options":[{"t":"「합의점은 세 의견 가운데 하나를 고르는 것뿐이야.」","correct":true,"mis_target":"K5-2-u4-X12"},{"t":"「두 의견을 합쳐 새 의견을 만들 수도 있어.」","mis":"K5-2-u4-X11"},{"t":"「두 가지 의견을 함께 고를 수도 있어.」","mis":"K5-2-u4-X19"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","합의점은 여러 모습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#6','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C7',3,'mc','auto','「지킴이」 의견을 「실천할 수 있는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X04','K5-2-u4-X08','K5-2-u4-X11']::text[],false,'{"seq":6,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"「지킴이」 의견을 「실천할 수 있는가」 기준으로 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"몇 명만 늘 맡으면 힘들어 오래 실천하기 어려울 수 있다","correct":true},{"t":"지킴이라는 이름이 멋져서 실천하기 쉽다","mis":"K5-2-u4-X04"},{"t":"도윤이가 말했으니 실천할 수 있다","mis":"K5-2-u4-X08"},{"t":"기준으로 따지면 친구가 속상하다","mis":"K5-2-u4-X11"}],"explanation":["이름은 까닭이 아니에요.","말한 사람이 기준이 아니에요.","실천할 수 있는지 따져요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#7','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C11',3,'mc','auto','지킴이 의견이 「모두 돌아가며 맡기」로 바뀌어 합의점에 들어갔어요. 이를 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X20','K5-2-u4-X38']::text[],false,'{"seq":7,"concept":"K5-2-u4-C11","difficulty":3,"kind":"mc","stem":"지킴이 의견이 「모두 돌아가며 맡기」로 바뀌어 합의점에 들어갔어요. 이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"지킴이 의견의 단점이 보완되어 더 좋아졌다","correct":true},{"t":"도윤이의 의견은 사라졌다","mis":"K5-2-u4-X03"},{"t":"도윤이가 토의에서 졌다","mis":"K5-2-u4-X20"},{"t":"지킴이 의견은 처음부터 정답이었다","mis":"K5-2-u4-X38"}],"explanation":["의견은 남아 있어요.","진 것이 아니에요.","단점을 보완해 나아졌어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#8','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C9',4,'essay','teacher','지후의 의견을 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C9","difficulty":4,"kind":"essay","stem":"지후의 의견을 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.","answer_guide":{"answer":"예: 효과적인가 기준으로 보면 뛰는 일이 빨리 줄 수 있다는 장점이 있다. 여러 사람에게 도움이 되는가 기준으로 보면 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다는 단점이 있다.","scoring_points":["기준 두 가지를 밝혔는가","기준에 비추어 장점을 썼는가","기준에 비추어 단점을 썼는가"]},"explanation":["기준을 골라요.","장점을 써요.","단점도 의견을 두고 써요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간마다 복도에서 뛰다가 부딪치는 일이 잦습니다. 복도를 안전하게 쓰는 방법을 토의해 봅시다."},{"who":"도윤","text":"복도 지킴이를 정하면 좋겠습니다. 뛰는 친구에게 바로 「걸어 주세요.」라고 알려 줄 수 있기 때문입니다."},{"who":"서아","text":"복도 안전 포스터를 만들어 붙이면 어떨까요? 오가며 볼 때마다 조심하게 될 것입니다."},{"who":"지후","text":"복도에서 뛴 사람은 다음 쉬는 시간에 교실에만 있기로 하면 좋겠습니다. 그러면 금방 줄어들 것입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#9','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C11',4,'essay','teacher','세 의견의 장점을 살려 모두가 동의할 만한 합의점을 새로 만들어 쓰고, 어떤 의견의 장점을 살렸는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C11","difficulty":4,"kind":"essay","stem":"세 의견의 장점을 살려 모두가 동의할 만한 합의점을 새로 만들어 쓰고, 어떤 의견의 장점을 살렸는지 쓰세요.","answer_guide":{"answer":"예: 지킴이를 모두 돌아가며 맡고, 복도 모퉁이에 포스터를 붙이고, 일주일 동안 잘 걸은 날이 많으면 학급 칭찬 붙임딱지를 받는다. 지킴이의 바로 알려 주는 점과 포스터의 쉽게 만드는 점, 교실에 남기의 빨리 줄어드는 점을 벌 대신 칭찬으로 바꾸어 살렸다.","scoring_points":["합의점을 썼는가","살린 장점을 밝혔는가","여럿이 동의할 만한가"]},"explanation":["새 합의점을 써요.","살린 장점을 밝혀요.","모두가 받아들일 만한지 봐요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가","지킴이 — 장점: 뛰는 친구에게 바로 알려 줄 수 있다","지킴이 — 단점: 몇 명만 늘 맡으면 힘들다","포스터 — 장점: 우리가 쉽게 만들 수 있다","포스터 — 단점: 붙인 뒤 효과가 오래 이어지기 어렵다","교실에 남기 — 장점: 뛰는 일이 빨리 줄 수 있다","교실에 남기 — 단점: 쉬는 시간을 빼앗겨 반 분위기가 나빠질 수 있다","합의점 — 지킴이는 모두 돌아가며 맡고, 포스터도 함께 붙인다"],"title":"복도 토의 장단점 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L02_challenge#10','kor',5,2,'u4','L02','g5_2_kor_u4_L02_challenge','lesson_challenge','K5-2-u4-C13',4,'essay','teacher','의견을 조정하는 세 차례를 쓰고, 조정이 막힐 때 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C13","difficulty":4,"kind":"essay","stem":"의견을 조정하는 세 차례를 쓰고, 조정이 막힐 때 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 의견을 검토할 기준 마련하기, 의견의 장점과 단점 검토하기, 합의점 찾기 차례로 한다. 합의점이 보이지 않으면 앞 차례로 되돌아가 기준을 더하거나 장단점을 다시 따져 본다.","scoring_points":["세 차례를 바르게 썼는가","차례를 알맞게 놓았는가","막힐 때 되돌아갈 수 있음을 썼는가"]},"explanation":["세 차례예요.","기준이 먼저예요.","되돌아갈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#1','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C15',1,'mc','auto','토의 주제로 정하기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15']::text[],false,'{"seq":1,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"토의 주제로 정하기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 신발장을 깔끔하게 쓸까?","correct":true},{"t":"신발장이 엉망이라 정말 싫다.","mis":"K5-2-u4-X15"},{"t":"신발장은 누가 어질렀어?","mis":"K5-2-u4-X15"},{"t":"신발장 정리는 내 일이 아니다.","mis":"K5-2-u4-X15"}],"explanation":["불평하는 말이에요.","탓하는 물음이에요.","함께 방법을 찾는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#2','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C16',1,'mc','auto','토의 주제를 고를 때 생각할 것이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u4-X16']::text[],false,'{"seq":2,"concept":"K5-2-u4-C16","difficulty":1,"kind":"mc","stem":"토의 주제를 고를 때 생각할 것이 아닌 것은 어느 것인가요?","options":[{"t":"가장 재미있게 들리는 문제인가?","correct":true},{"t":"우리와 관련이 있는 문제인가?","mis":"K5-2-u4-X16"},{"t":"우리가 직접 풀 수 있는 문제인가?","mis":"K5-2-u4-X16"},{"t":"가장 먼저 풀어야 할 문제인가?","mis":"K5-2-u4-X16"}],"explanation":["생각할 것이에요.","생각할 것이에요.","재미만으로 고르지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#3','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C17',1,'mc','auto','친구 의견을 듣고 궁금한 점을 묻는 것은 무엇을 하는 일인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X17','K5-2-u4-X18']::text[],false,'{"seq":3,"concept":"K5-2-u4-C17","difficulty":1,"kind":"mc","stem":"친구 의견을 듣고 궁금한 점을 묻는 것은 무엇을 하는 일인가요?","options":[{"t":"질문하며 듣기","correct":true},{"t":"맞장구만 치기","mis":"K5-2-u4-X21"},{"t":"못 들은 척하기","mis":"K5-2-u4-X17"},{"t":"끼어들어 말 끊기","mis":"K5-2-u4-X18"}],"explanation":["묻지 않는 일이에요.","듣지 않는 일이에요.","물으며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#4','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C20',1,'ox','auto','내 의견이 모둠 의견으로 뽑히지 않으면 토의에서 진 거예요.',ARRAY['K5-2-u4-X20']::text[],false,'{"seq":4,"concept":"K5-2-u4-C20","difficulty":1,"kind":"ox","stem":"내 의견이 모둠 의견으로 뽑히지 않으면 토의에서 진 거예요.","answer":"X","reason_options":[{"t":"함께 말하고 고친 과정 속에 내 생각도 들어 있기 때문에","correct":true},{"t":"토의는 의견이 뽑힌 사람이 이기는 자리이기 때문에","mis":"K5-2-u4-X20"}],"mis":"K5-2-u4-X20","explanation":["토의에는 이기고 짐이 없어요.","내 생각도 들어 있어요.","참여한 것이 소중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#5','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C15',2,'mc','auto','상황 ㉯를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X15']::text[],false,'{"seq":5,"concept":"K5-2-u4-C15","difficulty":2,"kind":"mc","stem":"상황 ㉯를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 실내화를 제자리에 꽂을까?","correct":true},{"t":"어떻게 하면 남는 우유를 줄일까?","mis":"K5-2-u4-X06"},{"t":"어떻게 하면 가위를 잘 챙길까?","mis":"K5-2-u4-X06"},{"t":"실내화를 어지른 사람은 누구일까?","mis":"K5-2-u4-X15"}],"explanation":["㉮의 주제예요.","㉰의 주제예요.","㉯는 신발장 문제예요."],"asset":{"type":"passage","lines":["㉮ 마시지 않은 우유가 많이 남아요.","㉯ 신발장에 실내화가 뒤죽박죽 꽂혀 있어요.","㉰ 모둠 바구니의 가위와 풀이 자꾸 없어져요."],"title":"학교에서 찾은 세 가지 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#6','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C17',2,'mc','auto','유나의 첫 번째 말은 어떤 일을 했나요?',ARRAY['K5-2-u4-X18','K5-2-u4-X21','K5-2-u4-X15']::text[],false,'{"seq":6,"concept":"K5-2-u4-C17","difficulty":2,"kind":"mc","stem":"유나의 첫 번째 말은 어떤 일을 했나요?","options":[{"t":"궁금한 점을 물어 이름표 의견의 빈틈을 채웠다","correct":true},{"t":"민재의 의견을 놀렸다","mis":"K5-2-u4-X18"},{"t":"민재의 의견에 맞장구만 쳤다","mis":"K5-2-u4-X21"},{"t":"토의 주제를 바꾸었다","mis":"K5-2-u4-X15"}],"explanation":["공손하게 물었어요.","맞장구가 아니에요.","질문으로 빈틈을 채웠어요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#7','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C16',2,'match','auto','주제를 고르는 기준과 알맞은 물음을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C16","difficulty":2,"kind":"match","stem":"주제를 고르는 기준과 알맞은 물음을 이으세요.","pairs":[{"l":"관련","r":"우리 반 친구들과 상관있는 일인가?"},{"l":"실천","r":"우리 손으로 직접 바꿀 수 있는가?"},{"l":"시급","r":"가장 먼저 풀어야 할 일인가?"}],"mis":"K5-2-u4-X16","explanation":["우리와 관련이 있어요.","직접 풀 수 있어요.","먼저 풀어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#8','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C18',2,'error','auto','현우의 의견에 한 질문들이에요. 알맞지 않은 질문은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":8,"concept":"K5-2-u4-C18","difficulty":2,"kind":"error","stem":"현우의 의견에 한 질문들이에요. 알맞지 않은 질문은 어느 것인가요?","options":[{"t":"「너는 왜 맨날 그런 말만 해?」","correct":true,"mis_target":"K5-2-u4-X18"},{"t":"「당번은 몇 명이 얼마 동안 맡아?」","mis":"K5-2-u4-X17"},{"t":"「궁금해서 묻는데, 당번이 없는 날은 어떻게 해?」","mis":"K5-2-u4-X17"}],"explanation":["알맞은 질문이에요.","알맞은 질문이에요.","공격하는 말은 질문이 아니에요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#9','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C19',2,'mc','auto','모둠이 의견을 하나로 고칠 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u4-X19','K5-2-u4-X21','K5-2-u4-X10']::text[],false,'{"seq":9,"concept":"K5-2-u4-C19","difficulty":2,"kind":"mc","stem":"모둠이 의견을 하나로 고칠 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"여러 의견의 장점을 살려 하나로 고친다","correct":true},{"t":"먼저 나온 의견 하나만 남긴다","mis":"K5-2-u4-X19"},{"t":"모두 좋다고 하고 바로 끝낸다","mis":"K5-2-u4-X21"},{"t":"단점이 있는 의견은 다 버린다","mis":"K5-2-u4-X10"}],"explanation":["장점을 버리게 돼요.","따지지 않았어요.","장점을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_basic#10','kor',5,2,'u4','L04','g5_2_kor_u4_L04_basic','lesson_basic','K5-2-u4-C21',3,'mc','auto','모둠원 모두가 「좋아, 좋아.」라고만 해서 금세 정했는데 실천해 보니 문제가 많았어요. 무엇이 빠졌을까요?',ARRAY['K5-2-u4-X14','K5-2-u4-X08','K5-2-u4-X15']::text[],false,'{"seq":10,"concept":"K5-2-u4-C21","difficulty":3,"kind":"mc","stem":"모둠원 모두가 「좋아, 좋아.」라고만 해서 금세 정했는데 실천해 보니 문제가 많았어요. 무엇이 빠졌을까요?","options":[{"t":"단점을 따지고 질문하는 과정","correct":true},{"t":"손을 드는 과정","mis":"K5-2-u4-X14"},{"t":"목소리를 키우는 과정","mis":"K5-2-u4-X08"},{"t":"주제를 바꾸는 과정","mis":"K5-2-u4-X15"}],"explanation":["손을 들어도 마찬가지예요.","목소리는 관계없어요.","따지고 물어야 문제가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#1','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C16',2,'mc','auto','세 문제 가운데 하나를 고를 때 「가장 먼저 풀어야 할 문제인가」를 따지는 까닭은 무엇인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31','K5-2-u4-X26']::text[],false,'{"seq":1,"concept":"K5-2-u4-C16","difficulty":2,"kind":"mc","stem":"세 문제 가운데 하나를 고를 때 「가장 먼저 풀어야 할 문제인가」를 따지는 까닭은 무엇인가요?","options":[{"t":"시간이 한정되어 있어 급한 문제부터 함께 풀려고","correct":true},{"t":"가장 재미있는 문제를 고르려고","mis":"K5-2-u4-X16"},{"t":"어른들만 풀 수 있는 문제를 고르려고","mis":"K5-2-u4-X31"},{"t":"친구 한 명이 좋아하는 문제를 고르려고","mis":"K5-2-u4-X26"}],"explanation":["재미가 기준이 아니에요.","우리가 풀 문제를 골라요.","급한 문제부터 풀어요."],"asset":{"type":"passage","lines":["㉮ 마시지 않은 우유가 많이 남아요.","㉯ 신발장에 실내화가 뒤죽박죽 꽂혀 있어요.","㉰ 모둠 바구니의 가위와 풀이 자꾸 없어져요."],"title":"학교에서 찾은 세 가지 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#2','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C18',2,'ox','auto','질문은 친구 의견의 빈틈을 공격하려고 하는 말이에요.',ARRAY['K5-2-u4-X18']::text[],false,'{"seq":2,"concept":"K5-2-u4-C18","difficulty":2,"kind":"ox","stem":"질문은 친구 의견의 빈틈을 공격하려고 하는 말이에요.","answer":"X","reason_options":[{"t":"궁금한 점을 물어 의견을 더 또렷하게 다듬으려는 말이기 때문에","correct":true},{"t":"질문을 많이 할수록 친구 의견을 이길 수 있기 때문에","mis":"K5-2-u4-X18"}],"mis":"K5-2-u4-X18","explanation":["이기려는 말이 아니에요.","함께 다듬어요.","궁금해서 묻는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#3','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C17',3,'mc','auto','유나의 질문 덕분에 이름표 의견은 어떻게 바뀌었나요?',ARRAY['K5-2-u4-X03','K5-2-u4-X17','K5-2-u4-X20']::text[],false,'{"seq":3,"concept":"K5-2-u4-C17","difficulty":3,"kind":"mc","stem":"유나의 질문 덕분에 이름표 의견은 어떻게 바뀌었나요?","options":[{"t":"투명 테이프로 덮어 오래가게 하는 의견으로 보완되었다","correct":true},{"t":"이름표 의견이 버려졌다","mis":"K5-2-u4-X03"},{"t":"질문 때문에 토의가 멈추었다","mis":"K5-2-u4-X17"},{"t":"민재가 의견을 거두고 토의에서 졌다","mis":"K5-2-u4-X20"}],"explanation":["버려지지 않았어요.","토의가 더 나아졌어요.","질문이 빈틈을 채웠어요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#4','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C20',3,'mc','auto','내 의견이 뽑히지 않아 속상한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X20','K5-2-u4-X08','K5-2-u4-X38']::text[],false,'{"seq":4,"concept":"K5-2-u4-C20","difficulty":3,"kind":"mc","stem":"내 의견이 뽑히지 않아 속상한 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「네 질문 덕분에 모둠 의견이 더 좋아졌어. 그 안에 네 생각도 있어.」","correct":true},{"t":"「뽑히지 않았으니 다음엔 말하지 마.」","mis":"K5-2-u4-X20"},{"t":"「목소리를 더 크게 했어야지.」","mis":"K5-2-u4-X08"},{"t":"「네 의견은 원래 틀렸어.」","mis":"K5-2-u4-X38"}],"explanation":["말하는 것이 소중해요.","목소리로 정하지 않아요.","참여한 가치를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#5','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C19',3,'error','auto','모둠 의견을 고치는 과정이에요. 가장 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X19','K5-2-u4-X12']::text[],false,'{"seq":5,"concept":"K5-2-u4-C19","difficulty":3,"kind":"error","stem":"모둠 의견을 고치는 과정이에요. 가장 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「단점이 하나라도 있는 의견은 모두 지우자.」","correct":true,"mis_target":"K5-2-u4-X10"},{"t":"「이름표 의견의 장점을 남기고 테이프로 보완하자.」","mis":"K5-2-u4-X19"},{"t":"「당번은 모두 돌아가며 맡게 하자.」","mis":"K5-2-u4-X12"}],"explanation":["알맞은 과정이에요.","알맞은 과정이에요.","단점은 보완할 거리예요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#6','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C15',3,'mc','auto','「급식실 줄이 너무 길어서 짜증 나.」를 토의 주제로 바꾼 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31','K5-2-u4-X16']::text[],false,'{"seq":6,"concept":"K5-2-u4-C15","difficulty":3,"kind":"mc","stem":"「급식실 줄이 너무 길어서 짜증 나.」를 토의 주제로 바꾼 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 급식실 줄을 짧게 할까?","correct":true},{"t":"급식실 줄은 누구 때문에 길까?","mis":"K5-2-u4-X15"},{"t":"급식실 줄은 원래 길다.","mis":"K5-2-u4-X31"},{"t":"급식실에 가지 말자.","mis":"K5-2-u4-X16"}],"explanation":["탓하는 물음이에요.","포기하는 말이에요.","방법을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#7','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C21',3,'mc','auto','단점을 말하고 질문하는 것이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X11','K5-2-u4-X21','K5-2-u4-X20']::text[],false,'{"seq":7,"concept":"K5-2-u4-C21","difficulty":3,"kind":"mc","stem":"단점을 말하고 질문하는 것이 꼭 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실천하기 전에 생길 문제를 미리 찾아 의견을 보완할 수 있어서","correct":true},{"t":"친구 의견을 빨리 떨어뜨릴 수 있어서","mis":"K5-2-u4-X11"},{"t":"토의를 길게 끌 수 있어서","mis":"K5-2-u4-X21"},{"t":"내 의견만 뽑히게 할 수 있어서","mis":"K5-2-u4-X20"}],"explanation":["떨어뜨리려는 게 아니에요.","길게 끌려는 게 아니에요.","미리 찾아 보완해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#8','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C15',4,'essay','teacher','세 문제 가운데 하나를 골라 토의 주제를 「어떻게 하면 ~할까?」 꼴로 쓰고, 주제를 고르는 기준 두 가지에 비추어 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C15","difficulty":4,"kind":"essay","stem":"세 문제 가운데 하나를 골라 토의 주제를 「어떻게 하면 ~할까?」 꼴로 쓰고, 주제를 고르는 기준 두 가지에 비추어 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 어떻게 하면 모둠 바구니의 가위와 풀을 잘 챙길까? 우리 모둠이 날마다 쓰는 물건이라 우리와 관련이 있고, 정리 방법을 정하면 우리가 직접 바꿀 수 있기 때문이다.","scoring_points":["주제를 방법을 묻는 꼴로 썼는가","기준 두 가지를 밝혔는가","기준에 비추어 까닭을 썼는가"]},"explanation":["물음으로 써요.","기준을 밝혀요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 마시지 않은 우유가 많이 남아요.","㉯ 신발장에 실내화가 뒤죽박죽 꽂혀 있어요.","㉰ 모둠 바구니의 가위와 풀이 자꾸 없어져요."],"title":"학교에서 찾은 세 가지 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#9','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C17',4,'essay','teacher','현우의 「정리 당번」 의견에 궁금한 점을 묻는 공손한 질문을 두 개 쓰고, 그 질문이 의견을 어떻게 다듬을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C17","difficulty":4,"kind":"essay","stem":"현우의 「정리 당번」 의견에 궁금한 점을 묻는 공손한 질문을 두 개 쓰고, 그 질문이 의견을 어떻게 다듬을지 쓰세요.","answer_guide":{"answer":"예: 「궁금해서 묻는데, 당번은 며칠씩 돌아가며 맡아?」 「당번이 학교에 오지 못한 날은 누가 대신해?」처럼 묻겠다. 이 질문에 답하다 보면 당번을 정하는 방법과 빈자리를 채우는 방법까지 정해져 의견이 더 단단해진다.","scoring_points":["질문을 두 개 썼는가","질문이 공손한가","질문이 의견을 다듬는 점을 썼는가"]},"explanation":["두 개를 써요.","공손하게 물어요.","다듬어지는 점을 써요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L04_challenge#10','kor',5,2,'u4','L04','g5_2_kor_u4_L04_challenge','lesson_challenge','K5-2-u4-C19',4,'essay','teacher','민재 · 유나 · 현우의 의견에서 장점을 살려 하나의 모둠 의견으로 고쳐 쓰고, 그렇게 고친 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C19","difficulty":4,"kind":"essay","stem":"민재 · 유나 · 현우의 의견에서 장점을 살려 하나의 모둠 의견으로 고쳐 쓰고, 그렇게 고친 까닭을 쓰세요.","answer_guide":{"answer":"예: 칸마다 이름표를 붙이고 투명 테이프로 덮으며, 정리 당번은 모두 돌아가며 아침마다 살핀다. 이름표가 오래가고 자기 칸이 바로 보이며, 한 사람만 애쓰지 않아도 되기 때문이다.","scoring_points":["세 의견의 장점을 살렸는가","하나의 의견으로 고쳤는가","고친 까닭을 썼는가"]},"explanation":["장점을 모아요.","하나로 고쳐요.","까닭을 써요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"칸마다 이름표를 다시 붙이면 좋겠어. 자기 칸이 바로 보이니까."},{"who":"유나","text":"궁금해서 묻는데, 이름표가 떨어지면 어떻게 해? 투명 테이프로 덮어 붙이는 건 어때?"},{"who":"현우","text":"정리 당번을 정해서 아침마다 확인하면 어때?"},{"who":"유나","text":"현우야, 당번은 몇 명이 얼마 동안 맡는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#1','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C23',1,'mc','auto','학급 토의의 첫 절차는 무엇인가요?',ARRAY['K5-2-u4-X23','K5-2-u4-X35']::text[],false,'{"seq":1,"concept":"K5-2-u4-C23","difficulty":1,"kind":"mc","stem":"학급 토의의 첫 절차는 무엇인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 정하기","mis":"K5-2-u4-X23"},{"t":"의견 모으기","mis":"K5-2-u4-X23"},{"t":"되돌아보기","mis":"K5-2-u4-X35"}],"explanation":["마지막 절차예요.","넷째 절차예요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#2','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C22',1,'mc','auto','학급 토의에서 절차를 안내하는 사람은 누구인가요?',ARRAY['K5-2-u4-X22','K5-2-u4-X08']::text[],false,'{"seq":2,"concept":"K5-2-u4-C22","difficulty":1,"kind":"mc","stem":"학급 토의에서 절차를 안내하는 사람은 누구인가요?","options":[{"t":"사회자","correct":true},{"t":"은서","mis":"K5-2-u4-X22"},{"t":"목소리가 가장 큰 친구","mis":"K5-2-u4-X08"},{"t":"가장 먼저 온 친구","mis":"K5-2-u4-X22"}],"explanation":["의견을 낸 친구예요.","목소리로 정하지 않아요.","사회자가 안내해요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러 학급 문제 가운데 무엇을 토의 주제로 정하면 좋을까요?"},{"who":"은서","text":"아침 활동을 아직 정하지 못한 문제가 가장 급해요. 벌써 둘째 주가 지나가거든요."},{"who":"사회자","text":"그럼 「우리 반 아침 활동 시간을 무엇으로 채울까?」로 토의해요. 각자 의견을 마련해 봅시다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#3','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C24',1,'mc','auto','의견을 검토할 기준을 정하고 장단점을 따져 합의점을 찾는 절차는 무엇인가요?',ARRAY['K5-2-u4-X24']::text[],false,'{"seq":3,"concept":"K5-2-u4-C24","difficulty":1,"kind":"mc","stem":"의견을 검토할 기준을 정하고 장단점을 따져 합의점을 찾는 절차는 무엇인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"토의 주제 정하기","mis":"K5-2-u4-X24"},{"t":"의견 마련하기","mis":"K5-2-u4-X24"},{"t":"의견 나누기","mis":"K5-2-u4-X24"}],"explanation":["첫 절차예요.","각자 의견을 쓰는 절차예요.","조정은 의견 모으기 안에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#4','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C26',1,'ox','auto','학급 토의는 몇몇 친구만 말하고 나머지는 듣기만 하면 돼요.',ARRAY['K5-2-u4-X26']::text[],false,'{"seq":4,"concept":"K5-2-u4-C26","difficulty":1,"kind":"ox","stem":"학급 토의는 몇몇 친구만 말하고 나머지는 듣기만 하면 돼요.","answer":"X","reason_options":[{"t":"반 전체의 문제라서 모두가 의견을 마련하고 참여해야 하기 때문에","correct":true},{"t":"말 잘하는 친구의 의견이 언제나 가장 좋기 때문에","mis":"K5-2-u4-X26"}],"mis":"K5-2-u4-X26","explanation":["모두의 문제예요.","말 잘하는 것이 기준이 아니에요.","모두 참여해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#5','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C22',2,'mc','auto','은서는 어떤 까닭으로 이 문제를 주제로 하자고 했나요?',ARRAY['K5-2-u4-X04','K5-2-u4-X22','K5-2-u4-X16']::text[],false,'{"seq":5,"concept":"K5-2-u4-C22","difficulty":2,"kind":"mc","stem":"은서는 어떤 까닭으로 이 문제를 주제로 하자고 했나요?","options":[{"t":"아직 정하지 못한 채 시간이 지나 가장 급해서","correct":true},{"t":"은서가 줄넘기를 좋아해서","mis":"K5-2-u4-X04"},{"t":"사회자가 시켜서","mis":"K5-2-u4-X22"},{"t":"가장 재미있어 보여서","mis":"K5-2-u4-X16"}],"explanation":["은서가 말하지 않은 까닭이에요.","은서가 스스로 말했어요.","가장 급하다고 했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"여러 학급 문제 가운데 무엇을 토의 주제로 정하면 좋을까요?"},{"who":"은서","text":"아침 활동을 아직 정하지 못한 문제가 가장 급해요. 벌써 둘째 주가 지나가거든요."},{"who":"사회자","text":"그럼 「우리 반 아침 활동 시간을 무엇으로 채울까?」로 토의해요. 각자 의견을 마련해 봅시다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#6','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C25',2,'mc','auto','의견이 많을 때 칠판에 정리하는 까닭은 무엇인가요?',ARRAY['K5-2-u4-X25','K5-2-u4-X26']::text[],false,'{"seq":6,"concept":"K5-2-u4-C25","difficulty":2,"kind":"mc","stem":"의견이 많을 때 칠판에 정리하는 까닭은 무엇인가요?","options":[{"t":"모두가 의견과 장단점을 한눈에 보고 견줄 수 있어서","correct":true},{"t":"칠판을 꾸미려고","mis":"K5-2-u4-X25"},{"t":"글씨 연습을 하려고","mis":"K5-2-u4-X25"},{"t":"말로 하면 시끄러워서","mis":"K5-2-u4-X26"}],"explanation":["꾸미려는 것이 아니에요.","연습하려는 것이 아니에요.","한눈에 보고 견줘요."],"asset":{"type":"passage","lines":["책 읽기 — 장점: 조용히 하루를 연다 · 단점: 책이 없으면 할 게 없다","줄넘기 — 장점: 몸이 깨어나 집중한다 · 단점: 비 오는 날은 못 한다","낱말 놀이 — 장점: 모두 함께 웃는다 · 단점: 매일 하면 지루해진다","합의점 — 요일마다 돌아가며 하고, 비 오는 날은 책 읽기를 한다"],"title":"칠판에 정리한 의견 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#7','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C23',2,'match','auto','학급 토의 절차와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C23","difficulty":2,"kind":"match","stem":"학급 토의 절차와 하는 일을 알맞게 이으세요.","pairs":[{"l":"의견 마련하기","r":"주제에 맞는 의견과 까닭을 각자 쓰기"},{"l":"의견 나누기","r":"마련한 의견을 발표하고 질문하기"},{"l":"의견 정하기","r":"실천할 의견을 정하기"}],"mis":"K5-2-u4-X23","explanation":["각자 마련해요.","발표하고 물어요.","실천할 의견을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#8','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C27',2,'error','auto','회의와 토의에 대한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X27','K5-2-u4-X14','K5-2-u4-X24']::text[],false,'{"seq":8,"concept":"K5-2-u4-C27","difficulty":2,"kind":"error","stem":"회의와 토의에 대한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「토의도 언제나 손을 들어 많은 쪽으로 바로 정해.」","correct":true,"mis_target":"K5-2-u4-X27"},{"t":"「회의는 손을 들어 많은 쪽으로 정하는 경우가 많아.」","mis":"K5-2-u4-X14"},{"t":"「토의는 의견을 조정해 합의된 쪽으로 정해.」","mis":"K5-2-u4-X24"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","토의는 조정해 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#9','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C24',2,'mc','auto','칠판의 합의점은 줄넘기 의견의 어떤 단점을 메웠나요?',ARRAY['K5-2-u4-X09','K5-2-u4-X10']::text[],false,'{"seq":9,"concept":"K5-2-u4-C24","difficulty":2,"kind":"mc","stem":"칠판의 합의점은 줄넘기 의견의 어떤 단점을 메웠나요?","options":[{"t":"비 오는 날에는 할 수 없는 점","correct":true},{"t":"책이 없으면 할 게 없는 점","mis":"K5-2-u4-X09"},{"t":"매일 하면 지루해지는 점","mis":"K5-2-u4-X09"},{"t":"몸이 깨어나는 점","mis":"K5-2-u4-X10"}],"explanation":["책 읽기의 단점이에요.","낱말 놀이의 단점이에요.","비 오는 날은 책 읽기로 메웠어요."],"asset":{"type":"passage","lines":["책 읽기 — 장점: 조용히 하루를 연다 · 단점: 책이 없으면 할 게 없다","줄넘기 — 장점: 몸이 깨어나 집중한다 · 단점: 비 오는 날은 못 한다","낱말 놀이 — 장점: 모두 함께 웃는다 · 단점: 매일 하면 지루해진다","합의점 — 요일마다 돌아가며 하고, 비 오는 날은 책 읽기를 한다"],"title":"칠판에 정리한 의견 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_basic#10','kor',5,2,'u4','L06','g5_2_kor_u4_L06_basic','lesson_basic','K5-2-u4-C28',3,'mc','auto','반이 「요일마다 돌아가며 하기」로 정했는데 은서는 「줄넘기 날만 하겠다.」고 했어요. 은서에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X01']::text[],false,'{"seq":10,"concept":"K5-2-u4-C28","difficulty":3,"kind":"mc","stem":"반이 「요일마다 돌아가며 하기」로 정했는데 은서는 「줄넘기 날만 하겠다.」고 했어요. 은서에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「함께 정한 절차대로 같이 해 보고, 문제가 있으면 다시 토의하자.」","correct":true},{"t":"「네 마음대로 해도 돼.」","mis":"K5-2-u4-X28"},{"t":"「한 번 정했으니 영원히 못 바꿔.」","mis":"K5-2-u4-X28"},{"t":"「네 의견은 틀렸어.」","mis":"K5-2-u4-X01"}],"explanation":["함께 정한 것은 함께 실천해요.","다시 토의할 수 있어요.","받아들이고, 필요하면 다시 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#1','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C23',2,'mc','auto','학급 토의 절차를 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['K5-2-u4-X23']::text[],false,'{"seq":1,"concept":"K5-2-u4-C23","difficulty":2,"kind":"mc","stem":"학급 토의 절차를 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"주제 정하기 → 의견 마련하기 → 의견 나누기 → 의견 모으기 → 의견 정하기","correct":true},{"t":"의견 마련하기 → 주제 정하기 → 의견 모으기 → 의견 나누기 → 의견 정하기","mis":"K5-2-u4-X23"},{"t":"주제 정하기 → 의견 정하기 → 의견 나누기 → 의견 마련하기 → 의견 모으기","mis":"K5-2-u4-X23"},{"t":"주제 정하기 → 의견 나누기 → 의견 정하기","mis":"K5-2-u4-X23"}],"explanation":["주제가 먼저예요.","정하기는 마지막이에요.","다섯 절차를 모두 거쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#2','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C27',2,'ox','auto','회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 의견을 조정해 합의해서 정해요.',ARRAY['K5-2-u4-X27']::text[],false,'{"seq":2,"concept":"K5-2-u4-C27","difficulty":2,"kind":"ox","stem":"회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 의견을 조정해 합의해서 정해요.","answer":"O","reason_options":[{"t":"두 말하기는 정하는 방법이 다르기 때문에","correct":true},{"t":"회의와 토의는 이름만 다르고 정하는 방법이 똑같기 때문에","mis":"K5-2-u4-X27"}],"mis":"K5-2-u4-X27","explanation":["정하는 방법이 달라요.","토의는 조정해요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#3','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C26',3,'mc','auto','학급 토의에서 늘 같은 친구만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X22']::text[],false,'{"seq":3,"concept":"K5-2-u4-C26","difficulty":3,"kind":"mc","stem":"학급 토의에서 늘 같은 친구만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의견을 마련할 시간을 주고 아직 말하지 않은 친구에게 차례를 준다","correct":true},{"t":"발표 잘하는 친구에게 계속 맡긴다","mis":"K5-2-u4-X26"},{"t":"조용한 친구는 의견이 없다고 여긴다","mis":"K5-2-u4-X26"},{"t":"사회자가 의견을 대신 정한다","mis":"K5-2-u4-X22"}],"explanation":["몇몇 친구만 말하게 돼요.","조용한 친구도 생각이 있어요.","여러 친구가 말하게 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#4','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C22',3,'mc','auto','사회자의 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X22','K5-2-u4-X25','K5-2-u4-X26']::text[],false,'{"seq":4,"concept":"K5-2-u4-C22","difficulty":3,"kind":"mc","stem":"사회자의 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"자기가 좋아하는 의견으로 정해 버리기","correct":true},{"t":"절차를 안내하기","mis":"K5-2-u4-X22"},{"t":"나온 의견을 정리하기","mis":"K5-2-u4-X25"},{"t":"여러 친구가 말하도록 돕기","mis":"K5-2-u4-X26"}],"explanation":["사회자의 일이에요.","사회자의 일이에요.","사회자는 대신 정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#5','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C28',3,'error','auto','학급에서 정한 의견을 실천한 뒤의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X13','K5-2-u4-X20']::text[],false,'{"seq":5,"concept":"K5-2-u4-C28","difficulty":3,"kind":"error","stem":"학급에서 정한 의견을 실천한 뒤의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘 안 되지만 한 번 정한 거니 절대 바꾸면 안 돼.」","correct":true,"mis_target":"K5-2-u4-X28"},{"t":"「해 보니 비 오는 날이 문제였어. 다시 토의해 보자.」","mis":"K5-2-u4-X13"},{"t":"「내 의견과 달랐지만 함께 정한 거라 열심히 했어.」","mis":"K5-2-u4-X20"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","잘 안 되면 다시 토의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#6','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C25',3,'mc','auto','반 친구들의 의견이 계속 쏟아져 정리가 안 될 때 가장 알맞은 방법은 어느 것인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X25']::text[],false,'{"seq":6,"concept":"K5-2-u4-C25","difficulty":3,"kind":"mc","stem":"반 친구들의 의견이 계속 쏟아져 정리가 안 될 때 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"칠판에 의견을 적고 비슷한 의견끼리 묶어 기준과 함께 본다","correct":true},{"t":"목소리 큰 의견 하나만 적는다","mis":"K5-2-u4-X08"},{"t":"정리하지 말고 계속 말한다","mis":"K5-2-u4-X25"},{"t":"처음 말한 의견으로 정한다","mis":"K5-2-u4-X08"}],"explanation":["목소리로 고르지 않아요.","정리해야 견줘요.","한눈에 보이게 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#7','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C24',3,'mc','auto','앞에서 배운 「의견 조정하기」가 들어 있는 학급 토의 절차는 어느 것인가요?',ARRAY['K5-2-u4-X24','K5-2-u4-X23']::text[],false,'{"seq":7,"concept":"K5-2-u4-C24","difficulty":3,"kind":"mc","stem":"앞에서 배운 「의견 조정하기」가 들어 있는 학급 토의 절차는 어느 것인가요?","options":[{"t":"의견 모으기","correct":true},{"t":"의견 마련하기","mis":"K5-2-u4-X24"},{"t":"토의 주제 정하기","mis":"K5-2-u4-X24"},{"t":"의견 정하기","mis":"K5-2-u4-X23"}],"explanation":["각자 쓰는 절차예요.","첫 절차예요.","의견 모으기 안에 조정이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#8','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C23',4,'essay','teacher','우리 반에서 풀고 싶은 학급 문제를 하나 골라 토의 주제로 바꾸고, 학급 토의 절차에 따라 무엇을 할지 차례대로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C23","difficulty":4,"kind":"essay","stem":"우리 반에서 풀고 싶은 학급 문제를 하나 골라 토의 주제로 바꾸고, 학급 토의 절차에 따라 무엇을 할지 차례대로 쓰세요.","answer_guide":{"answer":"예: 주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까? 먼저 주제를 함께 정하고, 각자 의견과 까닭을 쓴 뒤 발표하며 질문한다. 그다음 기준을 정해 장단점을 따지고 합의점을 찾아 의견을 모으고, 마지막으로 실천할 의견을 정한다.","scoring_points":["학급 문제를 토의 주제로 바꾸었는가","다섯 절차를 차례대로 썼는가","절차마다 할 일을 썼는가"]},"explanation":["주제로 바꿔요.","차례를 지켜요.","할 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#9','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C27',4,'essay','teacher','회의와 토의가 정하는 방법에서 어떻게 다른지 쓰고, 토의로 정하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C27","difficulty":4,"kind":"essay","stem":"회의와 토의가 정하는 방법에서 어떻게 다른지 쓰고, 토의로 정하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 회의는 손을 들어 많은 쪽으로 정하는 경우가 많고, 토의는 서로의 의견을 조정해 합의된 쪽으로 정한다. 토의로 정하면 적은 사람의 의견이라도 까닭이 옳으면 살릴 수 있고, 모두가 받아들여 함께 실천하기 쉽다.","scoring_points":["회의의 정하는 방법을 썼는가","토의의 정하는 방법을 썼는가","토의의 좋은 점을 썼는가"]},"explanation":["회의의 방법이에요.","토의의 방법이에요.","좋은 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L06_challenge#10','kor',5,2,'u4','L06','g5_2_kor_u4_L06_challenge','lesson_challenge','K5-2-u4-C28',4,'essay','teacher','반에서 정한 의견이 내 의견과 다를 때 어떻게 해야 하는지 까닭과 함께 쓰고, 실천해 보니 잘되지 않으면 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C28","difficulty":4,"kind":"essay","stem":"반에서 정한 의견이 내 의견과 다를 때 어떻게 해야 하는지 까닭과 함께 쓰고, 실천해 보니 잘되지 않으면 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 반 전체가 정당한 절차로 정한 의견이므로 내 의견과 달라도 받아들이고 함께 실천해야 한다. 그래야 모두가 지키며 문제를 풀 수 있다. 실천해 보니 잘되지 않으면 그 모습을 나누고 새 의견을 찾는 학급 토의를 다시 열자고 하겠다.","scoring_points":["받아들이고 실천한다고 썼는가","까닭을 썼는가","잘 안 될 때 다시 토의한다고 썼는가"]},"explanation":["받아들여요.","까닭을 써요.","다시 토의할 수 있어요."],"asset":{"type":"passage","lines":["책 읽기 — 장점: 조용히 하루를 연다 · 단점: 책이 없으면 할 게 없다","줄넘기 — 장점: 몸이 깨어나 집중한다 · 단점: 비 오는 날은 못 한다","낱말 놀이 — 장점: 모두 함께 웃는다 · 단점: 매일 하면 지루해진다","합의점 — 요일마다 돌아가며 하고, 비 오는 날은 책 읽기를 한다"],"title":"칠판에 정리한 의견 모으기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#1','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C29',1,'mc','auto','글쓴이는 사람마다 무엇이 다르다고 했나요?',ARRAY['K5-2-u4-X29']::text[],false,'{"seq":1,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"글쓴이는 사람마다 무엇이 다르다고 했나요?","options":[{"t":"소중하게 여기는 것","correct":true},{"t":"사는 나라","mis":"K5-2-u4-X29"},{"t":"좋아하는 색깔","mis":"K5-2-u4-X29"},{"t":"키와 몸무게","mis":"K5-2-u4-X29"}],"explanation":["글에 없어요.","글에 없어요.","글 첫 줄에 나와요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#2','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C30',1,'mc','auto','글쓴이가 바라는 것은 무엇인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31','K5-2-u4-X29']::text[],false,'{"seq":2,"concept":"K5-2-u4-C30","difficulty":1,"kind":"mc","stem":"글쓴이가 바라는 것은 무엇인가요?","options":[{"t":"서로 조금씩 양보할 방법을 함께 찾기","correct":true},{"t":"누가 옳은지 끝까지 겨루기","mis":"K5-2-u4-X30"},{"t":"부딪치는 일은 모른 척하기","mis":"K5-2-u4-X31"},{"t":"소중한 것을 하나로 똑같이 맞추기","mis":"K5-2-u4-X29"}],"explanation":["겨루기보다 양보예요.","모른 척하지 않아요.","글 마지막 줄에 나와요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#3','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C29',1,'mc','auto','글에서 공원 산책길에서 부딪치는 두 사람은 누구인가요?',ARRAY['K5-2-u4-X06']::text[],false,'{"seq":3,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"글에서 공원 산책길에서 부딪치는 두 사람은 누구인가요?","options":[{"t":"자전거를 타는 사람과 걷는 사람","correct":true},{"t":"공을 차는 아이와 쉬고 싶은 이웃","mis":"K5-2-u4-X06"},{"t":"가게 주인과 손님","mis":"K5-2-u4-X06"},{"t":"선생님과 학생","mis":"K5-2-u4-X06"}],"explanation":["놀이터 장면이에요.","글에 없어요.","산책길 장면을 봐요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#4','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C31',1,'ox','auto','우리 주변의 문제는 어른들만 풀 수 있어 어린이는 토의할 필요가 없어요.',ARRAY['K5-2-u4-X31']::text[],false,'{"seq":4,"concept":"K5-2-u4-C31","difficulty":1,"kind":"ox","stem":"우리 주변의 문제는 어른들만 풀 수 있어 어린이는 토의할 필요가 없어요.","answer":"X","reason_options":[{"t":"우리도 의견을 모아 알맞은 곳에 제안하며 풀이에 도움을 줄 수 있기 때문에","correct":true},{"t":"주변의 문제는 우리와 관련이 없기 때문에","mis":"K5-2-u4-X31"}],"mis":"K5-2-u4-X31","explanation":["우리와 관련이 있어요.","우리도 도울 수 있어요.","어린이의 토의도 힘이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#5','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C30',2,'mc','auto','준혁의 의견 「자전거를 아예 못 타게 하자」의 단점은 무엇인가요?',ARRAY['K5-2-u4-X09','K5-2-u4-X10','K5-2-u4-X06']::text[],false,'{"seq":5,"concept":"K5-2-u4-C30","difficulty":2,"kind":"mc","stem":"준혁의 의견 「자전거를 아예 못 타게 하자」의 단점은 무엇인가요?","options":[{"t":"자전거 타는 사람의 바람은 반영되지 않는다","correct":true},{"t":"걷는 사람이 더 위험해진다","mis":"K5-2-u4-X09"},{"t":"단점이 하나도 없다","mis":"K5-2-u4-X10"},{"t":"다른 의견과 똑같다","mis":"K5-2-u4-X06"}],"explanation":["오히려 안전해져요.","어느 의견이든 단점이 있어요.","한쪽 가치만 지켜요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#6','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C32',2,'mc','auto','시우가 의견을 다듬으려고 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X32','K5-2-u4-X08','K5-2-u4-X11']::text[],false,'{"seq":6,"concept":"K5-2-u4-C32","difficulty":2,"kind":"mc","stem":"시우가 의견을 다듬으려고 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산책길을 나눈 사례를 책이나 누리집에서 찾아본다","correct":true},{"t":"짐작만으로 까닭을 덧붙인다","mis":"K5-2-u4-X32"},{"t":"목소리를 크게 연습한다","mis":"K5-2-u4-X08"},{"t":"다른 친구의 의견을 깎아내린다","mis":"K5-2-u4-X11"}],"explanation":["근거가 약해요.","목소리는 관계없어요.","자료로 까닭을 다듬어요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#7','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C29',2,'match','auto','부딪치는 사람과 그 사람이 소중히 여기는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C29","difficulty":2,"kind":"match","stem":"부딪치는 사람과 그 사람이 소중히 여기는 것을 알맞게 이으세요.","pairs":[{"l":"자전거를 타는 사람","r":"시원하게 달리기"},{"l":"걷는 사람","r":"마음 놓고 천천히 걷기"},{"l":"쉬고 싶은 이웃","r":"조용한 저녁"}],"mis":"K5-2-u4-X29","explanation":["달리고 싶어요.","천천히 걷고 싶어요.","쉬고 싶어요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#8','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C30',2,'error','auto','산책길 토의를 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X29','K5-2-u4-X30']::text[],false,'{"seq":8,"concept":"K5-2-u4-C30","difficulty":2,"kind":"error","stem":"산책길 토의를 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「자전거 타는 사람이 나쁜 사람이니 못 타게 해야 해.」","correct":true,"mis_target":"K5-2-u4-X29"},{"t":"「두 사람 모두 소중히 여기는 것이 있어.」","mis":"K5-2-u4-X30"},{"t":"「서로 조금씩 양보할 방법을 찾자.」","mis":"K5-2-u4-X30"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","나쁜 사람이 아니라 가치가 달라요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#9','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C8',2,'mc','auto','산책길 토의에서 새로 더한 검토 기준은 무엇인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X16']::text[],false,'{"seq":9,"concept":"K5-2-u4-C8","difficulty":2,"kind":"mc","stem":"산책길 토의에서 새로 더한 검토 기준은 무엇인가요?","options":[{"t":"비용","correct":true},{"t":"목소리 크기","mis":"K5-2-u4-X08"},{"t":"먼저 말한 차례","mis":"K5-2-u4-X08"},{"t":"재미","mis":"K5-2-u4-X16"}],"explanation":["기준이 아니에요.","기준이 아니에요.","공원 일이라 비용을 더했어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 · 비용","자전거 금지 — 장점: 걷는 사람이 가장 안전하다","자전거 금지 — 단점: 자전거 타는 사람의 바람은 반영되지 않는다","가운데 선 — 장점: 두 쪽 모두 함께 길을 쓴다 · 단점: 안 지킬 수 있다","저녁엔 끌고 가기 — 장점: 붐빌 때 위험이 준다 · 단점: 모르는 사람이 많다","합의점 — 가운데 선을 긋고, 저녁엔 끌고 가자는 알림판을 세운다"],"title":"산책길 토의 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_basic#10','kor',5,2,'u4','L08','g5_2_kor_u4_L08_basic','lesson_basic','K5-2-u4-C33',3,'mc','auto','반에서 정한 합의점을 실천하려고 할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u4-X33','K5-2-u4-X31','K5-2-u4-X29']::text[],false,'{"seq":10,"concept":"K5-2-u4-C33","difficulty":3,"kind":"mc","stem":"반에서 정한 합의점을 실천하려고 할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"공원 관리소에 제안 글과 알림판 그림을 함께 보낸다","correct":true},{"t":"「알린다」고만 적어 둔다","mis":"K5-2-u4-X33"},{"t":"우리끼리만 알고 있는다","mis":"K5-2-u4-X31"},{"t":"자전거 타는 사람에게 소리친다","mis":"K5-2-u4-X29"}],"explanation":["누구에게 어떻게가 빠졌어요.","알려야 바뀌어요.","알맞은 곳에 제안해요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 · 비용","자전거 금지 — 장점: 걷는 사람이 가장 안전하다","자전거 금지 — 단점: 자전거 타는 사람의 바람은 반영되지 않는다","가운데 선 — 장점: 두 쪽 모두 함께 길을 쓴다 · 단점: 안 지킬 수 있다","저녁엔 끌고 가기 — 장점: 붐빌 때 위험이 준다 · 단점: 모르는 사람이 많다","합의점 — 가운데 선을 긋고, 저녁엔 끌고 가자는 알림판을 세운다"],"title":"산책길 토의 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#1','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C30',2,'ox','auto','서로 다른 가치가 부딪치면 더 옳은 쪽 하나를 골라 이기게 해야 해요.',ARRAY['K5-2-u4-X30']::text[],false,'{"seq":1,"concept":"K5-2-u4-C30","difficulty":2,"kind":"ox","stem":"서로 다른 가치가 부딪치면 더 옳은 쪽 하나를 골라 이기게 해야 해요.","answer":"X","reason_options":[{"t":"두 가치 모두 소중할 수 있어 서로 존중하며 양보할 방법을 찾아야 하기 때문에","correct":true},{"t":"토의는 옳은 쪽을 가리는 자리이기 때문에","mis":"K5-2-u4-X30"}],"mis":"K5-2-u4-X30","explanation":["둘 다 소중할 수 있어요.","가리는 자리가 아니에요.","존중하고 양보해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#2','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C31',2,'mc','auto','주변의 부딪침 가운데 우리 반 토의 주제로 고르기에 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31']::text[],false,'{"seq":2,"concept":"K5-2-u4-C31","difficulty":2,"kind":"mc","stem":"주변의 부딪침 가운데 우리 반 토의 주제로 고르기에 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리 동네 공원 산책길을 함께 안전하게 쓰는 방법","correct":true},{"t":"먼 나라 큰 강의 물길을 바꾸는 방법","mis":"K5-2-u4-X16"},{"t":"어른들의 회사 일을 정하는 방법","mis":"K5-2-u4-X31"},{"t":"친구 한 명의 숙제를 정하는 방법","mis":"K5-2-u4-X16"}],"explanation":["우리가 도울 수 없어요.","우리와 관련이 적어요.","우리가 도울 수 있는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#3','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C32',3,'mc','auto','「가운데 선을 그으면 부딪칠 일이 준다」는 까닭을 더 타당하게 만드는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X32','K5-2-u4-X04','K5-2-u4-X11']::text[],false,'{"seq":3,"concept":"K5-2-u4-C32","difficulty":3,"kind":"mc","stem":"「가운데 선을 그으면 부딪칠 일이 준다」는 까닭을 더 타당하게 만드는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"선을 그은 다른 공원 사례를 자료에서 찾아 덧붙인다","correct":true},{"t":"「분명 줄어들 거야.」라고 크게 말한다","mis":"K5-2-u4-X32"},{"t":"까닭을 빼고 의견만 말한다","mis":"K5-2-u4-X04"},{"t":"다른 의견의 단점만 말한다","mis":"K5-2-u4-X11"}],"explanation":["크게 말해도 근거가 안 돼요.","까닭이 필요해요.","자료가 까닭을 받쳐 줘요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#4','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C33',3,'mc','auto','공원 관리소에 제안할 때 넣을 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X11','K5-2-u4-X33']::text[],false,'{"seq":4,"concept":"K5-2-u4-C33","difficulty":3,"kind":"mc","stem":"공원 관리소에 제안할 때 넣을 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정한 의견과 까닭, 우리가 함께할 수 있는 일","correct":true},{"t":"불평하는 말만","mis":"K5-2-u4-X15"},{"t":"다른 의견을 낸 친구 이름","mis":"K5-2-u4-X11"},{"t":"아무 설명 없이 「바꿔 주세요.」만","mis":"K5-2-u4-X33"}],"explanation":["불평만으로는 바뀌지 않아요.","이름은 필요 없어요.","의견과 까닭을 함께 제안해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#5','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C8',3,'error','auto','산책길 토의의 기준을 정하는 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X09','K5-2-u4-X08','K5-2-u4-X07']::text[],false,'{"seq":5,"concept":"K5-2-u4-C8","difficulty":3,"kind":"error","stem":"산책길 토의의 기준을 정하는 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「기준은 어느 문제에서나 늘 세 가지로만 정해야 해.」","correct":true,"mis_target":"K5-2-u4-X09"},{"t":"「공원 일이니 돈이 얼마나 드는지도 따지자.」","mis":"K5-2-u4-X08"},{"t":"「걷는 사람과 자전거 타는 사람 모두에게 도움이 되는지 보자.」","mis":"K5-2-u4-X07"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","기준은 문제마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#6','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C30',3,'mc','auto','칠판의 합의점이 두 사람의 가치를 모두 존중한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C30","difficulty":3,"kind":"mc","stem":"칠판의 합의점이 두 사람의 가치를 모두 존중한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자전거도 탈 수 있고 걷는 사람도 안전해지기 때문에","correct":true},{"t":"자전거를 아예 못 타게 했기 때문에","mis":"K5-2-u4-X30"},{"t":"걷는 사람이 길을 비켜 주기로 했기 때문에","mis":"K5-2-u4-X30"},{"t":"아무것도 바꾸지 않았기 때문에","mis":"K5-2-u4-X31"}],"explanation":["한쪽만 지켜요.","한쪽만 양보해요.","둘 다 존중했어요."],"asset":{"type":"passage","lines":["기준 — 실천할 수 있는가 · 효과적인가 · 여러 사람에게 도움이 되는가 · 비용","자전거 금지 — 장점: 걷는 사람이 가장 안전하다","자전거 금지 — 단점: 자전거 타는 사람의 바람은 반영되지 않는다","가운데 선 — 장점: 두 쪽 모두 함께 길을 쓴다 · 단점: 안 지킬 수 있다","저녁엔 끌고 가기 — 장점: 붐빌 때 위험이 준다 · 단점: 모르는 사람이 많다","합의점 — 가운데 선을 긋고, 저녁엔 끌고 가자는 알림판을 세운다"],"title":"산책길 토의 칠판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#7','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C7',3,'mc','auto','「공원에 감시하는 사람을 늘 세워 두자.」 의견을 기준으로 다시 따진 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10','K5-2-u4-X07','K5-2-u4-X18']::text[],false,'{"seq":7,"concept":"K5-2-u4-C7","difficulty":3,"kind":"mc","stem":"「공원에 감시하는 사람을 늘 세워 두자.」 의견을 기준으로 다시 따진 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"효과는 클 수 있지만 비용이 많이 들어 실천하기 어렵다","correct":true},{"t":"감시하면 무조건 좋다","mis":"K5-2-u4-X10"},{"t":"기준은 따질 필요가 없다","mis":"K5-2-u4-X07"},{"t":"질문한 친구가 잘못했다","mis":"K5-2-u4-X18"}],"explanation":["단점도 있어요.","기준으로 따져요.","여러 기준으로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#8','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C29',4,'essay','teacher','우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 찾아, 두 사람이 각각 소중히 여기는 것을 쓰고 토의 주제로 바꾸어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C29","difficulty":4,"kind":"essay","stem":"우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 찾아, 두 사람이 각각 소중히 여기는 것을 쓰고 토의 주제로 바꾸어 쓰세요.","answer_guide":{"answer":"예: 저녁에 아파트 놀이터에서 공놀이를 하는 아이들은 즐겁게 노는 것을, 쉬고 싶은 이웃은 조용한 저녁을 소중히 여긴다. 토의 주제 — 어떻게 하면 놀이터를 아이들과 이웃이 모두 편하게 쓸까?","scoring_points":["부딪치는 일을 찾았는가","두 사람의 가치를 각각 썼는가","방법을 묻는 토의 주제로 바꾸었는가"]},"explanation":["부딪침을 찾아요.","두 가치를 써요.","주제로 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#9','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C30',4,'essay','teacher','산책길 문제에서 내가 생각하는 합의점을 쓰고, 그 합의점이 두 사람의 가치를 어떻게 존중하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C30","difficulty":4,"kind":"essay","stem":"산책길 문제에서 내가 생각하는 합의점을 쓰고, 그 합의점이 두 사람의 가치를 어떻게 존중하는지 쓰세요.","answer_guide":{"answer":"예: 산책길에 가운데 선을 긋고, 사람이 많은 저녁에는 자전거를 천천히 타거나 끌고 가자는 알림판을 세운다. 자전거 타는 사람은 계속 탈 수 있고, 걷는 사람은 붐비는 때에도 마음 놓고 걸을 수 있어 둘 다 존중된다.","scoring_points":["합의점을 썼는가","자전거 타는 사람의 가치를 살폈는가","걷는 사람의 가치를 살폈는가"]},"explanation":["합의점이에요.","한쪽 가치예요.","다른 쪽 가치도 살펴요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L08_challenge#10','kor',5,2,'u4','L08','g5_2_kor_u4_L08_challenge','lesson_challenge','K5-2-u4-C33',4,'essay','teacher','우리 반이 주변의 문제로 정한 의견을 누구에게 어떻게 알릴지 실천 계획을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C33","difficulty":4,"kind":"essay","stem":"우리 반이 주변의 문제로 정한 의견을 누구에게 어떻게 알릴지 실천 계획을 쓰세요.","answer_guide":{"answer":"예: 공원 산책길 의견을 공원 관리소에 알리겠다. 정한 의견과 까닭, 산책길 알림판 그림을 담은 제안 편지를 반 친구들이 함께 써서 관리소 누리집에 올리고, 동네 게시판에도 알림판 그림을 붙이겠다.","scoring_points":["알릴 곳을 정했는가","알릴 방법을 썼는가","의견과 까닭을 함께 담았는가"]},"explanation":["누구에게예요.","어떻게예요.","의견과 까닭을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#1','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C34',1,'mc','auto','학교 문제 토의 여섯 단계의 마지막 단계는 무엇인가요?',ARRAY['K5-2-u4-X35']::text[],false,'{"seq":1,"concept":"K5-2-u4-C34","difficulty":1,"kind":"mc","stem":"학교 문제 토의 여섯 단계의 마지막 단계는 무엇인가요?","options":[{"t":"되돌아보기","correct":true},{"t":"토의 주제 정하기","mis":"K5-2-u4-X35"},{"t":"의견 마련하기","mis":"K5-2-u4-X35"},{"t":"의견 나누기","mis":"K5-2-u4-X35"}],"explanation":["첫 단계예요.","둘째 단계예요.","마치면 되돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#2','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C36',1,'mc','auto','두 의견을 하나로 합쳐 새 의견을 만드는 생각 도구 물음은 무엇인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":2,"concept":"K5-2-u4-C36","difficulty":1,"kind":"mc","stem":"두 의견을 하나로 합쳐 새 의견을 만드는 생각 도구 물음은 무엇인가요?","options":[{"t":"합치기","correct":true},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"순서 바꾸기","mis":"K5-2-u4-X36"},{"t":"포기하기","mis":"K5-2-u4-X36"}],"explanation":["일부를 덜어 내요.","차례를 바꿔요.","두 의견을 합쳐요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#3','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C15',1,'mc','auto','쪽지를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31']::text[],false,'{"seq":3,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"쪽지를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 수돗가 바닥을 깨끗하게 쓸까?","correct":true},{"t":"수돗가가 물바다라서 정말 싫다.","mis":"K5-2-u4-X15"},{"t":"도서관은 내 탓이 아니다.","mis":"K5-2-u4-X15"},{"t":"급식실 줄은 원래 길다.","mis":"K5-2-u4-X31"}],"explanation":["불평하는 말이에요.","탓하는 말이에요.","방법을 묻는 물음이에요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#4','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C37',1,'ox','auto','토의를 되돌아볼 때에는 누구 잘못인지 따지는 것이 가장 중요해요.',ARRAY['K5-2-u4-X37']::text[],false,'{"seq":4,"concept":"K5-2-u4-C37","difficulty":1,"kind":"ox","stem":"토의를 되돌아볼 때에는 누구 잘못인지 따지는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"잘한 점과 다음에 함께 노력할 점을 찾는 시간이기 때문에","correct":true},{"t":"잘못한 친구를 찾아야 다음 토의가 잘되기 때문에","mis":"K5-2-u4-X37"}],"mis":"K5-2-u4-X37","explanation":["탓하는 시간이 아니에요.","함께 노력할 점을 찾아요.","잘한 점도 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#5','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C35',2,'mc','auto','의견을 정한 뒤 꼭 확인할 것은 무엇인가요?',ARRAY['K5-2-u4-X08','K5-2-u4-X38']::text[],false,'{"seq":5,"concept":"K5-2-u4-C35","difficulty":2,"kind":"mc","stem":"의견을 정한 뒤 꼭 확인할 것은 무엇인가요?","options":[{"t":"이견이 없는지 확인하기","correct":true},{"t":"가장 먼저 말한 의견인지 확인하기","mis":"K5-2-u4-X08"},{"t":"선생님 의견과 같은지 확인하기","mis":"K5-2-u4-X38"},{"t":"목소리 큰 친구가 좋아하는지 확인하기","mis":"K5-2-u4-X08"}],"explanation":["차례는 관계없어요.","정해진 정답은 없어요.","모두 받아들이는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#6','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C36',2,'mc','auto','「급식실에 일찍 가자」와 「늦게 가자」가 맞설 때, 「요일마다 학년이 가는 순서를 바꾸자」는 어떤 생각 도구로 만든 의견인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":6,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"「급식실에 일찍 가자」와 「늦게 가자」가 맞설 때, 「요일마다 학년이 가는 순서를 바꾸자」는 어떤 생각 도구로 만든 의견인가요?","options":[{"t":"순서 바꾸기","correct":true},{"t":"합치기","mis":"K5-2-u4-X36"},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"줄이기","mis":"K5-2-u4-X36"}],"explanation":["두 의견을 붙인 것이 아니에요.","덜어 낸 것이 아니에요.","차례를 바꾸었어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#7','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C34',2,'match','auto','학교 문제 토의 단계와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u4-C34","difficulty":2,"kind":"match","stem":"학교 문제 토의 단계와 하는 일을 알맞게 이으세요.","pairs":[{"l":"의견 나누기","r":"모둠에서 먼저 나누고 추려 발표하기"},{"l":"의견 정하기","r":"실천할 의견을 정하고 이견이 없는지 확인하기"},{"l":"되돌아보기","r":"잘한 점과 보완할 점 나누기"}],"mis":"K5-2-u4-X35","explanation":["모둠에서 먼저 나눠요.","정하고 확인해요.","마치고 돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#8','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C37',2,'error','auto','토의를 되돌아보는 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X37','K5-2-u4-X26']::text[],false,'{"seq":8,"concept":"K5-2-u4-C37","difficulty":2,"kind":"error","stem":"토의를 되돌아보는 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「이번 토의는 다 너 때문에 망쳤어.」","correct":true,"mis_target":"K5-2-u4-X37"},{"t":"「조용한 친구도 말할 수 있게 기다려 준 점이 좋았어.」","mis":"K5-2-u4-X26"},{"t":"「다음에는 의견이 다를 때 기준으로 차분히 따져 보자.」","mis":"K5-2-u4-X37"}],"explanation":["잘한 점이에요.","함께 노력할 점이에요.","탓하는 말은 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#9','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C34',2,'mc','auto','학교 문제 토의에서 의견 나누기를 모둠에서 먼저 하면 좋은 점은 무엇인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X35','K5-2-u4-X23']::text[],false,'{"seq":9,"concept":"K5-2-u4-C34","difficulty":2,"kind":"mc","stem":"학교 문제 토의에서 의견 나누기를 모둠에서 먼저 하면 좋은 점은 무엇인가요?","options":[{"t":"여러 의견을 추려 반에서 더 잘 견줄 수 있다","correct":true},{"t":"모둠 밖 친구는 말하지 않아도 된다","mis":"K5-2-u4-X26"},{"t":"되돌아보기를 안 해도 된다","mis":"K5-2-u4-X35"},{"t":"절차를 건너뛸 수 있다","mis":"K5-2-u4-X23"}],"explanation":["모두 말해요.","되돌아보기는 꼭 해요.","추려서 견주기 쉬워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_basic#10','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C28',3,'mc','auto','「수돗가 물바다」 문제로 정한 의견을 실천했는데 여전히 물이 흥건해요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X37','K5-2-u4-X14']::text[],false,'{"seq":10,"concept":"K5-2-u4-C28","difficulty":3,"kind":"mc","stem":"「수돗가 물바다」 문제로 정한 의견을 실천했는데 여전히 물이 흥건해요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"실천한 모습을 나누고 새 의견을 찾는 토의를 다시 연다","correct":true},{"t":"한 번 정했으니 그대로 둔다","mis":"K5-2-u4-X28"},{"t":"의견을 정한 친구 탓을 한다","mis":"K5-2-u4-X37"},{"t":"토의는 쓸모없다고 여긴다","mis":"K5-2-u4-X14"}],"explanation":["다시 고칠 수 있어요.","탓하지 않아요.","다시 토의하는 것도 조정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#1','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C35',2,'ox','auto','의견을 정한 뒤에는 이견이 없는지 확인해요.',ARRAY['K5-2-u4-X34']::text[],false,'{"seq":1,"concept":"K5-2-u4-C35","difficulty":2,"kind":"ox","stem":"의견을 정한 뒤에는 이견이 없는지 확인해요.","answer":"O","reason_options":[{"t":"모두가 받아들여야 함께 실천할 수 있기 때문에","correct":true},{"t":"이견이 있어도 이미 정했으니 상관없기 때문에","mis":"K5-2-u4-X34"}],"mis":"K5-2-u4-X34","explanation":["확인해야 해요.","함께 실천하려면 필요해요.","바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#2','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C36',2,'mc','auto','합의점이 보이지 않을 때 생각 도구 물음을 던지는 까닭은 무엇인가요?',ARRAY['K5-2-u4-X36','K5-2-u4-X12','K5-2-u4-X11']::text[],false,'{"seq":2,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"합의점이 보이지 않을 때 생각 도구 물음을 던지는 까닭은 무엇인가요?","options":[{"t":"막힌 생각을 풀어 새 의견을 떠올리려고","correct":true},{"t":"토의를 빨리 끝내려고","mis":"K5-2-u4-X36"},{"t":"한 의견만 고르려고","mis":"K5-2-u4-X12"},{"t":"친구 의견을 깎아내리려고","mis":"K5-2-u4-X11"}],"explanation":["빨리 끝내려는 게 아니에요.","새 의견을 만들어요.","막힐 때 던지는 물음이에요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#3','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C37',3,'mc','auto','되돌아보기에서 「의견이 다를 때 목소리가 커졌던 점」을 말할 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X37','K5-2-u4-X08','K5-2-u4-X35']::text[],false,'{"seq":3,"concept":"K5-2-u4-C37","difficulty":3,"kind":"mc","stem":"되돌아보기에서 「의견이 다를 때 목소리가 커졌던 점」을 말할 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「다음에는 의견이 맞지 않아도 차분히 기준으로 따져 보자.」","correct":true},{"t":"「누가 소리쳤는지 이름을 말해 봐.」","mis":"K5-2-u4-X37"},{"t":"「목소리 큰 쪽이 이겼으니 괜찮아.」","mis":"K5-2-u4-X08"},{"t":"「되돌아보기는 시간 낭비야.」","mis":"K5-2-u4-X35"}],"explanation":["탓하는 말이에요.","목소리로 정하지 않아요.","함께 노력할 점으로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#4','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C36',3,'mc','auto','「반납대 옆에 칸 그림을 붙이자」와 「책 정리 당번을 정하자」를 「합치기」로 만든 의견으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X03','K5-2-u4-X08']::text[],false,'{"seq":4,"concept":"K5-2-u4-C36","difficulty":3,"kind":"mc","stem":"「반납대 옆에 칸 그림을 붙이자」와 「책 정리 당번을 정하자」를 「합치기」로 만든 의견으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"칸 그림을 붙이고, 당번이 하루 한 번 그림대로 꽂혔는지 살핀다","correct":true},{"t":"당번만 정하고 그림은 버린다","mis":"K5-2-u4-X12"},{"t":"둘 다 버리고 새로 시작한다","mis":"K5-2-u4-X03"},{"t":"먼저 나온 의견으로 정한다","mis":"K5-2-u4-X08"}],"explanation":["한쪽을 버렸어요.","둘 다 살려요.","두 의견을 합쳤어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#5','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C34',3,'error','auto','학교 문제 토의 계획이에요. 가장 알맞지 않은 계획은 어느 것인가요?',ARRAY['K5-2-u4-X35','K5-2-u4-X34']::text[],false,'{"seq":5,"concept":"K5-2-u4-C34","difficulty":3,"kind":"error","stem":"학교 문제 토의 계획이에요. 가장 알맞지 않은 계획은 어느 것인가요?","options":[{"t":"「의견을 정하면 바로 끝내고 되돌아보기는 하지 말자.」","correct":true,"mis_target":"K5-2-u4-X35"},{"t":"「의견 나누기는 모둠에서 먼저 하자.」","mis":"K5-2-u4-X34"},{"t":"「정한 뒤 이견이 없는지 물어보자.」","mis":"K5-2-u4-X34"}],"explanation":["알맞은 계획이에요.","알맞은 계획이에요.","되돌아보기까지 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#6','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C31',3,'mc','auto','학교 지도 쪽지를 보고 토의 주제를 고르는 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C31","difficulty":3,"kind":"mc","stem":"학교 지도 쪽지를 보고 토의 주제를 고르는 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우리 반이 매일 쓰고 직접 바꿀 수 있는 수돗가 문제부터 하자.」","correct":true},{"t":"「학교 건물을 새로 짓는 문제를 하자.」","mis":"K5-2-u4-X16"},{"t":"「쪽지는 다 불평이니 무시하자.」","mis":"K5-2-u4-X31"},{"t":"「제일 웃긴 쪽지를 고르자.」","mis":"K5-2-u4-X16"}],"explanation":["우리가 풀 수 없어요.","쪽지가 문제를 알려 줘요.","관련 있고 직접 풀 수 있어요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#7','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C38',3,'mc','auto','토의에서 처음 나온 의견보다 합의점이 더 나아지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X38','K5-2-u4-X08','K5-2-u4-X12']::text[],false,'{"seq":7,"concept":"K5-2-u4-C38","difficulty":3,"kind":"mc","stem":"토의에서 처음 나온 의견보다 합의점이 더 나아지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 질문하고 장단점을 따지며 보완했기 때문에","correct":true},{"t":"선생님이 정답을 알려 주었기 때문에","mis":"K5-2-u4-X38"},{"t":"목소리가 큰 친구가 정했기 때문에","mis":"K5-2-u4-X08"},{"t":"한 의견을 그대로 골랐기 때문에","mis":"K5-2-u4-X12"}],"explanation":["정답이 정해진 게 아니에요.","목소리로 정하지 않아요.","과정에서 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#8','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C34',4,'essay','teacher','쪽지 하나를 골라 토의 주제를 정하고, 내 의견과 까닭을 쓴 뒤 학교 문제 토의 단계 가운데 두 단계에서 무엇을 할지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u4-C34","difficulty":4,"kind":"essay","stem":"쪽지 하나를 골라 토의 주제를 정하고, 내 의견과 까닭을 쓴 뒤 학교 문제 토의 단계 가운데 두 단계에서 무엇을 할지 쓰세요.","answer_guide":{"answer":"예: 주제 — 어떻게 하면 도서관 책을 제자리에 꽂을까? 의견 — 반납대 옆에 칸 그림을 붙이자. 까닭 — 어디에 꽂을지 바로 알 수 있다. 의견 모으기 단계에서는 기준을 정해 장단점을 따지고, 되돌아보기 단계에서는 잘한 점과 보완할 점을 나누겠다.","scoring_points":["주제를 방법을 묻는 꼴로 썼는가","의견과 까닭을 썼는가","두 단계에서 할 일을 썼는가"]},"explanation":["주제를 정해요.","의견과 까닭이에요.","단계마다 할 일을 써요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#9','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C36',4,'essay','teacher','서로 맞선 두 의견을 하나 떠올려 쓰고, 생각 도구 물음 가운데 하나를 골라 새 의견으로 만들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u4-C36","difficulty":4,"kind":"essay","stem":"서로 맞선 두 의견을 하나 떠올려 쓰고, 생각 도구 물음 가운데 하나를 골라 새 의견으로 만들어 쓰세요.","answer_guide":{"answer":"예: 쉬는 시간에 「운동하자」와 「책을 읽자」가 맞섰다. 순서 바꾸기 물음으로 앞 쉬는 시간에는 몸을 움직이고 뒤 쉬는 시간에는 책을 읽기로 하면 두 의견을 모두 살릴 수 있다.","scoring_points":["맞선 두 의견을 썼는가","생각 도구 하나를 밝혔는가","두 의견을 살린 새 의견을 썼는가"]},"explanation":["맞선 의견이에요.","도구를 골라요.","새 의견을 만들어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_L11_challenge#10','kor',5,2,'u4','L11','g5_2_kor_u4_L11_challenge','lesson_challenge','K5-2-u4-C37',4,'essay','teacher','모둠 토의를 되돌아보며 잘한 점과 보완할 점을 하나씩 쓰고, 다음 토의에서 함께 노력할 다짐을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u4-C37","difficulty":4,"kind":"essay","stem":"모둠 토의를 되돌아보며 잘한 점과 보완할 점을 하나씩 쓰고, 다음 토의에서 함께 노력할 다짐을 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 기준을 먼저 정해서 차분하게 따질 수 있었다. 보완할 점 — 시간이 모자라 조용한 친구의 의견을 다 듣지 못했다. 다짐 — 다음 토의에서는 모두 한 번씩 말할 수 있게 차례를 정하자.","scoring_points":["잘한 점을 썼는가","보완할 점을 탓하지 않고 썼는가","함께 노력할 다짐을 썼는가"]},"explanation":["잘한 점이에요.","보완할 점이에요.","함께 할 다짐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#1','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C2',1,'mc','auto','여럿이 함께 문제를 풀 방법을 찾는 말하기는 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X06']::text[],false,'{"seq":1,"concept":"K5-2-u4-C2","difficulty":1,"kind":"mc","stem":"여럿이 함께 문제를 풀 방법을 찾는 말하기는 어느 것인가요?","options":[{"t":"토의","correct":true},{"t":"연설","mis":"K5-2-u4-X02"},{"t":"토론","mis":"K5-2-u4-X02"},{"t":"면담","mis":"K5-2-u4-X06"}],"explanation":["혼자 주장해요.","맞서서 겨뤄요.","함께 방법을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#2','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C39',1,'mc','auto','어려운 말이나 외래어를 알기 쉬운 우리말로 바꾼 말을 무엇이라고 하나요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":2,"concept":"K5-2-u4-C39","difficulty":1,"kind":"mc","stem":"어려운 말이나 외래어를 알기 쉬운 우리말로 바꾼 말을 무엇이라고 하나요?","options":[{"t":"순화어","correct":true},{"t":"외래어","mis":"K5-2-u4-X39"},{"t":"방언","mis":"K5-2-u4-X39"},{"t":"줄임말","mis":"K5-2-u4-X39"}],"explanation":["바꾸기 전 말이에요.","지역의 말이에요.","쉬운 우리말로 다듬은 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#3','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C7',1,'mc','auto','의견을 조정할 때 가장 먼저 하는 일은 어느 것인가요?',ARRAY['K5-2-u4-X13','K5-2-u4-X08','K5-2-u4-X14']::text[],false,'{"seq":3,"concept":"K5-2-u4-C7","difficulty":1,"kind":"mc","stem":"의견을 조정할 때 가장 먼저 하는 일은 어느 것인가요?","options":[{"t":"의견을 검토할 기준 마련하기","correct":true},{"t":"합의점 찾기","mis":"K5-2-u4-X13"},{"t":"목소리 큰 의견 고르기","mis":"K5-2-u4-X08"},{"t":"손을 들어 정하기","mis":"K5-2-u4-X14"}],"explanation":["마지막 차례예요.","기준이 아니에요.","기준이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#4','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C23',1,'mc','auto','학급 토의의 첫 절차는 어느 것인가요?',ARRAY['K5-2-u4-X23','K5-2-u4-X35']::text[],false,'{"seq":4,"concept":"K5-2-u4-C23","difficulty":1,"kind":"mc","stem":"학급 토의의 첫 절차는 어느 것인가요?","options":[{"t":"토의 주제 정하기","correct":true},{"t":"의견 정하기","mis":"K5-2-u4-X23"},{"t":"의견 모으기","mis":"K5-2-u4-X23"},{"t":"되돌아보기","mis":"K5-2-u4-X35"}],"explanation":["마지막이에요.","넷째예요.","주제부터 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#5','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C6',1,'mc','auto','토의 「블록 놀이 자리」에서 풀어야 할 문제는 어느 것인가요?',ARRAY['K5-2-u4-X06']::text[],false,'{"seq":5,"concept":"K5-2-u4-C6","difficulty":1,"kind":"mc","stem":"토의 「블록 놀이 자리」에서 풀어야 할 문제는 어느 것인가요?","options":[{"t":"블록 놀이 자리가 좁고 시끄러워 다툼이 생기는 것","correct":true},{"t":"블록이 너무 적은 것","mis":"K5-2-u4-X06"},{"t":"쉬는 시간이 너무 짧은 것","mis":"K5-2-u4-X06"},{"t":"책 읽는 자리가 없는 것","mis":"K5-2-u4-X06"}],"explanation":["토의에 없어요.","토의에 없어요.","사회자가 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#6','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C15',1,'mc','auto','토의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"토의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 교실 뒤 놀이 자리를 사이좋게 쓸까?","correct":true},{"t":"놀이 자리가 시끄러워서 싫다.","mis":"K5-2-u4-X15"},{"t":"놀이 자리는 누가 어질렀지?","mis":"K5-2-u4-X15"},{"t":"놀이 자리는 원래 좁다.","mis":"K5-2-u4-X31"}],"explanation":["불평이에요.","탓하는 물음이에요.","방법을 묻는 물음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#7','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C17',1,'mc','auto','친구 의견을 들으며 궁금한 점을 묻는 것은 어느 것인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":7,"concept":"K5-2-u4-C17","difficulty":1,"kind":"mc","stem":"친구 의견을 들으며 궁금한 점을 묻는 것은 어느 것인가요?","options":[{"t":"질문하며 듣기","correct":true},{"t":"맞장구만 치기","mis":"K5-2-u4-X21"},{"t":"끼어들어 말 끊기","mis":"K5-2-u4-X18"},{"t":"못 들은 척하기","mis":"K5-2-u4-X17"}],"explanation":["묻지 않아요.","공손하지 않아요.","물으며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#8','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C29',1,'mc','auto','「소중한 것이 서로 다를 때」에서 부딪침이 생기는 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X29']::text[],false,'{"seq":8,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"「소중한 것이 서로 다를 때」에서 부딪침이 생기는 까닭은 어느 것인가요?","options":[{"t":"사람마다 소중하게 여기는 것이 달라서","correct":true},{"t":"한쪽이 나쁜 사람이라서","mis":"K5-2-u4-X29"},{"t":"규칙이 하나도 없어서","mis":"K5-2-u4-X29"},{"t":"모두 같은 것을 좋아해서","mis":"K5-2-u4-X29"}],"explanation":["나쁜 사람이 아니에요.","글에 없어요.","가치가 달라서예요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#9','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C15',2,'mc','auto','「꿈나무반 학급 토의 기록장」의 토의 주제는 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X06']::text[],false,'{"seq":9,"concept":"K5-2-u4-C15","difficulty":2,"kind":"mc","stem":"「꿈나무반 학급 토의 기록장」의 토의 주제는 어느 것인가요?","options":[{"t":"어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","correct":true},{"t":"화분은 누가 시들게 했을까?","mis":"K5-2-u4-X15"},{"t":"창가를 어떻게 넓힐까?","mis":"K5-2-u4-X06"},{"t":"이름표를 어디서 살까?","mis":"K5-2-u4-X06"}],"explanation":["탓하는 물음이에요.","주제가 아니에요.","기록장 첫 줄이에요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#10','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C9',2,'mc','auto','「네 명까지만 놀자」 의견의 단점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X10']::text[],false,'{"seq":10,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"「네 명까지만 놀자」 의견의 단점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"놀이마다 알맞은 인원이 달라 몇 명으로 할지 정하기 어렵다","correct":true},{"t":"자리가 넉넉해진다","mis":"K5-2-u4-X10"},{"t":"소리가 줄어든다","mis":"K5-2-u4-X10"},{"t":"단점이 하나도 없다","mis":"K5-2-u4-X10"}],"explanation":["장점이에요.","장점이에요.","어느 의견이든 단점이 있어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#11','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C12',2,'mc','auto','블록 토의의 합의점 「매트 안에서 네 명까지, 규칙 안내판 붙이기」는 어떻게 만든 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X08','K5-2-u4-X03']::text[],false,'{"seq":11,"concept":"K5-2-u4-C12","difficulty":2,"kind":"mc","stem":"블록 토의의 합의점 「매트 안에서 네 명까지, 규칙 안내판 붙이기」는 어떻게 만든 것인가요?","options":[{"t":"두 의견의 장점을 합쳤다","correct":true},{"t":"한 의견만 그대로 골랐다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 의견을 따랐다","mis":"K5-2-u4-X08"},{"t":"세 의견을 모두 버렸다","mis":"K5-2-u4-X03"}],"explanation":["합쳤어요.","목소리로 정하지 않아요.","하윤이와 나은이 의견을 합쳤어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#12','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C27',2,'mc','auto','회의와 토의가 정하는 방법을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u4-X27','K5-2-u4-X22']::text[],false,'{"seq":12,"concept":"K5-2-u4-C27","difficulty":2,"kind":"mc","stem":"회의와 토의가 정하는 방법을 바르게 말한 것은 어느 것인가요?","options":[{"t":"회의는 손을 들어 많은 쪽으로, 토의는 조정해 합의된 쪽으로 정한다","correct":true},{"t":"회의와 토의 모두 늘 손을 들어 정한다","mis":"K5-2-u4-X27"},{"t":"토의는 선생님이 대신 정한다","mis":"K5-2-u4-X22"},{"t":"회의는 아무것도 정하지 않는다","mis":"K5-2-u4-X27"}],"explanation":["정하는 방법이 달라요.","토의는 함께 정해요.","회의도 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#13','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C39',2,'mc','auto','「여행 가이드」를 순화어로 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":13,"concept":"K5-2-u4-C39","difficulty":2,"kind":"mc","stem":"「여행 가이드」를 순화어로 바꾼 것은 어느 것인가요?","options":[{"t":"여행 안내원","correct":true},{"t":"전시 기획자","mis":"K5-2-u4-X39"},{"t":"책 소개 영상","mis":"K5-2-u4-X39"},{"t":"개봉","mis":"K5-2-u4-X39"}],"explanation":["큐레이터예요.","북 트레일러예요.","안내하는 사람이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#14','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C36',2,'mc','auto','「앞 쉬는 시간에는 몸을 움직이고 뒤 쉬는 시간에는 책을 읽자」는 어떤 생각 도구로 만든 의견인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":14,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"「앞 쉬는 시간에는 몸을 움직이고 뒤 쉬는 시간에는 책을 읽자」는 어떤 생각 도구로 만든 의견인가요?","options":[{"t":"순서 바꾸기","correct":true},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"줄이기","mis":"K5-2-u4-X36"},{"t":"포기하기","mis":"K5-2-u4-X36"}],"explanation":["덜어 내지 않았어요.","줄이지 않았어요.","차례를 나누었어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#15','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C7',2,'mc','auto','여러 의견을 견줄 때 쓰는 기준으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u4-X07']::text[],false,'{"seq":15,"concept":"K5-2-u4-C7","difficulty":2,"kind":"mc","stem":"여러 의견을 견줄 때 쓰는 기준으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"가장 먼저 말한 의견인가?","correct":true},{"t":"실천할 수 있는가?","mis":"K5-2-u4-X07"},{"t":"효과적인가?","mis":"K5-2-u4-X07"},{"t":"여러 사람에게 도움이 되는가?","mis":"K5-2-u4-X07"}],"explanation":["알맞은 기준이에요.","알맞은 기준이에요.","말한 차례는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#16','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C37',2,'mc','auto','토의를 되돌아볼 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X37','K5-2-u4-X35','K5-2-u4-X08']::text[],false,'{"seq":16,"concept":"K5-2-u4-C37","difficulty":2,"kind":"mc","stem":"토의를 되돌아볼 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「질문 덕분에 의견이 단단해졌어. 다음엔 시간을 나누어 모두 말하자.」","correct":true},{"t":"「이번 토의는 너 때문에 망쳤어.」","mis":"K5-2-u4-X37"},{"t":"「되돌아보기는 시간 낭비야.」","mis":"K5-2-u4-X35"},{"t":"「목소리 큰 쪽이 이겼으니 됐어.」","mis":"K5-2-u4-X08"}],"explanation":["탓하는 말이에요.","꼭 필요해요.","잘한 점과 다짐을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#17','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C19',3,'mc','auto','기록장의 합의점은 세 의견을 어떻게 살렸나요?',ARRAY['K5-2-u4-X19','K5-2-u4-X10','K5-2-u4-X20']::text[],false,'{"seq":17,"concept":"K5-2-u4-C19","difficulty":3,"kind":"mc","stem":"기록장의 합의점은 세 의견을 어떻게 살렸나요?","options":[{"t":"이름표 · 당번 · 창가 의견의 장점을 모두 살리고 단점을 메웠다","correct":true},{"t":"지안이 의견만 그대로 골랐다","mis":"K5-2-u4-X19"},{"t":"로운이 의견은 단점이 있어 버렸다","mis":"K5-2-u4-X10"},{"t":"태린이 의견이 이겨서 그대로 정했다","mis":"K5-2-u4-X20"}],"explanation":["셋 다 살렸어요.","줄여서 살렸어요.","모아서 고쳤어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#18','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C11',3,'mc','auto','블록 토의에서 세 의견의 장점을 살린 합의점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X12','K5-2-u4-X08']::text[],false,'{"seq":18,"concept":"K5-2-u4-C11","difficulty":3,"kind":"mc","stem":"블록 토의에서 세 의견의 장점을 살린 합의점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"매트 안에서 네 명까지 놀고, 작은 목소리 규칙을 안내판으로 붙인다","correct":true},{"t":"블록 놀이를 아예 없앤다","mis":"K5-2-u4-X30"},{"t":"하윤이 의견만 그대로 따른다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 모둠이 먼저 논다","mis":"K5-2-u4-X08"}],"explanation":["모두의 바람을 지우지 않아요.","하나만 고르지 않아요.","장점을 모았어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#19','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C26',3,'mc','auto','학급 토의에서 늘 같은 친구들만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X22']::text[],false,'{"seq":19,"concept":"K5-2-u4-C26","difficulty":3,"kind":"mc","stem":"학급 토의에서 늘 같은 친구들만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의견을 마련할 시간을 주고 아직 말하지 않은 친구에게 차례를 준다","correct":true},{"t":"발표 잘하는 친구에게 계속 맡긴다","mis":"K5-2-u4-X26"},{"t":"사회자가 대신 정한다","mis":"K5-2-u4-X22"},{"t":"조용한 친구는 의견이 없다고 여긴다","mis":"K5-2-u4-X26"}],"explanation":["몇몇만 말하게 돼요.","대신 정하지 않아요.","모두 말하게 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#20','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C30',3,'mc','auto','산책길 문제에서 두 사람의 가치를 모두 존중한 의견으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31']::text[],false,'{"seq":20,"concept":"K5-2-u4-C30","difficulty":3,"kind":"mc","stem":"산책길 문제에서 두 사람의 가치를 모두 존중한 의견으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가운데 선을 긋고 붐비는 저녁엔 자전거를 끌고 가자","correct":true},{"t":"자전거를 아예 못 타게 하자","mis":"K5-2-u4-X30"},{"t":"걷는 사람이 늘 비켜 주자","mis":"K5-2-u4-X30"},{"t":"아무것도 바꾸지 말자","mis":"K5-2-u4-X31"}],"explanation":["한쪽만 지켜요.","한쪽만 양보해요.","둘 다 존중해요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#21','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C18',3,'mc','auto','친구 의견에 빈틈이 보일 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":21,"concept":"K5-2-u4-C18","difficulty":3,"kind":"mc","stem":"친구 의견에 빈틈이 보일 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「궁금해서 묻는데, 비 오는 날에는 어떻게 해?」","correct":true},{"t":"「그 의견은 빈틈투성이야.」","mis":"K5-2-u4-X18"},{"t":"「그냥 넘어가자.」","mis":"K5-2-u4-X17"},{"t":"「그럴 줄 알았어.」","mis":"K5-2-u4-X18"}],"explanation":["공격하는 말이에요.","빈틈이 남아요.","공손하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#22','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C38',3,'mc','auto','「좋은 의견은 처음부터 정해져 있어서 찾기만 하면 된다.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X38','K5-2-u4-X08']::text[],false,'{"seq":22,"concept":"K5-2-u4-C38","difficulty":3,"kind":"mc","stem":"「좋은 의견은 처음부터 정해져 있어서 찾기만 하면 된다.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「서로 견주고 고치는 과정에서 처음보다 나은 의견이 만들어져.」","correct":true},{"t":"「맞아, 선생님이 정답을 알고 계셔.」","mis":"K5-2-u4-X38"},{"t":"「목소리 큰 친구 의견이 정답이야.」","mis":"K5-2-u4-X08"},{"t":"「처음 나온 의견이 늘 정답이야.」","mis":"K5-2-u4-X38"}],"explanation":["정답이 정해진 게 아니에요.","목소리로 정하지 않아요.","과정에서 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#23','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C11',4,'essay','teacher','토의 「블록 놀이 자리」의 세 의견 가운데 둘 이상의 장점을 살려 합의점을 쓰고, 어떤 단점을 어떻게 메웠는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C11","difficulty":4,"kind":"essay","stem":"토의 「블록 놀이 자리」의 세 의견 가운데 둘 이상의 장점을 살려 합의점을 쓰고, 어떤 단점을 어떻게 메웠는지 쓰세요.","answer_guide":{"answer":"예: 매트 안에서 한 번에 네 명까지 놀고, 작은 목소리 규칙을 안내판으로 붙인다. 인원만 정하면 꾸준히 지키기 어렵다는 단점을 안내판으로 메웠고, 규칙만 정하면 자리가 좁다는 단점을 인원 제한으로 메웠다.","scoring_points":["둘 이상의 장점을 살렸는가","합의점을 분명히 썼는가","메운 단점을 썼는가"]},"explanation":["장점을 모아요.","합의점을 써요.","단점을 어떻게 메웠는지 써요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#24','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C30',4,'essay','teacher','우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 골라 두 사람이 소중히 여기는 것을 쓰고, 둘 다 존중하는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C30","difficulty":4,"kind":"essay","stem":"우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 골라 두 사람이 소중히 여기는 것을 쓰고, 둘 다 존중하는 방법을 쓰세요.","answer_guide":{"answer":"예: 밤늦게 악기를 연습하고 싶은 이웃과 조용히 쉬고 싶은 이웃이 있다. 한 사람은 연주 실력을, 다른 사람은 편안한 휴식을 소중히 여긴다. 저녁 일찍까지만 연습하고 소리를 줄이는 깔개를 깔면 둘 다 존중할 수 있다.","scoring_points":["부딪치는 일을 골랐는가","두 사람의 가치를 썼는가","둘 다 존중하는 방법을 썼는가"]},"explanation":["부딪침을 골라요.","두 가치를 써요.","둘 다 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_a#25','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C9',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 의견 하나를 골라 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C9","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 의견 하나를 골라 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.","answer_guide":{"answer":"예: 태린이의 당번 의견은 효과적인가 기준으로 보면 날마다 잊지 않고 물을 줄 수 있다는 장점이 있다. 여러 사람에게 도움이 되는가 기준으로 보면 당번만 애쓰고 다른 친구는 신경 쓰지 않을 수 있다는 단점이 있다.","scoring_points":["의견 하나를 골랐는가","기준 두 가지를 밝혔는가","장점과 단점을 의견을 두고 썼는가"]},"explanation":["의견을 골라요.","기준을 밝혀요.","장단점을 써요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#1','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C3',1,'mc','auto','서로 다른 의견을 견주고 고쳐 모두가 받아들일 만한 의견을 찾는 일은 어느 것인가요?',ARRAY['K5-2-u4-X03','K5-2-u4-X14','K5-2-u4-X21']::text[],false,'{"seq":1,"concept":"K5-2-u4-C3","difficulty":1,"kind":"mc","stem":"서로 다른 의견을 견주고 고쳐 모두가 받아들일 만한 의견을 찾는 일은 어느 것인가요?","options":[{"t":"의견 조정","correct":true},{"t":"의견 버리기","mis":"K5-2-u4-X03"},{"t":"손들기","mis":"K5-2-u4-X14"},{"t":"맞장구","mis":"K5-2-u4-X21"}],"explanation":["버리지 않아요.","손들기와 달라요.","견주고 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#2','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C39',1,'mc','auto','「팩트 체크」를 순화어로 바꾸면 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":2,"concept":"K5-2-u4-C39","difficulty":1,"kind":"mc","stem":"「팩트 체크」를 순화어로 바꾸면 어느 것인가요?","options":[{"t":"사실 확인","correct":true},{"t":"개봉","mis":"K5-2-u4-X39"},{"t":"여행 안내원","mis":"K5-2-u4-X39"},{"t":"전시 기획자","mis":"K5-2-u4-X39"}],"explanation":["언박싱이에요.","여행 가이드예요.","사실을 확인한다는 뜻이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#3','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C9',1,'mc','auto','기준에 비추어 의견의 좋은 점과 아쉬운 점을 따지는 일은 어느 것인가요?',ARRAY['K5-2-u4-X23','K5-2-u4-X13','K5-2-u4-X35']::text[],false,'{"seq":3,"concept":"K5-2-u4-C9","difficulty":1,"kind":"mc","stem":"기준에 비추어 의견의 좋은 점과 아쉬운 점을 따지는 일은 어느 것인가요?","options":[{"t":"장점과 단점 검토하기","correct":true},{"t":"주제 정하기","mis":"K5-2-u4-X23"},{"t":"합의점 찾기","mis":"K5-2-u4-X13"},{"t":"되돌아보기","mis":"K5-2-u4-X35"}],"explanation":["맨 앞 절차예요.","그다음 차례예요.","장단점을 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#4','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C23',1,'mc','auto','학급 토의의 마지막 절차는 어느 것인가요?',ARRAY['K5-2-u4-X23']::text[],false,'{"seq":4,"concept":"K5-2-u4-C23","difficulty":1,"kind":"mc","stem":"학급 토의의 마지막 절차는 어느 것인가요?","options":[{"t":"의견 정하기","correct":true},{"t":"토의 주제 정하기","mis":"K5-2-u4-X23"},{"t":"의견 마련하기","mis":"K5-2-u4-X23"},{"t":"의견 나누기","mis":"K5-2-u4-X23"}],"explanation":["첫 절차예요.","둘째 절차예요.","실천할 의견을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#5','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C6',1,'mc','auto','준서가 제안한 의견은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X30']::text[],false,'{"seq":5,"concept":"K5-2-u4-C6","difficulty":1,"kind":"mc","stem":"준서가 제안한 의견은 어느 것인가요?","options":[{"t":"모둠마다 요일을 정하자","correct":true},{"t":"한 번에 네 명까지만 놀자","mis":"K5-2-u4-X06"},{"t":"놀이 자리와 규칙을 정하자","mis":"K5-2-u4-X06"},{"t":"블록 놀이를 없애자","mis":"K5-2-u4-X30"}],"explanation":["하윤이의 의견이에요.","나은이의 의견이에요.","준서는 요일을 제안했어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#6','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C16',1,'mc','auto','토의 주제를 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X16','K5-2-u4-X31']::text[],false,'{"seq":6,"concept":"K5-2-u4-C16","difficulty":1,"kind":"mc","stem":"토의 주제를 고를 때 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리가 직접 풀 수 있는 문제인가?","correct":true},{"t":"가장 웃긴 문제인가?","mis":"K5-2-u4-X16"},{"t":"어른들만 풀 수 있는 문제인가?","mis":"K5-2-u4-X31"},{"t":"한 친구만 관심 있는 문제인가?","mis":"K5-2-u4-X16"}],"explanation":["재미가 기준이 아니에요.","우리가 도울 수 있어야 해요.","직접 풀 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#7','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C18',1,'mc','auto','공손한 질문으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":7,"concept":"K5-2-u4-C18","difficulty":1,"kind":"mc","stem":"공손한 질문으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「궁금해서 묻는데, 요일은 누가 정해?」","correct":true},{"t":"「그걸 의견이라고 냈어?」","mis":"K5-2-u4-X18"},{"t":"「넌 왜 맨날 그래?」","mis":"K5-2-u4-X18"},{"t":"「물어볼 것도 없어.」","mis":"K5-2-u4-X17"}],"explanation":["놀리는 말이에요.","탓하는 말이에요.","궁금한 점을 공손하게 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#8','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C30',1,'mc','auto','서로 다른 가치가 부딪칠 때 필요한 태도는 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31','K5-2-u4-X08']::text[],false,'{"seq":8,"concept":"K5-2-u4-C30","difficulty":1,"kind":"mc","stem":"서로 다른 가치가 부딪칠 때 필요한 태도는 어느 것인가요?","options":[{"t":"서로 존중하고 조금씩 양보하기","correct":true},{"t":"더 옳은 쪽만 이기게 하기","mis":"K5-2-u4-X30"},{"t":"모른 척하기","mis":"K5-2-u4-X31"},{"t":"큰 소리로 따지기","mis":"K5-2-u4-X08"}],"explanation":["겨루지 않아요.","모른 척하지 않아요.","존중하고 양보해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#9','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C6',2,'mc','auto','지안이가 제안한 의견은 어느 것인가요?',ARRAY['K5-2-u4-X06','K5-2-u4-X16']::text[],false,'{"seq":9,"concept":"K5-2-u4-C6","difficulty":2,"kind":"mc","stem":"지안이가 제안한 의견은 어느 것인가요?","options":[{"t":"물 주는 날을 적은 이름표를 꽂자","correct":true},{"t":"물 주는 당번을 정하자","mis":"K5-2-u4-X06"},{"t":"화분을 모두 창가로 옮기자","mis":"K5-2-u4-X06"},{"t":"화분을 집으로 가져가자","mis":"K5-2-u4-X16"}],"explanation":["태린이의 의견이에요.","로운이의 의견이에요.","지안이는 이름표를 제안했어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#10','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C9',2,'mc','auto','「모둠마다 요일을 정하자」 의견의 장점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X09','K5-2-u4-X04','K5-2-u4-X10']::text[],false,'{"seq":10,"concept":"K5-2-u4-C9","difficulty":2,"kind":"mc","stem":"「모둠마다 요일을 정하자」 의견의 장점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 차례를 기다리며 양보하게 된다","correct":true},{"t":"특정 요일에 몰릴 수 있다","mis":"K5-2-u4-X09"},{"t":"블록이 늘어난다","mis":"K5-2-u4-X04"},{"t":"규칙이 필요 없다","mis":"K5-2-u4-X10"}],"explanation":["단점이에요.","관계없어요.","양보하게 돼요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#11','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C12',2,'mc','auto','합의점에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X12','K5-2-u4-X08','K5-2-u4-X38']::text[],false,'{"seq":11,"concept":"K5-2-u4-C12","difficulty":2,"kind":"mc","stem":"합의점에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"새 의견을 만들거나 두 의견을 합칠 수도 있다","correct":true},{"t":"반드시 한 의견만 골라야 한다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 쪽으로 정한다","mis":"K5-2-u4-X08"},{"t":"정답이 처음부터 정해져 있다","mis":"K5-2-u4-X38"}],"explanation":["여러 모습이 있어요.","목소리로 정하지 않아요.","정답이 정해진 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#12','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C28',2,'mc','auto','반이 정당한 절차로 정한 의견이 내 의견과 다를 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['K5-2-u4-X28','K5-2-u4-X20','K5-2-u4-X37']::text[],false,'{"seq":12,"concept":"K5-2-u4-C28","difficulty":2,"kind":"mc","stem":"반이 정당한 절차로 정한 의견이 내 의견과 다를 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"받아들이고 함께 실천한다","correct":true},{"t":"내 의견대로만 한다","mis":"K5-2-u4-X28"},{"t":"다음 토의에는 나오지 않는다","mis":"K5-2-u4-X20"},{"t":"정한 친구들을 탓한다","mis":"K5-2-u4-X37"}],"explanation":["함께 정했어요.","참여는 소중해요.","함께 실천해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_kor_u4_review_b#13','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C39',2,'mc','auto','「북 트레일러」를 순화어로 바꾼 것은 어느 것인가요?',ARRAY['K5-2-u4-X39']::text[],false,'{"seq":13,"concept":"K5-2-u4-C39","difficulty":2,"kind":"mc","stem":"「북 트레일러」를 순화어로 바꾼 것은 어느 것인가요?","options":[{"t":"책 소개 영상","correct":true},{"t":"사실 확인","mis":"K5-2-u4-X39"},{"t":"여행 안내원","mis":"K5-2-u4-X39"},{"t":"개봉","mis":"K5-2-u4-X39"}],"explanation":["팩트 체크예요.","여행 가이드예요.","책을 소개하는 영상이에요."],"asset":{"type":"passage","lines":["언박싱 → 개봉","북 트레일러 → 책 소개 영상","큐레이터 → 전시 기획자","팩트 체크 → 사실 확인","여행 가이드 → 여행 안내원"],"title":"쉬운 우리말로 — 순화어"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
